    ["visuals.esp targets.NPCs"] = false,
    ["visuals.esp.Box"] = true,
    ["visuals.esp.Distance"] = false,
    ["visuals.esp.ESP"] = false,
    ["visuals.esp.Health bar"] = false,
    ["visuals.esp.Nametag"] = false,
    ["visuals.esp.Off-screen arrow"] = false,
    ["visuals.esp.Outline"] = false,
    ["visuals.esp.Skeleton"] = true,
    ["visuals.esp.Tracer"] = false,
    ["visuals.light.Fullbright"] = true,
    ["visuals.light.Strip fog"] = true,
    ["visuals.sight.Field of view"] = 93,
  },
  ["heaven"] = false,
  ["heroArt"] = true,
  ["loader"] = "Aurora",
  ["motion"] = "Silk",
  ["notify"] = false,
  ["pins"] = { "action.combat.Open player panel", "movement.protection.Block player collisions", "universal.movement.Noclip", "universal.movement.Infinite jump", "combat.aim.Aim assist", "visuals.esp.ESP" },
  ["radius"] = 2,
  ["shadow"] = 0.5,
  ["sideSize"] = 2,
  ["sideSort"] = "name",
  ["theme"] = "chrome",
  ["toggleAction"] = "Minimise",
  ["toggleKey"] = "V",
}

---True when this machine has never run LUMEN before.
function Defaults.fresh()
  local isf = rawget(getgenv(), "isfile")
  if type(isf) ~= "function" then return false end
  local there = false
  pcall(function() there = isf(L.Cfg.PATH) end)
  return not there
end

-- Seed, do not overwrite. Cfg.load has already run and absorbed whatever was on
-- disk; anything it found wins. This only fills keys that are still absent, so
-- re-running it can never clobber a choice somebody actually made.
function Defaults.seed()
  local Cfg = L.Cfg
  if not (Cfg and Cfg.SCHEMA) then return 0, "config not ready" end
  local n = 0
  for k, v in pairs(Defaults.VALUES) do
    if Cfg.SCHEMA[k] and Cfg.global[k] == nil and Cfg.place[k] == nil then
      Cfg.global[k] = v
      n = n + 1
    end
  end
  if n > 0 then
    Cfg.resolve()
    Cfg.flush()
  end
  return n
end

if Defaults.fresh() then
  local ok, n = pcall(Defaults.seed)
  if ok and n and n > 0 then
    L.note("defaults", "first run -- seeded " .. n .. " setting group(s)")
  end
end

end
do -- ==== lm_01_tokens.lua ====
-- LUMEN :: TOKENS
-- Colours, type, radii, spacing and motion. Every UI value comes from here.
-- Motion tokens are (duration, bounce) pairs, not stiffness/damping.

local L = getgenv().LUMEN
local T = {}
L.T = T

local rgb = Color3.fromRGB

-- ---------------------------------------------------------------- colour
-- A cool, near-black base rather than neutral grey.
T.c = {
  scrim      = rgb(0, 0, 0),
  bg         = rgb(2, 2, 3),        -- sidebar / recessed
  surface    = rgb(5, 5, 7),        -- the window body
  raised     = rgb(11, 12, 16),     -- cards, control rows
  overlay    = rgb(17, 18, 24),     -- dropdowns, popovers
  hover      = rgb(24, 26, 33),
  active     = rgb(31, 33, 42),

  -- Borders are nearly invisible on purpose: visible outlines read as a wireframe.
  line       = rgb(24, 26, 33),
  lineSoft   = rgb(15, 16, 21),
  lineStrong = rgb(46, 50, 62),

  text       = rgb(247, 248, 251),
  textDim    = rgb(146, 153, 168),
  textMute   = rgb(94, 101, 116),
  textOff    = rgb(58, 63, 76),

  -- The bloom: a light source behind the page, never used on a control.
  bloom      = rgb(26, 43, 107),

  -- Chrome accent: cool and pale, so it reads as metal rather than paint.
  accent     = rgb(138, 176, 255),
  accentAlt  = rgb(196, 182, 255),
  accentDeep = rgb(30, 44, 84),
  accentInk  = rgb(4, 5, 8),

  -- Dispersion: icon and chrome edges only, never UI furniture.
  irisA      = rgb(120, 220, 255),
  irisB      = rgb(255, 150, 220),
  irisC      = rgb(255, 196, 120),

  ok         = rgb(80, 224, 168),
  warn       = rgb(252, 200, 88),
  bad        = rgb(255, 120, 140),
}

-- ---------------------------------------------------------------- type
-- Authored against a 1080p reference; the root UIScale handles everything else.
T.font = {
  display = Enum.Font.GothamBlack,
  strong  = Enum.Font.GothamBold,
  medium  = Enum.Font.GothamMedium,
  body    = Enum.Font.Gotham,
  mono    = Enum.Font.Code,
}

-- Hierarchy comes from range, not weight: a large display against 9-10 px labels.
T.size = {
  hero    = 34,
  display = 24,
  title   = 17,
  head    = 15,
  body    = 13,
  label   = 12,
  micro   = 11,
  tiny    = 10,
  nano    = 9,      -- nav section labels, always upper case and tracked
}

-- ---------------------------------------------------------------- space
T.gap = { xs = 4, sm = 6, md = 10, lg = 14, xl = 20, xxl = 28 }

T.r = { sm = 7, md = 12, lg = 16, xl = 22, pill = 999 }

-- ---------------------------------------------------------------- density
-- Every structural height in one place, multiplied by one number. Read through
-- T.px at construction; a module local would be frozen at load.
T.base = { row = 52, tab = 46, header = 84, sidebar = 212, pad = 24, gap = 10 }
T.dense = 1.0                      -- 1.0 comfortable, 0.82 compact

function T.px(key)
  return math.floor((T.base[key] or 0) * T.dense + 0.5)
end

-- Elevation is a surface colour plus a border: Roblox has no box-shadow.
T.elev = {
  [0] = { fill = T.c.surface, line = T.c.lineSoft,   lineT = 0.55 },
  [1] = { fill = T.c.raised,  line = T.c.line,       lineT = 0.50 },
  [2] = { fill = T.c.overlay, line = T.c.lineStrong, lineT = 0.45 },
}

-- ---------------------------------------------------------------- motion
-- Named by role. Each token is (duration in seconds, bounce); see lm_02_spring.
T.m = {
  instant    = { 0.10,  0.00 },   -- hover/press state layers: no overshoot
  fast       = { 0.18,  0.20 },   -- toggles and checkmarks; 1.5% overshoot
  base       = { 0.30,  0.20 },   -- the default: panels, the tab indicator
  slow       = { 0.44,  0.22 },   -- window entrance, tab content swap
  expressive = { 0.42,  0.38 },   -- the loader mark, 8% overshoot. Overshoot is
                                  -- set by bounce alone; at 0.58 duration it
                                  -- settled in 0.97 s and read as lag
  gentle     = { 0.32, -0.20 },   -- progress and meters, overdamped on purpose:
}                                 -- at 0.50 it took 1.14 s to settle

-- Material 3 easing curves, for the rare case a curve beats a spring (anything
-- that must land on an exact frame). Sampled by L.bezier in lm_03_motion.
--   https://m3.material.io/styles/motion/easing-and-duration/tokens-specs
T.ease = {
  standard            = { 0.20, 0.00, 0.00, 1.00 },
  standardDecelerate  = { 0.00, 0.00, 0.00, 1.00 },  -- entering the screen
  standardAccelerate  = { 0.30, 0.00, 1.00, 1.00 },  -- leaving the screen
  emphasizedDecelerate= { 0.05, 0.70, 0.10, 1.00 },  -- prominent entries
  emphasizedAccelerate= { 0.30, 0.00, 0.80, 0.15 },  -- prominent exits
  linear              = { 0.00, 0.00, 1.00, 1.00 },  -- indeterminate only
}

-- Delay between successive items in a list reveal.
T.stagger = 0.035

function T.motion(name)
  local m = T.m[name] or T.m.base
  return m[1], m[2]
end

-- ---- reverse map, for the repaint registry ---------------------------------
-- Which token a colour came from. L.mk consults this while building so palette
-- colours are remembered by name and can repaint in place. Reindex whenever the
-- accent moves.
local reverse = {}

function T.reindex()
  reverse = {}
  for name, v in pairs(T.c) do
    if typeof(v) == "Color3" then reverse[tostring(v)] = name end
  end
end

function T.tokenOf(colour)
  return reverse[tostring(colour)]
end

T.reindex()
end
do -- ==== lm_02_spring.lua ====
-- LUMEN :: SPRING
-- A damped spring solved in closed form, so it is exact at any frame rate and
-- cannot blow up when a frame hitches. Euler integration does both.
--
-- Parameterised by DURATION and BOUNCE (Apple's scheme) rather than stiffness
-- and damping, because duration and bounce are independent and the raw
-- constants are not -- changing stiffness alone changes both.
--
-- Spring.selftest() checks the maths; verify_spring.py runs it head-less.

local L = getgenv().LUMEN
local Spring = {}
Spring.__index = Spring
L.Spring = Spring

local TAU = math.pi * 2

-- exp(-x), guarded. x is always >= 0 here by construction, but a NaN dt or a
-- pathological tuning would otherwise poison every later frame silently.
local function negexp(x)
  if x ~= x then return 0 end     -- NaN
  if x <= 0 then return 1 end
  if x > 40 then return 0 end     -- underflows to zero anyway, skip the call
  return math.exp(-x)
end

-- Apple's duration/bounce -> stiffness/damping, mass = 1.
function Spring.params(duration, bounce)
  duration = math.max(tonumber(duration) or 0.3, 1e-3)
  bounce   = math.clamp(tonumber(bounce) or 0, -0.95, 0.95)
  local k = (TAU / duration) ^ 2
  local c
  if bounce >= 0 then
    c = (1 - bounce) * 2 * TAU / duration
  else
    c = 2 * TAU / (duration * (1 + bounce))
  end
  return k, c
end

function Spring.new(duration, bounce, initial)
  local self = setmetatable({}, Spring)
  self.k, self.c = Spring.params(duration, bounce)
  self.duration, self.bounce = duration or 0.3, bounce or 0
  self.value    = initial or 0
  self.target   = initial or 0
  self.velocity = 0
  return self
end

function Spring:retune(duration, bounce)
  self.k, self.c = Spring.params(duration, bounce)
  self.duration, self.bounce = duration, bounce
  return self
end

-- Retarget. VELOCITY IS DELIBERATELY UNTOUCHED -- that is the whole point.
function Spring:to(target)
  self.target = target
  return self
end

-- Teleport: value, target and velocity all reset. For initial state only; using
-- this where `to` belongs is what makes an interface feel like it is snapping.
function Spring:snap(value)
  self.value, self.target, self.velocity = value, value, 0
  return self
end

function Spring:impulse(v)
  self.velocity = self.velocity + v
  return self
end

-- Exact step of  y'' + c*y' + k*y = 0  where y = value - target.
function Spring:step(dt)
  if not dt or dt ~= dt or dt <= 0 then return self.value end
  if dt > 0.25 then dt = 0.25 end     -- a long hitch should not teleport the UI

  local g  = self.target
  local y0 = self.value - g
  local v0 = self.velocity
  local k, c = self.k, self.c

  -- already there and not moving: skip the transcendentals entirely
  if y0 == 0 and v0 == 0 then return self.value end

  local disc = c * c - 4 * k
  local x, v

  if disc < -1e-9 then
    -- UNDERDAMPED: decaying oscillation. This is every bounce > 0 token.
    local zeta = c * 0.5
    local wd   = math.sqrt(4 * k - c * c) * 0.5
    local e    = negexp(zeta * dt)
    local c1   = y0
    local c2   = (v0 + zeta * y0) / wd
    local cs, sn = math.cos(wd * dt), math.sin(wd * dt)
    x = e * (c1 * cs + c2 * sn)
    v = e * ((-zeta * c1 + wd * c2) * cs + (-zeta * c2 - wd * c1) * sn)

  elseif disc <= 1e-9 then
    -- CRITICALLY DAMPED: the bounce = 0 case, fastest arrival without overshoot.
    local zeta = c * 0.5
    local e    = negexp(zeta * dt)
    local a    = y0
    local b    = v0 + zeta * y0
    local pos  = a + b * dt
    x = e * pos
    v = e * (b - zeta * pos)

  else
    -- OVERDAMPED: two real roots, both negative. Every bounce < 0 token.
    local sq = math.sqrt(disc)
    local r1 = (-c + sq) * 0.5
    local r2 = (-c - sq) * 0.5
    local c2 = (r1 * y0 - v0) / (r1 - r2)
    local c1 = y0 - c2
    local e1, e2 = negexp(-r1 * dt), negexp(-r2 * dt)
    x = c1 * e1 + c2 * e2
    v = c1 * r1 * e1 + c2 * r2 * e2
  end

  self.value    = x + g
  self.velocity = v
  return self.value
end

-- Settling is judged on BOTH offset and velocity. Position alone is not enough:
-- a spring passing through its target at speed is momentarily at zero offset,
-- and a position-only test would park it there mid-flight.
function Spring:settled(epsP, epsV)
  return math.abs(self.value - self.target) <= (epsP or 1e-3)
     and math.abs(self.velocity)            <= (epsV or 1e-2)
end

function Spring:finish()
  self.value, self.velocity = self.target, 0
  return self.value
end

-- ---------------------------------------------------------------- self test
--
-- Runnable head-less under luau.exe with no Roblox API, so the maths can be
-- verified without a game client. Checks the three regimes behave as their names
-- claim, that stepping is genuinely frame-rate independent, and -- the one that
-- matters -- that retargeting carries velocity.
function Spring.selftest()
  local out, fail = {}, 0
  local function check(name, cond, detail)
    if cond then out[#out + 1] = "ok    " .. name .. (detail and ("  " .. detail) or "")
    else out[#out + 1] = "FAIL  " .. name .. "  " .. tostring(detail) fail = fail + 1 end
  end

  local function run(dur, bounce, steps, dt, target)
    local s = Spring.new(dur, bounce, 0)
    s:to(target or 1)
    local peak = 0
    for _ = 1, steps do
      s:step(dt)
      if s.value > peak then peak = s.value end
    end
    return s, peak
  end

  -- bounce 0 is critically damped: must never exceed its target
  local _, peak0 = run(0.3, 0, 400, 1 / 240)
  check("bounce 0 does not overshoot", peak0 <= 1.0005, string.format("peak=%.5f", peak0))

  -- positive bounce must overshoot
  local _, peakB = run(0.3, 0.4, 400, 1 / 240)
  check("bounce 0.4 overshoots", peakB > 1.02, string.format("peak=%.4f", peakB))

  -- negative bounce must not, and must be slower to arrive than critical
  local sN, peakN = run(0.3, -0.5, 400, 1 / 240)
  check("bounce -0.5 does not overshoot", peakN <= 1.0005, string.format("peak=%.5f", peakN))

  -- all regimes must actually converge
  local sC = run(0.3, 0, 600, 1 / 240)
  check("critical converges", sC:settled(1e-3, 1e-2), string.format("v=%.5f", sC.velocity))
  check("overdamped converges", sN:settled(1e-2, 1e-1), string.format("d=%.5f", 1 - sN.value))

  -- FRAME-RATE INDEPENDENCE: 240 fps and 30 fps must agree closely over the
  -- same elapsed time. Euler integration fails this badly.
  local a = Spring.new(0.3, 0.2, 0); a:to(1)
  for _ = 1, 240 do a:step(1 / 240) end
  local b = Spring.new(0.3, 0.2, 0); b:to(1)
  for _ = 1, 30 do b:step(1 / 30) end
  check("240fps matches 30fps", math.abs(a.value - b.value) < 0.01,
        string.format("%.5f vs %.5f", a.value, b.value))

  -- STABILITY: an absurd dt must not produce NaN or an explosion
  local s = Spring.new(0.05, 0.5, 0); s:to(1)
  for _ = 1, 20 do s:step(10) end
  check("huge dt stays finite", s.value == s.value and math.abs(s.value) < 10,
        string.format("v=%.4f", s.value))

  -- VELOCITY PRESERVATION: retarget mid-flight and the spring must still be
  -- moving. This is the property the whole framework is built on.
  local r = Spring.new(0.4, 0, 0)
  r:to(1)
  for _ = 1, 12 do r:step(1 / 240) end
  local vBefore = r.velocity
  r:to(0.5)                                   -- retarget while in motion
  check("retarget preserves velocity", math.abs(r.velocity - vBefore) < 1e-12,
        string.format("%.5f -> %.5f", vBefore, r.velocity))
  check("velocity was non-zero", vBefore > 0.05, string.format("%.5f", vBefore))

  -- and snap must NOT preserve it
  r:snap(0)
  check("snap clears velocity", r.velocity == 0)

  return table.concat(out, "\n"), fail
end

end
do -- ==== lm_03_motion.lua ====
-- LUMEN :: MOTION
-- One RenderStepped loop drives every animation in the framework.
--
-- Motion.to never resets velocity, so retargeting mid-flight keeps the speed it
-- already had; a tween restarts from a dead stop. Settled springs are dropped
-- from the loop, so idle costs nothing.

local L = getgenv().LUMEN
local T = L.T
local Spring = L.Spring

local Motion = {}
L.Motion = Motion

-- ---------------------------------------------------------------- colour space
--
-- Colour is sprung in linear space, not sRGB: gamma-encoded channels average to a
-- chalky, desaturated midpoint. Squaring in and square-rooting out is the cheap
-- gamma-2.0 approximation, two multiplies.
local function toLinear(v) return v * v end
local function toGamma(v) return math.sqrt(v < 0 and 0 or v) end

-- ---------------------------------------------------------------- kinds
--
-- Each animatable type is decomposed into scalars, sprung independently, and
-- reassembled. eps is (position, velocity) for the settle test.
local KINDS = {}

KINDS.number = {
  n = 1, eps = { 0.0015, 0.02 },
  dec = function(v, o) o[1] = v end,
  enc = function(o) return o[1] end,
}

KINDS.UDim2 = {
  n = 4, eps = { 0.002, 0.03 },
  dec = function(v, o)
    o[1], o[2], o[3], o[4] = v.X.Scale, v.X.Offset, v.Y.Scale, v.Y.Offset
  end,
  enc = function(o) return UDim2.new(o[1], o[2], o[3], o[4]) end,
}

KINDS.UDim = {
  n = 2, eps = { 0.002, 0.03 },
  dec = function(v, o) o[1], o[2] = v.Scale, v.Offset end,
  enc = function(o) return UDim.new(o[1], o[2]) end,
}

KINDS.Vector2 = {
  n = 2, eps = { 0.002, 0.03 },
  dec = function(v, o) o[1], o[2] = v.X, v.Y end,
  enc = function(o) return Vector2.new(o[1], o[2]) end,
}

KINDS.Color3 = {
  n = 3, eps = { 0.0008, 0.01 },
  dec = function(v, o)
    o[1], o[2], o[3] = toLinear(v.R), toLinear(v.G), toLinear(v.B)
  end,
  enc = function(o)
    return Color3.new(toGamma(o[1]), toGamma(o[2]), toGamma(o[3]))
  end,
}

local function kindOf(v)
  local t = typeof(v)
  return KINDS[t]
end

-- ---------------------------------------------------------------- track
local Track = {}
Track.__index = Track

local active, activeN = {}, 0
local byObject = setmetatable({}, { __mode = "k" })

local function wake(tr)
  if tr.awake or tr.dead then return end
  tr.awake = true
  activeN = activeN + 1
  active[activeN] = tr
  tr.slot = activeN
end

local function sleep(tr)
  if not tr.awake then return end
  tr.awake = false
  -- swap-remove: order is irrelevant and this keeps removal O(1)
  local last = active[activeN]
  active[tr.slot] = last
  if last then last.slot = tr.slot end
  active[activeN] = nil
  activeN = activeN - 1
  tr.slot = nil
  if tr.onSettle then L.try("motion.settle", tr.onSettle, tr) end
end

function Track:to(value)
  if self.dead then return self end
  local kd = self.kind
  kd.dec(value, self.tmp)
  for i = 1, kd.n do
    self.springs[i]:to(self.tmp[i])
  end
  self.goal = value
  wake(self)
  return self
end

function Track:snap(value)
  if self.dead then return self end
  local kd = self.kind
  kd.dec(value, self.tmp)
  for i = 1, kd.n do self.springs[i]:snap(self.tmp[i]) end
  self.goal = value
  self.last = nil
  self:write(value)
  sleep(self)
  return self
end

function Track:retune(token)
  self.token = token or self.token
  local d, b = Motion.resolve(token or self.token)
  for i = 1, self.kind.n do self.springs[i]:retune(d, b) end
  return self
end

function Track:impulse(v)
  for i = 1, self.kind.n do self.springs[i]:impulse(v) end
  wake(self)
  return self
end

function Track:write(value)
  if self.last == value then return end
  self.last = value
  self.obj[self.prop] = value
end

function Track:destroy()
  self.dead = true
  sleep(self)
  local m = byObject[self.obj]
  if m then m[self.prop] = nil end
end

-- ---------------------------------------------------------------- api

-- Accepts a token name ("base") or a raw { duration, bounce } pair. The profile
-- multipliers apply at resolve time, so one pair restyles every animation.
Motion.durScale, Motion.bounceScale = 1, 1

function Motion.resolve(token)
  local d, b
  if type(token) == "table" then d, b = token[1], token[2]
  else
    local m = T.m[token or "base"] or T.m.base
    d, b = m[1], m[2]
  end
  return d * Motion.durScale, math.clamp(b * Motion.bounceScale, -0.95, 0.95)
end

-- A Track builds its springs once, so a token change alone does nothing to what
-- is already on screen. Each track remembers its token so it can be retuned.
function Motion.reprofile()
  local n = 0
  for _, props in pairs(byObject) do
    for _, tr in pairs(props) do
      if not tr.dead and tr.token then
        tr:retune(tr.token)
        n = n + 1
      end
    end
  end
  return n
end

function Motion.track(obj, prop, token)
  local m = byObject[obj]
  if not m then m = {} byObject[obj] = m end
  local existing = m[prop]
  if existing and not existing.dead then
    if token then existing.token = token existing:retune(token) end
    return existing
  end

  local current = obj[prop]
  local kd = kindOf(current)
  if not kd then
    L.fault("motion.kind", tostring(typeof(current)) .. " on " .. tostring(prop))
    return nil
  end

  local d, b = Motion.resolve(token)
  local tr = setmetatable({
    obj = obj, prop = prop, kind = kd, springs = {}, tmp = {},
    token = token or "base",
    goal = current, last = current, awake = false, dead = false,
  }, Track)

  kd.dec(current, tr.tmp)
  for i = 1, kd.n do tr.springs[i] = Spring.new(d, b, tr.tmp[i]) end
  m[prop] = tr
  return tr
end

-- Animate a property to a value, creating the track on first use.
function Motion.to(obj, prop, value, token)
  local tr = Motion.track(obj, prop, token)
  if tr then tr:to(value) end
  return tr
end

function Motion.set(obj, prop, value, token)
  local tr = Motion.track(obj, prop, token)
  if tr then tr:snap(value) end
  return tr
end

function Motion.stop(obj, prop)
  local m = byObject[obj]
  local tr = m and m[prop]
  if tr then tr:destroy() end
end

function Motion.stopAll(obj)
  local m = byObject[obj]
  if not m then return end
  for _, tr in pairs(m) do tr:destroy() end
  byObject[obj] = nil
end

-- ---------------------------------------------------------------- instrument
--
-- What the tokens do, measured through this exact spring code. `duration` is the
-- period parameter, not the settle time -- they are not the same number:
--
--     token         dur   bnc    t50ms  t90ms  t99ms  overshoot
--     instant      0.10  0.00       27     62    150      -0.0%
--     fast         0.18  0.20       44     86    249       1.5%
--     base         0.30  0.20       72    143    390       1.5%
--     slow         0.44  0.22      105    204    549       2.0%
--     expressive   0.42  0.38       92    161    510       8.4%
--     gentle       0.32 -0.20       99    264    568      -0.0%
--
-- Panels reach 90% of travel in 143 ms, a window entrance in 204 ms. Anything
-- that still feels instant is a property written directly instead of through
-- Motion, not a duration problem.

Motion.BUDGET = 0.002          -- 2 ms of main-thread work per frame

local perf = {
  cap = 240, i = 0, n = 0, ring = table.create(240, 0),
  frames = 0, over = 0, peak = 0, ema = 0,
}

local function record(elapsed)
  perf.frames = perf.frames + 1
  perf.i = perf.i % perf.cap + 1
  perf.ring[perf.i] = elapsed
  if perf.n < perf.cap then perf.n = perf.n + 1 end
  if elapsed > perf.peak then perf.peak = elapsed end
  if elapsed > Motion.BUDGET then perf.over = perf.over + 1 end
  -- EMA drives the degrade decision; a mean over all time reacts far too slowly.
  perf.ema = perf.ema + (elapsed - perf.ema) * 0.05
end

-- Percentiles are computed ON DEMAND, never per frame -- an instrument that
-- costs what it measures is not an instrument.
function Motion.perf()
  local n = perf.n
  if n == 0 then
    return { samples = 0, active = activeN }
  end
  local copy = table.create(n)
  for j = 1, n do copy[j] = perf.ring[j] end
  table.sort(copy)
  local sum = 0
  for j = 1, n do sum = sum + copy[j] end
  local function pct(q)
    local idx = math.clamp(math.ceil(q * n), 1, n)
    return copy[idx] * 1000
  end
  return {
    samples   = n,
    active    = activeN,
    avgMs     = (sum / n) * 1000,
    medianMs  = pct(0.50),
    p95Ms     = pct(0.95),
    worstMs   = copy[n] * 1000,
    peakMs    = perf.peak * 1000,
    budgetMs  = Motion.BUDGET * 1000,
    overPct   = perf.frames > 0 and (perf.over / perf.frames) * 100 or 0,
    frames    = perf.frames,
    quality   = Motion.quality,
  }
end

function Motion.resetPerf()
  perf.i, perf.n, perf.frames, perf.over, perf.peak, perf.ema = 0, 0, 0, 0, 0, 0
  return true
end

-- Measure a token's real response in-client, so the table above can be checked
-- on the machine that is actually complaining rather than trusted.
function Motion.measure(token, dt)
  local d, b = Motion.resolve(token)
  local s = Spring.new(d, b, 0)
  s:to(1)
  dt = dt or 1 / 1000
  local t, t50, t90, t99, peak = 0, nil, nil, nil, 0
  for _ = 1, math.floor(4 / dt) do
    s:step(dt) t = t + dt
    if s.value > peak then peak = s.value end
    if not t50 and s.value >= 0.50 then t50 = t end
    if not t90 and s.value >= 0.90 then t90 = t end
    if not t99 and math.abs(s.value - 1) <= 0.01 and math.abs(s.velocity) < 0.05 then
      t99 = t
    end
  end
  return { token = token, duration = d, bounce = b,
           t50ms = (t50 or 0) * 1000, t90ms = (t90 or 0) * 1000,
           t99ms = (t99 or 0) * 1000, overshootPct = (peak - 1) * 100 }
end

-- ---------------------------------------------------------------- degrade
--
-- Degrading means doing LESS WORK, never moving slower. Stretching durations
-- under load is the exact trick that makes an interface feel worse while
-- looking like it is trying to feel better -- the frames are still late, they
-- are just late for longer.
--
-- Hysteresis is not optional here: a single threshold flips quality on and off
-- every few frames right at the boundary, and a hub that keeps changing its own
-- animation style is worse than one that is simply slow.
Motion.quality = 1        -- 1 full, 0 minimal
Motion.autoDegrade = true

local degradeHold, recoverHold = 0, 0

local function judge()
  if not Motion.autoDegrade then return end
  if perf.ema > Motion.BUDGET then
    degradeHold, recoverHold = degradeHold + 1, 0
    if degradeHold > 60 and Motion.quality > 0 then
      Motion.quality = math.max(0, Motion.quality - 0.5)
      degradeHold = 0
      L.note("motion", string.format(
        "quality -> %.1f (ema %.2f ms over %.2f ms budget)",
        Motion.quality, perf.ema * 1000, Motion.BUDGET * 1000))
    end
  elseif perf.ema < Motion.BUDGET * 0.6 then
    recoverHold, degradeHold = recoverHold + 1, 0
    if recoverHold > 180 and Motion.quality < 1 then
      Motion.quality = math.min(1, Motion.quality + 0.5)
      recoverHold = 0
      L.note("motion", string.format("quality -> %.1f (recovered)", Motion.quality))
    end
  end
end

-- Features consult this before spending frames on something decorative. Weight
-- is how ornamental the animation is: 0 is structural and always runs, 1 is
-- pure decoration and is the first thing dropped.
function Motion.shouldAnimate(weight)
  return Motion.quality >= (weight or 0)
end

function Motion.stats()
  return { active = activeN, gen = L._gen, quality = Motion.quality }
end

-- ---------------------------------------------------------------- loop
local lastT = os.clock()

function Motion.step(dt)
  local i = 1
  while i <= activeN do
    local tr = active[i]
    if not tr or tr.dead then
      i = i + 1
    else
      local obj = tr.obj
      -- Drop tracks whose instance has left the tree. Checked only AFTER the
      -- object has been parented once, because a track is legitimately created
      -- during construction while Parent is still nil.
      if obj.Parent then tr.parented = true end
      if tr.parented and not obj.Parent then
        tr.dead = true
        sleep(tr)
      else
        local kd, sp, tmp = tr.kind, tr.springs, tr.tmp
        local settled = true
        local epsP, epsV = kd.eps[1], kd.eps[2]
        for j = 1, kd.n do
          local s = sp[j]
          s:step(dt)
          tmp[j] = s.value
          if settled and not s:settled(epsP, epsV) then settled = false end
        end
        if settled then
          for j = 1, kd.n do
            sp[j]:finish()
            tmp[j] = sp[j].value
          end
        end
        tr:write(kd.enc(tmp))
        if settled then sleep(tr) else i = i + 1 end
      end
    end
  end
end

function Motion.start()
  if Motion._on then return end
  Motion._on = true
  lastT = os.clock()
  -- RenderStepped so writes land before the frame is drawn; anything on
  -- Heartbeat is a frame late and shows up as UI lagging one frame behind the
  -- cursor during a drag.
  L.hold(L.RunService.RenderStepped:Connect(function(dt)
    if not L.live() then return end
    -- Two os.clock() calls a frame is far below the noise floor of what is being
    -- measured, and without them every claim about smoothness in this project is
    -- somebody's opinion.
    local t0 = os.clock()
    Motion.step(dt)
    record(os.clock() - t0)
    judge()
  end))
end

-- ---------------------------------------------------------------- curves
--
-- Springs cover almost everything, but not quite everything: an indeterminate
-- shimmer or a sweep that must land on an exact frame wants a real curve. These
-- are the Material 3 easing tokens, sampled properly.
--   https://m3.material.io/styles/motion/easing-and-duration/tokens-specs

local function bezierAxis(t, a, b)
  local mt = 1 - t
  return 3 * mt * mt * t * a + 3 * mt * t * t * b + t * t * t
end

-- cubic-bezier(x1,y1,x2,y2) evaluated at x. Newton-Raphson to invert x(t), with
-- a bisection fallback for the flat regions where the derivative vanishes and
-- Newton would otherwise wander off.
function L.bezier(name, x)
  local e = T.ease[name] or T.ease.standard
  local x1, y1, x2, y2 = e[1], e[2], e[3], e[4]
  x = math.clamp(x, 0, 1)
  if x == 0 or x == 1 then return x end

  local t = x
  for _ = 1, 6 do
    local cx = bezierAxis(t, x1, x2) - x
    if math.abs(cx) < 1e-5 then break end
    local mt = 1 - t
    local d = 3 * mt * mt * x1 + 6 * mt * t * (x2 - x1) + 3 * t * t * (1 - x2)
    if math.abs(d) < 1e-6 then
      local lo, hi = 0, 1
      for _ = 1, 20 do
        t = (lo + hi) * 0.5
        if bezierAxis(t, x1, x2) < x then lo = t else hi = t end
      end
      break
    end
    t = t - cx / d
  end
  return bezierAxis(math.clamp(t, 0, 1), y1, y2)
end

-- ---------------------------------------------------------------- helpers

-- Delay for item i of n in a cascade. Capped so a fifty-item list does not take
-- two seconds to finish revealing -- past about ten items the eye reads it as a
-- wave regardless, and the tail just feels slow.
function Motion.stagger(i, step)
  return math.min((i - 1) * (step or T.stagger), 0.34)
end

-- THE STAGGER PRIMITIVE.
--
-- `Motion.stagger` above only computes a delay; every caller then had to wire
-- its own task.delay, which is why almost nothing in the hub actually cascades
-- and why lists arrive all at once. Arriving all at once is most of what reads
-- as "basic" -- the eye gets no order to follow, so a list of twelve rows lands
-- as one flat event instead of a wave.
--
-- Cancellable, because a cascade that is still firing into a panel the user has
-- already closed will animate a dead tree and, worse, pop things back into view
-- after the close finished.
function Motion.seq(items, fn, opts)
  opts = opts or {}
  local step = opts.step or T.stagger or 0.03
  local cap  = opts.cap  or 0.34

  -- Under load the cascade COLLAPSES rather than slowing: the same work happens,
  -- it just stops being spread across frames. Spreading is what costs -- it is
  -- what keeps many tracks alive at once.
  if Motion.quality < 1 then step = step * Motion.quality end

  local h = { cancelled = false, pending = 0 }
  function h:cancel() self.cancelled = true return self end

  for i, item in ipairs(items) do
    local d = math.min((i - 1) * step, cap)
    if d <= 0 then
      if L.live() then L.try("motion.seq", fn, item, i) end
    else
      h.pending = h.pending + 1
      task.delay(d, function()
        h.pending = h.pending - 1
        if h.cancelled or not L.live() then return end
        L.try("motion.seq", fn, item, i)
      end)
    end
  end
  return h
end

-- The common case: animate one property across a list, in order.
function Motion.cascade(objs, prop, value, token, opts)
  return Motion.seq(objs, function(o)
    if o and o.Parent then Motion.to(o, prop, value, token) end
  end, opts)
end

function Motion.after(delay, fn)
  task.delay(delay, function()
    if L.live() then L.try("motion.after", fn) end
  end)
end

Motion.start()

end
do -- ==== lm_04_atoms.lua ====
-- LUMEN :: ATOMS
-- The primitives every control is built from: surfaces, text, shadows, glow,
-- grain, scrolling, hover/press states, tooltips.
--
-- Shadows and glows are pre-rendered images because Roblox has no box-shadow and
-- no radial gradient. Stacking circles to fake one always bands.

local L = getgenv().LUMEN
local T, M = L.T, L.Motion
local mk = L.mk

local A = {}
L.A = A

-- ---------------------------------------------------------------- surface

function A.surface(props)
  props = props or {}
  local e = T.elev[props.elev or 0]
  local f = mk("Frame", {
    BackgroundColor3 = props.fill or e.fill,
    BorderSizePixel = 0,
    Size = props.Size, Position = props.Position,
    AnchorPoint = props.AnchorPoint, LayoutOrder = props.LayoutOrder,
    Name = props.Name or "Surface",
    ClipsDescendants = props.clip,
    Parent = props.Parent,
  })
  L.corner(props.radius or T.r.md, f)
  if props.line ~= false then
    L.stroke(props.lineColour or e.line, 1, props.lineT or e.lineT, f)
  end
  -- One-pixel highlight along the top edge, and the whole elevation cue --
  -- Roblox has no box-shadow.
  if props.sheen then
    mk("Frame", {
      Size = UDim2.new(1, -(props.radius or T.r.md) * 2, 0, 1),
      Position = UDim2.new(0, props.radius or T.r.md, 0, 0),
      BackgroundColor3 = Color3.new(1, 1, 1),
      BackgroundTransparency = 0.92,
      BorderSizePixel = 0, ZIndex = 2,
      Parent = f,
    })
  end
  return f
end

-- Labels that asked to be truncated. Registered here rather than at each call
-- site so nothing has to remember: if a string can be cut short, it is
-- automatically eligible to be shown in full on hover. See A.truncatable below.
A.tips = {}

-- EXPLANATIONS, as distinct from truncations. A.tips exists so a label that had
-- to be cut short can still be read in full; this is the other half -- a control
-- whose PURPOSE is not obvious from its face. The panel pills are the clearest
-- case: "Goto", "Pick" and "Mark" are four characters each because a card is
-- narrow, and none of them says what it does.
--
-- Deliberately not wired to every control's `desc`: that text is already
-- rendered under the title, and a tooltip that repeats what is visible an inch
-- away is noise. This is for the things with nowhere to put an explanation.
A.hints = {}

-- PRUNED ON A CLOCK, not only when hovered. Both registries were swept inside
-- the hover test, so a window that is rebuilt while the pointer is elsewhere
-- left its labels on the list forever. Measured growing about twenty entries
-- per five panel cycles.
task.spawn(function()
  while true do
    task.wait(15)
    for i = #A.tips, 1, -1 do
      local l = A.tips[i]
      if not (l and l.Parent) then table.remove(A.tips, i) end
    end
    for i = #A.hints, 1, -1 do
      local h = A.hints[i]
      if not (h and h.obj and h.obj.Parent) then table.remove(A.hints, i) end
    end
  end
end)

-- `label` is optional and names the control; without one the card is a single
-- line, exactly as before. With one the card reads as a heading and a sentence,
-- which is the difference between a caption and an explanation.
function A.explain(obj, text, label)
  if not (obj and type(text) == "string" and text ~= "") then return obj end
  A.hints[#A.hints + 1] = { obj = obj, text = text, label = label }
  return obj
end

function A.text(props)
  local l = mk("TextLabel", {
    BackgroundTransparency = 1,
    Text = props.Text or "",
    TextColor3 = props.colour or T.c.text,
    Font = props.font or T.font.body,
    TextSize = props.size or T.size.body,
    TextXAlignment = props.align or Enum.TextXAlignment.Left,
    TextYAlignment = props.valign or Enum.TextYAlignment.Center,
    Size = props.Size or UDim2.fromScale(1, 1),
    Position = props.Position,
    AnchorPoint = props.AnchorPoint,
    LayoutOrder = props.LayoutOrder,
    TextTruncate = props.truncate and Enum.TextTruncate.AtEnd or Enum.TextTruncate.None,
    TextWrapped = props.wrap or false,
    RichText = props.rich or false,
    ZIndex = props.ZIndex or 1,
    Name = props.Name or "Text",
    Parent = props.Parent,
  })
  if props.autoSize then l.AutomaticSize = props.autoSize end
  if props.truncate and props.tip ~= false then A.tips[#A.tips + 1] = l end
  return l
end

function A.divider(parent, order)
  return mk("Frame", {
    Size = UDim2.new(1, 0, 0, 1),
    BackgroundColor3 = T.c.line,
    BackgroundTransparency = 0.4,
    BorderSizePixel = 0,
    LayoutOrder = order,
    Name = "Divider",
    Parent = parent,
  })
end

-- Vertical gradient used on the accent. Two stops of the SAME hue family, never
-- two unrelated colours -- a gradient between distant hues passes through a
-- third colour that belongs to no part of the palette.
-- Tracked separately from L.paints: a ColorSequence is not a Color3, so the
-- generic registry in L.mk cannot see it. These are rebuilt on a palette change.
--
-- NOT a weak table. An Instance held only by the Roblox tree is unreachable from
-- Lua's point of view, so weak keys let the entries be collected and the set was
-- empty by the time a repaint asked for it -- 0 gradients repainted while 526
-- plain properties worked. Held strongly and pruned on use instead.
A.accentGradients = {}

function A.accentGradient(parent, rotation)
  local g = mk("UIGradient", {
    Color = ColorSequence.new(T.c.accent, T.c.accentAlt),
    Rotation = rotation or 90,
    Parent = parent,
  })
  A.accentGradients[g] = true
  return g
end

function A.repaintGradients()
  local n = 0
  for g in pairs(A.accentGradients) do
    if g.Parent then
      g.Color = ColorSequence.new(T.c.accent, T.c.accentAlt)
      n = n + 1
    else
      A.accentGradients[g] = nil
    end
  end
  return n
end

-- ---------------------------------------------------------------- depth
--
-- ROBLOX HAS NO BOX-SHADOW AND NO RADIAL GRADIENT. That single fact is why every
-- dark Roblox hub looks flat, including every earlier version of this one. Both
-- fakes were tried here and both failed the same way: a radial falloff built
local getAsset = rawget(getgenv(), "getcustomasset") or rawget(getgenv(), "getsynasset")

-- RESOLVED ON FIRST USE, NOT AT LOAD. getcustomasset copies the file into the
-- content folder, so each call costs real milliseconds -- and resolving all
-- twelve sprites at module scope was most of the 306 ms this script blocked for
-- before the loading screen could draw its first frame. That is the freeze you
-- get the instant you execute. Nothing here is needed until something is built,
-- and by then we are inside a coroutine that yields.
local UI_DIR = "lumen_fx/ui"
local IMG_FILES = { shadow = "shadow.png", glow = "glow.png",
                    ring = "ring.png", grain = "grain.png",
                    flare = "flare.png", beam = "beam.png" }

local function resolveAsset(path)
  if type(getAsset) ~= "function" then return nil end
  local ok, present = pcall(isfile, path)
  if not ok or not present then return nil end
  local gok, id = pcall(getAsset, path)
  return gok and id or nil
end

-- Misses are remembered so a missing file is not re-resolved on every lookup.
-- But they must NOT be remembered forever: a pack can land mid-session, and a
-- permanent negative cache meant the sprite stayed missing until the next
-- execute even though the file was now on disk. A.forgetMisses() clears them.
local imgTried = {}
A.img = setmetatable({}, { __index = function(t, k)
  if imgTried[k] then return nil end
  imgTried[k] = true
  local id = IMG_FILES[k] and resolveAsset(UI_DIR .. "/" .. IMG_FILES[k])
  if id then rawset(t, k, id) end
  return id
end })

---Drop the negative cache so sprites installed since the last lookup resolve.
function A.forgetMisses()
  local n = 0
  for k in pairs(imgTried) do
    if rawget(A.img, k) == nil then imgTried[k] = nil n = n + 1 end
  end
  return n
end

function A.hasImages() return A.img.shadow ~= nil end

-- Soft drop shadow behind a panel. 9-slice, so it stretches to any size without
-- the blurred corners smearing -- Roblox scales only the centre of a sliced
-- image, which is exactly why the blur margin lives inside the slice border.
-- THE DARK BOX. Every one of them, and they were all this.
--
-- The sprite is nine-sliced at (72, 72, 120, 120): 72 px of border on each
-- side, so 144 px is the smallest element that still has room for the soft
-- falloff between its corners.
--
-- A toast's shadow renders at 404 x 137. One hundred and thirty-seven is less
-- than one hundred and forty-four, so vertically there is NO middle left --
-- Roblox squashes the two 72 px corner bands into each other and the gradient
-- collapses into a hard rectangle. At the toast's settled ImageTransparency of
-- 0.42 that is a 58%-opaque black block, slightly larger than the card, fading
-- in over ~0.3 s behind it. Which is exactly what it looked like: a dark box,
-- a beat late, that then goes away.
--
-- It was never a timing bug, which is why twice re-timing it changed nothing.
-- Every shadow in the hub comes through here, so every panel, toast and pin
-- small enough to trip the threshold had the same block behind it.
--
-- SliceScale shrinks the borders proportionally, so the corners always fit and
-- the falloff survives at any size. Bound to AbsoluteSize rather than computed
-- once: these elements are sprung, and a shadow that is correct only at its
-- resting size is wrong for the whole animation -- which is the part you
-- actually see.
local SLICE_PX = 72

function A.shadow(target, opts)
  if not A.img.shadow then return nil end
  opts = opts or {}
  local spread = opts.spread or 26
  local sh = mk("ImageLabel", {
    AnchorPoint = Vector2.new(0.5, 0.5),
    Position = UDim2.new(0.5, 0, 0.5, opts.lift or 6),
    Size = UDim2.new(1, spread * 2, 1, spread * 2),
    BackgroundTransparency = 1,
    Image = A.img.shadow,
    ImageTransparency = opts.alpha or 0.35,
    ImageColor3 = opts.colour or Color3.new(0, 0, 0),
    ScaleType = Enum.ScaleType.Slice,
    SliceCenter = Rect.new(SLICE_PX, SLICE_PX, 120, 120),
    ZIndex = (opts.ZIndex or 0),
    Name = "Shadow", Parent = opts.Parent or target.Parent,
  })

  local function fitSlice()
    if not sh.Parent then return end
    local s = sh.AbsoluteSize
    local smallest = math.min(s.X, s.Y)
    if smallest <= 0 then return end
    -- keep a sliver of middle rather than exactly zero, or the two corner
    -- bands meet and the seam reads as a line across the shadow
    local want = math.clamp(smallest / (SLICE_PX * 2.25), 0.2, 1)
    if math.abs(sh.SliceScale - want) > 0.01 then sh.SliceScale = want end
  end
  fitSlice()
  L.hold(sh:GetPropertyChangedSignal("AbsoluteSize"):Connect(fitSlice))

  return sh
end

-- Real radial bloom. Replaces the stacked-circle version entirely.
function A.glow(parent, size, colour, opts)
  opts = opts or {}
  if not A.img.glow then return nil end
  return mk("ImageLabel", {
    AnchorPoint = Vector2.new(0.5, 0.5),
    Position = opts.Position or UDim2.fromScale(0.5, 0.5),
    Size = UDim2.fromOffset(size, size),
    BackgroundTransparency = 1,
    Image = A.img.glow,
    ImageColor3 = colour,
    ImageTransparency = opts.alpha or 0.72,
    ZIndex = opts.ZIndex or 1,
    Name = "Glow", Parent = parent,
  })
end

-- Chrome icon tiles, extracted from the reference render. These are real 3D
-- glass objects; nothing drawn from frames gets anywhere near this, and the
-- dispersion along their edges is the only place spectral colour appears.
-- lazy, for the same reason A.img is
local ICON_DIR = "lumen_fx/icons"
local iconTried = {}
A.icons = setmetatable({}, { __index = function(t, k)
  if iconTried[k] then return nil end
  iconTried[k] = true
  local id = resolveAsset(ICON_DIR .. "/" .. tostring(k) .. ".png")
  if id then rawset(t, k, id) end
  return id
end })

function A.chrome(parent, name, size, opts)
  opts = opts or {}
  local id = A.icons[name]
  if not id then return nil end
  return mk("ImageLabel", {
    Size = UDim2.fromOffset(size, size),
    Position = opts.Position,
    AnchorPoint = opts.AnchorPoint,
    BackgroundTransparency = 1,
    Image = id,
    ImageTransparency = opts.alpha or 0,
    ZIndex = opts.ZIndex or 2,
    Name = "Chrome", Parent = parent,
  })
end

-- Tiled grain. A big flat gradient in an 8-bit framebuffer bands; a couple of
-- levels of noise dither it away. Same reason film grain exists.
function A.grain(parent, alpha)
  if not A.img.grain then return nil end
  return mk("ImageLabel", {
    Size = UDim2.fromScale(1, 1),
    BackgroundTransparency = 1,
    Image = A.img.grain,
    ImageTransparency = alpha or 0.94,
    ScaleType = Enum.ScaleType.Tile,
    TileSize = UDim2.fromOffset(128, 128),
    ZIndex = 1,
    Name = "Grain", Parent = parent,
  })
end

-- Vertical wash across a surface. Two stops of the same colour at different
-- brightness, never two hues -- this is a light source, not a decoration.
function A.wash(parent, topLift, bottomDrop)
  return mk("UIGradient", {
    Color = ColorSequence.new(
      Color3.new(1, 1, 1),
      Color3.new(1 - (bottomDrop or 0.10), 1 - (bottomDrop or 0.10), 1 - (bottomDrop or 0.10))
    ),
    Transparency = NumberSequence.new(0),
    Rotation = 90,
    Offset = Vector2.new(0, topLift or 0),
    Parent = parent,
  })
end

-- A hairline that fades out at both ends. A full-width 1 px line reads as a
-- border; one that dissolves at the edges reads as a highlight catching light.
function A.hairline(parent, colour, y, alpha)
  local f = mk("Frame", {
    Position = UDim2.new(0, 0, 0, y or 0),
    Size = UDim2.new(1, 0, 0, 1),
    BackgroundColor3 = colour,
    BorderSizePixel = 0, ZIndex = 6,
    Parent = parent,
  })
  mk("UIGradient", {
    Transparency = NumberSequence.new({
      NumberSequenceKeypoint.new(0, 1),
      NumberSequenceKeypoint.new(0.5, alpha or 0.25),
      NumberSequenceKeypoint.new(1, 1),
    }),
    Parent = f,
  })
  return f
end

-- ---------------------------------------------------------------- world blur
--
-- The single largest visual upgrade available, and it costs one instance: blur
-- the 3D world while the hub is open. A crisp game behind a flat panel is
-- exactly what makes an overlay look pasted on; pushing the world out of focus
local Lighting = game:GetService("Lighting")

function A.worldBlur()
  if A._blur and A._blur.Parent then return A._blur end
  local b = Instance.new("BlurEffect")
  b.Name = "LumenBlur"
  b.Size = 0
  b.Enabled = true
  b.Parent = Lighting
  L.own(b)
  A._blur = b
  return b
end

function A.blurTo(size, token)
  local b = A.worldBlur()
  M.to(b, "Size", size, token or "slow")
end

-- ---------------------------------------------------------------- scrolling
--
-- SPRUNG SCROLLING. Roblox writes CanvasPosition in instant jumps on every wheel
-- notch, which is the one genuinely jerky thing left in the interface -- and it
-- cannot be eased, because the engine owns the property.
A._scrolls = setmetatable({}, { __mode = "k" })

-- THE WHEEL HAS TO BE SUNK, NOT JUST HANDLED.
local CAS = game:GetService("ContextActionService")
A._wheelGuards = {}

function A.addWheelGuard(fn)
  A._wheelGuards[#A._wheelGuards + 1] = fn
end

do
  local NAME = "LumenWheelSink"
  pcall(function() CAS:UnbindAction(NAME) end)
  CAS:BindActionAtPriority(NAME, function()
    for _, fn in ipairs(A._wheelGuards) do
      local ok, want = pcall(fn)
      if ok and want then return Enum.ContextActionResult.Sink end
    end
    return Enum.ContextActionResult.Pass
  end, false, Enum.ContextActionPriority.High.Value + 10, Enum.UserInputType.MouseWheel)

  L.hold({ Disconnect = function() pcall(function() CAS:UnbindAction(NAME) end) end })
end

local SCROLL_TOKEN = { 0.26, 0.0 }

function A.smoothScroll(scroll, opts)
  opts = opts or {}
  if A._scrolls[scroll] then return A._scrolls[scroll] end

  scroll.ScrollingEnabled = false
  local ctrl = { obj = scroll, target = scroll.CanvasPosition.Y }
  local speed = opts.speed or 96

  local function maxY()
    return math.max(scroll.AbsoluteCanvasSize.Y - scroll.AbsoluteWindowSize.Y, 0)
  end

  function ctrl:clamp()
    self.target = math.clamp(self.target, 0, maxY())
    return self.target
  end

  function ctrl:to(y, immediate)
    self.target = y
    self:clamp()
    local v = Vector2.new(0, self.target)
    if immediate then M.set(scroll, "CanvasPosition", v)
    else M.to(scroll, "CanvasPosition", v, SCROLL_TOKEN) end
  end

  function ctrl:reset()
    self.target = 0
    M.set(scroll, "CanvasPosition", Vector2.zero)
  end

  function ctrl:nudge(delta)
    self:to(self.target + delta)
  end

  scroll.InputChanged:Connect(function(i)
    if i.UserInputType ~= Enum.UserInputType.MouseWheel then return end
    -- Position.Z carries the notch direction: +1 up, -1 down
    ctrl:nudge(-i.Position.Z * speed)
  end)

  A._scrolls[scroll] = ctrl
  return ctrl
end

function A.scrollReset(scroll)
  local c = A._scrolls[scroll]
  if c then c:reset() else scroll.CanvasPosition = Vector2.zero end
end

function A.scroll(props)
  local s = mk("ScrollingFrame", {
    BackgroundTransparency = 1,
    BorderSizePixel = 0,
    Size = props.Size or UDim2.fromScale(1, 1),
    Position = props.Position,
    CanvasSize = UDim2.new(),
    AutomaticCanvasSize = Enum.AutomaticSize.Y,
    ScrollingDirection = Enum.ScrollingDirection.Y,
    ScrollBarThickness = props.bar or 2,
    ScrollBarImageColor3 = T.c.lineStrong,
    ScrollBarImageTransparency = 0.3,
    ElasticBehavior = Enum.ElasticBehavior.WhenScrollable,
    Name = props.Name or "Scroll",
    Parent = props.Parent,
  })
  if props.gap then L.list(props.gap, nil, s) end
  -- explicit > 0 test: `padding = 0` is TRUTHY in Lua, so the old check built
  -- a zero UIPadding and any padding the caller added afterwards became a
  -- second one on the same instance, which Roblox silently ignores.
  if props.padding and props.padding > 0 then
    L.pad(props.padding, props.padding, props.padding, props.padding, s)
  end
  -- AutomaticCanvasSize grows the canvas from zero, and CanvasPosition 0 against
  -- a zero-height canvas already counts as "the bottom" -- so a list can end up
  -- pinned to its own end as it fills. Deferring one frame and re-zeroing costs
  -- nothing and removes a genuinely baffling bug.
  task.defer(function()
    if s.Parent then s.CanvasPosition = Vector2.new(0, 0) end
  end)
  if props.smooth ~= false then A.smoothScroll(s) end
  return s
end

-- ---------------------------------------------------------------- icons
--
-- Every glyph is built from `bar`: a rounded rectangle, rotated. A chevron is
-- two bars at +/-45 degrees; a cross is two at +/-45 crossing; a check is two of
-- unequal length. All of it inherits colour from the token palette.
local Icon = {}
A.Icon = Icon

local function bar(parent, w, h, x, y, rot, colour, thickness)
  local b = mk("Frame", {
    AnchorPoint = Vector2.new(0.5, 0.5),
    Position = UDim2.fromOffset(x, y),
    Size = UDim2.fromOffset(w, h or thickness or 2),
    Rotation = rot or 0,
    BackgroundColor3 = colour,
    BorderSizePixel = 0,
    Parent = parent,
  })
  L.corner(999, b)
  return b
end

local function holder(parent, size, name)
  return mk("Frame", {
    Size = UDim2.fromOffset(size, size),
    BackgroundTransparency = 1,
    Name = name or "Icon",
    Parent = parent,
  })
end

-- direction: "right" | "left" | "up" | "down"
function Icon.chevron(parent, size, colour, direction)
  local h = holder(parent, size, "Chevron")
  local c = size / 2
  local arm = size * 0.30
  local rot = ({ right = 0, down = 90, left = 180, up = 270 })[direction or "right"]
  local inner = mk("Frame", { Size = UDim2.fromScale(1, 1), BackgroundTransparency = 1,
                              Rotation = rot, Parent = h })
  bar(inner, arm, 1.6, c - arm * 0.18, c - arm * 0.35, 45, colour)
  bar(inner, arm, 1.6, c - arm * 0.18, c + arm * 0.35, -45, colour)
  -- `inner` is returned separately so callers can spring its Rotation: an
  -- expanding dropdown turns its chevron rather than swapping the glyph.
  return h, inner
end

function Icon.check(parent, size, colour)
  local h = holder(parent, size, "Check")
  local c = size / 2
  bar(h, size * 0.30, 1.8, c - size * 0.16, c + size * 0.10, 45, colour)
  bar(h, size * 0.52, 1.8, c + size * 0.09, c - size * 0.02, -45, colour)
  return h
end

function Icon.close(parent, size, colour)
  local h = holder(parent, size, "Close")
  local c = size / 2
  bar(h, size * 0.62, 1.6, c, c, 45, colour)
  bar(h, size * 0.62, 1.6, c, c, -45, colour)
  return h
end

function Icon.minus(parent, size, colour)
  local h = holder(parent, size, "Minus")
  bar(h, size * 0.62, 1.6, size / 2, size / 2, 0, colour)
  return h
end

function Icon.dot(parent, size, colour)
  local h = holder(parent, size, "Dot")
  bar(h, size * 0.34, size * 0.34, size / 2, size / 2, 0, colour)
  return h
end

function Icon.search(parent, size, colour)
  local h = holder(parent, size, "Search")
  local r = size * 0.30
  local ring = mk("Frame", {
    AnchorPoint = Vector2.new(0.5, 0.5),
    Position = UDim2.fromOffset(size * 0.44, size * 0.42),
    Size = UDim2.fromOffset(r * 2, r * 2),
    BackgroundTransparency = 1, Parent = h,
  })
  L.corner(999, ring)
  L.stroke(colour, 1.6, 0, ring)
  bar(h, size * 0.26, 1.6, size * 0.72, size * 0.72, 45, colour)
  return h
end

-- Three stacked bars of descending length. Reads as "list" / "menu" / "options".
function Icon.bars(parent, size, colour)
  local h = holder(parent, size, "Bars")
  bar(h, size * 0.62, 1.6, size * 0.5, size * 0.30, 0, colour)
  bar(h, size * 0.62, 1.6, size * 0.5, size * 0.50, 0, colour)
  bar(h, size * 0.40, 1.6, size * 0.4, size * 0.70, 0, colour)
  return h
end

function Icon.grip(parent, size, colour)
  local h = holder(parent, size, "Grip")
  for r = 0, 1 do
    for c = 0, 2 do
      bar(h, 2, 2, size * (0.36 + r * 0.28), size * (0.26 + c * 0.24), 0, colour)
    end
  end
  return h
end

-- A ring with a gap, used as the spinner. Rotating a gapped ring reads as motion
-- far better than a rotating solid, and needs no image.
function Icon.spinner(parent, size, colour)
  local h = holder(parent, size, "Spinner")
  local ring = mk("Frame", {
    Size = UDim2.fromScale(1, 1), BackgroundTransparency = 1, Parent = h,
  })
  L.corner(999, ring)
  local st = L.stroke(colour, 2, 0, ring)
  local grad = mk("UIGradient", {
    Transparency = NumberSequence.new({
      NumberSequenceKeypoint.new(0, 0),
      NumberSequenceKeypoint.new(0.55, 0.15),
      NumberSequenceKeypoint.new(1, 1),
    }),
    Parent = st,
  })
  return h, grad
end

-- ---------------------------------------------------------------- interaction

-- Adds a state layer and returns a controller. `hover` and `press` are the two
-- states every control shares; giving them one implementation is what makes the
-- whole framework feel like one product.
-- Puts `spot` exactly under the pointer, expressed in `frame`'s own coordinates.
--
-- The inset correction that used to live here was BACKWARDS, and it is now gone
-- entirely: `L.pointerIn` returns the cursor already in this frame's local,
-- pre-UIScale space. See the measurement in lm_00_core -- GetMouseLocation is
-- the inset-INCLUDED reading, so adding the inset to it (as this did) and then
-- subtracting an AbsolutePosition put the light 116 px below the pointer.
-- ONE FIXED SIZE CANNOT BE RIGHT FOR EVERY CONTROL, and this was 150 x 150 for
-- all of them. On a 26 px dock pill that is a wash of colour over the entire
-- button with no falloff visible anywhere -- there is no gradient left inside
-- the control, just a tinted pill. On a 520 px panel header it is a small dot
-- with a hard end to it. Neither reads as a light source.
--
-- The comment that used to sit on the ImageLabel said the glow was "wider than
-- the row is tall, so the falloff runs along the control". It was square. This
-- makes the comment true: the ellipse is sized from the control every time its
-- bounds change, tall enough to spill past the top and bottom edges (so the
-- falloff you see is horizontal, along the direction you actually move) and
-- never so wide that it stops being a highlight.
local function fitSpot(frame, spot, sc)
  local a = frame.AbsoluteSize
  if a.X < 1 or a.Y < 1 then return end
  local key = math.floor(a.X + 0.5) * 4096 + math.floor(a.Y + 0.5)
  if spot:GetAttribute("__fit") == key then return end
  spot:SetAttribute("__fit", key)
  local h = a.Y / math.max(sc, 0.01)              -- pre-UIScale local units
  local w = a.X / math.max(sc, 0.01)
  -- A POOL, NOT A WASH. The first pass at this scaled off the control and came
  -- out 185 x 119 on a 187 x 46 row -- a glow the size of the whole control,
  -- which is not a highlight, it is a second background. Sized to a little over
  -- the control's HEIGHT instead, so there is lit area and unlit area inside
  -- one row and the light has an edge you can actually see move.
  local gh = math.clamp(h * 1.25, 26, 84)
  local gw = math.clamp(gh * 1.9, 40, 150)
  spot.Size = UDim2.fromOffset(math.floor(gw), math.floor(gh))
end

-- TWO FRAMES OF LAG IS SMOOTH; A SPRING IS LOST.
--
-- The note that stood here said a cursor light has no business being animated,
-- and it was right about what it was describing: the position was going through
-- M.to -- a real spring, ~180 ms -- driven off MouseMoved, which fires less
-- often than the screen redraws. That light was permanently travelling to where
-- the pointer had just been, and between events it did not move at all.
--
-- This is a different quantity: a first-order approach evaluated EVERY frame,
-- with a time constant short enough to be smoothing rather than animation.
-- Worked out rather than eyeballed, at 60 fps (dt = 16.7 ms):
--
--   retention per frame  exp(-16.7/18) = 0.40    -- 60% of the error gone each frame
--   20 px step           7.9 -> 3.1 -> 1.2 -> 0.5 px   (settled in 4 frames, 67 ms)
--   steady-state lag     v * tau: 250 px/s -> 4.5 px, 800 px/s -> 14 px
--
-- The first draft used tau = 35 ms, where the error decays only 38% a frame and
-- a 26 px step needs nearly seven of them -- which is exactly the trailing the
-- note above complains about, just with a smaller constant. 18 ms removes the
-- per-frame jitter of raw pointer sampling and nothing else.
--
-- The distance is clamped too, so a hitch or a flick across the screen cannot
-- leave the light stranded: past MAX_LAG it stops interpolating and teleports.
-- 0.55 was loud enough to read as a coloured smear rather than as light on a
-- surface. At 0.74 the pool has an edge and the control underneath still shows
-- through it, which is the difference between lighting something and painting it.
local SPOT_REST = 0.74

local SPOT_TAU = 0.018
local SPOT_MAX_LAG = 14        -- local px; beyond this, snap rather than trail

function A.aimSpot(frame, spot, dt, h)
  if not (frame and spot and frame.Parent) then return end
  local sc = (L.Hub and L.Hub.window and L.Hub.window.scaleObj
              and L.Hub.window.scaleObj.Scale) or 1
  fitSpot(frame, spot, sc)
  local rel = L.pointerIn(frame, sc)
  local x, y = rel.X, rel.Y

  if h and dt and h.sx then
    local k = 1 - math.exp(-dt / SPOT_TAU)
    local nx = h.sx + (x - h.sx) * k
    local ny = h.sy + (y - h.sy) * k
    local dx, dy = x - nx, y - ny
    if (dx * dx + dy * dy) > (SPOT_MAX_LAG * SPOT_MAX_LAG) then
      nx, ny = x, y
    end
    h.sx, h.sy = nx, ny
    x, y = nx, ny
  elseif h then
    h.sx, h.sy = x, y                    -- first frame of a hover: no trail
  end
  spot.Position = UDim2.fromOffset(x, y)

  -- THE BORDER LIGHTS ON THE SIDE THE POINTER IS ON.
  --
  -- This is the part that stops it reading as a generic blob. A rim whose
  -- bright arc tracks the cursor is a surface catching a moving light; a rim
  -- that is always brightest at the top is a border with a gradient on it.
  -- Costs one Rotation write a frame.
  --
  -- A UIGradient at Rotation R runs along (cos R, sin R) with keypoint 0 on the
  -- far side, so putting the bright key (0.00) under the pointer at bearing
  -- theta means R = theta - 180.
  if h and h.rim then
    local a = frame.AbsoluteSize
    local cx, cy = a.X / (2 * sc), a.Y / (2 * sc)
    local vx, vy = x - cx, y - cy
    if (vx * vx + vy * vy) > 4 then
      h.rim.Rotation = math.deg(math.atan2(vy, vx)) - 180
    end
  end
end

-- ---------------------------------------------------------------- selection
--
-- ONE ANSWER TO "WHICH ONE IS CHOSEN", USED BY EVERY LIST.
--
-- The dropdown said it with a 0.86-transparent wash and accent text -- 14% of
-- an already dark colour, on a row 26 px tall. Against a busy page that is not
-- a state, it is a suggestion, and it looked broken rather than subtle. The
-- side panel and the command centre each had a third and fourth answer.
--
-- Three signals, because one is never enough on a dark surface: a fill you can
-- actually see, the accent on the text, and a bar down the leading edge that
-- has no other meaning anywhere in the interface. The bar is what makes it
-- unambiguous at a glance -- fills read as hover, bars read as chosen.
A.SEL_FILL  = 0.80          -- transparency of the selected row's wash
A.SEL_BAR_W = 3

function A.selectMark(frame)
  local bar = frame:FindFirstChild("SelBar")
  if bar then return bar end
  bar = mk("Frame", {
    AnchorPoint = Vector2.new(0, 0.5), Position = UDim2.new(0, 0, 0.5, 0),
    Size = UDim2.new(0, A.SEL_BAR_W, 0, 0),
    BackgroundColor3 = T.c.accent, BorderSizePixel = 0,
    BackgroundTransparency = 0, ZIndex = (frame.ZIndex or 1) + 1,
    Name = "SelBar", Parent = frame,
  })
  L.corner(999, bar)
  return bar
end

-- `on` selects, and the label is optional for callers that colour their own.
function A.selectRow(frame, label, on, token)
  if not frame then return end
  token = token or "fast"
  local bar = A.selectMark(frame)
  M.to(frame, "BackgroundTransparency", on and A.SEL_FILL or 1, token)
  M.to(bar, "Size", UDim2.new(0, A.SEL_BAR_W, 0, on and 14 or 0), token)
  M.to(bar, "BackgroundTransparency", on and 0 or 1, token)
  if label then
    M.to(label, "TextColor3", on and T.c.accent or T.c.textDim, token)
  end
end

-- ---------------------------------------------------------------- chrome
--
-- A TRAVELLING HIGHLIGHT, BUILT BY SAMPLING RATHER THAN BY OFFSET.
--
-- The page titles sweep a UIGradient by animating its Offset from -1 to +1. A
-- UIGradient only defines colour over [0, 1] and CLAMPS outside it, so for a
-- large part of that cycle the bright band is not on the letters at all:
--
--   bright key sits at p = 0.34, appears at object x = 0.34 + offset
--   so it is inside the glyphs only for offset in [-0.34, 0.66]
--   -- one unit out of the two the sweep travels. Half the cycle is flat.
--
-- Which is why the titles spend as long looking like dark grey text as they do
-- looking like metal. Widening the range does not help; the highlight has to
-- LEAVE somewhere, and with a single gradient there is nowhere for it to go.
--
-- So the offset is abandoned and the gradient's colours are resampled instead.
-- The pattern below is defined in a wrapped space, sampled at fixed positions
-- across whatever slice of it a given label occupies, and rebuilt as the phase
-- advances. Nothing clamps, because the keys always span exactly [0, 1] -- and
-- because the pattern wraps, the highlight that leaves the right edge is the
-- same one arriving at the left. It never goes flat.
--
-- The slice is what lets a word split across several labels share ONE sweep:
-- give glyph i the slice [i/n, (i+1)/n] and the highlight crosses the word,
-- rather than five letters each flashing on their own.
A.CHROME = {
  __default = { rot =   8, speed = 0.16, warm = Color3.fromRGB(196, 182, 140) },
  Movement  = { rot =  22, speed = 0.30, warm = Color3.fromRGB(150, 196, 214) },
  Combat    = { rot =   0, speed = 0.11, warm = Color3.fromRGB(214, 150, 140), hard = true },
  Visuals   = { rot = -16, speed = 0.20, warm = Color3.fromRGB(178, 158, 214), prism = true },
  -- The loading screen had its own richer "Boot" preset here. It read as a
  -- different product from the page titles, so it uses __default like they do
  -- -- one preset, and the two cannot drift apart.
}

local STEEL  = Color3.fromRGB(120, 124, 132)
local BRIGHT = Color3.fromRGB(248, 249, 252)
local DARK   = Color3.fromRGB( 78,  82,  90)

-- The pattern is a wrapped ring: position 1 is the same place as position 0, so
-- the first and last colour MUST match or the seam shows as a dark bar.
function A.chromePattern(cfg)
  cfg = cfg or A.CHROME.__default
  if cfg.hard then
    return { {0.00, STEEL}, {0.38, STEEL}, {0.40, BRIGHT}, {0.52, cfg.warm},
             {0.54, DARK},  {0.72, STEEL}, {1.00, STEEL} }
  elseif cfg.prism then
    return { {0.00, STEEL}, {0.18, Color3.fromRGB(150, 196, 214)},
             {0.36, BRIGHT}, {0.50, cfg.warm},
             {0.64, Color3.fromRGB(214, 170, 150)}, {0.82, DARK},
             {1.00, STEEL} }
  end
  return { {0.00, STEEL}, {0.26, BRIGHT}, {0.38, cfg.warm}, {0.54, DARK},
           {0.72, Color3.fromRGB(236, 238, 242)}, {1.00, STEEL} }
end

local function patternAt(pat, t)
  t = t % 1
  for i = 1, #pat - 1 do
    local a, b = pat[i], pat[i + 1]
    if t >= a[1] and t <= b[1] then
      local span = b[1] - a[1]
      return a[2]:Lerp(b[2], span > 0 and (t - a[1]) / span or 0)
    end
  end
  return pat[#pat][2]
end

-- 20 is the ColorSequence keypoint ceiling, and a hard-cut preset wants every
-- one of them -- sampled coarsely the cut turns into a ramp.
local CHROME_SAMPLES = 20

function A.chromeSeq(pat, phase, a, b)
  a, b = a or 0, b or 1
  local keys = {}
  for i = 0, CHROME_SAMPLES - 1 do
    local x = i / (CHROME_SAMPLES - 1)
    keys[i + 1] = ColorSequenceKeypoint.new(x, patternAt(pat, (a + (b - a) * x) - phase))
  end
  return ColorSequence.new(keys)
end

-- ---------------------------------------------------------------- fading
--
-- STROKES ARE PART OF A FADE, AND LEAVING THEM OUT IS WHY THINGS LEAVE A LINE.
--
-- A panel that fades by walking BackgroundTransparency and TextTransparency
-- looks finished and is not: its UIStroke is still sitting at its resting value,
-- so a 1 px outline stays lit over whatever is underneath. On the tooltip that
-- reads as a dark line hanging in the air a beat after the text has gone --
-- reported as "a delayed dark string" and visible in the recordings.
--
-- One map, one walk, used everywhere something fades out as a unit.
A.FADE_PROP = {
  Frame = "BackgroundTransparency",
  ScrollingFrame = "BackgroundTransparency",
  TextLabel = "TextTransparency",
  TextButton = "TextTransparency",
  TextBox = "TextTransparency",
  ImageLabel = "ImageTransparency",
  ImageButton = "ImageTransparency",
  CanvasGroup = "GroupTransparency",
  UIStroke = "Transparency",
}

-- GROUPTRANSPARENCY DOES NOT COVER THE GROUP'S OWN UISTROKE.
--
-- This is the bug behind "the dark outline is still there and it lags". A
-- CanvasGroup composites its CHILDREN and fades that composite; a UIStroke
-- parented to the CanvasGroup itself is not one of those children, so it keeps
-- drawing at its own transparency for the entire fade. Measured on the live
-- window, held mid-fade:
--
--   root.GroupTransparency = 0.92   -- contents faded to almost nothing
--   root's UIStroke        = 0.30   -- a solid rounded outline, full strength
--
-- Which is a bright 1 px rectangle around an empty hole, drawn over the game,
-- for the whole duration of every hide -- and then snapped away by Visible =
-- false at the end, which is what reads as the delay.
--
-- lm_05_window even asserted the opposite in a comment: "Body, wash, stroke,
-- icons and text all leave through GroupTransparency." Everything in that list
-- is true except the stroke.
--
-- Use this anywhere a CanvasGroup is faded by hand.
function A.groupTo(group, alpha, token)
  if not group then return end
  M.to(group, "GroupTransparency", alpha, token)
  for _, d in ipairs(group:GetChildren()) do
    if d:IsA("UIStroke") then
      local rest = L.strokeRest(d)
      M.to(d, "Transparency", rest + (1 - rest) * alpha, token)
    end
  end
end

-- Same, without animating: for the set-then-reveal pattern.
function A.groupSet(group, alpha)
  if not group then return end
  M.set(group, "GroupTransparency", alpha)
  for _, d in ipairs(group:GetChildren()) do
    if d:IsA("UIStroke") then
      local rest = L.strokeRest(d)
      M.set(d, "Transparency", rest + (1 - rest) * alpha)
    end
  end
end

-- Rest values are captured ONCE and cached on the instance. Reading them again
-- mid-fade records "invisible" as the resting state and the thing never comes
-- back -- the same trap the row cascade and the dock pill both hit.
function A.fadeSet(root)
  if not root then return {} end
  local cached = root:GetAttribute("__fadeCached")
  if cached and A._fadeSets and A._fadeSets[root] then return A._fadeSets[root] end
  local parts = {}
  local function add(o)
    local p = A.FADE_PROP[o.ClassName]
    if not p then return end
    local ok, v = pcall(function() return o[p] end)
    if ok and type(v) == "number" and v < 1 then parts[#parts + 1] = { o, p, v } end
  end
  add(root)
  for _, d in ipairs(root:GetDescendants()) do add(d) end
  A._fadeSets = A._fadeSets or setmetatable({}, { __mode = "k" })
  A._fadeSets[root] = parts
  pcall(function() root:SetAttribute("__fadeCached", true) end)
  return parts
end

-- k = 0 is fully at rest, k = 1 is fully gone.
function A.fadeTo(root, k, token)
  for _, e in ipairs(A.fadeSet(root)) do
    if e[1].Parent then
      M.to(e[1], e[2], e[3] + (1 - e[3]) * k, token or "fast")
    end
  end
end

-- The one control currently under the pointer, driven by the shared loop below.
A._hover = nil
L.hold(L.RunService.RenderStepped:Connect(function(dt)
  local h = A._hover
  if h then A.aimSpot(h.frame, h.spot, dt, h) end
end))

function A.interactive(frame, opts)
  opts = opts or {}
  local radius = opts.radius or T.r.md

  -- THE HIGHLIGHT MUST BE THE SAME SHAPE AS THE THING IT HIGHLIGHTS, and the
  -- FRAME'S OWN CORNER IS THE SOURCE OF TRUTH -- not the radius passed in.
  --
  -- Everything added below is rounded: the hover wash, the sweep, the spotlight
  -- host. The press/focus edge is a UIStroke, and a UIStroke follows the corner
  -- of the frame it is parented to. Two ways that went wrong:
  --
  --   NO CORNER AT ALL. Controls built on A.surface carry one, but anything that
  --   did not -- most visibly the sidebar tabs -- got a SQUARE outline drawn
  --   around a rounded fill, sitting outside the frame in Border mode, so it read
  --   as a slightly larger box of the wrong shape.
  --
  --   A DIFFERENT CORNER. A caller passing a radius that disagrees with the one
  --   already on the frame produced a highlight that did not follow the edge it
  --   was highlighting. Trusting the argument here would leave that mismatch in
  --   place, so the frame wins and the argument is only a default.
  --
  -- Radii are read back as PIXELS. L.corner multiplies by the user's radius
  -- setting, so feeding a value that has already been scaled back through it
  -- would scale it twice.
  local existingCorner = frame:FindFirstChildOfClass("UICorner")
  if not existingCorner then
    existingCorner = L.corner(radius, frame)
  end
  local radiusPx = existingCorner.CornerRadius.Offset
  local function matchCorner(parent)
    return mk("UICorner", { CornerRadius = UDim.new(0, radiusPx), Parent = parent })
  end

  local layer = mk("Frame", {
    Size = UDim2.fromScale(1, 1),
    BackgroundColor3 = opts.layerColour or Color3.new(1, 1, 1),
    BackgroundTransparency = 1,
    BorderSizePixel = 0,
    ZIndex = (frame.ZIndex or 1) + 4,
    Name = "State",
    Parent = frame,
  })
  matchCorner(layer)

  -- ---- the fill rises from the bottom ---------------------------------
  --
  -- A flat tint over the whole control says "hovered" and nothing else. Light
  -- pooling at the base of a surface says the surface has a bottom -- which is
  -- the difference between a coloured rectangle and something that looks lit.
  -- Taken from the reference clip: the fill is strongest at the floor of the
  -- pill and gone by two thirds up, so the top edge stays dark for the rim to
  -- read against.
  local fillGrad = mk("UIGradient", {
    Rotation = 90,
    Transparency = NumberSequence.new({
      NumberSequenceKeypoint.new(0.00, 1.00),
      NumberSequenceKeypoint.new(0.34, 0.92),
      NumberSequenceKeypoint.new(0.72, 0.42),
      NumberSequenceKeypoint.new(1.00, 0.10),
    }),
    Parent = layer,
  })

  local btn = mk("TextButton", {
    Size = UDim2.fromScale(1, 1),
    BackgroundTransparency = 1,
    Text = "", AutoButtonColor = false,
    ZIndex = (frame.ZIndex or 1) + 5,
    Name = "Hit",
    Parent = frame,
  })

  -- ---- specular sweep -------------------------------------------------------
  --
  -- A HIGHLIGHT THAT TRAVELS, not a panel that lights up. Every Roblox hub
  -- brightens a row on hover, which communicates "the cursor is here" and
  -- nothing else. A band of light crossing the surface says the surface is made
  local sweepGrad
  local sweepOn = opts.sweep ~= false
                  and not (L.Cfg and L.Cfg.data.sweep == false)
  if sweepOn then
    local sweep = mk("Frame", {
      Size = UDim2.fromScale(1, 1),
      BackgroundColor3 = Color3.new(1, 1, 1),
      BorderSizePixel = 0,
      ZIndex = (frame.ZIndex or 1) + 3,
      Name = "Sweep", Parent = frame,
    })
    matchCorner(sweep)
    sweepGrad = mk("UIGradient", {
      Rotation = 16,
      Transparency = NumberSequence.new({
        NumberSequenceKeypoint.new(0.00, 1),
        NumberSequenceKeypoint.new(0.40, 1),
        NumberSequenceKeypoint.new(0.50, 0.88),
        NumberSequenceKeypoint.new(0.60, 1),
        NumberSequenceKeypoint.new(1.00, 1),
      }),
      Offset = Vector2.new(-1.2, 0),
      Parent = sweep,
    })
  end

  -- ---- cursor spotlight -----------------------------------------------------
  --
  -- A GLOW THAT FOLLOWS THE POINTER, not one that lights the whole control. The
  -- reference clips both do the same thing: a soft radial bloom sits under the
  -- cursor and travels with it along the button, so the surface reads as lit
  -- from a moving source rather than as a state that toggled on.
  --
  -- Clipped by its own host rather than by `frame`: turning on ClipsDescendants
  -- on the control itself would also crop anything a caller has deliberately
  -- hung outside it, and several rows do exactly that.
  --
  -- A CANVASGROUP, BECAUSE ClipsDescendants CLIPS TO A RECTANGLE.
  --
  -- This was a Frame with ClipsDescendants and a matched UICorner, on the
  -- assumption that the corner rounds the clip region. It does not, and that is
  -- the source of the hard edges: bring the pointer near a rounded control and
  -- the glow stopped at the host's square bounds, drawing a straight edge
  -- across a corner that is meant to be curved.
  --
  -- Measured side by side on this client before changing it:
  --
  --   Frame + UICorner + ClipsDescendants   ->  SQUARE corners
  --   CanvasGroup + UICorner                ->  rounded
  --   oversized child in Frame + Clips      ->  square corner, the exact artifact
  --
  -- A CanvasGroup composites its children and THEN applies the corner, so the
  -- clip follows the curve. The usual objection to CanvasGroups -- that they
  -- resample glyphs and soften text -- does not apply here: this subtree holds
  -- one radial image and no type at all.
  local spot, spotHost
  local spotOn = opts.spot ~= false
                 and not (L.Cfg and L.Cfg.data.spot == false)
                 and A.img.glow ~= nil
  if spotOn then
    spotHost = mk("CanvasGroup", {
      Size = UDim2.fromScale(1, 1), BackgroundTransparency = 1,
      GroupTransparency = 0, ZIndex = (frame.ZIndex or 1) + 2,
      Name = "SpotHost", Parent = frame,
    })
    matchCorner(spotHost)
    spot = mk("ImageLabel", {
      AnchorPoint = Vector2.new(0.5, 0.5),
      Position = UDim2.fromScale(0.5, 0.5),
      -- a placeholder only: fitSpot resizes this from the control's own bounds
      -- the first frame it is hovered, and again whenever those bounds change
      Size = UDim2.fromOffset(opts.spotSize or 150, opts.spotSize or 150),
      BackgroundTransparency = 1,
      Image = A.img.glow,
      ImageColor3 = opts.spotColour or T.c.accent,
      ImageTransparency = 1,
      ZIndex = (frame.ZIndex or 1) + 2,
      Name = "Spot", Parent = spotHost,
    })
  end

  local state = { hovered = false, pressed = false, enabled = true }

  -- A GRADIENT MULTIPLIES, SO ADDING ONE MADE THE HOVER DIMMER.
  --
  -- The fill gradient above does not add light to the wash, it scales it. At the
  -- old flat 0.94 the arithmetic works out as:
  --
  --   opacity           = 1 - 0.94                       = 0.060  (was uniform)
  --   with the gradient = 0.060 * (1 - 0.10) at the base = 0.054
  --                       0.060 * (1 - 1.00) at the top  = 0.000
  --
  -- So the "brighter" bottom edge was fractionally DARKER than the flat tint it
  -- replaced, and the top half lost its wash entirely -- a net loss of hover
  -- feedback, which is the opposite of the point. These are the levels that put
  -- the base meaningfully above the old flat value while still letting the top
  -- go dark for the rim to read against:
  --
  --   base 1 - 0.88 = 0.120, times 0.90 = 0.108   -- 1.8x the old wash
  --   top                                = 0.000   -- rim has something to sit on
  local HOVER = opts.hoverAlpha or 0.88
  local PRESS = opts.pressAlpha or 0.80

  -- PRESS FEEDBACK IS A STROKE WHEREVER A LAYOUT IS WATCHING.
  --
  -- The obvious move is to shrink the control slightly on press. Re-measured on
  -- a live client before touching this, because "a scale would break the layout"
  -- is the kind of claim that ages badly:
  --
  --   4 rows of 40 px in a UIListLayout, UIScale 0.90 on row 2
  --     row 2 AbsoluteSize.Y   40 -> 36
  --     rows 3 and 4 shift     -4 px each
  --
  -- So it is true, and it is true for any scale: at 0.985 the shift is only
  -- ~0.6 px, but it lands on every row below AND reverses on release, so a list
  -- twitches each time you click anything in it. An accent edge that flares and
  -- fades confirms the press without touching layout at all.
  --
  -- But most of what the reference clip shows are BUTTONS, not rows -- dock
  -- pills, header actions, the command centre -- and those have no layout to
  -- disturb. Those get the dip, because forty milliseconds of movement is most
  -- of what makes a button feel physical. The test is simply whether anything
  -- is currently positioning this frame for us.
  local edge = mk("UIStroke", {
    Color = T.c.accent, Thickness = 1.4, Transparency = 1,
    ApplyStrokeMode = Enum.ApplyStrokeMode.Border, Parent = frame,
  })

  -- Is something else positioning this frame? Two effects need the answer -- the
  -- press dip, which would shove siblings, and the bloom, which would spill onto
  -- them -- so it is worked out once here rather than in each.
  local governedBy = frame.Parent and (frame.Parent:FindFirstChildWhichIsA("UIListLayout")
                   or frame.Parent:FindFirstChildWhichIsA("UIGridLayout")
                   or frame.Parent:FindFirstChildWhichIsA("UITableLayout")) or nil
  local governed = governedBy ~= nil

  -- A UIScale changes the MEASURED size -- that is the whole reason a governed
  -- row reflows -- so scale an INNER node and leave the outer frame alone. The
  -- layout keeps measuring a frame that never changes; the content dips inside
  -- it. Two frames cannot host it: one that sizes itself to its children (a
  -- fromScale child contributes nothing to AutomaticSize, so the row collapses)
  -- and one running its own layout (that layout would be left positioning a
  -- single object). Both keep the stroke-only press they have today.
  local dip
  local pressScale
  if opts.dip ~= false then
    if not governed then
      pressScale = mk("UIScale", { Scale = 1, Parent = frame })
    elseif frame.AutomaticSize == Enum.AutomaticSize.None
       and not frame:FindFirstChildWhichIsA("UILayout") then
      dip = mk("Frame", {
        Size = UDim2.fromScale(1, 1), BackgroundTransparency = 1,
        BorderSizePixel = 0, ZIndex = frame.ZIndex or 1,
        Name = "Dip", Parent = frame,
      })
      pressScale = mk("UIScale", { Scale = 1, Parent = dip })
    end
  end

  -- ---- rim light and bloom --------------------------------------------
  --
  -- THE RIM IS WHAT SELLS IT. In the reference the pill has a bright thin arc
  -- along its TOP edge that fades away by the sides -- the specular you get when
  -- a light sits above a rounded, slightly glossy surface. A stroke of uniform
  -- brightness reads as a border; the same stroke with a vertical gradient
  -- reads as a lit edge, and it costs one UIGradient.
  --
  -- The bloom is a sibling INSIDE the frame rather than outside it, so a caller
  -- that reparents or destroys the control takes the glow with it. Oversized on
  -- purpose: it is meant to spill past the edge.
  local bloom
  local rimGrad = mk("UIGradient", {
    Rotation = 90,
    Transparency = NumberSequence.new({
      NumberSequenceKeypoint.new(0.00, 0.00),
      NumberSequenceKeypoint.new(0.30, 0.35),
      NumberSequenceKeypoint.new(1.00, 0.85),
    }),
    Parent = edge,
  })
  if A.img and A.img.glow then
    -- SPILLING IS RIGHT FOR A BUTTON AND WRONG FOR A ROW.
    --
    -- 1.9 of the host's height is a deliberate overshoot on something standing
    -- on its own -- a dock pill, a header action -- where there is nothing
    -- beside it to light up. Inside a list it is a leak. Measured on the nav
    -- rail: a 300x73 row grew a 403x139 bloom, +33 px past each edge into a
    -- 4 px gap, so hovering one row lit 29 px of the row above AND the row
    -- below. On a recording it reads as the glow following the cursor around
    -- the whole rail rather than sitting under it.
    --
    -- So the vertical overshoot is spent only where there is room for it: half
    -- the layout's own gap, and no more. The horizontal 1.34 is kept either way
    -- -- a vertical list has nothing to its left or right to contaminate.
    local yScale = 1.9
    if governed then
      local gap = 0
      pcall(function() gap = governedBy.Padding.Offset end)
      local h = frame.AbsoluteSize.Y
      local sc = (L.Hub and L.Hub.window and L.Hub.window.scaleObj
                  and L.Hub.window.scaleObj.Scale) or 1
      h = h / math.max(sc, 0.01)
      yScale = (h > 1) and math.clamp(1 + (gap * 0.5) / h, 1, 1.9) or 1
    end
    bloom = mk("ImageLabel", {
      AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, 0.5),
      Size = UDim2.fromScale(1.34, yScale), BackgroundTransparency = 1,
      Image = A.img.glow, ImageColor3 = opts.spotColour or T.c.accent,
      ImageTransparency = 1, ZIndex = math.max(1, (frame.ZIndex or 1) - 1),
      Name = "Bloom", Parent = frame,
    })
  end

  local function apply()
    local a = 1
    if state.enabled then
      if state.pressed then a = PRESS
      elseif state.hovered then a = HOVER end
    end
    M.to(layer, "BackgroundTransparency", a, "instant")
    -- these are the values at the TOP of the stroke; the rim gradient takes the
    -- sides and the base down from here, so a flat 0.78 read as almost nothing
    -- once it was in place
    M.to(edge, "Transparency",
      (state.enabled and state.pressed) and 0.20
      or (state.enabled and state.hovered) and 0.68 or 1, "instant")
    if spot then
      -- the light flares under the finger on press, then settles back
      local base = opts.spotAlpha or SPOT_REST
      M.to(spot, "ImageTransparency",
        (state.enabled and state.pressed) and math.max(0, base - 0.20)
        or (state.enabled and state.hovered) and base or 1, "fast")
    end

    local live = state.enabled and (state.hovered or state.pressed)
    if bloom then
      M.to(bloom, "ImageTransparency",
        state.pressed and 0.68 or (live and 0.82 or 1), "fast")
    end
    if rimGrad then
      -- the rim brightens toward uniform on press: a lit edge tipping to face
      -- the light, rather than a second colour appearing from nowhere
      M.to(rimGrad, "Offset", Vector2.new(0, state.pressed and 0.12 or 0), "fast")
    end
    if pressScale then
      M.to(pressScale, "Scale", state.pressed and 0.978 or 1, "fast")
    end
    if opts.onState then opts.onState(state) end
  end

  -- CENTRED ON THE POINTER, EXACTLY. Two different offsets have to cancel or the
  -- light sits away from the cursor instead of under it, and the first version
  -- got both wrong:
  --
  --   INSET.  Both directions of this were asserted in this file at different
  --           times and the sign was wrong. It is now measured once in
  --           lm_00_core and applied by L.pointerIn; do not re-derive it here.
  --   SCALE.  AbsolutePosition is real pixels, a UDim2 offset is pre-UIScale.
  --
  -- Read from GetMouseLocation rather than from MouseMoved's arguments, so there
  -- is one source of truth for where the pointer is and one correction applied
  -- to it. With AnchorPoint at 0.5 the bloom then centres on the cursor exactly.
  -- ONE FOLLOWER FOR THE WHOLE HUB, NOT ONE PER CONTROL.
  --
  -- Only one thing can be under the pointer at a time, so a RenderStepped per
  -- interactive control means ~60 connections firing every frame to have 59 of
  -- them return immediately. The hovered control publishes itself to A._hover
  -- and a single shared loop drives it -- which also means the follower can be
  -- pointed at a control from outside and its accuracy measured, instead of
  -- being reachable only by a real hand on a real mouse.
  -- SET, NOT TWEENED, AND EVERY FRAME.
  --
  -- The arithmetic below was already correct -- verified at (0, -1) px -- and the
  -- glow still did not sit on the cursor, because the position was going through
  -- M.to. That is a spring: it EASES toward the target, so the light was always
  -- travelling to where the pointer had just been. Worse, it was driven off
  -- MouseMoved, which fires less often than the screen redraws, so between
  -- events it did not move at all. A cursor light has no business being
  -- animated -- it is not going anywhere the pointer is not.
  --
  -- Both corrections now live in L.pointerIn, measured rather than reasoned
  -- about. The claim that once stood here -- that GetMouseLocation excludes the
  -- topbar inset -- was the bug, not the fix.
  local function moveSpot()
    if spot then A.aimSpot(frame, spot) end   -- no dt: snaps, for the enter frame
  end

  btn.MouseEnter:Connect(function()
    state.hovered = true
    -- fired on ENTER only, never held: a highlight that loops while the pointer
    -- rests is a busy row, and thirty of them is a page that will not sit still
    if sweepGrad and state.enabled then
      M.set(sweepGrad, "Offset", Vector2.new(-1.2, 0))
      M.to(sweepGrad, "Offset", Vector2.new(1.2, 0), "slow")
    end
    if spot and state.enabled then
      -- placed where the pointer entered BEFORE it is faded up, so the light
      -- never appears mid-flight from wherever it was last hovered
      moveSpot()
      M.to(spot, "ImageTransparency", opts.spotAlpha or SPOT_REST, "base")
      A._hover = { frame = frame, spot = spot, rim = rimGrad }
    end
    apply()
  end)
  btn.MouseLeave:Connect(function()
    state.hovered, state.pressed = false, false
    -- only surrender the follower if it is still ours: entering the next control
    -- fires before this leaves, and clearing unconditionally would kill the glow
    -- that just took over
    if A._hover and A._hover.spot == spot then A._hover = nil end
    if spot then M.to(spot, "ImageTransparency", 1, "base") end
    apply()
  end)
  btn.MouseButton1Down:Connect(function()
    if not state.enabled then return end
    state.pressed = true apply()
  end)
  btn.MouseButton1Up:Connect(function() state.pressed = false apply() end)
  btn.Activated:Connect(function()
    if not state.enabled then return end
    if opts.onClick then L.try("atoms.click", opts.onClick) end
  end)

  -- ---- keep our overlays off the frame's own buttons -----------------------
  --
  -- Under ZIndexBehavior.Sibling the click is decided at the TOP level of this
  -- frame, not by the raw ZIndex under the cursor: every descendant rides in
  -- its parent's slot. So a button nested in a content frame loses to the Hit
  -- overlay above it no matter how high that button's own ZIndex is, and the
  -- container silently swallows the click. Lift any content branch that
  -- carries buttons of its own clear of the overlays. Transparent, inactive
  -- frames do not take input, so the container stays clickable in the gaps.
  local guard = (frame.ZIndex or 1) + 6
  -- FindFirstChildWhichIsA searches DESCENDANTS, so a child that is itself the
  -- input was missed: the slider's click-to-type readout is a childless
  -- TextButton and its entry -- like every input row's field -- is a TextBox.
  -- Both sat under the overlay and stopped responding.
  local function takesInput(o)
    return o:IsA("GuiButton") or o:IsA("TextBox")
       or o:FindFirstChildWhichIsA("GuiButton", true) ~= nil
       or o:FindFirstChildWhichIsA("TextBox", true) ~= nil
  end
  local lifted = false
  for _, child in ipairs(frame:GetChildren()) do
    if child:IsA("GuiObject") and child ~= layer and child ~= btn
       and child ~= dip and child ~= bloom
       and child.Name ~= "Sweep" and child.Name ~= "SpotHost" then
      if child.ZIndex < guard and takesInput(child) then
        child.ZIndex = guard
        lifted = true
      end
      -- the dip host takes the content; the overlays and the bloom stay put
      if dip then child.Parent = dip end
    end
  end
  -- A branch lifted INSIDE the host still rides in the host's slot, so the lift
  -- has to reach the host or the overlay goes straight back to swallowing it.
  if dip and lifted then dip.ZIndex = guard end

  return {
    button = btn, layer = layer, edge = edge, state = state,
    setEnabled = function(v)
      state.enabled = v and true or false
      apply()
    end,
  }
end

-- ---------------------------------------------------------------- tooltips
--
-- A LABEL CUT SHORT IS A PROMISE THE INTERFACE BROKE. Truncating is the right
do
  local tipGui, tipFrame, tipLbl, tipTitle
  local DWELL = 0.35            -- do not flash at every label swept past
  local shownFor, hoverSince, hovered = nil, 0, nil

  local function ensure()
    if tipFrame and tipFrame.Parent then return end
    tipGui = mk("ScreenGui", {
      Name = "LumenTip", ResetOnSpawn = false, IgnoreGuiInset = true,
      ZIndexBehavior = Enum.ZIndexBehavior.Sibling, DisplayOrder = 60,
    })
    tipGui.Parent = L.host()
    L.own(tipGui)
    -- BUILT AT ITS RESTING VALUES, then faded out and hidden.
    --
    -- A.fadeSet captures rest ONCE, on first use, and ignores anything already
    -- sitting at full transparency. Building this card invisible and letting the
    -- first show() capture it therefore recorded "gone" as the resting state for
    -- every text layer in it -- the card would open with its stroke and its
    -- background and no words inside. Build it lit, snapshot it, then put it
    -- away.
    -- NO OUTLINE ON THE TOOLTIP. Asked for directly, and it was the right call.
    --
    -- A 1 px dark border is the single worst thing to fade. A filled background
    -- reads as gone by roughly 0.6 transparency; a thin dark line against a
    -- bright game world is still plainly a line at 0.85. So the card dissolves
    -- and leaves its own edge hanging in the air after it -- and that happens
    -- even though the stroke WAS in the fade set, on the same clock, as of P1.
    -- There is no timing fix available: the outline itself is the problem.
    --
    -- The card does not need one. It is a near-black panel drawn over whatever
    -- the game is rendering, and a soft shadow separates it far better than a
    -- border does -- while fading honestly, because an image's alpha is spread
    -- over area instead of concentrated in a hairline.
    --
    -- STRUCTURE, and it matters: a child ALWAYS draws above its parent's own
    -- background, so a shadow parented to the card would sit on top of it as a
    -- dark smear. The outer frame is therefore an empty container, and the
    -- shadow and the card are siblings inside it.
    tipFrame = mk("Frame", {
      BackgroundTransparency = 1, BorderSizePixel = 0,
      Size = UDim2.fromOffset(10, 24),
      Name = "Tip", Parent = tipGui,
    })
    mk("ImageLabel", {
      AnchorPoint = Vector2.new(0.5, 0.5),
      Position = UDim2.new(0.5, 0, 0.5, 4),
      Size = UDim2.new(1, 34, 1, 30),
      BackgroundTransparency = 1,
      Image = A.img.glow, ImageColor3 = Color3.new(0, 0, 0),
      ImageTransparency = 0.34, ZIndex = 1,
      Name = "TipShadow", Parent = tipFrame,
    })
    local card = mk("Frame", {
      Size = UDim2.fromScale(1, 1),
      BackgroundColor3 = T.c.overlay, BackgroundTransparency = 0,
      BorderSizePixel = 0, ZIndex = 2,
      Name = "TipCard", Parent = tipFrame,
    })
    L.corner(T.r.sm, card)
    tipTitle = A.text({
      Text = "", font = T.font.medium, size = T.size.micro, colour = T.c.text,
      align = Enum.TextXAlignment.Left, valign = Enum.TextYAlignment.Top,
      Size = UDim2.new(1, -20, 0, 14), ZIndex = 3,
      Position = UDim2.fromOffset(10, 8), tip = false, Parent = card,
    })
    tipLbl = A.text({
      Text = "", font = T.font.body, size = T.size.micro, colour = T.c.textDim,
      align = Enum.TextXAlignment.Left, valign = Enum.TextYAlignment.Top,
      Size = UDim2.new(1, -20, 0, 14), ZIndex = 3,
      Position = UDim2.fromOffset(10, 8), tip = false, Parent = card,
    })
    A.fadeSet(tipFrame)                -- rest snapshot, while it is still lit
    A.fadeTo(tipFrame, 1, "instant")
    tipFrame.Visible = false
  end

  -- TEXTBOUNDS IS THE WRONG PROPERTY, AND MEASURED IT IS EXACTLY BACKWARDS. On a
  -- label with TextTruncate.AtEnd, TextBounds reports the width of what was
  -- actually DRAWN -- which is by definition never wider than the box -- so
  -- `TextBounds.X > AbsoluteSize.X` cannot be true even once. A row reading
  -- "the game rewrote WalkSpeed 47 times in the l..." measured TextBounds 459
  -- inside a 494 box while its full string needs 697. The untruncated width has
  -- to be asked for separately, and TextService is the only thing that knows it.
  local TextService = game:GetService("TextService")
  local function truncated(l)
    if l.Text == "" or l.AbsoluteSize.X < 8 then return false end
    local ok, sz = pcall(function()
      return TextService:GetTextSize(l.Text, l.TextSize, l.Font,
                                     Vector2.new(9999, 100))
    end)
    return (ok and sz and sz.X > l.AbsoluteSize.X + 0.5) and true or false
  end

  -- A RECTANGLE TEST ALONE ASKS "WHERE IS IT", NEVER "CAN YOU SEE IT".
  --
  -- This is the tooltip explaining something that is not on your screen. Every
  -- registered label was tested by its AbsolutePosition and nothing else, and
  -- AbsolutePosition is perfectly real for a control on a tab you are not
  -- looking at -- pages are hidden by fading their CanvasGroup, NOT by setting
  -- Visible = false, so `l.Visible` is true and `l.TextTransparency` is still 0
  -- on every page at once. Eleven pages of controls were all live hit targets,
  -- stacked on the same coordinates.
  --
  -- Which is exactly what the recording shows: "Heavy rig showed 0 adjusted
  -- studs locally -- trying Teleport (clean)" -- a fling log line off the
  -- Activity page -- floating over the Config page under a pointer that had
  -- never been near it.
  --
  -- Three things make a label unreachable, and the rect test knows none of them:
  --
  --   an ancestor is Visible = false, or its ScreenGui is disabled
  --   an ancestor CanvasGroup is faded out          <- the inactive pages
  --   a clipping ancestor does not contain the point <- scrolled out of view
  --
  -- Walked once per candidate, and only for candidates the rectangle already
  -- accepted, so the cost lands on one or two objects rather than on hundreds.
  local function reachable(o, pt)
    local n = o
    while n and n ~= game do
      if n:IsA("GuiObject") then
        if not n.Visible then return false end
        -- a clipping ancestor is the only thing that can hide a child that is
        -- itself Visible, and a ScrollingFrame always clips
        if n.ClipsDescendants or n:IsA("ScrollingFrame") then
          local p, sz = n.AbsolutePosition, n.AbsoluteSize
          if pt.X < p.X or pt.X > p.X + sz.X
             or pt.Y < p.Y or pt.Y > p.Y + sz.Y then return false end
        end
        if n:IsA("CanvasGroup") and n.GroupTransparency > 0.5 then return false end
      elseif n:IsA("ScreenGui") then
        if not n.Enabled then return false end
        return true
      end
      n = n.Parent
    end
    return true
  end

  local function under(pt)
    -- Rectangle tests first, measurement second. GetTextSize on every registered
    -- label at 10 Hz would be several hundred text measurements a second to
    -- decide one tooltip; only what the pointer is actually over gets measured.
    local hits, hints
    for i = #A.tips, 1, -1 do
      local l = A.tips[i]
      if not l.Parent then
        table.remove(A.tips, i)                 -- prune rebuilt windows
      elseif l.Visible and l.TextTransparency < 0.9 then
        local p, s = l.AbsolutePosition, l.AbsoluteSize
        if pt.X >= p.X and pt.X <= p.X + s.X and pt.Y >= p.Y and pt.Y <= p.Y + s.Y
           and reachable(l, pt) then
          hits = hits or {}
          hits[#hits + 1] = l
        end
      end
    end
    -- explicit explanations, which need no measurement: if the pointer is over
    -- it, it has something to say
    for i = #A.hints, 1, -1 do
      local h = A.hints[i]
      if not (h.obj and h.obj.Parent) then
        table.remove(A.hints, i)
      elseif h.obj.Visible then
        local p, s = h.obj.AbsolutePosition, h.obj.AbsoluteSize
        if s.X > 0 and pt.X >= p.X and pt.X <= p.X + s.X
           and pt.Y >= p.Y and pt.Y <= p.Y + s.Y
           and reachable(h.obj, pt) then
          hints = hints or {}
          hints[#hints + 1] = h
        end
      end
    end
    if hints then
      table.sort(hints, function(a, b) return (a.obj.ZIndex or 0) > (b.obj.ZIndex or 0) end)
      local h = hints[1]
      return { key = h.obj, text = h.text, label = h.label, src = h.obj }
    end

    if not hits then return nil end
    -- topmost first, so a value label wins over the row title stacked behind it
    table.sort(hits, function(a, b) return a.ZIndex > b.ZIndex end)
    for _, l in ipairs(hits) do
      if truncated(l) then return { key = l, text = l.Text, src = l } end
    end
    return nil
  end

  local function hide()
    if not tipFrame or not tipFrame.Visible then return end
    shownFor = nil
    -- the whole card, stroke included -- see A.fadeTo
    A.fadeTo(tipFrame, 1, "fast")
    M.after(0.22, function()
      if tipFrame and not shownFor then tipFrame.Visible = false end
    end)
  end

  local function show(l, pt)
    ensure()
    shownFor = l.key or l
    tipLbl.Text = l.text or ""
    tipTitle.Text = l.label or ""
    tipTitle.Visible = (l.label ~= nil and l.label ~= "")

    -- SCALED BY HAND, NOT BY A UISCALE. Everything here is positioned and
    -- measured in absolute pixels; a UIScale on the host would silently
    -- multiply all of it and put the tooltip in the wrong place at the wrong
    -- size. Scaling the one font instead keeps the arithmetic honest and still
    -- matches the rest of the interface at 1.6x.
    local win = L.Hub and L.Hub.window
    local sc = (win and win.scaleObj and win.scaleObj.Scale) or L.autoScale()
    tipLbl.TextSize = math.max(9, math.floor(T.size.micro * sc + 0.5))

    -- SIZED FROM THE FULL STRING, measured in the TOOLTIP's own font -- not from
    -- the source label's TextBounds, which is the truncated width and would size
    -- the tooltip to exactly the space that was too small in the first place.
    -- (It did: a 697 px string got a 475 px tooltip, clipping the text the
    -- tooltip existed to reveal.)
    local vp = L.viewport()
    local maxW = math.floor(vp.X * 0.6)
    local pad = math.ceil(8 * sc)
    -- MEASURE THE STRING THIS TOOLTIP IS ACTUALLY SHOWING.
    --
    -- `under()` hands back a plain descriptor, `{ key = ..., text = ... }` --
    -- never an Instance. So `l.Text` was always nil, GetTextSize always threw,
    -- and the fallback then read `l.AbsoluteSize.X` off the same plain table:
    --
    --     attempt to index nil with 'X'
    --
    -- Every hint tooltip in the interface hit it, on every hover. The text is
    -- already on `tipLbl`; measure that, and fall back to the frame we have.
    tipTitle.TextSize = tipLbl.TextSize
    local body  = tipLbl.Text
    local head  = tipTitle.Visible and tipTitle.Text or nil
    local padY  = math.ceil(7 * sc)
    local gapY  = math.ceil(2 * sc)

    local function widthOf(str, lbl)
      if not str or str == "" then return 0 end
      local ok, z = pcall(function()
        return TextService:GetTextSize(str, lbl.TextSize, lbl.Font,
                                       Vector2.new(9999, 200))
      end)
      return (ok and z) and z.X or (#str * lbl.TextSize * 0.55)
    end

    -- the card is as wide as its widest line, never wider than the cap
    local w = pad * 2 + math.ceil(math.max(widthOf(body, tipLbl),
                                           widthOf(head, tipTitle)))
    local lineH = math.ceil(tipLbl.TextSize * 1.35)
    local bodyH = lineH

    -- past the cap it wraps instead of clipping, because a tooltip that runs off
    -- the screen has reproduced the original problem in a larger font
    if w > maxW then
      w = maxW
      tipLbl.TextWrapped = true
      local okw, wz = pcall(function()
        return TextService:GetTextSize(body, tipLbl.TextSize, tipLbl.Font,
                                       Vector2.new(maxW - pad * 2, 9999))
      end)
      bodyH = (okw and wz) and math.ceil(wz.Y) or lineH
    else
      tipLbl.TextWrapped = false
    end

    local headH = head and lineH or 0
    local h = padY * 2 + headH + (head and gapY or 0) + bodyH
    tipTitle.Position = UDim2.fromOffset(pad, padY)
    tipTitle.Size     = UDim2.new(1, -pad * 2, 0, headH)
    tipLbl.Position   = UDim2.fromOffset(pad, padY + headH + (head and gapY or 0))
    tipLbl.Size       = UDim2.new(1, -pad * 2, 0, bodyH)
    -- a lone line is the message, so it gets the message colour; under a heading
    -- it is supporting text and steps back
    tipLbl.TextColor3 = head and T.c.textDim or T.c.text
    tipFrame.Size = UDim2.fromOffset(w, h)

    -- Positioned in tipGui's own space. The claim that used to stand here --
    -- that GetMouseLocation is measured below the topbar -- is false; it is the
    -- inset-INCLUDED reading, so adding the inset to it dropped every tooltip
    -- 58 px. L.pointerOffset asks tipGui which space it is in and answers in
    -- that space, so this stays correct if the ScreenGui's flags ever change.
    -- IT BELONGS TO THE CONTROL, NOT TO THE POINTER.
    --
    -- A card pinned 14 px right and 20 px down from the cursor is a cursor
    -- accessory: it slides around under the hand, it covers whatever is to the
    -- lower right, and it never quite points at the thing it is describing. The
    -- reference does the opposite -- the card sits centred just above the
    -- control and stays put while the pointer moves inside it, so it reads as
    -- that control speaking.
    --
    -- The pointer is still the fallback, for anything that reports no rect.
    local anchor = L.pointerOffset(tipGui)
    local gap = math.ceil(8 * sc)
    local x, y, from
    local src = l.src
    if src and src.Parent and src.AbsoluteSize.X > 0 then
      -- AbsolutePosition is inset-EXCLUDED; tipGui ignores the inset, so the
      -- offset between the two spaces has to be put back. L.pointerOffset
      -- already answers in tipGui's space, and L.pointer() in AbsolutePosition
      -- space, so their difference IS that offset -- no second inset call, and
      -- it stays right if the ScreenGui's flags ever change.
      local shift = anchor - L.pointer()
      local p, sz = src.AbsolutePosition + shift, src.AbsoluteSize
      x = p.X + sz.X * 0.5 - w * 0.5
      y = p.Y - h - gap
      from = y + math.ceil(6 * sc)            -- rises into place
      if y < 6 then                            -- no room above: sit below it
        y = p.Y + sz.Y + gap
        from = y - math.ceil(6 * sc)           -- and drops into place
      end
    else
      x = anchor.X + 14
      y = anchor.Y + 20
      if y + h > vp.Y - 6 then y = anchor.Y - h - 10 end
      from = y + 6
    end
    x = math.clamp(x, 6, math.max(vp.X - w - 6, 6))
    y = math.clamp(y, 6, math.max(vp.Y - h - 6, 6))

    -- Snap to the start of the travel, THEN reveal. Setting Position with M.to
    -- from wherever the last tooltip happened to be would fly the card across
    -- the screen between two unrelated controls.
    M.to(tipFrame, "Position", UDim2.fromOffset(x, math.floor(from)), "instant")
    tipFrame.Visible = true
    M.to(tipFrame, "Position", UDim2.fromOffset(x, y), "base")
    A.fadeTo(tipFrame, 0, "fast")
  end

  local acc = 0
  L.hold(L.RunService.Heartbeat:Connect(function(dt)
    if not L.live() then return end
    acc = acc + dt
    if acc < 0.1 then return end                -- 10 Hz is under human notice
    acc = 0
    local win = L.Hub and L.Hub.window
    if (not win) or (win.hidden and #A.hints == 0)
       or (#A.tips == 0 and #A.hints == 0) then
      if hovered then hovered = nil hide() end
      return
    end
    -- INSET-EXCLUDED, because `under` tests against AbsolutePosition. This used
    -- to pass GetMouseLocation straight in, which is the inset-INCLUDED value,
    -- so the tooltip hit test was 58 px below the label it was testing: rows
    -- claimed the pointer while it was still over the row above them.
    local pt = L.pointer()
    local l = under(pt)
    local key = l and l.key or nil
    if key ~= hovered then
      hovered, hoverSince = key, os.clock()
      if shownFor and shownFor ~= key then hide() end
    elseif l and not shownFor and (os.clock() - hoverSince) >= DWELL then
      show(l, pt)
    end
  end))
end

end
do -- ==== lm_19_focus.lua ====
-- LUMEN :: FOCUS
-- Keyboard navigation. Tab walks the page, arrows move and adjust, Enter
-- activates, [ and ] change tab, Escape or a click leaves.
-- CAS never receives Tab, Escape or the brackets (CoreGui claims them first), so
-- UIS drives and CAS is only used to sink keys.

local L = getgenv().LUMEN
local T, M, A = L.T, L.Motion, L.A
local mk = L.mk
local CAS = game:GetService("ContextActionService")

local F = {}
L.Focus = F

F.items = {}
F.current = nil
F.active = false

local ACTION = "LumenFocusNav"
local EDGE_PAD = 14          -- breathing room when scrolling a control into view

-- ---------------------------------------------------------------- registry

-- spec: { activate = fn, adjust = fn(dir), radius = n, label = s }
function F.register(frame, spec)
  spec = spec or {}
  spec.frame = frame
  F.items[#F.items + 1] = spec
  return spec
end

function F.reset()
  F.items, F.current, F.active = {}, nil, false
end

-- ---------------------------------------------------------------- ring

-- Roblox applies only one UIStroke per instance and A.interactive already owns
-- it, so the ring needs its own frame or hovering away erases it.
local function ringOf(spec)
  if spec._ring and spec._ring.Parent then return spec._ring end
  local f = spec.frame
  local ring = mk("Frame", {
    Size = UDim2.fromScale(1, 1),
    BackgroundTransparency = 1,
    ZIndex = (f.ZIndex or 1) + 6,
    Name = "FocusRing", Parent = f,
  })
  L.corner(spec.radius or T.r.md, ring)
  spec._ringStroke = L.stroke(T.c.accent, 1.6, 1, ring)
  spec._ring = ring
  return ring
end

local function paintRing(spec, on)
  if not spec or not spec.frame or not spec.frame.Parent then return end
  ringOf(spec)
  if spec._ringStroke then
    M.to(spec._ringStroke, "Transparency", on and 0.1 or 1, "fast")
  end
end

-- ---------------------------------------------------------------- page scope

local function activeTab()
  local win = L.Hub and L.Hub.window
  if not win or win.hidden then return nil end
  return win.tabs[win.active], win
end

local function inside(node, page)
  while node do
    if node == page then return true end
    node = node.Parent
  end
  return false
end

-- Also prunes: a theme change rebuilds the window, so dead specs must be dropped
-- or the registry grows on every rebuild.
local function visibleItems()
  local tab = activeTab()
  if not tab then return {} end
  local out, keep = {}, {}
  for _, s in ipairs(F.items) do
    if s.frame and s.frame.Parent then
      keep[#keep + 1] = s
      -- a veiled control is still Visible and still on the page; skipping it
      -- here is what stops Tab landing on something whose click is refused
      if s.frame.Visible ~= false and not s.frame:GetAttribute("lmDisabled")
         and inside(s.frame, tab.page) then
        out[#out + 1] = s
      end
    end
  end
  F.items = keep
  return out
end

F.visibleItems = visibleItems

-- ---------------------------------------------------------------- movement

local function scrollIntoView(spec)
  local tab = activeTab()
  local body = tab and tab.body
  if not body or not spec.frame.Parent then return end
  local ctrl = A._scrolls and A._scrolls[body]
  if not ctrl then return end

  -- position within the canvas, not on screen: the canvas is what scrolls
  local rel = (spec.frame.AbsolutePosition.Y - body.AbsolutePosition.Y)
              + body.CanvasPosition.Y
  local h, viewH = spec.frame.AbsoluteSize.Y, body.AbsoluteWindowSize.Y
  local top = body.CanvasPosition.Y
  local want = top
  if rel - EDGE_PAD < top then
    want = rel - EDGE_PAD
  elseif rel + h + EDGE_PAD > top + viewH then
    want = rel + h + EDGE_PAD - viewH
  end
  if math.abs(want - top) > 0.5 then ctrl:to(math.max(want, 0)) end
end

function F.focus(spec)
  if F.current and F.current ~= spec then paintRing(F.current, false) end
  F.current = spec
  if spec then
    paintRing(spec, true)
    scrollIntoView(spec)
  end
end

function F.blur()
  if F.current then paintRing(F.current, false) end
  F.current = nil
end

function F.step(dir)
  local list = visibleItems()
  if #list == 0 then F.blur() return false end
  local i = 0
  for k, s in ipairs(list) do if s == F.current then i = k break end end
  i = i + dir
  if i < 1 then i = #list elseif i > #list then i = 1 end   -- wrap
  F.focus(list[i])
  return true
end

-- ---------------------------------------------------------------- keys

local function driving()
  if not L.live() then return false end
  local win = L.Hub and L.Hub.window
  if not win or win.hidden then return false end
  -- the palette is a modal and owns the keyboard while it is up
  if L.Palette and L.Palette.open then return false end
  -- a focused text box wins: sinking Space and the arrows would break typing
  local box = L.UIS:GetFocusedTextBox()
  if box then return false end
  return true, win
end

local PASS, SINK = Enum.ContextActionResult.Pass, Enum.ContextActionResult.Sink

local function shift()
  return L.UIS:IsKeyDown(Enum.KeyCode.LeftShift)
      or L.UIS:IsKeyDown(Enum.KeyCode.RightShift)
end

-- Probed at priority 3000 (above every CoreScript binding): these are the only
-- keys ContextActionService actually receives.
local USED = {
  [Enum.KeyCode.Up] = true, [Enum.KeyCode.Down] = true,
  [Enum.KeyCode.Left] = true, [Enum.KeyCode.Right] = true,
  [Enum.KeyCode.Return] = true, [Enum.KeyCode.Space] = true,
}

local function suspended()
  local cur = F.current
  return cur and cur.suspend and cur.suspend()
end

CAS:BindActionAtPriority(ACTION, function(_, state, input)
  if state ~= Enum.UserInputState.Begin then return PASS end
  if not F.active or suspended() or not driving() then return PASS end
  if not USED[input.KeyCode] then return PASS end
  -- Left/Right only belong to us when the focused control can use them
  if (input.KeyCode == Enum.KeyCode.Left or input.KeyCode == Enum.KeyCode.Right)
     and not (F.current and F.current.adjust) then
    return PASS
  end
  if (input.KeyCode == Enum.KeyCode.Return or input.KeyCode == Enum.KeyCode.Space)
     and not (F.current and F.current.activate) then
    return PASS
  end
  return SINK
end, false, Enum.ContextActionPriority.High.Value,
  Enum.KeyCode.Up, Enum.KeyCode.Down, Enum.KeyCode.Left,
  Enum.KeyCode.Right, Enum.KeyCode.Return, Enum.KeyCode.Space)

-- ---- the driver ------------------------------------------------------------
-- `gameProcessedEvent` is already true for Tab, so an `if typing then return end`
-- guard would drop every Tab press.
L.hold(L.UIS.InputBegan:Connect(function(input)
  local ok, win = driving()
  if not ok then return end
  local k = input.KeyCode

  if not F.active then
    -- enters keyboard mode, and only while the pointer is over the window
    if k == Enum.KeyCode.Tab and win:_pointerInside() then
      F.active = true
      F.step(shift() and -1 or 1)
    end
    return
  end

  -- a control can ask for the raw keyboard back (the keybind chip, while recording)
  if suspended() then return end

  if k == Enum.KeyCode.Escape then
    -- Escape never reaches CAS, so it cannot be sunk at any priority and the
    -- Roblox menu opens either way. Handling it at least releases the ring.
    F.blur()
    F.active = false

  elseif k == Enum.KeyCode.Tab then
    F.step(shift() and -1 or 1)

  elseif k == Enum.KeyCode.Down then F.step(1)
  elseif k == Enum.KeyCode.Up   then F.step(-1)

  elseif k == Enum.KeyCode.LeftBracket or k == Enum.KeyCode.RightBracket then
    local n = win.active + (k == Enum.KeyCode.RightBracket and 1 or -1)
    if n < 1 then n = #win.tabs elseif n > #win.tabs then n = 1 end
    win:select(n)
    F.blur()
    task.defer(function() if F.active then F.step(1) end end)

  elseif k == Enum.KeyCode.Left or k == Enum.KeyCode.Right then
    local s = F.current
    if s and s.adjust then
      L.try("focus.adjust", s.adjust, k == Enum.KeyCode.Right and 1 or -1)
    end

  elseif k == Enum.KeyCode.Return or k == Enum.KeyCode.Space then
    local s = F.current
    if s and s.activate then L.try("focus.activate", s.activate) end
  end
end))

-- Unbind on teardown, or a reloaded hub leaves the old handler holding Tab.
-- L.teardown only knows how to call :Disconnect(), hence the fake connection.
L.hold({ Disconnect = function() pcall(function() CAS:UnbindAction(ACTION) end) end })

-- Clicking anywhere means the user went back to pointing, so drop the ring.
L.hold(L.UIS.InputBegan:Connect(function(i)
  if not L.live() or not F.active then return end
  if i.UserInputType == Enum.UserInputType.MouseButton1
  or i.UserInputType == Enum.UserInputType.Touch then
    F.blur()
    F.active = false
  end
end))

end
do -- ==== lm_05_window.lua ====
-- LUMEN :: WINDOW
-- The panel: header, nav, pages, drag, resize, minimise.
--
-- Two coordinate systems meet here. The window sits under a UIScale, so Position
-- OFFSETS are pre-scale units while the mouse reports real pixels. Anything
-- mixing the two must convert, and the drag does it as a delta from the grab
-- point so the constant offset cancels.

local L = getgenv().LUMEN
local T, M, A = L.T, L.Motion, L.A
local mk = L.mk

local Window = {}
Window.__index = Window
L.Window = Window

-- read per construction so a density change takes effect on rebuild
local HEADER, SIDEBAR, TAB_H

Window.BLUR = 16

-- ---------------------------------------------------------------- mark
function Window.mark(parent, size)
  local h = mk("Frame", {
    Size = UDim2.fromOffset(size, size), BackgroundTransparency = 1,
    Name = "Mark", Parent = parent,
  })
  local outer = mk("Frame", {
    AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, 0.5),
    Size = UDim2.fromOffset(size * 0.72, size * 0.72), Rotation = 45,
    BackgroundColor3 = T.c.accent, BorderSizePixel = 0, Parent = h,
  })
  L.corner(size * 0.18, outer)
  A.accentGradient(outer, 135)
  local inner = mk("Frame", {
    AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, 0.5),
    Size = UDim2.fromOffset(size * 0.28, size * 0.28), Rotation = 45,
    BackgroundColor3 = T.c.surface, BorderSizePixel = 0, ZIndex = 3, Parent = h,
  })
  L.corner(size * 0.08, inner)
  return h
end

-- ---------------------------------------------------------------- construct

function Window.new(opts)
  opts = opts or {}
  HEADER, SIDEBAR, TAB_H = T.px("header"), T.px("sidebar"), T.px("tab")
  local self = setmetatable({}, Window)
  self.tabs, self.active = {}, nil
  self.width  = opts.width or 880
  self.height = opts.height or 556
  self.minW, self.minH = 660, 430
  self.cascade = (L.Cfg and tonumber(L.Cfg.data.cascade)) or 0.035

  -- geometry is remembered across sessions; a tool that forgets where you put it
  -- makes you re-place it every launch
  local g = L.Cfg and L.Cfg.data.geom
  if type(g) == "table" and tonumber(g.w) and tonumber(g.h) then
    local vp = L.viewport()
    self.width  = math.clamp(tonumber(g.w), self.minW, math.max(vp.X - 40, self.minW))
    self.height = math.clamp(tonumber(g.h), self.minH, math.max(vp.Y - 40, self.minH))
    self._restorePos = (tonumber(g.x) and tonumber(g.y))
      and UDim2.fromOffset(tonumber(g.x), tonumber(g.y)) or nil
  end

  local gui = mk("ScreenGui", {
    Name = opts.guiName or "Lumen", ResetOnSpawn = false,
    ZIndexBehavior = Enum.ZIndexBehavior.Sibling, IgnoreGuiInset = true,
    DisplayOrder = 10,
  })
  gui.Parent = L.host()
  L.own(gui)
  self.gui = gui
  -- a saved scale wins over the auto-fit; nil means "fit this screen"
  local savedScale = L.Cfg and tonumber(L.Cfg.data.scale)
  self.scaleObj = mk("UIScale", { Scale = savedScale or L.autoScale(), Parent = gui })

  self.scrim = mk("Frame", {
    Size = UDim2.fromScale(1, 1), BackgroundColor3 = T.c.scrim,
    BackgroundTransparency = 1, BorderSizePixel = 0, ZIndex = 1,
    Name = "Scrim", Parent = gui,
  })

  local shell = mk("Frame", {
    AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, 0.5),
    Size = UDim2.fromOffset(self.width, self.height),
    BackgroundTransparency = 1, ZIndex = 2, Name = "Shell", Parent = gui,
  })
  self.shell = shell

  -- MEASURE ALWAYS, INCLUDING ON RESTORE.
  --
  -- Collapse the scale term before anything can drag it: Position starts as
  -- fromScale(0.5,0.5) but _saveGeom records only offsets, so a drag would
  -- persist numbers relative to a term nobody stored. Measured, not derived --
  -- one sample at offset zero pins the constant. Two frames, still hidden.
  --
  -- The restore path used to skip all of this and assign the saved offset
  -- straight in. It is a RAW OFFSET IN LOCAL UNITS, recorded under whatever
  -- UIScale and viewport that session happened to have, so on any other screen
  -- it lands somewhere else entirely. Measured on 2560x1369 at scale 1.6: a
  -- saved offset of (134, 5), centre-anchored, put AbsolutePosition at
  -- (-314, -510) -- three quarters of the window above and left of the screen,
  -- with the title bar off the top, so it could not even be dragged back.
  --
  -- Width and height were already clamped to the viewport above. Position was
  -- the one piece of remembered geometry still trusting the old session.
  task.spawn(function()
    L.RunService.Heartbeat:Wait()
    if not shell.Parent then return end
    shell.Position = UDim2.fromOffset(0, 0)
    L.RunService.Heartbeat:Wait()
    if not shell.Parent then return end
    local k = shell.AbsolutePosition
    local sc = (self.scaleObj and self.scaleObj.Scale) or 1
    local vp = L.viewport()
    local sz = shell.AbsoluteSize

    local want
    if self._restorePos then
      -- where that saved offset actually lands on THIS screen
      want = Vector2.new(self._restorePos.X.Offset * sc + k.X,
                         self._restorePos.Y.Offset * sc + k.Y)
    else
      -- centre it PROPERLY. fromScale(0.5,0.5) was landing 59 px high, because
      -- AbsolutePosition and ScreenGui space disagree about the topbar inset --
      -- so the window used to open slightly above the middle of the screen.
      want = Vector2.new(vp.X / 2 - sz.X / 2, vp.Y / 2 - sz.Y / 2)
    end

    -- Keep it reachable. A window larger than the screen is pinned to the
    -- top-left corner rather than centred, because the title bar has to stay
    -- on screen -- it is the only handle for moving it.
    local M_ = 8
    local function fit(v, size, limit)
      if size >= limit then return math.clamp(v, limit - size, 0) end
      return math.clamp(v, M_, limit - size - M_)
    end
    want = Vector2.new(fit(want.X, sz.X, vp.X), fit(want.Y, sz.Y, vp.Y))
    shell.Position = UDim2.fromOffset((want.X - k.X) / sc, (want.Y - k.Y) / sc)
  end)

  -- real drop shadow, in the SHELL so it sits outside the panel bounds
  -- HELD, NOT FIRE-AND-FORGET. This was created and never referenced again, so
  -- hide() faded the panel while the shadow stayed at full opacity until
  -- shell.Visible flipped 0.34 s later -- a black rounded rectangle hanging in
  -- the air after the window had gone.
  self.shadowSpread = 34
  self.shadow = A.shadow(nil, {
    Parent = shell, spread = self.shadowSpread, alpha = 0.34, lift = 10, ZIndex = 3 })
  self.shadowRest = (L.Cfg and tonumber(L.Cfg.data.shadow)) or 0.34

  local root = mk("CanvasGroup", {
    Name = "Window", AnchorPoint = Vector2.new(0.5, 0.5),
    Position = UDim2.fromScale(0.5, 0.5),
    Size = UDim2.fromOffset(self.width, self.height),
    BackgroundTransparency = 1, BorderSizePixel = 0,
    GroupTransparency = 1, ZIndex = 5, Parent = shell,
  })
  L.corner(T.r.lg, root)
  L.stroke(T.c.lineStrong, 1, 0.3, root)
  self.root = root

  local bg = mk("Frame", {
    Size = UDim2.fromScale(1, 1), BackgroundColor3 = T.c.surface,
    BorderSizePixel = 0, ZIndex = 0, Name = "Body", Parent = root,
  })
  L.corner(T.r.lg, bg)
  self.body = bg

  -- accent light bleeding from the top edge
  local wash = mk("Frame", {
    Size = UDim2.new(1, 0, 0, 260), BackgroundColor3 = T.c.accent,
    BorderSizePixel = 0, ZIndex = 0, Name = "Wash", Parent = root,
  })
  self.wash = wash
  mk("UIGradient", {
    Transparency = NumberSequence.new({
        NumberSequenceKeypoint.new(0, 0.925),
      NumberSequenceKeypoint.new(1, 1),
    }), Rotation = 90, Parent = wash,
  })

  -- ANIMATED BACKDROP. A blurred bloom has no high-frequency detail, so it is
  -- rendered at 320x200 and stretched across the whole panel with no visible
  -- loss -- the entire 48-frame loop is under half a megabyte. Sits at a resting
  -- transparency rather than opaque, so it lights the surface instead of
  -- becoming it.
  self.bgVid = L.Video and L.Video.new(bg, {
    folder = "lumen_fx/bg", prefix = "bg", count = 48, fps = 16, loop = true,
    Size = UDim2.fromScale(1, 1), Position = UDim2.fromScale(0.5, 0.5),
    -- 0.30 put the loop at 70% opacity and turned the whole panel blue-purple,
    -- which contradicts the entire near-black premise. At 0.86 it reads as light
    -- moving under the surface and you only notice it when it moves.
    ZIndex = 0, rest = 0.86,
  })
  if not (L.Cfg and L.Cfg.data.grain == false) then A.grain(bg, 0.955) end
  -- (the snap hint used to live here: a full-panel accent wash flashed on every
  -- edge snap. It went with the snapping itself -- see Window:_drag.)

  A.hairline(root, Color3.new(1, 1, 1), 0, 0.5)
  A.hairline(root, T.c.accent, 1, 0.25)

  -- ---- header ---------------------------------------------------------
  local header = mk("Frame", {
    Size = UDim2.new(1, 0, 0, HEADER), BackgroundTransparency = 1,
    Name = "Header", Parent = root,
  })
  self.header = header

  -- The orb from the loading screen, small and strided. Same footage, so the
  -- window and the loader are unmistakably the same product.
  local orbHolder = mk("Frame", {
    Position = UDim2.fromOffset(20, HEADER / 2 - 21),
    Size = UDim2.fromOffset(42, 42), BackgroundTransparency = 1,
    Name = "OrbMark", Parent = header,
  })
  -- FULL SEQUENCE, NO STRIDE. `stride` divides the playback rate to preserve the
  -- loop duration, so stride 6 was running this at 5 fps while the loading screen
  local orbVid = L.Video and L.Video.new(orbHolder, {
    -- 5..96 is this sequence's loop -- 92 frames, the half-rate copy of the
    -- full Saturn's 183. The remaining frames of the folder do not close.
    folder = "lumen_fx/saturn_s", prefix = "sms", first = 5, count = 92, fps = 15, size = 42,
    Position = UDim2.fromScale(0.5, 0.5), ZIndex = 2, loop = true,
  })
  A.glow(orbHolder, 104, T.c.accent, { alpha = 0.80, ZIndex = 1 })
  if not orbVid then Window.mark(orbHolder, 42) end
  self.orbVid = orbVid

  -- LIQUID CHROME WORDMARK, RENDERED OFFLINE. A Roblox TextLabel takes one flat
  local wmH = 42
  local wm = L.Video and L.Video.new(header, {
    folder = "lumen_fx/word", prefix = "wm", count = 60, fps = 20, loop = true,
    Size = UDim2.fromOffset(math.floor(wmH * 575 / 198), wmH),
    Position = UDim2.fromOffset(78 + math.floor(wmH * 575 / 198) / 2, 34),
    ZIndex = 2,
  })
  self.wordVid = wm
  if not wm then
    A.text({
      Text = L.track(opts.title or "LUMEN", 1),
      font = T.font.display, size = T.size.title,
      colour = T.c.text, Position = UDim2.fromOffset(78, 22),
      Size = UDim2.fromOffset(320, 20), Parent = header,
    })
  end
  self.searchHint = A.text({
    Text = "CTRL K", font = T.font.mono, size = T.size.tiny, colour = T.c.textOff,
    align = Enum.TextXAlignment.Right, AnchorPoint = Vector2.new(1, 0.5),
    Position = UDim2.new(1, -190, 0.5, 0), Size = UDim2.fromOffset(60, 14),
    Parent = header,
  })
  self.subtitleLbl = A.text({
    Text = opts.subtitle or "", font = T.font.mono, size = T.size.tiny,
    colour = T.c.textOff, Position = UDim2.fromOffset(80, 58),
    Size = UDim2.fromOffset(360, 12), Parent = header,
  })

  local function chromeBtn(x, draw, onClick)
    local b = mk("Frame", {
      AnchorPoint = Vector2.new(1, 0.5), Position = UDim2.new(1, x, 0.5, 0),
      Size = UDim2.fromOffset(30, 30), BackgroundColor3 = T.c.hover,
      BackgroundTransparency = 1, BorderSizePixel = 0, Parent = header,
    })
    L.corner(T.r.sm + 2, b)
    local g = draw(b, 16, T.c.textMute)
    g.AnchorPoint = Vector2.new(0.5, 0.5)
    g.Position = UDim2.fromScale(0.5, 0.5)
    A.interactive(b, { radius = T.r.sm + 2, onClick = onClick,
                       hoverAlpha = 0.9, pressAlpha = 0.82 })
  end
  chromeBtn(-16, A.Icon.close, function() self:hide() end)
  chromeBtn(-50, A.Icon.minus, function() self:minimise() end)

  local pill = mk("Frame", {
    AnchorPoint = Vector2.new(1, 0.5), Position = UDim2.new(1, -88, 0.5, 0),
    Size = UDim2.fromOffset(88, 28), BackgroundColor3 = T.c.raised,
    BorderSizePixel = 0, Parent = header,
  })
  L.corner(999, pill)
  L.stroke(T.c.line, 1, 0.3, pill)
  local pdot = mk("Frame", {
    AnchorPoint = Vector2.new(0, 0.5), Position = UDim2.new(0, 11, 0.5, 0),
    Size = UDim2.fromOffset(6, 6), BackgroundColor3 = T.c.ok,
    BorderSizePixel = 0, Parent = pill,
  })
  L.corner(999, pdot)
  self.pingLbl = A.text({
    Text = "-- ms", font = T.font.mono, size = T.size.tiny, colour = T.c.textDim,
    Position = UDim2.fromOffset(23, 0), Size = UDim2.new(1, -28, 1, 0), Parent = pill,
  })
  self.statusDot = pdot

  -- ---- health chip ------------------------------------------------------
  --
  -- HIDDEN WHILE THERE IS NOTHING TO SAY. A permanent "all good" badge is
  -- decoration: it trains you to stop reading it, so on the day it finally does
  -- say something you stopped looking weeks ago. This exists only when a claim
  -- the interface already made has since failed -- which is the only moment an
  -- indicator earns the space it takes.
  local health = mk("Frame", {
    AnchorPoint = Vector2.new(1, 0.5), Position = UDim2.new(1, -258, 0.5, 0),
    Size = UDim2.fromOffset(118, 26), BackgroundColor3 = T.c.raised,
    BackgroundTransparency = 1, BorderSizePixel = 0,
    Visible = false, Name = "Health", Parent = header,
  })
  L.corner(999, health)
  local healthStroke = L.stroke(T.c.warn, 1, 1, health)
  local hdot = mk("Frame", {
    AnchorPoint = Vector2.new(0, 0.5), Position = UDim2.new(0, 11, 0.5, 0),
    Size = UDim2.fromOffset(6, 6), BackgroundColor3 = T.c.warn,
    BackgroundTransparency = 1, BorderSizePixel = 0, ZIndex = 2, Parent = health,
  })
  L.corner(999, hdot)
  local hlbl = A.text({
    Text = "", font = T.font.mono, size = T.size.tiny, colour = T.c.warn,
    Position = UDim2.fromOffset(23, 0), Size = UDim2.new(1, -30, 1, 0),
    ZIndex = 2, Parent = health,
  })
  hlbl.TextTransparency = 1
  A.interactive(health, { radius = 999, onClick = function()
    if self.onHealth then L.try("window.onHealth", self.onHealth) end
  end })
  self.healthChip = health

  -- SAMPLED, NOT PUSHED. There is no event that means "a feature stopped
  -- working" -- that is precisely why it goes unnoticed -- so health is derived
  -- and polled, at a rate no one can distinguish from instant.
  local shownState
  task.spawn(function()
    while L.live() and health.Parent do
      local state, nf, nc = L.health()
      if state ~= shownState then
        shownState = state
        if state == "ok" then
          M.to(health, "BackgroundTransparency", 1, "fast")
          M.to(hlbl, "TextTransparency", 1, "fast")
          M.to(healthStroke, "Transparency", 1, "fast")
          M.to(hdot, "BackgroundTransparency", 1, "fast")
          -- hidden only after it has faded, so the chip stops eating clicks in
          -- the middle of the header -- which is also the window's drag handle
          M.after(0.3, function()
            if health.Parent and shownState == "ok" then health.Visible = false end
          end)
        else
          local col = (state == "fault") and T.c.bad or T.c.warn
          hdot.BackgroundColor3, hlbl.TextColor3, healthStroke.Color = col, col, col
          health.Visible = true
          M.to(health, "BackgroundTransparency", 0.06, "fast")
          M.to(hlbl, "TextTransparency", 0, "fast")
          M.to(healthStroke, "Transparency", 0.4, "fast")
          M.to(hdot, "BackgroundTransparency", 0, "fast")
        end
      end
      -- WORST FIRST, BUT NEVER AT THE COST OF HIDING THE REST. Showing only the
      -- fault count while two features were also contested meant fixing the
      -- fault made the chip vanish and took the contested features with it --
      -- the indicator would have gone quiet with the hub still lying.
      if state == "fault" then
        hlbl.Text = nc > 0
          and string.format("%d fault  +%d", nf, nc)
          or string.format("%d fault%s", nf, nf == 1 and "" or "s")
      elseif state ~= "ok" then
        hlbl.Text = string.format("%d contested", nc)
      end
      task.wait(0.4)
    end
  end)

  mk("Frame", {
    Position = UDim2.fromOffset(0, HEADER), Size = UDim2.new(1, 0, 0, 1),
    BackgroundColor3 = T.c.line, BackgroundTransparency = 0.35,
    BorderSizePixel = 0, Parent = root,
  })

  -- ---- sidebar --------------------------------------------------------
  -- THE SIDEBAR IS A TINT, NOT A SLAB. Painting it an opaque darker colour cut
  -- it out of the panel entirely: the bloom loop, the grain and the top accent
  -- wash all stopped at its edge, so it read as a black rectangle glued to a lit
  -- one. Semi-transparent black over the same body lets every one of those pass
  -- underneath, and it is still visibly recessed.
  local side = mk("Frame", {
    Position = UDim2.fromOffset(0, HEADER + 1),
    Size = UDim2.new(0, SIDEBAR, 1, -(HEADER + 1)),
    BackgroundColor3 = Color3.new(0, 0, 0), BackgroundTransparency = 0.42,
    BorderSizePixel = 0,
    Name = "Sidebar", Parent = root,
  })
  local seam = mk("Frame", {
    Position = UDim2.new(1, -1, 0, 0), Size = UDim2.new(0, 1, 1, 0),
    BackgroundColor3 = T.c.accent, BorderSizePixel = 0, Parent = side,
  })
  mk("UIGradient", {
    Transparency = NumberSequence.new({
      NumberSequenceKeypoint.new(0, 0.55),
      NumberSequenceKeypoint.new(0.55, 0.90),
      NumberSequenceKeypoint.new(1, 1),
    }),
    Rotation = 90, Parent = seam,
  })

  -- Scrolls once the tabs outgrow the sidebar. Ten tabs do not fit a shortened
  -- window, and a tab you cannot reach is a feature you do not have.
  self.navHolder = mk("ScrollingFrame", {
    Position = UDim2.fromOffset(12, 14), Size = UDim2.new(1, -24, 1, -84),
    BackgroundTransparency = 1, BorderSizePixel = 0,
    CanvasSize = UDim2.new(), AutomaticCanvasSize = Enum.AutomaticSize.Y,
    ScrollBarThickness = 2, ScrollBarImageColor3 = T.c.lineStrong,
    ScrollBarImageTransparency = 0.4, ScrollingDirection = Enum.ScrollingDirection.Y,
    ElasticBehavior = Enum.ElasticBehavior.Never,
    Name = "Nav", Parent = side,
  })

  -- indicator sits BEHIND the rows, in the same coordinate space
  self.pill = mk("Frame", {
    Size = UDim2.new(1, 0, 0, TAB_H), Position = UDim2.fromOffset(0, 0),
    BackgroundColor3 = T.c.accent, BackgroundTransparency = 0.82,
    BorderSizePixel = 0, Visible = false, Name = "Indicator",
    Parent = self.navHolder,
  })
  L.corner(T.r.md, self.pill)
  mk("UIGradient", {
    Transparency = NumberSequence.new({
      NumberSequenceKeypoint.new(0, 0),
      NumberSequenceKeypoint.new(1, 1),
    }), Parent = self.pill,
  })

  self.pillBar = mk("Frame", {
    Size = UDim2.fromOffset(3, TAB_H * 0.45),
    Position = UDim2.fromOffset(-12, TAB_H * 0.275),
    BackgroundColor3 = T.c.accent, BorderSizePixel = 0, Visible = false,
    Name = "IndicatorEdge", Parent = self.navHolder,
  })
  L.corner(999, self.pillBar)
  A.accentGradient(self.pillBar, 90)

  -- AutomaticSize, not fromScale(1,1): inside a scrolling frame a full-height
  -- child pins the canvas to the viewport and nothing ever scrolls.
  self.navList = mk("Frame", {
    Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y,
    BackgroundTransparency = 1, Name = "NavItems", Parent = self.navHolder,
  })
  L.list(2, nil, self.navList)
  self._navOrder, self._navY, self._sections = 0, {}, {}
  self._navCursor = 0

  -- sidebar footer
  local foot = mk("Frame", {
    AnchorPoint = Vector2.new(0, 1), Position = UDim2.new(0, 12, 1, -14),
    Size = UDim2.new(1, -24, 0, 42), BackgroundTransparency = 1,
    Name = "Footer", Parent = side,
  })
  mk("Frame", {
    Size = UDim2.new(1, 0, 0, 1), BackgroundColor3 = T.c.line,
    BackgroundTransparency = 0.4, BorderSizePixel = 0, Parent = foot,
  })
  -- THE PLAYER'S ACTUAL HEADSHOT. This was a gradient placeholder I never went
  -- back and filled. `rbxthumb://` resolves a user thumbnail without a web
  -- request or a yield -- GetUserThumbnailAsync would block the build for a
  -- round trip, and this is the same image.
  local av = mk("ImageLabel", {
    Position = UDim2.fromOffset(0, 13), Size = UDim2.fromOffset(28, 28),
    BackgroundColor3 = T.c.raised, BorderSizePixel = 0,
    Image = string.format("rbxthumb://type=AvatarHeadShot&id=%d&w=48&h=48", L.LP.UserId),
    Parent = foot,
  })
  L.corner(T.r.sm + 1, av)
  L.stroke(T.c.lineStrong, 1, 0.45, av)
  self.avatar = av
  A.text({
    Text = L.LP.Name, font = T.font.medium, size = T.size.micro,
    colour = T.c.textDim, Position = UDim2.fromOffset(36, 13),
    Size = UDim2.new(1, -38, 0, 13), truncate = true, Parent = foot,
  })
  self.footState = A.text({
    Text = "connected", font = T.font.mono, size = T.size.tiny,
    colour = T.c.textOff, Position = UDim2.fromOffset(36, 27),
    Size = UDim2.new(1, -38, 0, 12), Parent = foot,
  })

  task.spawn(function()
    local Stats = game:GetService("Stats")
    while L.live() and foot.Parent do
      local ok, v = pcall(function()
        return Stats.Network.ServerStatsItem["Data Ping"]:GetValue()
      end)
      local ms = (ok and type(v) == "number") and math.floor(v) or -1
      self.pingLbl.Text = (ms >= 0) and (ms .. " ms") or "offline"
      M.to(pdot, "BackgroundColor3",
        (ms < 0 and T.c.textOff) or (ms < 120 and T.c.ok)
        or (ms < 260 and T.c.warn) or T.c.bad, "base")
      task.wait(2)
    end
  end)

  -- ---- content --------------------------------------------------------
  self.content = mk("Frame", {
    Position = UDim2.fromOffset(SIDEBAR + 1, HEADER + 1),
    Size = UDim2.new(1, -(SIDEBAR + 1), 1, -(HEADER + 1)),
    BackgroundTransparency = 1, ClipsDescendants = true,
    Name = "Content", Parent = root,
  })

  -- THE SATURN, AS A BACKGROUND OBJECT. It appeared here once by accident when
  -- two sequences collided on the same basename, stretched edge to edge. It read
  -- well, so it is back on purpose: sized to the panel rather than filling it,
  -- anchored right and allowed to bleed off the edge so it behaves like a hero
  -- object the content sits over, and held well back in opacity so it never
  -- competes with a value the user is trying to read.
  self.heroVid = L.Video and (not (L.Cfg and L.Cfg.data.heroArt == false)) and L.Video.new(self.content, {
    folder = "lumen_fx/saturn", prefix = "sat", first = 68, count = 183, fps = 30,
    size = math.floor(self.height * 0.46),
    -- pulled inside the edge and dropped low, so the ring reads as an object
    -- the content sits over rather than a crop artefact, and it clears the cards
    Position = UDim2.new(1, -58, 1, -48),
    ZIndex = 0, rest = 0.84, loop = true,
  })

  -- ---- the background behind the pages ----------------------------------
  --
  -- THIS IS WHERE THE BACKGROUND STYLES BELONG, and I built them for the
  -- loading screen first, which was a misread: a loading screen is on for four
  -- seconds and this is what you look at for the rest of the session.
  --
  -- The lattice used to carry a note saying it was static ON PURPOSE, because
  -- "a wave running behind live controls is noise rather than atmosphere". That
  -- judgement still holds and it is why Nebula -- static -- stays the default.
  -- It is an argument for a good default, though, not for having no choice.
  --
  -- Sized to the VIEWPORT rather than the window: the panel can be resized, and
  -- a lattice built to the old size would run out of dots the moment it grew.
  -- Content clips, so the overspill costs nothing.
  do
    local vp = L.viewport()
    local gw, gh = vp.X, vp.Y
    local sp = 30
    local host = mk("Frame", {
      Size = UDim2.fromScale(1, 1), BackgroundTransparency = 1, ZIndex = 0,
      Name = "Lattice", Parent = self.content,
    })
    self.bgDots, self.bgBase = {}, 0.93
    local cols = math.floor(gw / sp)
    local rows = math.floor(gh / sp)
    for x = 0, cols do
      for y = 0, rows do
        local d = mk("Frame", {
          Position = UDim2.fromOffset(x * sp + 14, y * sp + 12),
          Size = UDim2.fromOffset(2, 2),
          BackgroundColor3 = Color3.fromRGB(150, 170, 210),
          BackgroundTransparency = 0.93,
          BorderSizePixel = 0, ZIndex = 0, Parent = host,
        })
        self.bgDots[#self.bgDots + 1] =
          { obj = d, u = x / math.max(cols, 1), v = y / math.max(rows, 1) }
      end
    end

    -- The iridescent field, off unless the style asks for it. Five very large,
    -- very soft, very transparent colour discs drifting through one another --
    -- overlap does the blending, and because each is bigger than the panel you
    -- never see an edge, only the colour changing where two of them cross.
    -- Behind the lattice and well under the content in opacity.
    self.bgFields = {}
    if A.img and A.img.glow then
      local fieldHost = mk("Frame", {
        Size = UDim2.fromScale(1, 1), BackgroundTransparency = 1, ZIndex = 0,
        Visible = false, Name = "Fields", Parent = self.content,
      })
      self.bgFieldHost = fieldHost
      local SPEC = {
        { c = Color3.fromRGB( 92, 128, 255), sx = 0.30, sy = 0.20, rx = 0.017, ry = 0.011, sz = 1.10 },
        { c = Color3.fromRGB(186, 108, 255), sx = 0.26, sy = 0.27, rx = 0.012, ry = 0.021, sz = 0.88 },
        { c = Color3.fromRGB( 88, 220, 220), sx = 0.29, sy = 0.22, rx = 0.022, ry = 0.009, sz = 0.96 },
        { c = Color3.fromRGB(255, 150, 120), sx = 0.20, sy = 0.24, rx = 0.010, ry = 0.016, sz = 0.74 },
        { c = Color3.fromRGB(120, 160, 255), sx = 0.33, sy = 0.17, rx = 0.007, ry = 0.019, sz = 1.24 },
      }
      for i, f in ipairs(SPEC) do
        local d = math.floor(self.width * f.sz)
        self.bgFields[i] = { spec = f, phase = i * 1.7, obj = mk("ImageLabel", {
          AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, 0.5),
          Size = UDim2.fromOffset(d, d), BackgroundTransparency = 1,
          Image = A.img.glow, ImageColor3 = f.c, ImageTransparency = 0.88,
          ZIndex = 0, Name = "Field" .. i, Parent = fieldHost,
        }) }
      end
    end
  end

  -- ---- background style --------------------------------------------------
  --
  -- One setting drives this and the loading screen, so the product has a look
  -- rather than two unrelated ones.
  function self:applyBackground(name)
    name = name or (L.Backdrop and L.Backdrop.styleName()) or "Nebula"
    self.bgStyle = name
    local aurora    = (name == "Aurora")
    local particles = (name == "Particles")
    local plain     = (name == "Plain")

    if self.bgFieldHost then self.bgFieldHost.Visible = aurora end
    -- the hero object is scenery: it belongs to the styles that want scenery
    if self.heroVid and self.heroVid.frameObj then
      self.heroVid.frameObj.Visible = not (plain or aurora)
    end
    -- Aurora lifts the lattice a little so the colour does not read as flat
    -- wallpaper; Plain drops it entirely
    self.bgBase = aurora and 0.955 or 0.93
    for _, d in ipairs(self.bgDots or {}) do
      d.obj.Visible = not plain
      d.obj.BackgroundTransparency = self.bgBase
      if not particles then d.obj.Size = UDim2.fromOffset(2, 2) end
    end
    self:_bgCull()
    return self
  end

  -- THE LATTICE IS BUILT TO THE VIEWPORT AND THE PANEL IS SMALLER THAN THAT.
  --
  -- Deliberately so -- the window resizes, and a lattice built to the old size
  -- would run out of dots the moment it grew. But the wave was walking all of
  -- them, and measured on a 958 x 931 panel only 992 of 3956 were inside it:
  -- three quarters of the work went to dots the content frame clips away. It
  -- showed up exactly where you would expect, in the tail rather than the
  -- median:
  --
  --   Nebula      median 6.11 ms   p95  8.68 ms
  --   Particles   median 6.20 ms   p95 17.44 ms   <- a dropped frame
  --   Aurora      median 6.07 ms   p95  8.16 ms
  --
  -- So the animated subset is resolved once per size change instead of per
  -- frame. Rebuilt on resize because the panel is resizable and a stale list
  -- would leave a rectangle of dead dots after it grew.
  function self:_bgCull()
    local c = self.content
    if not (c and self.bgDots) then return end
    local w, h = c.AbsoluteSize.X, c.AbsoluteSize.Y
    self._bgCullSize = Vector2.new(w, h)
    local live = {}
    for i = 1, #self.bgDots do
      local d = self.bgDots[i]
      local p = d.obj.Position
      if p.X.Offset <= w + 24 and p.Y.Offset <= h + 24 then live[#live + 1] = d end
    end
    self.bgActive = live
  end

  -- One clock for every animated nav icon. Advancing only the active and hovered
  -- ones keeps four of the five sequences completely still at rest.
  self._iconT = 0
  L.hold(L.RunService.RenderStepped:Connect(function(dt)
    if not L.live() or self.hidden then return end
    self._iconT = self._iconT + dt

    -- BACKGROUND. Only whichever style is live does any work, and the whole
    -- thing is skipped while the window is hidden by the guard above.
    if self.bgStyle == "Aurora" and self.bgFields then
      local t = self._iconT
      for i = 1, #self.bgFields do
        local fd = self.bgFields[i]
        local sp = fd.spec
        fd.obj.Position = UDim2.fromScale(
          0.5 + math.sin(t * sp.rx * 6.283 + fd.phase) * sp.sx,
          0.5 + math.cos(t * sp.ry * 6.283 + fd.phase * 1.31) * sp.sy)
        fd.obj.ImageTransparency = 0.88 + math.sin(t * 0.11 + fd.phase) * 0.05
      end
    elseif self.bgStyle == "Particles" and self.bgActive then
      -- 30 Hz: this touches every dot, and at 60 it is the single most
      -- expensive thing on an otherwise idle window for no visible gain
      self._bgAcc = (self._bgAcc or 0) + dt
      if self._bgAcc >= 1 / 30 then
        self._bgAcc = 0
        -- a resize invalidates the culled list, and the panel is resizable
        local cs = self.content and self.content.AbsoluteSize
        if cs and self._bgCullSize and (cs - self._bgCullSize).Magnitude > 8 then
          self:_bgCull()
        end
        local t, base = self._iconT, self.bgBase
        local live = self.bgActive
        for i = 1, #live do
          local d = live[i]
          local w = math.sin((d.u * 3.1 + d.v * 1.7) * 3.14159 - t * 0.85)
                  + math.sin((d.u * 1.3 - d.v * 2.9) * 3.14159 - t * 0.55)
          local k = math.clamp((w + 2) / 4, 0, 1)
          k = k * k * k                       -- most of the field stays quiet
          d.obj.BackgroundTransparency = base - (base - 0.62) * k
          local sz = 2 + math.floor(k * 2.4)
          if d.sz ~= sz then
            d.sz = sz
            d.obj.Size = UDim2.fromOffset(sz, sz)
          end
        end
      end
    end

    local f = math.floor(self._iconT * 12) + 1
    -- the chrome page title rides the same clock, at its own rate
    local tf = math.floor(self._iconT * 20) + 1
    local act = self.tabs[self.active]
    -- THE SWEEP RIDES THE WINDOW CLOCK, and only for the page you are looking
    -- at. Left to itself every page would animate its own gradient forever,
    -- including the ten nobody has open -- which is exactly the problem the old
    -- sequence solved with manual playback, kept here for the same reason.
    if act and act.titleGrad then
      -- SECONDS, NOT THE FRAME INDEX. This first shipped reading `tf`, which is
      -- the 20 fps counter the old image sequence stepped through -- so the
      -- sweep advanced twenty times a second instead of once, and math.floor
      -- quantised it into 20 visible steps on top. At speed 0.16 that is 1.6
      -- full passes per second and at Movement's 0.30 it is three: a strobe,
      -- not a shimmer. Caught on video.
      --
      -- Driven from the raw clock it is one pass every 2/speed seconds --
      -- 12.5 s at the default, which is slow enough to read as light moving
      -- across metal rather than as the title flashing.
      local sp = act.titleGrad:GetAttribute("Speed") or 0.16
      -- one full pass every 2/speed seconds, unchanged from the offset version
      -- so the measured 12.5 s at the default still holds -- but the pattern
      -- wraps, so there is no dead half of the cycle to sit through.
      local phase = (self._iconT * sp * 0.5) % 1
      -- Rebuilding 20 keypoints on every frame is needless allocation for a
      -- highlight that takes twelve seconds to cross a word. 24 Hz is far under
      -- the threshold where that reads as stepped. NOTE this throttles how often
      -- the colours are rebuilt, NOT the phase -- quantising the phase is what
      -- turned this into a strobe last time, and it is a different quantity.
      self._titleAcc = (self._titleAcc or 1) + dt
      if self._titleAcc >= 1 / 24 then
        self._titleAcc = 0
        act.titleGrad.Color = A.chromeSeq(act.titlePattern
                                          or A.chromePattern(A.CHROME.__default), phase)
      end
    end
    for i, t in ipairs(self.tabs) do
      if t.iconVid then
        local live = (i == self.active) or (i == self._hover)
        if live then
          t.iconVid:setFrame(f)
          t.iconVid.rest = (i == self.active) and 0 or 0.1
        else
          t.iconVid.rest = 0.5
        end
      end
    end
  end))

  -- while the pointer is over the hub, the wheel belongs to the hub
  A.addWheelGuard(function()
    return (not self.hidden) and self.root.Visible and self:_pointerInside()
  end)

  -- POPOVER LAYER. A dropdown cannot render inside the page: the content frame
  -- clips, and the page scrolls, so an expanding list is both cut off and
  -- dragged around by the scroll under it. This sits on the window root, above
  -- everything, clipped by nothing.
  self.overlay = mk("Frame", {
    Size = UDim2.fromScale(1, 1), BackgroundTransparency = 1,
    ZIndex = 30, Name = "Overlay", Parent = root,
  })

  self:_resize()
  self:_drag()
  self:_hotkeys(opts.toggleKey)

  -- ---- minimised dock -------------------------------------------------
  local dock = mk("Frame", {
    AnchorPoint = Vector2.new(0.5, 0), Position = UDim2.new(0.5, 0, 0, -60),
    Size = UDim2.fromOffset(142, 36), BackgroundColor3 = T.c.overlay,
    BorderSizePixel = 0, Name = "Dock", Parent = gui,
  })
  L.corner(999, dock)
  local dockStroke = L.stroke(T.c.lineStrong, 1, 0.3, dock)

  -- A HALO THAT BREATHES, so the pill reads as the one live thing on screen
  -- while everything else is gone. It sits behind the pill and outside it, which
  -- is the only way to glow without washing out the mark sitting on top.
  local dockGlow = A.img and A.img.glow and mk("ImageLabel", {
    AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, 0.5),
    Size = UDim2.new(1, 74, 1, 58), BackgroundTransparency = 1,
    Image = A.img.glow, ImageColor3 = T.c.accent, ImageTransparency = 0.82,
    ZIndex = 0, Name = "DockGlow", Parent = dock,
  })

  -- a small halo of its own, drifting around the mark. The pill's glow says
  -- "this is here"; this one says the mark is alive while nothing else is.
  local orbGlow = A.img and A.img.glow and mk("ImageLabel", {
    AnchorPoint = Vector2.new(0.5, 0.5),
    Position = UDim2.fromOffset(22, 18), Size = UDim2.fromOffset(46, 46),
    BackgroundTransparency = 1, Image = A.img.glow,
    ImageColor3 = T.c.accent, ImageTransparency = 0.72,
    ZIndex = 1, Name = "OrbGlow", Parent = dock,
  })

  -- the Saturn, not the drawn diamond: the same mark the loader and the header
  -- already use, so the minimised state is recognisably the same product
  local dockOrb = L.Video and L.Video.new(dock, {
    folder = "lumen_fx/saturn_s", prefix = "sms", first = 5, count = 92,
    fps = 15, size = 24, loop = true,
    Position = UDim2.fromOffset(22, 18), ZIndex = 2,
  })
  if not dockOrb then Window.mark(dock, 20).Position = UDim2.fromOffset(10, 8) end

  local dockLbl = A.text({
    Text = opts.title or "LUMEN", font = T.font.strong, size = T.size.label,
    colour = T.c.textDim, Position = UDim2.fromOffset(38, 0),
    Size = UDim2.new(1, -48, 1, 0), Parent = dock,
  })

  A.interactive(dock, {
    radius = 999, onClick = function() self:restore() end,
    onState = function(st)
      -- the whole pill answers the cursor: the halo swells, the edge lights up
      -- and the wordmark brightens, all on one token so it reads as one object
      M.to(dockStroke, "Color", st.hovered and T.c.accent or T.c.lineStrong, "fast")
      M.to(dockStroke, "Transparency", st.hovered and 0.05 or 0.3, "fast")
      M.to(dockLbl, "TextColor3", st.hovered and T.c.text or T.c.textDim, "fast")
      if dockGlow then
        M.to(dockGlow, "Size",
          st.hovered and UDim2.new(1, 104, 1, 80) or UDim2.new(1, 74, 1, 58), "base")
      end
      self._dockHover = st.hovered
    end,
  })

  -- One loop for the halo. A spring cannot express a cycle -- it settles by
  -- definition -- so the breathing is a cosine, and hovering only shifts the
  -- band it breathes within rather than interrupting it.
  if dockGlow then
    self._dockT = 0
    L.hold(L.RunService.RenderStepped:Connect(function(dt)
      if not L.live() or not dock.Parent then return end
      if dock.Position.Y.Offset < -20 then return end     -- parked offscreen
      self._dockT = self._dockT + dt
      local puls = 0.5 + 0.5 * math.cos(self._dockT * 2.1)
      local lo = self._dockHover and 0.52 or 0.74
      local hi = self._dockHover and 0.72 or 0.90
      dockGlow.ImageTransparency = hi - (hi - lo) * puls

      -- the mark's own halo drifts around it on a slower, offset cycle, so the
      -- two glows never breathe in step and the pill does not read as one pulse
      if orbGlow then
        local a = self._dockT * 0.75
        orbGlow.Position = UDim2.fromOffset(22 + math.cos(a) * 2.6,
                                            18 + math.sin(a * 1.3) * 2.2)
        local p2 = 0.5 + 0.5 * math.cos(self._dockT * 1.55 + 1.1)
        orbGlow.ImageTransparency = (self._dockHover and 0.50 or 0.66)
                                    + 0.16 * p2
      end
    end))
  end

  self.dock, self.dockGlow, self.dockOrb, self.orbGlow =
    dock, dockGlow, dockOrb, orbGlow

  -- the pinned-feature strip lives beside the pill, as a CHILD of it, so it
  -- inherits every minimise and restore rather than chasing them
  if L.Pins and L.Pins.attach then L.try("pins.attach", L.Pins.attach, dock) end

  -- last, because it reaches into the hero video and the lattice, both of which
  -- have to exist first
  L.try("window.background", function() self:applyBackground() end)

  return self
end

-- ---------------------------------------------------------------- nav

-- A group heading in the sidebar. Five flat entries read as a list; two groups
-- of two or three read as a structure.
function Window:navSection(name)
  local h = mk("Frame", {
    Size = UDim2.new(1, 0, 0, 26), BackgroundTransparency = 1,
    LayoutOrder = self._navOrder, Name = "NavSection", Parent = self.navList,
  })
  self._navOrder = self._navOrder + 1
  self._navCursor = self._navCursor + 26 + 2
  A.text({
    Text = L.track(string.upper(name or ""), 1),
    font = T.font.medium, size = T.size.nano,
    colour = T.c.textOff, Position = UDim2.fromOffset(12, 12),
    Size = UDim2.new(1, -14, 0, 12), Parent = h,
  })
  self._sections[#self._sections + 1] = h
  self._pendingSection = name
  return h
end

function Window:tab(opts)
  opts = opts or {}
  local index = #self.tabs + 1

  local btn = mk("Frame", {
    Size = UDim2.new(1, 0, 0, TAB_H), BackgroundTransparency = 1,
    LayoutOrder = self._navOrder, Name = "Tab_" .. (opts.name or index),
    Parent = self.navList,
  })
  self._navOrder = self._navOrder + 1
  local navY = self._navCursor
  self._navCursor = self._navCursor + TAB_H + 2

  -- ANIMATED CHROME TILE. The reference icons are not stills -- the objects turn.
  -- Each is a 48-frame loop at 96 px, which is near 1:1 at the 30 px display size
  -- and costs 1.7 MB per icon.
  --
  -- ONLY THE ACTIVE AND HOVERED ONES RUN. Five sequences turning at once is
  -- noise, and it makes the nav compete with the page for attention. A resting
  -- tab holds a single frame, which costs nothing.
  local glyph, iconVid, isChrome
  if opts.chrome then
    iconVid = L.Video and L.Video.new(btn, {
      folder = "lumen_fx/icons_anim", prefix = opts.chrome, count = 48, fps = 12,
      size = 30, Position = UDim2.fromOffset(8 + 15, TAB_H / 2), ZIndex = 2,
      manual = true, loop = true,
    })
    if iconVid then
      glyph = iconVid.frameObj
      isChrome = true
    end
  end
  if not glyph and opts.chrome then
    glyph = A.chrome(btn, opts.chrome, 30, {
      Position = UDim2.fromOffset(8, TAB_H / 2 - 15), ZIndex = 2 })
    isChrome = glyph ~= nil
  end
  if not glyph then
    local iconFn = A.Icon[opts.icon or "dot"] or A.Icon.dot
    glyph = iconFn(btn, 16, T.c.textMute)
    glyph.Position = UDim2.fromOffset(12, TAB_H / 2 - 8)
  end

  -- Same derivation as every other two-part row in this project: the name's box
  -- ends where the number's begins, plus a gap. It used to reserve `1, -76`
  -- while the number occupied the last 32 px, so the two overlapped by 4 px on
  -- every tab -- invisible only because the name truncates first.
  local NAV_X, NUM_W, NUM_RIGHT, NUM_GAP = 48, 20, 12, 8
  local label = A.text({
    Text = opts.name or ("Tab " .. index), font = T.font.medium,
    size = T.size.body, colour = T.c.textMute,
    Position = UDim2.fromOffset(NAV_X, 0),
    Size = UDim2.new(1, -(NAV_X + NUM_W + NUM_RIGHT + NUM_GAP), 1, 0),
    truncate = true, Parent = btn,
  })
  -- the number key that selects it, stated rather than hidden in a help screen
  A.text({
    Text = tostring(index), font = T.font.mono, size = T.size.tiny,
    colour = T.c.textOff, align = Enum.TextXAlignment.Right,
    AnchorPoint = Vector2.new(1, 0.5), Position = UDim2.new(1, -NUM_RIGHT, 0.5, 0),
    Size = UDim2.fromOffset(NUM_W, 12), Parent = btn,
  })

  local page = mk("Frame", {
    Size = UDim2.fromScale(1, 1), BackgroundTransparency = 1, Visible = false,
    Name = "Page_" .. (opts.name or index), Parent = self.content,
  })

  -- Heading lives OUTSIDE the CanvasGroup so it renders natively.
  --
  -- THREE TIERS, WIDE APART. The reference gets its hierarchy from RANGE: a tiny
  -- wide-tracked eyebrow, then a large title, then a small dim line. Sizes only
  local head = mk("Frame", {
    Size = UDim2.new(1, 0, 0, 88), BackgroundTransparency = 1,
    Name = "Heading", Parent = page,
  })
  local eyebrow = A.text({
    Text = L.track(string.upper(self._pendingSection or "SECTION"), 1),
    font = T.font.medium, size = T.size.nano, colour = T.c.textOff,
    Position = UDim2.fromOffset(24, 16), Size = UDim2.new(1, -48, 0, 12),
    Parent = head,
  })
  local titleLbl = A.text({
    Text = opts.name or "", font = T.font.display, size = T.size.display,
    colour = T.c.text,
    Position = UDim2.fromOffset(24, 30), Size = UDim2.new(1, -48, 0, 28),
    Parent = head,
  })

  -- ---- chrome title -----------------------------------------------------
  --
  -- THIS USED TO BE A 36-FRAME IMAGE SEQUENCE, and the reason given was:
  -- "Roblox cannot fill text with a gradient, mask an image to glyphs, or
  -- animate a reflection across a TextLabel". The first of those is false and
  -- has been for years -- a UIGradient parented to a TextLabel tints its
  -- glyphs. Verified on this client with a side-by-side probe and a screenshot
  -- before any of this was written.
  --
  -- What that assumption cost:
  --   * only SIX words existed. Movement, Combat, Visuals, AI and Config fell
  --     back to flat white, because nobody had run the generator for them.
  --   * the frames were baked at a 96 px glyph. Expand the window past the
  --     scale that assumed and the title is an UPSCALED BITMAP -- which is the
  --     "text goes soft when I resize" complaint, and it could not be fixed by
  --     any amount of care at the call site.
  --   * about 490 ms of the window build, by the old comment's own measurement.
  --
  -- Rendering it live costs one UIGradient per page and is resolution
  -- independent, so it is sharp at any window size and any DPI, and every tab
  -- gets one for free -- including tabs that do not exist yet.
  local titleGrad, titlePattern
  do
    -- PER-PAGE CHARACTER, from one engine -- now shared with the loading screen.
    -- See A.CHROME / A.chromeSeq in atoms for why the sweep resamples the
    -- gradient's colours instead of sliding its Offset. Short version: Offset
    -- clamps, so half of every cycle had the highlight outside the letters and
    -- the title just sat there as dark grey text.
    local cfg = A.CHROME[opts.name or ""] or A.CHROME.__default
    titlePattern = A.chromePattern(cfg)
    titleGrad = mk("UIGradient", {
      Color = A.chromeSeq(titlePattern, 0),
      Rotation = cfg.rot,
      Parent = titleLbl,
    })
    titleGrad:SetAttribute("Speed", cfg.speed)
  end

  local sub = A.text({
    Text = opts.desc or "", font = T.font.body, size = T.size.micro,
    colour = T.c.textMute, Position = UDim2.fromOffset(24, 60),
    Size = UDim2.new(1, -48, 0, 14), Parent = head,
  })
  -- (object, property) pairs, not bare labels: the heading is no longer all
  -- text -- the chrome title fades on GroupTransparency -- and a fade list that
  -- assumes TextTransparency would silently skip whatever is not a label.
  local heads = {
    { eyebrow,  "TextTransparency" },
    { titleLbl, "TextTransparency" },
    { sub,      "TextTransparency" },
  }

  local grp = mk("CanvasGroup", {
    Position = UDim2.fromOffset(0, 88), Size = UDim2.new(1, 0, 1, -88),
    BackgroundTransparency = 1, GroupTransparency = 1,
    ClipsDescendants = true,          -- or the scroll runs up under the heading
    Parent = page,
  })

  local scroll = A.scroll({ Parent = grp, gap = T.gap.md, Name = "PageScroll" })
  L.pad(4, 24, 24, 24, scroll)

  local tab = { index = index, name = opts.name, button = btn, label = label,
                glyph = glyph, chrome = isChrome, iconVid = iconVid,
                page = page, group = grp, head = head, heads = heads,
                titleGrad = titleGrad, titlePattern = titlePattern,
                body = scroll, sub = sub, navY = navY, window = self }

  A.interactive(btn, {
    radius = T.r.md, hoverAlpha = 0.97, pressAlpha = 0.95,
    onClick = function() self:select(index) end,
    -- The chrome tile grows and brightens under the pointer. Springs, so moving
    -- quickly along the nav makes each icon catch and release rather than
    -- snapping between two states.
    onState = function(st)
      if not isChrome then return end
      local on = (self.active == index)
      local big = st.hovered and 34 or 30
      M.to(glyph, "Size", UDim2.fromOffset(big, big), "fast")
      self._hover = st.hovered and index or (self._hover == index and nil or self._hover)
      if not on and not iconVid then
        M.to(glyph, "ImageTransparency", st.hovered and 0.12 or 0.5, "fast")
      end
    end,
  })

  if L.Palette then
    L.Palette.add(page, opts.name or ("Tab " .. index), opts.desc or "")
  end
  self.tabs[index] = tab
  self._navY[index] = nil
  if index == 1 then self:select(1, true) end
  return tab
end

function Window:select(index, immediate)
  local tab = self.tabs[index]
  if not tab or self.active == index then return end
  -- A popover belongs to the page that opened it; leaving that page must take it
  -- with you, or it hangs over the new one. Closed through its OWNER, not by
  -- destroying the overlay behind its back -- doing that left the dropdown still
  -- flagged open, so its next click closed nothing and it read as broken.
  if L.C and L.C.closePopovers then L.C.closePopovers() end
  if self.overlay then
    for _, d in ipairs(self.overlay:GetChildren()) do pcall(function() d:Destroy() end) end
  end
  local prev = self.active and self.tabs[self.active]
  self.active = index

  local y = tab.navY
  self.pill.Visible, self.pillBar.Visible = true, true
  local setter = immediate and M.set or M.to
  setter(self.pill, "Position", UDim2.fromOffset(0, y), "base")
  setter(self.pillBar, "Position", UDim2.fromOffset(-12, y + TAB_H * 0.275), "base")

  for i, t in ipairs(self.tabs) do
    local on = (i == index)
    M.to(t.label, "TextColor3", on and T.c.text or T.c.textMute, "fast")
    if t.chrome then
      -- brightness, not hue. Tinting a rendered chrome object toward the accent
      -- flattens every reflection in it.
      if t.iconVid then
        t.iconVid.rest = on and 0 or 0.5
        local cur = t.iconVid.labels[t.iconVid.shown]
        if cur then M.to(cur, "ImageTransparency", t.iconVid.rest, "fast") end
      else
        M.to(t.glyph, "ImageTransparency", on and 0 or 0.5, "fast")
      end
    else
      for _, d in ipairs(t.glyph:GetDescendants()) do
        if d:IsA("Frame") then
          M.to(d, "BackgroundColor3", on and T.c.accent or T.c.textMute, "fast")
        elseif d:IsA("UIStroke") then
          M.to(d, "Color", on and T.c.accent or T.c.textMute, "fast")
        end
      end
    end
  end

  if prev and prev ~= tab then
    local old = prev
    A.groupTo(old.group, 1, "fast")
    M.to(old.group, "Position", UDim2.fromOffset(0, 98), "fast")
    -- the heading leaves with the body it belongs to, or the two pages' titles
    -- sit on top of each other for the whole handover
    if old.heads then
      for _, h in ipairs(old.heads) do M.to(h[1], h[2], 1, "fast") end
      M.to(old.head, "Position", UDim2.fromOffset(0, 10), "fast")
    end
    -- DERIVED FROM THE TOKEN, NOT TYPED. 0.18 was the "fast" duration at scale
    -- 1.0 and nothing else -- on the Calm profile that token runs 1.4x longer,
    -- so the page was hidden 71% of the way through its own fade and the swap
    -- popped. Motion.resolve applies the live profile scale, so this tracks
    -- whatever the user picked.
    local fadeOut = select(1, M.resolve("fast"))
    task.delay(fadeOut + 0.04, function()
      if L.live() and self.active ~= old.index then old.page.Visible = false end
    end)
  end

  -- the chrome title for this page is built the first time it is opened

  tab.page.Visible = true
  if immediate then
    A.groupSet(tab.group, 0)
    M.set(tab.group, "Position", UDim2.fromOffset(0, 88))
    if tab.heads then
      M.set(tab.head, "Position", UDim2.fromOffset(0, 0))
      for _, h in ipairs(tab.heads) do M.set(h[1], h[2], 0) end
    end
  else
    M.set(tab.group, "Position", UDim2.fromOffset(0, 102))
    A.groupSet(tab.group, 1)
    A.groupTo(tab.group, 0, "base")
    M.to(tab.group, "Position", UDim2.fromOffset(0, 88), "slow")
    if tab.heads then
      M.set(tab.head, "Position", UDim2.fromOffset(0, 14))
      for _, h in ipairs(tab.heads) do M.set(h[1], h[2], 1) end
      M.to(tab.head, "Position", UDim2.fromOffset(0, 0), "slow")
      for _, h in ipairs(tab.heads) do M.to(h[1], h[2], 0, "base") end
    end
  end
  -- Return to the top. AutomaticCanvasSize grows the canvas AFTER the one-shot
  -- reset in A.scroll, so a page built later can end up scrolled with its first
  -- heading clipped above the viewport.
  -- reset through the controller: writing CanvasPosition alone would leave the
  -- spring still aiming at the old offset and it would scroll straight back
  A.scrollReset(tab.body)
  task.defer(function()
    if tab.body.Parent then A.scrollReset(tab.body) end
  end)

  -- deferred so the rows have been laid out and can be sorted by where they
  -- actually sit; skipped on the programmatic path, where nobody is watching
  if not immediate then
    task.defer(function()
      if L.live() and self.active == index then self:_cascade(tab) end
    end)
  end

  -- ONLY A TAB THE USER CHOSE IS WORTH REMEMBERING. This wrote on every select,
  -- including the `self:select(1, true)` that Window:tab fires while the nav is
  -- still being built -- so construction overwrote the saved tab with 1 before
  -- anything had a chance to read it back, and "reopen where you left off" could
  -- never have worked no matter how it was restored. `immediate` is true for
  -- exactly the programmatic paths (construction and restore) and false for the
  -- click handler, which makes it the intent flag this needs.
  if L.Cfg and not immediate then L.Cfg.set("tab", index) end
  if self.onTab then L.try("window.onTab", self.onTab, tab) end
end

-- ---------------------------------------------------------------- chrome

function Window:show(transitionGen)
  if transitionGen then
    if self._transitionGen ~= transitionGen then return self end
  else
    self._transitionGen = (self._transitionGen or 0) + 1
    transitionGen = self._transitionGen
  end
  self.hidden = false
  self.shell.Visible, self.root.Visible = true, true
  A.groupSet(self.root, 1)
  M.set(self.root, "Size", UDim2.fromOffset(self.width * 0.95, self.height * 0.95))
  -- Restore authored child alpha before the shared group clock starts.
  if self.body then M.set(self.body, "BackgroundTransparency", 0) end
  if self.wash then M.set(self.wash, "BackgroundTransparency", 0) end
  local fadeDur = select(1, M.resolve("base"))
  local fadeToken = { fadeDur, 0 }
  A.groupTo(self.root, 0, fadeToken)
  M.to(self.root, "Size", UDim2.fromOffset(self.width, self.height), "slow")
  if self.shadow then
    local sp = (self.shadowSpread or 34) * 2
    M.set(self.shadow, "ImageTransparency", 1)
    M.set(self.shadow, "Size", UDim2.new(0.97, sp, 0.97, sp))
    M.to(self.shadow, "ImageTransparency", self.shadowRest, fadeToken)
    M.to(self.shadow, "Size", UDim2.new(1, sp, 1, sp), "slow")
  end
  -- The root CanvasGroup is the one opacity clock. Animating the body again
  -- multiplied two fades, so the outline/text appeared a few frames before the
  -- dark plate in recordings. Restore child resting alpha synchronously.
  M.to(self.dock, "Position", Window.DOCK_OUT, "base")
  A.blurTo(Window.BLUR, "slow")
  M.to(self.scrim, "BackgroundTransparency", 0.5, fadeToken)
  return self
end

function Window:hide(token, keepDock, transitionGen)
  token = token or "fast"
  if transitionGen then
    if self._transitionGen ~= transitionGen then return self end
  else
    self._transitionGen = (self._transitionGen or 0) + 1
    transitionGen = self._transitionGen
  end
  self.hidden = true
  -- an open menu must not be waiting for you when the window comes back
  if L.C and L.C.closePopovers then L.C.closePopovers() end
  -- The drawer lives inside the shell, so it would be carried and squashed by
  -- the morph. It is handed its own window instead and becomes draggable, and
  -- comes back when this one does.
  if L.Side and L.Side.open and L.Side.detach then L.Side.detach() end
  -- ONE TOKEN FOR EVERY OUTGOING PROPERTY. The panel was leaving on `fast` while
  -- the scrim and blur left on `base`, so the dimming lingered after the window
  -- had already gone. Anything that arrives together has to leave together.
  local dur = select(1, M.resolve(token))
  local opacityToken = { dur, 0 }
  A.groupTo(self.root, 1, opacityToken)
  M.to(self.root, "Size", UDim2.fromOffset(self.width * 0.97, self.height * 0.97), token)
  -- Shadow geometry is outside the root group, so it receives the exact same
  -- duration explicitly. A shorter shadow/plate clock produced the dark edge
  -- lead visible in the minimise recording.
  if self.shadow then
    local sp = (self.shadowSpread or 34) * 2
    M.to(self.shadow, "ImageTransparency", 1, opacityToken)
    M.to(self.shadow, "Size", UDim2.new(0.97, sp, 0.97, sp), token)
  end

  -- Body, wash, icons and text leave through GroupTransparency. THE STROKE
  -- DOES NOT -- it is parented to the CanvasGroup rather than being one of
  -- the children the group composites, so it kept drawing at its resting 0.30
  -- for the whole hide: a solid rounded outline around an empty rectangle,
  -- snapped away only by Visible = false at the very end. A.groupTo carries
  -- the stroke with the group. Their authored resting values stay intact for
  -- an interruption-safe restore.
  if self.body then M.set(self.body, "BackgroundTransparency", 0) end
  if self.wash then M.set(self.wash, "BackgroundTransparency", 0) end
  A.blurTo(0, token)
  M.to(self.scrim, "BackgroundTransparency", 1, opacityToken)

  -- THE DOCK LEAVES TOO. It is the one drawn thing outside the root CanvasGroup
  -- that hide() never touched -- an opaque 227x58 bar parked just off the top
  -- edge. Anything the group fade cannot reach has to be faded by name, or it
  -- outlives the window that owned it.
  -- minimise owns the dock while the genie runs, so it opts out of this
  if not keepDock then M.to(self.dock, "Position", Window.DOCK_OUT, token) end

  -- DERIVED, NOT TYPED. 0.30 was the `fast` duration at scale 1.0 and nothing
  -- else: on the Calm profile the fade needs 0.35 s, so the window was switched
  -- off 15% before it finished fading and popped. Third instance of this exact
  -- bug in the project -- a literal that silently mirrors a motion token.
  task.delay(dur + 0.06, function()
    if L.live() and self.hidden and self._transitionGen == transitionGen then
      self.root.Visible, self.shell.Visible = false, false
    end
  end)
  return self
end

-- Everything on `o` that is currently drawn, with the value it rests at.
local function drawnParts(o, into)
  into = into or {}
  for _, p in ipairs({ "BackgroundTransparency", "TextTransparency",
                       "ImageTransparency", "Transparency" }) do
    local ok, v = pcall(function() return o[p] end)
    if ok and type(v) == "number" and v < 1 then into[#into + 1] = { o, p, v } end
  end
  return into
end

function Window:minimise()
  if self._morphBusy then return end
  self._transitionGen = (self._transitionGen or 0) + 1
  local transitionGen = self._transitionGen
  self._morphBusy = true

  -- THE PILL IS PLACED FIRST AND REVEALED LAST. Putting it at its resting spot
  -- immediately but invisible means the genie has a real target to measure, and
  -- fading it up as the bands land makes the stack look like it BECAME the
  -- pill rather than pulling up alongside one that was already there.
  M.stop(self.dock, "Position")
  self.dock.Position = Window.DOCK_IN

  -- CAPTURED ONCE, EVER. minimise() sets these to transparent and restore() has
  -- to put them back; re-reading them per minimise meant the second one sampled
  -- a dock the first had already hidden, recorded "invisible" as its resting
  -- state, and the pill never appeared again. Same trap as the row cascade.
  if not self._dockParts then
    local parts = drawnParts(self.dock)
    -- BOTH pin bars, not just the right-hand one. Pins now fill left as well as
    -- right, and each strip is its own CanvasGroup -- so treating only the
    -- first as a single unit left the left-hand chips being walked
    -- element-by-element, revealing on their own clocks while the right side
    -- faded as one.
    local pinBars = (L.Pins and L.Pins.bars) or (L.Pins and L.Pins.bar and { L.Pins.bar }) or {}
    local function isBar(x)
      for _, b in ipairs(pinBars) do if x == b then return b end end
      return nil
    end
    local function insideBar(x)
      for _, b in ipairs(pinBars) do
        if b and x:IsDescendantOf(b) then return true end
      end
      return false
    end
    for _, x in ipairs(self.dock:GetDescendants()) do
      local b = isBar(x)
      if b then
        parts[#parts + 1] = { b, "GroupTransparency", b.GroupTransparency }
      elseif not insideBar(x) then
        drawnParts(x, parts)
      end
    end
    self._dockParts = parts
  end
  local pill = self._dockParts
  for _, e in ipairs(pill) do M.set(e[1], e[2], 1) end

  -- THE SATURN HAS TO BE PAUSED, NOT JUST HIDDEN. It runs its own playback loop,
  -- which re-shows the current frame the instant it advances -- so walking the
  -- pill's parts hid it for a sixteenth of a second and then it came straight
  -- back, leaving the logo hanging alone at the pill's destination while the
  -- morph was still travelling. Caught on video: a Saturn floating in the sky
  -- above a curve that had not arrived yet.
  if self.dockOrb then
    self.dockOrb:pause()
    for _, lb in ipairs(self.dockOrb.labels) do lb.ImageTransparency = 1 end
  end

  local function revealAt(p)
    if self._transitionGen ~= transitionGen then return end
    local a = math.clamp((p - 0.78) / 0.22, 0, 1)
    a = a * a * (3 - 2 * a)
    for _, e in ipairs(pill) do
      if e[1].Parent then e[1][e[2]] = 1 + (e[3] - 1) * a end
    end
  end
  self:_morph(function()
    if self._transitionGen ~= transitionGen then return end
    revealAt(1)
    self._morphBusy = false
    if self.dockOrb then self.dockOrb:play() end
  end, revealAt)

  -- the real panel goes at once: the proxy is what the eye is following
  self:hide("fast", true, transitionGen)
end

function Window:restore()
  self._transitionGen = (self._transitionGen or 0) + 1
  local transitionGen = self._transitionGen
  -- put the detached drawer back where it belongs before anything animates
  if L.Side and L.Side.detached and L.Side.reattach then
    task.defer(function()
      if self._transitionGen == transitionGen then L.try("side.reattach", L.Side.reattach) end
    end)
  end
  -- CANCEL ANY GENIE STILL IN FLIGHT. _morphBusy is otherwise only cleared when
  -- the animation finishes, so restoring part-way through left it set and the
  -- NEXT minimise returned immediately and did nothing -- a dead button with no
  -- error to explain it. Reopening the window is an explicit "stop that".
  self._morphBusy = false
  local stale = L.host():FindFirstChild("LumenMorph")
  if stale then pcall(function() stale:Destroy() end) end

  -- and hand the pill its opacity back, or the next minimise has nothing to
  -- reveal: minimise() is what set these to 1, so restore() is what must undo it
  if self._dockParts then
    for _, e in ipairs(self._dockParts) do
      if e[1].Parent then M.set(e[1], e[2], e[3]) end
    end
  end
  if self.dockOrb then self.dockOrb:play() end

  M.to(self.dock, "Position", Window.DOCK_OUT, "base")
  self:show(transitionGen)
end

-- TWO THINGS THE HOTKEY COULD REASONABLY MEAN, so it is a setting rather than a
-- decision made for everyone. Hiding drops the window instantly and brings it
-- straight back -- fastest, and nothing is left on screen. Minimising runs the
-- morph down to the dock pill, which takes longer but leaves a visible handle
-- and reads as the window going somewhere rather than blinking out.
--
-- Minimise is the default because the pill is the discoverable way back: hide
-- leaves nothing on screen, so anyone who forgets the key has lost the hub.
function Window:toggle()
  local wantMinimise = not (L.Cfg and L.Cfg.data.toggleAction == "Hide")

  -- minimise routes through hide, so `hidden` already covers "parked on the
  -- pill" as well as "gone" -- one branch brings it back from either
  if self.hidden then
    self:restore()
    return
  end
  if wantMinimise and self.minimise then
    self:minimise()
  else
    self:hide()
  end
end

function Window:subtitle(text)
  if self.subtitleLbl then self.subtitleLbl.Text = tostring(text) end
end

-- ---------------------------------------------------------------- input

-- Persist where and how big the window is, debounced by Cfg.
function Window:_saveGeom()
  if not L.Cfg then return end
  local p, sz = self.shell.Position, self.root.Size
  L.Cfg.set("geom", {
    x = math.floor(p.X.Offset), y = math.floor(p.Y.Offset),
    w = math.floor(sz.X.Offset), h = math.floor(sz.Y.Offset),
  })
end

-- EDGE SNAPPING IS GONE, AND SO IS THE CODE FOR IT. It pulled the window to
-- places the cursor was not, and its confirmation flash -- a half-transparent
-- accent wash over the entire panel -- fired again every time a snap line was
-- crossed, which is what read as the window flickering blue while being
-- dragged. A drag is the one interaction that should have no opinions.

-- The minimise pill's two positions, named once. They were typed out at four
-- call sites with three different motion tokens between them, which is how the
-- dock ended up leaving on a different clock from the window it belongs to.
Window.DOCK_OUT = UDim2.new(0.5, 0, 0, -60)
Window.DOCK_IN  = UDim2.new(0.5, 0, 0, 18)

-- ---------------------------------------------------------------- morph
--
-- Minimising does not shrink the window, it REDRAWS it as a line and folds that
-- line away: the panel's outline contracts to a circle, the circle folds into an
-- infinity, and the infinity spins down into the pill.
--
-- Roblox has no vector paths, so the curve is a string of small frames placed on
-- it each frame. Two bits of maths do all the work and neither needs a lookup
-- table:
--
--   SUPERELLIPSE for the outline. |x/a|^n + |y/b|^n = 1 is an ellipse at n = 2
--   and approaches a rectangle as n grows. Sweeping the exponent turns the
--   window's rounded rectangle into a circle in one continuous family -- there
--   is no rectangle-to-circle interpolation to hand-write.
--
--   GERONO LEMNISCATE for the fold. A circle is (cos t, sin t); the figure-eight
--   is (cos t, sin t cos t). Only Y differs, so the morph is a single lerp on
--   one coordinate: y = sin t * (1 + m(cos t - 1)). At m = 0 it is exactly a
--   circle, at m = 1 exactly an infinity, and every value between is a clean
--   in-between rather than an approximation.

local MORPH_SEGS = 60
local MORPH_TOK  = { 0.95, -0.10 }   -- one long overdamped sweep, no bounce

-- The morph's bloom, as a fraction of the SHORTER viewport axis. 0.62 keeps it
-- clearly a glow around the panel rather than a wash across the display; the
-- uncapped version reached 2256 px on a 2560x1369 screen.
local MORPH_GLOW_CAP = 0.62
-- The span, in pixels, at which the bloom emits its full authored opacity.
-- Larger glows are faded in proportion so the light delivered stays even.
local MORPH_GLOW_REF = 620

-- 0..1 with eased ends, over an arbitrary window of the timeline
local function ramp(p, from, to)
  if to <= from then return p >= to and 1 or 0 end
  local t = math.clamp((p - from) / (to - from), 0, 1)
  return t * t * (3 - 2 * t)
end

function Window:_morph(onDone, onProgress)
  local dock = self.dock
  local r = { x = self.root.AbsolutePosition.X, y = self.root.AbsolutePosition.Y,
              w = self.root.AbsoluteSize.X,     h = self.root.AbsoluteSize.Y }
  local d = { x = dock.AbsolutePosition.X, y = dock.AbsolutePosition.Y,
              w = dock.AbsoluteSize.X,     h = dock.AbsoluteSize.Y }
  if r.w < 4 or d.w < 4 then if onDone then onDone() end return 0 end

  -- own ScreenGui, no UIScale: everything below is raw screen pixels, which is
  -- the only space the window rect and the dock rect are both measured in
  local gui = mk("ScreenGui", {
    Name = "LumenMorph", ResetOnSpawn = false, IgnoreGuiInset = true,
    ZIndexBehavior = Enum.ZIndexBehavior.Sibling, DisplayOrder = 12,
  })
  gui.Parent = L.host()

  local probe = mk("Frame", { Size = UDim2.fromOffset(1, 1),
    Position = UDim2.fromOffset(0, 0), BackgroundTransparency = 1, Parent = gui })
  L.RunService.Heartbeat:Wait()
  if not gui.Parent then return 0 end
  local k = probe.AbsolutePosition
  probe:Destroy()

  local glow = A.img and A.img.glow and mk("ImageLabel", {
    AnchorPoint = Vector2.new(0.5, 0.5), Size = UDim2.fromOffset(r.w, r.h),
    BackgroundTransparency = 1, Image = A.img.glow,
    ImageColor3 = T.c.accent, ImageTransparency = 0.86,
    ZIndex = 1, Parent = gui,
  })

  local dotW = math.max(3, math.floor(r.h / 150))
  local segs = {}
  for i = 1, MORPH_SEGS do
    local s = mk("Frame", {
      AnchorPoint = Vector2.new(0.5, 0.5),
      Size = UDim2.fromOffset(dotW, dotW),
      BackgroundColor3 = T.c.text, BorderSizePixel = 0,
      ZIndex = 3, Name = "Seg", Parent = gui,
    })
    L.corner(999, s)
    segs[i] = s
  end

  local ar, br = r.w / 2, r.h / 2
  local R = math.min(r.w, r.h) * 0.30          -- radius of the circle stage
  local cx0, cy0 = r.x + ar, r.y + br
  local cx1, cy1 = d.x + d.w / 2, d.y + d.h / 2

  -- RESOLVED, NOT RAW. This built its spring straight from MORPH_TOK while the
  -- timeout below took the same token THROUGH Motion.resolve, so the two
  -- disagreed about how long the morph lasts the moment any motion profile was
  -- active: under a slower profile the spring finished early and the morph sat
  -- waiting, and under a faster one the timeout cut it off mid-flight. It also
  -- meant the minimise was the one animation in the hub that ignored the motion
  -- profile entirely -- which is exactly why it still felt snappy after the
  -- profile was corrected.
  local morphDur, morphBounce = M.resolve(MORPH_TOK)
  local spring = L.Spring.new(morphDur, morphBounce, 0)
  spring:to(1)

  local conn
  conn = L.RunService.RenderStepped:Connect(function(dt)
    if not gui.Parent then if conn then conn:Disconnect() end return end
    local p = math.clamp(spring:step(dt), 0, 1)
    if onProgress then L.try("window.morphProgress", onProgress, p) end

    local toCircle = ramp(p, 0.00, 0.42)   -- rectangle outline -> circle
    local toInf    = ramp(p, 0.30, 0.72)   -- circle -> infinity
    local away     = ramp(p, 0.62, 1.00)   -- shrink and travel to the pill
    local fade     = ramp(p, 0.80, 1.00)

    local scale = 1 - 0.86 * away
    local cx = cx0 + (cx1 - cx0) * away
    local cy = cy0 + (cy1 - cy0) * away
    local rot = p * 2.6                     -- radians; the fold turns as it goes

    -- exponent sweeps 8 (near-rectangular) down to 2 (a true ellipse)
    local n = 8 - 6 * toCircle
    local cosR, sinR = math.cos(rot), math.sin(rot)

    for i, s in ipairs(segs) do
      local t = (i - 1) / MORPH_SEGS * math.pi * 2
      local ct, st = math.cos(t), math.sin(t)

      -- outline of the panel, as a superellipse
      local ex = (ct >= 0 and 1 or -1) * math.abs(ct) ^ (2 / n)
      local ey = (st >= 0 and 1 or -1) * math.abs(st) ^ (2 / n)
      local rx, ry = ar * ex, br * ey

      -- the symbol: circle at toInf 0, infinity at toInf 1
      local ix = R * ct
      local iy = R * st * (1 + toInf * (ct - 1))

      local x = rx + (ix - rx) * toCircle
      local y = ry + (iy - ry) * toCircle
      x, y = x * scale, y * scale
      local px = cx + x * cosR - y * sinR
      local py = cy + x * sinR + y * cosR

      s.Position = UDim2.fromOffset(px - k.X, py - k.Y)
      s.BackgroundTransparency = fade

      -- a brighter head runs round the curve, so the line reads as drawn
      -- rather than as a ring of dots sitting still
      local head = ((i / MORPH_SEGS) + p * 1.7) % 1
      local lit = head < 0.14 and (1 - head / 0.14) or 0
      s.BackgroundColor3 = T.c.text:Lerp(T.c.accent, 1 - lit * 0.85)
      local sz = dotW * (1 + lit * 1.25) * (0.5 + 0.5 * scale)
      s.Size = UDim2.fromOffset(math.max(sz, 1), math.max(sz, 1))
    end

    if glow then
      -- WHAT THE EYE READS IS AREA x OPACITY, NOT OPACITY.
      --
      -- This was r.w * scale * 1.5 at a flat 0.80. r is the whole window rect,
      -- so on a 1507x1139 panel the first frame drew a 2256x1704 glow -- larger
      -- than a 2560x1369 screen -- in a ScreenGui at DisplayOrder 12, i.e. over
      -- the game and over the hub. On a dark game that is a bloom. On a bright
      -- one it is a screen-wide wash with a soft edge, which is what a user
      -- photographed and reasonably called the visuals leaking.
      --
      -- Two changes. The size is capped against the VIEWPORT, so a bigger panel
      -- or a bigger monitor cannot turn a local bloom into full-bleed. And the
      -- opacity now falls as the glow grows, holding the total light roughly
      -- constant -- a big soft glow and a small tight one deliver the same
      -- amount of light, which is the thing that was actually wrong.
      local vp = L.viewport()
      local cap = math.min(vp.X, vp.Y) * MORPH_GLOW_CAP
      local gw = math.min(r.w * scale * 1.5, cap)
      local gh = math.min(r.h * scale * 1.5, cap)
      glow.Position = UDim2.fromOffset(cx - k.X, cy - k.Y)
      glow.Size = UDim2.fromOffset(gw, gh)

      local opaque = 1 - (0.80 + 0.20 * fade)          -- what it used to emit
      local span = math.max(math.sqrt(gw * gh), 1)
      opaque = opaque * math.clamp(MORPH_GLOW_REF / span, 0.30, 1)
      glow.ImageTransparency = 1 - opaque
    end
  end)

  local total = morphDur + 0.12          -- one source of truth with the spring
  task.delay(total, function()
    if conn then conn:Disconnect() end
    pcall(function() gui:Destroy() end)
    if onDone then onDone() end
  end)
  return total
end


-- ---------------------------------------------------------------- cascade
--
-- Rows arrive one after another instead of the page appearing all at once.
--
-- It has to be an opacity stagger, not a slide: the page uses a UIListLayout,
-- which owns child Position outright, so anything moved is snapped straight back.

local FADE_PROP = {
  Frame = "BackgroundTransparency", TextLabel = "TextTransparency",
  TextButton = "TextTransparency", ImageLabel = "ImageTransparency",
  UIStroke = "Transparency",
}

-- Every part of a row that is currently drawn, with the value it rests at.
local function rowParts(row)
  local parts = {}
  local function add(o)
    local p = FADE_PROP[o.ClassName]
    if not p then return end
    local v = o[p]
    -- already invisible at rest: fading it changes nothing and costs a spring
    if type(v) == "number" and v < 1 then parts[#parts + 1] = { o, p, v } end
  end
  add(row)
  for _, d in ipairs(row:GetDescendants()) do add(d) end
  return parts
end

function Window:_cascade(tab)
  if not self.cascade or self.cascade <= 0 then return end

  -- REST VALUES ARE CAPTURED ONCE, EVER. Reading them at cascade time looks
  -- right until you change tabs twice quickly: the second pass samples rows the
  -- first pass has already faded, records "invisible" as their resting state,
  -- and settles them there. The page comes back permanently blank.
  if not tab._cascadeParts then
    local rows = {}
    for _, c in ipairs(tab.body:GetChildren()) do
      if c:IsA("GuiObject") then rows[#rows + 1] = c end
    end
    -- sorted by where they actually sit: LayoutOrder is 0 for most of these, so
    -- child order would not match reading order
    table.sort(rows, function(a, b) return a.AbsolutePosition.Y < b.AbsolutePosition.Y end)
    local parts = {}
    for i, row in ipairs(rows) do
      if i > 12 then break end        -- past the fold nobody sees the stagger
      parts[i] = rowParts(row)
    end
    tab._cascadeParts = parts
  end

  -- CANCELLABLE. This used to fan out one bare M.after per element, which
  -- nothing could call back: switch tabs twice quickly and the first page's
  -- cascade kept firing into a page you had already left, fading rows back in
  -- underneath the new one. M.seq hands back a handle, so starting a cascade
  -- cancels the one before it.
  if self._cascadeSeq then self._cascadeSeq:cancel() end
  for _, group in ipairs(tab._cascadeParts) do
    for _, e in ipairs(group) do
      if e[1].Parent then M.set(e[1], e[2], 1) end
    end
  end
  self._cascadeSeq = M.seq(tab._cascadeParts, function(group)
    for _, e in ipairs(group) do
      if e[1].Parent then M.to(e[1], e[2], e[3], "base") end
    end
  end, { step = self.cascade, cap = 0.34 })
end

-- MOMENTUM ON RELEASE, because a window that stops dead the instant you let go
-- feels like a decal being repositioned rather than an object being moved. The
-- drag itself stays absolutely direct -- one-to-one with the cursor, no easing,
-- no lag, because anything else makes it feel broken -- and the glide happens
-- only after the button comes up.
--
-- The throw is measured from the last few frames of actual pointer motion, not
-- from the total drag, so flicking it and then pausing before release does
-- nothing: you get the momentum you were carrying at the moment you let go.
function Window:_drag()
  local dragging, startAbs, startOffset, startMouse
  local lastPos, lastT, vel = nil, nil, Vector2.new(0, 0)

  self.header.InputBegan:Connect(function(i)
    if i.UserInputType == Enum.UserInputType.MouseButton1
      or i.UserInputType == Enum.UserInputType.Touch then
      -- double click the header to maximise / restore
      local now = os.clock()
      if self._lastHeaderClick and now - self._lastHeaderClick < 0.32 then
        self._lastHeaderClick = nil
        self:maximise()
        return
      end
      self._lastHeaderClick = now
      dragging = true
      -- the shell is anchored at its centre, so its centre in screen pixels is
      startAbs = self.shell.AbsolutePosition + self.shell.AbsoluteSize / 2
      startOffset = Vector2.new(self.shell.Position.X.Offset,
                                self.shell.Position.Y.Offset)
      startMouse = i.Position
      lastPos, lastT, vel = i.Position, os.clock(), Vector2.new(0, 0)
      M.stop(self.shell, "Position")
    end
  end)

  L.hold(L.UIS.InputChanged:Connect(function(i)
    if not dragging then return end
    if i.UserInputType == Enum.UserInputType.MouseMovement
      or i.UserInputType == Enum.UserInputType.Touch then
      -- THE WHOLE DRAG LIVES IN REAL SCREEN PIXELS, AND CONVERTS ONCE AT THE END.
      --
      -- The window sits under a UIScale, so a Position OFFSET is in pre-scale
      local sc = (self.scaleObj and self.scaleObj.Scale) or 1
      local d = i.Position - startMouse
      local px, py = startAbs.X + d.X, startAbs.Y + d.Y

      -- the only rule left: keep a grabbable strip on screen, so the window can
      -- always be dragged back rather than lost off an edge
      local vp = L.viewport()
      local hw, hh = self.shell.AbsoluteSize.X / 2, self.shell.AbsoluteSize.Y / 2
      local KEEP = 90
      px = math.clamp(px, -hw + KEEP, vp.X + hw - KEEP)
      py = math.clamp(py, -hh + KEEP, vp.Y + hh - KEEP)

      -- carry the pointer's own speed, smoothed, so one stuttering frame does
      -- not decide the throw
      local now = os.clock()
      if lastPos and lastT and now > lastT then
        local dt = now - lastT
        if dt > 0.002 then
          local inst = Vector2.new((i.Position.X - lastPos.X) / dt,
                                   (i.Position.Y - lastPos.Y) / dt)
          vel = vel:Lerp(inst, 0.4)
          lastPos, lastT = i.Position, now
        end
      end

      M.stop(self.shell, "Position")
      self.shell.Position = UDim2.fromOffset(
        startOffset.X + (px - startAbs.X) / sc,
        startOffset.Y + (py - startAbs.Y) / sc)
    end
  end))

  L.hold(L.UIS.InputEnded:Connect(function(i)
    if i.UserInputType == Enum.UserInputType.MouseButton1
      or i.UserInputType == Enum.UserInputType.Touch then
      if dragging then
        dragging = false

        -- GLIDE. A spring toward a point a fraction of a second ahead along the
        -- release velocity: overdamped, so it slides and settles rather than
        -- overshooting and bouncing back, which would read as elastic rather
        -- than heavy. Skipped entirely below a threshold so a careful
        -- repositioning lands exactly where it was put.
        local speed = vel.Magnitude
        if speed > 220 and L.Cfg and L.Cfg.data.dragGlide ~= false then
          local sc = (self.scaleObj and self.scaleObj.Scale) or 1
          local carry = math.clamp(speed / 4200, 0, 1) * 0.16
          local vp = L.viewport()
          local hw = self.shell.AbsoluteSize.X / 2
          local hh = self.shell.AbsoluteSize.Y / 2
          local KEEP = 90
          local absNow = self.shell.AbsolutePosition + self.shell.AbsoluteSize / 2
          local tx = math.clamp(absNow.X + vel.X * carry, -hw + KEEP, vp.X + hw - KEEP)
          local ty = math.clamp(absNow.Y + vel.Y * carry, -hh + KEEP, vp.Y + hh - KEEP)
          local cur = self.shell.Position
          M.to(self.shell, "Position", UDim2.fromOffset(
            cur.X.Offset + (tx - absNow.X) / sc,
            cur.Y.Offset + (ty - absNow.Y) / sc), "gentle")
          M.after(0.42, function() self:_saveGeom() end)
        else
          self:_saveGeom()
        end
        vel = Vector2.new(0, 0)
      end
    end
  end))
end

-- ---------------------------------------------------------------- resize

function Window:_resize()
  local grip = mk("Frame", {
    AnchorPoint = Vector2.new(1, 1),
    Position = UDim2.new(1, -3, 1, -3),
    Size = UDim2.fromOffset(18, 18),
    BackgroundTransparency = 1, ZIndex = 20,
    Name = "Grip", Parent = self.root,
  })
  -- three short diagonals, the universal resize affordance
  for i = 0, 2 do
    local bar = mk("Frame", {
      AnchorPoint = Vector2.new(1, 1),
      Position = UDim2.new(1, -i * 5, 1, 0),
      Size = UDim2.fromOffset(1, 12 - i * 4),
      Rotation = 45,
      BackgroundColor3 = T.c.textOff, BorderSizePixel = 0,
      ZIndex = 21, Parent = grip,
    })
    local _ = bar
  end
  local hit = mk("TextButton", {
    Size = UDim2.fromScale(1, 1), BackgroundTransparency = 1, Text = "",
    AutoButtonColor = false, ZIndex = 22, Parent = grip,
  })
  self.grip = grip

  local sizing, startSize, startMouse
  hit.MouseButton1Down:Connect(function()
    sizing = true
    startSize = self.root.Size
    startMouse = L.UIS:GetMouseLocation()
    M.to(grip, "BackgroundTransparency", 1, "instant")
  end)

  L.hold(L.UIS.InputChanged:Connect(function(i)
    if not sizing then return end
    if i.UserInputType ~= Enum.UserInputType.MouseMovement then return end
    local m = L.UIS:GetMouseLocation()
    local sc = (self.scaleObj and self.scaleObj.Scale) or 1
    local vp = L.viewport()
    -- the drag happens in screen pixels; the size is authored in unscaled units,
    local dw = (m.X - startMouse.X) / sc
    local dh = (m.Y - startMouse.Y) / sc
    local w = math.clamp(startSize.X.Offset + dw * 2, self.minW, (vp.X - 24) / sc)
    local h = math.clamp(startSize.Y.Offset + dh * 2, self.minH, (vp.Y - 24) / sc)
    self.width, self.height = math.floor(w), math.floor(h)
    self.root.Size = UDim2.fromOffset(self.width, self.height)
    self.shell.Size = UDim2.fromOffset(self.width, self.height)
    M.stop(self.root, "Size")
  end))

  L.hold(L.UIS.InputEnded:Connect(function(i)
    if i.UserInputType == Enum.UserInputType.MouseButton1 and sizing then
      sizing = false
      self:_saveGeom()
    end
  end))
end

function Window:maximise()
  local vp = L.viewport()
  local sc = (self.scaleObj and self.scaleObj.Scale) or 1
  if self._maxed then
    local g = self._preMax
    if g then
      M.to(self.root, "Size", UDim2.fromOffset(g.w, g.h), "slow")
      M.to(self.shell, "Position", g.pos, "slow")
      self.shell.Size = UDim2.fromOffset(g.w, g.h)
      self.width, self.height = g.w, g.h
    end
    self._maxed = false
  else
    self._preMax = { w = self.width, h = self.height, pos = self.shell.Position }
    local w = math.floor((vp.X - 48) / sc)
    local h = math.floor((vp.Y - 48) / sc)
    self.width, self.height = w, h
    M.to(self.root, "Size", UDim2.fromOffset(w, h), "slow")
    M.to(self.shell, "Position", UDim2.fromScale(0.5, 0.5), "slow")
    self.shell.Size = UDim2.fromOffset(w, h)
    self._maxed = true
  end
  task.delay(0.5, function() if L.live() then self:_saveGeom() end end)
  return self._maxed
end

function Window:_pointerInside()
  -- INSET-EXCLUDED, to match AbsolutePosition. This used to read
  -- GetMouseLocation, which is the inset-INCLUDED value, so the test was 58 px
  -- out -- the window counted the pointer as inside while it was still above
  -- the title bar, and stopped counting it 58 px before the bottom edge.
  local m = L.pointer()
  local p, sz = self.root.AbsolutePosition, self.root.AbsoluteSize
  return m.X >= p.X and m.X <= p.X + sz.X and m.Y >= p.Y and m.Y <= p.Y + sz.Y
end

function Window:_hotkeys(key)
  self.toggleKey = key or (L.Cfg and L.Cfg.keyCode()) or Enum.KeyCode.RightControl
  local NUM = {
    [Enum.KeyCode.One] = 1, [Enum.KeyCode.Two] = 2, [Enum.KeyCode.Three] = 3,
    [Enum.KeyCode.Four] = 4, [Enum.KeyCode.Five] = 5, [Enum.KeyCode.Six] = 6,
  }
  L.hold(L.UIS.InputBegan:Connect(function(i, typing)
    if typing or not L.live() then return end
    if i.KeyCode == self.toggleKey then self:toggle() return end
    -- ONLY WHILE THE POINTER IS OVER THE WINDOW. 1-5 is the Roblox tool hotbar;
    -- binding them globally means every weapon swap in a game also changes tab.
    local n = NUM[i.KeyCode]
    if n and not self.hidden and self.tabs[n] and self:_pointerInside() then
      self:select(n)
    end
  end))
end

end
do -- ==== lm_06_controls.lua ====
-- LUMEN :: CONTROLS
-- Toggle, slider, segmented, dropdown, keybind, input, buttons, log view.
--
-- Every control is the same row shape, so a new one inherits the right padding,
-- hover feel and disabled state for free.
--
-- A control never claims a state it did not reach: if its callback throws or
-- returns false, it puts itself back.

local L = getgenv().LUMEN
local T, M, A = L.T, L.Motion, L.A
local mk = L.mk

local C = {}
L.C = C

-- EVERY OPEN POPOVER, SO SOMETHING ELSE CAN SHUT IT.
--
-- Leaving a tab used to destroy the overlay's children directly, which removed
-- the menu from the screen but left the dropdown that owned it still believing
-- it was open -- so the next click on it ran the close path against a destroyed
-- frame and did nothing visible. The control looked dead until you clicked it
-- twice. Closing through the owner keeps the state and the pixels in agreement.
--
-- A plain list, pruned on use: weak keys cannot track this, because the frame is
-- an Instance held by the Roblox tree and would be collected out from under us.
C._pops = {}

-- Controls by their persistence id, so anything that changes a setting from
-- outside its own row can move the visible control too. Theme.setMotion has
-- called C.find since it was written and it has never existed, so that call has
-- been silently doing nothing -- which is how a dropdown ends up showing a
-- profile that is not the one running.
-- STRONG VALUES, PRUNED BY FRAME LIVENESS. Weak values could never work here:
-- every register() call site is fire-and-forget, so nothing else in Lua holds
-- the api and the collector took live controls at random.
C._reg = {}
C._regN = 0

-- The L._insts test from L.prune, applied to the frame each api carries.
function C.prune()
  local kept, n = {}, 0
  for id, h in pairs(C._reg) do
    local ok, parent = pcall(function() return h.frame and h.frame.Parent end)
    if ok and parent ~= nil then kept[id] = h n = n + 1 end
  end
  C._reg, C._regN = kept, n
  return n
end

function C.find(id)
  local h = C._reg[id]
  if h and h.frame and h.frame.Parent then return h end
  if h then C._reg[id] = nil C._regN = C._regN - 1 end
  return nil
end

local function register(opts, api)
  if not (opts and api) then return api end

  -- THE CONTRACT GOES ON EVERY CONTROL, not the one that happened to get it.
  -- register is the last line of every constructor, so the api is finished and
  -- the frame exists -- nothing else in this file is true of all of them. It
  -- sits above the id check on purpose: a control with no id still gets to be
  -- disabled and to declare a dependency.
  if api.frame and not api.setEnabled then
    api._label = api._label or opts.text or opts._id
    api.setEnabled = function(on, why)
      if api._ix then api._ix.setEnabled(on) end
      C.setEnabled(api, on, why)
    end
    C.dependent(api, opts)
  end

  -- Controls that never persist have no _id. Derive the id bindPersist would
  -- have used rather than leaving them unfindable, but do NOT write it back:
  -- C.pinnable reads opts._id as permission to persist a pin.
  local id = opts._id or (C.autoId and C.autoId(opts))
  if not id then return api end
  if C._reg[id] == nil then
    C._regN = C._regN + 1
    -- A rebuild re-registers the same ids, so growth past the watermark means
    -- genuinely new ones; sweep the retired generation instead of carrying it.
    if C._regN > 256 then C.prune() end
  end
  C._reg[id] = api
  return api
end

-- teardown destroys the frames; the table would otherwise outlive them
L.cleanup(function() C._reg, C._regN = {}, 0 end)

function C.closePopovers(instant)
  local kept = {}
  for _, p in ipairs(C._pops) do
    if p.frame and p.frame.Parent then
      kept[#kept + 1] = p
      L.try("popover.close", p.close, instant)
    end
  end
  C._pops = kept
  return #kept
end

-- read at construction, not captured at load -- see T.px
local function ROWH() return T.px("row") end

-- Register a control as a keyboard focus stop. Order of registration is order of
-- construction, which is top-to-bottom on the page, so Tab already moves the way
-- the eye does without anyone maintaining a tab-index.
--
-- A CONTROL WITH NO KEYBOARD BEHAVIOUR IS NOT A STOP. Tabbing onto something
-- that ignores every key is worse than skipping it: the ring stops somewhere
-- inert and the keyboard appears to have broken.
local function focusable(frame, spec)
  if not L.Focus or not frame then return nil end
  return L.Focus.register(frame, spec)
end

-- ---------------------------------------------------------------- scaffolding

local function row(parent, opts)
  local f = A.surface({
    Parent = parent, elev = 1, radius = T.r.md, sheen = true,
    Size = UDim2.new(1, 0, 0, opts.height or ROWH()),
    Name = "Row",
  })
  f.AutomaticSize = opts.grow and Enum.AutomaticSize.Y or Enum.AutomaticSize.None

  local hasDesc = opts.desc and opts.desc ~= ""
  A.text({
    Text = opts.text or "",
    font = T.font.medium, size = T.size.body, colour = T.c.text,
    Position = UDim2.fromOffset(12, hasDesc and 7 or 0),
    Size = hasDesc and UDim2.new(1, -(opts.rightRoom or 80), 0, 15)
                   or UDim2.new(1, -(opts.rightRoom or 80), 1, 0),
    truncate = true, Parent = f,
  })
  if hasDesc then
    A.text({
      Text = opts.desc,
      font = T.font.body, size = T.size.micro, colour = T.c.textMute,
      Position = UDim2.fromOffset(12, 23),
      Size = UDim2.new(1, -(opts.rightRoom or 80), 0, 13),
      truncate = true, Parent = f,
    })
  end
  -- Self-registration. The control does not know or care which tab it is in --
  -- the palette walks up from this frame when it needs to know, so moving a
  -- control between tabs never leaves a stale entry behind.
  if L.Palette and opts.text then
    L.Palette.add(f, opts.text, opts.desc or "")
  end
  return f
end

-- ---------------------------------------------------------------- static

-- ---------------------------------------------------------------- persistence
--
-- EVERY CONTROL SAVES ITSELF. Before this, a setting survived a reload only if
-- somebody had also declared it in Cfg.SCHEMA by hand -- which covered the
-- twenty interface preferences and none of the hundred-odd controls in the
-- feature tabs. Aim FOV, hitbox size, fling power, every dropdown: rebuilt from
-- source defaults on every execute.
--
-- Rather than add an id to a hundred call sites, the id is derived from where
-- the control sits: the owning module sets a context with C.ctx, C.section
-- tracks the group, and the control's own label finishes it -- "combat.fling.
-- Launch power". Stable across rebuilds because all three come from source, and
-- unique because no two controls in one section share a label. An explicit
-- opts.id always wins if a call site wants to pin one down.
C._ctx, C._section = "hub", ""

-- id -> the default the SOURCE gave the control. Rebuilt at construction every
-- execute, never stored: a saved default outlives the code that changed it, and
-- a stale default is worse than none -- it makes a wrong value look correct.
C._def = {}

function C.ctx(name)
  C._ctx = tostring(name or "hub")
  C._section = ""
  return C
end

local function autoId(opts)
  if type(opts.id) == "string" and opts.id ~= "" then return opts.id end
  local label = opts.text or opts.placeholder
  if type(label) ~= "string" or label == "" then return nil end
  return C._ctx .. "." .. C._section .. "." .. label
end

-- Resolves the saved value into opts.default and wraps opts.callback so the new
-- value is written back. Mutating opts is deliberate: every call site builds it
-- inline, and the alternative is threading two return values through six
-- constructors that each read opts.default in several places.
local function bindPersist(opts)
  local Cfg = L.Cfg
  if not (Cfg and Cfg.feat and Cfg.setFeat) then return end
  local id = autoId(opts)
  if not id then return end
  opts._id = id

  -- THE CONTROL IS THE SCHEMA. Everything needed to validate this id is already
  -- in opts -- it is the same data the constructor below builds the widget from.
  -- Harvesting it here rather than declaring it in lm_15 is the difference
  -- between 104 declarations somebody maintains and none. The fallbacks match
  -- C.slider's own, so a spec can never be tighter than the control it describes.
  if Cfg.declare then
    local spec
    if type(opts.min) == "number" or type(opts.max) == "number" then
      spec = { t = "number", min = opts.min or 0, max = opts.max or 100 }
    elseif type(opts.items) == "table" and opts.items[1] ~= nil then
      local set, ok = {}, true
      for _, it in ipairs(opts.items) do
        if type(it) == "string" then set[it] = true else ok = false end
      end
      -- a control's own default is legal by definition, even if a call site
      -- forgot to put it in the list
      if ok then
        if type(opts.default) == "string" then set[opts.default] = true end
        spec = { t = "string", enum = set }
      end
    else
      local d = type(opts.default)
      if d == "boolean" or d == "string" or d == "number" then spec = { t = d } end
    end
    if spec then Cfg.declare(id, spec) end
  end

  local sourceDefault = opts.default
  -- THE ONE MOMENT id -> default EXISTS. opts.default becomes the saved value
  -- below and the source fact is gone for the rest of the session.
  if sourceDefault ~= nil then C._def[id] = sourceDefault end
  local saved = Cfg.feat(id, nil)
  local restored

  -- only accept a stored value of the same shape the control expects, so a
  -- hand-edited file cannot hand a slider a string
  if saved ~= nil and (sourceDefault == nil or type(saved) == type(sourceDefault)) then
    -- A STORED **ON** IS REMEMBERED BUT NOT RE-APPLIED. See Cfg.ARM_SAFE: the
    -- only booleans that come back armed are the ones that cannot act on their
    -- own (appearance sub-options, anti-AFK). Everything else starts off, so
    -- executing the hub never leaves something already running.
    --
    -- Numbers, strings and a stored `false` skip this entirely -- a slider
    -- cannot switch anything on by itself, and restoring an OFF is a no-op.
    local allowed = true
    if Cfg.NO_APPLY and Cfg.NO_APPLY[id] then
      -- A number that writes straight to the character. Same surprise as a
      -- switch coming back on, so it gets the same answer.
      allowed = false
    elseif type(saved) == "boolean" and saved and Cfg.restorable then
      allowed = Cfg.restorable(id)
    end
    if allowed then
      opts.default = saved
      restored = saved
    end
  end

  -- LIVE VALUES, NOT THE STORE, are what opts.when reads -- ARM_SAFE above can
  -- leave disk holding a `true` for a switch that came back off. Notifying here
  -- is also what covers a dependency built AFTER its dependent.
  C._live[id] = opts.default
  C.notify(id)

  local cb = opts.callback

  -- ANYTHING THAT CAME BACK ARMED GETS RECORDED. Restoring switched-on features
  -- is only reasonable if the operator can see what was restored and undo it in
  -- one click; without that it is the old silent-rearm bug with better
  -- intentions. The ledger is what buys the denylist in lm_15_config.
  if restored == true and Cfg.noteRestored then
    Cfg.noteRestored(id, restored, cb)
  end

  opts.callback = function(v)
    local r, why
    if cb then r, why = cb(v) end
    -- C.toggle reverts on an explicit false, so a refused change must not be
    -- the one that gets written to disk
    if r ~= false then
      Cfg.setFeat(id, v)
      if C._live[id] ~= v then C._live[id] = v C.notify(id) end
    end
    return r
  end

  -- RESTORING THE KNOB IS NOT RESTORING THE SETTING. The control now shows the
  -- saved value, but the feature module still holds whatever its source default
  -- was -- so the panel would read 7250 while the engine used 3000, which is
  -- worse than not saving at all. Push it through the original callback once,
  -- deferred so the page has finished building first, and using `cb` rather
  -- than the wrapper so restoring does not write the value straight back.
  if restored ~= nil and restored ~= sourceDefault and cb then
    task.defer(function() L.try("cfg.restore", cb, restored) end)
  end
end

C.bindPersist = bindPersist
C.autoId = autoId

-- A refusal is an answer, not a crash. `false[, why]` back from a callback means
-- the feature declined, so the control has to put the visible value back --
-- otherwise the knob, the disk and the engine hold three different numbers and
-- the next launch looks like the hub lost the setting. Returns ok, why.
local function commitValue(kind, opts, v, quiet)
  if not opts.callback then return true end
  local label = kind .. ":" .. tostring(opts.text or opts.placeholder or "?")
  local ran, res, why = L.try(label, opts.callback, v)
  if ran and res ~= false then return true end
  why = why or (ran and "Did not engage." or "Threw while applying.")
  if ran then L.log("refused", label, why) end   -- refused, not broken: fault log stays clean
  if not quiet and L.Toast then
    L.Toast.warn(tostring(opts.text or "Setting"), tostring(why))
  end
  return false, why
end

C.commitValue = commitValue

-- ------------------------------------------------------- enabled + dependency
--
-- ONE VEIL RATHER THAN FIFTEEN DISABLED PATHS. A.interactive returns a
-- setEnabled, but it reaches exactly one constructor; the other fourteen bury
-- their input in track, pill, popover and TextBox children that share no shape.
-- A scrim parented to the row sits above all of them.
--
-- Transparency, not a new colour token: a T.c.disabled would have to be painted
-- on every label, knob, stroke and gradient inside each control -- six
-- instances in the slider alone -- which is the per-constructor work this is
-- meant to delete, and lm_16_theme would need a swap entry for it. A scrim in
-- the page ground colour washes the whole row at once and follows any theme.
local VEIL_A = 0.42

function C.setEnabled(api, on, why)
  local f = api and api.frame
  if not f then return end
  on = on and true or false
  api._why = (not on) and (why or "Not available yet.") or nil

  local v = f:FindFirstChild("Veil")
  if on and not v then return end
  if not v then
    -- clear of A.interactive's Hit overlay at frame.ZIndex + 5 and the content
    -- lift at + 6; under Sibling behaviour it cannot escape its own row
    v = mk("TextButton", {
      Name = "Veil", Text = "", AutoButtonColor = false, Active = true,
      Size = UDim2.fromScale(1, 1), BackgroundColor3 = T.c.surface,
      BackgroundTransparency = 1, BorderSizePixel = 0, Visible = false,
      ZIndex = (f.ZIndex or 1) + 20, Parent = f,
    })
    local rc = f:FindFirstChildOfClass("UICorner")
    mk("UICorner", {
      CornerRadius = rc and rc.CornerRadius or UDim.new(0, T.r.md), Parent = v,
    })
    -- SAY WHY ON HOVER, TOAST IT ON CLICK: the segmented locked pattern, the
    -- only unavailable state in this library nobody reads as a bug. A.explain
    -- freezes its text, so keep the hint entry to retarget it.
    A.explain(v, api._why or "Not available yet.", tostring(api._label or ""))
    api._hint = A.hints[#A.hints]
    v.MouseButton1Click:Connect(function()
      if L.Toast then
        L.Toast.info(tostring(api._label or "Unavailable"),
                     tostring(api._why or "Not available yet."))
      end
    end)
  end
  if api._hint then api._hint.text = api._why or "Not available yet." end

  f:SetAttribute("lmDisabled", (not on) or nil)
  -- a fully transparent GuiButton still eats clicks, so enabling hides it
  -- rather than fading it out
  if on then
    v.Visible = false
    M.set(v, "BackgroundTransparency", 1)
  elseif not v.Visible then
    M.set(v, "BackgroundTransparency", 1)
    v.Visible = true
    M.to(v, "BackgroundTransparency", VEIL_A, "fast")
  end
end

-- opts.when: what a control needs before it means anything. A string is a
-- bindPersist auto-id ("combat.aim.Aim assist"); a function is called as-is.
-- Declared once at the call site instead of a setEnabled fan-out hand-written
-- into every owning module's callback.
C._deps, C._any, C._live = {}, {}, {}

local function met(when)
  if type(when) == "function" then
    local ok, val = pcall(when)
    return ok and val ~= nil and val ~= false
  end
  -- NOT Cfg.feat: ARM_SAFE can leave the store holding a `true` for a switch
  -- that deliberately came back off, and a dependent follows the knob. A
  -- numeric id is satisfied by 0, so point `when` at a toggle.
  local val = C._live[when]
  return val ~= nil and val ~= false
end

local function applyDep(e)
  local f = e.api.frame
  if not (f and f.Parent) then return false end     -- rebuilt page: drop it
  e.api.setEnabled(met(e.when), e.why)
  return true
end

local function sweepAny()
  for i = #C._any, 1, -1 do
    if not applyDep(C._any[i]) then table.remove(C._any, i) end
  end
end

function C.notify(id)
  local list = C._deps[id]
  if list then
    for i = #list, 1, -1 do
      if not applyDep(list[i]) then table.remove(list, i) end
    end
  end
  -- A function dependency cannot be keyed by id, so it is re-read on any
  -- change -- at most once a frame, or dragging a slider would run every
  -- predicate in the hub sixty times a second.
  if #C._any > 0 and not C._anyQueued then
    C._anyQueued = true
    task.defer(function() C._anyQueued = false sweepAny() end)
  end
end

function C.dependent(api, opts)
  local w = opts.when
  if w == nil then return end
  local e = {
    api = api, when = w,
    why = opts.whyDisabled or (type(w) == "string"
      and ("Turn on " .. (string.match(w, "[^.]+$") or w) .. " first.")
      or "Not available yet."),
  }
  if type(w) == "string" then
    local l = C._deps[w]
    if not l then l = {} C._deps[w] = l end
    l[#l + 1] = e
  else
    C._any[#C._any + 1] = e
  end
  applyDep(e)                    -- the state at construction, before first paint
end

-- ---------------------------------------------------------------- pinnable
--
-- Registers a built control with L.Pins and makes the row itself the pin
-- affordance: RIGHT-CLICK ANY ROW TO PIN IT. A dedicated pin glyph on every
-- control would have to be drawn, positioned and kept clear of the value
-- readout on six different row layouts; the secondary click is already unused
-- everywhere in the hub and costs one connection.
function C.pinnable(frame, opts, spec)
  local id = opts._id
  if not (id and L.Pins and frame) then return end
  spec.label = opts.text or id
  spec.ctx = C._ctx
  L.Pins.register(id, spec)

  local btn = frame:FindFirstChild("Hit")
  if not btn then return end
  btn.MouseButton2Click:Connect(function()
    local Cfg = L.Cfg
    if not (Cfg and Cfg.setPin) then return end
    local now = Cfg.pinned(id)
    Cfg.setPin(id, not now)
    if L.Toast then
      L.Toast.info(now and "Unpinned" or "Pinned",
        tostring(opts.text or id) ..
        (now and " removed from the dock." or " added to the dock strip."))
    end
  end)
end

-- `shown` overrides only what is PAINTED. `text` still sets C._section, which
-- is half of every id underneath, so a section can be relabelled or moved to
-- another tab without orphaning a single saved value.
function C.section(parent, text, shown)
  C._section = tostring(text or "")
  local h = mk("Frame", {
    Size = UDim2.new(1, 0, 0, 26), BackgroundTransparency = 1,
    Name = "Section", Parent = parent,
  })
  A.text({
    Text = L.track(string.upper(shown or text or ""), 1),
    font = T.font.medium, size = T.size.nano, colour = T.c.textOff,
    Position = UDim2.fromOffset(2, 12), Size = UDim2.new(1, -4, 0, 14),
    Parent = h,
  })
  return h
end

function C.paragraph(parent, text)
  local f = A.surface({
    Parent = parent, elev = 1, radius = T.r.md,
    Size = UDim2.new(1, 0, 0, 0), Name = "Paragraph",
  })
  f.AutomaticSize = Enum.AutomaticSize.Y
  L.pad(12, 12, 12, 12, f)
  A.text({
    Text = text or "", wrap = true,
    font = T.font.body, size = T.size.label, colour = T.c.textDim,
    valign = Enum.TextYAlignment.Top,
    Size = UDim2.new(1, 0, 0, 0), autoSize = Enum.AutomaticSize.Y,
    Parent = f,
  })
  return f
end

-- ---------------------------------------------------------------- tiles
--
-- A row of small metric cards. Numbers get the mono face and the accent; their
-- captions get the muted face. Keeping the figure and its label in different
-- weights is what lets the eye read a row of these at a glance instead of
-- parsing each one.
function C.tiles(parent, items, opts)
  opts = opts or {}
  local n = math.max(#items, 1)
  local holder = mk("Frame", {
    Size = UDim2.new(1, 0, 0, opts.height or 62),
    BackgroundTransparency = 1, Name = "Tiles", Parent = parent,
  })
  local gap = T.gap.md
  local layout = L.list(gap, Enum.FillDirection.Horizontal, holder)
  layout.VerticalAlignment = Enum.VerticalAlignment.Center

  local api = { frame = holder, cells = {} }
  for i, item in ipairs(items) do
    local cell = A.surface({
      Parent = holder, elev = 1, radius = T.r.md, sheen = true,
      -- width is scale-based minus its share of the gaps, so the row fills
      -- exactly regardless of how many tiles are passed
      Size = UDim2.new(1 / n, -(gap * (n - 1)) / n, 1, 0),
      Name = "Tile", LayoutOrder = i,
    })
    A.text({
      Text = string.upper(item.label or ""),
      font = T.font.medium, size = T.size.tiny, colour = T.c.textOff,
      Position = UDim2.fromOffset(12, 12), Size = UDim2.new(1, -24, 0, 12),
      truncate = true, Parent = cell,
    })
    local val = A.text({
      Text = tostring(item.value or "-"),
      font = T.font.mono, size = T.size.head,
      colour = item.colour or T.c.accent,
      Position = UDim2.fromOffset(12, 28), Size = UDim2.new(1, -24, 0, 18),
      truncate = true, Parent = cell,
    })
    api.cells[item.key or i] = val
  end

  -- ROLL THE NUMBER rather than swapping it. A figure that jumps reads as a
  -- readout being overwritten; one that travels reads as a value changing.
  --
  -- Only plain "number" or "number unit" rolls. "29/35" and "0:24" are two
  -- numbers and a clock -- interpolating either produces nonsense on the way.
  local rolls = {}

  function api:set(key, text, colour)
    local lbl = self.cells[key]
    if not lbl then return end
    if colour then M.to(lbl, "TextColor3", colour, "fast") end
    text = tostring(text)

    local num, unit = text:match("^%s*(%-?%d+)%s*(%a*)%s*$")
    if not L.Cfg or L.Cfg.data.rollNumbers == false or not num then
      rolls[key] = nil
      lbl.Text = text
      return
    end
    local target = tonumber(num)
    local r = rolls[key]
    if not r then
      -- first value is not a change, so it appears rather than counting up
      rolls[key] = { spring = L.Spring.new(0.55, -0.2, target), unit = unit, lbl = lbl }
      lbl.Text = text
      return
    end
    r.unit, r.lbl = unit, lbl
    r.spring:to(target)
  end

  task.spawn(function()
    while L.live() and holder.Parent do
      local dt = L.RunService.Heartbeat:Wait()
      for _, r in pairs(rolls) do
        if not r.spring:settled(0.5, 2) then
          local v = r.spring:step(dt)
          r.lbl.Text = string.format("%d%s%s", v + 0.5,
                                     r.unit ~= "" and " " or "", r.unit)
        end
      end
    end
  end)

  return api
end

-- ---------------------------------------------------------------- actions
--
-- A row of small pills, not a stack of full-width bars. A button that spans the
-- whole column reads as the most important thing on the page; three of them
-- stacked read as a page made entirely of alarms. The reference uses compact
-- pills for exactly this reason -- weight is spent on the one primary action and
-- nothing else.
function C.actions(parent, items)
  local holder = mk("Frame", {
    Size = UDim2.new(1, 0, 0, 34), BackgroundTransparency = 1,
    Name = "Actions", Parent = parent,
  })
  local lay = L.list(T.gap.sm, Enum.FillDirection.Horizontal, holder)
  lay.VerticalAlignment = Enum.VerticalAlignment.Center

  local api = { frame = holder }
  for i, item in ipairs(items) do
    -- width follows the label: TextBounds after a frame, so the pill hugs its
    -- text instead of every action being the same arbitrary size
    local w = 22 + #tostring(item.text) * 7
    local f = A.surface({
      Parent = holder, elev = item.primary and 1 or 1, radius = T.r.pill,
      Size = UDim2.fromOffset(w, 32), Name = "Pill", LayoutOrder = i,
      fill = item.primary and T.c.accent or nil,
      line = not item.primary,
    })
    if item.primary then A.accentGradient(f, 100) end
    A.text({
      Text = item.text, font = T.font.medium, size = T.size.label,
      colour = item.primary and T.c.accentInk or T.c.textDim,
      align = Enum.TextXAlignment.Center, Parent = f,
    })
    A.interactive(f, {
      radius = T.r.pill,
      layerColour = item.primary and Color3.new(0, 0, 0) or Color3.new(1, 1, 1),
      hoverAlpha = item.primary and 0.9 or 0.95,
      pressAlpha = item.primary and 0.8 or 0.9,
      onClick = function() if item.callback then item.callback() end end,
    })
    -- each pill is its own stop: a row of three actions is three decisions
    focusable(f, {
      radius = T.r.pill, label = item.text,
      activate = function() if item.callback then item.callback() end end,
    })
    -- Buttons are pinnable too, which is most of the point: "Open player panel"
    -- is a thing you want one click away, and it is not a setting so nothing
    -- else in this file would ever have given it an id.
    C.pinnable(f, { _id = "action." .. C._ctx .. "." .. tostring(item.text),
                    text = item.text }, {
      kind = "action",
      run = function() if item.callback then item.callback() end end,
    })
  end
  return api
end

-- ---------------------------------------------------------------- button

function C.button(parent, opts)
  opts = opts or {}
  local f = A.surface({
    Parent = parent, elev = 1, radius = T.r.md,
    Size = UDim2.new(1, 0, 0, 38), Name = "Button",
    fill = opts.primary and T.c.accent or nil,
    line = not opts.primary,
  })
  if opts.primary then A.accentGradient(f, 90) end

  A.text({
    Text = opts.text or "Button",
    font = T.font.strong, size = T.size.body,
    colour = opts.primary and T.c.accentInk or T.c.text,
    align = Enum.TextXAlignment.Center,
    Parent = f,
  })

  local api = {}
  local ix = A.interactive(f, {
    radius = T.r.md,
    layerColour = opts.primary and Color3.new(0, 0, 0) or Color3.new(1, 1, 1),
    hoverAlpha = opts.primary and 0.9 or 0.95,
    pressAlpha = opts.primary and 0.8 or 0.90,
    onClick = function() if opts.callback then opts.callback() end end,
  })
  api.frame, api._ix = f, ix
  register(opts, api)
  focusable(f, {
    radius = T.r.md, label = opts.text,
    activate = function() if opts.callback then opts.callback() end end,
  })
  return api
end

-- ---------------------------------------------------------------- toggle

function C.toggle(parent, opts)
  opts = opts or {}
  bindPersist(opts)
  local state = opts.default and true or false
  local f = row(parent, { text = opts.text, desc = opts.desc, rightRoom = 68 })

  local track = mk("Frame", {
    AnchorPoint = Vector2.new(1, 0.5),
    Position = UDim2.new(1, -12, 0.5, 0),
    Size = UDim2.fromOffset(38, 21),
    BackgroundColor3 = T.c.active,
    BorderSizePixel = 0, ZIndex = 2,
    Parent = f,
  })
  L.corner(999, track)
  local trackStroke = L.stroke(T.c.lineStrong, 1, 0.4, track)

  -- The "on" state is a GRADIENT, not a flat accent. A UIGradient tints whatever
  -- BackgroundColor3 it sits on, so it cannot be faded in and out on the track
  -- itself without also dragging the off-state colour through it -- hence a
  -- separate fill layer whose transparency is what actually animates.
  local fill = mk("Frame", {
    Size = UDim2.fromScale(1, 1),
    BackgroundColor3 = Color3.new(1, 1, 1),
    BackgroundTransparency = 1,
    BorderSizePixel = 0, ZIndex = 2, Parent = track,
  })
  L.corner(999, fill)
  A.accentGradient(fill, 0)

  local knob = mk("Frame", {
    AnchorPoint = Vector2.new(0, 0.5),
    Position = UDim2.new(0, 3, 0.5, 0),
    Size = UDim2.fromOffset(15, 15),
    BackgroundColor3 = T.c.textDim,
    BorderSizePixel = 0, ZIndex = 3,
    Parent = track,
  })
  L.corner(999, knob)

  local api = {}
  local function paint(immediate)
    local tok = immediate and nil or "fast"
    local pos = UDim2.new(0, state and 20 or 3, 0.5, 0)
    local setter = immediate and M.set or M.to
    setter(knob, "Position", pos, tok)
    setter(fill, "BackgroundTransparency", state and 0 or 1, tok)
    setter(knob, "BackgroundColor3", state and T.c.accentInk or T.c.textDim, tok)
    setter(trackStroke, "Transparency", state and 1 or 0.4, tok)
  end

  -- A CONTROL MAY NOT CLAIM A STATE IT NEVER REACHED. This used to paint the new
  -- state and fire the callback with no interest in the answer, so a feature
  function api:set(v, silent)
    v = v and true or false
    if v == state then return end
    state = v
    paint(false)
    if silent or not opts.callback then return end

    -- labelled with the control's own text: "toggle.cb" in a fault list tells
    -- you a toggle broke but not which one, which is barely better than silence
    local label = "toggle:" .. tostring(opts.text or "?")
    local ran, res, why = L.try(label, opts.callback, state)
    if ran and res ~= false then return end

    state = not state
    paint(false)
    if ran then                       -- refused, not broken: the fault log stays clean
      L.log("refused", label, why or "did not engage")
    end
    if L.Toast and state == false then
      L.Toast.warn(tostring(opts.text or "Feature"),
                   tostring(why or (ran and "Did not engage." or "Threw while starting.")))
    end
  end
  function api:get() return state end

  A.interactive(f, { radius = T.r.md, onClick = function() api:set(not state) end })
  -- Enter flips it; Left and Right set it outright, so a keyboard user can force
  -- a known state instead of toggling and having to look to find out which way
  -- it went.
  focusable(f, {
    radius = T.r.md, label = opts.text,
    activate = function() api:set(not state) end,
    adjust = function(dir) api:set(dir > 0) end,
  })
  paint(true)
  api.frame = f
  register(opts, api)
  -- pinnable: the strip drives THIS api, so a pinned switch and the switch in
  -- the tab are one object and cannot drift apart
  C.pinnable(f, opts, {
    kind = "toggle",
    get = function() return api:get() end,
    set = function(v) api:set(v) end,
  })
  return api
end

-- ---------------------------------------------------------------- segmented

-- Three or four mutually exclusive choices, all visible at once. A dropdown
-- hides the options behind a click and gives no sense of where the current one
-- sits in the range; a segmented control shows the whole scale.
function C.segmented(parent, opts)
  opts = opts or {}
  bindPersist(opts)
  local items = opts.items or {}
  local value = opts.default or items[1]

  -- CELLS ARE MEASURED, NOT ASSUMED. Every cell used to be exactly 54 px wide
  -- and the bar 38 + n*54, both independent of what the labels actually said.
  -- That fitted "Calm" and "Default" and clipped "Comfortable" to "Comfortab"
  -- while the selected pill overhung the panel edge -- and the control it broke
  -- was Density, which is itself the thing that changes text size. The one
  -- control most able to invalidate a hardcoded width was the one relying on it.
  local CELL_PAD, GAP, BAR_PAD, MIN_CELL = 16, 3, 3, 44
  local TextService = game:GetService("TextService")
  local function widthOf(s)
    local ok, sz = pcall(function()
      return TextService:GetTextSize(s, T.size.micro, T.font.medium,
                                     Vector2.new(4096, 100))
    end)
    if ok and sz then return math.ceil(sz.X) end
    return #s * math.ceil(T.size.micro * 0.62)      -- generous, so it clips last
  end

  local widths, total = {}, 0
  for i, item in ipairs(items) do
    widths[i] = math.max(widthOf(tostring(item)) + CELL_PAD, MIN_CELL)
    total = total + widths[i]
  end
  local barW = total + GAP * math.max(#items - 1, 0) + BAR_PAD * 2

  -- the row reserves what the bar actually needs, so a long option pushes the
  local f = row(parent, { text = opts.text, desc = opts.desc, rightRoom = barW + 24 })

  local bar = mk("Frame", {
    AnchorPoint = Vector2.new(1, 0.5),
    Position = UDim2.new(1, -12, 0.5, 0),
    Size = UDim2.fromOffset(barW, 26),
    BackgroundColor3 = T.c.overlay, BorderSizePixel = 0, ZIndex = 2, Parent = f,
  })
  L.corner(T.r.sm + 2, bar)
  L.stroke(T.c.line, 1, 0.35, bar)
  L.pad(3, 3, 3, 3, bar)
  local lay = L.list(3, Enum.FillDirection.Horizontal, bar)
  lay.VerticalAlignment = Enum.VerticalAlignment.Center

  local api, cells = {}, {}
  local function paint()
    for _, c in ipairs(cells) do
      local on = (c.value == value)
      M.to(c.pill, "BackgroundTransparency", on and 0 or 1, "fast")
      M.to(c.label, "TextColor3",
        on and T.c.accentInk
        or (c.locked and T.c.textOff or T.c.textMute), "fast")
    end
  end

  for i, item in ipairs(items) do
    local cell = mk("Frame", {
      Size = UDim2.fromOffset(widths[i], 20), BackgroundTransparency = 1,
      LayoutOrder = i, ZIndex = 3, Parent = bar,
    })
    local pill = mk("Frame", {
      Size = UDim2.fromScale(1, 1), BackgroundColor3 = T.c.accent,
      BackgroundTransparency = 1, BorderSizePixel = 0, ZIndex = 3, Parent = cell,
    })
    L.corner(T.r.sm, pill)
    A.accentGradient(pill, 135)
    local lbl = A.text({
      Text = tostring(item), font = T.font.medium, size = T.size.micro,
      colour = T.c.textMute, align = Enum.TextXAlignment.Center,
      ZIndex = 4, Parent = cell,
    })
    -- A LOCKED OPTION STILL HAS TO SAY WHY, or it reads as a bug.
    --
    -- Hiding an option the user has already seen is worse than showing it
    -- unavailable: they go looking for the thing that vanished. So it stays in
    -- the bar, visibly out of reach, and says what it is waiting for the moment
    -- the pointer touches it.
    local why = opts.locked and opts.locked[item]
    if why then
      A.explain(cell, why, tostring(item))
      A.interactive(cell, { radius = T.r.sm, hoverAlpha = 0.97, spot = false,
        onClick = function()
          L.Toast.info(tostring(item), why)
        end })
    else
      A.interactive(cell, { radius = T.r.sm, hoverAlpha = 0.95,
        onClick = function() api:set(item) end })
    end
    cells[#cells + 1] = { pill = pill, label = lbl, value = item, locked = why }
  end

  function api:set(v, silent)
    if v == value then return end
    local prev = value
    value = v
    paint()
    if silent then return end
    if not commitValue("segmented", opts, v) then
      value = prev
      paint()
    end
  end
  function api:get() return value end

  -- ONE STOP FOR THE WHOLE CONTROL, not one per cell. The cells are a single
  -- choice shown in full; making each its own stop would mean four Tab presses
  -- to cross one setting, and the ring would say "this option" when what is
  -- actually selected is the row.
  focusable(f, {
    radius = T.r.md, label = opts.text,
    adjust = function(dir)
      local i = 1
      for k, item in ipairs(items) do if item == value then i = k break end end
      -- step OVER locked options rather than stopping on one: arrowing into a
      -- dead end feels like the control broke
      local j = i
      repeat
        j = math.clamp(j + dir, 1, #items)
        if not (opts.locked and opts.locked[items[j]]) then api:set(items[j]) return end
      until j <= 1 or j >= #items
    end,
    activate = function()                       -- Enter cycles forward, wrapping
      local i = 1
      for k, item in ipairs(items) do if item == value then i = k break end end
      for step = 1, #items do
        local j = ((i - 1 + step) % #items) + 1
        if not (opts.locked and opts.locked[items[j]]) then api:set(items[j]) return end
      end
    end,
  })

  paint()
  api.frame = f
  register(opts, api)
  return api
end

-- ---------------------------------------------------------------- slider

function C.slider(parent, opts)
  opts = opts or {}
  bindPersist(opts)
  local min   = opts.min or 0
  local max   = opts.max or 100
  local step  = opts.step or 1
  local value = math.clamp(opts.default or min, min, max)

  local f = row(parent, { text = opts.text, desc = opts.desc,
                          rightRoom = 150, height = 50 })

  local readout = A.text({
    Text = "", font = T.font.mono, size = T.size.micro, colour = T.c.accent,
    align = Enum.TextXAlignment.Right,
    AnchorPoint = Vector2.new(1, 0),
    Position = UDim2.new(1, -12, 0, 8), Size = UDim2.fromOffset(60, 13),
    ZIndex = 2, Parent = f,
  })

  -- ---- typed entry ----------------------------------------------------
  --
  -- A SLIDER CANNOT EXPRESS AN EXACT NUMBER. Dragging to precisely 137 on a
  -- 16..250 track is roughly a one-pixel target, and the keyboard route added in
  -- Wave 3 is 121 key presses. The readout was already showing the value, so it
  -- becomes the place you can also type it -- the number and the field for the
  -- number are the same object, which is the only version nobody has to discover.
  local entry = mk("TextBox", {
    AnchorPoint = Vector2.new(1, 0),
    Position = UDim2.new(1, -12, 0, 4), Size = UDim2.fromOffset(64, 20),
    BackgroundColor3 = T.c.active, BackgroundTransparency = 1,
    Text = "", TextColor3 = T.c.accent, Font = T.font.mono,
    TextSize = T.size.micro, TextXAlignment = Enum.TextXAlignment.Right,
    ClearTextOnFocus = false, Visible = false, ZIndex = 4, Name = "Entry",
    Parent = f,
  })
  L.corner(T.r.sm, entry)
  L.pad(0, 6, 0, 6, entry)
  local entryStroke = L.stroke(T.c.accent, 1, 0.35, entry)

  local hitReadout = mk("TextButton", {
    AnchorPoint = Vector2.new(1, 0),
    Position = UDim2.new(1, -10, 0, 4), Size = UDim2.fromOffset(68, 20),
    BackgroundTransparency = 1, Text = "", AutoButtonColor = false,
    ZIndex = 3, Name = "ReadoutHit", Parent = f,
  })

  local track = mk("Frame", {
    AnchorPoint = Vector2.new(1, 1),
    Position = UDim2.new(1, -12, 1, -12),
    Size = UDim2.fromOffset(132, 4),
    BackgroundColor3 = T.c.active,
    BorderSizePixel = 0, ZIndex = 2,
    Parent = f,
  })
  L.corner(999, track)

  local fill = mk("Frame", {
    Size = UDim2.fromScale(0, 1),
    BackgroundColor3 = T.c.accent,
    BorderSizePixel = 0, ZIndex = 3,
    Parent = track,
  })
  L.corner(999, fill)
  A.accentGradient(fill, 0)

  local knob = mk("Frame", {
    AnchorPoint = Vector2.new(0.5, 0.5),
    Position = UDim2.fromScale(0, 0.5),
    Size = UDim2.fromOffset(11, 11),
    BackgroundColor3 = T.c.text,
    BorderSizePixel = 0, ZIndex = 4,
    Parent = track,
  })
  L.corner(999, knob)

  local hit = mk("TextButton", {
    AnchorPoint = Vector2.new(0.5, 0.5),
    Position = UDim2.fromScale(0.5, 0.5),
    Size = UDim2.new(1, 20, 0, 22),
    BackgroundTransparency = 1, Text = "", AutoButtonColor = false,
    ZIndex = 5, Parent = track,
  })

  -- ---- the curve ---------------------------------------------------------
  --
  -- A LINEAR SLIDER OVER A WIDE RANGE IS NOT A CONTROL, IT IS A LOTTERY.
  -- "Launch power" ran 500 to 250,000 across about 130 pixels: every pixel was
  -- roughly nineteen hundred units, so the low half of the range -- where most
  -- of the useful values live -- could not be aimed at at all, and lowering the
  -- floor or raising the ceiling only makes that worse.
  --
  -- `curve = "log"` spends slider travel proportionally instead: equal distance
  -- for equal RATIO, so 1->10 takes as much room as 100,000->1,000,000. That is
  -- the only way one control can offer both fine tuning at the bottom and
  -- millions at the top, which is exactly what these settings need.
  --
  -- Quantisation follows the curve too: snapping a logarithmic value to a fixed
  -- linear step would put every stop at the bottom and none at the top.
  local logCurve = (opts.curve == "log")
  local logLo, logSpan
  if logCurve then
    logLo = math.log(math.max(min, 1e-4))
    logSpan = math.log(math.max(max, min + 1e-3)) - logLo
    if logSpan <= 0 then logCurve = false end
  end

  local function toAlpha(v)
    if logCurve then
      return math.clamp((math.log(math.max(v, 1e-4)) - logLo) / logSpan, 0, 1)
    end
    return (max > min) and math.clamp((v - min) / (max - min), 0, 1) or 0
  end

  local function fromAlpha(a)
    a = math.clamp(a, 0, 1)
    if logCurve then return math.exp(logLo + a * logSpan) end
    return min + a * (max - min)
  end

  local api = {}
  local function quantise(v)
    v = math.clamp(v, min, max)
    if logCurve then
      -- significant figures rather than a fixed step: 1.2, then 12, then 120,
      -- so the readout stays legible across five orders of magnitude
      local mag = math.floor(math.log10(math.max(math.abs(v), 1e-4)))
      local q = 10 ^ math.max(mag - 2, -3)
      v = math.floor(v / q + 0.5) * q
    elseif step > 0 then
      v = math.floor((v - min) / step + 0.5) * step + min
    end
    return math.clamp(v, min, max)
  end

  local function paint(immediate)
    local a = toAlpha(value)
    -- 1,250,000 rather than 1250000: past four digits the eye cannot count
    -- zeroes, and these ranges now reach seven
    local shown
    if math.abs(value) >= 10000 then
      local whole = string.format("%d", math.floor(value + 0.5))
      local sep = whole:reverse():gsub("(%d%d%d)", "%1,"):reverse():gsub("^,", "")
      shown = sep
    else
      shown = tostring(L.round(value, 3))
    end
    readout.Text = opts.suffix and (shown .. opts.suffix) or shown
    if immediate then
      M.set(fill, "Size", UDim2.fromScale(a, 1))
      M.set(knob, "Position", UDim2.fromScale(a, 0.5))
    else
      -- `gentle` is overdamped on purpose: a slider fill that springs PAST the
      -- value the readout already shows looks like a bug, not like polish.
      M.to(fill, "Size", UDim2.fromScale(a, 1), "gentle")
      M.to(knob, "Position", UDim2.fromScale(a, 0.5), "gentle")
    end
  end

  local dragging, dragRefused = false, nil
  local lastGood = value

  function api:set(v, silent)
    local nv = quantise(v)
    if nv == value then return end
    local prev = value
    value = nv
    paint(false)
    if silent then return end
    -- MID-DRAG A REVERT WOULD FIGHT THE POINTER: the knob snaps back, the next
    -- mouse-move refuses again, and that is a toast per frame. A drag is one
    -- gesture, so it records the refusal and settles once on release.
    if dragging then
      local ok, why = commitValue("slider", opts, value, true)
      if ok then lastGood, dragRefused = value, nil else dragRefused = why end
      return
    end
    if commitValue("slider", opts, value) then
      lastGood = value
    else
      value = prev
      paint(false)
    end
  end
  function api:get() return value end
  local function fromX(px)
    -- IGNORE ANY POINTER MATH BEFORE THE TRACK IS LAID OUT. A slider on a tab
    -- that is active at load (the persisted tab) exists a frame or two before
    -- Roblox gives it a real AbsoluteSize. Until then AbsoluteSize.X is 0, the
    -- max(...,1) floor makes the divisor 1, and any stray Activated turns a
    -- 900px mouse X into a=900 -> clamp to 1 -> the slider SLAMS to its maximum.
    -- That is what was quietly pinning fling power to max on load. No real drag
    -- can happen on a zero-width track, so there is nothing to lose by waiting.
    local w = track.AbsoluteSize.X
    if w < 8 then return end
    local a = (px - track.AbsolutePosition.X) / w
    api:set(fromAlpha(a))
  end

  hit.MouseButton1Down:Connect(function()
    dragging = true
    M.to(knob, "Size", UDim2.fromOffset(14, 14), "fast")
  end)
  hit.InputChanged:Connect(function(i)
    if dragging and i.UserInputType == Enum.UserInputType.MouseMovement then
      fromX(i.Position.X)
    end
  end)
  L.hold(L.UIS.InputChanged:Connect(function(i)
    if dragging and (i.UserInputType == Enum.UserInputType.MouseMovement
      or i.UserInputType == Enum.UserInputType.Touch) then
      fromX(i.Position.X)
    end
  end))
  L.hold(L.UIS.InputEnded:Connect(function(i)
    if i.UserInputType == Enum.UserInputType.MouseButton1
      or i.UserInputType == Enum.UserInputType.Touch then
      if dragging then
        dragging = false
        M.to(knob, "Size", UDim2.fromOffset(11, 11), "fast")
        if dragRefused then
          local why = dragRefused
          dragRefused = nil
          if value ~= lastGood then value = lastGood paint(false) end
          if L.Toast then L.Toast.warn(tostring(opts.text or "Setting"), tostring(why)) end
        end
      end
    end
  end))
  -- A CLICK ON A SLIDER IS, BY DEFINITION, ON THE SLIDER.
  --
  -- Activated used to be trusted outright and the mouse X mapped straight onto
  -- the track. That is unsound whenever the track has not been placed yet: a
  -- fresh row reports its real width a frame before Roblox resolves its
  -- position, so AbsoluteSize.X is 132 while AbsolutePosition.X is still 0, and
  -- (900 - 0) / 132 clamps to 1 -- the slider would jump to its maximum from a
  -- click nowhere near it.
  --
  -- Requiring the pointer to actually be over the track closes that off. This
  -- is defence, not a bug fix: the max-value readings that prompted it turned
  -- out to be a stale global left by a silently-failing obfuscated build, not
  -- this code path.
  hit.Activated:Connect(function()
    local w = track.AbsoluteSize.X
    if w < 8 then return end
    local x0 = track.AbsolutePosition.X
    -- X-only, and the inset is vertical on every current platform, so this was
    -- never visibly wrong -- but it is read through the same helper as the rest
    -- so it cannot rot if a platform ever reports a horizontal inset.
    local mx = L.pointer().X
    -- hit is 20px wider than the track on each side, so allow that much slack
    if mx < x0 - 24 or mx > x0 + w + 24 then return end
    fromX(mx)
  end)

  local function closeEntry(commit)
    if not entry.Visible then return end
    if commit then
      -- accepts "137", "137.5", " 137 " and rejects the rest rather than
      -- silently resolving a typo to 0, which would look like the slider moved
      -- on its own
      local n = tonumber((entry.Text:gsub("%s", "")))
      if n then
        api:set(n)
      elseif entry.Text ~= "" and L.Toast then
        L.Toast.warn(opts.text or "Value",
          string.format("'%s' is not a number -- left at %s.", entry.Text, tostring(value)))
      end
    end
    entry.Visible = false
    readout.Visible = true
    pcall(function() entry:ReleaseFocus() end)
  end

  local function openEntry()
    readout.Visible = false
    entry.Visible = true
    entry.Text = tostring(L.round(value, 2))
    M.set(entry, "BackgroundTransparency", 1)
    M.to(entry, "BackgroundTransparency", 0.4, "fast")
    entry:CaptureFocus()
    pcall(function() entry.CursorPosition = #entry.Text + 1 entry.SelectionStart = 1 end)
  end

  hitReadout.Activated:Connect(openEntry)
  entry.FocusLost:Connect(function(enter) closeEntry(enter) end)
  -- Escape abandons the edit. Without it the only way out of a half-typed value
  -- is to commit it, and the engine takes Escape before anything can sink it, so
  -- this listener is the whole mechanism.
  L.hold(L.UIS.InputBegan:Connect(function(i)
    if entry.Visible and i.KeyCode == Enum.KeyCode.Escape then closeEntry(false) end
  end))
  local _ = entryStroke

  -- One step per press, ten with Shift. A slider whose only keyboard speed is
  -- one step makes a 16..250 range a 234-press job, and one that always jumps
  -- coarsely cannot be aimed -- so the modifier picks which you wanted.
  focusable(f, {
    radius = T.r.md, label = opts.text,
    suspend = function() return entry.Visible end,
    activate = openEntry,          -- Enter on a focused slider types the value
    adjust = function(dir)
      local mult = (L.UIS:IsKeyDown(Enum.KeyCode.LeftShift)
                 or L.UIS:IsKeyDown(Enum.KeyCode.RightShift)) and 10 or 1
      if logCurve then
        -- a fixed step is meaningless on a ratio scale; move along the track
        api:set(fromAlpha(toAlpha(value) + dir * 0.02 * mult))
      else
        api:set(value + dir * (step > 0 and step or 1) * mult)
      end
    end,
  })

  -- Hover wash, rim and pointer spotlight, same as the toggle above it. Wired
  -- last on purpose: the guard inside A.interactive lifts the track, the readout
  -- button and the entry box clear of the full-size Hit overlay, and it can only
  -- lift children that already exist.
  A.interactive(f, { radius = T.r.md })

  paint(true)
  api.frame = f
  register(opts, api)
  return api
end

-- ---------------------------------------------------------------- dropdown
--
-- A POPOVER, NOT AN INLINE EXPANSION.

local DD_ROW, DD_MAX, DD_FILTER_AT = 32, 232, 8
-- geometry of the closed row: left padding, the value label's width and its
-- distance from the right edge (clearing the chevron), and the gap the title
-- must leave before the value starts
local DD_PAD, DD_VAL_W, DD_VAL_RIGHT, DD_GAP = 12, 160, 32, 10

local function overlayLayer()
  local w = L.Hub and L.Hub.window
  return w and w.overlay
end

function C.dropdown(parent, opts)
  opts = opts or {}
  bindPersist(opts)
  local items = opts.items or {}
  local value = opts.default
  local open, pop, rows, filterBox, shadow = false, nil, {}, nil, nil

  local f = A.surface({
    Parent = parent, elev = 1, radius = T.r.md,
    Size = UDim2.new(1, 0, 0, ROWH()), Name = "Dropdown",
  })

  A.text({
    Text = opts.text or "Select",
    font = T.font.medium, size = T.size.body, colour = T.c.text,
    Position = UDim2.fromOffset(DD_PAD, 0),
    -- DERIVED, NOT GUESSED. The title used to reserve `1, -150` while the value
    -- label occupied the last 192 px, so the two boxes overlapped by ~42 px --
    -- measured at 86 px on screen at 1.6x scale. Both truncate, so short titles
    -- hid it, but a long one drew straight through the value it sits beside.
    -- Every number below comes from the same four constants, so the two boxes
    -- cannot drift apart again.
    Size = UDim2.new(1, -(DD_PAD + DD_VAL_W + DD_VAL_RIGHT + DD_GAP), 1, 0),
    truncate = true, Parent = f,
  })

  local valueLbl = A.text({
    Text = tostring(value or "None"),
    font = T.font.body, size = T.size.label, colour = T.c.textDim,
    align = Enum.TextXAlignment.Right, AnchorPoint = Vector2.new(1, 0),
    Position = UDim2.new(1, -DD_VAL_RIGHT, 0, 0),
    Size = UDim2.fromOffset(DD_VAL_W, ROWH()),
    truncate = true, ZIndex = 2, Parent = f,
  })

  local _, chevInner = A.Icon.chevron(f, 14, T.c.textMute, "down")
  local chev = chevInner.Parent
  chev.Position = UDim2.new(1, -26, 0, ROWH() / 2 - 7)
  chev.ZIndex = 2

  local api = {}

  local function paintRows()
    for _, r in ipairs(rows) do
      -- one shared treatment, so a chosen row looks the same here, in the
      -- player panel and in the command centre -- see A.selectRow
      A.selectRow(r.frame, r.label, r.value == value, "fast")
    end
  end

  function api:set(v, silent)
    local prev = value
    value = v
    valueLbl.Text = tostring(v)
    paintRows()
    if silent then return end
    if not commitValue("dropdown", opts, v) then
      value = prev
      valueLbl.Text = tostring(prev)
      paintRows()
    end
  end
  function api:get() return value end

  -- THE STACKING SHADOW. The drop shadow was created anonymously --
  -- `A.shadow(nil, { Parent = layer })` -- and only `pop` was ever destroyed, so
  -- every open left another full-strength shadow behind on the overlay. Measured:
  -- five open/close cycles, five orphaned Shadow ImageLabels, each one darkening
  -- the page again. Held by reference now and torn down with the menu it belongs
  -- to.
  local function closePop(instant)
    if not open then return end
    open = false
    M.to(chevInner, "Rotation", 0, "base")
    local p, s = pop, shadow
    pop, shadow = nil, nil
    if s then
      if instant then pcall(function() s:Destroy() end)
      else
        M.to(s, "ImageTransparency", 1, "fast")
        task.delay(0.28, function() pcall(function() s:Destroy() end) end)
      end
    end
    if p and instant then
      -- DISPLACED, NOT DISMISSED. Closing normally leaves the old menu on the
      -- overlay for 0.28 s while it collapses -- which is fine on its own, and
      -- is a stack of two opaque menus when the next one is already opening on
      -- top of it. That is the bug in the recording: a four-item Method list
      -- showing five rows, the extra one belonging to Aim at.
      pcall(function() p:Destroy() end)
      p = nil
    end
    if p then
      M.to(p, "Size", UDim2.fromOffset(p.Size.X.Offset, 0), "fast")
      -- A.fadeTo, not a bare background fade. This popover collapses to zero
      -- HEIGHT as it closes, so an un-faded UIStroke does not merely linger --
      -- it becomes a literal horizontal line sitting where the list used to be.
      A.fadeTo(p, 1, "fast")
      task.delay(0.28, function() pcall(function() p:Destroy() end) end)
    end
    rows = {}
  end
  api.close = closePop

  local function build()
    local layer = overlayLayer()
    if not layer then return end
    local win = L.Hub.window
    local sc = (win.scaleObj and win.scaleObj.Scale) or 1

    -- absolute geometry, converted into the overlay's own space
    local originAbs = layer.AbsolutePosition
    local fAbs, fSize = f.AbsolutePosition, f.AbsoluteSize
    local x = (fAbs.X - originAbs.X) / sc
    local yBelow = (fAbs.Y + fSize.Y - originAbs.Y) / sc + 4
    local width = fSize.X / sc

    -- rows can be taller than the plain-text default when the caller draws more
    -- into them (a headshot needs room a name does not)
    local ROWPX = opts.rowHeight or DD_ROW
    local showFilter = #items >= DD_FILTER_AT
    local listH = math.min(#items * ROWPX + 8, opts.maxHeight or DD_MAX)
    local fullH = listH + (showFilter and 34 or 0)

    -- FLIPPING UP IS NOT ENOUGH ON ITS OWN, and this is the bug the recording
    -- caught: with 32 players in the server the menu is at its full height, and
    -- flipping it above a row near the bottom put its top at a negative Y. It
    -- drew over the title bar and off the top of the window, filter box clipped.
    --
    -- So the menu is clamped into the CONTENT region -- below the header, not
    -- merely inside the window -- and if it still cannot fit, it is shortened
    -- rather than allowed to overhang. It scrolls, so shorter costs nothing.
    local panelH = win.root.AbsoluteSize.Y / sc
    local top = 8
    local content = win.root:FindFirstChild("Content")
    if content then
      top = (content.AbsolutePosition.Y - originAbs.Y) / sc + 6
    end
    local bottom = panelH - 8

    local avail = bottom - top
    if fullH > avail then
      fullH = math.max(DD_ROW + 8, avail)
      listH = fullH - (showFilter and 34 or 0)
    end

    local flip = (yBelow + fullH) > bottom
    local y = flip and ((fAbs.Y - originAbs.Y) / sc - fullH - 4) or yBelow
    y = math.clamp(y, top, math.max(top, bottom - fullH))

    pop = mk("Frame", {
      Position = UDim2.fromOffset(x, y),
      Size = UDim2.fromOffset(width, 0),
      BackgroundColor3 = T.c.overlay, BackgroundTransparency = 0,
      BorderSizePixel = 0,
      ClipsDescendants = true, ZIndex = 31, Name = "Popover", Parent = layer,
    })
    L.corner(T.r.md, pop)
    L.stroke(T.c.lineStrong, 1, 0.25, pop)

    -- Sized and placed to follow the menu, and kept so closePop can remove it.
    -- It cannot be parented to `pop` itself: pop clips its descendants, which
    -- would cut the shadow off at exactly the edge it needs to spill past.
    shadow = A.shadow(nil, { Parent = layer, spread = 22, alpha = 1, ZIndex = 30 })
    if shadow then
      shadow.AnchorPoint = Vector2.new(0, 0)
      shadow.Position = UDim2.fromOffset(x - 22, y - 22 + 6)
      shadow.Size = UDim2.fromOffset(width + 44, fullH + 44)
      M.to(shadow, "ImageTransparency", 0.42, "base")
    end

    -- A DEFENSIVE SWEEP, because one orphan is invisible and ten are not. If any
    -- shadow ever outlives its menu again, the next open clears it rather than
    -- letting the page get darker every time.
    for _, c in ipairs(layer:GetChildren()) do
      if c ~= shadow and c.Name == "Shadow" then pcall(function() c:Destroy() end) end
    end

    M.to(pop, "Size", UDim2.fromOffset(width, fullH), "base")

    local listTop = 0
    if showFilter then
      filterBox = mk("TextBox", {
        Position = UDim2.fromOffset(8, 6), Size = UDim2.fromOffset(width - 16, 24),
        BackgroundColor3 = T.c.raised, BorderSizePixel = 0,
        Text = "", PlaceholderText = "Filter " .. #items .. " items",
        PlaceholderColor3 = T.c.textOff, TextColor3 = T.c.text,
        Font = T.font.body, TextSize = T.size.micro,
        TextXAlignment = Enum.TextXAlignment.Left, ClearTextOnFocus = false,
        ZIndex = 32, Parent = pop,
      })
      L.corner(T.r.sm, filterBox)
      L.pad(0, 8, 0, 8, filterBox)
      listTop = 34
    end

    local scroll = A.scroll({
      Parent = pop, gap = 2,
      Size = UDim2.new(1, -8, 0, listH - 8),
      Position = UDim2.fromOffset(4, listTop + 4),
      Name = "DDList",
    })
    scroll.ZIndex = 32

    rows = {}
    for i, item in ipairs(items) do
      local r = mk("Frame", {
        Size = UDim2.new(1, -4, 0, ROWPX - 2), LayoutOrder = i,
        BackgroundColor3 = T.c.accent, BackgroundTransparency = 1,
        BorderSizePixel = 0, ZIndex = 32, Parent = scroll,
      })
      L.corner(T.r.sm, r)
      local lbl = A.text({
        Text = opts.labelFor and opts.labelFor(item) or tostring(item),
        font = T.font.body, size = T.size.label,
        colour = T.c.textDim, Position = UDim2.fromOffset(opts.textInset or 10, 0),
        Size = UDim2.new(1, -((opts.textInset or 10) + 10), 1, 0),
        truncate = true, ZIndex = 33, Parent = r,
      })
      A.interactive(r, {
        radius = T.r.sm, hoverAlpha = 0.94,
        onClick = function() api:set(item) closePop() end,
      })
      rows[#rows + 1] = { frame = r, label = lbl, value = item }
      -- the caller may hang anything it likes on the row (a headshot, a
      -- distance) without this control needing to know what a player is
      if opts.decorate then L.try("dropdown.decorate", opts.decorate, r, item, i) end

      -- STAGGERED ENTRANCE. Thirty rows appearing at once is a block of text
      -- arriving; the same thirty arriving over a fifth of a second reads as a
      -- list being dealt. Capped so a 32-player server does not take a second
      -- to finish dealing.
      -- TEXT ONLY, DELIBERATELY. Fading the row's images too looked right until
      -- the headshots landed: the avatar starts invisible and fades itself in
      -- when the thumbnail returns from the network, so the stagger captured
      -- "invisible" as its rest value and, if the image arrived first, animated
      -- it straight back to nothing. Cached thumbnails lost that race every
      -- time. Anything a decorator draws now owns its own entrance.
      if opts.stagger ~= false then
        for _, d in ipairs(r:GetDescendants()) do
          if d:IsA("TextLabel") then
            local rest = d.TextTransparency
            d.TextTransparency = 1
            M.after(math.min(i, 14) * 0.018, function()
              if d.Parent then M.to(d, "TextTransparency", rest, "base") end
            end)
          end
        end
      end
    end
    paintRows()

    if filterBox then
      filterBox:GetPropertyChangedSignal("Text"):Connect(function()
        local q = string.lower(filterBox.Text)
        local shown = 0
        for _, r in ipairs(rows) do
          local hit = (q == "") or string.find(string.lower(tostring(r.value)), q, 1, true) ~= nil
          r.frame.Visible = hit
          if hit then shown = shown + 1 end
        end
        -- capped by what actually fits, not by DD_MAX: re-deriving from the
        -- constant here would undo the clamp above the moment you typed
        local h = math.min(shown * ROWPX + 8, listH)
        M.to(pop, "Size", UDim2.fromOffset(width, h + 34), "fast")
        M.to(scroll, "Size", UDim2.new(1, -8, 0, h - 8), "fast")
        -- a shorter menu may now sit lower than it needs to; keep it in bounds
        local ny = math.clamp(pop.Position.Y.Offset, top, math.max(top, bottom - (h + 34)))
        if math.abs(ny - pop.Position.Y.Offset) > 0.5 then
          M.to(pop, "Position", UDim2.fromOffset(x, ny), "fast")
        end
      end)
      task.defer(function() if open and filterBox then filterBox:CaptureFocus() end end)
    end
  end

  local function openPop()
    if open then return end
    -- EVERY OTHER MENU GOES FIRST, and goes instantly.
    --
    -- Each dropdown already closed itself on a click outside, which mostly
    -- worked -- but only mostly: the click that opens the next menu can land
    -- inside the OLD menu's rectangle, and that path treats it as a click on
    -- itself and stays open. Two lists then sit on the overlay together, which
    -- is why the recording shows items from one dropdown under another.
    -- Asking directly is both cheaper and correct.
    C.closePopovers(true)
    open = true
    M.to(chevInner, "Rotation", 180, "base")
    build()
  end

  api.open = openPop
  C._pops[#C._pops + 1] = { frame = f, close = closePop }

  local head = mk("TextButton", {
    Size = UDim2.new(1, 0, 0, ROWH()), BackgroundTransparency = 1,
    Text = "", AutoButtonColor = false, ZIndex = 3, Parent = f,
  })
  head.Activated:Connect(function()
    if open then closePop() else openPop() end
  end)

  -- close on a click anywhere else, and on Escape
  L.hold(L.UIS.InputBegan:Connect(function(i, typing)
    if not open then return end
    if i.KeyCode == Enum.KeyCode.Escape then closePop() return end
    if typing then return end
    if i.UserInputType == Enum.UserInputType.MouseButton1 then
      -- INSET-EXCLUDED: every comparison below is against an AbsolutePosition,
      -- and GetMouseLocation is measured in the other space. Mixing them left
      -- this 58 px out on the Y axis, so the dropdown thought the pointer had
      -- left while it was still over the bottom of the list.
      local m = L.pointer()
      local inTrigger = m.X >= f.AbsolutePosition.X and m.X <= f.AbsolutePosition.X + f.AbsoluteSize.X
        and m.Y >= f.AbsolutePosition.Y and m.Y <= f.AbsolutePosition.Y + f.AbsoluteSize.Y
      local inPop = false
      if pop then
        local pa, ps = pop.AbsolutePosition, pop.AbsoluteSize
        inPop = m.X >= pa.X and m.X <= pa.X + ps.X and m.Y >= pa.Y and m.Y <= pa.Y + ps.Y
      end
      if not inTrigger and not inPop then closePop() end
    end
  end))

  paintRows()
  api.frame = f
  register(opts, api)
  -- drivable from code, not only by clicking: needed for tests, and for any
  -- caller that wants to open a chooser in response to something else
  api.open, api.toggle = openPop, function()
    if open then closePop() else openPop() end
  end
  api.isOpen = function() return open end

  -- Enter opens the popover; Left and Right change the selection without opening
  -- it at all, which is faster than open-arrow-arrow-Enter for a short list.
  focusable(f, {
    radius = T.r.md, label = opts.text,
    activate = function() if open then closePop() else openPop() end end,
    adjust = function(dir)
      if #items == 0 then return end
      local i = 1
      for k, it in ipairs(items) do if it == api:get() then i = k break end end
      api:set(items[math.clamp(i + dir, 1, #items)])
    end,
  })
  return api
end

-- ---------------------------------------------------------------- keybind

function C.keybind(parent, opts)
  opts = opts or {}
  local key = opts.default
  local listening = false

  local f = row(parent, { text = opts.text, desc = opts.desc, rightRoom = 110 })

  local chip = A.surface({
    Parent = f, elev = 2, radius = T.r.sm,
    Size = UDim2.fromOffset(78, 24), Name = "Chip",
  })
  chip.AnchorPoint = Vector2.new(1, 0.5)
  chip.Position = UDim2.new(1, -12, 0.5, 0)
  chip.ZIndex = 2

  local lbl = A.text({
    Text = key and key.Name or "None",
    font = T.font.mono, size = T.size.micro, colour = T.c.textDim,
    align = Enum.TextXAlignment.Center, ZIndex = 3, Parent = chip,
  })

  local api = {}
  local function paint()
    lbl.Text = listening and "press..." or (key and key.Name or "None")
    M.to(lbl, "TextColor3", listening and T.c.accent or T.c.textDim, "fast")
  end

  function api:set(k, silent)
    key = k
    paint()
    if not silent and opts.callback then L.try("keybind.cb", opts.callback, k) end
  end
  function api:get() return key end

  -- L.Binds is told we are listening, or pressing F to bind fly to F would also
  -- fire fly on the way past -- the key would toggle the feature and record
  -- itself in the same keystroke.
  local function listen(on)
    listening = on
    if L.Binds then L.Binds.capturing = on end
    paint()
  end

  A.interactive(chip, { radius = T.r.sm, onClick = function() listen(true) end })

  L.hold(L.UIS.InputBegan:Connect(function(i, typing)
    if not listening or not L.live() then return end
    if i.UserInputType ~= Enum.UserInputType.Keyboard then return end
    listen(false)
    -- Escape CLEARS rather than binding. A UI that lets you bind Escape and
    -- then needs Escape to get out of the menu has trapped you.
    if i.KeyCode == Enum.KeyCode.Escape then api:set(nil) else api:set(i.KeyCode) end
  end))

  -- `suspend` HANDS THE KEYBOARD BACK. While this control is listening it needs
  -- the raw keys -- including the very ones focus navigation claims. Without it
  -- you could never bind Tab, an arrow or Enter, because the navigator would
  -- sink each of them before this control ever saw it.
  focusable(f, {
    radius = T.r.md, label = opts.text,
    suspend = function() return listening end,
    activate = function() listen(true) end,
  })

  paint()
  api.frame = f
  register(opts, api)
  return api
end

-- ---------------------------------------------------------------- input

function C.input(parent, opts)
  opts = opts or {}
  bindPersist(opts)
  local f = row(parent, { text = opts.text, desc = opts.desc, rightRoom = 170 })

  local box = mk("TextBox", {
    AnchorPoint = Vector2.new(1, 0.5),
    Position = UDim2.new(1, -12, 0.5, 0),
    Size = UDim2.fromOffset(146, 26),
    BackgroundColor3 = T.c.overlay,
    BorderSizePixel = 0,
    Text = opts.default or "",
    PlaceholderText = opts.placeholder or "",
    PlaceholderColor3 = T.c.textOff,
    TextColor3 = T.c.text,
    Font = T.font.body, TextSize = T.size.label,
    TextXAlignment = Enum.TextXAlignment.Left,
    ClearTextOnFocus = false,
    ZIndex = 2, Parent = f,
  })
  L.corner(T.r.sm, box)
  L.pad(0, 8, 0, 8, box)
  local st = L.stroke(T.c.lineStrong, 1, 0.4, box)

  box.Focused:Connect(function() M.to(st, "Color", T.c.accent, "fast") M.to(st, "Transparency", 0.1, "fast") end)
  box.FocusLost:Connect(function(enter)
    M.to(st, "Color", T.c.lineStrong, "fast")
    M.to(st, "Transparency", 0.4, "fast")
    if enter and opts.callback then L.try("input.cb", opts.callback, box.Text) end
  end)

  -- An input row read as dead beside the toggle above it. The guard lifts the
  -- box clear of the Hit overlay so the field still takes the caret, and the
  -- overlay gives the dead space beside a 146 px field a job it never had.
  A.interactive(f, { radius = T.r.md, onClick = function() box:CaptureFocus() end })

  local api = { frame = f, box = box }
  function api:get() return box.Text end
  function api:set(v) box.Text = tostring(v or "") end
  register(opts, api)
  return api
end

-- ---------------------------------------------------------------- textarea
--
-- Full width and several lines tall, for text nobody can write in 146 pixels.
-- MultiLine TextBoxes do not wrap on their own, so TextWrapped is not optional
-- here -- without it a long prompt runs off the right edge and simply vanishes.
function C.textarea(parent, opts)
  opts = opts or {}
  local lines = opts.lines or 4
  local h = 10 + 16 + (lines * 16) + 10

  local f = A.surface({
    Parent = parent, elev = 1, radius = T.r.md,
    Size = UDim2.new(1, 0, 0, h), Name = "TextArea",
  })
  if opts.text then
    A.text({
      Text = opts.text,
      font = T.font.medium, size = T.size.micro, colour = T.c.textMute,
      Position = UDim2.fromOffset(12, 8), Size = UDim2.new(1, -24, 0, 13),
      truncate = true, Parent = f,
    })
  end

  local box = mk("TextBox", {
    Position = UDim2.fromOffset(10, opts.text and 26 or 10),
    Size = UDim2.new(1, -20, 1, opts.text and -36 or -20),
    BackgroundColor3 = T.c.overlay, BorderSizePixel = 0,
    Text = opts.default or "", PlaceholderText = opts.placeholder or "",
    PlaceholderColor3 = T.c.textOff, TextColor3 = T.c.text,
    Font = T.font.body, TextSize = T.size.label,
    TextXAlignment = Enum.TextXAlignment.Left,
    TextYAlignment = Enum.TextYAlignment.Top,
    MultiLine = true, ClearTextOnFocus = false, TextWrapped = true,
    ZIndex = 2, Parent = f,
  })
  L.corner(T.r.sm, box)
  L.pad(6, 8, 6, 8, box)
  local st = L.stroke(T.c.lineStrong, 1, 0.4, box)
  box.Focused:Connect(function()
    M.to(st, "Color", T.c.accent, "fast") M.to(st, "Transparency", 0.1, "fast")
  end)
  box.FocusLost:Connect(function()
    M.to(st, "Color", T.c.lineStrong, "fast") M.to(st, "Transparency", 0.4, "fast")
  end)

  local api = { frame = f, box = box }
  function api:get() return box.Text end
  function api:set(v) box.Text = tostring(v or "") end
  register(opts, api)
  return api
end

-- ---------------------------------------------------------------- output
--
-- Read-only prose of unknown length: a model's answer, an error body. Grows with
-- its content and scrolls past a ceiling, because the one thing it must never do
-- is silently clip the end of an answer.
function C.output(parent, opts)
  opts = opts or {}
  local maxH = opts.maxHeight or 260

  local f = A.surface({
    Parent = parent, elev = 0, radius = T.r.md, line = true,
    Size = UDim2.new(1, 0, 0, 64), Name = "Output",
  })

  local scroll = mk("ScrollingFrame", {
    Position = UDim2.fromOffset(10, 10), Size = UDim2.new(1, -20, 1, -20),
    BackgroundTransparency = 1, BorderSizePixel = 0,
    ScrollBarThickness = 3, ScrollBarImageColor3 = T.c.lineStrong,
    ScrollBarImageTransparency = 0.3,
    CanvasSize = UDim2.new(), AutomaticCanvasSize = Enum.AutomaticSize.Y,
    ZIndex = 2, Parent = f,
  })

  local label = A.text({
    Text = opts.default or "", font = opts.mono and T.font.mono or T.font.body,
    size = T.size.label, colour = T.c.textMute,
    Size = UDim2.new(1, -6, 0, 20), wrap = true,
    Parent = scroll,
  })
  label.TextYAlignment = Enum.TextYAlignment.Top

  -- MEASURED WITH GetTextSize, NOT LEFT TO AutomaticSize. Three separate things
  -- went wrong before this, and the third is why the whole approach changed:
  --
  -- 1. UNITS. AbsoluteSize is real screen pixels, a UDim2 Y offset is pre-UIScale
  --    units. Mixing them multiplied every card by the scale -- measured at 1.6.
  -- 2. TIMING. One deferred frame is not enough for a wrapped label to settle.
  -- 3. TextBounds IS THE RENDERED HEIGHT, AND IT DEADLOCKS. Measured live on the
  --    free-keys card: 490 characters over 14 lines reported TextBounds.Y = 43
  --    while GetTextSize said 224. AutomaticSize faithfully followed the wrong
  --    number, so the label never grew, so its AbsoluteSize never changed, so
  --    nothing ever re-fired the resize. It sat there clipped forever.
  --
  -- GetTextSize asks what the text NEEDS at a given width, which is the question
  -- actually being asked, and it answers before anything is laid out.
  local TS = game:GetService("TextService")
  local function fit()
    if not label.Parent then return end
    local win = L.Hub and L.Hub.window
    local sc = (win and win.scaleObj and win.scaleObj.Scale) or 1
    local w = label.AbsoluteSize.X / sc
    if w < 20 then return end            -- not laid out yet; the signal will call back
    local textH = TS:GetTextSize(label.Text, label.TextSize, label.Font,
                                 Vector2.new(w, 100000)).Y
    if math.abs(label.Size.Y.Offset - textH) >= 1 then
      label.Size = UDim2.new(1, -6, 0, textH)
    end
    local want = math.clamp(textH + 20, 56, maxH)
    if math.abs(f.Size.Y.Offset - want) < 1 then return end
    M.to(f, "Size", UDim2.new(1, 0, 0, want), "fast")
  end
  -- watched on the SCROLL, not the label: the label's size is what fit() writes,
  -- so listening there would retrigger itself
  scroll:GetPropertyChangedSignal("AbsoluteSize"):Connect(fit)

  local api = { frame = f, label = label, scroll = scroll }
  function api:set(text, colour)
    label.Text = tostring(text or "")
    label.TextColor3 = colour or T.c.textMute
    fit()
  end
  function api:get() return label.Text end
  api:set(opts.default or "")
  return api
end

-- ---------------------------------------------------------------- text dots
--
-- A status line whose trailing dots animate while the words hold still. The
-- point is that the COPY stays ordinary text -- animating the whole string makes
-- a label look like it is malfunctioning, whereas animating only the appended
-- marks reads as "still working".
--
-- The dots are separate labels rather than characters appended to the string,
-- because rewriting `Text` every frame reflows the label and makes the words
-- themselves jitter by a pixel. Each dot runs the same pulse on its own phase.
function C.textDots(parent, opts)
  opts = opts or {}
  local count = opts.count or 3
  local period = opts.duration or 1.30      -- one full pass over all the dots
  local stagger = opts.delay or (period / (count + 1))
  local size = opts.size or T.size.label
  local font = opts.font or T.font.body
  local colour = opts.colour or T.c.textMute

  local holder = mk("Frame", {
    BackgroundTransparency = 1, Name = "TextDots",
    Size = opts.Size or UDim2.new(1, 0, 0, size + 6),
    Position = opts.Position, ZIndex = opts.ZIndex or 2, Parent = parent,
  })

  local label = A.text({
    Text = opts.text or "Thinking", font = font, size = size, colour = colour,
    Size = UDim2.new(1, 0, 1, 0), ZIndex = (opts.ZIndex or 2) + 1, Parent = holder,
  })

  -- measured, never assumed: TextBounds is the RENDERED width and lies whenever
  -- the label truncates, so the dots would stack on top of the last glyph
  local TS = game:GetService("TextService")
  local dots, dotW = {}, 0
  local function layout()
    local w = TS:GetTextSize(label.Text, size, font, Vector2.new(1e5, 1e5)).X
    dotW = TS:GetTextSize(".", size, font, Vector2.new(1e5, 1e5)).X
    for i, d in ipairs(dots) do
      d.Position = UDim2.fromOffset(w + 1 + (i - 1) * (dotW + 1), 0)
    end
  end

  for i = 1, count do
    dots[i] = A.text({
      Text = ".", font = font, size = size, colour = colour,
      Size = UDim2.fromOffset(12, size + 6), ZIndex = (opts.ZIndex or 2) + 1,
      Parent = holder,
    })
    dots[i].TextXAlignment = Enum.TextXAlignment.Left
  end
  layout()

  local conn, t0 = nil, os.clock()
  local api = { frame = holder, label = label }

  function api:setText(s)
    label.Text = tostring(s or "")
    layout()
  end
  function api:setColour(c)
    label.TextColor3 = c
    for _, d in ipairs(dots) do d.TextColor3 = c end
  end

  function api:start()
    if conn then return end
    t0 = os.clock()
    conn = L.hold(L.RunService.RenderStepped:Connect(function()
      if not holder.Parent then return end
      local now = os.clock() - t0
      for i, d in ipairs(dots) do
        -- phase 0..1 per dot, offset so they light in sequence
        local ph = ((now - (i - 1) * stagger) / period) % 1
        -- a short bright pass, then a long rest: the same shape as the CSS
        -- keyframes this is modelled on (peak early, settle back)
        local a
        if ph < 0.30 then
          a = ph / 0.30
        elseif ph < 0.62 then
          a = 1 - (ph - 0.30) / 0.32
        else
          a = 0
        end
        d.TextTransparency = 0.78 - 0.78 * a
        d.Position = UDim2.fromOffset(d.Position.X.Offset, -math.floor(a * 2 + 0.5))
      end
    end))
  end

  function api:stop()
    if conn then conn:Disconnect() conn = nil end
    for _, d in ipairs(dots) do
      d.TextTransparency = 0.78
      d.Position = UDim2.fromOffset(d.Position.X.Offset, 0)
    end
  end

  function api:destroy()
    api:stop()
    pcall(function() holder:Destroy() end)
  end

  if opts.autoStart ~= false then api:start() end
  return api
end

-- ---------------------------------------------------------------- log view
--
-- The activity log, rendered. This is the receipt for everything else in Wave 1:
-- an indicator that says "2 contested" is only worth trusting if you can open it
-- and read WHAT is contested and WHEN it stopped holding.
function C.logView(parent, opts)
  opts = opts or {}
  local MAX = opts.max or 80
  local ROW = 20

  local KINDC = {
    fault   = T.c.bad,     refused = T.c.warn,  ok = T.c.ok,
    note    = T.c.textMute, user   = T.c.textDim,
  }

  local holder = mk("Frame", {
    Size = UDim2.new(1, 0, 0, opts.height or 286),
    BackgroundColor3 = T.c.overlay, BackgroundTransparency = 0.4,
    BorderSizePixel = 0, Parent = parent,
  })
  L.corner(T.r.md, holder)
  L.stroke(T.c.line, 1, 0.55, holder)

  local scroll = A.scroll({ Parent = holder, gap = 1, padding = 10 })

  local empty = A.text({
    Text = "Nothing logged yet.", font = T.font.mono, size = T.size.tiny,
    colour = T.c.textOff, align = Enum.TextXAlignment.Center,
    AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, 0.5),
    Size = UDim2.new(1, -20, 0, 16), Parent = holder,
  })

  -- MEASURED, NOT PICKED. The clock column was 52 px wide and "23:56:39" needs
  -- 56 at this font and size, so every row lost the last digit of its seconds --
  -- with no truncation set, so there was not even an ellipsis to hint at it.
  -- Deriving the width from the widest real timestamp cannot drift when the mono
  -- font or the tiny size changes.
  -- Widening the clock pushes every column after it, so the whole row is derived
  -- from one chain. Hardcoding the next offset is how the old 52 survived: each
  -- number looked right on its own.
  local CLOCK_W = math.ceil(game:GetService("TextService")
    :GetTextSize("00:00:00", T.size.tiny, T.font.mono, Vector2.new(1e5, 1e5)).X) + 4
  local GAP, KIND_W, SRC_W = 4, 52, 132
  local KIND_X = CLOCK_W + GAP
  local SRC_X  = KIND_X + KIND_W + GAP
  local MSG_X  = SRC_X + SRC_W + GAP

  local function mkRow(e, order)
    local r = mk("Frame", {
      Size = UDim2.new(1, 0, 0, ROW), BackgroundTransparency = 1,
      LayoutOrder = order, Parent = scroll,
    })
    local col = KINDC[e.kind] or T.c.textMute
    A.text({ Text = e.at, font = T.font.mono, size = T.size.tiny, colour = T.c.textOff,
             Size = UDim2.fromOffset(CLOCK_W, ROW), Parent = r })
    A.text({ Text = e.kind, font = T.font.mono, size = T.size.tiny, colour = col,
             Position = UDim2.fromOffset(KIND_X, 0), Size = UDim2.fromOffset(52, ROW),
             Parent = r })
    -- 132, not 94: sources are qualified ("toggle:Infinite jump"), and a column
    -- that clips them to "toggle:Infinit..." identifies the KIND of control that
    -- failed while hiding WHICH ONE -- the single fact the row exists to carry.
    A.text({ Text = e.src, font = T.font.mono, size = T.size.tiny, colour = T.c.textDim,
             Position = UDim2.fromOffset(SRC_X, 0), Size = UDim2.fromOffset(SRC_W, ROW),
             truncate = true, Parent = r })
    local msg = A.text({ Text = e.text, font = T.font.body, size = T.size.micro,
             colour = T.c.textMute, Position = UDim2.fromOffset(MSG_X, 0),
             Size = UDim2.new(1, -(MSG_X + 42), 0, ROW), truncate = true, Parent = r })
    local cnt = A.text({ Text = e.n > 1 and ("x" .. e.n) or "",
             font = T.font.mono, size = T.size.tiny, colour = col,
             align = Enum.TextXAlignment.Right, AnchorPoint = Vector2.new(1, 0),
             Position = UDim2.new(1, 0, 0, 0), Size = UDim2.fromOffset(38, ROW),
             Parent = r })
    return r, cnt, msg
  end

  local seenSeq, topCnt, topEntry, dropLbl = -1, nil, nil, nil

  local function rebuild()
    for _, c in ipairs(scroll:GetChildren()) do
      if c:IsA("Frame") or (c:IsA("TextLabel") and c.Name ~= "Layout") then c:Destroy() end
    end
    local logs = L.logs
    empty.Visible = #logs == 0
    local shown = math.min(#logs, MAX)
    local order = 0
    for i = #logs, #logs - shown + 1, -1 do
      order = order + 1
      local r, cnt = mkRow(logs[i], order)
      if i == #logs then topCnt, topEntry = cnt, logs[i] end
    end
    -- NO SILENT TRUNCATION. A list that quietly stops at 80 reads as "that is
    -- everything that happened", which is a worse lie than the ones this wave
    -- set out to remove.
    if #logs > shown then
      dropLbl = A.text({
        Text = string.format("... %d older entr%s not shown (%d kept in memory)",
                             #logs - shown, (#logs - shown) == 1 and "y" or "ies", #logs),
        font = T.font.mono, size = T.size.tiny, colour = T.c.textOff,
        Size = UDim2.new(1, 0, 0, ROW), LayoutOrder = order + 1, Parent = scroll,
      })
    end
  end

  local function refresh()
    if L._logSeq ~= seenSeq then
      seenSeq = L._logSeq
      rebuild()
    elseif topCnt and topEntry and topCnt.Parent then
      -- only the newest entry can collapse, so nothing else can have changed
      topCnt.Text = topEntry.n > 1 and ("x" .. topEntry.n) or ""
    end
  end

  refresh()
  task.spawn(function()
    while L.live() and holder.Parent do
      L.try("logview.refresh", refresh)
      task.wait(0.5)
    end
  end)

  return { frame = holder, scroll = scroll, refresh = refresh }
end

end
do -- ==== lm_20_binds.lua ====
-- LUMEN :: KEYBINDS
-- Bind any feature to a key, so the common ones never need the window open.
--
-- One listener for every bind, not one per feature. A bind is refused while text
-- is being typed, while the palette is up, and while a keybind chip is recording.

local L = getgenv().LUMEN

local B = {}
L.Binds = B

B.actions = {}      -- ordered list of { name, label, run, get }
B.byName = {}
B.map = {}          -- name -> KeyCode
B.capturing = false -- set by the keybind control while it listens

-- run: fn(newState) toggles the feature. get: fn() -> state, so a bind can flip.
function B.register(name, label, run, get)
  if B.byName[name] then
    B.byName[name].run, B.byName[name].get = run, get
    B.byName[name].label = label
    return B.byName[name]
  end
  local a = { name = name, label = label, run = run, get = get }
  B.actions[#B.actions + 1] = a
  B.byName[name] = a
  return a
end

function B.keyFor(name) return B.map[name] end

-- Returns the name of whatever else already owns this key, so the caller can warn
-- instead of creating a shortcut that fires two things at once.
function B.conflict(name, key)
  if not key then return nil end
  for other, k in pairs(B.map) do
    if other ~= name and k == key then return other end
  end
  return nil
end

function B.set(name, key)
  B.map[name] = key
  local out = {}
  for n, k in pairs(B.map) do out[n] = k.Name end
  if L.Cfg then L.Cfg.set("binds", out) end
  return true
end

-- Restore from config. Names that no longer exist are dropped, not kept as dead
-- entries: features get renamed, and a bind to nothing is a key silently lost.
function B.load()
  local saved = L.Cfg and L.Cfg.data.binds
  if type(saved) ~= "table" then return end
  for name, keyName in pairs(saved) do
    if type(keyName) == "string" and B.byName[name] then
      local ok, k = pcall(function() return Enum.KeyCode[keyName] end)
      if ok and k then B.map[name] = k end
    end
  end
end

local function blocked()
  if not L.live() then return true end
  if B.capturing then return true end
  if L.Palette and L.Palette.open then return true end
  if L.UIS:GetFocusedTextBox() then return true end
  return false
end

L.hold(L.UIS.InputBegan:Connect(function(input, typing)
  if typing or blocked() then return end
  if input.UserInputType ~= Enum.UserInputType.Keyboard then return end
  for _, a in ipairs(B.actions) do
    if B.map[a.name] == input.KeyCode then
      -- Not `a.get and (not a.get()) or true`: the and/or idiom cannot carry a
      -- false value, so that form is always true and could only switch things on.
      local now = true
      if a.get then now = not a.get() end
      local ran, ok, why = L.try("bind:" .. a.name, a.run, now)
      -- the window may be closed, so the toast is the feedback
      if L.Toast and L.Cfg and L.Cfg.data.notify ~= false then
        if ran and ok ~= false then
          L.Toast.info(a.label, now and "on" or "off")
        else
          L.Toast.warn(a.label, tostring(why or "did not engage"))
        end
      end
      L.note("bind", a.label .. " -> " .. (now and "on" or "off"))
    end
  end
end))

end
do -- ==== lm_29_pins.lua ====
-- LUMEN :: PINS
-- Favourite features, reachable from the minimised pill.
--
-- The hub is eight tabs deep. Half of what anyone actually uses is three or
-- four switches and a couple of buttons, and hunting for them through the nav
-- every time is the tax you pay for having a big interface. DEV HUD solves this
-- with a quick strip; this is the same idea wired into LUMEN's dock.
--
-- WHAT MAKES IT WORK IS THAT CONTROLS REGISTER THEMSELVES. A pin is not a
-- second implementation of a feature -- it is a handle on the control that
-- already exists, so a pinned toggle and its switch in the tab are the same
-- object and can never disagree. Controls hand us their api at construction;
-- the strip only ever calls back into it.
--
-- The strip is parented to the dock, so it inherits the dock's position and
-- every minimise/restore animation for free rather than needing a second clock
-- to chase it with.

local L = getgenv().LUMEN
local T, M, A = L.T, L.Motion, L.A
local mk = L.mk

local P = {}
L.Pins = P

P.registry = {}      -- id -> { id, label, kind, get, set, run, ctx }
P.order = {}         -- registration order, so the manager lists them sensibly

local CHIP_W, CHIP_H, GAP = 34, 26, 5
P.HOLD = 0.5      -- seconds of press before a chip unpins itself

-- ---------------------------------------------------------------- registry

-- kind: "toggle" needs get+set; "action" needs run.
function P.register(id, spec)
  if type(id) ~= "string" or id == "" or type(spec) ~= "table" then return end
  if not P.registry[id] then P.order[#P.order + 1] = id end
  spec.id = id
  spec.label = spec.label or id
  P.registry[id] = spec
  -- A pin saved from a previous session only becomes real when the control that
  -- owns it is built, which is why the strip refreshes on registration.
  --
  -- WRAPPED, BECAUSE THIS RUNS INSIDE TAB CONSTRUCTION. Registration happens
  -- while a page is being built, so anything that throws in here escapes into
  -- the middle of a builder. That is not hypothetical: a call to a helper that
  -- did not exist took out the Universal page and, with it, every tab after it.
  -- The strip is decoration; it must never be able to cost somebody their hub.
  if L.Cfg and L.Cfg.pinned and L.Cfg.pinned(id) then
    L.try("pins.refresh", P.refresh)
  end
end

function P.forget(id)
  P.registry[id] = nil
end

-- Everything currently registered, for the manager list in Interface.
function P.list()
  local out = {}
  for _, id in ipairs(P.order) do
    local s = P.registry[id]
    if s then out[#out + 1] = s end
  end
  return out
end

-- A short, readable chip label. "combat.fling.Launch power" -> "Launch power",
-- then trimmed to something that fits 34px without becoming an initialism
-- nobody can read.
-- A LABEL THAT DISTINGUISHES, not merely one that fits.
--
-- Truncating to the first five characters produced a dock reading
-- "Fly / Open / Anti- / Nocli / Anti- / Infin / Open" -- two "Anti-" and two
-- "Open", so the strip told you how many things were pinned and nothing about
-- which. A quick-access bar whose buttons cannot be told apart is worse than no
-- quick-access bar.
--
-- Multi-word names become initials, which stays unique where truncation
-- collides: "Anti-fling" and "Anti-AFK" are AF and AA, "Open player panel" is
-- OPP. Single words keep their letters. Anything still colliding gets a digit,
-- because two identical chips is the one outcome worth avoiding outright.
local function baseLabel(spec)
  local label = tostring(spec.short or spec.label or spec.id)
  label = label:gsub("^.*%.", "")                     -- drop the id prefix
  local words = {}
  for w in label:gmatch("[%a%d]+") do words[#words + 1] = w end
  if #words >= 2 then
    local ini = ""
    for i = 1, math.min(#words, 3) do ini = ini .. words[i]:sub(1, 1):upper() end
    return ini
  end
  local one = words[1] or label
  return (#one > 5) and one:sub(1, 5) or one
end

local function chipLabels(specs)
  local seen, out = {}, {}
  for i, spec in ipairs(specs) do
    local base = baseLabel(spec)
    local text, n = base, 1
    while seen[text] do
      n = n + 1
      text = base .. n
    end
    seen[text] = true
    out[i] = text
  end
  return out
end

-- ---------------------------------------------------------------- the strip

function P.attach(dock)
  if not dock then return end
  -- A CanvasGroup makes the whole quick strip one visual unit during the dock
  -- morph. The window animates GroupTransparency once, so chip plates, labels,
  -- dots and strokes cannot reveal on four slightly different spring clocks.
  P.bar = mk("CanvasGroup", {
    AnchorPoint = Vector2.new(0, 0),
    -- a child of the dock, so it rides every minimise and restore without a
    -- second animation chasing the first
    Position = UDim2.new(1, 8, 0, 5),
    Size = UDim2.fromOffset(0, CHIP_H),
    BackgroundTransparency = 1, GroupTransparency = 0, BorderSizePixel = 0,
    ZIndex = 6, Name = "PinBar", Parent = dock,
  })
  -- SECOND BAR, GROWING LEFT. A strip that only ever extends right walks off
  -- the screen once more than a handful are pinned, and the pill is rarely
  -- against the left edge -- so half the available space went unused. Anchored
  -- at the dock's left edge with AnchorPoint 1 on X, it grows away from the
  -- dock in the opposite direction.
  --
  -- A SEPARATE CanvasGroup, not negative offsets inside the first: a CanvasGroup
  -- renders its children into a buffer its own size, so a chip placed at a
  -- negative X inside the right-hand bar would simply be clipped away.
  P.barL = mk("CanvasGroup", {
    AnchorPoint = Vector2.new(1, 0),
    Position = UDim2.new(0, -8, 0, 5),
    Size = UDim2.fromOffset(0, CHIP_H),
    BackgroundTransparency = 1, GroupTransparency = 0, BorderSizePixel = 0,
    ZIndex = 6, Name = "PinBarLeft", Parent = dock,
  })
  P.bars = { P.bar, P.barL }
  P.dock = dock
  P.refresh()
  return P.bar
end

local function paintChip(chip, spec)
  if spec.kind ~= "toggle" or not spec.get then return end
  local on = false
  pcall(function() on = spec.get() and true or false end)
  M.to(chip.dot, "BackgroundColor3", on and T.c.accent or T.c.textOff, "fast")
  M.to(chip.dot, "BackgroundTransparency", on and 0 or 0.45, "fast")
  M.to(chip.lbl, "TextColor3", on and T.c.text or T.c.textDim, "fast")
  M.to(chip.stroke, "Color", on and T.c.accent or T.c.lineStrong, "fast")
  M.to(chip.stroke, "Transparency", on and 0.25 or 0.55, "fast")
end

function P.refresh()
  if not (P.bar and P.bar.Parent) then return end
  for _, bar in ipairs(P.bars or { P.bar }) do
    for _, c in ipairs(bar:GetChildren()) do
      if c:IsA("GuiObject") then c:Destroy() end
    end
  end
  P.chips = {}

  local ids = (L.Cfg and L.Cfg.pins and L.Cfg.pins()) or {}
  -- resolve every spec up front: the labels are chosen as a SET so two chips
  -- can never end up saying the same thing
  local specs = {}
  for _, id in ipairs(ids) do
    if P.registry[id] then specs[#specs + 1] = P.registry[id] end
  end
  local labels = chipLabels(specs)

  -- HOW MANY FIT BEFORE THE EDGE, measured rather than guessed at. The pill sits
  -- wherever it was last dragged, so the room to its right is not a constant.
  local vpx = (L.viewport and L.viewport().X) or 1920
  local dockRight = 0
  pcall(function()
    dockRight = P.dock.AbsolutePosition.X + P.dock.AbsoluteSize.X
  end)
  local roomRight = math.max(0, vpx - dockRight - 24)
  local perRight = math.max(1, math.floor(roomRight / (CHIP_W + GAP)))

  -- NEAREST SIDE FIRST, AND STABLE. Chips fill the right until it is full and
  -- then continue on the left, so adding a pin only ever APPENDS. A rule that
  -- balanced the two sides evenly would instead reshuffle chips across the dock
  -- every time the count changed, and a control that moves when you add a
  -- different one is worse than a control in an awkward place.
  local nR, nL = 0, 0
  for si, spec in ipairs(specs) do
    local id = spec.id
    do
      local onRight = nR < perRight
      local slot = onRight and nR or nL
      local parentBar = onRight and P.bar or P.barL
      local f = mk("Frame", {
        Position = UDim2.fromOffset(slot * (CHIP_W + GAP), 0),
        Size = UDim2.fromOffset(CHIP_W, CHIP_H),
        BackgroundColor3 = T.c.raised, BackgroundTransparency = 0.15,
        BorderSizePixel = 0, ZIndex = 6, Name = "Pin", Parent = parentBar,
      })
      L.corner(T.r.sm, f)
      local stroke = L.stroke(T.c.lineStrong, 1, 0.55, f)

      -- a state dot for toggles, so the strip reports as well as commands
      local dot = mk("Frame", {
        AnchorPoint = Vector2.new(0.5, 0),
        Position = UDim2.new(0.5, 0, 0, 4), Size = UDim2.fromOffset(4, 4),
        BackgroundColor3 = T.c.textOff, BackgroundTransparency = 0.45,
        BorderSizePixel = 0, ZIndex = 7, Parent = f,
      })
      L.corner(999, dot)

      local lbl = A.text({
        Text = labels[si], font = T.font.medium, size = T.size.nano,
        colour = T.c.textDim, align = Enum.TextXAlignment.Center,
        Position = UDim2.fromOffset(0, 10), Size = UDim2.new(1, 0, 0, 12),
        ZIndex = 7, Parent = f,
      })

      local chip = { frame = f, dot = dot, lbl = lbl, stroke = stroke, spec = spec }
      P.chips[#P.chips + 1] = chip

      -- HOLD TO UNPIN, WITH THE HOLD MADE VISIBLE. A press that appears to do
      -- nothing for half a second reads as a dead control, so the fill is the
      -- affordance: it says something is happening and how much longer it wants.
      local fill = mk("Frame", {
        Size = UDim2.new(0, 0, 1, 0), BackgroundColor3 = T.c.accent,
        BackgroundTransparency = 0.55, BorderSizePixel = 0,
        ZIndex = 6, Name = "Hold", Parent = f,
      })
      L.corner(T.r.sm, fill)
      chip.fill = fill
      local holdConn, holdStart
      local function endHold(done)
        if holdConn then holdConn:Disconnect() holdConn = nil end
        holdStart = nil
        if fill.Parent then
          if done then M.set(fill, "Size", UDim2.new(0, 0, 1, 0))
          else M.to(fill, "Size", UDim2.new(0, 0, 1, 0), "fast") end
        end
      end
      f.InputBegan:Connect(function(i)
        if i.UserInputType ~= Enum.UserInputType.MouseButton1 then return end
        holdStart = os.clock()
        chip.heldFired = false
        if holdConn then holdConn:Disconnect() end
        holdConn = L.RunService.RenderStepped:Connect(function()
          if not (holdStart and fill.Parent) then return end
          local prog = math.clamp((os.clock() - holdStart) / P.HOLD, 0, 1)
          fill.Size = UDim2.new(prog, 0, 1, 0)
          if prog >= 1 then
            chip.heldFired = true
            endHold(true)
            if L.Cfg and L.Cfg.setPin then L.Cfg.setPin(id, false) end
            if L.Toast then L.Toast.info("Unpinned", spec.label) end
            P.refresh()
          end
        end)
      end)
      f.InputEnded:Connect(function(i)
        if i.UserInputType == Enum.UserInputType.MouseButton1 then endHold(false) end
      end)
      f.MouseLeave:Connect(function() endHold(false) end)

      A.interactive(f, { radius = T.r.sm, spotSize = 40, onClick = function()
        -- a completed hold has already acted; releasing after it must not also
        -- toggle the feature it just unpinned
        if chip.heldFired then chip.heldFired = false return end
        if spec.kind == "action" then
          if spec.run then L.try("pin.run", spec.run) end
          return
        end
        if not (spec.get and spec.set) then return end
        local now = false
        pcall(function() now = spec.get() and true or false end)
        L.try("pin.set", spec.set, not now)
        paintChip(chip, spec)
      end })

      A.explain(f, spec.label .. (spec.kind == "toggle"
        and "  -- click to switch it on or off, hold to unpin"
        or "  -- click to run it, hold to unpin"))
      paintChip(chip, spec)
      if onRight then nR = nR + 1 else nL = nL + 1 end
    end
  end

  local function span(k) return math.max(0, k * (CHIP_W + GAP) - GAP) end
  P.bar.Size = UDim2.fromOffset(span(nR), CHIP_H)
  P.bar.Visible = nR > 0
  if P.barL then
    P.barL.Size = UDim2.fromOffset(span(nL), CHIP_H)
    P.barL.Visible = nL > 0
  end
  P.lastSplit = { right = nR, left = nL, perRight = perRight }
end

-- The strip reports live state, so a feature switched off from its tab (or by a
-- keybind, or by the watchdog) must not leave a lit chip behind. Polled rather
-- than subscribed: there is no change signal on a plain Lua flag, and six chips
-- at 4Hz is nothing.
task.spawn(function()
  while true do
    task.wait(0.25)
    if L.live() and P.chips and P.bar and P.bar.Parent and P.bar.Visible then
      for _, c in ipairs(P.chips) do paintChip(c, c.spec) end
    end
  end
end)

end
do -- ==== lm_07_toast.lua ====
-- LUMEN :: TOAST
-- Notifications, bottom-right, four visible at once and the rest queued.
-- Repeats of the same message collapse into a count rather than stacking, and
-- the stack springs into gaps instead of relaying out.
-- The card is a CanvasGroup so its whole subtree fades as one image; fading
-- label by label reads as several things appearing separately.

local L = getgenv().LUMEN
local T, M, A = L.T, L.Motion, L.A
local mk = L.mk

local Toast = {}
L.Toast = Toast

local W, GAP, MARGIN = 300, 8, 18
local RISE  = 22      -- how far below its resting place a toast starts
local SMALL = 0.90    -- and how far under full size
-- read live, so changing it in Interface takes effect on the next toast
local function MAX_VISIBLE()
  return math.floor((L.Cfg and tonumber(L.Cfg.data.toastMax)) or 4)
end

local live, queue = {}, {}
local departing = 0

-- ---------------------------------------------------------------- easing
-- A curve, not a spring: duration 0.4s, cubic-bezier(0.25, 0.46, 0.45, 0.94).
-- TweenService has no arbitrary bezier, so the curve is solved directly (Newton
-- on X for the parameter, then read Y) and driven per frame.
local EASE = { 0.25, 0.46, 0.45, 0.94 }

local function bezier(t)
  if t <= 0 then return 0 end
  if t >= 1 then return 1 end
  local x1, y1, x2, y2 = EASE[1], EASE[2], EASE[3], EASE[4]
  local u = t
  for _ = 1, 5 do
    local mu = 1 - u
    local x = 3 * mu * mu * u * x1 + 3 * mu * u * u * x2 + u * u * u
    local dx = 3 * mu * mu * x1 + 6 * mu * u * (x2 - x1) + 3 * u * u * (1 - x2)
    if math.abs(dx) < 1e-6 then break end
    u = u - (x - t) / dx
  end
  local mu = 1 - u
  return 3 * mu * mu * u * y1 + 3 * mu * u * u * y2 + u * u * u
end

-- One driver per (object, property). Re-targeting mid-flight restarts from where
-- it is, so a toast still sliding when the stack shifts does not jump.
-- Keyed on the instance, not tostring(it): tostring(Instance) returns its Name
-- and every wrapper is called "Toast", so string keys collapse onto one entry.
local drives = setmetatable({}, { __mode = "k" })
local function easeTo(obj, prop, target, dur, onDone)
  if not obj then return end
  local perObj = drives[obj]
  if not perObj then perObj = {} drives[obj] = perObj end
  local d = perObj[prop]
  if d then d.dead = true end
  local from = obj[prop]
  local t0 = os.clock()
  dur = dur or 0.4
  local rec = { dead = false }
  perObj[prop] = rec
  task.spawn(function()
    while not rec.dead do
      if not obj.Parent then
        if perObj[prop] == rec then perObj[prop] = nil end
        return
      end
      local a = math.clamp((os.clock() - t0) / dur, 0, 1)
      local e = bezier(a)
      if typeof(from) == "UDim2" then
        obj[prop] = UDim2.new(
          from.X.Scale + (target.X.Scale - from.X.Scale) * e,
          from.X.Offset + (target.X.Offset - from.X.Offset) * e,
          from.Y.Scale + (target.Y.Scale - from.Y.Scale) * e,
          from.Y.Offset + (target.Y.Offset - from.Y.Offset) * e)
      else
        obj[prop] = from + (target - from) * e
      end
      if a >= 1 then
        -- only clear our OWN row: a newer drive may already own this slot
        if perObj[prop] == rec then perObj[prop] = nil end
        if onDone then L.try("toast.done", onDone) end
        return
      end
      L.RunService.Heartbeat:Wait()
    end
  end)
end


local KIND = {
  info = { colour = T.c.accent, icon = "dot" },
  ok   = { colour = T.c.ok,     icon = "check" },
  warn = { colour = T.c.warn,   icon = "bars" },
  bad  = { colour = T.c.bad,    icon = "close" },
}

local function ensureHost()
  if Toast.gui and Toast.gui.Parent then return Toast.gui end
  local gui = mk("ScreenGui", {
    Name = "LumenToasts", ResetOnSpawn = false, IgnoreGuiInset = true,
    ZIndexBehavior = Enum.ZIndexBehavior.Sibling, DisplayOrder = 20,
  })
  gui.Parent = L.host()
  L.own(gui)
  mk("UIScale", { Scale = L.autoScale(), Parent = gui })

  -- The column fades at its top edge so a tall stack dissolves upward instead of
  -- reading as a wall.
  local fade = mk("Frame", {
    AnchorPoint = Vector2.new(1, 1),
    Position = UDim2.new(1, 0, 1, 0), Size = UDim2.fromOffset(W + MARGIN * 2, 420),
    BackgroundTransparency = 1, ZIndex = 0, Name = "FadeHost", Parent = gui,
  })
  Toast.fadeHost = fade
  Toast.gui = gui
  return gui
end

-- ---------------------------------------------------------------- overflow pill

local morePill, moreLbl
local function updateMore()
  local n = #queue
  if n == 0 then
    if morePill then A.groupTo(morePill, 1, "fast") end
    return
  end
  if not morePill then
    local gui = ensureHost()
    morePill = mk("CanvasGroup", {
      AnchorPoint = Vector2.new(1, 1),
      Position = UDim2.new(1, -MARGIN, 1, -MARGIN),
      Size = UDim2.fromOffset(112, 22),
      BackgroundColor3 = T.c.overlay, BackgroundTransparency = 0.05,
      GroupTransparency = 1,
      BorderSizePixel = 0, Parent = gui,
    })
    L.corner(999, morePill)
    L.stroke(T.c.lineStrong, 1, 0.35, morePill)
    moreLbl = A.text({
      Text = "", font = T.font.mono, size = T.size.tiny, colour = T.c.textDim,
      align = Enum.TextXAlignment.Center, Parent = morePill,
    })
  end
  moreLbl.Text = string.format("+%d waiting", n)
  A.groupTo(morePill, 0, "fast")
end

-- Recompute every visible toast's resting Y from the bottom up and spring it.
local function restack()
  local y = -MARGIN - (#queue > 0 and 28 or 0)
  for i = #live, 1, -1 do
    local t = live[i]
    if t.wrap.Parent then
      t.restY = y
      easeTo(t.wrap, "Position", UDim2.new(1, -MARGIN, 1, y), 0.4)
      y = y - (t.height + GAP)
    end
  end
  updateMore()
end

local spawnOne   -- forward declaration: dismiss promotes from the queue

-- Fade, shrink and sink: the entrance played backwards.
local function dismiss(entry)
  if not entry.alive then return end
  entry.alive = false
  for i, e in ipairs(live) do
    if e == entry then table.remove(live, i) break end
  end
  departing = departing + 1

  -- Every part of the exit shares OUT, or the card keeps settling after it has
  -- left.
  local OUT = 0.26
  local finished = false
  local function finishDeparture()
    if finished then return end
    finished = true
    departing = math.max(0, departing - 1)
    pcall(function() entry.wrap:Destroy() end)
    -- A queued card takes the slot only once the departing one is fully gone.
    if #queue > 0 and (#live + departing) < MAX_VISIBLE() then
      local nextOpts = table.remove(queue, 1)
      spawnOne(nextOpts)
    else
      updateMore()
    end
  end
  entry.wrap.Destroying:Connect(finishDeparture)
  easeTo(entry.wrap, "GroupTransparency", 1, OUT, finishDeparture)
  easeTo(entry.scale, "Scale", SMALL, OUT)
  easeTo(entry.wrap, "Position",
    UDim2.new(1, -MARGIN + W * 0.5, 1, entry.restY or -MARGIN), OUT)

  restack()
end

function spawnOne(opts)
  local kind = KIND[opts.kind or "info"] or KIND.info
  local gui = ensureHost()
  local hasBody = opts.body and opts.body ~= ""
  local height = hasBody and 70 or 48
  local elev = T.elev[2]

  -- The wrapper carries position and scale only. Everything visible is a child
  -- of it, so one UIScale pulls the card, its halo and its shadow together --
  -- scaling the card alone would leave the shadow the wrong size mid-flight.
  local wrap = mk("CanvasGroup", {
    AnchorPoint = Vector2.new(1, 1),
    Position = UDim2.new(1, -MARGIN, 1, -MARGIN + RISE),
    Size = UDim2.fromOffset(W, height),
    BackgroundTransparency = 1, GroupTransparency = 1, BorderSizePixel = 0,
    Name = "Toast", Parent = gui,
  })
  local scale = mk("UIScale", { Scale = SMALL, Parent = wrap })

  -- THE DEFOCUS GHOST IS GONE, and it is worth saying why because the idea was
  -- sound and the result was not.
  --
  -- The entrance used to crossfade a soft silhouette of the card into the sharp
  -- card, imitating something pulling into focus. The silhouette was the 9-slice
  -- shadow sprite tinted with the card's own fill -- which on a dark theme is a
  -- DARK RECTANGLE, larger than the card, drawn at 0.06 transparency on the
  -- first frame while the card itself was still fully invisible.
  --
  -- So every notification opened with a dark box appearing on its own, holding
  -- for a beat, and then dissolving as the card arrived. Read as an artifact,
  -- because it is one: nothing in the interface has a reason to be a dark
  -- rectangle. The concept only works if the blob is genuinely a blurred copy of
  -- the card, and Roblox has no GUI blur, so there was never a version of this
  -- that was going to land.
  --
  -- What replaces it: the card fades and rises on one clock, and its shadow is
  -- on the SAME clock so the pair arrives as one object. No stand-in, nothing
  -- that exists only during the transition.
  local drop = A.shadow(nil, {
    Parent = wrap, spread = 24, alpha = 0.42, lift = 8, ZIndex = 0,
  })

  -- A small, PERMANENT colour bloom behind the icon well -- not a flash that
  -- fades out. The old one animated from visible to invisible during the
  -- entrance, which is another thing appearing and then leaving for no reason
  -- the viewer can name.
  local bloom = A.glow(wrap, 78, kind.colour, {
    alpha = 0.72, ZIndex = 2,
    Position = UDim2.new(0, 22, 0.5, 0),
  })

  local card = mk("CanvasGroup", {
    AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, 0.5),
    Size = UDim2.fromOffset(W, height),
    BackgroundColor3 = elev.fill, BackgroundTransparency = 0,
    BorderSizePixel = 0, GroupTransparency = 0,
    ZIndex = 4, Name = "Card", Parent = wrap,
  })
  L.corner(T.r.md, card)
  L.stroke(elev.line, 1, elev.lineT, card)
  mk("Frame", {
    Size = UDim2.new(1, -T.r.md * 2, 0, 1), Position = UDim2.new(0, T.r.md, 0, 0),
    BackgroundColor3 = Color3.new(1, 1, 1), BackgroundTransparency = 0.92,
    BorderSizePixel = 0, ZIndex = 2, Parent = card,
  })

  -- ---- the card's face ---------------------------------------------------
  --
  -- The first version was a coloured bar, a glyph and two lines of text, which
  -- is the shape every hub ships and reads as a debug print with rounded
  -- corners. What was missing was HIERARCHY: nothing told the eye where to land
  -- first, so it landed everywhere.
  --
  -- Now the status colour is carried by a filled disc that the glyph sits
  -- inside, which gives the card one clear anchor point on the left; the title
  -- is heavier and the body is dimmer, so the two lines separate at a glance;
  -- and the accent runs as a soft vertical wash off the left edge rather than a
  -- hard three-pixel rule, so the colour is present without being a stripe.
  local edge = mk("Frame", {
    Size = UDim2.new(0, 64, 1, 0), BackgroundColor3 = kind.colour,
    BackgroundTransparency = 0.86, BorderSizePixel = 0, ZIndex = 1, Parent = card,
  })
  mk("UIGradient", {
    Transparency = NumberSequence.new({
      NumberSequenceKeypoint.new(0.00, 0.10),
      NumberSequenceKeypoint.new(1.00, 1.00),
    }),
    Parent = edge,
  })

  -- the icon well: a filled disc in the status colour, glyph knocked out of it
  local well = mk("Frame", {
    AnchorPoint = Vector2.new(0, 0.5),
    Position = UDim2.new(0, 12, 0.5, 0), Size = UDim2.fromOffset(26, 26),
    BackgroundColor3 = kind.colour, BackgroundTransparency = 0.18,
    BorderSizePixel = 0, ZIndex = 3, Parent = card,
  })
  L.corner(999, well)
  L.stroke(kind.colour, 1, 0.45, well)

  local glyph = (A.Icon[kind.icon] or A.Icon.dot)(well, 13, T.c.accentInk)
  glyph.AnchorPoint = Vector2.new(0.5, 0.5)
  glyph.Position = UDim2.fromScale(0.5, 0.5)
  glyph.ZIndex = 4

  -- ---- the two lines ------------------------------------------------------
  -- Title heavier, body dimmer and a size smaller: the separation is what lets
  -- the pair be read as one message with a headline rather than two sentences.
  local titleLbl = A.text({
    Text = opts.title or "Notice",
    font = T.font.strong, size = T.size.label, colour = T.c.text,
    Position = UDim2.fromOffset(50, hasBody and 12 or 0),
    Size = hasBody and UDim2.new(1, -96, 0, 15) or UDim2.new(1, -96, 1, 0),
    truncate = true, ZIndex = 3, Parent = card,
  })
  if hasBody then
    A.text({
      Text = opts.body, font = T.font.body, size = T.size.micro,
      colour = T.c.textMute, valign = Enum.TextYAlignment.Top,
      Position = UDim2.fromOffset(50, 29), Size = UDim2.new(1, -62, 0, 24),
      wrap = true, ZIndex = 3, Parent = card,
    })
  end

  -- repeat counter, hidden until it is needed
  local countLbl = A.text({
    Text = "", font = T.font.mono, size = T.size.tiny, colour = kind.colour,
    align = Enum.TextXAlignment.Right, AnchorPoint = Vector2.new(1, 0),
    Position = UDim2.new(1, -12, 0, hasBody and 12 or 0),
    Size = hasBody and UDim2.fromOffset(40, 15) or UDim2.new(0, 40, 1, 0),
    ZIndex = 4, Parent = card,
  })

  -- INSET AND ROUNDED, not a full-width rule welded to the bottom edge. A bar
  -- that runs corner to corner fights the card's own radius and reads as a
  -- progress bar for the card rather than a clock on the message.
  local timerTrack = mk("Frame", {
    AnchorPoint = Vector2.new(0, 1),
    Position = UDim2.new(0, 12, 1, -7), Size = UDim2.new(1, -24, 0, 2),
    BackgroundColor3 = T.c.line, BackgroundTransparency = 0.55,
    BorderSizePixel = 0, ZIndex = 3, Parent = card,
  })
  L.corner(999, timerTrack)
  local timer = mk("Frame", {
    Size = UDim2.new(1, 0, 1, 0), BackgroundColor3 = kind.colour,
    BackgroundTransparency = 0.15, BorderSizePixel = 0, ZIndex = 4,
    Parent = timerTrack,
  })
  L.corner(999, timer)

  local entryHovered = false
  local entry = {
    wrap = wrap, card = card, scale = scale, bloom = bloom,
    drop = drop, height = height, alive = true, count = 1,
    key = (opts.title or "") .. "|" .. (opts.body or ""),
    countLbl = countLbl, title = titleLbl,
    life = opts.duration or (L.Cfg and tonumber(L.Cfg.data.toastDur)) or 4.5, born = os.clock(),
    onAction = opts.onAction,
  }
  live[#live + 1] = entry
  -- AN ACTIONABLE TOAST. A card click has always dismissed; if the caller
  -- supplies onAction it now RUNS first and dismisses after, so a notice can
  -- offer the one obvious response to itself instead of only reporting.
  -- Used by the restored-settings notice, which needs a one-click undo to be
  -- honest about re-arming features.
  A.interactive(card, { radius = T.r.md, onClick = function()
    if type(entry.onAction) == "function" then
      L.try("toast.action", entry.onAction)
    end
    dismiss(entry)
  end })

  -- ---- entrance ----------------------------------------------------------
  --
  -- Slide in from the right on the list's own curve, while the stack above
  -- shifts up on the SAME curve and duration -- so the arrival and the
  -- rearrangement read as one motion instead of two things happening near each
  -- other. Scale and the defocus blob ride along, which is what stops it
  -- looking like a rectangle being translated.
  -- ONE CLOCK FOR EVERY PART OF IT.
  --
  -- These used to run on 0.4 / 0.4 / 0.4 / 0.45 / 0.34, which is five things
  -- finishing at four different moments. Individually each is defensible;
  -- together they read as a card that keeps settling after it has arrived, and
  -- the shadow in particular finished last, so it looked like it was catching
  -- up with the card it belongs to.
  --
  -- Everything that is part of "the toast appearing" now shares IN, so the
  -- whole thing lands as a single object.
  local IN = 0.40
  wrap.Position = UDim2.new(1, -MARGIN + W * 0.55, 1, -MARGIN)
  restack()
  easeTo(scale, "Scale", 1, IN)
  easeTo(wrap, "GroupTransparency", 0, IN)

  -- ---- hover: lift, and hold the clock ------------------------------------
  -- Reading a notification should not be a race. Hovering pauses the timer and
  -- lifts the card slightly, which is also the affordance that says it can be
  -- interacted with at all.
  local hit = card:FindFirstChild("Hit")
  if hit then
    hit.MouseEnter:Connect(function()
      entryHovered = true
      easeTo(scale, "Scale", 1.03, 0.18)
    end)
    hit.MouseLeave:Connect(function()
      entryHovered = false
      easeTo(scale, "Scale", 1, 0.18)
    end)
  end

  -- The timer bar is the one place a linear curve is correct: it is a literal
  -- readout of remaining time, so easing it would misreport the clock.
  task.spawn(function()
    local held = 0
    while L.live() and entry.alive do
      -- paused while hovered: the clock stops rather than the bar freezing at a
      -- lie, so releasing resumes from where it actually was
      if entryHovered then
        held = held + L.RunService.Heartbeat:Wait()
      else
        L.RunService.Heartbeat:Wait()
      end
      local a = 1 - math.clamp((os.clock() - entry.born - held) / entry.life, 0, 1)
      timer.Size = UDim2.new(a, 0, 1, 0)
      -- dims as it empties, so a nearly-spent toast recedes
      timer.BackgroundTransparency = 0.15 + (1 - a) * 0.45
      if a <= 0 then break end
    end
    if entry.alive then dismiss(entry) end
  end)

  return entry
end

-- ---------------------------------------------------------------- api

function Toast.push(opts)
  opts = opts or {}
  local key = (opts.title or "") .. "|" .. (opts.body or "")

  -- collapse a repeat of the most recent message rather than stacking it
  local newest = live[#live]
  if newest and newest.alive and newest.key == key then
    newest.count = newest.count + 1
    newest.countLbl.Text = "x" .. newest.count
    newest.born = os.clock()             -- restart its clock
    -- a nudge of the same focus pull, so a repeat reads as the SAME card being
    -- struck again rather than as a new one that failed to appear
    M.set(newest.scale, "Scale", 0.965)
    M.to(newest.scale, "Scale", 1, "fast")
    return { dismiss = function() dismiss(newest) end, frame = newest.card }
  end

  if (#live + departing) >= MAX_VISIBLE() then
    queue[#queue + 1] = opts
    -- never let the backlog itself become a leak
    if #queue > 40 then table.remove(queue, 1) end
    updateMore()
    return { queued = true }
  end

  local e = spawnOne(opts)
  return { dismiss = function() dismiss(e) end, frame = e.card }
end

function Toast.clear()
  -- EMPTY THE QUEUE FIRST. dismiss() promotes the next queued toast into the
  -- freed slot, so clearing while the queue still had items refilled the stack
  -- as fast as it was emptied -- a burst of 14 "cleared" straight back into 4
  -- live toasts, and the next push then failed to collapse against them because
  -- it was comparing itself to a resurrected message.
  queue = {}
  for i = #live, 1, -1 do dismiss(live[i]) end
  updateMore()
end

function Toast.stats() return { visible = #live, departing = departing, queued = #queue } end

function Toast.info(title, body) return Toast.push({ title = title, body = body, kind = "info" }) end
function Toast.ok(title, body)   return Toast.push({ title = title, body = body, kind = "ok" }) end
function Toast.warn(title, body) return Toast.push({ title = title, body = body, kind = "warn" }) end
function Toast.bad(title, body)  return Toast.push({ title = title, body = body, kind = "bad" }) end

end
do -- ==== lm_13_backdrop.lua ====
-- LUMEN :: BACKDROP
-- The living background behind the loading screen: drifting wash, sparse stars,
-- a slow light sweep, edge falloff. Fadable parts are registered with the caller
-- rather than wrapped in a CanvasGroup, which would cost the text its crispness.

local L = getgenv().LUMEN
local T = L.T
local A = L.A
local mk = L.mk

local Backdrop = {}
L.Backdrop = Backdrop

local TICK = 1 / 30

-- ---------------------------------------------------------------- styles
--
-- Every layer is built once and a style decides which are live, so `faders()` and
-- `destroy()` still walk one known tree and switching styles sets flags rather
-- than rebuilding a screen the user is looking at.
Backdrop.STYLES = { "Nebula", "Aurora", "Particles", "Plain" }
Backdrop.DEFAULT_STYLE = "Nebula"

-- These describe the hub; the loading screen follows the same choice.
Backdrop.STYLE_DESC = {
  Nebula    = "The Saturn and a still dot lattice -- quiet behind live controls",
  Aurora    = "Slow iridescent colour fields drifting through each other",
  Particles = "The dot lattice carries a travelling wave",
  Plain     = "Surface and wash only -- nothing behind the content at all",
}

function Backdrop.styleName()
  local want = L.Cfg and L.Cfg.data and L.Cfg.data.backdrop
  for _, n in ipairs(Backdrop.STYLES) do if n == want then return n end end
  return Backdrop.DEFAULT_STYLE
end

function Backdrop.setStyle(name)
  local found
  for _, n in ipairs(Backdrop.STYLES) do if n == name then found = n end end
  if not found then return false, "unknown background " .. tostring(name) end
  if L.Cfg then L.Cfg.set("backdrop", found) end
  if Backdrop.live and Backdrop.live.applyStyle then
    pcall(function() Backdrop.live:applyStyle(found) end)
  end
  -- The loading screen is on for four seconds; the hub carries the style after.
  local w = L.Hub and L.Hub.window
  if w and w.applyBackground then
    pcall(function() w:applyBackground(found) end)
  end
  return true, found
end

function Backdrop.new(parent, opts)
  opts = opts or {}
  local self = { t = 0, acc = 0, nextStreak = 4, dirty = {} }
  local Z = opts.ZIndex or 0

  local root = mk("Frame", {
    Size = UDim2.fromScale(1, 1),
    BackgroundColor3 = opts.base or Color3.fromRGB(1, 1, 2),
    BorderSizePixel = 0, ZIndex = Z, Name = "Backdrop", Parent = parent,
  })
  self.frame = root

  -- ---- 1. wash ---------------------------------------------------------
  local wash = mk("Frame", {
    Size = UDim2.fromScale(1, 1), BackgroundColor3 = Color3.new(1, 1, 1),
    BorderSizePixel = 0, ZIndex = Z, Name = "Wash", Parent = root,
  })
  local washGrad = mk("UIGradient", {
    Color = ColorSequence.new({
      ColorSequenceKeypoint.new(0, Color3.fromRGB(7, 11, 26)),
      ColorSequenceKeypoint.new(0.52, Color3.fromRGB(1, 1, 3)),
      ColorSequenceKeypoint.new(1, Color3.fromRGB(4, 3, 2)),
    }),
    Rotation = 90, Parent = wash,
  })
  self.washGrad = washGrad

  -- ---- 2. dot grid -----------------------------------------------------
  local vp = L.viewport()
  local step = opts.gridStep or 96
  local cols = math.floor(vp.X / step) + 1
  local rows = math.floor(vp.Y / step) + 1
  local gridHost = mk("Frame", {
    Size = UDim2.fromScale(1, 1), BackgroundTransparency = 1,
    ZIndex = Z + 1, Name = "Grid", Parent = root,
  })
  self.dots, self.cols, self.rows = {}, cols, rows
  local BASE_A = 0.93
  for r = 0, rows - 1 do
    for c = 0, cols - 1 do
      local d = mk("Frame", {
        Position = UDim2.fromOffset(c * step, r * step),
        Size = UDim2.fromOffset(3, 3),
        BackgroundColor3 = Color3.fromRGB(168, 188, 228),
        BackgroundTransparency = BASE_A,
        BorderSizePixel = 0, ZIndex = Z + 1, Parent = gridHost,
      })
      self.dots[#self.dots + 1] = { obj = d, u = c / math.max(cols - 1, 1),
                                    v = r / math.max(rows - 1, 1) }
    end
  end
  self.baseA = BASE_A

  -- ---- 2b. aurora fields -----------------------------------------------
  --
  -- No shader here, so the iridescent-mesh look is a few very large, very soft,
  -- very transparent discs drifting through one another; overlap does the
  -- blending. Lissajous paths, not random walks: two sines at incommensurable
  -- rates never repeat and cannot drift into a corner and sit there.
  local FIELDS = {
    { c = Color3.fromRGB( 92, 128, 255), sx = 0.34, sy = 0.21, rx = 0.019, ry = 0.013, sz = 1.05 },
    { c = Color3.fromRGB(196, 108, 255), sx = 0.28, sy = 0.30, rx = 0.014, ry = 0.023, sz = 0.86 },
    { c = Color3.fromRGB( 88, 226, 220), sx = 0.31, sy = 0.24, rx = 0.024, ry = 0.010, sz = 0.94 },
    { c = Color3.fromRGB(255, 154, 118), sx = 0.22, sy = 0.26, rx = 0.011, ry = 0.017, sz = 0.72 },
    { c = Color3.fromRGB(120, 160, 255), sx = 0.36, sy = 0.18, rx = 0.008, ry = 0.021, sz = 1.20 },
  }
  self.fields = {}
  if A and A.img and A.img.glow then
    local auroraHost = mk("Frame", {
      Size = UDim2.fromScale(1, 1), BackgroundTransparency = 1,
      Visible = false, ZIndex = Z + 1, Name = "Aurora", Parent = root,
    })
    self.auroraHost = auroraHost
    for i, f in ipairs(FIELDS) do
      local d = math.floor(vp.X * f.sz)
      local obj = mk("ImageLabel", {
        AnchorPoint = Vector2.new(0.5, 0.5),
        Position = UDim2.fromScale(0.5, 0.5),
        Size = UDim2.fromOffset(d, d),
        BackgroundTransparency = 1,
        Image = A.img.glow, ImageColor3 = f.c, ImageTransparency = 0.80,
        ZIndex = Z + 1, Name = "Field" .. i, Parent = auroraHost,
      })
      self.fields[i] = { obj = obj, spec = f, phase = i * 1.7 }
    end
  end

  -- ---- 3. terrain ------------------------------------------------------
  -- Thin vertical bars whose heights follow a sum of sines. Three sines is
  -- enough to stop it reading as a repeating wave.
  local function ridge(yScale, height, colour, bars, seed, zoff)
    local host = mk("Frame", {
      AnchorPoint = Vector2.new(0.5, 1),
      Position = UDim2.fromScale(0.5, yScale),
      Size = UDim2.fromScale(1.25, 0),
      BackgroundTransparency = 1,
      ZIndex = Z + 2 + zoff, Name = "Ridge", Parent = root,
    })
    local w = (vp.X * 1.25) / bars
    for i = 0, bars - 1 do
      local x = i / bars * 12
      local hh = height * (0.55
        + 0.28 * math.sin(x * 1.7 + seed)
        + 0.13 * math.sin(x * 3.9 + seed * 2.3)
        + 0.06 * math.sin(x * 8.1 + seed * 4.7))
      mk("Frame", {
        AnchorPoint = Vector2.new(0, 1),
        Position = UDim2.fromOffset(i * w, 0),
        Size = UDim2.fromOffset(math.ceil(w) + 1, math.max(hh, 2)),
        BackgroundColor3 = colour, BorderSizePixel = 0,
        ZIndex = Z + 2 + zoff, Parent = host,
      })
    end
    return host
  end

  local vh = vp.Y
  self.ridges = {
    { obj = ridge(1.00, vh * 0.13, Color3.fromRGB(7, 10, 19), 400, 1.0, 2), rate = 0.0035 },
    { obj = ridge(1.00, vh * 0.09, Color3.fromRGB(4, 6, 11),  400, 3.7, 1), rate = 0.0022 },
    { obj = ridge(1.00, vh * 0.06, Color3.fromRGB(2, 2, 5),   400, 6.2, 0), rate = 0.0012 },
  }

  -- ---- 4. streak -------------------------------------------------------
  local streak = mk("Frame", {
    AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(-0.2, 0.2),
    Size = UDim2.fromOffset(170, 1), BackgroundColor3 = Color3.fromRGB(200, 218, 255),
    BackgroundTransparency = 1, BorderSizePixel = 0, Rotation = 20,
    ZIndex = Z + 4, Name = "Streak", Parent = root,
  })
  mk("UIGradient", {
    Transparency = NumberSequence.new({
      NumberSequenceKeypoint.new(0, 1),
      NumberSequenceKeypoint.new(0.85, 0.3),
      NumberSequenceKeypoint.new(1, 1),
    }), Parent = streak,
  })
  self.streak, self.streakOn, self.streakT, self.streakY = streak, false, 0, 0.2

  -- ---- 5. edges --------------------------------------------------------
  local edges = mk("Frame", {
    Size = UDim2.fromScale(1, 1), BackgroundColor3 = Color3.new(0, 0, 0),
    BorderSizePixel = 0, ZIndex = Z + 5, Name = "Edges", Parent = root,
  })
  mk("UIGradient", {
    Transparency = NumberSequence.new({
      NumberSequenceKeypoint.new(0, 0.02),
      NumberSequenceKeypoint.new(0.30, 1),
      NumberSequenceKeypoint.new(0.70, 1),
      NumberSequenceKeypoint.new(1, 0.02),
    }), Parent = edges,
  })
  self.edges = edges

  -- ---- style ------------------------------------------------------------
  function self:applyStyle(name)
    name = name or Backdrop.DEFAULT_STYLE
    self.style = name
    local aurora    = (name == "Aurora")
    local particles = (name == "Particles")
    local plain     = (name == "Plain")

    if self.auroraHost then self.auroraHost.Visible = aurora end
    for _, rg in ipairs(self.ridges) do
      -- Aurora has no horizon: a ridge in front of a colour field reads as two
      -- backgrounds. Plain has nothing but the wash.
      rg.obj.Visible = not (aurora or plain)
    end
    self.streak.Visible = not plain
    -- the dot field survives into Aurora, dimmed, so the colour does not read
    -- as flat wallpaper
    self.baseA = aurora and 0.965 or 0.93
    self.dotsOn = not plain
    for i = 1, #self.dots do
      local d = self.dots[i]
      d.obj.Visible = self.dotsOn
      d.obj.BackgroundTransparency = self.baseA
      if not particles then d.obj.Size = UDim2.fromOffset(3, 3) end
    end
    for i = #self.dirty, 1, -1 do self.dirty[i] = nil end
    return self
  end

  -- ---- drive -----------------------------------------------------------
  local BAND = 0.14          -- how wide the lit band is, in diagonal units
  self.conn = L.hold(L.RunService.RenderStepped:Connect(function(dt)
    if not L.live() or not root.Parent then return end
    self.t = self.t + dt
    local t = self.t

    washGrad.Rotation = 90 + math.sin(t * 0.10) * 8

    for i = 1, #self.ridges do
      local rg = self.ridges[i]
      if rg.obj.Visible then
        rg.obj.Position = UDim2.fromScale(0.5 + math.sin(t * rg.rate * 6) * 0.012, 1.0)
      end
    end

    if self.style == "Aurora" then
      for i = 1, #self.fields do
        local f = self.fields[i]
        local sp = f.spec
        f.obj.Position = UDim2.fromScale(
          0.5 + math.sin(t * sp.rx * 6.283 + f.phase) * sp.sx,
          0.5 + math.cos(t * sp.ry * 6.283 + f.phase * 1.31) * sp.sy)
        -- breathing opacity, so two fields crossing do not always look the same.
        -- 0.87 read as a barely-tinted black screen; 0.80 with a wider breath is
        -- where the colour shows without competing with the wordmark.
        f.obj.ImageTransparency = 0.80 + math.sin(t * 0.11 + f.phase) * 0.07
      end
    end

    if not self.streak.Visible then
      -- nothing to move, and nothing should accumulate while it is put away
      self.streakOn, self.nextStreak = false, t + 4
    elseif not self.streakOn then
      if t >= self.nextStreak then
        self.streakOn, self.streakT = true, 0
        self.streakY = 0.08 + ((t * 0.37) % 1) * 0.45
        streak.Rotation = 14 + ((t * 0.91) % 1) * 20
      end
    else
      self.streakT = self.streakT + dt
      local p = self.streakT / 0.8
      if p >= 1 then
        self.streakOn = false
        self.nextStreak = t + 6 + ((t * 0.53) % 1) * 8
        streak.BackgroundTransparency = 1
      else
        streak.Position = UDim2.fromScale(-0.15 + p * 1.3, self.streakY)
        streak.BackgroundTransparency = 0.3 + (1 - math.sin(p * math.pi)) * 0.7
      end
    end

    self.acc = self.acc + dt
    if self.acc < TICK then return end
    self.acc = 0

    if not self.dotsOn then return end

    if self.style == "Particles" then
      -- The grid itself is displaced, not lit by a passing band. Two sines at
      -- different angles and rates give an interference pattern that never
      -- repeats. Size moves with brightness: a dot that only changes opacity
      -- reads as a light flicking on rather than a particle rising toward you.
      for i = 1, #self.dots do
        local d = self.dots[i]
        local w = math.sin((d.u * 3.1 + d.v * 1.7) * 3.14159 - t * 1.05)
                + math.sin((d.u * 1.3 - d.v * 2.9) * 3.14159 - t * 0.68)
        local k = math.clamp((w + 2) / 4, 0, 1)
        k = k * k * k                            -- most of the field stays quiet
        d.obj.BackgroundTransparency = self.baseA - (self.baseA - 0.06) * k
        local sz = 3 + math.floor(k * 3.4)
        if d.sz ~= sz then
          d.sz = sz
          d.obj.Size = UDim2.fromOffset(sz, sz)
        end
      end
      return
    end

    -- reset only what was lit last tick, then light only the current band
    local dirty = self.dirty
    for i = 1, #dirty do dirty[i].BackgroundTransparency = self.baseA end
    local n = 0
    local head = ((t * 0.16) % 1.6) - 0.3     -- travels, then a gap before repeating
    for i = 1, #self.dots do
      local d = self.dots[i]
      local pos = (d.u + d.v) * 0.5            -- diagonal coordinate
      local dist = math.abs(pos - head)
      if dist < BAND then
        local k = 1 - (dist / BAND)
        n = n + 1
        dirty[n] = d.obj
        d.obj.BackgroundTransparency = self.baseA - (self.baseA - 0.10) * k * k
      end
    end
    for i = #dirty, n + 1, -1 do dirty[i] = nil end
  end))

  function self:destroy()
    if self.conn then self.conn:Disconnect() end
    if Backdrop.live == self then Backdrop.live = nil end
    pcall(function() root:Destroy() end)
  end

  function self:faders()
    local out = {
      { obj = root, prop = "BackgroundTransparency" },
      { obj = wash, prop = "BackgroundTransparency" },
      { obj = edges, prop = "BackgroundTransparency" },
      { obj = streak, prop = "BackgroundTransparency" },
    }
    for i = 1, #self.dots do
      out[#out + 1] = { obj = self.dots[i].obj, prop = "BackgroundTransparency" }
    end
    -- the colour fields must fade too, or the hub inherits five coloured discs
    for i = 1, #self.fields do
      out[#out + 1] = { obj = self.fields[i].obj, prop = "ImageTransparency" }
    end
    for i = 1, #self.ridges do
      for _, bar in ipairs(self.ridges[i].obj:GetChildren()) do
        out[#out + 1] = { obj = bar, prop = "BackgroundTransparency" }
      end
    end
    return out
  end

  Backdrop.live = self
  self:applyStyle(Backdrop.styleName())

  return self
end

end
do -- ==== lm_12_video.lua ====
-- LUMEN :: VIDEO
-- Plays a folder of PNGs as an image sequence, via getcustomasset.
-- getcustomasset keys on the BASENAME, not the path, so two sequences that both
-- contain f001.png resolve to the same id. Every sequence needs its own prefix.
-- `first` picks where a loop starts, since footage rarely loops across a folder.

local L = getgenv().LUMEN
local mk = L.mk

local Video = {}
L.Video = Video

local getAsset = rawget(getgenv(), "getcustomasset") or rawget(getgenv(), "getsynasset")

-- getcustomasset returns rbxasset://<sessionhash>/<basename>, keyed on the
-- basename and not the path, so every sequence needs a unique prefix.
-- Digit width and extension are parameters because frame naming varies by
-- pipeline (f001.png here, f_0001.jpg elsewhere); defaults are the old values.
function Video.framePath(folder, prefix, i, digits, ext)
  return string.format("%s/%s%0" .. tostring(digits or 3) .. "d%s",
                       folder, prefix, i, ext or ".png")
end

-- `cells` is frames per file (1 when unpacked), so the check counts files.
function Video.available(folder, prefix, count, first, digits, ext, cells)
  if type(getAsset) ~= "function" then return false, "executor has no getcustomasset" end
  first = first or 1
  cells = math.max(1, cells or 1)
  local files = math.max(1, math.ceil(count / cells))
  local firstPath = Video.framePath(folder, prefix, first, digits, ext)
  local ok, present = pcall(isfile, firstPath)
  if not ok or not present then return false, "no frames at " .. firstPath end
  local lastPath = Video.framePath(folder, prefix, first + files - 1, digits, ext)
  local ok2, last = pcall(isfile, lastPath)
  if not ok2 or not last then return false, "sequence is short -- missing " .. lastPath end
  return true
end

-- opts: folder, count, fps, size (px), Position, ZIndex, loop, first
function Video.new(parent, opts)
  opts = opts or {}
  local folder = opts.folder
  local count  = opts.count or 120
  local fps    = opts.fps or 15
  -- Take every Nth frame. The textures are already decoded by the loader, so a
  -- strided instance costs only its ImageLabels.
  local stride = math.max(math.floor(opts.stride or 1), 1)

  local prefix = opts.prefix or "f"
  local first  = math.max(math.floor(opts.first or 1), 1)
  local digits = opts.digits or 3
  local ext    = opts.ext or ".png"
  local okAvail, why = Video.available(folder, prefix, count, first, digits, ext,
    opts.atlas and ((opts.atlas.cols or 1) * (opts.atlas.rows or 1)) or 1)
  if not okAvail then return nil, why end

  local self = { count = count, fps = fps, frame = 1, t = 0, playing = true }

  local holder = mk("Frame", {
    AnchorPoint = Vector2.new(0.5, 0.5),
    Position = opts.Position or UDim2.fromScale(0.5, 0.5),
    -- an explicit Size wins, so a background can fill its parent, not just a square
    Size = opts.Size or UDim2.fromOffset(opts.size or 465, opts.size or 465),
    BackgroundTransparency = 1,
    ZIndex = opts.ZIndex or 3,
    Name = "Video", Parent = parent,
  })
  self.frameObj = holder

  -- Built in batches so building ~700 frames is not one long stall; every caller
  -- is already inside a coroutine. BATCH is 8, not 24: a frame of this work
  -- measures ~2.1 ms, so 24 is a 50 ms chunk while 8 fits one 60 fps frame.
  -- ---- atlases --------------------------------------------------------
  -- Roblox refuses textures over 1024 px on either axis, so long clips are
  -- packed: 30 files of 1024x576, each a 2x2 grid of 512x288 cells, is 120
  -- frames. `atlas = { cols, rows, tile }` describes the packing; `count` stays
  -- the number of FRAMES. One ImageLabel per file, ImageRectOffset picks the cell.
  local atlas = opts.atlas
  local cells = 1
  if atlas then
    cells = math.max(1, (atlas.cols or 1) * (atlas.rows or 1))
  end
  local fileCount = math.max(1, math.ceil(count / cells))

  local BATCH = 8
  local labels = {}
  local made = 0
  for i = first, first + fileCount - 1, stride do
    local ok, id = pcall(getAsset, Video.framePath(folder, prefix, i, digits, ext))
    if ok and id then
      local props = {
        Size = UDim2.fromScale(1, 1),
        BackgroundTransparency = 1,
        Image = id,
        ScaleType = opts.scaleType or Enum.ScaleType.Stretch,
        ImageTransparency = 1,
        ZIndex = opts.ZIndex or 3,
        Name = prefix .. i,
        Parent = holder,
      }
      if atlas and atlas.tile then props.ImageRectSize = atlas.tile end
      labels[#labels + 1] = mk("ImageLabel", props)
    end
    made = made + 1
    if made % BATCH == 0 and opts.yield ~= false then
      L.RunService.Heartbeat:Wait()
    end
  end
  self.labels = labels
  self.atlas, self.cells = atlas, cells
  count = #labels * cells
  self.count = count

  -- Which label holds frame n, and which cell within it.
  local function cellOf(n)
    if not atlas then return labels[n], nil end
    local fi = math.floor((n - 1) / cells) + 1
    return labels[fi], (n - 1) % cells
  end

  -- Reveal frame n and hide whatever was showing. Shared by the manual seek and
  -- the auto-advance.
  local function present(n, prevN)
    local lbl, ci = cellOf(n)
    local prevLbl = prevN and cellOf(prevN) or nil
    if prevLbl and prevLbl ~= lbl then prevLbl.ImageTransparency = 1 end
    if lbl then
      if ci and atlas.tile then
        lbl.ImageRectOffset = Vector2.new(
          (ci % (atlas.cols or 1)) * atlas.tile.X,
          math.floor(ci / (atlas.cols or 1)) * atlas.tile.Y)
      end
      lbl.ImageTransparency = self.rest or 0
    end
  end
  self._present = present
  fps = fps / stride
  if #labels == 0 then
    pcall(function() holder:Destroy() end)
    return nil, "no frames decoded"
  end
  self.rest = opts.rest or 0
  self.shown = 1
  present(1, nil)

  -- Warm the texture cache before anything is on screen. PreloadAsync blocks, so
  -- it runs on its own thread rather than stalling the loader.
  task.spawn(function()
    L.try("video.preload", function()
      game:GetService("ContentProvider"):PreloadAsync(labels)
    end)
    self.warm = true
  end)

  -- Manual mode: the caller owns the playhead and the auto-advance stays out.
  function self:setFrame(n)
    n = ((math.floor(n) - 1) % count) + 1
    local prev = self.shown
    if prev == n then return end
    present(n, prev)
    self.shown, self.frame = n, n
  end

  local step = 1 / fps
  self.conn = L.hold(L.RunService.RenderStepped:Connect(function(dt)
    if opts.manual then return end
    if not L.live() or not holder.Parent or not self.playing then return end
    self.t = self.t + dt
    if self.t < step then return end
    -- Advance by however many frame periods elapsed, so a hitch skips ahead.
    local advance = math.floor(self.t / step)
    self.t = self.t - advance * step
    local nxt = self.frame + advance
    if opts.loop == false and nxt > count then
      nxt = count
      self.playing = false
    else
      nxt = ((nxt - 1) % count) + 1
    end
    self.frame = nxt
    local prev = self.shown
    if prev ~= nxt then
      present(nxt, prev)
      self.shown = nxt
    end
  end))

  function self:setSpeed(mult) step = 1 / (fps * math.max(mult, 0.05)) end
  function self:pause() self.playing = false end
  function self:play() self.playing = true end
  function self:destroy()
    if self.conn then self.conn:Disconnect() end
    pcall(function() holder:Destroy() end)
  end

  return self
end

end
do -- ==== lm_10_orb.lua ====
-- LUMEN :: ORB
-- Drawn fallback mark for when the rendered Saturn frames are unavailable.

local L = getgenv().LUMEN
local T, M, A = L.T, L.Motion, L.A
local mk = L.mk

local Orb = {}
L.Orb = Orb

local BLUE   = Color3.fromRGB(46, 96, 255)
local BLUE_L = Color3.fromRGB(120, 170, 255)
local GOLD   = Color3.fromRGB(255, 176, 62)
local WHITE  = Color3.fromRGB(226, 238, 255)

local function ball(parent, size, colour, transparency, offset)
  local p = Instance.new("Part")
  p.Shape = Enum.PartType.Ball
  p.Size = Vector3.new(size, size, size)
  p.Color = colour
  p.Material = Enum.Material.Neon
  p.Transparency = transparency
  p.Anchored, p.CanCollide, p.CanQuery, p.CanTouch = true, false, false, false
  p.CastShadow = false
  p.CFrame = CFrame.new(offset or Vector3.new())
  p.Parent = parent
  return p
end

-- An ellipse drawn as a stroked, rounded frame; its height animates edge-on.
local function arc(parent, w, h, rot, colour, thickness, alpha)
  local f = mk("Frame", {
    AnchorPoint = Vector2.new(0.5, 0.5),
    Position = UDim2.fromScale(0.5, 0.5),
    Size = UDim2.fromScale(w, h),
    BackgroundTransparency = 1,
    Rotation = rot,
    ZIndex = 6,
    Name = "Arc", Parent = parent,
  })
  L.corner(999, f)
  local s = L.stroke(colour, thickness or 1.4, alpha or 0.25, f)
  return f, s
end

-- size: pixel square. Returns a controller.
function Orb.new(parent, size, opts)
  opts = opts or {}
  local self = { }

  local holder = mk("Frame", {
    AnchorPoint = Vector2.new(0.5, 0.5),
    Position = opts.Position or UDim2.fromScale(0.5, 0.5),
    Size = UDim2.fromOffset(size, size),
    BackgroundTransparency = 1,
    ZIndex = opts.ZIndex or 3,
    Name = "Orb", Parent = parent,
  })
  self.frame = holder

  -- ---- 3D body -------------------------------------------------------
  local vp = mk("ViewportFrame", {
    Size = UDim2.fromScale(1, 1),
    BackgroundTransparency = 1,
    -- A viewport has its own lighting rig; Neon ignores it, ambient lifts the rim.
    Ambient = Color3.fromRGB(40, 60, 120),
    LightColor = Color3.fromRGB(190, 210, 255),
    LightDirection = Vector3.new(-0.4, -0.8, -0.5),
    ZIndex = (opts.ZIndex or 3) + 1,
    Name = "Body", Parent = holder,
  })
  self.vp = vp

  local world = Instance.new("WorldModel")
  world.Parent = vp

  local model = Instance.new("Model")
  model.Name = "OrbModel"
  model.Parent = world

  -- A glass shell, not a glowing ball: bright rim, see-through middle.
  ball(model, 5.60, BLUE,   0.93)
  ball(model, 5.05, BLUE,   0.90)
  ball(model, 4.30, BLUE_L, 0.92)

  -- Colour pooled low inside the shell, plus one small specular opposite it.
  local goldA = ball(model, 3.10, GOLD,  0.76, Vector3.new(-0.5, -1.8, 0.3))
  local goldB = ball(model, 1.70, GOLD,  0.68, Vector3.new(1.3, -1.4, -0.7))
  local pool  = ball(model, 2.40, BLUE_L, 0.80, Vector3.new(0.4, -1.2, 1.0))
  local spec  = ball(model, 0.70, WHITE, 0.30, Vector3.new(-1.2, 1.7, 1.3))
  self.gold = { goldA, goldB, pool, spec }

  local cam = Instance.new("Camera")
  cam.FieldOfView = 42
  cam.CFrame = CFrame.new(Vector3.new(0, 0, 13), Vector3.new())
  cam.Parent = vp
  vp.CurrentCamera = cam

  -- ---- the glass edge -------------------------------------------------
  -- The rim a viewport cannot produce, plus a thinner brighter one inside it.
  local rim = mk("Frame", {
    AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, 0.5),
    Size = UDim2.fromScale(0.80, 0.80), BackgroundTransparency = 1,
    ZIndex = (opts.ZIndex or 3) + 5, Name = "Rim", Parent = holder,
  })
  L.corner(999, rim)
  -- Stroke widths are a fraction of the orb, not fixed pixels: tuned at 250 px
  -- and left constant they become invisible hairlines by 470 px.
  local K = size / 250
  L.stroke(BLUE_L, 2.6 * K, 0.22, rim)

  local rimIn = mk("Frame", {
    AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, 0.5),
    Size = UDim2.fromScale(0.755, 0.755), BackgroundTransparency = 1,
    ZIndex = (opts.ZIndex or 3) + 6, Name = "RimInner", Parent = holder,
  })
  L.corner(999, rimIn)
  local rimStroke = L.stroke(WHITE, 1.1 * K, 0.55, rimIn)
  -- Brightest top-left, fading round the bottom, so the light source reads fixed.
  mk("UIGradient", {
    Transparency = NumberSequence.new({
      NumberSequenceKeypoint.new(0, 0.15),
      NumberSequenceKeypoint.new(0.45, 0.75),
      NumberSequenceKeypoint.new(1, 1),
    }),
    Rotation = 118, Parent = rimStroke,
  })
  self.rim, self.rimIn = rim, rimIn

  -- ---- 2D arcs -------------------------------------------------------
  self.arcs = {}
  local defs = {
    { w = 0.98, rot = -14, colour = BLUE_L, th = 1.6, a = 0.20, phase = 0.00, speed = 0.55 },
    { w = 0.86, rot =  22, colour = WHITE,  th = 1.2, a = 0.42, phase = 2.10, speed = 0.41 },
    { w = 0.92, rot =  62, colour = GOLD,   th = 1.1, a = 0.55, phase = 4.05, speed = 0.33 },
  }
  for _, d in ipairs(defs) do
    local f, s = arc(holder, d.w, d.w, d.rot, d.colour, d.th * (size / 250), d.a)
    self.arcs[#self.arcs + 1] = { frame = f, stroke = s, def = d }
  end

  -- ---- animation -----------------------------------------------------
  self.t = 0
  self.speed = opts.speed or 1
  self.conn = L.hold(L.RunService.RenderStepped:Connect(function(dt)
    if not L.live() or not holder.Parent then return end
    self.t = self.t + dt * self.speed

    -- Tilted axis, so the gold pool swings through the silhouette.
    model:PivotTo(CFrame.Angles(math.rad(14), self.t * 0.55, math.rad(6)))

    for i, a in ipairs(self.arcs) do
      local d = a.def
      -- |cos| of the phase is the ring's projected height, floored off zero.
      local k = math.abs(math.cos(self.t * d.speed + d.phase))
      a.frame.Size = UDim2.fromScale(d.w, d.w * (0.06 + 0.94 * k))
      a.frame.Rotation = d.rot + math.sin(self.t * d.speed * 0.5 + d.phase) * 9
      -- fade as it goes edge-on, so the far side does not read as in front
      a.stroke.Transparency = d.a + (1 - d.a) * (1 - k) * 0.55
      local _ = i
    end
  end))

  function self:setSpeed(v) self.speed = v end
  function self:destroy()
    if self.conn then self.conn:Disconnect() end
    pcall(function() holder:Destroy() end)
  end

  return self
end

end
do -- ==== lm_11_spinner.lua ====
-- LUMEN :: SPINNER
-- The game carousel: a fan of cards on an arc, positioned by distance from the
-- front, so the one in focus is largest and brightest.

local L = getgenv().LUMEN
local T, M, A = L.T, L.Motion, L.A
local mk = L.mk

local Spinner = {}
L.Spinner = Spinner

local CARD_W, CARD_H, CARD_D = 3.3, 3.3, 0.08
local RADIUS = 4.9
-- 0.16 rad/s was ~6.5 s per card to the front, too slow to read as motion.
-- 0.42 brings a card round every ~2.5 s.
local IDLE = 0.42

local getAsset = rawget(getgenv(), "getcustomasset") or rawget(getgenv(), "getsynasset")

local function iconId(key)
  if type(getAsset) ~= "function" or not key then return nil end
  local path = "lumen_fx/games/" .. key .. ".png"
  local ok, present = pcall(isfile, path)
  if not ok or not present then return nil end
  local gok, id = pcall(getAsset, path)
  return gok and id or nil
end

function Spinner.new(parent, opts)
  opts = opts or {}
  local items = opts.items or {}
  local n = math.max(#items, 1)
  local self = { items = items, index = 1, drift = 0,
                 idleScale = 1, slowUntil = 0 }

  local holder = mk("Frame", {
    Size = opts.Size or UDim2.new(1, 0, 0, 320),
    BackgroundTransparency = 1, Name = "Spinner", Parent = parent,
  })
  self.frame = holder

  local vp = mk("ViewportFrame", {
    Size = UDim2.new(1, 0, 1, -46), BackgroundTransparency = 1,
    Ambient = Color3.fromRGB(150, 162, 190),
    LightColor = Color3.fromRGB(255, 255, 255),
    LightDirection = Vector3.new(-0.3, -0.55, -0.8),
    ZIndex = 2, Name = "Stage", Parent = holder,
  })
  self.vp = vp

  local world = Instance.new("WorldModel")
  world.Parent = vp
  local model = Instance.new("Model")
  model.Parent = world

  local cam = Instance.new("Camera")
  cam.FieldOfView = 42
  cam.CFrame = CFrame.new(Vector3.new(0, 0.5, 14.5), Vector3.new(0, 0, 0))
  cam.Parent = vp
  vp.CurrentCamera = cam

  local step = (2 * math.pi) / n
  self.step = step
  self.cards = {}

  for i, it in ipairs(items) do
    -- chrome backing plate, slightly larger, so the card reads as a printed panel
    local back = Instance.new("Part")
    back.Size = Vector3.new(CARD_W + 0.16, CARD_H + 0.16, CARD_D)
    back.Color = Color3.fromRGB(176, 196, 232)
    back.Material = Enum.Material.SmoothPlastic
    back.Anchored, back.CanCollide, back.CanQuery, back.CanTouch = true, false, false, false
    back.CastShadow = false
    back.Parent = model

    local face = Instance.new("Part")
    face.Size = Vector3.new(CARD_W, CARD_H, CARD_D + 0.02)
    face.Color = Color3.fromRGB(16, 18, 26)
    face.Material = Enum.Material.SmoothPlastic
    face.Anchored, face.CanCollide, face.CanQuery, face.CanTouch = true, false, false, false
    face.CastShadow = false
    face.Parent = model

    local id = iconId(it.key)
    if id then
      for _, f in ipairs({ Enum.NormalId.Front, Enum.NormalId.Back }) do
        local d = Instance.new("Decal")
        d.Texture = id
        d.Face = f
        d.Parent = face
      end
    end

    self.cards[i] = { back = back, face = face, has = id ~= nil }
  end

  -- ---- labels ---------------------------------------------------------
  self.label = A.text({
    Text = items[1] and items[1].name or "",
    font = T.font.strong, size = T.size.head, colour = T.c.text,
    align = Enum.TextXAlignment.Center,
    AnchorPoint = Vector2.new(0.5, 1),
    Position = UDim2.new(0.5, 0, 1, -18), Size = UDim2.new(1, 0, 0, 20),
    ZIndex = 4, Parent = holder,
  })
  -- subFor lets the caller replace the "3 / 10" counter with what picking the
  -- front card actually gets you.
  local function subText(item, i)
    if opts.subFor then
      local ok, s = pcall(opts.subFor, item, i, #items)
      if ok and type(s) == "string" then return s end
    end
    return string.format("%d / %d", i, #items)
  end
  self.subText = subText

  self.sub = A.text({
    Text = subText(items[1], 1),
    font = T.font.mono, size = T.size.tiny, colour = T.c.textMute,
    align = Enum.TextXAlignment.Center,
    AnchorPoint = Vector2.new(0.5, 1),
    Position = UDim2.new(0.5, 0, 1, -2), Size = UDim2.new(1, 0, 0, 12),
    ZIndex = 4, Parent = holder,
  })

  -- ---- motion ---------------------------------------------------------
  self.spring = L.Spring.new(0.70, 0.26, 0)

  self.conn = L.hold(L.RunService.RenderStepped:Connect(function(dt)
    if not L.live() or not holder.Parent then return end
    -- 2.5 s at the front is not long enough to read a label and click Join, so
    -- touching an arrow drops the rate to a crawl for five seconds, then eases
    -- back. It never fully stops.
    local want = (os.clock() < self.slowUntil) and 0.04 or 1
    self.idleScale = self.idleScale + (want - self.idleScale) * math.min(dt * 2.4, 1)
    self.drift = self.drift + dt * IDLE * self.idleScale
    local base = self.drift + self.spring:step(dt)

    local bestI, bestFacing = 1, -2
    for i, c in ipairs(self.cards) do
      local theta = base + (i - 1) * step
      local x = math.sin(theta) * RADIUS
      local z = math.cos(theta) * RADIUS
      local bob = math.sin(theta * 2 + self.drift * 0.7) * 0.14
      local cf = CFrame.new(x, bob, z)
                 * CFrame.Angles(0, theta, 0)
                 * CFrame.Angles(math.rad(-3), 0, 0)
      c.back.CFrame = cf
      c.face.CFrame = cf

      local facing = math.cos(theta)              -- 1 front, -1 back
      if facing > bestFacing then bestFacing, bestI = facing, i end
      -- fade the far side so the ring reads as having a front
      local a = (facing + 1) * 0.5
      local t = 0.04 + (1 - a) * 0.66
      c.face.Transparency = t
      c.back.Transparency = math.min(t + 0.10, 1)
      for _, d in ipairs(c.face:GetChildren()) do
        if d:IsA("Decal") then d.Transparency = t end
      end
    end

    -- the label follows whatever is actually at the front
    if bestI ~= self.index then
      self.index = bestI
      self.label.Text = self.items[bestI].name or ""
      self.sub.Text = subText(self.items[bestI], bestI)
      if opts.onFront then L.try("spinner.front", opts.onFront, self.items[bestI], bestI) end
    end
  end))

  -- Arrows push the spring by exactly one card. Repeated presses accumulate
  -- because a retarget keeps the velocity already in flight.
  function self:hold(seconds)
    self.slowUntil = os.clock() + (seconds or 5)
  end

  function self:nudge(dir)
    self:hold(5)
    self.spring:to(self.spring.target - dir * step)
  end
  function self:next() self:nudge(1) end
  function self:prev() self:nudge(-1) end

  function self:select(i)
    local total = #self.items
    if total == 0 then return end
    self:hold(5)
    i = ((i - 1) % total) + 1
    -- solve for the offset that puts card i at the front, given current drift
    local want = -((i - 1) * step) - self.drift
    local cur = self.spring.target
    while want - cur > math.pi do want = want - 2 * math.pi end
    while cur - want > math.pi do want = want + 2 * math.pi end
    self.spring:to(want)
    if opts.callback then L.try("spinner.cb", opts.callback, self.items[i], i) end
  end

  function self:destroy()
    if self.conn then self.conn:Disconnect() end
    pcall(function() holder:Destroy() end)
  end

  -- ---- arrows ---------------------------------------------------------
  local function arrow(xScale, dir, fn)
    local b = mk("Frame", {
      AnchorPoint = Vector2.new(0.5, 0.5),
      Position = UDim2.new(xScale, 0, 0.44, 0),
      Size = UDim2.fromOffset(32, 32),
      BackgroundColor3 = T.c.raised, BackgroundTransparency = 0.12,
      BorderSizePixel = 0, ZIndex = 5, Parent = holder,
    })
    L.corner(999, b)
    L.stroke(T.c.lineStrong, 1, 0.35, b)
    local g = A.Icon.chevron(b, 14, T.c.textDim, dir)
    g.AnchorPoint = Vector2.new(0.5, 0.5)
    g.Position = UDim2.fromScale(0.5, 0.5)
    g.ZIndex = 6
    A.interactive(b, { radius = 999, onClick = fn })
    return b
  end
  arrow(0.05, "left",  function() self:prev() end)
  arrow(0.95, "right", function() self:next() end)

  return self
end

end
do -- ==== lm_27_infinity.lua ====
-- LUMEN :: BOOT MARKS
--
-- Two shapes, one renderer. `Inf.new` is the morphing infinity; `Inf.newRing`
-- is the arc that replaced it on the loading screen. They share `update`'s
-- chord-laying step and the same small interface, so the loader swaps between
-- them on one line.
--
-- ---------------------------------------------------------------- infinity
-- A port of loading-ui.com's morphing-infinity, which is an SVG whose single
-- stroked path animates through circle -> infinity -> circle -> infinity over
-- five seconds.
--
-- Roblox draws no vector paths, so the curve is walked and rebuilt every frame
-- out of 64 rounded segments. That sounds worse than it is: at this size each
-- segment is about three pixels long under a six pixel stroke, so the round
-- caps overlap into one continuous line with no visible facets.
--
-- WHY THE TWO CIRCLES ARE NOT THE SAME CIRCLE. circleA starts at the top and
-- runs clockwise; circleB starts at the bottom and runs anticlockwise. They
-- draw an identical ring. Interpolating between them THROUGH the lemniscate is
-- what makes the loop read as one ribbon turning inside out, because no two
-- consecutive transitions are the same motion -- swap circleB for circleA and
-- the whole thing collapses into a circle that flexes and un-flexes on the
-- spot. That asymmetry is the entire idea and it costs nothing.
--
-- All three paths share a structure -- a start point and four cubic segments --
-- so morphing is interpolating 26 numbers and re-walking the curve, which is
-- exactly what the web version's path interpolation does underneath.

local L = getgenv().LUMEN
local T = L.T
local mk = L.mk

local Inf = {}
L.Infinity = Inf

-- flat, in the source's own 24x24 box: x0 y0 then four (c1 c2 end) triples
local circleA = {
  12, 8,
  14.21, 8,     16, 9.79,   16, 12,
  16, 14.21,    14.21, 16,  12, 16,
  9.79, 16,     8, 14.21,   8, 12,
  8, 9.79,      9.79, 8,    12, 8,
}
local infinity = {
  12, 12,
  14, 8.5,      19, 8.5,    19, 12,
  19, 15.5,     14, 15.5,   12, 12,
  10, 8.5,      5, 8.5,     5, 12,
  5, 15.5,      10, 15.5,   12, 12,
}
local circleB = {
  12, 16,
  14.21, 16,    16, 14.21,  16, 12,
  16, 9.79,     14.21, 8,   12, 8,
  9.79, 8,      8, 9.79,    8, 12,
  8, 14.21,     9.79, 16,   12, 16,
}

local KEYS  = { circleA, infinity, circleB, infinity, circleA }
local TIMES = { 0, 0.25, 0.50, 0.75, 1.00 }
local CYCLE = 5.0            -- seconds, from the source
local SUB   = 16             -- samples per cubic; 4 cubics -> 64 segments
local N     = SUB * 4

-- The source eases each keyframe-to-keyframe leg with motion's "easeInOut",
-- which is cubic-bezier(0.42, 0, 0.58, 1). Its Y curve happens to be exactly
-- smoothstep, but its X curve is not linear, so feeding time straight into
-- smoothstep is wrong by up to 0.03 -- visible here as the shape lingering at
-- the circle and rushing the crossing. Solve X for the curve parameter first,
-- then read Y off it.
local function easeInOut(t)
  if t <= 0 then return 0 end
  if t >= 1 then return 1 end
  local s = t
  for _ = 1, 4 do
    local x = ((0.52 * s - 0.78) * s + 1.26) * s - t
    local dx = (1.56 * s - 1.56) * s + 1.26
    if dx <= 1e-6 then break end
    s = s - x / dx
  end
  return (3 - 2 * s) * s * s
end

function Inf.new(parent, size, opts)
  opts = opts or {}
  local self = setmetatable({}, { __index = Inf })

  local px = size / 24                      -- the source box is 24 units wide
  local thick = math.max(2, math.floor(1.5 * px + 0.5))   -- strokeWidth 1.5
  self.size, self.px, self.thick = size, px, thick
  self.t, self.settle = 0, 0

  -- One CanvasGroup so the whole curve fades on a single property. There is no
  -- text inside it, so nothing pays the resampling cost that keeps the loading
  -- screen's wordmark out of one.
  local holder = mk("CanvasGroup", {
    AnchorPoint = opts.AnchorPoint or Vector2.new(0.5, 0.5),
    Position = opts.Position or UDim2.fromScale(0.5, 0.5),
    Size = UDim2.fromOffset(size, size),
    BackgroundTransparency = 1,
    GroupTransparency = opts.transparency or 0,
    ZIndex = opts.ZIndex or 2,
    Name = "Infinity", Parent = parent,
  })
  self.holder = holder

  local colour = opts.colour or T.c.accent
  self.segs = table.create(N)
  for i = 1, N do
    local s = mk("Frame", {
      AnchorPoint = Vector2.new(0.5, 0.5),
      Size = UDim2.fromOffset(thick, thick),
      BackgroundColor3 = colour,
      BorderSizePixel = 0,
      Name = "S" .. i, Parent = holder,
    })
    L.corner(999, s)                        -- round caps, and so round joins
    self.segs[i] = s
  end

  -- scratch, reused every frame: this runs 60 times a second and allocating
  -- three tables per frame is how a loading screen ends up stuttering
  self._n = table.create(26)
  self._x = table.create(N)
  self._y = table.create(N)

  self:update(0)

  if opts.drive ~= false then
    self.conn = L.hold(L.RunService.RenderStepped:Connect(function(dt)
      if not (L.live() and holder.Parent) then return end
      self:update(self.t + dt)
    end))
  end
  return self
end


-- ---------------------------------------------------------------- ring
--
-- WHY THE INFINITY WAS REPLACED, having been the thing that replaced a bar.
--
-- Its whole argument was that a bar tells you a number the percentage already
-- says, and says it worse. That is true. But the infinity then says NOTHING --
-- it is equally busy at 4% and at 96%, so the screen has one element that
-- carries information and one that is purely decorative, and they sit in
-- separate places doing separate jobs.
--
-- This does both at once, and answers the bar objection on its own terms:
--
--   the TRACK is the whole ring, always there, so there is a shape to read
--   the ARC lights from twelve o'clock as progress arrives  -- the number
--   the COMET keeps orbiting regardless                     -- still alive
--
-- The bar's real failure is that 40% and 45% look identical because a bar has
-- no motion of its own to compare against. The comet supplies exactly that: it
-- laps a stationary arc, so the arc's edge is always being pointed at. And
-- unlike the infinity, at 96% it visibly nearly-closed.
--
-- The percentage goes in the middle of it, which is the other half of the
-- reason: three scattered elements (mark, status, percent) become one object
-- with a caption.
local TAIL = 15                 -- comet segments; ~85 degrees at N = 64
local SPIN = 1.45               -- seconds per lap

function Inf.newRing(parent, size, opts)
  opts = opts or {}
  local self = setmetatable({}, { __index = Inf })
  self.isRing = true
  self.size   = size
  self.thick  = opts.thick or math.max(3, math.floor(size * 0.055))
  self.t, self._last = 0, nil
  self.progress, self.progressTo = 0, 0
  self.settle, self.settleTo = 0, 0

  local holder = mk("CanvasGroup", {
    AnchorPoint = opts.AnchorPoint or Vector2.new(0.5, 0.5),
    Position = opts.Position or UDim2.fromScale(0.5, 0.5),
    Size = UDim2.fromOffset(size, size),
    BackgroundTransparency = 1,
    GroupTransparency = opts.transparency or 0,
    ZIndex = opts.ZIndex or 2,
    Name = "Ring", Parent = parent,
  })
  self.holder = holder

  self.colour = opts.colour or T.c.accent
  self.segs = table.create(N)
  for i = 1, N do
    local seg = mk("Frame", {
      AnchorPoint = Vector2.new(0.5, 0.5),
      Size = UDim2.fromOffset(self.thick, self.thick),
      BackgroundColor3 = self.colour,
      BackgroundTransparency = 1,
      BorderSizePixel = 0,
      Name = "S" .. i, Parent = holder,
    })
    L.corner(999, seg)
    self.segs[i] = seg
  end

  -- LAID OUT ONCE. The infinity rebuilds its geometry every frame because its
  -- geometry actually changes; a circle's does not. Only transparency and
  -- colour move here, which is the difference between 64 CFrame-equivalent
  -- writes per frame and 64 float writes.
  local r = size * 0.5 - self.thick * 0.5 - 1
  local half = size / 2
  for i = 1, N do
    local a0 = ((i - 1) / N) * math.pi * 2 - math.pi / 2
    local a1 = (i / N) * math.pi * 2 - math.pi / 2
    local x0, y0 = half + math.cos(a0) * r, half + math.sin(a0) * r
    local x1, y1 = half + math.cos(a1) * r, half + math.sin(a1) * r
    local dx, dy = x1 - x0, y1 - y0
    local len = math.sqrt(dx * dx + dy * dy)
    local seg = self.segs[i]
    seg.Position = UDim2.fromOffset(x0 + dx * 0.5, y0 + dy * 0.5)
    seg.Size = UDim2.fromOffset(len + self.thick, self.thick)
    seg.Rotation = math.deg(math.atan2(dy, dx))
  end

  self:update(0)
  if opts.drive ~= false then
    self.conn = L.hold(L.RunService.RenderStepped:Connect(function(dt)
      if not (L.live() and holder.Parent) then return end
      self:update(self.t + dt)
    end))
  end
  return self
end

-- 0..1. Eased toward rather than snapped, for the same reason the percentage is
-- sprung: a stage boundary is a step in the DATA, never in the picture.
function Inf:setProgress(a)
  self.progressTo = math.clamp(a or 0, 0, 1)
  return self
end

local TRACK_ALPHA = 0.88
local ARC_ALPHA   = 0.30

function Inf:updateRing(t)
  local dt = math.clamp(t - (self._last or t), 0, 0.25)
  self._last, self.t = t, t

  self.progress = self.progress
    + (self.progressTo - self.progress) * (1 - math.exp(-dt / 0.22))
  if self.settleTo ~= self.settle then
    self.settle = self.settle + (self.settleTo - self.settle) * (1 - math.exp(-dt / 0.10))
    if math.abs(self.settleTo - self.settle) < 0.002 then self.settle = self.settleTo end
  end

  -- resolving fills the ring and puts the comet away: the lap is a promise that
  -- something is still happening, and once it is not, the promise has to stop
  local p = self.progress + (1 - self.progress) * self.settle
  local litTo = p * N
  local head = (t / SPIN) % 1 * N
  local cometFade = 1 - self.settle

  for i = 1, N do
    -- partial credit on the leading segment, so the arc grows smoothly instead
    -- of in 1/64 steps -- at this size one step is a visible tick
    local fill = math.clamp(litTo - (i - 1), 0, 1)
    local alpha = TRACK_ALPHA + (ARC_ALPHA - TRACK_ALPHA) * fill

    if cometFade > 0.01 then
      -- distance BEHIND the head, wrapped: the comet is a tail, not a dot
      local d = (head - (i - 1)) % N
      if d < TAIL then
        local w = (1 - d / TAIL)
        w = w * w * cometFade
        alpha = math.min(alpha, TRACK_ALPHA + (0.02 - TRACK_ALPHA) * w)
      end
    end
    self.segs[i].BackgroundTransparency = alpha
  end
  return self
end

-- absolute time in, so a caller that already has a clock can hand us theirs and
-- the two can never drift apart
function Inf:update(t)
  if self.isRing then return self:updateRing(t) end
  local dt = math.clamp(t - (self._last or t), 0, 0.25)
  self._last, self.t = t, t
  local n = self._n

  -- exponential approach rather than a Motion track: Motion's tracks are built
  -- for Instances, and this is a plain table. tau 0.09 puts it at rest inside a
  -- quarter second, under the loader's own handover.
  if self.settleTo and self.settleTo ~= self.settle then
    self.settle = self.settle + (self.settleTo - self.settle) * (1 - math.exp(-dt / 0.09))
    if math.abs(self.settleTo - self.settle) < 0.001 then self.settle = self.settleTo end
  end

  local phase = (t / CYCLE) % 1
  local k = 1
  while k < #TIMES - 1 and phase >= TIMES[k + 1] do k = k + 1 end
  local span = TIMES[k + 1] - TIMES[k]
  local e = easeInOut(span > 0 and (phase - TIMES[k]) / span or 0)
  local a, b = KEYS[k], KEYS[k + 1]
  for i = 1, 26 do n[i] = a[i] + (b[i] - a[i]) * e end

  -- settling blends whatever we are toward the resting circle, so finishing
  -- does not wait for the five second cycle to come back around
  local s = self.settle
  if s > 0 then
    for i = 1, 26 do n[i] = n[i] + (circleA[i] - n[i]) * s end
  end

  -- walk the four cubics
  local px, half = self.px, self.size / 2
  local X, Y = self._x, self._y
  local p = 0
  for seg = 0, 3 do
    local o = seg * 6
    local x0, y0 = n[o + 1], n[o + 2]
    local x1, y1 = n[o + 3], n[o + 4]
    local x2, y2 = n[o + 5], n[o + 6]
    local x3, y3 = n[o + 7], n[o + 8]
    for j = 0, SUB - 1 do
      local u = j / SUB
      local m = 1 - u
      local w0 = m * m * m
      local w1 = 3 * m * m * u
      local w2 = 3 * m * u * u
      local w3 = u * u * u
      p = p + 1
      X[p] = (w0 * x0 + w1 * x1 + w2 * x2 + w3 * x3) * px
      Y[p] = (w0 * y0 + w1 * y1 + w2 * y2 + w3 * y3) * px
    end
  end

  -- lay a rounded bar along each chord. Length carries the full stroke width so
  -- consecutive caps overlap; without it the curve beads at every joint.
  local thick = self.thick
  local segs = self.segs
  for i = 1, N do
    local j = (i % N) + 1
    local ax, ay = X[i], Y[i]
    local dx, dy = X[j] - ax, Y[j] - ay
    local len = math.sqrt(dx * dx + dy * dy)
    local f = segs[i]
    if len < 0.05 then
      -- the lemniscate's own crossing point, where two samples coincide: a zero
      -- length chord has no direction, and atan2(0,0) would spin it randomly
      f.Visible = false
    else
      f.Visible = true
      f.Position = UDim2.fromOffset(ax + dx * 0.5, ay + dy * 0.5)
      f.Size = UDim2.fromOffset(len + thick, thick)
      f.Rotation = math.deg(math.atan2(dy, dx))
    end
  end
  return self
end

-- Bring it to rest on the circle NOW rather than letting it run out its cycle.
-- Loading finishing is the event; the animation has no business adding another
-- two and a half seconds to it.
function Inf:resolve()
  self.settleTo = 1
  return self
end

function Inf:setColour(c)
  self.colour = c
  for i = 1, N do self.segs[i].BackgroundColor3 = c end
  return self
end

function Inf:destroy()
  if self.conn then pcall(function() self.conn:Disconnect() end) end
  pcall(function() self.holder:Destroy() end)
end

end
do -- ==== lm_08_loader.lua ====
-- LUMEN :: LOADER
-- The loading screen.
--
-- No CanvasGroup around the text: one rasterises its subtree to an offscreen
-- buffer, and text drawn through that is resampled and goes soft. Fading walks
-- a list of (object, property, resting value) instead.
--
-- Sizes derive from viewport height, so it renders at its final resolution
-- rather than being authored small and stretched.

local L = getgenv().LUMEN
local T, M, A = L.T, L.Motion, L.A
local mk = L.mk

local Loader = {}
L.Loader = Loader

-- The folder holds 301 frames but the orbit only repeats every 183, starting at
-- 68. Playing the whole folder snapped once per revolution; this window loops.
local ORB_FIRST, ORB_FRAMES, ORB_FPS = 68, 183, 30

-- ---------------------------------------------------------------- skins
--
-- There is more than one loading screen now, and which one runs is a saved
-- preference rather than whichever was compiled in last.
--
-- EVERY SKIN IMPLEMENTS THE SAME FIVE METHODS -- stage, say, flash, finish,
-- fade -- so Hub.launch never learns which one it is driving. That is the whole
-- reason a second screen is cheap to add: the boot sequence is a list of
-- progress calls, not a description of a picture.

Loader.SKINS = { "Aurora", "Made in Heaven" }
Loader.DEFAULT_SKIN = "Aurora"

-- Made in Heaven ships as loose files rather than baked assets, so it can be
-- absent on a fresh install. Asked, never assumed: a picker that offers a
-- screen which then falls back to a different one is worse than a picker that
-- greys the option out.
Loader.MIH = {
  dir = "leakvid", frames = "max", prefix = "f_", count = 685, fps = 30,
  audio = "mih_full_v2.mp3", stand = "stand_v1.png",
  -- 30 FILES, 120 FRAMES. Each 1024x576 backdrop holds a 2x2 grid of 512x288
  -- cells, because Roblox will not take a texture over 1024 px on either axis.
  -- count is frames; the atlas describes how they are packed.
  swirl = "swirl", swirlPrefix = "sw_", swirlCount = 120,
  swirlAtlas = { cols = 2, rows = 2, tile = Vector2.new(512, 288) },
  swirlFps = 15,
}

-- HELD BACK ON PURPOSE, which is a different thing from missing.
--
-- The skin runs -- the files are there, the audio clock works, the stand drives.
-- It is the finish that is not done, and shipping a picker option that opens a
-- half-finished screen makes the whole hub look unfinished on the one screen
-- every user sees first. `skinAvailable` already had a vocabulary for "you
-- cannot have this and here is why", so this uses it rather than inventing a
-- second one -- and every caller that pcalls or checks the reason keeps working
-- unchanged.
--
-- Clearing this table is the whole of shipping it.
Loader.LOCKED = {
  ["Made in Heaven"] = "still in development -- it plays, but it is not finished",
}

function Loader.skinLocked(name)
  return Loader.LOCKED[name]
end

function Loader.skinAvailable(name)
  local heldBack = Loader.LOCKED[name]
  if heldBack then return false, heldBack end
  if name == "Aurora" then return true end
  if name ~= "Made in Heaven" then return false, "unknown skin" end
  local gca = rawget(getgenv(), "getcustomasset") or rawget(getgenv(), "getsynasset")
  if type(gca) ~= "function" then return false, "executor cannot load local files" end
  local M2 = Loader.MIH
  if not (L.Video and L.Video.available) then return false, "no video module" end
  local okV, whyV = L.Video.available(
    M2.dir .. "/" .. M2.frames, M2.prefix, M2.count, 1, 4, ".jpg", 1)
  if not okV then return false, tostring(whyV) end
  local okS, whyS = L.Video.available(
    M2.dir .. "/" .. M2.swirl, M2.swirlPrefix, M2.swirlCount, 1, 2, ".jpg", 4)
  if not okS then return false, tostring(whyS) end
  return true
end

function Loader.skinName()
  local want = L.Cfg and L.Cfg.data and L.Cfg.data.loader
  if type(want) ~= "string" then want = Loader.DEFAULT_SKIN end
  local ok = Loader.skinAvailable(want)
  if not ok then return Loader.DEFAULT_SKIN end
  return want
end

function Loader.setSkin(name)
  local ok, why = Loader.skinAvailable(name)
  if not ok then return false, why end
  if L.Cfg then L.Cfg.set("loader", name) end
  return true, name
end

-- ---------------------------------------------------------------- MIH skin
--
-- A full-bleed sequence with its own audio, wearing the standard loader
-- interface. It does NOT reimplement the progress UI: the status line is one
-- label, because when a 685-frame reveal is playing nobody is reading a
-- six-stage checklist -- they are watching the screen.
local function newMIH(opts)
  local M2 = Loader.MIH
  local self = setmetatable({}, { __index = Loader })
  self.total = math.max(opts.stages or 4, 1)
  self.done = 0
  self._fade = {}
  self.skin = "Made in Heaven"

  local gui = mk("ScreenGui", {
    Name = "LumenLoader", ResetOnSpawn = false, IgnoreGuiInset = true,
    ZIndexBehavior = Enum.ZIndexBehavior.Sibling, DisplayOrder = 40,
  })
  gui.Parent = L.host()
  L.own(gui)
  self.gui = gui

  -- SIZED FROM THE VIEWPORT, NOT FROM A PIXEL CAP.
  --
  -- The first version capped the card at 760 px. That looked reasonable on the
  -- machine it was checked on and turned into a video thumbnail floating in the
  -- middle of a large display -- which is exactly how it read back: a small
  -- unframed box on a bright background. Aurora derives every size from
  -- viewport height for this reason; so does this now.
  local vp = L.viewport()
  local vy = vp.Y
  local function S(f) return math.floor(vy * f + 0.5) end
  self.S, self.vy = S, vy

  -- The backdrop has to LOSE. At 0.35 the game stayed bright and legible and
  -- competed with the footage the whole way through; the clip is dark and
  -- low-contrast, so anything busy behind it wins. Blurred and heavily dimmed,
  -- the game is still there -- you can see you have not crashed -- but it has
  -- stopped arguing.
  local ground = mk("Frame", {
    Size = UDim2.fromScale(1, 1), BackgroundColor3 = Color3.new(0, 0, 0),
    BackgroundTransparency = 1, BorderSizePixel = 0, ZIndex = 1, Parent = gui,
  })
  self.ground = ground
  M.to(ground, "BackgroundTransparency", 0.12, "slow")
  A.blurTo(L.Window.BLUR or 18, "slow")

  -- The clip is 1024x711, so the card keeps that ratio rather than letterboxing
  -- footage into a shape it was not cut for.
  local cardH = S(0.60)
  local cardW = math.floor(cardH * (1024 / 711))
  if cardW > vp.X * 0.86 then
    cardW = math.floor(vp.X * 0.86)
    cardH = math.floor(cardW * (711 / 1024))
  end
  local CY = 0.50

  -- A GLOW UNDER IT, NOT A BORDER AROUND IT. A hard rectangle on a dark ground
  -- reads as pasted on; light spilling out from behind gives the card somewhere
  -- to sit. Built before the card so it stays underneath.
  if A.img and A.img.glow then
    local sp = math.floor(cardH * 0.55)
    self.cardGlow = mk("ImageLabel", {
      AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, CY),
      Size = UDim2.fromOffset(cardW + sp, cardH + sp),
      BackgroundTransparency = 1, Image = A.img.glow,
      ImageColor3 = T.c.accent, ImageTransparency = 1,
      ZIndex = 1, Parent = gui,
    })
    M.to(self.cardGlow, "ImageTransparency", 0.82, "slow")
  end

  local card = mk("Frame", {
    AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, CY),
    Size = UDim2.fromOffset(math.floor(cardW * 0.94), math.floor(cardH * 0.94)),
    BackgroundColor3 = Color3.new(0, 0, 0), BorderSizePixel = 0,
    ClipsDescendants = true, ZIndex = 2, Name = "Stage", Parent = gui,
  })
  L.corner(T.r.lg, card)
  L.stroke(T.c.lineStrong, 1, 0.55, card)
  -- it arrives at size rather than appearing at it
  M.to(card, "Size", UDim2.fromOffset(cardW, cardH), "slow")

  -- WORDMARK ABOVE, STATUS BELOW. The old build had a 10 px status line and
  -- nothing else, so there was no way to tell whose loading screen it was.
  local GLYPH = S(0.038)
  self.wordLbl = A.text({
    Text = L.track(tostring(opts.title or "LUMEN"), 3),
    font = T.font.display, size = GLYPH, colour = T.c.text,
    align = Enum.TextXAlignment.Center, AnchorPoint = Vector2.new(0.5, 1),
    Position = UDim2.new(0.5, 0, CY, -cardH / 2 - S(0.030)),
    Size = UDim2.fromOffset(S(0.9), math.floor(GLYPH * 1.4)),
    ZIndex = 8, Parent = gui,
  })
  M.set(self.wordLbl, "TextTransparency", 1)
  M.to(self.wordLbl, "TextTransparency", 0, "slow")

  self.subLbl = A.text({
    Text = tostring(opts.subtitle or ""),
    font = T.font.body, size = S(0.0135), colour = T.c.textMute,
    align = Enum.TextXAlignment.Center, AnchorPoint = Vector2.new(0.5, 1),
    Position = UDim2.new(0.5, 0, CY, -cardH / 2 - S(0.012)),
    Size = UDim2.fromOffset(S(0.9), S(0.03)),
    ZIndex = 8, Parent = gui,
  })
  M.set(self.subLbl, "TextTransparency", 1)
  M.to(self.subLbl, "TextTransparency", 0.25, "slow")
  -- NOT self.stage: Loader:stage() is a METHOD, and an instance field of the
  -- same name shadows it. Assigning the card there made loader:stage("...")
  -- try to CALL a Frame, which killed the boot sequence at step 0 of 6 while
  -- the video carried on playing -- so the screen looked perfectly healthy and
  -- the hub simply never appeared.
  self.card = card

  -- the swirl runs behind on its own slower clock, so the two sequences do not
  -- beat against each other at a shared frame rate
  self.swirl = L.Video and L.Video.new(card, {
    folder = M2.dir .. "/" .. M2.swirl, prefix = M2.swirlPrefix,
    count = M2.swirlCount, fps = M2.swirlFps, loop = true,
    digits = 2, ext = ".jpg", atlas = M2.swirlAtlas,
    Size = UDim2.fromScale(1, 1), Position = UDim2.fromScale(0.5, 0.5), ZIndex = 2,
  })

  -- MANUAL, because the audio is the clock. Left to its own RenderStepped
  -- timer the picture drifts against the music within a few seconds -- and this
  -- clip is cut to the track, so drift is the one thing that ruins it. The
  -- sound reports where it actually is; the picture follows that.
  self.vid = L.Video and L.Video.new(card, {
    folder = M2.dir .. "/" .. M2.frames, prefix = M2.prefix,
    count = M2.count, fps = M2.fps, loop = false, manual = true,
    digits = 4, ext = ".jpg",
    Size = UDim2.fromScale(1, 1), Position = UDim2.fromScale(0.5, 0.5), ZIndex = 3,
  })

  local gca = rawget(getgenv(), "getcustomasset") or rawget(getgenv(), "getsynasset")
  if gca then
    local okS, id = pcall(gca, M2.dir .. "/" .. M2.audio)
    if okS and id then
      local snd = mk("Sound", { SoundId = id, Volume = 1, Looped = false, Parent = gui })
      self.sound = snd
      -- PLAY AFTER IsLoaded, NOT BEFORE. Calling Play on a Sound that has not
      -- finished loading does nothing and reports nothing -- the first version
      -- of this ran the whole sequence in silence with TimePosition stuck at
      -- 0.00, which also stranded the picture, because the audio is its clock.
      -- Measured: the file loads in well under a second and is 22.91 s long.
      task.spawn(function()
        for _ = 1, 80 do
          if snd.IsLoaded then break end
          task.wait(0.05)
        end
        if snd.Parent then pcall(function() snd:Play() end) end
      end)
    end
    -- ---- the stand ---------------------------------------------------
    --
    -- IT DOES NOT LIVE IN THE MIDDLE, AND IT DOES NOT FADE IN.
    --
    -- Made in Heaven's whole conceit is that it has already been everywhere. A
    -- thing that strobes in one place is a flickering image; a thing that is in
    -- a DIFFERENT place every time you catch it has been moving between the
    -- glimpses, faster than you can see -- and the viewer supplies that
    -- inference for free, which is why it needs no motion trail.
    --
    -- So every burst picks a new anchor, scale and facing, and inside a longer
    -- burst it jumps AGAIN mid-strobe: two glimpses 30 ms apart in different
    -- places read as being in both at once rather than as travelling between.
    local okI, sid = pcall(gca, M2.dir .. "/" .. M2.stand)
    if okI and sid then
      local st = {}
      local holder = mk("Frame", {
        AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, 0.47),
        Size = UDim2.fromOffset(1, 1), BackgroundTransparency = 1,
        ZIndex = 6, Parent = card,
      })
      st.holder = holder

      -- HEAVENLY MEANS LIGHT BEHIND IT, not a brighter picture. The fan and the
      -- bloom are parented to the holder, so when the stand jumps the light
      -- jumps with it as one object instead of trailing behind.
      local rays = mk("Frame", {
        AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, 0.5),
        Size = UDim2.fromOffset(1, 1), BackgroundTransparency = 1,
        ZIndex = 6, Parent = holder,
      })
      st.rays, st.rayList = rays, {}
      for i = 1, 28 do
        local a = (i / 28) * math.pi * 2
        local r = mk("Frame", {
          AnchorPoint = Vector2.new(0.5, 0.5), Size = UDim2.fromOffset(2, 300),
          BackgroundColor3 = Color3.fromRGB(255, 246, 220), BackgroundTransparency = 1,
          BorderSizePixel = 0, Rotation = math.deg(a) + 90, ZIndex = 6, Parent = rays,
        })
        st.rayList[i] = { f = r, a = a }
      end

      -- Fourteen discs on a QUADRATIC falloff read as one glow. A linear ramp
      -- across this few shows as concentric bands.
      st.bloom = {}
      for i = 1, 14 do
        local b = mk("Frame", {
          AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, 0.5),
          Size = UDim2.fromOffset(10, 10),
          BackgroundColor3 = Color3.fromRGB(255, 248, 228), BackgroundTransparency = 1,
          BorderSizePixel = 0, ZIndex = 6, Parent = holder,
        })
        L.corner(999, b)
        st.bloom[i] = { f = b, k = i / 14 }
      end

      -- Three copies of the same image: a red and a cyan pass offset against
      -- each other for the chromatic tear, and the white one on top.
      local function layer(colour, z)
        return mk("ImageLabel", {
          AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, 0.5),
          Size = UDim2.fromOffset(S(0.30), S(0.47)), BackgroundTransparency = 1,
          ScaleType = Enum.ScaleType.Fit, Image = sid, ImageTransparency = 1,
          ImageColor3 = colour, ZIndex = z, Parent = holder,
        })
      end
      st.r = layer(Color3.fromRGB(255, 60, 70), 7)
      st.c = layer(Color3.fromRGB(60, 230, 255), 7)
      st.main = layer(Color3.new(1, 1, 1), 8)
      self.stand = st
    end
  end

  -- ONE LOOP DRIVES BOTH. The picture is seeked from the sound, and the stand
  -- is revealed on a cue measured in seconds of the track rather than in frames
  -- of the clip, so it lands in the same place whatever the playback does.
  local clipLen = M2.count / M2.fps
  self._t = 0
  self.conn = L.hold(L.RunService.RenderStepped:Connect(function(dt)
    if not L.live() or not gui.Parent then return end
    self._t = self._t + dt
    local at = self._t
    local snd = self.sound
    if snd and snd.IsPlaying and snd.TimePosition > 0 then at = snd.TimePosition end
    if self.vid then
      local want = math.floor(at * M2.fps) + 1
      if want > M2.count then want = M2.count end
      self.vid:setFrame(want)
    end
    -- THE STAND IS PACED BY THE BOOT, NOT BY THE CLIP.
    --
    -- Measured: the hub finishes loading about 9 s in and the clip runs 22.8 s,
    -- so driving the stand off clip time meant it never left its opening
    -- section -- cubed pressure at that point is 0.04, which is a burst every
    -- 1.3 s lasting 0.08 s, and the escalation and the p>=0.93 hold simply never
    -- happened. The footage got cut off mid-sentence every single time.
    --
    -- Pacing it by how much of the BOOT is done means the finale lands exactly
    -- as the hub appears, whether that takes four seconds or twenty. The picture
    -- and the audio keep their own clock; only the apparition follows the work.
    if self.stand then
      local boot = math.clamp((self.done or 0) / math.max(self.total or 1, 1), 0, 1)
      local byClip = at / clipLen
      self:_driveStand(at, math.max(boot, byClip * 0.35))
    end
  end))
  self.clipLen = clipLen

  self.status = A.text({
    Text = opts.status or "starting", font = T.font.mono, size = S(0.0125),
    colour = T.c.textDim, align = Enum.TextXAlignment.Center,
    AnchorPoint = Vector2.new(0.5, 0),
    Position = UDim2.new(0.5, 0, CY, cardH / 2 + S(0.028)),
    Size = UDim2.fromOffset(S(0.9), S(0.03)), ZIndex = 8, Parent = gui,
  })

  -- A VIGNETTE INSIDE THE CARD, so the footage falls off into its own edge
  -- instead of stopping dead at a rectangle. Wide and weak: narrow strong edges
  -- stack at the corners into visible dark blobs.
  if A.img and A.img.glow then
    self.vig = mk("ImageLabel", {
      AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, 0.5),
      Size = UDim2.fromScale(1.9, 1.9), BackgroundTransparency = 1,
      Image = A.img.glow, ImageColor3 = Color3.new(0, 0, 0),
      ImageTransparency = 0.55, ZIndex = 7, Parent = card,
    })
  end
  return self
end

function Loader.new(opts)
  opts = opts or {}
  -- SKIN DISPATCH. Anything that is not the default hands off entirely; the
  -- rest of this function is Aurora and only Aurora.
  if Loader.skinName() == "Made in Heaven" then
    local okB, alt = pcall(newMIH, opts)
    if okB and alt then return alt end
  end
  local self = setmetatable({}, { __index = Loader })
  self.total = math.max(opts.stages or 4, 1)
  self.done = 0
  self._fade = {}

  local gui = mk("ScreenGui", {
    Name = "LumenLoader", ResetOnSpawn = false, IgnoreGuiInset = true,
    ZIndexBehavior = Enum.ZIndexBehavior.Sibling, DisplayOrder = 50,
  })
  gui.Parent = L.host()
  L.own(gui)
  self.gui = gui

  -- No UIScale: every size derives from viewport height, so the composition is
  -- rasterised at its final resolution instead of authored small and stretched.
  local vy = L.viewport().Y
  local function S(f) return math.floor(vy * f + 0.5) end
  self.S, self.vy = S, vy

  A.blurTo(L.Window.BLUR, "slow")

  -- Register something to fade, remembering the transparency it rests at.
  local function fadable(obj, prop)
    self._fade[#self._fade + 1] = { obj = obj, prop = prop, base = obj[prop] }
    return obj
  end

  local root = mk("Frame", {
    Size = UDim2.fromScale(1, 1),
    BackgroundColor3 = Color3.fromRGB(3, 4, 7),
    BackgroundTransparency = 0.02,
    BorderSizePixel = 0,
    Name = "Root", Parent = gui,
  })
  self.root = root
  fadable(root, "BackgroundTransparency")

  -- Living backdrop: drifting wash, a sparse star field breathing on its own
  -- phases, a slow light sweep, and linear edge falloff. It registers its own
  -- fadable parts with us rather than being wrapped in a CanvasGroup, so none of
  -- it costs the text its crispness.
  -- The orb's centre and size are handed to the backdrop so the pulse rings
  -- originate from the hero rather than from the middle of the screen.
  self.backdrop = L.Backdrop.new(root, {
    ZIndex = 0,
  })
  for _, e in ipairs(self.backdrop:faders()) do
    self._fade[#self._fade + 1] = { obj = e.obj, prop = e.prop, base = e.obj[e.prop] }
  end

  local ORB   = S(0.34)
  local CY    = 0.40
  local below = function(px) return UDim2.new(0.5, 0, CY, ORB * 0.5 + px) end

  -- ---- the orb, from the real footage --------------------------------
  local vgroup = mk("CanvasGroup", {
    AnchorPoint = Vector2.new(0.5, 0.5),
    Position = UDim2.new(0.5, 0, CY, 0),
    Size = UDim2.fromOffset(ORB, ORB),
    BackgroundTransparency = 1,
    GroupTransparency = 0,
    Name = "OrbGroup", Parent = root,
  })
  fadable(vgroup, "GroupTransparency")

  local vid = L.Video.new(vgroup, {
    folder = "lumen_fx/saturn", prefix = "sat", first = ORB_FIRST,
    count = ORB_FRAMES, fps = ORB_FPS, size = ORB,
    Position = UDim2.fromScale(0.5, 0.5), ZIndex = 3, loop = true,
  })
  if vid then
    self.orb, self.isVideo = vid, true
  else
    pcall(function() vgroup:Destroy() end)
    self.orb = L.Orb.new(root, ORB, {
      Position = UDim2.new(0.5, 0, CY, 0), ZIndex = 3, speed = 1,
    })
    self.isVideo = false
  end

  -- ---- wordmark, assembled per letter --------------------------------
  local word = tostring(opts.title or "LUMEN")
  local GLYPH = S(0.052)
  local holder = mk("Frame", {
    AnchorPoint = Vector2.new(0.5, 0),
    Position = below(S(0.045)),
    Size = UDim2.fromOffset(S(0.55), math.floor(GLYPH * 1.25)),
    BackgroundTransparency = 1, Name = "Word", Parent = root,
  })
  local lay = L.list(math.max(2, S(0.003)), Enum.FillDirection.Horizontal, holder)
  lay.HorizontalAlignment = Enum.HorizontalAlignment.Center
  lay.VerticalAlignment = Enum.VerticalAlignment.Center

  -- ONE SWEEP ACROSS THE WORD, NOT FIVE LETTERS FLASHING SEPARATELY.
  --
  -- The wordmark is five independent TextLabels in a list layout, so a gradient
  -- per glyph would give each its own highlight and read as a row of blinking
  -- letters. A.chromeSeq takes a SLICE of the shared pattern, so glyph i is
  -- handed the window [i/n, (i+1)/n] of one continuous sweep -- and the light
  -- crosses the word the way it crosses a page title.
  -- Exactly what a page title uses: same palette, same rotation, same 12.5 s
  -- pass. The wordmark is five labels, so each gets a slice of one sweep.
  self.chromePat = A.chromePattern(A.CHROME.__default)
  self.chromeSpeed = A.CHROME.__default.speed
  self.glyphGrads = {}

  self.glyphs = {}
  for i = 1, #word do
    local ch = A.text({
      Text = word:sub(i, i),
      font = T.font.display, size = GLYPH, colour = T.c.text,
      align = Enum.TextXAlignment.Center,
      Size = UDim2.fromOffset(math.floor(GLYPH * 0.80), math.floor(GLYPH * 1.25)),
      LayoutOrder = i, Parent = holder,
    })
    ch.TextTransparency = 1
    self.glyphGrads[i] = mk("UIGradient", {
      Color = A.chromeSeq(self.chromePat, 0, (i - 1) / #word, i / #word),
      Rotation = A.CHROME.__default.rot, Parent = ch,
    })
    self.glyphs[i] = ch
    M.set(ch, "Position", UDim2.fromOffset(0, math.floor(GLYPH * 0.45)))
    M.after(0.12 + (i - 1) * 0.055, function()
      M.to(ch, "TextTransparency", 0, "base")
      M.to(ch, "Position", UDim2.fromOffset(0, 0), "expressive")
    end)
  end

  local SUB = S(0.0135)
  self.subLbl = A.text({
    Text = opts.subtitle or "",
    font = T.font.medium, size = SUB, colour = T.c.textMute,
    align = Enum.TextXAlignment.Center,
    AnchorPoint = Vector2.new(0.5, 0),
    Position = below(S(0.108)), Size = UDim2.fromOffset(S(0.6), SUB * 2),
    Parent = root,
  })
  fadable(self.subLbl, "TextTransparency")
  -- arrives after the wordmark has finished assembling, so the eye is led down
  self.subLbl.TextTransparency = 1
  M.set(self.subLbl, "Position", below(S(0.108) + S(0.010)))
  M.after(0.12 + #word * 0.055 + 0.10, function()
    M.to(self.subLbl, "TextTransparency", 0, "base")
    M.to(self.subLbl, "Position", below(S(0.108)), "expressive")
  end)

  -- ---- progress ------------------------------------------------------
  --
  -- A SHAPE, NOT A BAR. A progress bar spends its whole life telling you a
  -- number the percentage underneath it already says, and it says it worse --
  -- a bar at 40% and a bar at 45% look the same. The morphing infinity says
  -- the only other thing a loading screen has to communicate, which is that
  -- the thing is alive and still working, and it says that continuously.
  local SUB_BOTTOM = 0.108 + 0.0135 * 2      -- subtitle top + its own height
  -- The mark replaced a bar that was a third of the screen wide. At the same
  -- optical weight as a bar it would dominate; at the size the reference uses
  -- inline it disappeared into the gap the bar left. This is the size where it
  -- reads as deliberate against a 0.34 orb and a display-size wordmark.
  local MARK_H     = 0.105
  local BREATH     = 0.010
  local MARK_Y     = SUB_BOTTOM + MARK_H / 2 + BREATH
  local STATUS_Y   = MARK_Y + MARK_H / 2 + BREATH

  local BAR_W = S(0.34)                      -- the column the status row sits in

  local INF = S(MARK_H)
  self.inf = L.Infinity.newRing(root, INF, {
    Position = below(S(MARK_Y)),
    colour = T.c.accent,
    ZIndex = 2,
    -- NOT SELF DRIVEN. This screen already has one RenderStepped running the
    -- percentage, the shimmer and the wordmark's breathing; a second clock for
    -- the curve is a second thing to fall out of step on a bad frame. It gets
    -- handed the same time value as everything else below.
    drive = false,
  })
  fadable(self.inf.holder, "GroupTransparency")


  -- status and percent on one line, in the same column the mark is centred on
  local MONO = S(0.0125)
  self.statusPair, self.statusIdx = {}, 1
  for k = 1, 2 do
    local lbl = A.text({
      Text = (k == 1) and (opts.status or "starting") or "",
      font = T.font.mono, size = MONO, colour = T.c.textMute,
      -- CENTRED NOW THAT IT IS ALONE. It was left-aligned in a column shared
      -- with a right-aligned percentage; with the percentage moved inside the
      -- ring, keeping it left just parks one short word off to one side of a
      -- screen whose every other element is centred.
      align = Enum.TextXAlignment.Center,
      AnchorPoint = Vector2.new(0.5, 0),
      Position = below(S(STATUS_Y)), Size = UDim2.fromOffset(BAR_W, MONO * 2),
      Parent = root,
    })
    lbl.TextTransparency = (k == 1) and 0 or 1
    self.statusPair[k] = lbl
    fadable(lbl, "TextTransparency")
  end
  self.status = self.statusPair[1]
  self._statusY = S(STATUS_Y)
  self._below = below

  -- INSIDE THE RING, NOT BESIDE IT.
  --
  -- It used to sit at the right end of the status row, which put the two things
  -- that describe the same fact -- how far along this is -- at opposite ends of
  -- the screen, with a decorative mark between them. The ring carries the
  -- progress now, so the number belongs in the middle of it: one object that
  -- says the same thing twice, precisely and approximately, instead of three
  -- objects saying different things in different places.
  --
  -- Bigger, too. It is the only number on the screen.
  local PCT = S(0.020)
  self.pct = A.text({
    Text = "0%", font = T.font.mono, size = PCT, colour = T.c.text,
    align = Enum.TextXAlignment.Center, valign = Enum.TextYAlignment.Center,
    AnchorPoint = Vector2.new(0.5, 0.5),
    Position = below(S(MARK_Y)),
    Size = UDim2.fromOffset(S(MARK_H), S(MARK_H)),
    ZIndex = 3, Parent = root,
  })
  fadable(self.pct, "TextTransparency")

  -- One line below the status row, hidden until there is something to wait for.
  -- Wider than the status column because it carries a sentence, not a word.
  self.flashLbl = A.text({
    Text = "", font = T.font.mono, size = MONO, colour = T.c.accent,
    align = Enum.TextXAlignment.Center,
    AnchorPoint = Vector2.new(0.5, 0),
    Position = below(S(STATUS_Y + 0.030)),
    Size = UDim2.fromOffset(S(0.62), MONO * 2),
    Visible = false, Parent = root,
  })
  fadable(self.flashLbl, "TextTransparency")

  -- ---- continuous motion ----------------------------------------------
  -- One connection drives everything that is always moving: the percentage
  -- counting up, the curve morphing, and the wordmark breathing.
  self.pctSpring = L.Spring.new(0.75, -0.25, 0)   -- overdamped: a counter must
  self._wordT = 0                                  -- never tick past its target
  self.animConn = L.hold(L.RunService.RenderStepped:Connect(function(dt)
    if not L.live() or not root.Parent then return end

    -- percentage COUNTS rather than jumping between stage values
    local v = self.pctSpring:step(dt)
    local shown = math.floor(v + 0.5)
    if shown ~= self._lastPct then
      self._lastPct = shown
      self.pct.Text = shown .. "%"
    end

    -- THE CURVE RUNS ON THIS CLOCK, NOT ITS OWN. Handed the same accumulating
    -- time as the wordmark's breathing, so the two can never drift; and it is
    -- driven right through the exit rather than being cut off at `leaving`,
    -- because the settle to the circle happens DURING the fade and stopping the
    -- updates would freeze it mid-morph while it faded.
    self._wordT = self._wordT + dt
    if self.inf then
      -- the ring is handed the same figure the counter is easing toward, so the
      -- arc and the number can never disagree about where we are
      if self.inf.setProgress then self.inf:setProgress((self.pctSpring.value or 0) / 100) end
      self.inf:update(self._wordT)
    end

    -- THE DOWNLOAD LINE FLASHES, because it is the one thing on this screen the
    -- user is actually waiting on. Everything else here breathes gently; this
    -- pulses hard enough to read as "something is happening, keep waiting"
    -- rather than as decoration. Driven off the same clock as the rest, so it
    -- cannot drift out of step with the wordmark underneath it.
    if self.flashLbl and self.flashLbl.Visible and not self.leaving then
      local p = 0.5 + 0.5 * math.sin(self._wordT * 4.2)
      self.flashLbl.TextTransparency = 0.72 - 0.72 * p
    end

    -- wordmark breathes once it has finished arriving, staggered per glyph so it
    -- ripples along the word instead of pulsing as a block
    if not self.leaving
       and self._wordT > 0.12 + #self.glyphs * 0.055 + 0.5 then
      for i, g in ipairs(self.glyphs) do
        g.TextTransparency = 0.06 + math.sin(self._wordT * 1.15 + i * 0.55) * 0.06
      end
    end

    -- CHROME. Same throttle as the page titles and for the same reason: the
    -- phase stays continuous, only the rebuild is paced. Five glyphs at 24 Hz
    -- is 120 sequence builds a second on a screen that exists for four.
    if self.glyphGrads then
      self._chromeAcc = (self._chromeAcc or 1) + dt
      if self._chromeAcc >= 1 / 24 then
        self._chromeAcc = 0
        local n = #self.glyphGrads
        local phase = (self._wordT * self.chromeSpeed * 0.5) % 1
        for i, g in ipairs(self.glyphGrads) do
          g.Color = A.chromeSeq(self.chromePat, phase, (i - 1) / n, i / n)
        end
      end
    end
  end))

  -- ---- entrance ------------------------------------------------------
  self:fade(1, true)
  self:fade(0, false, "base")

  return self
end

-- alpha 0 = fully visible, 1 = gone. Walking a list keeps the group fade without
-- forcing the text through a render target to get it.
function Loader:fade(alpha, immediate, token)
  for _, e in ipairs(self._fade) do
    local v = e.base + (1 - e.base) * alpha
    if immediate then M.set(e.obj, e.prop, v)
    else M.to(e.obj, e.prop, v, token or "base") end
  end
  -- glyphs run their own entrance cascade, so they are only driven on the exit
  if alpha > 0 and self.glyphs then
    for _, g in ipairs(self.glyphs) do
      if immediate then M.set(g, "TextTransparency", alpha)
      else M.to(g, "TextTransparency", alpha, token or "base") end
    end
  end
end

-- The flashing wait line. Pass nil to put it away.
function Loader:flash(text)
  if not self.flashLbl then return self end
  if text == nil then
    self.flashLbl.Visible = false
    return self
  end
  self.flashLbl.Text = tostring(text)
  self.flashLbl.Visible = true
  return self
end

function Loader:stage(text)
  self.done = math.min(self.done + 1, self.total)
  if text then self:say(text) end
  if not self.pctSpring then return self end   -- MIH shows no percentage
  local a = self.done / self.total
  self.pctSpring:to(a * 100)
  return self
end

function Loader:say(text)
  if not text then return self end
  -- MIH carries ONE plain label, Aurora a swapping pair. Branching here rather
  -- than giving MIH a fake statusPair keeps the difference visible: the two
  -- screens genuinely say things differently, and pretending otherwise is how a
  -- shared interface turns into a shared implementation nobody can change.
  if self.skin == "Made in Heaven" then
    if self.status then
      self.status.Text = tostring(text)
      M.set(self.status, "TextTransparency", 1)
      M.to(self.status, "TextTransparency", 0, "base")
    end
    return self
  end
  local nextIdx = (self.statusIdx % 2) + 1
  local outLbl, inLbl = self.statusPair[self.statusIdx], self.statusPair[nextIdx]
  self.statusIdx, self.status = nextIdx, inLbl

  inLbl.Text = tostring(text)
  M.set(inLbl, "TextTransparency", 1)
  M.set(inLbl, "Position", self._below(self._statusY + self.S(0.008)))
  M.to(inLbl, "TextTransparency", 0, "base")
  M.to(inLbl, "Position", self._below(self._statusY), "expressive")

  M.to(outLbl, "TextTransparency", 1, "fast")
  M.to(outLbl, "Position", self._below(self._statusY - self.S(0.008)), "base")
  return self
end

function Loader:finish(after)
  if self.skin == "Made in Heaven" then
    -- A screen that fades out while its music keeps playing over the hub is the
    -- kind of thing nobody notices until it ships.
    self:say("ready")
    self:stopMIH()
    local g = self.gui
    if g then
      -- EVERY GuiObject, NOT JUST IMAGES AND TEXT.
      --
      -- The first version faded ImageLabels and TextLabels and left the bloom
      -- and the ray fan behind -- 14 discs and 28 rays, all plain Frames, all
      -- still lit over the hub after the screen was supposedly gone. Measured:
      -- 38 descendants still opaque with the loader "finished".
      for _, d in ipairs(g:GetDescendants()) do
        if d:IsA("ImageLabel") then
          M.to(d, "ImageTransparency", 1, "slow")
        elseif d:IsA("TextLabel") or d:IsA("TextButton") then
          M.to(d, "TextTransparency", 1, "fast")
          if d.BackgroundTransparency < 1 then
            M.to(d, "BackgroundTransparency", 1, "fast")
          end
        elseif d:IsA("GuiObject") then
          M.to(d, "BackgroundTransparency", 1, "slow")
        end
        if d:IsA("UIStroke") then M.to(d, "Transparency", 1, "slow") end
      end
      if self.card then
        M.to(self.card, "Size", UDim2.fromOffset(
          math.floor(self.card.AbsoluteSize.X * 0.94),
          math.floor(self.card.AbsoluteSize.Y * 0.94)), "slow")
      end

      -- DISABLED BEFORE DESTROYED, and destroyed on a generation-guarded delay.
      -- A ScreenGui that outlives its fade is invisible but still hit-testable;
      -- leaving one over the hub is a dead zone nobody can explain later.
      -- `after` IS A CALLBACK, NOT A DELAY. Aurora calls it once its fade has
      -- run, and it is what reveals the hub window -- so treating it as a
      -- number both threw ("arithmetic on function and number") and skipped the
      -- reveal entirely. Same contract here: fade, hand over, then clean up.
      task.delay(0.52, function()
        if after then L.try("loader.after", after) end
      end)
      task.delay(0.75, function()
        if g and g.Parent then g.Enabled = false end
      end)
      task.delay(1.3, function()
        pcall(function() g:Destroy() end)
        if L.Hub and L.Hub._loader == self then L.Hub._loader = nil end
      end)
    end
    return self
  end
  self:say("ready")
  self.pctSpring:to(100)

  -- THE CURVE STOPS WHEN LOADING STOPS, NOT WHEN ITS CYCLE ENDS. It is on a
  -- five second loop and loading rarely takes five seconds, so left alone it
  -- would be caught mid-morph -- a half-formed shape fading out, which reads as
  -- the screen being cut off rather than finishing. Asking it to resolve here,
  -- a beat BEFORE the fade starts, means it has come to rest on the circle by
  -- the time anything moves.
  if self.inf then self.inf:resolve() end

  task.delay(0.26, function()          -- one beat to read "ready" at 100%
    if not L.live() then return end
    self.leaving = true                -- the render loop lets go of the wordmark

    -- THE WINDOW COMES UP AS THE LOADER GOES DOWN. These used to be sequential:
    -- fade the loader for 0.52 s, THEN show the window -- so after "ready" the
    -- screen held a blurred game and nothing else for most of a second. The two
    -- are one handover, so they run on one clock.
    self:fade(1, false, "base")
    if after then L.try("loader.after", after) end

    -- derived from the token, not typed: a literal here is a third clock that
    -- drifts the moment anyone changes the motion profile
    local dur = select(1, M.resolve("base"))
    task.delay(dur + 0.08, function()
      if self.orb and self.orb.destroy then self.orb:destroy() end
      if self.inf then self.inf:destroy() end
      pcall(function() self.gui:Destroy() end)
    end)
  end)
  return self
end

-- MIH overrides only what differs. stage/say/flash all land on one line here,
-- because a six-stage checklist over a full-screen reveal is a checklist nobody
-- reads -- and fade/finish already work on self._fade, which it populates.
function Loader:isMIH() return self.skin == "Made in Heaven" end

-- MIH owns a sound and a drive loop, so its teardown has to do more than fade.
-- Loader:finish is shared, and a screen that fades out while its music keeps
-- playing over the hub is the kind of thing nobody notices until it ships.
function Loader:stopMIH()
  if self.conn then pcall(function() self.conn:Disconnect() end) self.conn = nil end
  -- THE PLAYERS HAVE THEIR OWN LOOPS. Disconnecting only the drive loop left
  -- the swirl advancing, and every frame it advanced it re-set that frame's
  -- ImageTransparency back to its resting value -- so the fade was being undone
  -- as fast as it was applied. One backdrop frame was still fully opaque over
  -- the hub with the loader "finished".
  for _, v in ipairs({ self.vid, self.swirl }) do
    if v then
      if v.pause then pcall(function() v:pause() end) end
      if v.conn then pcall(function() v.conn:Disconnect() end) end
    end
  end
  if self.sound then
    local snd = self.sound
    M.to(snd, "Volume", 0, "slow")
    task.delay(0.7, function() pcall(function() snd:Stop() end) end)
  end
end

-- ---------------------------------------------------------------- stand drive
--
-- `p` is progress through the clip, 0..1. Pressure is CUBED so the first half
-- stays sparse and the last quarter comes apart -- a linear ramp spends its
-- whole budget early and has nowhere left to go at the end.
function Loader:_driveStand(now, p)
  local S = self.stand
  if not (S and S.main and S.main.Parent) then return end

  local pressure = math.clamp((p - 0.14) / 0.76, 0, 1)
  pressure = pressure * pressure * pressure
  local hold = p >= 0.93

  self._burstUntil = self._burstUntil or 0
  self._nextBurst  = self._nextBurst or 0
  self._strobeAt   = self._strobeAt or 0
  self._jumpAt     = self._jumpAt or 0
  self._anchor     = self._anchor or { x = 0.5, y = 0.47, s = 1, face = 1 }

  local A = self._anchor
  local function reanchor()
    -- biased away from dead centre and kept off the lower third, so the clip
    -- underneath is never fully covered
    A.x = 0.18 + math.random() * 0.64
    A.y = 0.28 + math.random() * 0.26
    A.s = 0.5 + math.random() * (0.5 + pressure * 0.55)
    A.face = (math.random() < 0.5) and -1 or 1
  end

  local visible, tear
  if hold then
    -- the finale settles: centre, full size, and a steady shimmer instead of
    -- the random tear, so the last thing you see is legible
    visible, tear = true, 7 + math.sin(now * 26) * 6
    A.x, A.y, A.s, A.face = 0.5, 0.47, 1.0, 1
  else
    if now >= self._nextBurst then
      self._burstUntil = now + 0.07 + pressure * 0.30
      self._nextBurst  = self._burstUntil
        + (0.95 - pressure * 0.85) * (0.4 + math.random() * 0.7)
      reanchor()
      self._jumpAt = now + 0.05 + math.random() * 0.09
    end
    if now < self._burstUntil then
      if now >= self._strobeAt then
        self._strobeOn = not self._strobeOn
        self._strobeAt = now + (0.012 + math.random() * 0.030)  -- 1-2 frames @30
      end
      if now >= self._jumpAt then
        reanchor()
        self._jumpAt = now + 0.05 + math.random() * 0.10
      end
      visible = self._strobeOn
      tear = 5 + math.random() * (7 + pressure * 30)
    else
      visible = false
    end
  end

  S.holder.Position = UDim2.fromScale(A.x, A.y)

  if not visible then
    S.main.ImageTransparency, S.r.ImageTransparency, S.c.ImageTransparency = 1, 1, 1
    for _, b in ipairs(S.bloom) do b.f.BackgroundTransparency = 1 end
    for _, r in ipairs(S.rayList) do r.f.BackgroundTransparency = 1 end
    return
  end

  local a = hold and 0.04 or (0.06 + (1 - pressure) * 0.22)
  S.main.ImageTransparency = a
  S.r.ImageTransparency = a + 0.32
  S.c.ImageTransparency = a + 0.32

  local base = self.S and self.S(0.30) or 398
  local w, h = base * A.s, base * (620 / 398) * A.s
  S.main.Size = UDim2.fromOffset(w * A.face, h)
  S.r.Size    = UDim2.fromOffset(w * A.face, h)
  S.c.Size    = UDim2.fromOffset(w * A.face, h)

  -- ASYMMETRIC ON PURPOSE. Equal offsets in opposite directions cancel into
  -- something that merely looks embossed; unequal ones read as a signal tearing.
  local jx = (math.random() - 0.5) * tear * 0.7
  local jy = (math.random() - 0.5) * tear * 0.4
  S.r.Position    = UDim2.new(0.5, -tear + jx, 0.5, jy)
  S.c.Position    = UDim2.new(0.5, tear * 0.72 - jx, 0.5, -jy * 0.6)
  S.main.Position = UDim2.new(0.5, jx * 0.35, 0.5, jy * 0.35)

  local glow = hold and 1 or (0.45 + pressure * 0.55)
  local d0 = 300 * A.s
  for _, b in ipairs(S.bloom) do
    local d = d0 * (0.3 + b.k * 1.6)
    b.f.Size = UDim2.fromOffset(d, d)
    local fall = 1 - b.k
    b.f.BackgroundTransparency = 1 - glow * fall * fall * 0.45
  end

  S.rays.Rotation = (now * 26) % 360
  local reach = (150 + pressure * 90) * A.s
  for _, r in ipairs(S.rayList) do
    r.f.Position = UDim2.fromOffset(math.cos(r.a) * reach, math.sin(r.a) * reach)
    r.f.Size = UDim2.fromOffset(2, 220 * A.s)
    r.f.BackgroundTransparency = 1 - glow * 0.30
  end
end


end
do -- ==== lm_16_theme.lua ====
-- LUMEN :: THEME
-- Accent palettes, motion profiles, density and blur.

local L = getgenv().LUMEN
local T, M = L.T, L.Motion

local Theme = {}
L.Theme = Theme

-- ---------------------------------------------------------------- palettes
local rgb = Color3.fromRGB

Theme.palettes = {
  chrome = { name = "Chrome", accent = rgb(138, 176, 255), alt = rgb(196, 182, 255),
             deep = rgb(30, 44, 84) },
  ember  = { name = "Ember",  accent = rgb(255, 170, 92),  alt = rgb(255, 122, 122),
             deep = rgb(86, 44, 24) },
  mint   = { name = "Mint",   accent = rgb(94, 232, 190),  alt = rgb(140, 232, 255),
             deep = rgb(20, 74, 66) },
  orchid = { name = "Orchid", accent = rgb(206, 148, 255), alt = rgb(255, 148, 214),
             deep = rgb(64, 34, 90) },
  bone   = { name = "Bone",   accent = rgb(226, 228, 236), alt = rgb(180, 186, 204),
             deep = rgb(52, 55, 66) },
  -- Sampled from the Heaven footage: amber swirl, green type, bone-white reveal.
  heaven = { name = "Heaven", accent = rgb(224, 178, 92),  alt = rgb(150, 214, 150),
             deep = rgb(74, 52, 20) },
}
Theme.order = { "chrome", "ember", "mint", "orchid", "bone" }
Theme.current = "chrome"

function Theme.names()
  local out = {}
  for _, k in ipairs(Theme.order) do out[#out + 1] = Theme.palettes[k].name end
  return out
end

function Theme.keyFor(displayName)
  for _, k in ipairs(Theme.order) do
    if Theme.palettes[k].name == displayName then return k end
  end
  return "chrome"
end

-- Applies the colours only. Callers that need the UI to reflect it must rebuild.
function Theme.poke(key)
  local p = Theme.palettes[key] or Theme.palettes.chrome
  T.c.accent, T.c.accentAlt, T.c.accentDeep = p.accent, p.alt, p.deep
  Theme.current = key
  -- The reverse map is keyed by colour value, so it has to follow the accent.
  if T.reindex then T.reindex() end
end

function Theme.set(key, opts)
  opts = opts or {}
  if not Theme.palettes[key] then return false, "no palette " .. tostring(key) end
  Theme.poke(key)
  if L.Cfg then L.Cfg.set("theme", key) end

  -- Repainted in place: L.mk registered every palette-coloured property with the
  -- token it came from. Gradients need their own pass because a ColorSequence is
  -- not a Color3 and the registry cannot see them. A rebuild cost ~700 instances
  -- plus scroll positions, open popovers and the focus ring.
  if opts.rebuild ~= false then
    local painted = L.repaint and L.repaint() or 0
    local grads = L.A and L.A.repaintGradients and L.A.repaintGradients() or 0
    L.note("theme", string.format("%s -- repainted %d properties, %d gradients",
      Theme.palettes[key].name, painted, grads))
  end
  return true, (Theme.palettes[key].name .. " applied")
end

-- For changes a repaint cannot cover: density row metrics are read at
-- construction.
function Theme.rebuild()
  if not (L.Hub and L.Hub.window) then return false end
  local old = L.Hub.window
  local tab = old.active or 1
  local pos = old.shell and old.shell.Position
  local scale = old.scaleObj and old.scaleObj.Scale
  pcall(function() old.gui:Destroy() end)
  if old.dock then pcall(function() old.dock:Destroy() end) end

  local win = L.Hub.build()
  L.Hub.window = win
  if scale and win.scaleObj then win.scaleObj.Scale = scale end
  if pos then win.shell.Position = pos end
  win:show()
  if win.tabs[tab] then win:select(tab, true) end
  return true
end

-- ---------------------------------------------------------------- motion

-- Multipliers applied to every token as it is resolved. Measured through the
-- shipped spring at 2 kHz; t90 is when the value first reaches 90% of travel:
--
--     profile     dur   bnc |  base t90 / ov  |  slow t90 / ov  | expressive ov
--     Calm       1.40  0.35 |   238ms   0.0%  |   345ms   0.1%  |     0.4%
--     Silk       1.20  0.80 |   181ms   0.8%  |   259ms   1.0%  |     4.8%
--     Default    1.00  1.00 |   143ms   1.5%  |   204ms   2.0%  |     8.4%
--     Lively     0.72  1.60 |    89ms   5.4%  |   125ms   6.9%  |    26.2%
--
-- Silk is the default: the fastest profile that still clears 180 ms, at 0.8%
-- overshoot, with expressive left at 4.8% so the loader mark keeps its bounce.
Theme.motionProfiles = {
  Calm    = { dur = 1.40, bounce = 0.35 },
  Silk    = { dur = 1.20, bounce = 0.80 },
  -- Heaven mode's own pace, measured alongside the others:
  --     Heaven  0.80  0.75 |  base 122ms 0.6%  |  fast 73ms 0.6%
  -- Quicker than Silk, but at 0.6% overshoot rather than Lively's 5.4%.
  Heaven  = { dur = 0.80, bounce = 0.75 },
  Default = { dur = 1.00, bounce = 1.00 },
  Lively  = { dur = 0.72, bounce = 1.60 },
}
Theme.motionOrder = { "Calm", "Silk", "Default", "Lively", "Heaven" }
Theme.motion = "Silk"

-- Id the Config tab registers its profile picker under. This setting is stored
-- twice and both copies must be written together -- see setMotion.
Theme.MOTION_CTL = "config.motion.Animation profile"

function Theme.setMotion(name)
  local p = Theme.motionProfiles[name]
  if not p then return false, "no profile " .. tostring(name) end
  Theme.motion = name
  M.durScale, M.bounceScale = p.dur, p.bounce
  M.reprofile()

  -- The profile lives in two keys: Cfg "motion" and the Config picker's
  -- Cfg.features[MOTION_CTL]. Cfg.applyOnLoad restores the picker and fires its
  -- callback back into here with the old value, so writing only one key means a
  -- profile set from anywhere else reverts on the next execute. Write both.
  if L.Cfg then
    L.Cfg.set("motion", name)
    if L.Cfg.setFeat then pcall(L.Cfg.setFeat, Theme.MOTION_CTL, name) end
  end
  -- Move the visible control so the dropdown cannot show a stale profile.
  if L.C and L.C.find then
    local h = L.C.find(Theme.MOTION_CTL)
    if h and h.set then pcall(function() h:set(name, true) end) end
  end
  return true, name
end

-- ---------------------------------------------------------------- heaven
-- Heaven mode is a parameter set, not a second interface: it moves palette,
-- motion profile and loading screen together, and stores what it replaced so
-- turning it off restores the operator's own values.
Theme.HEAVEN = { palette = "heaven", motion = "Heaven", loader = "Made in Heaven" }
Theme.heavenOn = false

function Theme.setHeaven(on, silent)
  on = on and true or false
  local H = Theme.HEAVEN

  if on and not Theme.heavenOn then
    Theme._preHeaven = {
      palette = (L.Cfg and L.Cfg.data and L.Cfg.data.theme) or "chrome",
      motion  = Theme.motion,
      loader  = (L.Loader and L.Loader.skinName and L.Loader.skinName()) or nil,
    }
  end

  local want = on and H or (Theme._preHeaven or
    { palette = "chrome", motion = "Silk", loader = "Aurora" })

  Theme.heavenOn = on
  pcall(function() Theme.set(want.palette) end)
  pcall(function() Theme.setMotion(want.motion) end)
  if L.Loader and L.Loader.setSkin and want.loader then
    -- Loader may be absent on this install; then the next execute opens Aurora.
    pcall(L.Loader.setSkin, want.loader)
  end
  if L.Cfg then L.Cfg.set("heaven", on) end

  if not silent and L.Toast then
    if on then
      L.Toast.info("Made in Heaven", "Palette, motion and loading screen switched")
    else
      L.Toast.info("Heaven off", "Everything back to how you had it")
    end
  end
  return true
end

-- ---------------------------------------------------------------- density

Theme.densities = { Comfortable = 1.0, Compact = 0.82 }
Theme.densityOrder = { "Comfortable", "Compact" }
Theme.density = "Comfortable"

function Theme.setDensity(name)
  local d = Theme.densities[name]
  if not d then return false, "no density " .. tostring(name) end
  Theme.density = name
  T.dense = d
  if L.Cfg then L.Cfg.set("density", name) end
  -- Row heights are read at construction, so density needs a real rebuild.
  Theme.rebuild()
  return true, name
end

-- ---------------------------------------------------------------- blur

function Theme.setBlur(v)
  v = math.clamp(tonumber(v) or 16, 0, 40)
  L.Window.BLUR = v
  if L.Cfg then L.Cfg.set("blur", v) end
  if L.Hub and L.Hub.window and not L.Hub.window.hidden then
    L.A.blurTo(v, "base")
  end
  return true, string.format("blur %d", v)
end

-- ---------------------------------------------------------------- restore
if L.Cfg then
  local k = L.Cfg.data.theme
  if type(k) == "string" and Theme.palettes[k] then Theme.poke(k) end
  local dn = L.Cfg.data.density
  if type(dn) == "string" and Theme.densities[dn] then
    Theme.density = dn
    T.dense = Theme.densities[dn]
  end
  local bl = tonumber(L.Cfg.data.blur)
  if bl then L.Window.BLUR = math.clamp(bl, 0, 40) end
  local m = L.Cfg.data.motion
  if type(m) == "string" and Theme.motionProfiles[m] then
    Theme.motion = m
    local p = Theme.motionProfiles[m]
    M.durScale, M.bounceScale = p.dur, p.bounce
  end
  -- Only the flag is restored; the three values came from their own keys above.
  -- Re-applying the mode here would overwrite a palette changed while it was on.
  Theme.heavenOn = (L.Cfg.data.heaven == true)
end

end
do -- ==== lm_17_palette.lua ====
-- LUMEN :: COMMAND PALETTE
-- Ctrl+K, type, Enter. Tab is resolved lazily by walking up the ancestry, so
-- moving a control between tabs never leaves a stale entry. Match is subsequence.

local L = getgenv().LUMEN
local T, M, A = L.T, L.Motion, L.A
local mk = L.mk

local P = {}
L.Palette = P

P.entries = {}
P.open = false

-- ---------------------------------------------------------------- registry

function P.add(frame, name, hint, run)
  P.entries[#P.entries + 1] = {
    frame = frame, name = name or "?", hint = hint or "", run = run,
  }
end

function P.clear() P.entries = {} end

local function tabOf(entry)
  if entry._tab ~= nil then return entry._tab end
  local win = L.Hub and L.Hub.window
  local n = nil
  if win and entry.frame then
    local node = entry.frame
    while node and node.Parent do
      for i, t in ipairs(win.tabs) do
        if node == t.page then n = i break end
      end
      if n then break end
      node = node.Parent
    end
  end
  entry._tab = n or false
  return entry._tab
end

-- ---------------------------------------------------------------- matching

-- Returns nil for no match, otherwise a score (higher is better).
local function score(query, text)
  if query == "" then return 0 end
  local q, t = query:lower(), text:lower()
  local qi, s, streak = 1, 0, 0
  local prevWordStart = true
  for i = 1, #t do
    local c = t:sub(i, i)
    local isBoundary = (i == 1) or t:sub(i - 1, i - 1):match("[%s%-_/]") ~= nil
    if qi <= #q and c == q:sub(qi, qi) then
      streak = streak + 1
      s = s + 6 + streak * 3
      if isBoundary then s = s + 14 end        -- start of a word matters most
      if i <= 3 then s = s + 4 end             -- near the front of the label
      qi = qi + 1
    else
      streak = 0
    end
    prevWordStart = isBoundary
  end
  local _ = prevWordStart
  if qi <= #q then return nil end              -- not all of the query consumed
  return s - #t * 0.15                         -- prefer shorter, tighter labels
end

function P.search(query)
  local out = {}
  -- TYPE "reset" TO SEE WHAT IS NOT STOCK. Reset rides the palette because it
  -- costs no Instance, no connection, and no meaning stolen from C.pinnable's
  -- right-click -- and it reaches sliders and dropdowns, which have no row
  -- right-click at all. The entry list is the diff view, so there is no second
  -- surface to build. Carrying the control's own frame makes the existing
  -- activate path jump to its tab and flash the row before the value moves.
  local Cfg = L.Cfg
  if Cfg and Cfg.changedFromDefault and query:lower():sub(1, 3) == "res" then
    for _, d in ipairs(Cfg.changedFromDefault()) do
      local h = L.C and L.C.find and L.C.find(d.id)
      if h and h.frame then
        out[#out + 1] = { s = 1e6, e = {
          frame = h.frame,
          name = "Reset " .. tostring(h._label or d.id),
          hint = tostring(d.value) .. "  \226\134\146  " .. tostring(d.default),
          run = function() Cfg.resetFeat(d.id) end,
        } }
      end
    end
  end
  for _, e in ipairs(P.entries) do
    if e.frame and e.frame.Parent then
      local sc = score(query, e.name .. " " .. e.hint)
      if sc then out[#out + 1] = { e = e, s = sc } end
    end
  end
  table.sort(out, function(a, b)
    if a.s ~= b.s then return a.s > b.s end
    return a.e.name < b.e.name
  end)
  return out
end

-- ---------------------------------------------------------------- ui

local gui, root, box, listFrame, rows, sel, results

local function paintSel()
  for i, r in ipairs(rows) do
    local on = (i == sel)
    M.to(r.bg, "BackgroundTransparency", on and 0.86 or 1, "instant")
    M.to(r.name, "TextColor3", on and T.c.text or T.c.textDim, "instant")
  end
end

-- `animate` only on open: cascading per keystroke re-staggers eight rows on
-- every character and reads as lag, so search results snap.
local function render(list, animate)
  results = list
  if P._seq then P._seq:cancel() P._seq = nil end
  for _, r in ipairs(rows) do r.bg.Visible = false end

  local shown = {}
  for i = 1, math.min(#list, 8) do
    local r = rows[i]
    local e = list[i].e
    local ti = tabOf(e)
    local win = L.Hub and L.Hub.window
    r.bg.Visible = true
    r.name.Text = e.name
    r.hint.Text = (ti and win and win.tabs[ti] and win.tabs[ti].name or e.hint or "")
    r.entry = e
    shown[#shown + 1] = r
  end

  if animate and #shown > 0 then
    for _, r in ipairs(shown) do
      M.set(r.name, "TextTransparency", 1)
      M.set(r.hint, "TextTransparency", 1)
      M.set(r.name, "Position", UDim2.fromOffset(18, 0))
    end
    -- Cancellable, so a cascade still running after close cannot fade rows back in.
    P._seq = M.seq(shown, function(r)
      if not r.bg.Parent then return end
      M.to(r.name, "TextTransparency", 0, "base")
      M.to(r.hint, "TextTransparency", 0, "base")
      M.to(r.name, "Position", UDim2.fromOffset(10, 0), "base")
    end, { step = 0.028, cap = 0.2 })
  else
    for _, r in ipairs(shown) do
      M.set(r.name, "TextTransparency", 0)
      M.set(r.hint, "TextTransparency", 0)
      M.set(r.name, "Position", UDim2.fromOffset(10, 0))
    end
  end

  sel = (#list > 0) and 1 or 0
  paintSel()
end

local function activate(i)
  local item = results and results[i]
  if not item then return end
  local e = item.e
  P.hide()
  local ti = tabOf(e)
  local win = L.Hub and L.Hub.window
  if ti and win then win:select(ti) end
  -- Flash the row so the eye lands on the control that was searched for.
  task.delay(0.28, function()
    if not L.live() or not e.frame or not e.frame.Parent then return end
    local was = e.frame.BackgroundColor3
    M.set(e.frame, "BackgroundColor3", T.c.accentDeep)
    M.to(e.frame, "BackgroundColor3", was, "slow")
  end)
  if e.run then L.try("palette.run", e.run) end
end

function P.build()
  if gui and gui.Parent then return end
  gui = mk("ScreenGui", {
    Name = "LumenPalette", ResetOnSpawn = false, IgnoreGuiInset = true,
    ZIndexBehavior = Enum.ZIndexBehavior.Sibling, DisplayOrder = 40,
  })
  gui.Parent = L.host()
  L.own(gui)
  mk("UIScale", { Scale = L.autoScale(), Parent = gui })

  local scrim = mk("Frame", {
    Size = UDim2.fromScale(1, 1), BackgroundColor3 = T.c.scrim,
    BackgroundTransparency = 1, BorderSizePixel = 0, Parent = gui,
  })
  local hit = mk("TextButton", {
    Size = UDim2.fromScale(1, 1), BackgroundTransparency = 1, Text = "",
    AutoButtonColor = false, Parent = scrim,
  })
  hit.Activated:Connect(function() P.hide() end)
  P.scrim = scrim

  -- CanvasGroup, not Frame: a Frame has no single opacity clock, so only
  -- GroupTransparency fades plate, outline and text together.
  root = mk("CanvasGroup", {
    AnchorPoint = Vector2.new(0.5, 0),
    Position = UDim2.new(0.5, 0, 0.18, 0),
    Size = UDim2.fromOffset(520, 60),
    BackgroundColor3 = T.c.overlay, BorderSizePixel = 0,
    GroupTransparency = 0,
    Parent = gui,
  })
  L.corner(T.r.lg, root)
  L.stroke(T.c.lineStrong, 1, 0.25, root)
  A.shadow(nil, { Parent = gui, spread = 30, alpha = 0.4, ZIndex = 0 })
  P.root = root

  A.Icon.search(root, 16, T.c.textMute).Position = UDim2.fromOffset(18, 18)

  box = mk("TextBox", {
    Position = UDim2.fromOffset(44, 0), Size = UDim2.new(1, -60, 0, 52),
    BackgroundTransparency = 1, Text = "",
    PlaceholderText = "Search controls...",
    PlaceholderColor3 = T.c.textOff, TextColor3 = T.c.text,
    Font = T.font.body, TextSize = 15,
    TextXAlignment = Enum.TextXAlignment.Left, ClearTextOnFocus = false,
    Parent = root,
  })
  P.box = box

  listFrame = mk("Frame", {
    Position = UDim2.fromOffset(8, 54), Size = UDim2.new(1, -16, 0, 0),
    BackgroundTransparency = 1, Parent = root,
  })
  L.list(2, nil, listFrame)

  rows = {}
  for i = 1, 8 do
    local bg = mk("Frame", {
      Size = UDim2.new(1, 0, 0, 34), BackgroundColor3 = T.c.accent,
      BackgroundTransparency = 1, BorderSizePixel = 0, Visible = false,
      LayoutOrder = i, Parent = listFrame,
    })
    L.corner(T.r.sm, bg)
    local nm = A.text({
      Text = "", font = T.font.medium, size = T.size.body, colour = T.c.textDim,
      Position = UDim2.fromOffset(10, 0), Size = UDim2.new(1, -120, 1, 0),
      truncate = true, Parent = bg,
    })
    local hn = A.text({
      Text = "", font = T.font.mono, size = T.size.tiny, colour = T.c.textOff,
      align = Enum.TextXAlignment.Right, AnchorPoint = Vector2.new(1, 0.5),
      Position = UDim2.new(1, -10, 0.5, 0), Size = UDim2.fromOffset(100, 14),
      Parent = bg,
    })
    local btn = mk("TextButton", {
      Size = UDim2.fromScale(1, 1), BackgroundTransparency = 1, Text = "",
      AutoButtonColor = false, ZIndex = 3, Parent = bg,
    })
    btn.Activated:Connect(function() activate(i) end)
    btn.MouseEnter:Connect(function() sel = i paintSel() end)
    rows[i] = { bg = bg, name = nm, hint = hn }
  end

  box:GetPropertyChangedSignal("Text"):Connect(function()
    local list = P.search(box.Text)
    render(list)
    local h = 54 + math.min(#list, 8) * 36 + (#list > 0 and 8 or 0)
    M.to(root, "Size", UDim2.fromOffset(520, h), "base")
    M.to(listFrame, "Size", UDim2.new(1, -16, 0, math.min(#list, 8) * 36), "base")
  end)
end

function P.show()
  P.build()
  P.open = true
  gui.Enabled = true
  box.Text = ""
  render(P.search(""), true)
  M.set(root, "Position", UDim2.new(0.5, 0, 0.18, -14))
  A.groupSet(root, 1)
  M.set(P.scrim, "BackgroundTransparency", 1)
  M.to(P.scrim, "BackgroundTransparency", 0.42, "base")
  M.to(root, "Position", UDim2.new(0.5, 0, 0.18, 0), "slow")
  -- Fade is shorter than the slide, so the panel is legible before it lands.
  A.groupTo(root, 0, "base")
  task.defer(function() if P.open then box:CaptureFocus() end end)
end

function P.hide()
  if not P.open then return end
  P.open = false
  if P._seq then P._seq:cancel() P._seq = nil end
  M.to(P.scrim, "BackgroundTransparency", 1, "fast")
  M.to(root, "Position", UDim2.new(0.5, 0, 0.18, -10), "fast")
  A.groupTo(root, 1, "fast")
  pcall(function() box:ReleaseFocus() end)
  task.delay(0.3, function()
    if gui and not P.open then gui.Enabled = false end
  end)
end

function P.toggle() if P.open then P.hide() else P.show() end end

-- ---------------------------------------------------------------- keys
L.hold(L.UIS.InputBegan:Connect(function(i, typing)
  if not L.live() then return end
  local ctrl = L.UIS:IsKeyDown(Enum.KeyCode.LeftControl)
             or L.UIS:IsKeyDown(Enum.KeyCode.RightControl)
  if i.KeyCode == Enum.KeyCode.K and ctrl then P.toggle() return end
  if not P.open then return end
  -- These run while the TextBox has focus, so they cannot be gated on `typing`.
  if i.KeyCode == Enum.KeyCode.Escape then P.hide()
  elseif i.KeyCode == Enum.KeyCode.Down then
    if results and #results > 0 then sel = math.min(sel + 1, math.min(#results, 8)) paintSel() end
  elseif i.KeyCode == Enum.KeyCode.Up then
    if results and #results > 0 then sel = math.max(sel - 1, 1) paintSel() end
  elseif i.KeyCode == Enum.KeyCode.Return then
    activate(sel)
  end
  local _ = typing
end))

end
do -- ==== lm_14_universal.lua ====
-- LUMEN :: UNIVERSAL
-- Features that work in any place: movement, fly, noclip, ESP, teleport.
--
-- Every feature stores what it WANTS and re-applies on respawn, so a toggle
-- cannot silently turn itself off when you die.
--
-- A watchdog re-checks each switched-on feature against the game once a second.
-- A switch here means the game agrees, not just that you clicked it.

local L = getgenv().LUMEN
local T, M, A, C = L.T, L.Motion, L.A, L.C

local U = {}
L.Universal = U

U.want = {
  walkSpeed = nil, jumpPower = nil,
  fly = false, noclip = false, infJump = false, antiAfk = false,
}
U.FLY_SPEED = 60

local Players, UIS, RS = L.Players, L.UIS, L.RunService
local LP = L.LP

local function char() return LP.Character end
local function hum()
  local c = char()
  return c and c:FindFirstChildOfClass("Humanoid")
end
local function root()
  local c = char()
  return c and c:FindFirstChild("HumanoidRootPart")
end

-- ---------------------------------------------------------------- movement

function U.applyWalk()
  local h = hum()
  if not h then return false, "no character" end
  if not U.want.walkSpeed then return true end
  local ok = pcall(function() h.WalkSpeed = U.want.walkSpeed end)
  return ok, ok and nil or "humanoid rejected WalkSpeed"
end

function U.applyJump()
  local h = hum()
  if not h then return false, "no character" end
  if not U.want.jumpPower then return true end
  local ok = pcall(function()
    -- UseJumpPower is the modern switch; without setting it, JumpPower is
    -- ignored in favour of JumpHeight and the slider appears to do nothing
    h.UseJumpPower = true
    h.JumpPower = U.want.jumpPower
  end)
  return ok, ok and nil or "humanoid rejected JumpPower"
end

-- ---------------------------------------------------------------- fly

local flyConn, flyVel, flyGyro
local function combatPhysicsActive()
  local combat = L.Combat
  if not combat then return false end
  if combat.physicsBusy then
    local ok, busy = pcall(combat.physicsBusy)
    if ok then return busy and true or false end
  end
  return combat.flinging or combat.activeCleanup ~= nil
      or (combat.want and combat.want.touchFling) or false
end

local function stopFly()
  if flyConn then flyConn:Disconnect() flyConn = nil end
  if flyVel then flyVel:Destroy() flyVel = nil end
  if flyGyro then flyGyro:Destroy() flyGyro = nil end
end

local function startFly()
  stopFly()
  if combatPhysicsActive() then
    return false, "finish the active fling before enabling Fly"
  end
  local r, h = root(), hum()
  if not r or not h then return false, "no character" end

  -- BodyVelocity rather than writing CFrame directly: the humanoid keeps
  -- simulating, so animations, collisions and the camera all behave normally
  -- instead of the character reading as teleporting every frame.
  flyVel = Instance.new("BodyVelocity")
  flyVel.MaxForce = Vector3.new(1, 1, 1) * 1e5
  flyVel.Velocity = Vector3.zero
  flyVel.Parent = r
  L.own(flyVel)

  flyGyro = Instance.new("BodyGyro")
  flyGyro.MaxTorque = Vector3.new(1, 1, 1) * 1e5
  flyGyro.P = 9e4
  flyGyro.CFrame = r.CFrame
  flyGyro.Parent = r
  L.own(flyGyro)

  flyConn = L.hold(RS.RenderStepped:Connect(function()
    if not L.live() or not U.want.fly then return end
    local rr = root()
    local cam = workspace.CurrentCamera
    if not rr or not cam or not flyVel then return end
    local dir = Vector3.zero
    if UIS:IsKeyDown(Enum.KeyCode.W) then dir = dir + cam.CFrame.LookVector end
    if UIS:IsKeyDown(Enum.KeyCode.S) then dir = dir - cam.CFrame.LookVector end
    if UIS:IsKeyDown(Enum.KeyCode.A) then dir = dir - cam.CFrame.RightVector end
    if UIS:IsKeyDown(Enum.KeyCode.D) then dir = dir + cam.CFrame.RightVector end
    if UIS:IsKeyDown(Enum.KeyCode.Space) then dir = dir + Vector3.yAxis end
    if UIS:IsKeyDown(Enum.KeyCode.LeftShift) then dir = dir - Vector3.yAxis end
    if dir.Magnitude > 0.05 then dir = dir.Unit * U.FLY_SPEED else dir = Vector3.zero end
    flyVel.Velocity = dir
    flyGyro.CFrame = cam.CFrame
  end))
  return true
end

function U.setFly(on)
  on = on and true or false
  if on and combatPhysicsActive() then
    return false, "finish the active fling before enabling Fly"
  end
  U.want.fly = on
  if U.want.fly then return startFly() end
  stopFly()
  return true
end

-- ---------------------------------------------------------------- noclip

local noclipConn, collideSnap
local noclipSuspensions = {}

local function restoreNoclipCollision()
  if collideSnap then
    for part, was in pairs(collideSnap) do
      if part.Parent then pcall(function() part.CanCollide = was end) end
    end
    collideSnap = nil
  end
end

function U.setNoclip(on)
  on = on and true or false
  if on and U.want.noclip then U.setNoclip(false) end
  U.want.noclip = on
  if noclipConn then noclipConn:Disconnect() noclipConn = nil end

  -- Turning it on with no character is not a failure -- the loop applies to
  -- whatever character exists whenever one does -- but it IS worth saying,
  -- because otherwise the switch flips and visibly nothing happens.
  if U.want.noclip and not char() then
    L.note("noclip", "armed, waiting for a character")
  end

  if not U.want.noclip or next(noclipSuspensions) then
    -- restore exactly what each part had. A blanket CanCollide = true breaks a
    -- stock R6, where only Head and Torso ever collided.
    restoreNoclipCollision()
    return true
  end

  collideSnap = {}
  noclipConn = L.hold(RS.Stepped:Connect(function()
    if not L.live() or not U.want.noclip then return end
    local c = char()
    if not c then return end
    for _, d in ipairs(c:GetDescendants()) do
      if d:IsA("BasePart") and d.CanCollide then
        if collideSnap[d] == nil then collideSnap[d] = true end
        d.CanCollide = false
      end
    end
  end))
  return true
end

-- Physics features suspend noclip by token instead of racing its Stepped
-- writer. User intent stays ON and is re-armed only after the final holder
-- releases, so nested features cannot resume each other prematurely.
function U.suspendNoclip(token)
  token = tostring(token or "anonymous")
  if noclipSuspensions[token] then return false end
  noclipSuspensions[token] = true
  if noclipConn then noclipConn:Disconnect() noclipConn = nil end
  restoreNoclipCollision()
  return true
end

function U.resumeNoclip(token)
  token = tostring(token or "anonymous")
  if not noclipSuspensions[token] then return false end
  noclipSuspensions[token] = nil
  if not next(noclipSuspensions) and U.want.noclip then U.setNoclip(true) end
  return true
end

L.cleanup(function()
  U.want.fly = false
  stopFly()
  U.want.noclip = false
  if noclipConn then pcall(function() noclipConn:Disconnect() end) noclipConn = nil end
  restoreNoclipCollision()
  table.clear(noclipSuspensions)
  U.want.unlockCamera = false
  if U.setUnlockCamera then pcall(U.setUnlockCamera, false) end
end, 0)

-- ---------------------------------------------------------------- inf jump

function U.setInfJump(on)
  U.want.infJump = on and true or false
  if U._infConn then return true end
  U._infConn = L.hold(UIS.JumpRequest:Connect(function()
    if not L.live() or not U.want.infJump then return end
    local h = hum()
    if h then pcall(function() h:ChangeState(Enum.HumanoidStateType.Jumping) end) end
  end))
  return true
end

-- ---------------------------------------------------------------- anti-afk
--
-- Roblox disconnects you after ~20 minutes without input. LocalPlayer.Idled
-- fires just before that, and a VirtualUser click resets the timer.
--
-- Right button, not left: ClickButton1 would fire whatever the game has bound to
-- a primary click -- swinging a tool, placing a block -- every twenty minutes,
-- unattended. Button 2 is inert in almost every game.

function U.setAntiAfk(on)
  U.want.antiAfk = on and true or false
  if not U.want.antiAfk then
    if U._afkConn then U._afkConn:Disconnect() U._afkConn = nil end
    return true
  end
  if U._afkConn then return true end

  local ok, vu = pcall(function() return game:GetService("VirtualUser") end)
  if not ok or not vu then
    U.want.antiAfk = false
    return false, "this client has no VirtualUser"
  end

  U._afkConn = L.hold(LP.Idled:Connect(function()
    if not L.live() or not U.want.antiAfk then return end
    L.try("antiafk", function()
      vu:CaptureController()
      vu:ClickButton2(Vector2.new())
    end)
    U.afkSaves = (U.afkSaves or 0) + 1
    L.note("anti-afk", "idle kick avoided (" .. U.afkSaves .. " this session)")
  end))
  return true
end

-- ---------------------------------------------------------------- esp

-- UserId -> true for players the ESP should skip. Keyed by id rather than by the
-- Player instance so it survives them respawning, leaving and rejoining.
U.espHidden = U.espHidden or {}

function U.setEspHidden(userId, hidden)
  U.espHidden[userId] = hidden and true or nil
  return U.espHidden[userId] == true
end

-- U.setEsp IS GONE, AND THAT IS THE FIX. It built its own Highlight and
-- BillboardGui per player under L.host() while lm_30's engine drew its own, and
-- nothing checked the other: an armed hub gave every player two AlwaysOnTop
-- fills at different alphas and two nametags at different anchors, and the
-- panic path turned off the copy the user was not looking at. Both switches
-- drive L.Esp.set now. U.espHidden above stays -- it is the per-player mute the
-- side panel writes, and lm_30 reads it in collect().

-- ---------------------------------------------------------------- teleport

-- ---------------------------------------------------------------- camera

-- UNLOCK THE CAMERA
--
-- Games narrow the zoom range to force a viewpoint -- first person only, or a
-- fixed shoulder distance. Min and Max are Player properties, not camera ones,
-- and they are re-applied by the game's own scripts whenever the character
-- respawns, so this is stored as an intent and re-asserted rather than set once.
--
-- CameraMode is the other half: LockFirstPerson pins you regardless of the zoom
-- range, so widening the range alone does nothing in the games that use it.
U.want.unlockCamera = false

local camPrev
function U.setUnlockCamera(on)
  U.want.unlockCamera = on and true or false
  if on then
    camPrev = camPrev or {
      min = LP.CameraMinZoomDistance,
      max = LP.CameraMaxZoomDistance,
      mode = LP.CameraMode,
    }
    local ok = pcall(function()
      LP.CameraMinZoomDistance = 0.5
      LP.CameraMaxZoomDistance = 2048
      LP.CameraMode = Enum.CameraMode.Classic
    end)
    if not ok then return false, "the game refused the camera change" end
  elseif camPrev then
    pcall(function()
      LP.CameraMinZoomDistance = camPrev.min
      LP.CameraMaxZoomDistance = camPrev.max
      LP.CameraMode = camPrev.mode
    end)
    camPrev = nil
  end
  return true
end

-- Re-asserted on respawn, which is where the game gets its chance to put the
-- restriction back.
L.hold(LP.CharacterAdded:Connect(function(c)
  if not U.want.unlockCamera then return end
  task.wait(0.4)
  if L.live() and LP.Character == c and U.want.unlockCamera then
    pcall(function()
      LP.CameraMinZoomDistance = 0.5
      LP.CameraMaxZoomDistance = 2048
      LP.CameraMode = Enum.CameraMode.Classic
    end)
  end
end))

-- ---------------------------------------------------------------- respawn

-- Health = 0 rather than BreakJoints. Both kill the character, but the health
-- route goes through Humanoid.Died, which is the signal the game's own respawn
-- logic listens for; BreakJoints dismembers the model without firing it, and in
-- games that handle their own respawning that leaves you dead permanently.
function U.resetCharacter()
  local h = hum()
  if not h then return false, "no character" end
  local ok = pcall(function() h.Health = 0 end)
  if not ok then return false, "the game refused it" end
  return true
end

function U.teleportTo(name)
  local target
  for _, p in ipairs(Players:GetPlayers()) do
    if p ~= LP and string.lower(p.Name):sub(1, #name) == string.lower(name) then
      target = p break
    end
  end
  -- A NAME THAT MATCHES NOBODY IS A USER ERROR, NOT A FAULT. It gets said out
  -- loud and recorded nowhere -- putting it in the fault list would mean a typo
  -- lights the same indicator as a crash.
  if not target then return false, "no player matching " .. name, "user" end
  local r, tr = root(), target.Character and target.Character:FindFirstChild("HumanoidRootPart")
  if not r or not tr then return false, "no character", "refused" end
  r.CFrame = tr.CFrame * CFrame.new(0, 0, 3)
  return true, "teleported to " .. target.Name
end

-- ---------------------------------------------------------------- watchdog
--
-- THE CHECK EVERY HUB SKIPS. Setting a property is not the same as the property
-- being set. A game that writes WalkSpeed back on a loop leaves the slider
-- reading 120 while the character walks at 16, and the interface never admits
local strikes = {}

local SETTER = {
  ["fly"] = function(v) return U.setFly(v) end,
  ["esp"] = function(v) return L.Esp.set(v) end,
  ["noclip"] = function(v) return U.setNoclip(v) end,
  ["infinite jump"] = function(v) return U.setInfJump(v) end,
  ["anti-afk"] = function(v) return U.setAntiAfk(v) end,
}

-- Toggle handles, so a feature that dies can move its own switch. Filled by
-- U.build; absent when the Universal tab has not been built yet.
U.ui = {}

function U.forceOff(key, msg)
  strikes[key] = 0
  L.uncontest(key)
  if SETTER[key] then pcall(SETTER[key], false) end
  local t = U.ui[key]
  if t then t:set(false, true) end        -- silent: the feature is already off
  L.log("refused", key, "switched off automatically")
  if L.Toast then L.Toast.warn("Turned off: " .. key, msg) end
end

local function judge(key, ok, why)
  if ok then
    strikes[key] = 0
    L.uncontest(key)
    return true
  end
  strikes[key] = (strikes[key] or 0) + 1
  if strikes[key] >= 2 then L.contest(key, why) end
  return false
end

local function near(a, b) return a and b and math.abs(a - b) < 0.5 end

function U.verify()
  local h = hum()

  -- movement: the game owns these properties outright and may write them back
  if U.want.walkSpeed and h then
    local held = judge("walk speed", near(h.WalkSpeed, U.want.walkSpeed),
      string.format("game holds %d, you asked for %d",
        math.floor(h.WalkSpeed + 0.5), math.floor(U.want.walkSpeed + 0.5)))
    if not held then U.applyWalk() end     -- desired-state: keep asking
  end

  if U.want.jumpPower and h then
    local held = judge("jump power", near(h.JumpPower, U.want.jumpPower),
      string.format("game holds %d, you asked for %d",
        math.floor(h.JumpPower + 0.5), math.floor(U.want.jumpPower + 0.5)))
    if not held then U.applyJump() end
  end

  -- fly rides on two BodyMovers, which are Instances the game can simply
  -- delete. Put them back once; a feature that will not restart is OFF, and the
  -- switch has to follow it rather than keep advertising it.
  if U.want.fly then
    local alive = flyVel and flyVel.Parent and flyGyro and flyGyro.Parent
                  and flyConn and flyConn.Connected
    if alive then
      judge("fly", true)
    else
      local ok, why = startFly()
      judge("fly", ok and true or false, why or "movers removed and would not restart")
      if (strikes["fly"] or 0) >= 5 then
        U.forceOff("fly", "Fly stopped and would not restart.")
      end
    end
  end

  if L.Esp and L.Esp.want.on then
    judge("esp", L.Esp.alive(), "draw loop was disconnected")
  end

  if U.want.noclip then
    local intentionallySuspended = next(noclipSuspensions) ~= nil
    judge("noclip", intentionallySuspended
          or ((noclipConn and noclipConn.Connected) and true or false),
      intentionallySuspended and "intentionally suspended by a physics feature"
        or "collision loop was disconnected")
  end

  if U.want.infJump then
    judge("infinite jump", (U._infConn and U._infConn.Connected) and true or false,
      "jump listener was disconnected")
  end

  if U.want.antiAfk then
    judge("anti-afk", (U._afkConn and U._afkConn.Connected) and true or false,
      "idle listener was disconnected")
  end

  return L.health()
end

-- One timer for every feature rather than one per feature: the check is a few
-- property reads, and six sleeping coroutines cost more than the work does.
task.spawn(function()
  while L.live() do
    task.wait(1)
    if not L.live() then break end
    L.try("universal.verify", U.verify)
  end
end)

-- ---------------------------------------------------------------- respawn

-- The reason every feature above stores intent instead of just acting.
L.hold(LP.CharacterAdded:Connect(function(c)
  if not L.live() then return end
  c:WaitForChild("HumanoidRootPart", 8)
  task.wait(0.3)
  if not L.live() or LP.Character ~= c then return end
  L.try("universal.respawn", function()
    U.applyWalk()
    U.applyJump()
    if U.want.fly then startFly() end
    -- The Stepped writer follows LP.Character immediately and may already have
    -- captured/disabled collision on this new body. Re-arm transactionally so
    -- those exact snapshots are restored before a fresh epoch is opened.
    if U.want.noclip then U.setNoclip(true) end
  end)
end))

-- ---------------------------------------------------------------- ui

function U.build(page, movePage)
  C.ctx("universal")
  -- These rows render on the Movement tab and keep their universal.movement.*
  -- ids. Moving the BUILD and not the id is what keeps a hundred tuned values
  -- off the orphan list.
  local homePage = page
  page = movePage or page
  C.section(page, "movement", "getting around")

  local h = hum()
  local Cfg = L.Cfg

  -- REMEMBERED, DISPLAYED, NOT APPLIED -- and the slider agrees with the legs.
  --
  -- This used to restore AND apply, with a comment defending it: a slider
  -- reading 145 over a character walking at 16 is a lie, so tell the character
  -- too. The reasoning was right and the conclusion was backwards. Executing
  -- the hub should leave you exactly as it found you, and this was a second
  -- auto-apply path hiding behind the feature store -- it does not go through
  -- bindPersist, so fixing the config policy did not touch it. Measured after
  -- that fix: every switch correctly off, character still at WalkSpeed 10000.
  --
  -- The lie is avoided the other way round now. The handle paints the speed the
  -- character ACTUALLY has, the tuned value stays on disk, and one nudge of the
  -- slider brings it back -- which is a click, against spawning at ten thousand
  -- studs a second in front of everyone.
  local savedWalk = Cfg and tonumber(Cfg.data.walkSpeed)
  local savedJump = Cfg and tonumber(Cfg.data.jumpPower)
  if savedWalk then
    L.note("walk speed", math.floor(savedWalk) .. " saved for this place, not applied")
  end
  if savedJump then
    L.note("jump power", math.floor(savedJump) .. " saved for this place, not applied")
  end

  U.ui["walk speed"] = C.slider(page, {
    text = "Walk speed", desc = "Default is 16 -- saved per game",
    min = 0, max = 10000, step = 1, curve = "log",
    -- The character's real speed, not the saved one. See the note above.
    default = (h and h.WalkSpeed) or 16,
    callback = function(v)
      U.want.walkSpeed = v
      local ok, why = U.applyWalk()
      if not ok then L.log("refused", "walk speed", why) end
      if Cfg then Cfg.set("walkSpeed", v) end
    end,
  })
  U.ui["jump power"] = C.slider(page, {
    text = "Jump power", desc = "Default is 50 -- saved per game",
    min = 0, max = 10000, step = 1, curve = "log",
    default = (h and h.JumpPower) or 50,
    callback = function(v)
      U.want.jumpPower = v
      local ok, why = U.applyJump()
      if not ok then L.log("refused", "jump power", why) end
      if Cfg then Cfg.set("jumpPower", v) end
    end,
  })

  -- EVERY TOGGLE RETURNS ITS SETTER'S ANSWER. That single `return` is what lets
  -- the switch put itself back when the feature refuses -- without it the
  -- control paints ON and the callback's failure goes nowhere. The handles are
  -- kept so the watchdog can move a switch whose feature died later.
  U.ui["fly"] = C.toggle(page, {
    text = "Fly", desc = "WASD to move, Space up, Shift down",
    default = false, callback = function(v) return U.setFly(v) end,
  })
  U.ui["noclip"] = C.toggle(page, {
    text = "Noclip", desc = "Walk through parts",
    default = false, callback = function(v) return U.setNoclip(v) end,
  })
  U.ui["infinite jump"] = C.toggle(page, {
    text = "Infinite jump", desc = "Jump again in mid-air",
    default = false, callback = function(v) return U.setInfJump(v) end,
  })

  -- SAFE TO RE-ARM, and one of the few things in Cfg.ARM_SAFE. Anti-AFK changes
  -- nothing a game can observe about your character -- it only stops Roblox's
  -- own idle disconnect -- so rejoining with it on is not a surprise, not a
  -- tell, and not something you have to notice was left running.
  U.ui["anti-afk"] = C.toggle(page, {
    text = "Anti-AFK", desc = "Blocks the 20 minute idle disconnect",
    default = L.Cfg and L.Cfg.data.antiAfk == true,
    callback = function(v)
      local ok, why = U.setAntiAfk(v)
      if L.Cfg then L.Cfg.set("antiAfk", v) end
      return ok, why
    end,
  })
  if L.Cfg and L.Cfg.data.antiAfk == true then
    U.setAntiAfk(true)
    L.note("anti-afk", "restored on")
  end

  page = homePage
  C.section(page, "camera")
  -- ONE SETTING, ONE STORE. This carried a second persistence path beside the
  -- one every control already gets from bindPersist: it read a default from
  -- Cfg.data.unlockCamera, wrote back with Cfg.set("unlockCamera", v), and
  -- re-applied on load from the same key.
  --
  -- None of it worked. "unlockCamera" was never declared in Cfg.SCHEMA, so the
  -- write was rejected every time -- surfaced by the W11 pass as
  -- "cfg.key x2 unknown config key" -- the read was always nil, and the
  -- manual restore therefore never fired once.
  --
  -- Same shape as the motion profile bug, with the opposite symptom: there the
  -- two stores fought and the wrong one won, here the second was simply dead.
  -- bindPersist already handles default, save and restore, so this is deletion
  -- rather than repair.
  U.ui["unlock camera"] = C.toggle(page, {
    text = "Unlock camera", desc = "Removes a game's zoom limits and first-person lock",
    default = false,
    callback = function(v) return U.setUnlockCamera(v) end,
  })
  C.actions(page, {
    { text = "Reset character", callback = function()
        local ok, why = U.resetCharacter()
        if ok then L.Toast.info("Respawning")
        else L.Toast.warn("Could not reset", tostring(why)) end
      end },
  })

  C.section(page, "players")
  -- The same switch as Visuals > ESP, not a second one: Cfg.RENAMED points this
  -- id at that one, so there is a single stored boolean, and bindSwitch keeps
  -- the two faces of it in step.
  U.ui["esp"] = C.toggle(page, {
    text = "Player ESP", desc = "Highlight and name every player",
    default = false,
    callback = function(v)
      local ok, why = L.Esp.set(v)
      if not ok and why then L.Toast.warn("Player ESP", tostring(why)) end
      return ok
    end,
  })
  L.Esp.bindSwitch(U.ui["esp"])

  -- ---- who to teleport to ----------------------------------------------
  --
  -- A LIST OF NAMES IS NOT A LIST OF PEOPLE. Thirty usernames in a mono column
  -- all look alike, and picking the wrong one costs you a teleport across the
  -- map. Each row now carries the player's actual headshot and how far away they
  -- are, which are the two facts you are really choosing between.
  local names = {}
  for _, p in ipairs(Players:GetPlayers()) do
    if p ~= LP then names[#names + 1] = p.Name end
  end

  if #names > 0 then
    local function rootOf(name)
      local p = Players:FindFirstChild(name)
      local ch = p and p.Character
      return ch and ch:FindFirstChild("HumanoidRootPart")
    end

    local function distanceTo(name)
      local mine = LP.Character and LP.Character:FindFirstChild("HumanoidRootPart")
      local theirs = rootOf(name)
      if not (mine and theirs) then return nil end
      return (mine.Position - theirs.Position).Magnitude
    end

    -- The panel is the primary way in now: it stays open while you work, has
    -- room for faces and distances, and does not cover the page you were on.
    -- The dropdown is kept for the keyboard path and for anyone who just wants
    -- the nearest name without a second window appearing.
    C.actions(page, {
      { text = "Open player panel", primary = true, callback = function()
          if not (L.Side and L.Side.toggle) then
            L.Toast.warn("Unavailable", "The side panel did not load.")
            return
          end
          local ok, why = L.Side.toggle()
          if ok == false and why then L.Toast.warn("Player panel", why) end
        end },
      { text = "Refresh list", callback = function()
          if L.Side and L.Side.open then
            local n = L.Side.refresh()
            L.Toast.ok("Refreshed", (n or 0) .. " other players here.")
          else
            L.Toast.info("Not open", "Open the player panel first.")
          end
        end },
    })

    U.tpDropdown = C.dropdown(page, {
      text = "Teleport to", items = names, default = names[1],
      rowHeight = 44, textInset = 46, maxHeight = 300,
      decorate = function(row, name, i)
        -- headshot. Thumbnails are fetched over the network, so this yields --
        -- doing it inline would stall the menu opening by however long Roblox
        -- takes to answer, once per player.
        local av = L.mk("ImageLabel", {
          AnchorPoint = Vector2.new(0, 0.5),
          Position = UDim2.fromOffset(6, 21),
          Size = UDim2.fromOffset(30, 30),
          BackgroundColor3 = T.c.raised, BackgroundTransparency = 0.25,
          BorderSizePixel = 0, ImageTransparency = 1,
          ZIndex = 33, Name = "Head", Parent = row,
        })
        L.corner(999, av)
        task.spawn(function()
          local p = Players:FindFirstChild(name)
          if not p then return end
          local ok, url = pcall(function()
            return Players:GetUserThumbnailAsync(p.UserId,
              Enum.ThumbnailType.HeadShot, Enum.ThumbnailSize.Size48x48)
          end)
          if ok and url and av.Parent then
            av.Image = url
            M.to(av, "ImageTransparency", 0, "base")
          end
        end)

        local d = distanceTo(name)
        local far = A.text({
          Text = d and string.format("%d studs", math.floor(d + 0.5)) or "not spawned",
          font = T.font.mono, size = T.size.micro,
          colour = d and T.c.textOff or T.c.warn,
          align = Enum.TextXAlignment.Right, AnchorPoint = Vector2.new(1, 0.5),
          Position = UDim2.new(1, -12, 0.5, 0), Size = UDim2.fromOffset(90, 14),
          ZIndex = 33, Parent = row,
        })
        -- kept live while the menu is open: people move, and a distance that was
        -- true when the list opened is a lie ten seconds later
        task.spawn(function()
          while far.Parent and row.Parent do
            local nd = distanceTo(name)
            far.Text = nd and string.format("%d studs", math.floor(nd + 0.5)) or "not spawned"
            far.TextColor3 = nd and T.c.textOff or T.c.warn
            task.wait(0.5)
          end
        end)
      end,
      callback = function(v)
        local ok, why, kind = U.teleportTo(v)
        if ok then
          L.Toast.ok("Teleport", why)
          L.note("teleport", why)
        else
          L.Toast.warn("Teleport", tostring(why))
          -- a typo is the user's, not the hub's: say it, do not record it
          if kind ~= "user" then L.log("refused", "teleport", why) end
        end
      end,
    })
  end

  -- ---- shortcuts -------------------------------------------------------
  --
  -- Bound features work with the window closed, which is the whole point: fly is
  -- something you reach for mid-movement, not something you open a menu for.
  --
  -- Each bind flips the feature AND the switch, so the interface never disagrees
  -- with the world just because you used a key instead of a click.
  C.section(page, "shortcuts")

  local BINDABLE = {
    { "fly",           "Fly" },
    { "noclip",        "Noclip" },
    { "infinite jump", "Infinite jump" },
    { "esp",           "Player ESP" },
    { "anti-afk",      "Anti-AFK" },
  }

  if L.Binds then
    for _, e in ipairs(BINDABLE) do
      local key, label = e[1], e[2]
      L.Binds.register(key, label,
        function(state)
          local ok, why = SETTER[key] and SETTER[key](state)
          -- the switch follows the key, silently: the setter has already run
          if U.ui[key] then U.ui[key]:set(state, true) end
          return ok, why
        end,
        function()
          local t = U.ui[key]
          return t and t:get() or false
        end)
    end
    L.Binds.load()

    for _, e in ipairs(BINDABLE) do
      local key, label = e[1], e[2]
      C.keybind(page, {
        text = label, desc = "Press to toggle without opening the hub",
        default = L.Binds.keyFor(key),
        callback = function(k)
          local clash = k and L.Binds.conflict(key, k)
          L.Binds.set(key, k)
          if clash then
            -- both would fire on one press; say which rather than let the user
            -- discover it by watching two features toggle at once
            L.Toast.warn("Key already used",
              string.format("%s is also bound to %s.", k.Name, clash))
          elseif k then
            L.Toast.ok(label, "Bound to " .. k.Name .. ".")
          end
        end,
      })
    end
  end

  C.section(page, "reset")
  C.actions(page, {
    { text = "Restore defaults", callback = function()
        U.want.walkSpeed, U.want.jumpPower = 16, 50
        U.applyWalk() U.applyJump()
        U.setFly(false) U.setNoclip(false) U.setInfJump(false) L.Esp.set(false)
        U.setAntiAfk(false)
        if L.Cfg then L.Cfg.set("antiAfk", false) end
        -- the switches have to follow, or "restore defaults" leaves four
        -- controls reading ON with nothing behind them -- the exact lie this
        -- wave exists to remove. Silent, because the setters already ran.
        for _, key in ipairs({ "fly", "noclip", "infinite jump", "esp", "anti-afk" }) do
          if U.ui[key] then U.ui[key]:set(false, true) end
          L.uncontest(key)
        end
        L.uncontest("walk speed") L.uncontest("jump power")
        -- and forget the saved values, or a reload brings 145 straight back and
        -- "restore defaults" turns out to have lasted exactly one session
        if L.Cfg then
          L.Cfg.clearPlace("walkSpeed")
          L.Cfg.clearPlace("jumpPower")
        end
        if U.ui["walk speed"] then U.ui["walk speed"]:set(16, true) end
        if U.ui["jump power"] then U.ui["jump power"]:set(50, true) end
        L.note("reset", "movement and visuals restored, saved values cleared")
        L.Toast.ok("Reset", "Movement and visuals restored, and no longer saved for this place.")
      end },
  })
end

end
do -- ==== lm_30_esp.lua ====
-- LUMEN :: ESP
-- Seeing through walls, as a set of layers you combine rather than a mode you
-- pick.
--
-- WHY LAYERS AND NOT MODES. Every hub ships "Box ESP", "Chams", "Tracers" as
-- alternatives, so wanting an outline AND a nametag AND a distance readout
-- means picking whichever single one you can least do without. They are not
-- alternatives -- they answer different questions. An outline says WHERE, a
-- tracer says WHICH WAY, a nametag says WHO, a health bar says WHETHER IT IS
-- WORTH IT. Each is a switch, and they stack.
--
-- WHAT IT DRAWS ON. Highlights are real engine objects and cost nothing to keep
-- accurate, so they carry the through-wall fill. Everything with a position on
-- screen -- boxes, tracers, arrows -- is GUI updated per frame from
-- WorldToViewportPoint. Text that nobody reads sixty times a second (distance,
-- health) updates at 12 Hz, because it is indistinguishable and costs a fifth
-- as much.
--
-- THE BUDGET IS THE POINT. A hub that adds four milliseconds a frame to look at
-- a server is not a feature, it is a tax. Everything here runs inside a measured
-- millisecond budget and simply does fewer targets per frame when it cannot
-- afford them all -- so a busy server degrades to "the nearest twenty are
-- accurate" instead of dropping the frame rate.

local L = getgenv().LUMEN
local T, M, A, C = L.T, L.Motion, L.A, L.C
local mk = L.mk

local Players = game:GetService("Players")
local RS = game:GetService("RunService")
local LP = L.LP

local E = {}
L.Esp = E

E.want = { on = false }

E.cfg = {
  -- layers
  highlight = true,
  box       = false,
  skeleton  = false,
  tracer    = false,
  nametag   = true,
  distance  = true,
  health    = true,
  arrow     = false,

  -- what to look at
  players      = true,
  npcs         = false,
  vehicles     = false,
  loot         = false,
  containers   = false,

  teamColour   = true,     -- friend/enemy rather than one flat colour
  maxDistance  = 1500,
  budgetMs     = 1.2,      -- per frame, for DRAWING only; the scan is amortised
  textRate     = 12,       -- Hz for distance and health
  rescanHz     = 4,        -- how often the target list is rebuilt
  hotCount     = 8,        -- nearest N redrawn every frame, the rest rotate
  highlightCap = 24,       -- the engine renders ~31; leave the game its share
  fillAlpha    = 0.62,
  tracerFrom   = "Bottom", -- Bottom | Centre | Top
}

E.TRACER_FROM = { "Bottom", "Centre", "Top" }

-- names that mark an object worth seeing, kept as data so adding a category is
-- a line rather than a branch
local LOOT_WORDS      = { "ammo", "loot", "drop", "pickup", "coin", "cash", "gem" }
local CONTAINER_WORDS = { "chest", "crate", "box", "barrel", "safe", "stash", "locker" }

local function nameHas(inst, words)
  local n = inst.Name:lower()
  for _, w in ipairs(words) do if n:find(w, 1, true) then return true end end
  return false
end

-- ---------------------------------------------------------------- surface

local gui, hlFolder, conns, entries, lastText, budgetUsed
conns, entries = {}, {}

local function teardown()
  for _, c in ipairs(conns) do pcall(function() c:Disconnect() end) end
  conns = {}
  for _, e in pairs(entries) do
    if e.hl then pcall(function() e.hl:Destroy() end) end
    if e.frame then pcall(function() e.frame:Destroy() end) end
  end
  entries = {}
  if gui then pcall(function() gui:Destroy() end) gui = nil end
  if hlFolder then pcall(function() hlFolder:Destroy() end) hlFolder = nil end
end

local function ensure()
  if gui and gui.Parent then return true end
  local host = L.host()
  if not host then return false end
  gui = mk("ScreenGui", {
    Name = "LumenESP", ResetOnSpawn = false, IgnoreGuiInset = true,
    ZIndexBehavior = Enum.ZIndexBehavior.Sibling, DisplayOrder = 5,
  })
  gui.Parent = host
  L.own(gui)
  hlFolder = Instance.new("Folder")
  hlFolder.Name = "LumenESPHL"
  hlFolder.Parent = host
  L.own(hlFolder)
  return true
end

-- ---------------------------------------------------------------- colour

-- A GAME MODULE MAY OVERRIDE THE COLOUR.
--
-- Team colour is the right default for a generic hub, and it is the wrong
-- answer in a game where the meaningful division is not the team list. In
-- Murder Mystery 2 everyone is on the same team and the only fact worth reading
-- off a highlight is who is holding the knife.
--
-- Rather than teach the ESP about every game, it takes one hook: a function
-- given a player and returning a colour, or nil to fall through to the normal
-- rules. Registered by whichever module owns the current place.
local colourHook

--- `fn(player) -> Color3?, string?` — colour and an optional short tag.
function E.setColourHook(fn)
  colourHook = (type(fn) == "function") and fn or nil
end

function E.colourTagFor(player)
  if not colourHook then return nil end
  local ok, _, tag = pcall(colourHook, player)
  return ok and tag or nil
end

local function colourFor(kind, player)
  if kind == "player" and player and colourHook then
    -- Wrapped: a module's hook running every frame for every player is exactly
    -- where a bad index would turn the whole overlay off.
    local ok, col = pcall(colourHook, player)
    if ok and typeof(col) == "Color3" then return col end
  end
  if kind == "player" and player and E.cfg.teamColour then
    local mine = LP.Team
    if mine and player.Team == mine then return T.c.ok end
    return T.c.bad
  end
  if kind == "npc" then return T.c.warn end
  if kind == "vehicle" then return T.c.accent end
  if kind == "loot" then return T.c.ok end
  if kind == "container" then return T.c.warn end
  return T.c.accent
end

-- ---------------------------------------------------------------- entries

local function makeEntry(key, adornee, kind, player)
  local e = { key = key, adornee = adornee, kind = kind, player = player }
  local col = colourFor(kind, player)

  e.hl = Instance.new("Highlight")
  e.hl.Name = "LumenHL"
  e.hl.Adornee = adornee
  e.hl.FillColor = col
  e.hl.OutlineColor = col
  e.hl.FillTransparency = E.cfg.fillAlpha
  e.hl.OutlineTransparency = 0.1
  e.hl.DepthMode = Enum.HighlightDepthMode.AlwaysOnTop
  e.hl.Enabled = false
  -- unparented until it earns a capped slot: an unused Highlight still counts
  -- against the engine limit, so existing is what costs, not being enabled
  e.hl.Parent = nil

  -- one frame holds every 2D layer for this target, so showing or hiding the
  -- whole entry is a single property rather than a walk
  e.frame = mk("Frame", {
    BackgroundTransparency = 1, Size = UDim2.fromOffset(0, 0),
    Visible = false, Name = "E", Parent = gui,
  })

  -- box: four corner brackets, which read as a box without drawing one that
  -- fights every busy background it sits on
  e.corners = {}
  for i = 1, 8 do
    e.corners[i] = mk("Frame", {
      BackgroundColor3 = col, BorderSizePixel = 0,
      BackgroundTransparency = 1, ZIndex = 2, Parent = e.frame,
    })
  end

  -- skeleton: a fixed pool, parented to the same frame the box uses. Parenting
  -- here rather than to the gui is what makes the rest of the system work
  -- unchanged -- hideEntry's one Visible flag hides the bones too, and
  -- dropEntry's one Destroy takes them with it. A separate pool on the gui
  -- would need its own line in both, and would eventually be missed from one.
  e.bones = {}
  for i = 1, 16 do
    e.bones[i] = mk("Frame", {
      BackgroundColor3 = col, BorderSizePixel = 0,
      AnchorPoint = Vector2.new(0.5, 0.5),
      BackgroundTransparency = 1, ZIndex = 3, Parent = e.frame,
    })
  end

  e.tracer = mk("Frame", {
    BackgroundColor3 = col, BorderSizePixel = 0, AnchorPoint = Vector2.new(0.5, 1),
    BackgroundTransparency = 1, Size = UDim2.fromOffset(1, 0), ZIndex = 1,
    Parent = gui,
  })

  e.name = A.text({
    Text = "", font = T.font.medium, size = T.size.micro, colour = col,
    align = Enum.TextXAlignment.Center, AnchorPoint = Vector2.new(0.5, 1),
    Size = UDim2.fromOffset(200, 14), ZIndex = 4, Parent = e.frame,
  })
  e.name.TextStrokeTransparency = 0.4
  e.info = A.text({
    Text = "", font = T.font.mono, size = T.size.nano, colour = T.c.textDim,
    align = Enum.TextXAlignment.Center, AnchorPoint = Vector2.new(0.5, 0),
    Size = UDim2.fromOffset(200, 12), ZIndex = 4, Parent = e.frame,
  })
  e.info.TextStrokeTransparency = 0.5

  -- health: a thin bar beside the box, which is where the eye already is
  e.hpBack = mk("Frame", {
    BackgroundColor3 = Color3.new(0, 0, 0), BackgroundTransparency = 0.35,
    BorderSizePixel = 0, ZIndex = 2, Parent = e.frame,
  })
  e.hpFill = mk("Frame", {
    BackgroundColor3 = T.c.ok, BorderSizePixel = 0, ZIndex = 3,
    AnchorPoint = Vector2.new(0, 1), Parent = e.hpBack,
  })

  -- off-screen arrow, so a target behind you is still locatable
  e.arrow = A.text({
    Text = "^", font = T.font.strong, size = T.size.label, colour = col,
    align = Enum.TextXAlignment.Center, AnchorPoint = Vector2.new(0.5, 0.5),
    Size = UDim2.fromOffset(22, 22), Visible = false, ZIndex = 4, Parent = gui,
  })

  entries[key] = e
  return e
end

local function hideEntry(e)
  e.frame.Visible = false
  e.tracer.BackgroundTransparency = 1
  e.arrow.Visible = false
  if e.hl then e.hl.Enabled = false e.hl.Parent = nil end
end

local function dropEntry(key)
  local e = entries[key]
  if not e then return end
  pcall(function() e.hl:Destroy() end)
  pcall(function() e.frame:Destroy() end)
  pcall(function() e.tracer:Destroy() end)
  pcall(function() e.arrow:Destroy() end)
  entries[key] = nil
end

-- ---------------------------------------------------------------- skeleton

-- R15 first because it is what almost every game ships now; R6 is the fallback
-- and is checked by the absence of UpperTorso rather than by asking the
-- Humanoid, which is a property read per frame per player for a fact that
-- cannot change while the character lives.
local R15_BONES = {
  { "Head", "UpperTorso" }, { "UpperTorso", "LowerTorso" },
  { "UpperTorso", "LeftUpperArm" }, { "LeftUpperArm", "LeftLowerArm" },
  { "LeftLowerArm", "LeftHand" },
  { "UpperTorso", "RightUpperArm" }, { "RightUpperArm", "RightLowerArm" },
  { "RightLowerArm", "RightHand" },
  { "LowerTorso", "LeftUpperLeg" }, { "LeftUpperLeg", "LeftLowerLeg" },
  { "LeftLowerLeg", "LeftFoot" },
  { "LowerTorso", "RightUpperLeg" }, { "RightUpperLeg", "RightLowerLeg" },
  { "RightLowerLeg", "RightFoot" },
}
local R6_BONES = {
  { "Head", "Torso" },
  { "Torso", "Left Arm" }, { "Torso", "Right Arm" },
  { "Torso", "Left Leg" }, { "Torso", "Right Leg" },
}

-- A LINE IS A ROTATED RECTANGLE.
--
-- A ScreenGui has no 2D line, so each bone is a one-pixel-tall Frame as long as
-- the gap between the two joints, turned to the angle between them. The anchor
-- sits at the centre so the rotation happens about the bone's midpoint; anchored
-- at a corner the same rotation swings the far end away from the joint it is
-- supposed to meet, and the figure comes apart at every limb.
--
-- Offsets are relative to the entry frame, not the screen, because that is
-- where these live.
local function drawBones(e, char, cam, ox, oy, col)
  local set = char:FindFirstChild("UpperTorso") and R15_BONES or R6_BONES
  local n = 0
  for _, b in ipairs(set) do
    local a, c = char:FindFirstChild(b[1]), char:FindFirstChild(b[2])
    if a and c then
      local pa, va = cam:WorldToViewportPoint(a.Position)
      local pb, vb = cam:WorldToViewportPoint(c.Position)
      -- both ends must be in front of the camera; one behind projects to a
      -- mirrored point and draws a bone straight across the screen
      if va and vb and pa.Z > 0 and pb.Z > 0 then
        n = n + 1
        local f = e.bones[n]
        if f then
          local dx, dy = pb.X - pa.X, pb.Y - pa.Y
          f.BackgroundTransparency = 0.1
          f.BackgroundColor3 = col
          f.Position = UDim2.fromOffset((pa.X + pb.X) / 2 - ox, (pa.Y + pb.Y) / 2 - oy)
          f.Size = UDim2.fromOffset(math.max(math.sqrt(dx * dx + dy * dy), 1), 1)
          f.Rotation = math.deg(math.atan2(dy, dx))
        end
      end
    end
  end
  for i = n + 1, #e.bones do e.bones[i].BackgroundTransparency = 1 end
end

-- ---------------------------------------------------------------- targets

-- Everything worth drawing this pass, cheapest categories first.
local function collect()
  local out = {}
  if E.cfg.players then
    for _, p in ipairs(Players:GetPlayers()) do
      if p ~= LP and p.Character then
        local hum = p.Character:FindFirstChildOfClass("Humanoid")
        local root = p.Character:FindFirstChild("HumanoidRootPart")
        if hum and root and hum.Health > 0
           and not (L.Universal and L.Universal.espHidden
                    and L.Universal.espHidden[p.UserId]) then
          out[#out + 1] = { key = "p" .. p.UserId, adornee = p.Character,
                            root = root, kind = "player", player = p, hum = hum }
        end
      end
    end
  end

  local wantWorld = E.cfg.npcs or E.cfg.vehicles or E.cfg.loot or E.cfg.containers
  if wantWorld then
    for _, m in ipairs(workspace:GetChildren()) do
      if m:IsA("Model") and m ~= LP.Character then
        local root = m:FindFirstChild("HumanoidRootPart") or m.PrimaryPart
        local hum = m:FindFirstChildOfClass("Humanoid")
        if E.cfg.npcs and hum and root and hum.Health > 0
           and not Players:GetPlayerFromCharacter(m) then
          out[#out + 1] = { key = "n" .. m:GetDebugId(), adornee = m, root = root,
                            kind = "npc", hum = hum }
        elseif E.cfg.vehicles and root and m:FindFirstChildWhichIsA("VehicleSeat", true) then
          out[#out + 1] = { key = "v" .. m:GetDebugId(), adornee = m, root = root,
                            kind = "vehicle" }
        elseif E.cfg.containers and root and nameHas(m, CONTAINER_WORDS) then
          out[#out + 1] = { key = "c" .. m:GetDebugId(), adornee = m, root = root,
                            kind = "container" }
        end
      elseif E.cfg.loot and m:IsA("Tool") then
        local h = m:FindFirstChild("Handle")
        if h then
          out[#out + 1] = { key = "l" .. m:GetDebugId(), adornee = m, root = h,
                            kind = "loot" }
        end
      elseif E.cfg.loot and m:IsA("BasePart") and nameHas(m, LOOT_WORDS) then
        out[#out + 1] = { key = "l" .. m:GetDebugId(), adornee = m, root = m,
                          kind = "loot" }
      end
    end
  end
  return out
end

-- THE SCAN IS NOT A PER-FRAME COST. collect() calls GetDebugId and a recursive
-- VehicleSeat search on every top-level child -- measured 16us per child, so a
-- world with two thousand of them spends a 1.2ms budget before one target is
-- drawn. It runs on its own clock; events only mark it dirty, so a game that
-- reparents parts every frame cannot drag it back to per-frame.
local scanned, scanAt, scanDirty = {}, 0, true

local function markDirty() scanDirty = true end

local function targets()
  local now = os.clock()
  local period = 1 / math.max(E.cfg.rescanHz or 4, 0.5)
  if now - scanAt >= (scanDirty and period * 0.5 or period) then
    local t = os.clock()
    scanned, scanAt, scanDirty = collect(), now, false

    -- the engine's Highlight cap is shared with the game and cannot be read
    -- back, so count the ones we did not make and stay off them
    local foreign = 0
    for _, p in ipairs(Players:GetPlayers()) do
      local ch = p.Character
      if ch and ch:FindFirstChildOfClass("Highlight") then foreign = foreign + 1 end
    end
    E.hlBudget = math.clamp((E.cfg.highlightCap or 24) - foreign, 4, 31)
    E.scanMs = math.floor((os.clock() - t) * 100000) / 100
  end
  return scanned
end

-- ---------------------------------------------------------------- draw

local textAcc = 0
local cursor = 1     -- rotation position in the far tail; survives the frame

local function espDraw(dt)
  if not (L.live() and E.want.on and gui and gui.Parent) then return end
  local cam = workspace.CurrentCamera
  local myRoot = LP.Character and LP.Character:FindFirstChild("HumanoidRootPart")
  if not (cam and myRoot) then return end

  -- outside the measured window on purpose: charging the scan to this frame's
  -- budget is what made a busy world draw nothing while still costing a frame
  local list = targets()

  local t0 = os.clock()
  local budget = (E.cfg.budgetMs or 1.2) / 1000
  textAcc = textAcc + dt
  local doText = textAcc >= (1 / math.max(E.cfg.textRate or 12, 1))
  if doText then textAcc = 0 end

  local vp = cam.ViewportSize
  local present = {}
  local reach = (E.cfg.maxDistance or 1500)
  if L.Guard then reach = reach * L.Guard.quality() end

  -- nearest first, so the budget is spent on what matters when it runs out
  for _, t in ipairs(list) do
    -- the list is up to a rescan period old, so a target in it can be gone
    t.dead = not (t.root and t.root.Parent) or (t.hum and t.hum.Health <= 0) or false
    t.dist = t.dead and math.huge or (t.root.Position - myRoot.Position).Magnitude
    if not t.dead and t.dist <= reach then present[t.key] = true end
  end
  table.sort(list, function(a, b) return a.dist < b.dist end)

  -- ROTATE, DO NOT STARVE. Nearest-first with a plain break means everything
  -- past what the budget affords is never drawn once. The nearest hotCount are
  -- what the eye is on and are redrawn every frame; the rest are visited from a
  -- cursor that survives the frame, so every target is reached within
  -- ceil(tail / (afforded - hot)) frames instead of never.
  local n = #list
  local hot = math.clamp(E.cfg.hotCount or 8, 0, n)
  local tailN = n - hot
  if tailN <= 0 or cursor > tailN then cursor = 1 end
  local order = table.create(n)
  for i = 1, hot do order[i] = i end
  for i = 1, tailN do order[hot + i] = hot + ((cursor - 2 + i) % tailN) + 1 end
  local hlCap = E.hlBudget or E.cfg.highlightCap or 24
  local reached = 0

  for oi = 1, n do
    if os.clock() - t0 > budget then break end     -- out of time: stop cleanly
    reached = oi
    local rank = order[oi]                         -- 1 is the nearest target
    local t = list[rank]
    if not t.dead and t.dist <= reach then
      local e = entries[t.key]
      if e and e.adornee ~= t.adornee then
        dropEntry(t.key)
        e = nil
      end
      e = e or makeEntry(t.key, t.adornee, t.kind, t.player)
      local col = colourFor(t.kind, t.player)

      -- HIGHLIGHTS ARE ENGINE-CAPPED at roughly 31 rendered instances and fail
      -- silently past it, so on a full server the fill layer just stops. Only
      -- the nearest hlCap targets hold a parented Highlight; the rest detach
      -- (Parent = nil is the only reliable way to stop counting) and get the
      -- bracket box instead, which is visible rather than invisibly "on".
      local hlOk = E.cfg.highlight and rank <= hlCap
      e.hl.Enabled = hlOk
      if hlOk then
        if e.hl.Parent ~= hlFolder then e.hl.Parent = hlFolder end
        e.hl.Adornee = t.adornee
        e.hl.FillColor, e.hl.OutlineColor = col, col
        e.hl.FillTransparency = E.cfg.fillAlpha
      elseif e.hl.Parent then
        e.hl.Parent = nil
      end

      local pos, onScreen = cam:WorldToViewportPoint(t.root.Position)
      if onScreen and pos.Z > 0 then
        e.arrow.Visible = false
        -- a body is about five studs; scale the box by depth so it hugs
        local h = math.clamp(1600 / math.max(pos.Z, 1), 14, 400)
        local w = h * 0.55
        e.frame.Visible = true
        e.frame.Position = UDim2.fromOffset(pos.X - w / 2, pos.Y - h / 2)
        e.frame.Size = UDim2.fromOffset(w, h)

        -- corner brackets
        local armX, armY, th = w * 0.28, h * 0.22, 2
        local show = (E.cfg.box or (E.cfg.highlight and not hlOk)) and 0 or 1
        local seg = {
          { 0, 0, armX, th }, { 0, 0, th, armY },
          { w - armX, 0, armX, th }, { w - th, 0, th, armY },
          { 0, h - th, armX, th }, { 0, h - armY, th, armY },
          { w - armX, h - th, armX, th }, { w - th, h - armY, th, armY },
        }
        for i, s in ipairs(seg) do
          local c = e.corners[i]
          c.BackgroundTransparency = show
          c.BackgroundColor3 = col
          c.Position = UDim2.fromOffset(s[1], s[2])
          c.Size = UDim2.fromOffset(s[3], s[4])
        end

        -- skeleton
        if E.cfg.skeleton then
          drawBones(e, t.adornee, cam, pos.X - w / 2, pos.Y - h / 2, col)
        elseif e.bones[1].BackgroundTransparency < 1 then
          for i = 1, #e.bones do e.bones[i].BackgroundTransparency = 1 end
        end

        -- tracer
        if E.cfg.tracer then
          local from = E.cfg.tracerFrom
          local ox, oy = vp.X / 2, vp.Y
          if from == "Centre" then oy = vp.Y / 2 elseif from == "Top" then oy = 0 end
          local dx, dy = pos.X - ox, pos.Y - oy
          local len = math.sqrt(dx * dx + dy * dy)
          e.tracer.BackgroundTransparency = 0.25
          e.tracer.BackgroundColor3 = col
          e.tracer.Position = UDim2.fromOffset(ox, oy)
          e.tracer.Size = UDim2.fromOffset(1, len)
          e.tracer.Rotation = math.deg(math.atan2(dy, dx)) - 90
        else
          e.tracer.BackgroundTransparency = 1
        end

        -- nametag / distance / health
        e.name.Visible = E.cfg.nametag
        if E.cfg.nametag then
          e.name.TextColor3 = col
          e.name.Position = UDim2.fromOffset(w / 2, -2)
          if doText or e.name.Text == "" then
            local shown = t.player
              and ((t.player.DisplayName ~= "" and t.player.DisplayName) or t.player.Name)
              or t.adornee.Name
            local tag = t.player and E.colourTagFor(t.player) or nil
            e.name.Text = tag and tag ~= "" and ("[" .. tag .. "] " .. shown) or shown
          end
        end
        e.info.Visible = E.cfg.distance
        if E.cfg.distance then
          e.info.Position = UDim2.fromOffset(w / 2, h + 2)
          if doText then e.info.Text = math.floor(t.dist) .. " studs" end
        end

        local wantHp = E.cfg.health and t.hum ~= nil
        e.hpBack.Visible = wantHp
        if wantHp then
          e.hpBack.Position = UDim2.fromOffset(-6, 0)
          e.hpBack.Size = UDim2.fromOffset(3, h)
          if doText then
            local frac = math.clamp(t.hum.Health / math.max(t.hum.MaxHealth, 1), 0, 1)
            e.hpFill.Position = UDim2.fromScale(0, 1)
            e.hpFill.Size = UDim2.fromScale(1, frac)
            e.hpFill.BackgroundColor3 = (frac > 0.5 and T.c.ok)
              or (frac > 0.25 and T.c.warn) or T.c.bad
          end
        end
      else
        -- behind us: an edge arrow is the only useful thing to say
        e.frame.Visible = false
        e.tracer.BackgroundTransparency = 1
        if E.cfg.arrow then
          local dir = (t.root.Position - cam.CFrame.Position)
          local rel = cam.CFrame:VectorToObjectSpace(dir)
          local ang = math.atan2(rel.X, -rel.Z)
          local rad = math.min(vp.X, vp.Y) * 0.32
          e.arrow.Visible = true
          e.arrow.TextColor3 = col
          e.arrow.Rotation = math.deg(ang)
          e.arrow.Position = UDim2.fromOffset(
            vp.X / 2 + math.sin(ang) * rad, vp.Y / 2 - math.cos(ang) * rad)
        else
          e.arrow.Visible = false
        end
      end
    end
  end
  if tailN > 0 then
    cursor = ((cursor - 1 + math.max(reached - hot, 0)) % tailN) + 1
  end

  -- Budget exhaustion leaves valid existing entries at their last good frame;
  -- hiding every unprocessed entry made dense servers flicker in rotating sets.
  -- Only targets truly gone/out of range are hidden or released.
  for key, e in pairs(entries) do
    if not present[key] then
      if e.adornee and e.adornee.Parent then hideEntry(e) else dropEntry(key) end
    end
  end
  budgetUsed = (budgetUsed or 0) * 0.9 + (os.clock() - t0) * 1000 * 0.1
  E.frameMs = math.floor((budgetUsed or 0) * 100) / 100
end

-- ---------------------------------------------------------------- api

-- ONE ENGINE, TWO FACES. Universal and Visuals each show an ESP switch and they
-- are the same setting now, so whichever one moves the other has to follow --
-- otherwise the tab you are not looking at lies about what is running.
E.switches = E.switches or {}

function E.bindSwitch(api)
  if api then E.switches[#E.switches + 1] = api end
  return api
end

local function mirror(v)
  for i = #E.switches, 1, -1 do
    local api = E.switches[i]
    if api.frame and api.frame.Parent then
      -- silent, and a no-op on the switch that called us: set() returns early
      -- when the state already matches, so there is no loop back into here
      L.try("esp.mirror", api.set, api, v, true)
    else
      table.remove(E.switches, i)     -- a rebuild left this widget behind
    end
  end
end

-- The watchdog's question, which it used to ask of the other engine's folder.
function E.alive()
  if not E.want.on then return false end
  for _, c in ipairs(conns) do
    if typeof(c) == "RBXScriptConnection" and c.Connected then return true end
  end
  return false
end

function E.set(on)
  E.want.on = on and true or false
  mirror(E.want.on)
  teardown()
  if not E.want.on then return true end
  if not ensure() then
    E.want.on = false
    return false, "nowhere to draw"
  end
  scanned, scanAt, scanDirty = {}, 0, true
  conns[#conns + 1] = L.hold(Players.PlayerAdded:Connect(markDirty))
  conns[#conns + 1] = L.hold(Players.PlayerRemoving:Connect(markDirty))
  conns[#conns + 1] = L.hold(workspace.ChildAdded:Connect(markDirty))
  conns[#conns + 1] = L.hold(workspace.ChildRemoved:Connect(markDirty))
  conns[#conns + 1] = L.hold(RS.RenderStepped:Connect(espDraw))
  return true
end

function E.refresh()
  if E.want.on then E.set(false) E.set(true) end
end

function E.stats()
  local n = 0
  for _ in pairs(entries) do n = n + 1 end
  return { tracked = n, frameMs = E.frameMs or 0, scanMs = E.scanMs or 0,
           hlCap = E.hlBudget or E.cfg.highlightCap or 24 }
end

end
do -- ==== lm_23_visuals.lua ====
-- LUMEN :: VISUALS
-- Lighting, visibility and performance.
--
-- Every feature here edits something the game owns, so each records what it found
-- before touching it. Restores are stored per property, not as one snapshot of a
-- service: two features touch Lighting, and a blanket restore would undo the other.

local L = getgenv().LUMEN
local T, M, A, C = L.T, L.Motion, L.A, L.C

local Lighting = game:GetService("Lighting")
local RS = game:GetService("RunService")

local V = {}
L.Visuals = V

V.want = { fullbright = false, xray = false, noFog = false }
V.saved = {}          -- "Service.Property" -> original value

-- ---------------------------------------------------------------- restore

local function remember(obj, prop, key)
  key = key or (obj.Name .. "." .. prop)
  if V.saved[key] == nil then
    local ok, v = pcall(function() return obj[prop] end)
    if ok then V.saved[key] = v end
  end
end

local function restore(obj, prop, key)
  key = key or (obj.Name .. "." .. prop)
  local v = V.saved[key]
  if v == nil then return end
  pcall(function() obj[prop] = v end)
  V.saved[key] = nil
end

-- ---------------------------------------------------------------- fullbright

-- Three methods because they fail in different games: a game that drives Ambient
-- itself every frame fights the flood, and ColorCorrection wins there.
V.brightMethods = { "Ambient flood", "ColorCorrection", "Both" }
V.brightMethod = "Ambient flood"

local ccBright

local function ambientOn(on)
  if on then
    remember(Lighting, "Ambient")
    remember(Lighting, "OutdoorAmbient")
    remember(Lighting, "Brightness")
    remember(Lighting, "GlobalShadows")
    remember(Lighting, "FogEnd")
    Lighting.Ambient = Color3.fromRGB(178, 178, 178)
    Lighting.OutdoorAmbient = Color3.fromRGB(178, 178, 178)
    Lighting.Brightness = 2
    Lighting.GlobalShadows = false
    Lighting.FogEnd = 1e6
  else
    restore(Lighting, "Ambient")
    restore(Lighting, "OutdoorAmbient")
    restore(Lighting, "Brightness")
    restore(Lighting, "GlobalShadows")
    restore(Lighting, "FogEnd")
  end
end

local function ccOn(on)
  if on then
    if ccBright and ccBright.Parent then return end
    ccBright = Instance.new("ColorCorrectionEffect")
    ccBright.Name = "LumenBright"
    ccBright.Brightness = 0.18
    ccBright.Contrast = 0.06
    ccBright.Parent = Lighting
    L.own(ccBright)
  else
    if ccBright then pcall(function() ccBright:Destroy() end) ccBright = nil end
  end
end

function V.setFullbright(on)
  V.want.fullbright = on and true or false
  local m = V.brightMethod
  ambientOn(V.want.fullbright and (m == "Ambient flood" or m == "Both"))
  ccOn(V.want.fullbright and (m == "ColorCorrection" or m == "Both"))
  return true
end

function V.setBrightMethod(name)
  V.brightMethod = name
  if V.want.fullbright then
    -- re-apply so switching method does not leave the old one running
    ambientOn(false) ccOn(false)
    V.setFullbright(true)
  end
  return true, name
end

-- ---------------------------------------------------------------- fog

function V.setNoFog(on)
  V.want.noFog = on and true or false
  if on then
    remember(Lighting, "FogEnd", "fog.FogEnd")
    remember(Lighting, "FogStart", "fog.FogStart")
    Lighting.FogEnd, Lighting.FogStart = 1e6, 1e6
    for _, d in ipairs(Lighting:GetChildren()) do
      if d:IsA("Atmosphere") then
        V._atmo = V._atmo or {}
        V._atmo[d] = d.Density
        d.Density = 0
      end
    end
  else
    restore(Lighting, "FogEnd", "fog.FogEnd")
    restore(Lighting, "FogStart", "fog.FogStart")
    for d, density in pairs(V._atmo or {}) do
      if d.Parent then pcall(function() d.Density = density end) end
    end
    V._atmo = nil
  end
  return true
end

-- ---------------------------------------------------------------- x-ray

-- LocalTransparencyModifier, not Transparency: it is client-only, so the server
-- never sees the write. Transparency replicates in some games and gets you kicked.
V.xrayLevel = 0.65

local xrayConn

function V.setXray(on)
  V.want.xray = on and true or false
  if xrayConn then xrayConn:Disconnect() xrayConn = nil end

  local function paint(v)
    for _, d in ipairs(workspace:GetDescendants()) do
      if d:IsA("BasePart") and not d:IsDescendantOf(L.LP.Character or workspace) then
        pcall(function() d.LocalTransparencyModifier = v end)
      end
    end
  end

  if not V.want.xray then
    paint(0)
    return true
  end

  -- Re-applied on a slow loop: parts stream in and out, and a one-shot pass
  -- leaves everything that loaded afterwards solid.
  local acc = 0
  xrayConn = L.hold(RS.Heartbeat:Connect(function(dt)
    if not L.live() or not V.want.xray then return end
    acc = acc + dt
    if acc < 1.5 then return end
    acc = 0
    paint(V.xrayLevel)
  end))
  paint(V.xrayLevel)
  return true
end

-- ---------------------------------------------------------------- time / fov

function V.setClock(v)
  remember(Lighting, "ClockTime", "clock.ClockTime")
  Lighting.ClockTime = math.clamp(v, 0, 24)
  return true, string.format("%.1f", Lighting.ClockTime)
end

function V.resetClock()
  restore(Lighting, "ClockTime", "clock.ClockTime")
  return true
end

function V.setFov(v)
  local cam = workspace.CurrentCamera
  if not cam then return false, "no camera" end
  if V.saved["cam.FieldOfView"] == nil then V.saved["cam.FieldOfView"] = cam.FieldOfView end
  cam.FieldOfView = math.clamp(v, 1, 120)
  return true, tostring(math.floor(cam.FieldOfView))
end

function V.resetFov()
  local cam = workspace.CurrentCamera
  if cam and V.saved["cam.FieldOfView"] then
    cam.FieldOfView = V.saved["cam.FieldOfView"]
    V.saved["cam.FieldOfView"] = nil
  end
  return true
end

-- ---------------------------------------------------------------- fps boost
--
-- Quality settings and lighting come back exactly. Stripped textures and meshes
-- do not, so the level that strips them says so up front.
V.LEVELS = { "Off", "Light", "Medium", "Nuclear" }
V.level = "Off"

local boosted = {}          -- instance -> { prop = original }

local function stash(inst, prop)
  boosted[inst] = boosted[inst] or {}
  if boosted[inst][prop] == nil then
    local ok, v = pcall(function() return inst[prop] end)
    if ok then boosted[inst][prop] = v end
  end
end

local function lightweightLighting(on)
  if on then
    remember(Lighting, "GlobalShadows", "fps.GlobalShadows")
    remember(Lighting, "Technology", "fps.Technology")
    Lighting.GlobalShadows = false
    for _, d in ipairs(Lighting:GetChildren()) do
      if d:IsA("PostEffect") or d:IsA("Atmosphere") then
        stash(d, "Enabled")
        pcall(function() d.Enabled = false end)
      end
    end
  else
    restore(Lighting, "GlobalShadows", "fps.GlobalShadows")
  end
end

local function stripParts(level)
  local n = 0
  for _, d in ipairs(workspace:GetDescendants()) do
    if d:IsA("BasePart") then
      stash(d, "Material") stash(d, "Reflectance") stash(d, "CastShadow")
      pcall(function()
        d.Material = Enum.Material.SmoothPlastic
        d.Reflectance = 0
        d.CastShadow = false
      end)
      n = n + 1
    elseif d:IsA("ParticleEmitter") or d:IsA("Trail") or d:IsA("Smoke")
        or d:IsA("Fire") or d:IsA("Sparkles") or d:IsA("Beam") then
      stash(d, "Enabled")
      pcall(function() d.Enabled = false end)
      n = n + 1
    elseif level == "Nuclear" and (d:IsA("Decal") or d:IsA("Texture")) then
      stash(d, "Transparency")
      pcall(function() d.Transparency = 1 end)
      n = n + 1
    end
  end
  return n
end

function V.setFps(level)
  local prev = V.level
  V.level = level or "Off"

  -- always unwind first, so switching between levels is not cumulative
  for inst, props in pairs(boosted) do
    if inst.Parent then
      for prop, v in pairs(props) do pcall(function() inst[prop] = v end) end
    end
  end
  boosted = {}
  lightweightLighting(false)

  if V.level == "Off" then
    pcall(function() settings().Rendering.QualityLevel = Enum.QualityLevel.Automatic end)
    return true, "restored"
  end

  local q = (V.level == "Light" and 8) or (V.level == "Medium" and 4) or 1
  pcall(function()
    settings().Rendering.QualityLevel = Enum.QualityLevel.Level01
    settings().Rendering.MeshPartDetailLevel = Enum.MeshPartDetailLevel.Level04
  end)
  pcall(function() workspace.StreamingEnabled = workspace.StreamingEnabled end)

  lightweightLighting(true)
  local touched = 0
  if V.level ~= "Light" then touched = stripParts(V.level) end

  L.note("fps", string.format("%s -- %d objects simplified", V.level, touched))
  return true, string.format("%s (%d objects)", V.level, touched)
end

-- ---------------------------------------------------------------- ui

function V.build(page)
  C.ctx("visuals")
  C.section(page, "light")

  C.toggle(page, {
    text = "Fullbright", desc = "Floods light, drops shadows",
    default = false, callback = function(v) return V.setFullbright(v) end,
  })
  C.dropdown(page, {
    text = "Fullbright method", desc = "Switch if one is fought",
    items = V.brightMethods, default = V.brightMethod,
    callback = function(v) V.setBrightMethod(v) end,
  })
  C.toggle(page, {
    text = "Strip fog", desc = "Clears fog and atmosphere density",
    default = false, callback = function(v) return V.setNoFog(v) end,
  })
  C.slider(page, {
    text = "Time of day", desc = "Lighting.ClockTime",
    min = 0, max = 24, step = 0.5, default = 14,
    callback = function(v) V.setClock(v) end,
  })

  C.section(page, "sight")

  C.toggle(page, {
    text = "X-ray", desc = "See-through world, client side",
    default = false, callback = function(v) return V.setXray(v) end,
  })
  C.slider(page, {
    text = "X-ray strength", desc = "How transparent the world goes",
    when = "visuals.sight.X-ray",
    min = 0, max = 1, step = 0.01, default = 0.65,
    callback = function(v)
      V.xrayLevel = v
      if V.want.xray then V.setXray(true) end
    end,
  })
  C.slider(page, {
    text = "Field of view", desc = "70 is the Roblox default",
    min = 1, max = 120, step = 1, default = 70,
    callback = function(v) V.setFov(v) end,
  })

  C.section(page, "esp")

  L.Esp.bindSwitch(C.toggle(page, {
    text = "ESP", desc = "See through walls. Every layer below stacks",
    default = false,
    callback = function(v)
      local ok, why = L.Esp.set(v)
      if not ok and why then L.Toast.warn("ESP", why) end
      return ok
    end,
  }))
  local function layer(name, desc, key)
    C.toggle(page, {
      text = name, desc = desc, default = L.Esp.cfg[key],
      callback = function(v) L.Esp.cfg[key] = v end,
    })
  end
  layer("Outline",   "Through-wall fill on the whole body",        "highlight")
  layer("Box",       "Corner brackets that hug them at any range", "box")
  layer("Skeleton",  "Bone lines through the body, R15 and R6",    "skeleton")
  layer("Tracer",    "A line from the screen edge to them",        "tracer")
  layer("Nametag",   "Who it is",                                  "nametag")
  layer("Distance",  "How far, in studs",                          "distance")
  layer("Health bar","A bar beside the box, colour by fraction",   "health")
  layer("Off-screen arrow", "Points at targets behind you",        "arrow")

  C.dropdown(page, {
    text = "Tracer origin", desc = "Where the line starts",
    items = L.Esp.TRACER_FROM, default = L.Esp.cfg.tracerFrom,
    callback = function(v) L.Esp.cfg.tracerFrom = v end,
  })

  C.section(page, "esp targets")
  local function cat(name, desc, key)
    C.toggle(page, {
      text = name, desc = desc, default = L.Esp.cfg[key],
      callback = function(v) L.Esp.cfg[key] = v end,
    })
  end
  cat("Players",    "Other players",                       "players")
  cat("NPCs",       "Living things that are not players",  "npcs")
  cat("Vehicles",   "Anything with a seat you can drive",  "vehicles")
  cat("Loot",       "Tools and pickups on the ground",     "loot")
  cat("Containers", "Chests, crates, barrels, lockers",    "containers")

  C.toggle(page, {
    text = "Team colours", desc = "Green for your team, red for everyone else",
    default = L.Esp.cfg.teamColour,
    callback = function(v) L.Esp.cfg.teamColour = v end,
  })
  C.slider(page, {
    text = "ESP range", desc = "Studs past which it stops drawing",
    min = 1, max = 500000, step = 1, curve = "log", default = L.Esp.cfg.maxDistance,
    callback = function(v) L.Esp.cfg.maxDistance = v end,
  })
  C.slider(page, {
    text = "Frame budget", desc = "Milliseconds a frame it may ever spend",
    min = 0.05, max = 33, step = 0.05, default = L.Esp.cfg.budgetMs,
    callback = function(v) L.Esp.cfg.budgetMs = v end,
  })
  C.slider(page, {
    text = "Fill strength", desc = "0 is solid, 1 is outline only",
    min = 0, max = 1, step = 0.02, default = L.Esp.cfg.fillAlpha,
    callback = function(v) L.Esp.cfg.fillAlpha = v end,
  })

  C.section(page, "performance")

  C.segmented(page, {
    text = "FPS booster", desc = "How much detail to give up",
    items = V.LEVELS, default = "Off",
    callback = function(v)
      local ok, why = V.setFps(v)
      if ok then L.Toast.ok("FPS booster", why) end
    end,
  })
  C.actions(page, {
    { text = "Restore everything", primary = true, callback = function()
        V.setFps("Off")
        V.setFullbright(false)
        V.setNoFog(false)
        V.setXray(false)
        V.resetClock()
        V.resetFov()
        L.Toast.ok("Restored", "Lighting, visibility and quality put back.")
      end },
  })
end

end
do -- ==== lm_24_combat.lua ====
-- LUMEN :: COMBAT
-- Aim assistance, hitbox size and fling.
--
-- FOUR AIM METHODS, BECAUSE THEY ARE DEFEATED DIFFERENTLY. Moving the camera is
-- the most compatible and the most visible. Hooking the mouse is invisible to
-- anyone watching your screen but only works where the game reads Mouse.Hit to
-- decide what you shot. Neither is "better"; a game either reads the value you
-- can reach or it does not, and the honest thing is to expose the choice and say
-- what each one touches.
--
-- Everything here is client side. Nothing below can make a server accept a shot
-- it would otherwise refuse -- if the game validates hits, aim assist changes
-- where you are pointing and nothing more.

local L = getgenv().LUMEN
local T, M, A, C = L.T, L.Motion, L.A, L.C

local Players = game:GetService("Players")
local RS = game:GetService("RunService")
local UIS = game:GetService("UserInputService")
local PhysicsService = game:GetService("PhysicsService")
local LP = L.LP

local K = {}
L.Combat = K

K.want = { aim = false, fov = false, hitbox = false, touchFling = false }
K.cfg = {
  method = "Camera lock",
  part = "Head",
  target = "Closest to cursor",
  fov = 120,
  smooth = 0.22,
  maxDist = 500,
  teamCheck = true,
  visibleOnly = false,
  holdRmb = true,
  hitboxSize = 8,
  hitboxScope = "Root only",
}

K.METHODS = { "Camera lock", "Camera snap", "Silent aim", "Off" }
K.PARTS   = { "Head", "Torso", "HumanoidRootPart" }
K.TARGETS = { "Closest to cursor", "Nearest player", "Lowest health" }
K.SCOPES  = { "Root only", "Root and legs", "Every part" }

-- ---------------------------------------------------------------- targeting

local function partOf(ch)
  if not ch then return nil end
  local want = K.cfg.part
  if want == "Torso" then
    return ch:FindFirstChild("UpperTorso") or ch:FindFirstChild("Torso")
        or ch:FindFirstChild("HumanoidRootPart")
  end
  return ch:FindFirstChild(want) or ch:FindFirstChild("HumanoidRootPart")
end

local function alive(p)
  local ch = p.Character
  local hum = ch and ch:FindFirstChildOfClass("Humanoid")
  return hum and hum.Health > 0, ch, hum
end

local function seen(part)
  if not K.cfg.visibleOnly then return true end
  local cam = workspace.CurrentCamera
  if not (cam and part) then return true end
  local params = RaycastParams.new()
  params.FilterType = Enum.RaycastFilterType.Exclude
  params.FilterDescendantsInstances = { LP.Character, part.Parent }
  local dir = part.Position - cam.CFrame.Position
  local hit = workspace:Raycast(cam.CFrame.Position, dir, params)
  return hit == nil
end

-- Returns the player the current settings say to aim at, or nil.
function K.findTarget()
  local cam = workspace.CurrentCamera
  if not cam then return nil end
  -- LEAVE THIS AS GetMouseLocation. It looks like the coordinate-space mix that
  -- was just fixed in the ring above, and it is not one. Measured on a live
  -- client against the same world point:
  --
  --     WorldToViewportPoint   (1278.7, 684.9)   inset-INCLUDED
  --     WorldToScreenPoint     (1278.7, 626.9)   inset-excluded
  --     difference                       58.0    exactly the inset
  --
  -- `sp` below comes from WorldToViewportPoint, which is the inset-INCLUDED
  -- reading -- the same space GetMouseLocation reports in. The two agree, so
  -- the cone test is already correct. Converting either one to L.pointer()
  -- would introduce a 58 px targeting error where there is none today.
  local mouse = UIS:GetMouseLocation()
  local myTeam = LP.Team

  local best, bestScore
  for _, p in ipairs(Players:GetPlayers()) do
    if p ~= LP then
      local ok, ch, hum = alive(p)
      local part = ok and partOf(ch)
      local sameTeam = K.cfg.teamCheck and myTeam and p.Team == myTeam
      if part and not sameTeam then
        local sp, onScreen = cam:WorldToViewportPoint(part.Position)
        local dist = (part.Position - cam.CFrame.Position).Magnitude
        if onScreen and dist <= K.cfg.maxDist and seen(part) then
          local flat = (Vector2.new(sp.X, sp.Y) - mouse).Magnitude
          if flat <= K.cfg.fov then
            local score
            if K.cfg.target == "Nearest player" then score = dist
            elseif K.cfg.target == "Lowest health" then score = hum.Health
            else score = flat end
            if not bestScore or score < bestScore then
              bestScore, best = score, { player = p, part = part }
            end
          end
        end
      end
    end
  end
  return best
end

-- ---------------------------------------------------------------- prediction
--
-- AIMING AT WHERE SOMEBODY IS ONLY WORKS FOR HITSCAN. If the game fires a
-- projectile, a moving target has left by the time it arrives, and an aim assist
-- that tracks perfectly still misses every shot -- which is the single most
-- common reason one of these "does not work" in a game where it clearly aimed.
--
-- So the aim point is led by the target's own velocity. `travel` is how long the
-- projectile takes per stud; 0 turns prediction off for hitscan games. There is
-- no way to read a game's projectile speed from here, so it is a dial.
-- Roblox's remote-character interpolation buffer, in seconds. Measured at
-- 0.185 by two-client cross-correlation: total observed lag 0.22 s at a
-- one-way ping of 0.035 s. See `newLead` for the full experiment. This is the
-- DOMINANT term in the aim lead -- ping is the small one.
K.cfg.interpBuffer = 0.185

K.cfg.predict = 0            -- seconds of lead per stud of distance

function K.predict(part)
  if not part then return nil end
  local p = part.Position
  if K.cfg.predict <= 0 then return p end
  local cam = workspace.CurrentCamera
  if not cam then return p end
  local dist = (p - cam.CFrame.Position).Magnitude
  local vel = part.AssemblyLinearVelocity
  -- gravity is not compensated: a lead that also arcs needs the projectile's
  -- speed, and guessing that produces confident nonsense
  return p + vel * (dist * K.cfg.predict)
end

-- ---------------------------------------------------------------- fov circle

local fovGui, fovRing, fovDot, fovTicks

local function ensureRing()
  if fovRing and fovRing.Parent then return end
  fovGui = L.mk("ScreenGui", {
    Name = "LumenFov", ResetOnSpawn = false, IgnoreGuiInset = true,
    ZIndexBehavior = Enum.ZIndexBehavior.Sibling, DisplayOrder = 8,
  })
  fovGui.Parent = L.host()
  L.own(fovGui)
  fovRing = L.mk("Frame", {
    AnchorPoint = Vector2.new(0.5, 0.5),
    BackgroundTransparency = 1, BorderSizePixel = 0,
    Size = UDim2.fromOffset(240, 240), Name = "Ring", Parent = fovGui,
  })
  L.corner(999, fovRing)
  L.stroke(T.c.accent, 1.4, 0.35, fovRing)

  -- A bare circle shows where the cone reaches but not where its centre is, and
  -- the centre is the thing being aimed. The dot marks it; the four ticks give
  -- the eye fixed references so the overlay reads as an instrument rather than
  -- a ring drifting across the screen.
  fovDot = L.mk("Frame", {
    AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, 0.5),
    Size = UDim2.fromOffset(3, 3), BackgroundColor3 = T.c.accent,
    BackgroundTransparency = 0.55, BorderSizePixel = 0,
    Name = "Centre", Parent = fovRing,
  })
  L.corner(999, fovDot)

  fovTicks = {}
  for _, t in ipairs({
    { p = UDim2.fromScale(0.5, 0), s = UDim2.fromOffset(1, 7) },
    { p = UDim2.fromScale(0.5, 1), s = UDim2.fromOffset(1, 7) },
    { p = UDim2.fromScale(0, 0.5), s = UDim2.fromOffset(7, 1) },
    { p = UDim2.fromScale(1, 0.5), s = UDim2.fromOffset(7, 1) },
  }) do
    fovTicks[#fovTicks + 1] = L.mk("Frame", {
      AnchorPoint = Vector2.new(0.5, 0.5), Position = t.p, Size = t.s,
      BackgroundColor3 = T.c.lineStrong, BackgroundTransparency = 0.55,
      BorderSizePixel = 0, Name = "Tick", Parent = fovRing,
    })
  end
end

-- THE RING GETS ITS OWN LOOP. It used to be moved from inside the aim loop,
-- which meant switching the circle on WITHOUT aim assist drew it once at the
-- origin and left it there -- a control that appeared to do nothing, or worse,
-- put a stray ring in the corner of the screen. The overlay is its own feature
-- and drives itself.
local ringConn

function K.setFovRing(on)
  K.want.fov = on and true or false
  if ringConn then ringConn:Disconnect() ringConn = nil end
  if not on then
    if fovGui then pcall(function() fovGui:Destroy() end) end
    fovGui, fovRing, fovDot, fovTicks = nil, nil, nil, nil
    return true
  end
  ensureRing()
  local lit = 0
  ringConn = L.hold(RS.RenderStepped:Connect(function(dt)
    if not (L.live() and K.want.fov and fovRing and fovRing.Parent) then return end

    -- POSITION IS EXACT AND NEVER EASED. This is a targeting overlay: a spring
    -- here would draw the cone where the pointer just was, which is a lie about
    -- where the assist is going to look. Only the lock STATE is eased.
    --
    -- The `+ inset` that used to be here was the bug behind the ring sitting
    -- below the cursor. GetMouseLocation is already the inset-INCLUDED reading,
    -- which is exactly what an IgnoreGuiInset ScreenGui wants; adding the inset
    -- again put it 58 px low. Measured, then fixed in one place -- see
    -- L.pointerOffset in lm_00_core.
    local off = L.pointerOffset(fovGui)
    fovRing.Position = UDim2.fromOffset(off.X, off.Y)
    fovRing.Size = UDim2.fromOffset(K.cfg.fov * 2, K.cfg.fov * 2)

    -- Frame-rate independent ease. `1 - e^(-rate*dt)` settles in the same wall
    -- time at 30 fps as at 240; a fixed per-frame lerp does not, and would make
    -- the lock flash faster on a better machine.
    local want = (K.want.aim and K.current ~= nil) and 1 or 0
    lit = lit + (want - lit) * (1 - math.exp(-14 * math.min(dt or 1/60, 0.1)))

    for _, ch in ipairs(fovRing:GetChildren()) do
      if ch:IsA("UIStroke") then
        ch.Transparency = 0.45 - 0.40 * lit
        ch.Color = T.c.lineStrong:Lerp(T.c.accent, lit)
      end
    end
    if fovDot then
      fovDot.BackgroundTransparency = 0.55 - 0.45 * lit
      local d = 3 + 2 * lit
      fovDot.Size = UDim2.fromOffset(d, d)
    end
    if fovTicks then
      for _, tk in ipairs(fovTicks) do
        tk.BackgroundTransparency = 0.55 - 0.35 * lit
      end
    end
  end))
  return true
end

-- ---------------------------------------------------------------- aim

local aimConn, silentHook

local function holdOK()
  if not K.cfg.holdRmb then return true end
  return UIS:IsMouseButtonPressed(Enum.UserInputType.MouseButton2)
end

function K.setAim(on)
  K.want.aim = on and true or false
  if aimConn then aimConn:Disconnect() aimConn = nil end
  if not K.want.aim then
    K.current = nil
    return true
  end

  local cam = workspace.CurrentCamera
  if not cam then
    K.want.aim = false
    return false, "no camera"
  end

  aimConn = L.hold(RS.RenderStepped:Connect(function(dt)
    if not L.live() or not K.want.aim then return end
    -- re-read: the camera object is replaced on respawn in a lot of games, and
    -- writing to the old one is a silent no-op
    cam = workspace.CurrentCamera
    if not cam then return end

    if K.cfg.method == "Off" or K.cfg.method == "Silent aim" then
      -- silent aim still needs a target resolved every frame, because the hook
      -- answers from K.current rather than doing its own search mid-read
      K.current = K.cfg.method == "Silent aim" and holdOK()
        and (function() local t = K.findTarget() return t and t.player.Name end)() or nil
      return
    end
    if not holdOK() then K.current = nil return end

    local t = K.findTarget()
    K.current = t and t.player.Name or nil
    if not t then return end

    local aimAt = K.predict(t.part)
    local look = CFrame.new(cam.CFrame.Position, aimAt)
    if K.cfg.method == "Camera snap" then
      cam.CFrame = look
    else
      -- framerate-independent smoothing: raising dt into the exponent means a
      -- drop from 120 to 30 fps does not quietly triple the assist
      local a = 1 - math.exp(-(1 / math.max(K.cfg.smooth, 0.01)) * dt)
      cam.CFrame = cam.CFrame:Lerp(look, math.clamp(a, 0, 1))
    end
  end))
  return true
end

-- SILENT AIM rewrites what the game READS, not where the camera points.
--
-- Two honesty problems in the first version, both fixed here:
--
--   IT DID NOT UNHOOK. "Turning it off" set K.want.aim = false, which also
--   switched off the camera assist and left the metamethod hooked for the rest
--   of the session. A toggle whose off state disables a different feature and
--   leaves this one installed is not a toggle.
--
--   IT ONLY ANSWERED Mouse.Hit. Plenty of games never read that; they read
--   Mouse.UnitRay, or ray-cast from the camera themselves. Answering one of
--   three read paths is why silent aim "does nothing" in most places.
--
-- It is still not universal and cannot be: a game that raycasts on the SERVER
-- from its own numbers cannot be reached from here at all. What this does is
-- answer every client-side read we can legitimately intercept.
local silentActive = false

function K.setSilent(on)
  if not on then
    -- the hook stays installed (executors do not offer a portable unhook) but it
    -- is inert: it forwards to the original for everything
    silentActive = false
    return true
  end

  local hookmeta = rawget(getgenv(), "hookmetamethod")
  if type(hookmeta) ~= "function" then
    return false, "this executor has no hookmetamethod"
  end
  silentActive = true
  if silentHook then return true end          -- already installed, just re-armed

  local mouse = LP:GetMouse()
  local ok, err = pcall(function()
    local old
    old = hookmeta(game, "__index", function(self, key)
      if L.live() and silentActive and K.want.aim and self == mouse then
        local name = K.current
        local t = name and K.findTarget()
        if t then
          local at = K.predict(t.part)
          if key == "Hit" then
            return CFrame.new(at)
          elseif key == "Target" then
            return t.part
          elseif key == "UnitRay" then
            local cam = workspace.CurrentCamera
            if cam then
              local from = cam.CFrame.Position
              return Ray.new(from, (at - from).Unit)
            end
          end
        end
      end
      return old(self, key)
    end)
    silentHook = old
  end)
  if not ok then
    silentActive = false
    return false, tostring(err)
  end
  return true
end

function K.silentInstalled() return silentHook ~= nil, silentActive end

-- ---------------------------------------------------------------- hitbox

local hitboxConn
local originalHitboxes = {}

local function restoreHitboxes()
  for part, state in pairs(originalHitboxes) do
    pcall(function()
      if part.Parent then
        part.Size = state.size
        part.Transparency = state.transparency
        part.CanCollide = state.canCollide
      end
    end)
  end
  originalHitboxes = {}
end

local function scopeParts(ch)
  local names = { "HumanoidRootPart" }
  if K.cfg.hitboxScope == "Root and legs" then
    names = { "HumanoidRootPart", "LeftFoot", "RightFoot", "LeftLowerLeg", "RightLowerLeg" }
  elseif K.cfg.hitboxScope == "Every part" then
    local all = {}
    for _, d in ipairs(ch:GetChildren()) do
      if d:IsA("BasePart") then all[#all + 1] = d.Name end
    end
    names = all
  end
  return names
end

function K.setHitbox(on)
  K.want.hitbox = on and true or false
  if hitboxConn then
    local oldConn = hitboxConn
    hitboxConn = nil
    pcall(function() oldConn:Disconnect() end)
  end

  if not K.want.hitbox then
    restoreHitboxes()
    return true
  end

  local acc = 0
  hitboxConn = L.hold(RS.Heartbeat:Connect(function(dt)
    if not L.live() or not K.want.hitbox then return end
    -- Expanded hitboxes set remote limbs non-collidable, which destroys the
    -- only channel a fling can use and also creates a false immune diagnosis.
    -- Preserve intent but restore exact state for the whole physics transaction.
    if K.physicsBusy and K.physicsBusy() then
      restoreHitboxes()
      acc = 0
      return
    end
    acc = acc + dt
    if acc < 0.4 then return end
    acc = 0
    local s = K.cfg.hitboxSize
    for _, p in ipairs(Players:GetPlayers()) do
      if p ~= LP then
        local okAlive, ch = alive(p)
        if okAlive and ch then
          for _, n in ipairs(scopeParts(ch)) do
            local part = ch:FindFirstChild(n)
            if part and part:IsA("BasePart") then
              if originalHitboxes[part] == nil then
                originalHitboxes[part] = {
                  size = part.Size,
                  transparency = part.Transparency,
                  canCollide = part.CanCollide,
                }
              end
              pcall(function()
                part.Size = Vector3.new(s, s, s)
                part.Transparency = 0.7
                part.CanCollide = false
              end)
            end
          end
        end
      end
    end
  end))
  return true
end

-- ---------------------------------------------------------------- fling
--
-- THE VELOCITY-ORBIT ENGINE, taken from the script that actually behaves the way
-- it should. My previous attempt spun a BodyAngularVelocity and hoped the
-- collision would carry; this does something smarter and it is worth stating
-- why each piece is there, because every one of them is load-bearing.
--
--   IT TELEPORTS AROUND THEM, IT DOES NOT ORBIT SMOOTHLY. Six offsets per cycle
--   -- above, below, and two diagonals -- each written on its own frame with a
--   rotation that keeps advancing. Contact happens from a different direction
--   every frame, which is what a single smooth orbit could never do.
--
--   VELOCITY IS WRITTEN ON EVERY PLACEMENT, not left to the solver. 9e7 linear
--   and 9e8 rotational, re-stamped at each offset, so there is never a frame
--   where the engine gets to damp it back down.
--
--   FallenPartsDestroyHeight IS SET TO NaN for the duration. Being thrown under
--   the map is how the operator dies during a fling; with the floor set to
--   not-a-number nothing is ever below it, so you cannot be deleted. Restored
--   afterwards from the value captured at load.
--
--   IT READS THE TARGET'S MOTION. A standing target and a sprinting one need
--   different offsets, so the pattern switches on their speed and leans into
--   their MoveDirection -- aiming where they are going rather than where they
--   were.
--
--   IT KNOWS WHEN IT WORKED: the loop ends the moment their part exceeds 500
--   studs/s. No fixed duration to sit through, and no guessing.
--
--   THE RETURN IS A LOOP, NOT A WRITE. It re-asserts the saved CFrame and calls
--   GettingUp every frame until you are within 25 studs of where you started.
--   That is why this one puts you back and my anchor-brake had to fight to.

K.FLING_MODES  = { "One target", "Loop one target", "Selected", "Nearest", "Everyone" }
-- names the user ticked in the player panel; "Selected" walks exactly these
K.selected = {}

-- HOW CONTACT IS DELIVERED. Contact lock is the default because it keeps two
-- separate collidable assemblies overlapped around one predicted centre. The
-- legacy weld label is accepted only to migrate an old saved profile; no weld is
-- created anywhere in the engine because local assembly ownership is a POV
-- illusion and removes the contact channel that actually moves the other client.
local TELE     = "Teleport (clean)"
local LATCH    = "Contact lock"
local LEGACY_LATCH = "Weld (glued)"
local MASSLESS = "Heavy rig"          -- was "Massless rig"; see rigMassless
local INFV     = "Overflow"
local VOID     = "Void drop"
local CONSTR   = "Constraint spin"
local REP      = "Rep-root"
local REPBURST = "Rep-root burst"
local REPNAN   = "Rep-root NaN"
K.FLING_ATTACH = { LATCH, REP, REPBURST, REPNAN, MASSLESS, TELE, CONSTR, VOID, INFV }
K.cfg.flingAttach = LATCH

-- ---------------------------------------------------------------- rep-root
--
-- IT IS NOT A WELD, AND CALLING IT ONE COST ME TWENTY-FIVE TRIALS.
--
-- The community name for this is "weld fling", so I tested welds: WeldConstraint,
-- legacy Weld, Motor6D, RigidConstraint, AnimationConstraint. All five moved the
-- victim at 25 studs/s or less against 43,930 for contact, and I concluded the
-- technique was a myth. It is not. It just has nothing to do with joints.
--
-- The whole mechanism is one hidden property:
--
--   sethiddenproperty(myRoot, "PhysicsRepRootPart", theirRoot)
--
-- PhysicsRepRootPart names the part the replication layer treats as the root of
-- this part's assembly when it sends physics to the server. Normally that is
-- your own root. Point it at somebody else's and your client's physics packets
-- are framed as belonging to THEIR assembly -- so the velocities you write are
-- applied to their body by the server, which already trusts you because you
-- legitimately own your own character.
--
-- A joint is simulated locally and replicates as a joint; the victim's client
-- simulates its own body and ignores it. This operates a layer below that, on
-- the replication stream itself, where the joint was never relevant. That is
-- why every weld measurement said no and this says yes.
--
-- Read as nil on a normal root; writes verified on this executor.
local shp = rawget(getgenv(), "sethiddenproperty") or rawget(getgenv(), "sethiddenprop")
local ghp = rawget(getgenv(), "gethiddenproperty")

function K.repAvailable()
  return type(shp) == "function"
end

-- `to` is the part to be replicated through, or the part itself to release.
local function repBind(part, to)
  if type(shp) ~= "function" or not (part and part.Parent) then return false end
  local ok = pcall(shp, part, "PhysicsRepRootPart", to)
  return ok
end

local function repRead(part)
  if type(ghp) ~= "function" or not part then return nil end
  local ok, v = pcall(ghp, part, "PhysicsRepRootPart")
  return ok and v or nil
end

-- How hard the hijack pushes. The reference hub used 500 and 5000 and those are
-- the numbers everybody copies; Lumen's contact path has always used 9e7/9e8 and
-- the rep stream takes the same magnitudes, so there is no reason to be timid.
K.cfg.repPower = 4.5e8        -- linear, studs/s
K.cfg.repSpin  = 9e8          -- angular, rad/s
K.cfg.repLift  = 0.55         -- share of power spent going up rather than out

-- Runaway detector measured from the attempt origin, never world origin.
K.SANE_LIMIT    = 2000000

K.cfg.flingMode     = "One target"
-- SHIPPED ON "INSTANT + BRUTAL". The three preset buttons still exist and still
-- do what they say; this is just which one you start on. The old defaults were
-- the safe preset, which meant every fresh install threw at a fraction of what
-- the engine will carry until somebody found the button.
--
-- Only the monotonic levers are pushed. approachSettle stays at 0.35 and the
-- orbit geometry stays where it is, because those have measured optima rather
-- than "more is better" -- 0.35 s is the least settle that still transfers
-- network ownership, and dropping under it fails to fling at all.
K.cfg.flingDuration = 8       -- seconds spent on each player before moving on
K.cfg.flingGap      = 0       -- pause between players in Everyone mode
K.cfg.orbitRadius   = 0.6     -- multiplier on the offset pattern
K.cfg.orbitLift     = 1.2     -- the vertical half-offset the pattern swings through
K.cfg.contactEnvelope = 1.25  -- maximum horizontal contact radius in studs
-- The strike pattern scores itself per cycle and adapts. `adaptGain` is the
-- studs/s of target speed change that counts as "the offsets connected";
-- `adaptWiden` is how far past the envelope the search may widen when they do
-- not. Set `adaptive = false` to pin the old fixed pattern.
K.cfg.adaptive   = true
K.cfg.adaptGain  = 25
K.cfg.adaptWiden = 1.6

-- POWER LIVES IN TWO NUMBERS, NOT IN THE CONTACT VELOCITY.
--
-- The slam written at every placement is already 9e7 / 9e8 -- past the point
-- Roblox's solver will impart more in a single step, so cranking it does
-- nothing. What actually decides how far a target flies is (1) the speed we let
-- them reach before we stop, and (2) whether we keep hitting them once they are
-- already moving fast. The old engine released at the FIRST frame past 500 --
-- one good contact and it let go, which is a shove, not a launch.
--
--   flungAt   -- release speed. The loop keeps pumping contact until the target
--                is travelling this fast. 3000 st/s over the flingDuration is
--                ~7500 studs of travel, well inside SANE_LIMIT: they cross the
--                whole map, they do not leave the world.
--   afterburn -- once they cross flungAt we do NOT stop; we keep slamming for
--                this many more seconds. Each extra contact adds momentum until
--                they outrun the offsets, which is the real ceiling of the
--                technique -- so this is what turns "flung" into "gone".
-- A THRESHOLD, NOT A CAP. Raising this does not slow anything down: it is the
-- speed at which the loop decides they are launched and starts counting the
-- afterburn. Set high, the afterburn simply never begins and the loop keeps
-- slamming for the full duration, which is where the distance comes from.
K.cfg.flungAt       = 1000000 -- studs/s the loop drives them to before releasing
K.cfg.flingAfterburn = 3.5    -- extra seconds of hard contact past that speed

-- How long we remain visibly nearby before contact begins. Distance applies a
-- continuous reliability floor; this is propagation time, not a weld/ownership
-- claim.
K.cfg.approachSettle = 0.5

-- 0 disables lead; 1 applies half RTT + the measured 0.185 s interpolation
-- buffer exactly once. A stud cap contains outliers.
K.cfg.predictLead = 1.0
K.cfg.predictCap  = 24

-- ---- LOOP MODE: WHAT HAPPENS BETWEEN THROWS ----------------------------
--
-- Loop mode used to stop after one throw, and the cause was not the loop.
-- `engage` returned local throw evidence, the runner immediately came round again, and
-- `approach` teleported to a body now travelling at tens of thousands of
-- studs per second -- which has moved thousands of studs by the next frame.
-- Nothing lands, `it.attempts` climbs, three of those and `engage` reports
-- "givenup", which the runner treated as a stop condition.
--
-- So it was succeeding, then failing three times at something impossible, then
-- concluding the target was immune. The fix is to wait for them to be a real
-- target again before trying: back on the ground, or freshly respawned.
K.cfg.settleSpeed    = 60     -- studs/s under which they count as landed again
K.cfg.settleHold     = 0.45   -- and how long they have to stay that slow
K.cfg.settlePatience = 60     -- stop waiting for a body that never comes down
-- Keep going through failures rather than stopping on them. "Relentless" is
-- what the loop was always meant to be: a failed pass is a reason to try again,
-- not a reason to give up on somebody who is standing right there.
K.cfg.loopRelentless = true

-- how patient the engagement layer is before it gives up on somebody
K.cfg.waitSeated      = true
K.cfg.seatPatience    = 30
K.cfg.waitRespawn     = true
K.cfg.respawnPatience = 25
K.cfg.watchImmune     = true
K.cfg.immunePatience  = 20
K.cfg.maxAttempts     = 8

K.cfg.autoFallback  = true
K.cfg.returnHome    = true   -- stopping puts you back where the run began
K.cfg.fallbackAt    = 40      -- studs of travel under which the attempt failed

K.flinging   = false
K.flingTarget = nil
K.runHome    = nil            -- CFrame captured when a run starts, not per attempt
K.whitelist  = {}             -- lowercase names that are never targeted

local FPDH = workspace.FallenPartsDestroyHeight
local flingRunner
local returnSerial = 0
K.returningHome = false

local function cancelReturnHome()
  returnSerial = returnSerial + 1
  K.returningHome = false
end

-- A NIL runSerial MEANS "NOT TIED TO A RUN". Per-attempt returns must stop the
-- instant the run does; the return to where the whole run STARTED has to survive
-- the run ending, because that is the only moment it ever fires.
local function returnHomeOwned(ticket, generation, runSerial, character, humanoid, root)
  return ticket == returnSerial
     and L._gen == generation and L.live()
     and (runSerial == nil or (K.flinging and K.runSerial == runSerial))
     and LP.Character == character
     and root and root.Parent and humanoid and humanoid.Parent == character
     and humanoid.Health > 0
end

-- Returning is deliberately not part of a fling finalizer. Finalizers must be
-- synchronous so a stop/reload can release every borrowed physics channel in
-- the same turn. This small follow-up owns no globals or tokens and checks both
-- module and run generations immediately before every write.
local function scheduleReturnHome(character, humanoid, root, home, runSerial)
  cancelReturnHome()
  if not (character and humanoid and root and home and L.live()) then return nil end
  if runSerial ~= nil and not K.flinging then return nil end

  local ticket, generation = returnSerial, L._gen
  local deadline = os.clock() + 1.5
  K.returningHome = true
  task.spawn(function()
    local guard = 0
    while guard < 60 and os.clock() < deadline
          and returnHomeOwned(ticket, generation, runSerial, character, humanoid, root) do
      guard = guard + 1
      local ok, arrived = pcall(function()
        if not returnHomeOwned(ticket, generation, runSerial, character, humanoid, root) then
          return false
        end
        local back = home * CFrame.new(0, 0.5, 0)
        root.CFrame = back
        if character.PrimaryPart then
          character:SetPrimaryPartCFrame(back)
        else
          character:PivotTo(back)
        end
        humanoid:ChangeState(Enum.HumanoidStateType.GettingUp)
        for _, part in ipairs(character:GetChildren()) do
          if part:IsA("BasePart") then
            part.AssemblyLinearVelocity = Vector3.zero
            part.AssemblyAngularVelocity = Vector3.zero
          end
        end
        return (root.Position - home.Position).Magnitude < 25
      end)
      if not ok or arrived then break end
      RS.Heartbeat:Wait()
    end
    if ticket == returnSerial and L.live() then K.returningHome = false end
  end)
  return ticket
end

local function waitForReturnHome(ticket)
  local deadline = os.clock() + 1.6
  while ticket and ticket == returnSerial and K.returningHome
        and L.live() and K.flinging and os.clock() < deadline do
    RS.Heartbeat:Wait()
  end
end

-- ---------------------------------------------------------------- unstick
--
-- A REFUSAL THAT NEVER HEALS IS WORSE THAN A FORCED RECOVERY.
--
-- startFling used to ask a stuck run to stop, wait four seconds, and if anything
-- was still held, refuse -- and then refuse identically on every later press,
-- because nothing in that path ever cleared the thing that was stuck. The
-- operator sees a button that has silently stopped working.
--
-- The ordering here matters and is the reason this is not simply "clear the
-- flags": the finalizer is run SYNCHRONOUSLY first, so every borrowed physics
-- channel (mass, collisions, platform stand, camera subject, the block and
-- noclip suspensions) is handed back before the thread that borrowed them is
-- destroyed. Cancelling first would strand all of it.
function K.recoverFling(why)
  local held = {}
  if flingRunner       then held[#held + 1] = "runner"  end
  if K.activeCleanup   then held[#held + 1] = "cleanup" end
  if K.returningHome   then held[#held + 1] = "return"  end
  if K.flinging        then held[#held + 1] = "flag"    end

  local active = K.activeCleanup
  if active then pcall(active, false) end
  K.activeCleanup = nil

  local runner = flingRunner
  flingRunner = nil
  if runner and coroutine.status(runner) ~= "dead" then
    pcall(task.cancel, runner)
  end

  cancelReturnHome()
  K.flinging = false
  K.flingTarget = nil
  K.waitingOn = nil
  -- a new serial invalidates any straggler that wakes up after this point
  K.runSerial = (K.runSerial or 0) + 1

  if #held > 0 then
    L.note("fling", "unstuck (" .. table.concat(held, ", ") .. ") "
                 .. (why and ("-- " .. why) or ""))
  end
  return #held > 0, held
end

-- The run origin, not the last attempt's origin. Deliberately not gated on
-- K.flinging: this fires precisely when the run has just ended.
local function returnToRunHome()
  local home = K.runHome
  if not home then return false end
  local ch = LP.Character
  local hum = ch and ch:FindFirstChildOfClass("Humanoid")
  local root = ch and ch:FindFirstChild("HumanoidRootPart")
  if not (ch and hum and root and hum.Health > 0) then return false end
  return scheduleReturnHome(ch, hum, root, home, nil) ~= nil
end
K.returnToRunHome = returnToRunHome

-- Shared interlock for Movement and Universal. Touch intent counts as busy even
-- between character epochs; a respawn rebind must wait until Combat releases it.
function K.physicsBusy()
  return K.flinging or K.activeCleanup ~= nil or flingRunner ~= nil
      or K.returningHome or (K.want and K.want.touchFling) or false
end

-- ---------------------------------------------------------------- fling lead
--
-- WHERE TO STAND SO THE CONTACT HAPPENS WHERE THEY WILL BE.
--
-- The old lead was `thum.MoveDirection * part.Velocity.Magnitude / 1.25`. Three
-- things wrong with it, and they compound:
--
--   * `MoveDirection` is a UNIT input vector. It says which way they are
--     holding, and carries no speed at all.
--   * Multiplying a unit vector by an unrelated speed magnitude produces a
--     number in studs that happens to look plausible and means nothing.
--   * `/1.25` is a magic constant with no relationship to anything measurable.
--
-- What actually sets the lead is TIME: how stale our copy of their position is.
-- That is one network trip plus a frame, and Roblox reports the trip.
local Stats = game:FindService("Stats")

-- One-way network trip in seconds. Two-client measurement proved the render
-- stream has a separate 0.185 s interpolation buffer; multiplying ping cannot
-- model that fixed term.
function K.pingSeconds()
  local ok, ms = pcall(function()
    return Stats.Network.ServerStatsItem["Data Ping"]:GetValue()
  end)
  if not ok or type(ms) ~= "number" or ms ~= ms then return 0.06 end
  return math.clamp(ms / 2000, 0.008, 0.35)
end

-- One continuously warmed tracker per remote character. A repeated replicated
-- position is not a new velocity sample; only packet changes advance its clock.
-- This avoids twenty zero samples followed by one one-frame spike. Teleports and
-- character epochs reset rather than contaminating subsequent engagements.
local motionTracks = setmetatable({}, { __mode = "k" })

local function updateMotion(player)
  local ch = player and player.Character
  local root = ch and ch:FindFirstChild("HumanoidRootPart")
  if not root then return nil end
  local now, here = os.clock(), root.Position
  local rec = motionTracks[player]
  if not rec or rec.character ~= ch then
    rec = { character = ch, position = here, changedAt = now,
            velocity = Vector3.zero, samples = 0, packetGap = 0.22 }
    motionTracks[player] = rec
    return rec
  end

  local delta = here - rec.position
  if delta.Magnitude > 0.015 then
    local dt = now - rec.changedAt
    local speed = dt > 0 and delta.Magnitude / dt or math.huge
    -- The Heartbeat collector is the sole writer. A rare early callback is
    -- ignored rather than erasing good history; teleports/outliers still reset.
    if dt < 0.025 then
      return rec
    elseif delta.Magnitude > 60 or dt > 1.0 or speed > 240 then
      rec.velocity, rec.samples = Vector3.zero, 0
    else
      local measured = delta / dt
      local alpha = rec.samples == 0 and 1 or math.clamp(dt * 2.5, 0.35, 0.72)
      rec.velocity = rec.velocity:Lerp(measured, alpha)
      rec.samples = rec.samples + 1
      rec.packetGap = rec.packetGap * 0.7 + dt * 0.3
    end
    rec.position, rec.changedAt = here, now
  end
  return rec
end

local motionClock = 0
L.hold(RS.Heartbeat:Connect(function(dt)
  motionClock = motionClock + dt
  if motionClock < 0.05 then return end
  motionClock = motionClock % 0.05
  for _, player in ipairs(Players:GetPlayers()) do
    if player ~= LP then updateMotion(player) end
  end
end))

local function newLead(player)
  local function currentTrack()
    local rec = motionTracks[player]
    if not rec or rec.character ~= player.Character then return nil end
    return rec
  end
  local function currentVelocity(rec)
    if not rec then return Vector3.zero, 0 end
    local age = os.clock() - rec.changedAt
    local staleAfter = math.clamp((rec.packetGap or 0.22) * 1.5, 0.10, 0.45)
    local freshness = 1 - math.clamp((age - staleAfter) / 0.20, 0, 1)
    return rec.velocity, freshness
  end
  return {
    point = function(part)
      if not (part and part.Parent) then return nil end
      -- Read-only getter: render-rate consumers cannot corrupt the 20 Hz packet
      -- estimator by sampling it again at 60/144 Hz.
      local rec = currentTrack()
      local velocity, freshness = currentVelocity(rec)
      local scale = K.cfg.predictLead or 1
      if L.Guard then scale = scale * L.Guard.quality() end
      local horizon = (K.pingSeconds() + (K.cfg.interpBuffer or 0.185)) * scale
      K.lastHorizon = horizon
      local confidence = (rec and math.clamp(rec.samples / 4, 0, 1) or 0) * freshness
      local lead = (rec and rec.samples > 0)
        and velocity * horizon * confidence or Vector3.zero
      local cap = K.cfg.predictCap or 24
      if lead.Magnitude > cap then lead = lead.Unit * cap end
      K.lastAimLead = lead.Magnitude
      K.predictConfidence = confidence
      return part.Position + lead
    end,
    velocity = function()
      local rec = currentTrack()
      local velocity, freshness = currentVelocity(rec)
      return velocity * freshness
    end,
  }
end

-- ---------------------------------------------------------------- afterburn
--
-- BUG 5 from FLING_PLAN: the afterburn was a flat clock. `launchedAt + 0.4`
-- fires 400 ms after the target first crosses the release speed, whether they
-- are still accelerating hard or have already stopped gaining. On a clean hit
-- that is the worst possible moment to let go -- the contacts are landing, the
-- speed is still climbing, and the timer cuts it off mid-climb.
--
-- So it ends on the DERIVATIVE instead. Keep burning while speed is still
-- rising; stop once it plateaus, because a plateau means the offsets are no
-- longer catching them and every further frame is spent chasing a body that has
-- outrun the pattern. That is the real ceiling of the technique, and this finds
-- it per target instead of guessing it once for everybody.
--
-- Three guards, because a derivative alone is not safe to loop on:
--   * a MINIMUM burn, so one noisy sample cannot end it instantly
--   * a HARD CEILING, so a target accelerating forever cannot hold the loop
--   * consecutive stalls, not a single one, so jitter does not end it early
K.cfg.burnCeiling = 2.0    -- absolute seconds past release, whatever happens
K.cfg.burnRising  = 150    -- studs/s^2 that still counts as "gaining"
K.cfg.burnStalls  = 8      -- consecutive non-gaining samples that end it

local function newBurn()
  return { at = nil, last = 0, lastT = 0, stalls = 0, peak = 0 }
end

-- Returns true when the afterburn is over. `speed` is the target's current
-- speed; call once per contact frame after launch.
local function burnDone(b, speed, now)
  if not b.at then return false end
  local dt = now - (b.lastT > 0 and b.lastT or now)
  if speed > b.peak then b.peak = speed end

  -- the minimum burn is the old constant, kept as a floor rather than a limit
  if now < b.at + (K.cfg.flingAfterburn or 0.4) then
    b.last, b.lastT = speed, now
    return false
  end
  if now > b.at + (K.cfg.burnCeiling or 2.0) then return true end

  if dt > 1e-4 then
    local rate = (speed - b.last) / dt
    if rate >= (K.cfg.burnRising or 150) then b.stalls = 0
    else b.stalls = b.stalls + 1 end
    b.last, b.lastT = speed, now
  end
  return b.stalls >= (K.cfg.burnStalls or 8)
end

-- ---- one target ------------------------------------------------------

-- Ordered alternatives after the chosen technique. Contact lock is the default
-- first attempt and is not repeated as its own fallback.
-- HEAVY RIG IS NOT IN THIS LIST BY ACCIDENT ANYMORE.
--
-- "Massless rig" used to be the FIRST fallback, so every failed attempt fell
-- straight into the worst available option. Measured against a body we own, in
-- a live client, attacker Massless costs 87% of the transfer:
--
--     MASSLESS   false 1.69e9   true 2.20e8      -87%
--
-- which is what the equation says it should: collision impulse scales with the
-- reduced mass m1*m2/(m1+m2), and that RISES with our mass. Shedding mass to hit
-- harder is backwards. The mode still exists for anyone who wants it, but it is
-- no longer somewhere the engine goes on its own.
-- Rep-root first: it is the only one that reaches the victim's assembly through
-- replication rather than through contact, so it works in games where contact
-- is filtered. NaN stays last -- it lands hard but it is unpredictable.
local FALLBACK_ORDER = { "Rep-root", "Rep-root burst", "Teleport (clean)",
                         "Void drop", "Overflow", "Rep-root NaN" }

local function flingOne(target, depth, session)
  depth = depth or 0
  if not K.flinging or not L.live() then return false, "cancelled" end
  if depth > #FALLBACK_ORDER then return false, "fallback depth exhausted" end
  cancelReturnHome()
  local runSerial = K.runSerial
  K.lastThrow = 0
  K.lastThrowEvidence = nil
  local ch = LP.Character
  local hum = ch and ch:FindFirstChildOfClass("Humanoid")
  local root = hum and hum.RootPart
  if not (ch and hum and root) then return false, "you have no character" end

  local tch = target.Character
  local thum = tch and tch:FindFirstChildOfClass("Humanoid")
  local troot = thum and thum.RootPart
  local thead = tch and tch:FindFirstChild("Head")
  local acc = tch and tch:FindFirstChildOfClass("Accessory")
  local handle = acc and acc:FindFirstChild("Handle")
  if not tch then return false, "they have no character" end
  -- a seated target is welded to the seat; the impulse goes into the seat and
  -- nothing happens, so it is skipped rather than wasted time
  if thum and thum.Sit then return false, "they are sitting" end
  if not tch:FindFirstChildWhichIsA("BasePart") then return false, "nothing to hit" end

  -- One estimator for this engagement. See `newLead` for why the old
  -- MoveDirection-times-speed expression was replaced.
  local lead = newLead(target)

  -- One immutable home per engagement/fallback chain. A module-global home can
  -- belong to an old character or map, and recursive fallback must not add 0.5
  -- studs of drift on each pass.
  if not session or session.character ~= ch then
    session = { character = ch, home = root.CFrame, tried = {} }
  end
  session.tried = session.tried or {}
  local home = session.home
  K.home = home
  local attemptCancelled = false
  local function attemptActive()
    return not attemptCancelled and K.flinging and L.live()
       and K.runSerial == runSerial
  end

  -- where they were standing when we started, so afterwards we can ask the only
  -- question that matters: did they actually move?
  local markPart = troot or thead or handle
  local beforePos = markPart and markPart.Position

  local attemptCamera = workspace.CurrentCamera
  local camSubject = attemptCamera and attemptCamera.CameraSubject

  -- FLINGING NEEDS COLLISION, AND NOCLIP TAKES IT AWAY.
  --
  -- An impulse can only be handed over through a contact, so with your limbs
  -- non-collidable the whole technique runs perfectly and does nothing -- which
  -- is exactly how it presents: hundreds of placements, target velocity zero,
  -- no error anywhere. Anyone with noclip left on hits this, and diagnosing it
  -- from the outside is miserable.
  --
  -- Re-asserted every cycle rather than once, because noclip is itself a
  -- per-frame loop and a single write loses to it. What was collidable before is
  -- recorded so the character is handed back exactly as it was found.
  local collideWas = {}
  local forceCollide
  forceCollide = function()
    for _, d in ipairs(ch:GetDescendants()) do
      if d:IsA("BasePart") and d.Name ~= "HumanoidRootPart"
         and not d:FindFirstAncestorOfClass("Accessory") then
        if collideWas[d] == nil then collideWas[d] = d.CanCollide end
        if not d.CanCollide then d.CanCollide = true end
      end
    end
  end

  -- ---- the massless rig -------------------------------------------------
  --
  -- DevForum's recurring "locally welded models fling my character" bug has one
  -- accepted fix: make every limb massless and put the mass back on the
  -- HumanoidRootPart via CustomPhysicalProperties. That is a FIX when it happens
  -- to you and a WEAPON when you do it deliberately -- the same rig that stops
  -- your own body being thrown by a joint is the rig that concentrates every
  -- contact into one dense point instead of spreading it across twelve limbs.
  --
  -- It also removes the limbs from the mass that has to be accelerated, so the
  -- solver can move you far faster between placements, which is what actually
  -- feeds the contact.
  local massWas, propWas = {}, nil
  local function rigMassless(on, restoreRoot)
    if on then
      if propWas == nil then propWas = root.CustomPhysicalProperties or false end
      -- INVERTED, AND THE OLD COMMENT WAS THE TELL. It said "dense" while
      -- setting density to 0.01, which is Roblox's MINIMUM (the range is
      -- 0.01-100). So the rig shed mass twice -- Massless on every limb and the
      -- lightest possible root -- while its own comment claimed the opposite.
      --
      -- Impulse scales with the reduced mass m1*m2/(m1+m2), which rises with
      -- ours, so the lever points the other way. Measured: attacker Massless
      -- 1.69e9 -> 2.20e8, a loss of 87%.
      --
      -- HONEST LIMIT: the -87% for Massless is measured. That maximum density
      -- is correspondingly BETTER follows from the same equation but has not
      -- itself been measured yet -- it is an inference, and it is flagged in
      -- the panel as one until there is a number beside it.
      for _, d in ipairs(ch:GetDescendants()) do
        if d:IsA("BasePart") and d ~= root then
          if massWas[d] == nil then massWas[d] = d.Massless end
          d.Massless = false
        end
      end
      pcall(function()
        -- genuinely dense this time, frictionless and inelastic: all transfer,
        -- no bounce, and as much reduced mass as the solver will give us
        root.CustomPhysicalProperties = PhysicalProperties.new(100, 0, 0, 100, 1)
      end)
    else
      for d, was in pairs(massWas) do
        if d.Parent then pcall(function() d.Massless = was end) end
      end
      massWas = {}
      if propWas ~= nil then
        if restoreRoot ~= false then
          pcall(function()
            root.CustomPhysicalProperties = propWas or nil
          end)
        end
        propWas = nil
      end
    end
  end

  -- Every technique consumes this same predicted centre exactly once.
  local function aimAt(part) return lead.point(part) or part.Position end
  K.lastAimLead = 0
  local peakVisibleSpeed = 0

  local function observeTargetSpeed(part)
    if not (part and part.Parent) then return end
    local ok, speed = pcall(function() return part.AssemblyLinearVelocity.Magnitude end)
    if ok and type(speed) == "number" and speed == speed and speed < math.huge then
      peakVisibleSpeed = math.max(peakVisibleSpeed, speed)
    end
  end

  local function place(part, pos, ang)
    if not attemptActive() then return false end
    if not (root and root.Parent and part and part.Parent) then return false end
    forceCollide()
    observeTargetSpeed(part)
    local cf = CFrame.new(aimAt(part)) * pos * ang
    root.CFrame = cf
    pcall(function()
      if ch.PrimaryPart then ch:SetPrimaryPartCFrame(cf) else ch:PivotTo(cf) end
    end)
    root.Velocity = Vector3.new(9e7, 9e7 * 10, 9e7)
    root.RotVelocity = Vector3.new(9e8, 9e8, 9e8)
    return true
  end

  -- CONTACT LOCK. Two-client proof invalidated every local-weld signal
  -- (zero gap, merged AssemblyRootPart and ReceiveAge zero): all were attacker
  -- simulation and snapped back remotely. The only usable channel is a collision
  -- the target client resolves against our separately replicated body.
  -- Client-created welds only manufacture an attacker-POV illusion; they do not
  -- move an active remote character. Contact lock therefore stays as two
  -- separate assemblies and repeatedly places our collidable body inside a
  -- compact envelope around the one predicted centre.
  -- BUG 4 from FLING_PLAN: THE PATTERN NOW CLOSES THE LOOP.
  --
  -- The six offsets used to be computed once from the target's part size and
  -- then repeated unchanged for the whole engagement. If that geometry happened
  -- to miss a particular character's collision box -- a different rig, an
  -- accessory, a crouch, a hitbox that is not where the part says it is -- it
  -- missed for every cycle, and the engine read that as "immune" rather than
  -- "wrong shape".
  --
  -- So each cycle is now scored by what it actually produced. The target's own
  -- replicated speed is the only honest signal available: we cannot see their
  -- simulation, but we can see the velocity their client publishes, and a cycle
  -- that moved it is a cycle whose offsets connected.
  --
  --   gained    keep the geometry, and creep the radius back IN, because tight
  --             overlap is where transfer is best and we only widened to search
  --   dry       rotate the phase so the next cycle samples different contact
  --             points, and after two consecutive misses widen the search
  --
  -- THE PHASE STEP IS THE GOLDEN RATIO, not a round fraction. Stepping by 1/3 or
  -- 1/4 walks a lattice and revisits the same three or four orientations
  -- forever, which is the same fixed pattern with extra steps. 0.618 never
  -- repeats, so consecutive cycles sample the contact geometry evenly instead of
  -- cycling through a handful of angles.
  local function contactWork(part)
    local t0, origin, angle = tick(), part.Position, 0
    local launchedAt, burn = nil, newBurn()
    local baseRadius = math.clamp(math.max(part.Size.X, part.Size.Z) * 0.32,
                              0.35, math.max(0.35, K.cfg.contactEnvelope or 1.25))
    local envelope = math.max(0.35, K.cfg.contactEnvelope or 1.25)
    local radMax = envelope * (K.cfg.adaptWiden or 1.6)
    local rad = baseRadius
    local lift = math.clamp(K.cfg.orbitLift, 0.35, 2.4)
    local phase, dry, cycles, bestGain = 0, 0, 0, 0

    repeat
      if not (root and root.Parent and part.Parent and thum and thum.Parent) then break end
      if (part.Position - origin).Magnitude > 400000 then break end
      if not launchedAt and part.Velocity.Magnitude > K.cfg.flungAt then
        launchedAt = tick()
        burn.at, burn.lastT = launchedAt, launchedAt
        burn.last = part.Velocity.Magnitude
      end

      local before = part.Velocity.Magnitude
      angle = angle + 100
      local a = CFrame.Angles(math.rad(angle), 0, 0)

      -- the horizontal offsets rotate with the phase; the vertical pair does not,
      -- because rotating a purely vertical offset produces the same offset
      local th = phase * math.pi * 2
      local c, sn = math.cos(th), math.sin(th)
      local function rot(x, z) return x * c - z * sn, x * sn + z * c end

      local x1, z1 = rot(rad, -rad)
      local x2, z2 = rot(-rad, rad)
      local x3, z3 = rot(0, rad * 0.5)
      local x4, z4 = rot(0, -rad * 0.5)

      if not place(part, CFrame.new(0, lift, 0), a) then break end   task.wait()
      if not place(part, CFrame.new(0, -lift, 0), a) then break end  task.wait()
      if not place(part, CFrame.new(x1, 0, z1), a) then break end task.wait()
      if not place(part, CFrame.new(x2, 0, z2), a) then break end task.wait()
      if not place(part, CFrame.new(x3, 0, z3), a) then break end task.wait()
      if not place(part, CFrame.new(x4, 0, z4), a) then break end task.wait()

      cycles = cycles + 1
      -- Written unconditionally, so a run with adaptation OFF is still
      -- attributable to contactWork. Without this an A/B comparison cannot
      -- prove which technique produced the number it is reporting.
      K.lastContact = { cycles = cycles, radius = rad,
                        adaptive = K.cfg.adaptive ~= false,
                        frozen = launchedAt ~= nil }
      -- ADAPTATION FREEZES AT LAUNCH, and the first live A/B is what found this.
      --
      -- The search reads a cycle that produced no speed gain as "these offsets
      -- are missing, widen and rotate". That inference is only valid while the
      -- target is still standing in front of us. Once they are airborne, every
      -- subsequent cycle scores dry for the trivial reason that they have left --
      -- so the radius walked all the way to its cap chasing contact that was
      -- never coming back. Measured: 0.64 -> 1.60, pinned at the ceiling.
      --
      -- After launch the geometry that worked is the geometry to keep.
      if K.cfg.adaptive ~= false and not launchedAt then
        local gain = part.Velocity.Magnitude - before
        if gain > bestGain then bestGain = gain end
        if gain < (K.cfg.adaptGain or 25) then
          dry = dry + 1
          phase = (phase + 0.618) % 1
          if dry >= 2 then
            rad = math.min(rad * 1.18, radMax)
            dry = 0
          end
        else
          dry = 0
          rad = math.max(0.35, rad * 0.94)
        end
        K.lastAdapt = { radius = rad, phase = phase, cycles = cycles,
                        bestGain = bestGain, base = baseRadius, cap = radMax }
      end
    until (launchedAt and burnDone(burn, part.Velocity.Magnitude, tick()))
        or tick() > t0 + K.cfg.flingDuration
        or not K.flinging or not L.live()
        or (thum and thum.Sit) or hum.Health <= 0
  end

  local function work(part)
    local t0 = tick()
    local angle = 0
    local R, LIFT = K.cfg.orbitRadius, K.cfg.orbitLift
    -- when they FIRST cross the release speed. We do not stop here any more --
    -- we keep slamming for the afterburn window, which is where most of the
    -- final launch speed comes from.
    local launchedAt, burn = nil, newBurn()
    -- Stop feeding them once they are this far from where they started. It only
    -- stops the loop ADDING energy -- it cannot retract momentum they already
    -- carry, since contact is the only authority we have over their assembly.
    -- Measured: at 6000 with 1.5s of afterburn they peaked at 24,744 studs/s
    -- and coasted 112,327 studs with this check in place, because by the time
    -- it fired the speed was already delivered.
    --
    -- So it is an early-out that stops wasting frames on somebody already
    -- launched into the distance, not a power cap. It sits far enough out that
    -- it never truncates a throw the operator actually asked for.
    local origin = part.Position
    local SAFE_TRAVEL = 400000
    repeat
      if (part.Position - origin).Magnitude > SAFE_TRAVEL then break end
      if not launchedAt and part.Velocity.Magnitude > K.cfg.flungAt then
        launchedAt = tick()
        burn.at, burn.lastT = launchedAt, launchedAt
        burn.last = part.Velocity.Magnitude
      end
      if not (root and thum and root.Parent and part.Parent) then break end
      -- Prediction moves the centre; speed must never inflate the contact
      -- radius. The previous high-speed path used WalkSpeed/velocity as world-Z
      -- offsets and deliberately teleported tens of studs away from the body.
      angle = angle + 100
      local a = CFrame.Angles(math.rad(angle), 0, 0)
      local radius = math.clamp(R, 0.35, K.cfg.contactEnvelope or 1.25)
      if not place(part, CFrame.new(0, LIFT, 0), a) then break end  task.wait()
      if not place(part, CFrame.new(0, -LIFT, 0), a) then break end task.wait()
      if not place(part, CFrame.new(radius, 0, -radius), a) then break end task.wait()
      if not place(part, CFrame.new(-radius, 0, radius), a) then break end task.wait()
      if not place(part, CFrame.new(0, 0, radius * 0.5), a) then break end task.wait()
      if not place(part, CFrame.new(0, 0, -radius * 0.5), a) then break end task.wait()
    until ((part.Position - origin).Magnitude > K.SANE_LIMIT)
        or (launchedAt and burnDone(burn, part.Velocity.Magnitude, tick()))
        or part.Parent ~= target.Character
        or target.Parent ~= Players
        or (thum and thum.Sit)
        or hum.Health <= 0
        or not K.flinging or not L.live()
        or tick() > t0 + K.cfg.flingDuration
  end

  -- ---- OVERFLOW ----------------------------------------------------------
  --
  -- Roblox's security docs describe setting velocities to "extreme values
  -- (including Inf or NaN)" to "interfere with the physics of other unanchored
  -- parts/assemblies, even those that are not owned by the exploiter" -- and
  -- name flinging as the use. The first clause is out of date on this engine
  -- build and the second is not.
  --
  -- MEASURED, because the docs imply Inf still works and it does not: writing
  -- math.huge is ACCEPTED without error and then silently sanitised to about
  -- 6.5e-6, i.e. zero. NaN likewise. So the literal documented vector is dead.
  --
  -- Enormous FINITE values are not. Walking the ladder: 1e7, 9e7, 1e9, 1e12 and
  -- 1e18 all stick exactly (1e18 reads back 1.732e18 = 1e18*sqrt(3)); only at
  -- 1e25 and above does the magnitude readout overflow, and 1e37 comes back
  -- NaN. 1e18 is therefore the top of the range that is both accepted and
  -- readable -- ten orders of magnitude above what the other variants write.
  local function infWork(part)
    local t0 = tick()
    local angle = 0
    local origin = part.Position
    local INF = 1e18
    repeat
      if not (root and root.Parent and part.Parent) then break end
      observeTargetSpeed(part)
      if (part.Position - origin).Magnitude > 400000 then break end
      forceCollide()
      angle = angle + 100
      local a = CFrame.Angles(math.rad(angle), 0, 0)
      for _, off in ipairs({
        CFrame.new(0, K.cfg.orbitLift, 0),
        CFrame.new(0, -K.cfg.orbitLift, 0),
        CFrame.new(2.25 * K.cfg.orbitRadius, K.cfg.orbitLift, -2.25 * K.cfg.orbitRadius),
      }) do
        if not attemptActive() then break end
        local cf = CFrame.new(aimAt(part)) * off * a
        root.CFrame = cf
        pcall(function() root.AssemblyLinearVelocity = Vector3.new(INF, INF, INF) end)
        pcall(function() root.AssemblyAngularVelocity = Vector3.new(INF, INF, INF) end)
        RS.Heartbeat:Wait()
      end
    until part.Velocity.Magnitude > K.cfg.flungAt
        or tick() > t0 + K.cfg.flingDuration
        or not K.flinging or not L.live()
        or (thum and thum.Sit)
  end

  -- ---- CONSTRAINT --------------------------------------------------------
  --
  -- The same violence, delivered by an actuator instead of a property write.
  -- An AngularVelocity constraint spins the assembly toward a target angular
  -- velocity under a FINITE MaxTorque, which is the whole point: the raw
  -- `RotVelocity = 9e8` write has no ceiling and is what threw the operator two
  -- billion studs in the touch-fling attempts. A torque budget cannot do that --
  -- the solver refuses to exceed it, so the failure mode is "not enough spin"
  -- rather than "you are now in orbit".
  --
  -- BodyAngularVelocity is the legacy of this and still works, but it is
  -- deprecated and the constraint takes the same job with an explicit bound.
  local function constraintWork(part)
    local t0 = tick()
    local origin = part.Position

    local att = Instance.new("Attachment")
    att.Name = "LumenSpinAt"
    att.Parent = root

    local av = Instance.new("AngularVelocity")
    av.Name = "LumenSpin"
    av.Attachment0 = att
    av.RelativeTo = Enum.ActuatorRelativeTo.World
    -- Back at full strength now the infinite-force mover is off this path. At
    -- these values it measured the best peak of any variant, 29,293 studs/s;
    -- the 13,114,016 studs of operator drift recorded alongside it was the
    -- mover, not the torque. MaxTorque stays finite so the failure mode is a
    -- weak spin rather than a launch.
    av.AngularVelocity = Vector3.new(9e5, 9e5, 9e5)
    av.MaxTorque = 1e9
    av.ReactionTorqueEnabled = false
    av.Parent = root
    L.own(av) L.own(att)

    local launchedAt, burn = nil, newBurn()
    repeat
      if not (root and root.Parent and part.Parent) then break end
      observeTargetSpeed(part)
      if (part.Position - origin).Magnitude > 400000 then break end
      if not launchedAt and part.Velocity.Magnitude > K.cfg.flungAt then
        launchedAt = tick()
        burn.at, burn.lastT = launchedAt, launchedAt
        burn.last = part.Velocity.Magnitude
      end
      if launchedAt and burnDone(burn, part.Velocity.Magnitude, tick()) then break end
      forceCollide()
      -- ride them: position from a teleport, spin from the constraint, so the
      -- two never fight over the same channel
      root.CFrame = CFrame.new(aimAt(part))
        + Vector3.new(0, K.cfg.orbitLift * 0.4, 0)
      RS.Heartbeat:Wait()
    until tick() > t0 + K.cfg.flingDuration
        or not K.flinging or not L.live()
        or (thum and thum.Sit)

    pcall(function() av:Destroy() end)
    pcall(function() att:Destroy() end)
  end

  -- ---- VOID DROP ---------------------------------------------------------
  --
  -- The same contact, aimed DOWN rather than across. Cheaper than throwing
  -- somebody across a map because it does not have to beat their ground
  -- controller for long -- once they are under the floor the map does the rest.
  -- set by any worker that cannot start; read after run() returns
  local refusal

  -- ---- REP-ROOT ----------------------------------------------------------
  --
  -- The reference hub's shape, with the parts that were leaving power on the
  -- table fixed:
  --
  --   it re-asserted the hidden property EVERY Heartbeat. It only has to be set
  --   once; re-asserting 60 times a second is 60 hidden-property writes for one
  --   binding. Set here, re-checked only if something clears it.
  --
  --   it wrote `Velocity` and `RotVelocity`, which are the deprecated aliases.
  --   On a multi-part assembly those touch one part; AssemblyLinearVelocity and
  --   AssemblyAngularVelocity move the whole body, which is what is being
  --   replicated.
  --
  --   it used a fixed (500, 500, 500) -- an unaimed diagonal of magnitude 866.
  --   Aimed along the camera and scaled to repPower instead, so they go where
  --   you are looking rather than north-east-up every time.
  --
  --   it never alternated the spin. A constant angular velocity gets damped;
  --   flipping its sign every frame keeps pumping energy in, which is the same
  --   trick the contact path already uses.
  local function repAimVector()
    local cam = workspace.CurrentCamera
    local look = (cam and cam.CFrame.LookVector) or Vector3.new(0, 0, -1)
    local flat = Vector3.new(look.X, 0, look.Z)
    if flat.Magnitude < 0.05 then flat = Vector3.new(0, 0, -1) end
    flat = flat.Unit
    local lift = math.clamp(K.cfg.repLift or 0.55, 0, 1)
    local dir = (flat * (1 - lift) + Vector3.new(0, 1, 0) * lift)
    if dir.Magnitude < 0.05 then dir = Vector3.new(0, 1, 0) end
    return dir.Unit * (K.cfg.repPower or 9e7)
  end

  local function repWork(part)
    if not K.repAvailable() then
      refusal = "this executor has no sethiddenproperty"
      return
    end
    local t0 = tick()
    local origin = part.Position
    local bound = repBind(root, part)
    if not bound then refusal = "rep-root write refused" return end

    -- lying down, the way the reference does it: a pitched root defeats the
    -- upright standing controller and puts our collision box through theirs
    local LAY = CFrame.Angles(-math.pi / 2, 0, 0)
    local flip, spin = 1, K.cfg.repSpin or 9e8
    local launchedAt, burn = nil, newBurn()

    repeat
      if not (root and root.Parent and part.Parent) then break end
      if (part.Position - origin).Magnitude > K.SANE_LIMIT then break end
      observeTargetSpeed(part)

      -- re-bind only if something cleared it, not once a frame
      if repRead(root) ~= part then repBind(root, part) end

      local thrust = repAimVector()
      root.CFrame = CFrame.new(aimAt(part)) * LAY
      root.AssemblyLinearVelocity = thrust
      root.AssemblyAngularVelocity = Vector3.new(spin * flip, spin * flip, spin * flip)
      flip = -flip

      if not launchedAt and part.AssemblyLinearVelocity.Magnitude > K.cfg.flungAt then
        launchedAt = tick()
        burn.at, burn.lastT = launchedAt, launchedAt
        burn.last = part.AssemblyLinearVelocity.Magnitude
      end
      RS.Heartbeat:Wait()
      if not attemptActive() then break end
    until (launchedAt and burnDone(burn, part.AssemblyLinearVelocity.Magnitude, tick()))
        or tick() > t0 + K.cfg.flingDuration
        or not K.flinging or not L.live()
        or (thum and thum.Sit) or hum.Health <= 0

    repBind(root, root)
  end

  -- The rocket variants, which are the same binding used as one impulse rather
  -- than a sustained state. The reference fired 50 and called the 5000 version
  -- GODSPEED; both are tiny next to what the stream will carry, so this is one
  -- hard shove at repPower and then out -- short enough that anti-cheat has
  -- little to average over.
  local function repBurstWork(part)
    if not K.repAvailable() then
      refusal = "this executor has no sethiddenproperty"
      return
    end
    if not repBind(root, part) then refusal = "rep-root write refused" return end
    local LAY = CFrame.Angles(-math.pi / 2, 0, 0)
    local thrust = repAimVector()
    local spin = K.cfg.repSpin or 9e8
    local t0 = tick()
    local flip = 1
    repeat
      if not (root and root.Parent and part.Parent) then break end
      observeTargetSpeed(part)
      root.CFrame = CFrame.new(part.Position + Vector3.new(0, -3, 0)) * LAY
      root.AssemblyLinearVelocity = thrust
      root.AssemblyAngularVelocity = Vector3.new(spin * flip, spin * flip, spin * flip)
      flip = -flip
      RS.Heartbeat:Wait()
      if not attemptActive() then break end
    until tick() > t0 + math.min(0.30, K.cfg.flingDuration)
        or not K.flinging or not L.live()
    repBind(root, root)
  end

  -- NaN through the rep stream. The reference put NaN in the velocity and called
  -- Humanoid:Move(NaN) with PlatformStand on. NaN propagates through the physics
  -- solver, so a body that receives it has no valid position to resolve to and
  -- the engine ejects it. Kept because it lands in places the others do not --
  -- but it is genuinely unpredictable, so it is bounded hard and always the last
  -- thing tried.
  local function repNanWork(part)
    if not K.repAvailable() then
      refusal = "this executor has no sethiddenproperty"
      return
    end
    if not repBind(root, part) then refusal = "rep-root write refused" return end
    local nan = 0 / 0
    local nanV = Vector3.new(nan, nan, nan)
    local t0 = tick()
    hum.PlatformStand = true
    repeat
      if not (root and root.Parent and part.Parent) then break end
      root.CFrame = part.CFrame
      root.AssemblyLinearVelocity = nanV
      root.AssemblyAngularVelocity = nanV
      pcall(function() hum:Move(nanV) end)
      RS.Heartbeat:Wait()
      if not attemptActive() then break end
    until tick() > t0 + math.min(1.5, K.cfg.flingDuration)
        or not K.flinging or not L.live()
    repBind(root, root)
    -- NaN in our own assembly would follow us out of the attempt
    pcall(function()
      root.AssemblyLinearVelocity = Vector3.zero
      root.AssemblyAngularVelocity = Vector3.zero
    end)
  end

  local function voidWork(part)
    local t0 = tick()
    local origin = part.Position
    repeat
      if not (root and root.Parent and part.Parent) then break end
      observeTargetSpeed(part)
      forceCollide()
      -- sit directly above them and drive straight down through the floor
      local cf = CFrame.new(aimAt(part) + Vector3.new(0, K.cfg.orbitLift * 2, 0))
      root.CFrame = cf
      root.Velocity = Vector3.new(0, -9e7, 0)
      root.RotVelocity = Vector3.new(9e8, 9e8, 9e8)
      RS.Heartbeat:Wait()
      if not attemptActive() then break end
      root.CFrame = cf * CFrame.new(0, -K.cfg.orbitLift * 3, 0)
      root.Velocity = Vector3.new(0, -9e7, 0)
      RS.Heartbeat:Wait()
    until (part.Position.Y < origin.Y - 120)
        or tick() > t0 + K.cfg.flingDuration
        or not K.flinging or not L.live()
        or (thum and thum.Sit)
  end

  local mode = K.cfg.flingAttach
  if mode == LEGACY_LATCH then mode = LATCH end
  -- "Massless rig" was renamed to "Heavy rig" when the measurement showed the
  -- rig was shedding mass to hit harder, which is backwards. A saved profile
  -- still holding the old name must land on the mode, not fall through to nil.
  if mode == "Massless rig" then mode = MASSLESS end
  session.tried[mode] = true

  -- Transaction snapshot. Every mutation below is undone by one idempotent
  -- finalizer on success, refusal, exception, cancellation, death or reload.
  local seatedWas = true
  pcall(function() seatedWas = hum:GetStateEnabled(Enum.HumanoidStateType.Seated) end)
  local snap = {
    -- the reference hub never restores this and leaks a rep-root pointing at a
    -- player who may have left; it is part of the transaction here
    repRoot = repRead(root),
    fpdh = workspace.FallenPartsDestroyHeight,
    physical = root.CustomPhysicalProperties,
    platform = hum.PlatformStand,
    seated = seatedWas,
    camera = attemptCamera,
    cameraSubject = camSubject,
    character = ch,
    humanoid = hum,
    moveEpoch = L.Move and L.Move.physicsEpoch and {
      physical = L.Move.physicsEpoch.physical,
      platform = L.Move.physicsEpoch.platform,
    } or nil,
  }
  local bv, cleaned, suspendedByUs, noclipByUs = nil, false, false, false
  local cameraOverride, returnTicket

  -- THE HANDLE IS RELEASED FIRST, AND THAT ORDER IS THE WHOLE BUG.
  --
  -- `K.activeCleanup = nil` used to live at the BOTTOM of this function, past
  -- forty lines of restoration. Every one of those lines is individually
  -- pcall-ed, so the usual failures are absorbed -- but anything that threw
  -- outside a pcall (an indexing error on a torn-down epoch, most plausibly)
  -- landed after `cleaned = true` and before the release. From then on:
  --
  --   K.activeCleanup   still points at this closure, forever
  --   stopFling         calls it, hits `if cleaned then return end`, no-ops
  --   startFling        sees activeCleanup set, waits 4 s, refuses
  --   every later try   refuses again, with the same message
  --
  -- Which is exactly the reported shape: one failed fling and the button is
  -- dead for the rest of the session, logging "previous fling is still
  -- recovering" over and over. Releasing the handle FIRST means a throw during
  -- restoration costs one attempt's worth of restoration, not the feature.
  local function cleanup(shouldReturn)
    attemptCancelled = true
    if K.activeCleanup == cleanup then K.activeCleanup = nil end
    if cleaned then
      if not shouldReturn then cancelReturnHome() end
      return returnTicket
    end
    cleaned = true
    if not shouldReturn then cancelReturnHome() end
    local currentEpoch = L.Move and L.Move.physicsEpoch
    local physicalChanged = snap.moveEpoch and currentEpoch
      and currentEpoch.physical ~= snap.moveEpoch.physical
    local platformChanged = snap.moveEpoch and currentEpoch
      and currentEpoch.platform ~= snap.moveEpoch.platform
    if bv then
      local ownedMover = bv
      bv = nil
      pcall(function() ownedMover:Destroy() end)
    end
    pcall(function()
      for _, name in ipairs({ "LumenSpin", "LumenSpinAt", "LumenThrow" }) do
        local item = root:FindFirstChild(name)
        if item then item:Destroy() end
      end
      root.AssemblyLinearVelocity = Vector3.zero
      root.AssemblyAngularVelocity = Vector3.zero
    end)
    -- Zero first, then restore mass/properties; restoring a fast massless rig is
    -- the measured runaway shape.
    pcall(rigMassless, false, not physicalChanged)
    for d, was in pairs(collideWas) do
      pcall(function()
        if d.Parent then d.CanCollide = was end
      end)
    end
    pcall(function()
      if root.Parent and not physicalChanged then
        root.CustomPhysicalProperties = snap.physical
      end
    end)
    pcall(function()
      if hum.Parent == ch then
        if not platformChanged then hum.PlatformStand = snap.platform end
        hum:SetStateEnabled(Enum.HumanoidStateType.Seated, snap.seated)
      end
    end)
    -- Do not write an old subject into a replacement camera or character epoch,
    -- and do not overwrite another feature that took the camera after us.
    pcall(function()
      if snap.camera and workspace.CurrentCamera == snap.camera
         and LP.Character == snap.character and snap.humanoid.Parent == snap.character then
        local subject = snap.cameraSubject
        local subjectExists = subject == nil
          or (typeof(subject) == "Instance" and subject.Parent ~= nil)
        if subjectExists and (cameraOverride == nil or snap.camera.CameraSubject == cameraOverride) then
          snap.camera.CameraSubject = subject
        end
      end
    end)
    -- released before anything else that touches physics: while this points at
    -- somebody else every velocity we write is still landing on their body
    pcall(function()
      if root and root.Parent then repBind(root, snap.repRoot or root) end
    end)
    pcall(function() workspace.FallenPartsDestroyHeight = snap.fpdh end)
    if suspendedByUs and L.Move and L.Move.resumeBlock then
      pcall(L.Move.resumeBlock, "fling")
    end
    suspendedByUs = false
    if noclipByUs and L.Universal and L.Universal.resumeNoclip then
      pcall(L.Universal.resumeNoclip, "fling")
    end
    noclipByUs = false
    -- (the handle was already released at the top -- see the note there)
    -- Only after every synchronous ownership channel is released may the
    -- generation-bound return routine begin moving this same character.
    if shouldReturn and L.live() and K.flinging and K.runSerial == runSerial
       and LP.Character == ch and root.Parent and hum.Parent == ch and hum.Health > 0 then
      returnTicket = scheduleReturnHome(ch, hum, root, home, runSerial)
    end
    return returnTicket
  end
  K.activeCleanup = cleanup

  local setupOK, setupWhy = pcall(function()
    -- Our own anti-fling removes the contact channel. Suspend only a block we
    -- own, preserving an already-suspended state from another feature.
    if L.Move and L.Move.suspendBlock then
      suspendedByUs = L.Move.suspendBlock("fling") == true
    end
    if L.Universal and L.Universal.suspendNoclip then
      noclipByUs = L.Universal.suspendNoclip("fling") == true
    end
    if root.CustomPhysicalProperties then root.CustomPhysicalProperties = nil end
    workspace.FallenPartsDestroyHeight = 0 / 0
    if attemptCamera and workspace.CurrentCamera == attemptCamera then
      cameraOverride = thead or handle or thum
      attemptCamera.CameraSubject = cameraOverride
    end
  end)
  if not setupOK then cleanup(false) return false, tostring(setupWhy) end
  -- The infinite-force mover is allowlisted later for Teleport, Massless and
  -- Overflow only. Contact lock, Constraint and Void must never inherit it.
  -- ---- APPROACH AND SETTLE ----------------------------------------------
  --
  -- THE SINGLE BIGGEST FACTOR IN WHETHER A FLING LANDS, and it is not power.
  -- Measured against the same target, same technique, same run -- the only
  -- difference being whether we closed the distance and waited a beat first:
  --
  --     struck from 214 studs :  peak     16 st/s,       5 studs thrown
  --     closed, settled 1.5s  :  peak 25,430 st/s, 101,476 studs thrown
  --
  -- Roblox hands network ownership of unanchored parts to clients with NEARBY
  -- characters. Arriving is not enough: the victim's machine has to actually
  -- see us standing next to them before a contact against our body is resolved
  -- by their client, and their client's result is the authoritative one. Strike
  -- before that has propagated and every placement lands on a body nobody else
  -- believes we are touching.
  --
  -- The travel itself is instant -- one CFrame write -- so the only cost is the
  -- settle, and that is charged only when we actually came from far away.
  local function approach(part)
    if not (part and part.Parent and root and root.Parent) then
      return false, "approach parts disappeared"
    end
    -- SETTLE SCALES WITH HOW FAR WE CAME, because that is what it is paying for.
    --
    -- The wait exists so the victim's machine sees us arrive before we start
    -- hitting them, and the further we jumped the more there is to propagate.
    -- A flat figure has to be sized for the worst case, which makes every
    -- close-range fling needlessly slow.
    --
    -- Measured across repeats: 0.5s landed 2/2 (peaks 23,275 and 40,279, throws
    -- of 101,720 and 111,649 studs); 0.2s landed 1/2; and the old 1.2s default
    -- was simply paying a second of delay for nothing. Distance, not patience,
    -- is what actually decided it.
    local gap = (root.Position - part.Position).Magnitude
    local base = math.max(K.cfg.approachSettle or 0.5, 0.01)
    local distanceScale = math.clamp(gap / 120, 0, 1)
    local settle = base * (0.35 + distanceScale * 1.25)

    -- A FLOOR, BECAUSE ZERO IS NOT A SETTING, IT IS A BREAKAGE.
    --
    -- The slider reaches 0 and a saved 0 was restored from a previous session:
    -- every engagement then skipped the wait entirely and measured 0/3 landed,
    -- peak 0, with nothing in the interface suggesting why. Somebody who has
    -- once dragged this to the bottom would conclude the fling is broken.
    --
    -- Close range genuinely needs almost nothing, so the floor there is token.
    -- Beyond that it is the mechanism the whole technique rests on, so it gets
    -- the least that was ever observed to work.
    -- Continuous reliability floor: 0.05 while already touching, rising to the
    -- measured 0.25 minimum by 25 studs without a 24.9/25-stud discontinuity.
    settle = math.max(settle, 0.05 + math.clamp(gap / 25, 0, 1) * 0.20)
    local elapsed, held = 0, 0
    while K.flinging and L.live() and part.Parent and root.Parent and elapsed < settle do
      forceCollide()
      local wanted = aimAt(part) + Vector3.new(0, 0, 3)
      local ok = pcall(function()
        root.CFrame = CFrame.new(wanted)
        root.AssemblyLinearVelocity = Vector3.zero
        root.AssemblyAngularVelocity = Vector3.zero
      end)
      if not ok then return false, "approach placement failed" end
      local dt = RS.Heartbeat:Wait()
      elapsed = elapsed + dt
      if (root.Position - wanted).Magnitude <= 2 then held = held + dt else held = 0 end
    end
    if not K.flinging or not L.live() then return false, "cancelled" end
    if not part.Parent or not root.Parent then return false, "approach identity changed" end
    if held < math.min(0.10, settle * 0.35) then return false, "approach never held" end
    return true
  end

  local strikeStartPos, strikeStartedAt, baselineVelocity, baselineSpeed, baselineConfidence
  local runOK, runWhy = xpcall(function()
    local handleFor = troot or thead or handle
    if not handleFor then refusal = "target has no stable hit part" return end
    local approached, approachWhy = approach(handleFor)
    if not approached then refusal = approachWhy return end
    strikeStartPos = markPart and markPart.Parent and markPart.Position or nil
    strikeStartedAt = os.clock()
    baselineVelocity = lead.velocity()
    baselineSpeed = baselineVelocity.Magnitude
    if baselineSpeed ~= baselineSpeed or baselineSpeed == math.huge then
      baselineVelocity, baselineSpeed = Vector3.zero, 0
    end
    baselineConfidence = K.predictConfidence or 0

    -- Infinite-force movement is restricted to variants that reassert CFrame
    -- several times per frame. Contact lock and constraint spin never receive it.
    -- rep-root writes AssemblyLinearVelocity directly into the replicated
    -- assembly; a BodyVelocity fighting it on our own root only muddies what
    -- gets sent
    if mode == TELE or mode == MASSLESS or mode == INFV then
      bv = Instance.new("BodyVelocity")
      bv.Name = "LumenThrow"
      bv.Velocity = Vector3.new(9e8, 9e8, 9e8)
      bv.MaxForce = Vector3.new(1 / 0, 1 / 0, 1 / 0)
      bv.Parent = root
      L.own(bv)
    end

    if mode == MASSLESS or mode == INFV then rigMassless(true) end
    hum:SetStateEnabled(Enum.HumanoidStateType.Seated, false)
    hum.PlatformStand = true

    local runners = {
      [TELE]     = work,
      [LATCH]    = contactWork,
      [MASSLESS] = work,
      [INFV]     = infWork,
      [VOID]     = voidWork,
      [CONSTR]   = constraintWork,
      [REP]      = repWork,
      [REPBURST] = repBurstWork,
      [REPNAN]   = repNanWork,
    }
    local run = runners[mode] or work
    if troot and thead and (troot.Position - thead.Position).Magnitude > 5 then
      run(thead)
    elseif troot then run(troot)
    elseif thead then run(thead)
    elseif handle then run(handle)
    else refusal = "target parts disappeared" end
  end, function(err) return tostring(err) end)

  observeTargetSpeed(markPart)
  local homeTicket = cleanup(true)
  waitForReturnHome(homeTicket)
  if not runOK then K.lastThrow = 0 return false, runWhy end
  if refusal then K.lastThrow = 0 return false, refusal end

  -- ---- did it actually work? -------------------------------------------
  --
  -- A technique that lands in one game does nothing in the next -- different
  -- character controllers, anti-fling, ownership, ragdoll systems. Rather than
  -- make the operator diagnose that, measure the one observable that settles it
  -- and move down the list. This is why the variants exist at all.
  local rawMoved, residualMoved, moved = 0, 0, 0
  local characterStable = target.Character == tch
  if characterStable and strikeStartPos and markPart and markPart.Parent then
    local delta = markPart.Position - strikeStartPos
    local d = delta.Magnitude
    if d == d and d < math.huge then
      rawMoved = d
      local elapsedNow = strikeStartedAt and math.max(os.clock() - strikeStartedAt, 0) or 0
      residualMoved = (delta - (baselineVelocity or Vector3.zero) * elapsedNow).Magnitude
    end
  end
  local elapsed = strikeStartedAt and math.max(os.clock() - strikeStartedAt, 0) or 0
  -- Endpoint distance alone calls a fast runner a successful throw. Require a
  -- contact-correlated speed spike, then subtract the full baseline velocity
  -- vector (not a capped scalar distance) from the observed displacement.
  local speedGain = math.max(0, peakVisibleSpeed - (baselineSpeed or 0))
  local spikeFloor = math.max(120, (baselineSpeed or 0) * 0.75)
  local contactSpike = speedGain >= spikeFloor
    and ((baselineConfidence or 0) >= 0.5 or peakVisibleSpeed >= 500)
  moved = contactSpike and residualMoved or 0
  K.lastThrow = moved
  K.lastThrowEvidence = {
    observedDisplacement = rawMoved,
    predictedLocomotion = (baselineVelocity or Vector3.zero) * elapsed,
    residualDisplacement = residualMoved,
    contactCorrelated = contactSpike,
    locomotionAdjusted = moved,
    baselineSpeed = baselineSpeed or 0,
    baselineConfidence = baselineConfidence or 0,
    visibleSpeedGain = speedGain,
    peakAttackerVisibleSpeed = peakVisibleSpeed,
    characterStable = characterStable,
    authoritative = false,
  }

  if K.cfg.autoFallback and moved < K.cfg.fallbackAt and K.flinging then
    -- Explicit tried-set: every fallback is attempted at most once, regardless
    -- of whether the operator began on Contact lock or Constraint spin.
    local cur, nextMode = mode, nil
    for _, candidate in ipairs(FALLBACK_ORDER) do
      if not session.tried[candidate] then nextMode = candidate break end
    end
    if nextMode and nextMode ~= cur then
      L.note("fling", string.format(
        "%s showed %d adjusted studs locally -- trying %s",
        cur, math.floor(moved), nextMode))
      local fallbackResult = table.pack(xpcall(function()
        K.cfg.flingAttach = nextMode
        task.wait(0.2)
        if not K.flinging or not L.live() then return false, "cancelled" end
        return flingOne(target, depth + 1, session)
      end, function(err) return tostring(err) end))
      K.cfg.flingAttach = cur          -- the operator's choice is never overwritten
      if not fallbackResult[1] then
        return false, "fallback failed: " .. tostring(fallbackResult[2])
      end
      return table.unpack(fallbackResult, 2, fallbackResult.n)
    end
  end
  return true
end

-- ---------------------------------------------------------------- touch fling
--
-- THE PASSIVE ONE. Everything above picks somebody and goes to them; this waits
-- for them to come to you, which is the right shape for a crowded lobby or for
-- anyone who walks up to you first.
--
-- The mechanism is the same contact impulse, minus the travel: carry an absurd
-- angular velocity so any collision resolves violently, then re-assert your own
-- position every frame so the spin throws THEM and not you. That snap-back is
-- what separates this from simply spinning yourself into orbit -- the velocity
-- lives just long enough for the physics step to use it, and is undone before
-- it can move you anywhere.
-- MEASURED FAILURE THAT SHAPED THIS. The first version wrote the spin and then
-- restored `root.CFrame = CFrame.new(root.Position)` on Heartbeat. Heartbeat
-- runs AFTER the physics step, so the position it read had already been moved
-- by the velocity it was meant to cancel -- the anchor chased the runaway and
-- fed it. Measured drift: 2,065,836,160 studs in ninety frames. It is the exact
-- feedback shape that sent welded targets thirty million studs out.
--
-- So the anchor is captured PRE-physics on Stepped, and enforced POST-physics on
-- Heartbeat, and only when the frame's displacement is too large to be walking.
-- Ordinary movement passes through untouched; a spin-driven launch does not.
local touchConns = {}
local touchCollide = {}
local touchRoots = {}
local touchBlockHeld, touchNoclipHeld = false, false

local function restoreTouchRoot(root, state)
  if not (root and root.Parent and state) then return end
  local restoreAnchor = not L.Move or not L.Move.physicsEpoch
    or state.anchoredEpoch == L.Move.physicsEpoch.anchored
  if restoreAnchor and not state.anchored then
    pcall(function() root.Anchored = false end)
  end
  pcall(function() root.CFrame = CFrame.new(root.Position) * state.rotation end)
  if restoreAnchor and state.anchored then
    pcall(function() root.Anchored = true end)
  end
  pcall(function()
    root.AssemblyAngularVelocity = Vector3.zero
    root.AssemblyLinearVelocity = Vector3.zero
  end)
end

local function pruneTouchEpoch(character, currentRoot)
  for part, was in pairs(touchCollide) do
    if not part.Parent or not part:IsDescendantOf(character) then
      if part.Parent then pcall(function() part.CanCollide = was end) end
      touchCollide[part] = nil
    end
  end
  for oldRoot, state in pairs(touchRoots) do
    if oldRoot ~= currentRoot then
      restoreTouchRoot(oldRoot, state)
      touchRoots[oldRoot] = nil
    end
  end
end

local function conflictingPhysicsFeature()
  local universal, movement = L.Universal, L.Move
  if universal and universal.want and universal.want.fly then return "Fly" end
  if movement and movement.want then
    if movement.want.freeze then return "Freeze" end
    if movement.want.spin then return "Spinbot" end
    if movement.want.invis
       and movement.cfg.invisMethod == "Park (hide from everyone)" then
      return "Park invisibility"
    end
  end
  return nil
end

local function mm2PhysicsBusyReason()
  local mm2 = L.MM2
  if not mm2 then return nil end
  if mm2.relocating then return "wait for the MM2 relocation to finish" end
  if mm2.shotPreparing then return "wait for the MM2 shot preparation to finish" end
  return nil
end

function K.setTouchFling(on)
  on = on and true or false
  local mm2Busy = on and mm2PhysicsBusyReason()
  if mm2Busy then return false, mm2Busy end
  if on and (K.flinging or K.activeCleanup or flingRunner or K.returningHome) then
    return false, "targeted fling is active or still recovering"
  end
  -- A watchdog/UI re-apply is a fresh transaction: release our existing tokens
  -- before reacquiring them, otherwise a duplicate `true` loses token ownership.
  if on and K.want.touchFling then K.setTouchFling(false) end
  K.want.touchFling = on
  for _, c in ipairs(touchConns) do pcall(function() c:Disconnect() end) end
  touchConns = {}

  if not K.want.touchFling then
    for d, was in pairs(touchCollide) do
      if d.Parent then pcall(function() d.CanCollide = was end) end
    end
    touchCollide = {}
    for r, state in pairs(touchRoots) do
      restoreTouchRoot(r, state)
    end
    touchRoots = {}
    if touchBlockHeld and L.Move and L.Move.resumeBlock then
      pcall(L.Move.resumeBlock, "touchFling")
    end
    if touchNoclipHeld and L.Universal and L.Universal.resumeNoclip then
      pcall(L.Universal.resumeNoclip, "touchFling")
    end
    touchBlockHeld, touchNoclipHeld = false, false
    return true
  end

  local conflict = conflictingPhysicsFeature()
  if conflict then
    K.want.touchFling = false
    return false, "turn off " .. conflict .. " before touch fling"
  end
  if K.want.hitbox then restoreHitboxes() end
  if L.Move and L.Move.suspendBlock then
    touchBlockHeld = L.Move.suspendBlock("touchFling") == true
  end
  if L.Universal and L.Universal.suspendNoclip then
    touchNoclipHeld = L.Universal.suspendNoclip("touchFling") == true
  end

  -- ANCHORED, AND THAT IS THE WHOLE FIX.
  local spin = 0
  local hold, holdRoot

  touchConns[#touchConns + 1] = L.hold(RS.Heartbeat:Connect(function(dt)
    if not (L.live() and K.want.touchFling) then return end
    local ch = LP.Character
    local hum = ch and ch:FindFirstChildOfClass("Humanoid")
    local root = hum and hum.RootPart
    if not (ch and hum and root) then hold, holdRoot = nil, nil return end
    if hum.Health <= 0 then hold, holdRoot = nil, nil return end
    if holdRoot ~= root then
      pruneTouchEpoch(ch, root)
      hold, holdRoot = nil, root
    end

    -- no contact, no impulse: the same trap noclip sets for the targeted modes
    for _, d in ipairs(ch:GetDescendants()) do
      if d:IsA("BasePart") and d.Name ~= "HumanoidRootPart"
         and not d:FindFirstAncestorOfClass("Accessory") then
        if touchCollide[d] == nil then touchCollide[d] = d.CanCollide end
        if not d.CanCollide then d.CanCollide = true end
      end
    end

    if not hold then
      hold = root.Position
      if not touchRoots[root] then
        touchRoots[root] = {
          anchored = root.Anchored,
          rotation = root.CFrame.Rotation,
          anchoredEpoch = L.Move and L.Move.physicsEpoch
            and L.Move.physicsEpoch.anchored or nil,
        }
      end
      pcall(function()
        root.Anchored = true
      end)
    end
    spin = (spin + dt * 40) % (math.pi * 2)
    pcall(function()
      root.CFrame = CFrame.new(hold) * CFrame.Angles(spin * 1.7, spin, spin * 0.6)
    end)
  end))
  return true
end

-- ---- targets ---------------------------------------------------------

-- ---------------------------------------------------------------- diagnosis
--
-- WHY A FLING FAILED, ANSWERED RATHER THAN GUESSED. The two common defences
-- need opposite responses, so telling them apart is the whole game:
--
--   COLLISION DISABLED -- their character's parts are CanCollide = false, which
--     we can simply read. An impulse can only cross a contact, so there is no
--     amount of power that helps. More attempts are wasted effort and obvious
--     to anyone watching. Stop, and keep an eye on them: people toggle it off
--     to get through a door and forget, and the moment they do we resume.
--
--   COLLISION GROUP BLOCKED -- their limbs and ours are individually solid, but
--     PhysicsService says no pair of their active groups can contact ours. This
--     is the same no-channel outcome with a distinct, actionable diagnosis.
--
--   VELOCITY CLAMPED -- they collide normally but something pins their speed.
--     Here power IS the lever: each attempt lands, gets clamped, and the answer
--     is to come back harder until either it breaks through or the clamp is
--     provably tighter than anything we can deliver.
--
-- Anything else is "open" and should simply work.
K.DIAG = { OPEN = "locally open", COLLISION = "locally collision disabled",
           GROUP = "locally collision groups do not interact",
           CLAMPED = "local resistance",
           SEATED = "seated", GONE = "gone" }

-- CanCollide=true is not sufficient when the two rigs occupy non-interacting
-- collision groups. Ask PhysicsService about every distinct limb-group pair.
-- Executors/engine revisions that do not expose the API fail open: an absent
-- diagnostic must never become a false immunity verdict.
local function collisionGroupsPermit(targetCharacter)
  local ownCharacter = LP.Character
  if not (ownCharacter and targetCharacter) then return nil end
  local ok, result = pcall(function()
    local ownGroups, targetGroups = {}, {}
    for _, part in ipairs(ownCharacter:GetDescendants()) do
      if part:IsA("BasePart") and part.Name ~= "HumanoidRootPart"
         and not part:FindFirstAncestorOfClass("Accessory") then
        ownGroups[part.CollisionGroup] = true
      end
    end
    for _, part in ipairs(targetCharacter:GetDescendants()) do
      if part:IsA("BasePart") and part.Name ~= "HumanoidRootPart"
         and not part:FindFirstAncestorOfClass("Accessory") and part.CanCollide then
        targetGroups[part.CollisionGroup] = true
      end
    end
    if next(ownGroups) == nil or next(targetGroups) == nil then return nil end
    for ownGroup in pairs(ownGroups) do
      for targetGroup in pairs(targetGroups) do
        local collidable = PhysicsService:CollisionGroupsAreCollidable(ownGroup, targetGroup)
        if type(collidable) ~= "boolean" then return nil end
        if collidable then
          return true
        end
      end
    end
    return false
  end)
  if not ok then return nil end
  return result
end

function K.diagnose(p)
  local ch = p and p.Character
  if not (ch and p.Parent) then return K.DIAG.GONE end
  local hum = ch:FindFirstChildOfClass("Humanoid")
  local root = ch:FindFirstChild("HumanoidRootPart")
  if not (hum and root) then return K.DIAG.GONE end
  if hum.Health <= 0 then return K.DIAG.GONE end
  if hum.Sit or hum.SeatPart then return K.DIAG.SEATED end

  -- collidable surface area is what an impulse needs; the root is CanCollide
  -- false on every normal rig, so it is the limbs that matter
  local solid, total = 0, 0
  for _, d in ipairs(ch:GetDescendants()) do
    if d:IsA("BasePart") and d.Name ~= "HumanoidRootPart"
       and not d:FindFirstAncestorOfClass("Accessory") then
      total = total + 1
      if d.CanCollide then solid = solid + 1 end
    end
  end
  if total > 0 and solid == 0 then return K.DIAG.COLLISION end
  if collisionGroupsPermit(ch) == false then return K.DIAG.GROUP end
  return K.DIAG.OPEN
end

-- Anti-fling deliberately makes remote limbs non-collidable on this client.
-- Reading those values before releasing our own block would falsely label every
-- target immune and prevent flingOne from reaching its existing suspension.
-- Diagnose through a synchronous, nested token and fail open on unavailable
-- module/API state; the actual attempt acquires its own longer-lived token.
local function diagnoseForEngagement(p)
  local movement = L.Move
  local held = false
  if movement and movement.suspendBlock and movement.resumeBlock then
    local ok, acquired = pcall(movement.suspendBlock, "flingDiagnosis")
    held = ok and acquired == true
  end
  local ok, verdict = pcall(K.diagnose, p)
  if held and movement and movement.resumeBlock then
    pcall(movement.resumeBlock, "flingDiagnosis")
  end
  if not ok or verdict == nil then return K.DIAG.OPEN end
  return verdict
end

-- Remembers what we learned per player, so a second attempt is not a repeat of
-- the first. Keyed by name because characters are replaced on respawn.
K.intel = {}
local function intelFor(name)
  local t = K.intel[name]
  if not t then
    t = { attempts = 0, best = 0, power = nil, verdict = nil, since = os.clock() }
    K.intel[name] = t
  end
  return t
end
K.intelFor = intelFor

function K.forgetIntel(name)
  if name then K.intel[name] = nil else K.intel = {} end
end

local function eligible(p)
  if p == LP then return nil end
  if K.whitelist[p.Name:lower()] then return nil end
  local ch = p.Character
  local r = ch and ch:FindFirstChild("HumanoidRootPart")
  local hu = ch and ch:FindFirstChildOfClass("Humanoid")
  if not (r and hu) or hu.Health <= 0 then return nil end
  return r
end

local function nearest()
  local me = LP.Character and LP.Character:FindFirstChild("HumanoidRootPart")
  local best, bestD
  for _, p in ipairs(Players:GetPlayers()) do
    local r = eligible(p)
    if r then
      local d = me and (r.Position - me.Position).Magnitude or 0
      if not bestD or d < bestD then bestD, best = d, p end
    end
  end
  return best
end

local function byName(name)
  if not name or name == "" then return nil, "target name is empty" end
  local q = name:lower()
  -- Exact username is unambiguous and always wins over display names.
  for _, p in ipairs(Players:GetPlayers()) do
    if p ~= LP and p.Name:lower() == q then return p end
  end

  local matches, seen = {}, {}
  local function add(p)
    if p ~= LP and not seen[p] then seen[p] = true matches[#matches + 1] = p end
  end
  for _, p in ipairs(Players:GetPlayers()) do
    if (p.DisplayName or ""):lower() == q then add(p) end
  end
  if #matches == 1 then return matches[1] end
  if #matches > 1 then return nil, "display name is ambiguous" end

  matches, seen = {}, {}
  for _, p in ipairs(Players:GetPlayers()) do
    if p.Name:lower():sub(1, #q) == q
       or (p.DisplayName or ""):lower():sub(1, #q) == q then add(p) end
  end
  if #matches == 1 then return matches[1] end
  if #matches > 1 then return nil, "name prefix is ambiguous" end
  return nil, "no player matching " .. tostring(name)
end

-- ---- run -------------------------------------------------------------

-- `opts.home = false` suppresses the return -- used by the paths that are not a
-- deliberate stop (teardown, death, a restart that is about to move you anyway).
function K.stopFling(why, opts)
  cancelReturnHome()
  local active = K.activeCleanup
  if active then pcall(active, false) end
  if not K.flinging then return false end
  K.flinging = false
  K.flingTarget = nil
  K.waitingOn = nil

  -- AFTER the finalizer and after cancelReturnHome, both of which would undo it.
  -- A fling ends with you somewhere you did not choose -- mid-air, under the
  -- map, or wherever the last orbit left you -- and walking back is the tax the
  -- feature charged for using it.
  if K.cfg.returnHome and not (opts and opts.home == false) then
    if returnToRunHome() then why = (why or "stopped") .. ", returning" end
  end
  L.note("fling", why or "stopped")
  return true
end

L.cleanup(function()
  -- Inert hooks and visual/body mutations first; lower-priority module teardown
  -- may destroy the instances these exact restorations need.
  pcall(K.setAim, false)
  pcall(K.setSilent, false)
  pcall(K.setFovRing, false)
  pcall(K.setHitbox, false)
  cancelReturnHome()
  K.flinging = false
  K.flingTarget = nil
  local active = K.activeCleanup
  if active then pcall(active, false) end
  pcall(K.setTouchFling, false)
  -- The generation is dead and all synchronous ownership is now released. Do
  -- not make lower-priority Movement cleanup mistake the inert runner task for
  -- live physics recovery and refuse its own exact restoration.
  flingRunner = nil
end, 100)

-- ---------------------------------------------------------------- latch: NO
--
-- A LATCH THAT HOLDS ANOTHER PLAYER CANNOT BE BUILT. Measured, twice, because
-- the first round of measurements fooled me completely.
--
-- Welding our root to their part really does hand our client local simulation
-- of the merged body. All of this is true and reproducible:
--
--   * gap between the two roots: 0.00 studs across 40 consecutive frames
--   * assemblies merged on 40 of 40 frames, our root the AssemblyRootPart
--   * their root ReceiveAge falls 0.073 -> 0.000, and 0.000 is what a part we
--     genuinely own reports (calibrated against our own root: 0.0000)
--   * a target running at WalkSpeed 16 covers 7.2 studs in a second normally,
--     and 0.0 studs in one and a half while welded, still reporting Running
--
-- Every one of those readings is our own client describing its own simulation,
-- and NONE of them says anything about what the target sees. The test that
-- separates the two: claim them 60 studs up, hold, cut the weld, and watch.
--
--   dY after release, sampled every 0.5 s:  0, 0, 0, -0, -0, -0 ...
--   their ReceiveAge over the same window:  0.09, 0.08, 0.08 ...
--
-- They are home in under half a second. That is not a fall -- dropping 60 studs
-- takes 0.78 s, so a real fall reads dY ~= 36 at the first sample, not 0. It is
-- a snap-back, and it means the displacement never existed anywhere but on our
-- screen. The whole time, they were running around normally on theirs.
--
-- Local simulation is not replicated authority. A client-made weld does not
-- grant server-side network ownership, so the server never accepts our position
-- for a character we do not own. Anything built on this is a POV illusion --
-- convincing from the inside, invisible from every other machine.
--
-- The only channel that moves another player is CONTACT, resolved by THEIR
-- client against our replicated body, because their result is the authoritative
-- one. That is what the fling above does and why it is built the way it is.


-- ---------------------------------------------------------------- engagement
--
-- One considered attempt on one player, wrapping flingOne with everything that
-- decides WHETHER to attempt, HOW HARD, and whether to stop trying.
local function engage(p)
  if not (p and p.Parent) then return "gone" end
  local it = intelFor(p.Name)
  local diag = diagnoseForEngagement(p)

  -- ---- seated: unflingable, but only for now --------------------------
  -- A seat welds them to it, so the impulse goes into the seat and nothing
  -- happens. Waiting is right: they stood up to get there and they will stand
  -- up to leave. The instant they do we are already on them.
  if diag == K.DIAG.SEATED then
    if not K.cfg.waitSeated then return "seated" end
    local t0 = tick()
    while K.flinging and L.live() and tick() < t0 + (K.cfg.seatPatience or 30) do
      if not p.Parent then return "gone" end
      if diagnoseForEngagement(p) ~= K.DIAG.SEATED then break end
      K.waitingOn = p.Name .. " (seated)"
      task.wait(0.25)
    end
    K.waitingOn = nil
    if not K.flinging or not L.live() then return "stopped" end
    diag = diagnoseForEngagement(p)
    if diag == K.DIAG.SEATED then return "seated" end
  end

  -- ---- dead or gone: wait for them to come back -----------------------
  if diag == K.DIAG.GONE then
    if not (K.cfg.waitRespawn and p.Parent) then return "gone" end
    local t0 = tick()
    while K.flinging and L.live() and p.Parent and tick() < t0 + (K.cfg.respawnPatience or 25) do
      K.waitingOn = p.Name .. " (respawning)"
      if diagnoseForEngagement(p) ~= K.DIAG.GONE then break end
      task.wait(0.25)
    end
    K.waitingOn = nil
    if not K.flinging or not L.live() then return "stopped" end
    diag = diagnoseForEngagement(p)
    if diag == K.DIAG.GONE then return "gone" end
    if diag == K.DIAG.SEATED then return "seated" end
  end

  -- ---- collision channel blocked: nothing can cross, do not waste effort -
  if diag == K.DIAG.COLLISION or diag == K.DIAG.GROUP then
    it.verdict = diag
    -- watch rather than abandon: this gets toggled off constantly
    if K.cfg.watchImmune then
      local t0 = tick()
      while K.flinging and L.live() and p.Parent and tick() < t0 + (K.cfg.immunePatience or 20) do
        K.waitingOn = p.Name .. (it.verdict == K.DIAG.GROUP
          and " (collision groups)" or " (collision off)")
        local current = diagnoseForEngagement(p)
        if current == K.DIAG.OPEN then
          it.verdict = nil
          break
        elseif current == K.DIAG.COLLISION or current == K.DIAG.GROUP then
          it.verdict = current
        elseif current == K.DIAG.GONE or current == K.DIAG.SEATED then
          break
        end
        task.wait(0.4)
      end
      K.waitingOn = nil
    end
    if not K.flinging or not L.live() then return "stopped" end
    local final = diagnoseForEngagement(p)
    if final == K.DIAG.OPEN then
      it.verdict = nil
    elseif final == K.DIAG.GONE then
      return "gone"
    elseif final == K.DIAG.SEATED then
      return "seated"
    elseif final == K.DIAG.COLLISION or final == K.DIAG.GROUP then
      it.verdict = final
      return "immune", final
    end
  end

  -- ---- attempt, and escalate if they are merely clamped ---------------
  local basePower = K.cfg.flungAt
  it.power = it.power or basePower
  local savedPower = K.cfg.flungAt
  K.cfg.flungAt = it.power

  it.attempts = it.attempts + 1
  local callOK, attemptOK, attemptWhy = L.try("fling.one", flingOne, p)
  K.cfg.flungAt = savedPower
  local attemptFailed = not callOK or attemptOK ~= true

  local moved = K.lastThrow or 0
  if moved > it.best then it.best = moved end

  if moved >= (K.cfg.fallbackAt or 40) then
    it.attempts = 0                 -- it worked; forget the failures
    it.power = basePower
    it.verdict = nil
    return "observed", moved
  end

  -- it landed and they barely moved: that is a clamp, and clamps answer to
  -- power. Double it, up to the slider ceiling, and come back.
  if not attemptFailed and diagnoseForEngagement(p) == K.DIAG.OPEN then
    it.verdict = K.DIAG.CLAMPED
    it.power = math.min(it.power * 2, 250000)
  elseif attemptFailed then
    it.verdict = "attempt failed"
  end

  if it.attempts >= (K.cfg.maxAttempts or 3) then
    local why = (it.verdict == K.DIAG.CLAMPED)
      and ("local resistance -- best adjusted evidence was " .. math.floor(it.best)
           .. " studs at power "
           .. math.floor(it.power))
      or tostring(attemptWhy or attemptOK or "nothing landed")
    return "givenup", why
  end
  return "retry"
end
K.engage = engage

-- ---------------------------------------------------------------- settle
--
-- BETWEEN THROWS, IN LOOP MODE.
--
-- A target that has just been flung is doing tens of thousands of studs per
-- second. Re-engaging immediately means `approach` writes our CFrame to where
-- they were, and by the next frame they are thousands of studs away -- so
-- nothing lands, the attempt counter climbs, and after three of those `engage`
-- reports "givenup" and the runner stops.
--
-- That is the whole reason loop mode appeared not to loop: it was not failing
-- to come round again, it was coming round instantly and then failing three
-- times at something that cannot be done, and treating that as proof the target
-- was immune.
--
-- So wait until they are worth hitting again. Three ways that happens, and all
-- three end the wait:
--
--   * they come to rest -- speed under a walking pace, held for a moment, which
--     is what stops a single slow frame mid-flight counting as landed;
--   * their character is replaced, which is a respawn;
--   * they die, and the next character arrives.
--
-- A respawn also FORGETS the intel. Escalated power and accumulated failures
-- belong to the body that earned them; a fresh character is not the clamp
-- problem the last one was, and carrying the old verdict forward means starting
-- the next pass already half-way to giving up.
local function settleOrRespawn(p, startChar)
  local t0 = tick()
  local calm, lastPos, lastChanged, observedSpeed = 0, nil, nil, math.huge
  local yAnchor = nil
  local lastLoop = os.clock()
  while K.flinging and L.live() and p.Parent do
    local ch = p.Character
    -- nil is commonly streaming, not a respawn. Only a different NON-NIL
    -- character identity proves a new epoch.
    if ch and ch ~= startChar then
      K.forgetIntel(p.Name)
      K.waitingOn = nil
      return "respawned"
    end

    local hum = ch and ch:FindFirstChildOfClass("Humanoid")
    local part = hum and hum.RootPart
    if not ch then
      K.waitingOn = p.Name .. " (unstreamed)"
      calm = 0
      lastPos, lastChanged, observedSpeed = nil, nil, math.huge
      lastLoop = os.clock()
    elseif not (part and hum) or hum.Health <= 0 then
      -- down but not yet replaced: keep waiting, the new character is coming
      K.waitingOn = p.Name .. " (down)"
      calm = 0
      lastPos, lastChanged, observedSpeed = nil, nil, math.huge
      lastLoop = os.clock()
    else
      local now, here = os.clock(), part.Position
      if not lastPos then
        lastPos, lastChanged = here, now
      elseif (here - lastPos).Magnitude > 0.015 then
        local dt = now - lastChanged
        if dt > 0.025 and dt < 1.0 then observedSpeed = (here - lastPos).Magnitude / dt end
        lastPos, lastChanged = here, now
      elseif lastChanged and now - lastChanged > 0.30 then
        observedSpeed = 0
      end
      -- FLOORMATERIAL IS NOT OBSERVABLE FOR A REMOTE CHARACTER, and this is
      -- the whole of "loop mode stops after one throw".
      --
      -- Humanoid.FloorMaterial is simulated by the client that OWNS the
      -- character. Read from our machine for somebody else, it does not
      -- resolve. Measured today, twice: a target standing motionless at speed 0
      -- with full health reported FloorMaterial = Air indefinitely -- and the
      -- same check deadlocked the A/B test harness before it was spotted there.
      --
      -- So `grounded` was false forever, `calm` never accumulated, and this
      -- function could not return "settled" by any path. Every loop pass then
      -- burned the full settlePatience (60 s) waiting on a condition that
      -- cannot be observed, and only ever escaped if the target happened to
      -- die and respawn. From the outside that is indistinguishable from the
      -- loop having stopped.
      --
      -- Stability is the honest proxy, and it needs BOTH terms: speed alone
      -- calls the apex of a throw "settled", because a body at the top of its
      -- arc is momentarily slow while about to fall a very long way.
      if yAnchor == nil or math.abs(here.Y - yAnchor) > 4 then
        yAnchor = here.Y
        if calm > 0 then calm = 0 end
      end
      local steady = observedSpeed < (K.cfg.settleSpeed or 60)
                 and math.abs(here.Y - yAnchor) <= 4
      local dt = now - lastLoop
      lastLoop = now
      if steady then
        calm = calm + dt
        if calm >= (K.cfg.settleHold or 0.45) then
          K.waitingOn = nil
          return "settled"
        end
      else
        calm = 0
        K.waitingOn = p.Name .. " (in flight, "
                    .. (observedSpeed < math.huge and math.floor(observedSpeed) or "?")
                    .. " st/s)"
      end
    end

    if tick() > t0 + (K.cfg.settlePatience or 60) then
      K.waitingOn = nil
      return "timeout"
    end
    task.wait(0.15)
  end
  K.waitingOn = nil
  return "stopped"
end
K.settleOrRespawn = settleOrRespawn

-- ---------------------------------------------------------------- selection
function K.select(name, on)
  if type(name) ~= "string" or name == "" then return false end
  if name:lower() == LP.Name:lower() then return false end
  if on == nil then on = not K.selected[name] end
  if on then K.selected[name] = true else K.selected[name] = nil end
  return K.selected[name] == true
end

function K.selectedList()
  local t = {}
  for nm in pairs(K.selected) do t[#t+1] = nm end
  table.sort(t)
  return t
end

function K.clearSelection() K.selected = {} return true end

function K.startFling(name)
  local mm2Busy = mm2PhysicsBusyReason()
  if mm2Busy then return false, mm2Busy, "refused" end
  if K.flinging or flingRunner or K.activeCleanup or K.returningHome then
    -- no return trip: we are about to fly somewhere on purpose
    K.stopFling("restarted", { home = false })
    -- 1.5 s is the whole of a scheduled return and one settle tick; a run that
    -- has not released by then is not going to on its own
    local deadline = os.clock() + 1.6
    while (flingRunner or K.activeCleanup or K.returningHome)
          and os.clock() < deadline do task.wait(0.03) end
    if flingRunner or K.activeCleanup or K.returningHome then
      K.recoverFling("a run would not release in 1.6 s")
      task.wait(0.05)
      if flingRunner or K.activeCleanup then
        return false, "fling is wedged -- reload the script", "refused"
      end
    end
  end
  mm2Busy = mm2PhysicsBusyReason()
  if mm2Busy then return false, mm2Busy, "refused" end
  local ch = LP.Character
  if not (ch and ch:FindFirstChild("HumanoidRootPart")) then
    return false, "you have no character", "refused"
  end
  local conflict = conflictingPhysicsFeature()
  if conflict then return false, "turn off " .. conflict .. " before flinging", "refused" end
  if K.want.touchFling then
    local touchOK, touchWhy = K.setTouchFling(false)
    if not touchOK then return false, touchWhy, "refused" end
  end

  local mode = K.cfg.flingMode
  local fixed
  if mode == "One target" or mode == "Loop one target" then
    local matchWhy
    fixed, matchWhy = byName(name)
    if not fixed then return false, matchWhy, "user" end
    if K.whitelist[fixed.Name:lower()] then
      return false, fixed.Name .. " is on your whitelist", "user"
    end
  end

  if K.want.hitbox then restoreHitboxes() end

  -- CAPTURED ONCE, HERE. The per-attempt return already puts you back after
  -- each throw, but across a loop those origins drift -- each attempt starts
  -- from wherever the last one dropped you, so "back where I started" ends up
  -- being the far side of the map. This is the only place that sees the spot
  -- the operator was standing in when they pressed the button.
  do
    local r0 = ch:FindFirstChild("HumanoidRootPart")
    K.runHome = r0 and r0.CFrame or nil
  end

  K.flinging = true
  -- LOOP TELEMETRY, because "is it still going?" was only answerable by staring
  -- at the screen. Counted inside the runner rather than around it: `engage` is
  -- an upvalue of this closure, so wrapping K.engage from outside measures
  -- nothing at all -- which is exactly the trap I fell into testing this.
  K.passes = 0
  K.startedAt = os.clock()
  K.runSerial = (K.runSerial or 0) + 1
  local serial = K.runSerial
  flingRunner = task.spawn(function()
    local runnerOK, runnerWhy = xpcall(function()
      repeat
      if not K.flinging or not L.live() or K.runSerial ~= serial then break end
      if mode == "Everyone" or mode == "Selected" then
        local list = {}
        local didWork = false
        if mode == "Selected" then
          for nm in pairs(K.selected) do
            local p = Players:FindFirstChild(nm)
            if p and p ~= LP then list[#list+1] = p end
          end
          -- ALL OF THEM GONE MEANS THE JOB IS OVER, not that we idle forever
          if #list == 0 then K.stopFling("everyone selected has left") break end
        else
          for _, p in ipairs(Players:GetPlayers()) do
            if eligible(p) then list[#list+1] = p end
          end
        end
        for _, p in ipairs(list) do
          if not K.flinging or not L.live() then break end
          if p.Parent and not K.whitelist[p.Name:lower()] then
            didWork = true
            K.flingTarget = p.Name
          K.passes = (K.passes or 0) + 1
          local verdict, info = engage(p)
            K.lastVerdict = p.Name .. ": " .. tostring(verdict)
              .. (verdict == "immune" and info and (" (" .. tostring(info) .. ")") or "")
            if verdict == "stopped" or not K.flinging or not L.live() then break end
            if verdict == "immune" or verdict == "givenup" then
              L.note("fling", p.Name .. " -- " .. tostring(verdict == "immune"
                and ((info or "local collision channel is blocked") .. ", skipping") or info))
            end
            task.wait(K.cfg.flingGap)
          end
        end
        if not didWork and K.flinging and L.live() then task.wait(0.15) end
      elseif mode == "Nearest" then
        local p = nearest()
        if not p then K.stopFling("nobody flingable") break end
        K.flingTarget = p.Name
        K.passes = (K.passes or 0) + 1
        local verdict, info = engage(p)
        K.lastVerdict = p.Name .. ": " .. tostring(verdict)
          .. (verdict == "immune" and info and (" (" .. tostring(info) .. ")") or "")
        if verdict == "stopped" or not K.flinging or not L.live() then break end
        if verdict == "immune" or verdict == "givenup" then
          L.note("fling", p.Name .. " -- " .. tostring(verdict == "immune"
            and ((info or "local collision channel is blocked") .. ", skipping") or info))
        end
        task.wait(K.cfg.flingGap)
      else
        if not (fixed and fixed.Parent) then K.stopFling("they left") break end
        K.flingTarget = fixed.Name
        K.passes = (K.passes or 0) + 1
        local verdict, info = engage(fixed)
        K.lastVerdict = fixed.Name .. ": " .. tostring(verdict)
          .. (verdict == "immune" and info and (" (" .. tostring(info) .. ")") or "")
        if verdict == "stopped" or not K.flinging or not L.live() then break end
        if mode == "One target" then
          if verdict ~= "retry" then
            K.stopFling(verdict == "observed" and "local throw observed"
              or tostring(info or verdict))
            break
          end
          task.wait(math.max(K.cfg.flingGap, 0.1))
        end

        -- ---- LOOP MODE: RELENTLESS BY DEFAULT ---------------------------
        --
        -- A successful throw is followed by a wait, not by another attempt.
        -- Without it the next pass chases a body doing 20,000 studs/s, misses
        -- three times, and the loop concludes the target is immune -- which is
        -- exactly how "loop mode stops after one fling" presented.
        if verdict == "observed" then
          local how = settleOrRespawn(fixed, fixed.Character)
          if how == "stopped" then break end
          K.lastSettle = how
        end

        -- Failures no longer end the run. The old code stopped on "givenup",
        -- which is a verdict about ONE attempt on a body that is standing right
        -- there -- the natural response to which is to try again, not to quit.
        -- Intel is cleared so the next pass starts from base power rather than
        -- inheriting an escalation that already did not work.
        if verdict == "immune" or verdict == "givenup" then
          if not K.cfg.loopRelentless then
            K.stopFling(tostring(info or verdict))
            L.Toast.warn("Fling stopped", fixed.Name .. " -- " .. tostring(info or verdict))
            break
          end
          K.forgetIntel(fixed.Name)
          -- a beat longer than the normal gap: whatever blocked the last pass
          -- is usually still true for a moment
          task.wait(math.max(K.cfg.flingGap, 0.4))
        end

        task.wait(K.cfg.flingGap)
      end
    -- ONE CONDITION, AND IT IS THE ONLY ONE THAT WAS EVER TRUE.
    --
    -- This read `not K.flinging or not K.cfg.loopFling and mode ~= "Everyone"
    -- and mode ~= "Nearest"` -- and `K.cfg.loopFling` was referenced here and
    -- defined nowhere. Always nil, so `not nil` was always true, so for "Loop
    -- one target" the whole tail evaluated true and the repeat exited after
    -- exactly one pass. Loop mode has never looped once.
    --
    -- Every mode that genuinely ends after one engagement already breaks out
    -- above with a reason attached, so the only thing this needs to ask is
    -- whether we are still meant to be running.
      until not K.flinging or not L.live() or K.runSerial ~= serial
    end, function(err) return tostring(err) end)
    if not runnerOK and L.live() then L.fault("fling.runner", runnerWhy) end
    if K.activeCleanup then pcall(K.activeCleanup, false) end
    if K.runSerial == serial then
      cancelReturnHome()
      K.flinging = false
      K.flingTarget = nil
    end
    flingRunner = nil
  end)

  return true, (fixed and ("flinging " .. fixed.Name)) or ("flinging: " .. mode)
end

-- kept so older call sites still work
function K.fling(name, seconds)
  return K.startFling(name)
end

-- ---------------------------------------------------------------- respawn
--
-- The aim loop caches `workspace.CurrentCamera`, and the hitbox loop holds the
-- parts it resized. Both are replaced when you die, so without this the page
-- keeps saying everything is on while nothing on it is doing anything.
L.hold(LP.CharacterAdded:Connect(function(c)
  if not L.live() then return end
  cancelReturnHome()
  -- no return trip on death: the respawn decides where you are, not us
  if K.flinging then K.stopFling("you died", { home = false }) end
  local active = K.activeCleanup
  if active then pcall(active, false) end
  c:WaitForChild("HumanoidRootPart", 8)
  task.wait(0.35)
  if not L.live() or LP.Character ~= c then return end
  L.try("combat.respawn", function()
    if K.want.aim then K.setAim(false) K.setAim(true) end
    -- the sizes recorded before you died belong to characters that no longer
    -- exist; dropping them stops the next "off" writing to dead parts
    if K.want.hitbox then K.setHitbox(false) K.setHitbox(true) end
    if K.want.fov then K.setFovRing(false) K.setFovRing(true) end
  end)
end))

-- ---------------------------------------------------------------- ui

-- ---------------------------------------------------------------- tuning
--
-- AUTO-TUNE MEASURES, IT DOES NOT RECOMMEND. The one number that genuinely
-- varies per person is the round trip to the server, and it is the number the
-- predictive lead is built on. Everything else here is a value that was swept
-- against reality and won: lead 1.00 measured a 2.19 stud median aim error
-- against 6.67 with prediction off, and both 0.75 and 1.25 were worse.
-- ---------------------------------------------------------------- prediction
--
-- PREDICTION IS A CONNECTION MEASUREMENT, SO IT SHOULD NOT BE A BUTTON.
--
-- The lead and the cap are derived entirely from ping and the interpolation
-- buffer. Nothing about them is taste, and a value tuned on a 90 ms server is
-- wrong the moment you join a 300 ms one -- which is exactly when somebody who
-- pressed Auto-tune an hour ago starts missing and cannot say why.
--
-- It owns the PREDICTION HORIZON ONLY. It deliberately does not touch
-- approachSettle, the technique, or any power setting: those belong to the
-- preset you chose, and having a background timer quietly walk them back to
-- something ping-shaped would undo "instant + brutal" a few seconds after you
-- selected it.
-- ONE SETTING, TWO STORED COPIES -- THE SAME TRAP THE MOTION PROFILE FELL INTO.
--
-- This shipped defaulting to true and came back false, because the toggle also
-- saves itself under Cfg.features and applyOnLoad restores THAT after the module
-- default has been set. Whichever store is written last wins, so the answer is
-- to never let them disagree: setAutoPredict writes the declared key, the
-- feature key and the visible control together.
K.cfg.autoPredict = true
K.AUTO_CTL = "combat.fling.Automatic prediction"

function K.setAutoPredict(on, silent)
  on = on and true or false
  K.cfg.autoPredict = on
  if L.Cfg then
    L.Cfg.set("autoPredict", on)
    if L.Cfg.setFeat then pcall(L.Cfg.setFeat, K.AUTO_CTL, on) end
  end
  if not silent and L.C and L.C.find then
    local h = L.C.find(K.AUTO_CTL)
    if h and h.set then pcall(function() h:set(on, true) end) end
  end
  if on then K.predictFromPing() end
  return on
end

-- Restoration is bindPersist's job, and the id is in Cfg.ARM_SAFE so a stored
-- ON actually comes back. A second restore here raced it -- which is the very
-- bug this setting already had.

function K.predictFromPing()
  local ok, ms = pcall(function()
    return game:GetService("Stats").Network.ServerStatsItem["Data Ping"]:GetValue()
  end)
  if not (ok and type(ms) == "number" and ms == ms) then return nil end
  local horizon = math.clamp(ms / 2000, 0.008, 0.35)
                + (K.cfg.interpBuffer or 0.185)
  K.cfg.predictLead = 1.0
  K.cfg.predictCap  = math.clamp(horizon * 90, 12, 32)
  K.lastPredictMs   = ms
  return ms
end

-- Re-derived on a slow clock and only when the connection has actually moved.
-- 25 ms is under the point where the cap changes by a stud, so anything smaller
-- would be rewriting the same numbers.
task.spawn(function()
  task.wait(4)
  while true do
    if L.live() and K.cfg.autoPredict then
      local prev = K.lastPredictMs
      local ms = K.predictFromPing()
      -- push the derived numbers back into the two sliders. Without this the
      -- controls keep showing whatever was saved -- a lead of 0 and a cap of
      -- 1.04 in the config this was found in -- while the engine quietly uses
      -- something else entirely.
      if ms and L.C and L.C.find then
        local a = L.C.find("combat.fling.Predictive lead")
        if a and a.set then pcall(function() a:set(K.cfg.predictLead, true) end) end
        local b = L.C.find("combat.fling.Lead limit")
        if b and b.set then pcall(function() b:set(K.cfg.predictCap, true) end) end
      end
      if ms and prev and math.abs(ms - prev) > 25 then
        L.note("combat", string.format("prediction re-tuned: %d ms -> cap %d studs",
          math.floor(ms), math.floor(K.cfg.predictCap)))
      end
    end
    task.wait(15)
  end
end)

function K.autoTune()
  local ok, ms = pcall(function()
    return game:GetService("Stats").Network.ServerStatsItem["Data Ping"]:GetValue()
  end)
  if not (ok and type(ms) == "number" and ms == ms) then
    return nil, "this client will not report a ping"
  end

  -- Scale one applies the measured horizon exactly once.
  K.cfg.predictLead = 1.0
  local horizon = math.clamp(ms / 2000, 0.008, 0.35)
                + (K.cfg.interpBuffer or 0.185)
  -- Enough room for a fast humanoid over the measured horizon, never hundreds
  -- of studs where a bad sample would deliberately aim at empty space.
  K.cfg.predictCap = math.clamp(horizon * 90, 12, 32)
  K.cfg.approachSettle = math.clamp(0.45 + ms / 2000, 0.45, 0.80)
  -- NOT the technique. Auto-tune answers "what does this connection need",
  -- and which technique to throw with is not a connection question.
  K.cfg.autoFallback = true

  return ms, string.format(
    "%d ms ping -> lead 1.0, cap %d studs, settle %.2fs",
    math.floor(ms), math.floor(K.cfg.predictCap), K.cfg.approachSettle)
end

-- Two shapes people actually want, rather than twelve dials.
function K.preset(kind)
  if kind == "instant" then
    K.cfg.approachSettle = 0.35     -- the least that still transfers ownership
    K.cfg.flingDuration  = 8
    K.cfg.flingAfterburn = 3.5
    K.cfg.flungAt        = 1000000
    K.cfg.orbitRadius    = 0.6
    K.cfg.orbitLift      = 1.2
    K.cfg.flingGap       = 0
    K.cfg.maxAttempts    = 8
    K.cfg.autoFallback   = true
    K.cfg.repPower       = 4.5e8
    K.cfg.repSpin        = 9e8
  elseif kind == "safe" then
    K.cfg.approachSettle = 1.6
    K.cfg.flingDuration  = 3
    K.cfg.flingAfterburn = 0.5
    K.cfg.flungAt        = 4000
    K.cfg.orbitRadius    = 1.0
    K.cfg.orbitLift      = 1.5
    K.cfg.flingGap       = 0.05
    K.cfg.maxAttempts    = 3
    K.cfg.autoFallback   = true
    K.cfg.repPower       = 5e7
    K.cfg.repSpin        = 2e8
  end
  return true
end

function K.build(page)
  C.ctx("combat")
  C.section(page, "aim")

  C.toggle(page, {
    text = "Aim assist", desc = "Follows the target your settings pick",
    default = false,
    callback = function(v)
      local ok, why = K.setAim(v)
      if v and K.cfg.method == "Silent aim" then
        local sok, swhy = K.setSilent(true)
        if not sok then L.Toast.warn("Silent aim", tostring(swhy)) end
      elseif not v then
        K.setSilent(false)
      end
      if not ok then L.Toast.warn("Aim assist", tostring(why)) end
      return ok
    end,
  })
  C.dropdown(page, {
    text = "Method", desc = "Lock is smooth, snap is instant, silent hooks the mouse",
    when = "combat.aim.Aim assist",
    items = K.METHODS, default = K.cfg.method,
    callback = function(v)
      K.cfg.method = v
      K.setSilent(false)
      if v == "Silent aim" and K.want.aim then
        local ok, why = K.setSilent(true)
        if not ok then L.Toast.warn("Silent aim", tostring(why)) end
      end
    end,
  })
  C.dropdown(page, {
    text = "Aim at", desc = "Which part to point at",
    when = "combat.aim.Aim assist",
    items = K.PARTS, default = K.cfg.part,
    callback = function(v) K.cfg.part = v end,
  })
  C.dropdown(page, {
    text = "Pick target by", desc = "How to choose between them",
    when = "combat.aim.Aim assist",
    items = K.TARGETS, default = K.cfg.target,
    callback = function(v) K.cfg.target = v end,
  })
  C.slider(page, {
    text = "FOV", desc = "Targets inside this circle only",
    when = "combat.aim.Aim assist",
    min = 1, max = 2000, step = 1, default = K.cfg.fov,
    callback = function(v) K.cfg.fov = v end,
  })
  C.slider(page, {
    text = "Smoothing", desc = "Higher is slower",
    when = "combat.aim.Aim assist",
    min = 0.01, max = 1, step = 0.01, default = K.cfg.smooth,
    callback = function(v) K.cfg.smooth = v end,
  })
  C.slider(page, {
    text = "Max distance", desc = "Ignore anyone further than this",
    when = "combat.aim.Aim assist",
    min = 1, max = 100000, step = 1, curve = "log", default = K.cfg.maxDist,
    callback = function(v) K.cfg.maxDist = v end,
  })
  C.slider(page, {
    text = "Lead the target", desc = "0 for hitscan, raise for projectiles",
    min = 0, max = 0.5, step = 0.001, default = K.cfg.predict,
    callback = function(v) K.cfg.predict = v end,
  })
  C.toggle(page, {
    text = "Hold right mouse", desc = "Assist only while held",
    default = K.cfg.holdRmb, callback = function(v) K.cfg.holdRmb = v end,
  })
  C.toggle(page, {
    text = "Team check", desc = "Never target your own team",
    default = K.cfg.teamCheck, callback = function(v) K.cfg.teamCheck = v end,
  })
  C.toggle(page, {
    text = "Visible only", desc = "Skip anyone behind a wall",
    default = K.cfg.visibleOnly, callback = function(v) K.cfg.visibleOnly = v end,
  })
  C.toggle(page, {
    text = "Show FOV circle", desc = "Circle around your cursor",
    default = false, callback = function(v) return K.setFovRing(v) end,
  })

  C.section(page, "hitbox")

  C.toggle(page, {
    text = "Hitbox expander", desc = "Grows their parts on your client",
    default = false, callback = function(v) return K.setHitbox(v) end,
  })
  C.slider(page, {
    text = "Hitbox size", desc = "Studs per side",
    min = 0.5, max = 500, step = 0.5, curve = "log", default = K.cfg.hitboxSize,
    callback = function(v) K.cfg.hitboxSize = v end,
  })
  C.dropdown(page, {
    text = "Which parts", desc = "More parts is easier to hit",
    items = K.SCOPES, default = K.cfg.hitboxScope,
    callback = function(v)
      K.cfg.hitboxScope = v
      if K.want.hitbox then K.setHitbox(false) K.setHitbox(true) end
    end,
  })

  C.section(page, "fling")

  C.dropdown(page, {
    text = "Who to fling", desc = "Everyone walks the server, loop repeats one",
    items = K.FLING_MODES, default = K.cfg.flingMode,
    callback = function(v) K.cfg.flingMode = v end,
  })
  -- ---- one-press setup ---------------------------------------------------
  --
  -- There are now a dozen fling numbers and no reason anybody should have to
  -- learn what they all do. These measure the connection and write the settings
  -- that were actually best in testing, rather than offering a "recommended"
  -- that is really just somebody's guess.
  C.actions(page, {
    { text = "Auto-tune", primary = true, callback = function()
        local ping, why = K.autoTune()
        if ping then
          L.Toast.ok("Tuned to your connection", why)
        else
          L.Toast.warn("Auto-tune", tostring(why))
        end
      end },
    { text = "Instant + brutal", callback = function()
        K.preset("instant")
        L.Toast.ok("Instant", "Shortest approach, hardest contact, longest afterburn. This is the default.")
      end },
    { text = "Safe + reliable", callback = function()
        K.preset("safe")
        L.Toast.ok("Safe", "Longer settle, bounded power -- lands more often.")
      end },
  })

  C.dropdown(page, {
    text = "Technique",
    desc = "Contact lock stays overlapped; massless and void are harder fallbacks",
    items = K.FLING_ATTACH, default = K.cfg.flingAttach,
    callback = function(v) K.cfg.flingAttach = v end,
  })
  C.slider(page, {
    text = "Contact envelope", desc = "Maximum horizontal radius around the predicted body",
    min = 0.35, max = 3, step = 0.05, default = K.cfg.contactEnvelope,
    callback = function(v) K.cfg.contactEnvelope = v end,
  })
  C.slider(page, {
    text = "Orbit spread", desc = "How wide the diagonal offsets swing",
    min = 0.05, max = 40, step = 0.05, default = K.cfg.orbitRadius,
    callback = function(v) K.cfg.orbitRadius = v end,
  })
  C.slider(page, {
    text = "Orbit lift", desc = "Vertical swing above and below them",
    min = 0.05, max = 40, step = 0.05, default = K.cfg.orbitLift,
    callback = function(v) K.cfg.orbitLift = v end,
  })
  C.slider(page, {
    text = "Seconds per player", desc = "Ends early once they launch",
    min = 0.1, max = 30, step = 0.1, default = K.cfg.flingDuration,
    callback = function(v) K.cfg.flingDuration = v end,
  })
  C.slider(page, {
    text = "Gap between players", desc = "Pause before moving to the next one",
    min = 0, max = 5, step = 0.01, default = K.cfg.flingGap,
    callback = function(v) K.cfg.flingGap = v end,
  })
  -- THE RANGE IS OPEN. Measured points along it: 3000 with 0.4s of afterburn
  -- peaks near 14,400 studs/s and throws them ~22,700 studs; 6000 with 1.5s
  -- peaks at 24,744 and throws them 112,327. Both are real flings and both land
  -- somewhere; the second simply removes them from the map entirely.
  --
  -- WHERE IT ACTUALLY STOPS, and it is not this slider. The slam written at
  -- every placement is already 9e7 -- past what Roblox's solver will impart in
  -- one step -- so beyond a point the limit is how many contacts land before
  -- they outrun the offset pattern, not the number typed here. Expect the curve
  -- to flatten well before the top of the range; that is physics, not a cap.
  -- Every readout is click-to-type, so any exact value can be entered directly.
  C.slider(page, {
    text = "Launch power", desc = "Speed they are driven to. Higher throws farther",
    min = 1, max = 50000000, step = 1, curve = "log", default = K.cfg.flungAt,
    callback = function(v) K.cfg.flungAt = v end,
  })
  C.slider(page, {
    text = "Afterburn", desc = "Extra seconds of contact once they are moving",
    min = 0, max = 15, step = 0.05, default = K.cfg.flingAfterburn,
    callback = function(v) K.cfg.flingAfterburn = v end,
  })
  C.toggle(page, {
    text = "Wait out chairs",
    desc = "A seat welds them to it -- hold, and strike the moment they stand",
    default = K.cfg.waitSeated,
    callback = function(v) K.cfg.waitSeated = v end,
  })
  C.toggle(page, {
    text = "Wait for respawn",
    desc = "Killed or thrown off the map? Re-engage the instant they are back",
    default = K.cfg.waitRespawn,
    callback = function(v) K.cfg.waitRespawn = v end,
  })
  C.toggle(page, {
    text = "Watch immune players",
    desc = "Collision-off cannot be flung, but people toggle it back",
    default = K.cfg.watchImmune,
    callback = function(v) K.cfg.watchImmune = v end,
  })
  C.slider(page, {
    text = "Attempts before giving up",
    desc = "Each failure doubles the power before the next try",
    min = 1, max = 50, step = 1, default = K.cfg.maxAttempts,
    callback = function(v) K.cfg.maxAttempts = v end,
  })
  C.actions(page, {
    { text = "Clear selection", callback = function()
        K.clearSelection()
        L.Toast.info("Selection cleared", "Nobody is marked for the Selected mode.")
      end },
    { text = "Forget what I learned", callback = function()
        K.forgetIntel()
        L.Toast.info("Intel cleared", "Every player is treated as untested again.")
      end },
  })

  C.toggle(page, {
    text = "Automatic prediction",
    desc = "Derives lead and cap from your live ping -- retunes when it moves",
    default = K.cfg.autoPredict,
    callback = function(v)
      K.setAutoPredict(v, true)
      if v then
        local ms = K.predictFromPing()
        if ms then
          L.Toast.ok("Prediction automatic", string.format(
            "%d ms -> cap %d studs, and it will follow the connection",
            math.floor(ms), math.floor(K.cfg.predictCap)))
        else
          L.Toast.warn("Prediction", "this client will not report a ping")
        end
      else
        L.Toast.info("Prediction manual", "The two sliders below are yours now.")
      end
    end,
  })
  C.slider(page, {
    text = "Predictive lead",
    desc = "0 is off; 1 uses the measured one-way trip plus interpolation buffer",
    min = 0, max = 6, step = 0.05, default = K.cfg.predictLead,
    callback = function(v) K.cfg.predictLead = v end,
  })
  C.slider(page, {
    text = "Lead limit", desc = "Studs of lead it will never exceed",
    min = 0.5, max = 2000, step = 0.5, curve = "log", default = K.cfg.predictCap,
    callback = function(v) K.cfg.predictCap = v end,
  })
  C.slider(page, {
    text = "Close-in settle",
    desc = "Pause beside them before striking. Below 0.25 the engine floors it",
    min = 0.05, max = 10, step = 0.05, default = K.cfg.approachSettle,
    callback = function(v) K.cfg.approachSettle = v end,
  })
  C.slider(page, {
    text = "Rep-root power",
    desc = "Linear thrust pushed through their replication stream",
    min = 1e6, max = 9e8, step = 1e6, default = K.cfg.repPower,
    callback = function(v) K.cfg.repPower = v end,
  })
  C.slider(page, {
    text = "Rep-root lift",
    desc = "0 throws them flat, 1 straight up",
    min = 0, max = 1, step = 0.05, default = K.cfg.repLift,
    callback = function(v) K.cfg.repLift = v end,
  })
  C.toggle(page, {
    text = "Go back when you stop",
    desc = "Stopping returns you to where you were standing when the run began",
    default = K.cfg.returnHome,
    callback = function(v) K.cfg.returnHome = v end,
  })
  C.toggle(page, {
    text = "Try other techniques if one fails",
    desc = "Uses locomotion-adjusted local evidence, then tries each fallback once",
    default = K.cfg.autoFallback,
    callback = function(v) K.cfg.autoFallback = v end,
  })
  C.toggle(page, {
    text = "Touch fling",
    desc = "Passive hazard: you stand still and spin, anyone touching you flies",
    default = false,
    callback = function(v) return K.setTouchFling(v) end,
  })

  local flingName = C.input(page, {
    text = "Target name", desc = "Or use the player panel",
    placeholder = "name",
  })
  C.actions(page, {
    { text = "Open player panel", primary = true, callback = function()
        if L.Side and L.Side.show then
          local ok, why = L.Side.show()
          if ok == false and why then L.Toast.warn("Player panel", why)
          else L.Toast.info("Player panel", "Press Fling on anyone's card.") end
        end
      end },
  })
  C.input(page, {
    text = "Never fling", desc = "Enter to toggle",
    placeholder = "name",
    callback = function(v)
      if v == "" then return end
      local key = v:lower()
      if K.whitelist[key] then
        K.whitelist[key] = nil
        L.Toast.ok("Off the whitelist", v .. " can be flung again.")
      else
        K.whitelist[key] = true
        L.Toast.ok("Whitelisted", v .. " will never be targeted.")
      end
    end,
  })

  C.actions(page, {
    { text = "Start fling", primary = true, callback = function()
        local ok, why, kind = K.startFling(flingName:get())
        if ok then L.Toast.ok("Fling", why)
        else
          L.Toast.warn("Fling", tostring(why))
          if kind ~= "user" then L.log("refused", "fling", why) end
        end
      end },
    { text = "Stop fling", callback = function()
        if K.stopFling("stopped by hand") then
          L.Toast.ok("Fling", K.cfg.returnHome and K.runHome
                     and "Stopped -- putting you back." or "Stopped.")
        else
          -- "Not running" is a lie when something is still held: that is the
          -- exact state the operator is pressing Stop to get out of.
          local stuck = K.recoverFling("stop pressed while idle but held")
          if stuck then L.Toast.warn("Fling", "Was not running, but something was stuck. Cleared.")
          else L.Toast.info("Fling", "Not running.") end
        end
      end },
    { text = "Unstick", callback = function()
        local stuck, held = K.recoverFling("unstick pressed")
        if stuck then
          L.Toast.ok("Fling", "Released: " .. table.concat(held, ", ") .. ".")
        else
          L.Toast.info("Fling", "Nothing was held -- fling is already clear.")
        end
      end },
  })

  C.actions(page, {
    { text = "Turn everything off", primary = true, callback = function()
        K.setAim(false) K.setSilent(false)
        K.setFovRing(false) K.setHitbox(false) K.setTouchFling(false)
        K.stopFling("turned everything off", { home = false })
        L.Toast.ok("Combat off", "Aim, hitbox, overlay and fling all cleared.")
      end },
  })
end

end
do -- ==== lm_25_movement.lua ====
-- LUMEN :: MOVEMENT
-- The rest of the movement and utility set: gravity, freeze, spin, invisibility,
-- position marks, anti-void, anti-fling, and getting out of a server.
--
-- SEVERAL OF THESE OFFER A CHOICE OF METHOD, and that is not decoration. A game
-- that drives your character every frame will fight one approach and ignore
-- another, and which one wins is not knowable from here -- so the choice is
-- exposed instead of guessed, and each option says what it actually touches.
--
-- Anything that edits a property of YOUR character records what it found first.
-- L.Universal already owns fly, noclip, infinite jump, walk speed and jump power;
-- this file deliberately does not duplicate them.

local L = getgenv().LUMEN
local T, M, A, C = L.T, L.Motion, L.A, L.C

local Players = game:GetService("Players")
local RS = game:GetService("RunService")
local TS = game:GetService("TeleportService")
local LP = L.LP

local Mv = {}
L.Move = Mv
Mv.physicsEpoch = { physical = 0, anchored = 0, platform = 0 }

local function bumpPhysicsEpoch(...)
  for i = 1, select("#", ...) do
    local property = select(i, ...)
    Mv.physicsEpoch[property] = (Mv.physicsEpoch[property] or 0) + 1
  end
end

Mv.want = { freeze = false, spin = false, invis = false, antiVoid = false,
            antiFling = false, guardian = false }
Mv.cfg = {
  gravity = 196.2,
  spinSpeed = 30,
  freezeMethod = "Anchor",
  invisMethod = "Local transparency",
  voidFloor = -180,
  spinMethod = "Angular velocity",
  ghostFade = 0.5,               -- how solid the stand-in looks to you
  antiFlingBlockPlayers = true,  -- the layer an attacker cannot answer
  guardDecollide  = true,        -- on being flung, leave everyone's collision set
  guardAntiAfk    = true,        -- arm anti-AFK before the idle kick lands
  guardRetaliate  = false,       -- off by default: attribution is a GUESS
}

Mv.FREEZE = { "Anchor", "Platform stand", "Velocity clamp" }
-- ordered weakest to strongest, and the last one is the only one anybody else
-- can observe
Mv.INVIS  = { "Local transparency", "Transparency write", "Park (hide from everyone)" }
Mv.SPIN   = { "Angular velocity", "CFrame rotate" }

local function char() return LP.Character end
local function root()
  local c = char()
  return c and c:FindFirstChild("HumanoidRootPart")
end
local function hum()
  local c = char()
  return c and c:FindFirstChildOfClass("Humanoid")
end

local function combatPhysicsActive()
  local combat = L.Combat
  if not combat then return false end
  if combat.physicsBusy then
    local ok, busy = pcall(combat.physicsBusy)
    if ok then return busy and true or false end
  end
  return combat.flinging or combat.activeCleanup ~= nil
      or (combat.want and combat.want.touchFling) or false
end

-- ---------------------------------------------------------------- gravity

local savedGravity

function Mv.setGravity(v)
  if savedGravity == nil then savedGravity = workspace.Gravity end
  -- clamp matched to the slider: a control that offers 2000 and is silently
  -- capped at 500 is worse than one that never offered it
  workspace.Gravity = math.clamp(v, 0, 2000)
  Mv.cfg.gravity = workspace.Gravity
  return true, string.format("%.0f", workspace.Gravity)
end

function Mv.resetGravity()
  if savedGravity then
    workspace.Gravity = savedGravity
    savedGravity = nil
  end
  return true
end

-- ---------------------------------------------------------------- freeze

local freezeConn
local freezeState

local function restoreFreeze()
  local state = freezeState
  freezeState = nil
  if not state then return end
  if state.method == "Anchor" and state.root and state.root.Parent then
    pcall(function() state.root.Anchored = state.anchored end)
  end
  if state.method == "Platform stand" and state.humanoid and state.humanoid.Parent then
    pcall(function() state.humanoid.PlatformStand = state.platform end)
  end
end

function Mv.setFreeze(on)
  if combatPhysicsActive() then
    return false, "finish the active fling before changing Freeze"
  end
  local previousMethod = freezeState and freezeState.method
  if previousMethod == "Anchor" then bumpPhysicsEpoch("anchored") end
  if previousMethod == "Platform stand" then bumpPhysicsEpoch("platform") end
  if on and Mv.cfg.freezeMethod == "Anchor" then bumpPhysicsEpoch("anchored") end
  if on and Mv.cfg.freezeMethod == "Platform stand" then bumpPhysicsEpoch("platform") end
  Mv.want.freeze = on and true or false
  if freezeConn then freezeConn:Disconnect() freezeConn = nil end

  if not Mv.want.freeze then
    restoreFreeze()
    return true
  end

  local r, h = root(), hum()
  if not r then
    Mv.want.freeze = false
    return false, "no character"
  end

  -- Re-applying after a method change first returns the previous transaction.
  restoreFreeze()
  freezeState = {
    root = r, anchored = r.Anchored,
    humanoid = h, platform = h and h.PlatformStand or false,
    method = Mv.cfg.freezeMethod,
  }

  local m = Mv.cfg.freezeMethod
  if m == "Anchor" then
    r.Anchored = true
  elseif m == "Platform stand" then
    if h then h.PlatformStand = true end
  else
    -- clamp: leaves you unanchored, so pushes still register but go nowhere.
    -- The one that survives games which reset Anchored every frame.
    freezeConn = L.hold(RS.Heartbeat:Connect(function()
      if not (L.live() and Mv.want.freeze) then return end
      local rr = root()
      if rr then
        rr.AssemblyLinearVelocity = Vector3.zero
        rr.AssemblyAngularVelocity = Vector3.zero
      end
    end))
  end
  return true
end

-- ---------------------------------------------------------------- spin

local spinConn

function Mv.setSpin(on)
  on = on and true or false
  if on and combatPhysicsActive() then
    return false, "finish the active fling before enabling Spinbot"
  end
  Mv.want.spin = on
  if spinConn then spinConn:Disconnect() spinConn = nil end
  if not Mv.want.spin then
    local r = root()
    if r then pcall(function() r.AssemblyAngularVelocity = Vector3.zero end) end
    return true
  end
  if not root() then
    Mv.want.spin = false
    return false, "no character"
  end
  spinConn = L.hold(RS.Heartbeat:Connect(function(dt)
    if not (L.live() and Mv.want.spin) then return end
    local r = root()
    if not r then return end
    if Mv.cfg.spinMethod == "Angular velocity" then
      r.AssemblyAngularVelocity = Vector3.new(0, Mv.cfg.spinSpeed, 0)
    else
      r.CFrame = r.CFrame * CFrame.Angles(0, math.rad(Mv.cfg.spinSpeed * dt * 12), 0)
    end
  end))
  return true
end

-- ---------------------------------------------------------------- invisibility

-- TWO KINDS OF INVISIBLE, AND ONLY ONE OF THEM IS REAL.
--
-- Writing transparency -- by any property, local or replicated -- hides you on
-- your OWN screen and nowhere else. A client's property writes do not replicate,
-- so every other player still sees you standing there. That is worth having as
-- a cosmetic option and worthless as a way to disappear, and a hub that muddles
-- the two is lying to you.
--
-- "Park (hide from everyone)" is the one that other people actually observe,
-- and it works for a reason that has nothing to do with transparency: you own
-- your character's network ownership, so writing HumanoidRootPart.CFrame DOES
-- replicate. The real body is parked 100,000 studs up and re-asserted every
-- frame; a client-only clone is left where you were standing and driven by your
-- input, so you still see and control yourself. Everyone else sees you vanish
-- by DISTANCE.
--
-- Be honest about the cost: you remain a real player at a real position, so any
-- server-side height, zone, distance or anti-teleport check will see it.
local invisConn
local invisSaved = {}
local invisDisplaySaved = {}
local ghost, ghostConn, parkConn
local parkState

local PARK = CFrame.new(0, 100000, 0)

local function killGhost()
  if ghostConn then pcall(function() ghostConn:Disconnect() end) ghostConn = nil end
  if parkConn then pcall(function() parkConn:Disconnect() end) parkConn = nil end
  if ghost then pcall(function() ghost:Destroy() end) ghost = nil end
end

-- Parenting the clone to workspace from a LocalScript keeps it client-side:
-- nothing about it reaches the server, so nobody else ever sees two of you.
local function makeGhost(c)
  -- THE MODEL ITSELF NEEDS Archivable, not just its parts. Clone() on a model
  -- with Archivable = false returns nil, and a character is usually exactly
  -- that -- so setting it on the descendants alone produced a silent nil and
  -- the whole mode reported "could not build the stand-in".
  local ok, clone = pcall(function()
    local archived = {}
    if not c.Archivable then archived[#archived + 1] = c c.Archivable = true end
    for _, d in ipairs(c:GetDescendants()) do
      if not d.Archivable then archived[#archived + 1] = d d.Archivable = true end
    end
    local cl = c:Clone()
    for _, d in ipairs(archived) do d.Archivable = false end
    return cl
  end)
  if not ok or not clone then return nil end

  -- scripts in the clone would run a second copy of the game's character logic
  for _, d in ipairs(clone:GetDescendants()) do
    if d:IsA("BaseScript") then pcall(function() d:Destroy() end) end
  end
  local gh = clone:FindFirstChildOfClass("Humanoid")
  if gh then
    gh.DisplayDistanceType = Enum.HumanoidDisplayDistanceType.None
    pcall(function() gh:ChangeState(Enum.HumanoidStateType.Physics) end)
  end
  for _, d in ipairs(clone:GetDescendants()) do
    if d:IsA("BasePart") then
      d.CanCollide = false
      d.Anchored = true              -- driven by us, never simulated
      d.LocalTransparencyModifier = Mv.cfg.ghostFade or 0.5
    end
  end
  clone.Name = "LumenGhost"
  clone.Parent = workspace
  return clone
end

function Mv.setInvis(on)
  if combatPhysicsActive()
     and (Mv.cfg.invisMethod == "Park (hide from everyone)" or parkState) then
    return false, "finish the active fling before changing Park invisibility"
  end
  if Mv.cfg.invisMethod == "Park (hide from everyone)" or parkState then
    bumpPhysicsEpoch("platform")
  end
  Mv.want.invis = on and true or false
  if invisConn then invisConn:Disconnect() invisConn = nil end

  local method = Mv.cfg.invisMethod
  -- The property to restore is the one we PAINTED, not the one the dropdown
  -- happens to say now. Recomputing it here meant switching method while
  -- invisible restored the saved values into the other property and left
  -- Transparency = 1 baked on with the toggle reading OFF.
  local prop = Mv._invisProp
    or ((method == "Transparency write") and "Transparency" or "LocalTransparencyModifier")

  if not Mv.want.invis then
    killGhost()
    local state = parkState
    parkState = nil
    if state and state.root and state.root.Parent then
      pcall(function()
        state.root.CFrame = state.from or state.root.CFrame
        state.root.AssemblyLinearVelocity = Vector3.zero
      end)
    end
    if state then
      for part, was in pairs(state.collide) do
        if part.Parent then pcall(function() part.CanCollide = was end) end
      end
      if state.humanoid and state.humanoid.Parent then
        pcall(function() state.humanoid.PlatformStand = state.platform end)
      end
      if workspace.CurrentCamera and state.camera then
        pcall(function() workspace.CurrentCamera.CameraSubject = state.camera end)
      end
    end
    Mv._parked, Mv._parkFrom = false, nil
    -- restore by what was SAVED: effects stored a boolean Enabled, parts and
    -- decals stored a number for whichever transparency property was painted
    for part, v in pairs(invisSaved) do
      if part.Parent then
        if type(v) == "boolean" then
          pcall(function() part.Enabled = v end)
        else
          pcall(function() part[prop] = v end)
        end
      end
    end
    invisSaved = {}
    for humanoid, was in pairs(invisDisplaySaved) do
      if humanoid.Parent then
        pcall(function() humanoid.DisplayDistanceType = was end)
      end
    end
    invisDisplaySaved = {}
    Mv._invisProp = nil
    return true
  end

  local c = char()
  if not c then
    Mv.want.invis = false
    return false, "no character"
  end

  -- ---- the one that other players actually observe -------------------
  if method == "Park (hide from everyone)" then
    local r, h = root(), hum()
    if not (r and h) then Mv.want.invis = false return false, "no character" end
    Mv._parkFrom = r.CFrame
    Mv._parked = true
    parkState = {
      root = r, humanoid = h, from = r.CFrame,
      platform = h.PlatformStand,
      camera = workspace.CurrentCamera and workspace.CurrentCamera.CameraSubject,
      collide = {},
    }

    ghost = makeGhost(c)
    if not ghost then
      Mv.want.invis = false
      Mv._parked = false
      Mv._parkFrom = nil
      parkState = nil
      return false, "could not build the stand-in"
    end
    local gRoot = ghost:FindFirstChild("HumanoidRootPart")

    pcall(function() h.PlatformStand = true end)
    for _, d in ipairs(c:GetDescendants()) do
      if d:IsA("BasePart") and d ~= r then
        parkState.collide[d] = d.CanCollide
        pcall(function() d.CanCollide = false end)
      end
    end

    -- The ghost follows where you STEER; the real body stays parked. Both are
    -- re-asserted every frame because the game's own character scripts will
    -- happily move a body you left lying at the top of the world.
    local moveT = 0
    parkConn = L.hold(RS.Heartbeat:Connect(function(dt)
      if not (L.live() and Mv.want.invis) then return end
      if LP.Character ~= c then return end
      local rr, hh = r, h
      if not (rr and hh and ghost and ghost.Parent and gRoot) then return end
      pcall(function()
        rr.CFrame = PARK
        rr.AssemblyLinearVelocity = Vector3.zero
      end)
      -- drive the stand-in from the humanoid's own move vector, so it walks
      -- exactly where your input says rather than following a parked body
      moveT = moveT + dt
      local dir = hh.MoveDirection
      if dir.Magnitude > 0 then
        gRoot.CFrame = gRoot.CFrame + dir * (hh.WalkSpeed * dt)
      end
      if workspace.CurrentCamera then
        workspace.CurrentCamera.CameraSubject = ghost:FindFirstChildOfClass("Humanoid") or gRoot
      end
    end))
    return true, "parked -- other players cannot see you"
  end

  Mv._invisProp = prop

  -- Parts and decals were never the whole character. A trail, a particle
  -- emitter, a highlight or a nametag survives every transparency write and
  -- keeps drawing exactly where you are, which is most of why this read as
  -- "it does not actually hide me" even on your own screen.
  local EFFECTS = { "ParticleEmitter", "Trail", "Beam", "Fire", "Smoke",
                    "Sparkles", "Highlight", "BillboardGui", "SurfaceGui" }
  local function isEffect(d)
    for _, cls in ipairs(EFFECTS) do if d:IsA(cls) then return true end end
    return false
  end

  local function paint()
    local cc = char()
    if not cc then return end
    for _, d in ipairs(cc:GetDescendants()) do
      if d:IsA("BasePart") or d:IsA("Decal") then
        if invisSaved[d] == nil then
          local ok, v = pcall(function() return d[prop] end)
          invisSaved[d] = ok and v or 0
        end
        pcall(function() d[prop] = 1 end)
      elseif isEffect(d) then
        if invisSaved[d] == nil then
          local ok, v = pcall(function() return d.Enabled end)
          invisSaved[d] = ok and v or true
        end
        pcall(function() d.Enabled = false end)
      end
    end
    local h = hum()
    if h then
      if invisDisplaySaved[h] == nil then
        local ok, was = pcall(function() return h.DisplayDistanceType end)
        if ok then invisDisplaySaved[h] = was end
      end
      pcall(function()
        h.DisplayDistanceType = Enum.HumanoidDisplayDistanceType.None
      end)
    end
  end

  -- EVERY FRAME, NOT ON A TIMER. Roblox resets LocalTransparencyModifier on the
  -- local character every single frame as part of drawing it, so a half-second
  -- repaint loop does not make you invisible -- it makes you strobe. The set is
  -- one character's parts, so per-frame costs nothing worth measuring.
  --
  -- The write-Transparency method does NOT need this (it is not reset), but it
  -- is replicated, so it runs on the same loop only to catch parts that stream
  -- in after a respawn.
  if prop == "LocalTransparencyModifier" then
    invisConn = L.hold(RS.RenderStepped:Connect(function()
      if not (L.live() and Mv.want.invis) then return end
      local cc = char()
      if not cc then return end
      for _, d in ipairs(cc:GetDescendants()) do
        if d:IsA("BasePart") or d:IsA("Decal") then
          d.LocalTransparencyModifier = 1
        end
      end
    end))
  else
    local acc = 0
    invisConn = L.hold(RS.Heartbeat:Connect(function(dt)
      if not (L.live() and Mv.want.invis) then return end
      acc = acc + dt
      if acc < 0.5 then return end
      acc = 0
      paint()
    end))
  end
  paint()
  return true, "you are hidden on your own screen only"
end

-- ---------------------------------------------------------------- anti-void

local voidConn
local voidSafe, voidRoot

function Mv.setAntiVoid(on)
  Mv.want.antiVoid = on and true or false
  if voidConn then voidConn:Disconnect() voidConn = nil end
  if not Mv.want.antiVoid then voidSafe, voidRoot = nil, nil return true end

  voidConn = L.hold(RS.Heartbeat:Connect(function()
    if not (L.live() and Mv.want.antiVoid) then return end
    if combatPhysicsActive() then return end
    local r = root()
    local ch = LP.Character
    local hum = ch and ch:FindFirstChildOfClass("Humanoid")
    if not (r and hum and hum.Health > 0) then return end
    if voidRoot ~= r then voidRoot, voidSafe = r, nil end

    -- Trigger before Roblox's destruction plane when a game raises it above the
    -- configured floor. Combat may temporarily use NaN for its own transaction;
    -- NaN is deliberately ignored and Combat already pauses this loop.
    local rescueY = tonumber(Mv.cfg.voidFloor) or -180
    local destroyY = workspace.FallenPartsDestroyHeight
    if type(destroyY) == "number" and destroyY == destroyY then
      rescueY = math.max(rescueY, destroyY + 25)
    end

    -- Keep an actual grounded character epoch as the preferred return point.
    -- A mark remains an explicit user override, but never a stale prior body.
    if r.Position.Y > rescueY + 12
       and hum.FloorMaterial ~= Enum.Material.Air
       and r.AssemblyLinearVelocity.Magnitude < 90 then
      voidSafe = r.CFrame
    end

    if r.Position.Y < rescueY then
      local back = Mv.mark or voidSafe
        or CFrame.new(r.Position.X, rescueY + 40, r.Position.Z)
      r.CFrame = back
      r.AssemblyLinearVelocity = Vector3.zero
      r.AssemblyAngularVelocity = Vector3.zero
      pcall(function() hum:ChangeState(Enum.HumanoidStateType.GettingUp) end)
      L.note("move", "caught a fall through the void")
    end
  end))
  return true
end

-- ---------------------------------------------------------------- anti-fling

local flingConns = {}
local decolSaved = {}          -- part -> its CanCollide before we touched it
-- what the root's physical properties were before we hardened them. Stored
-- because NOT restoring these was a genuine, invisible own-goal: the hardening
-- sets elasticity to zero, which is exactly "absorb impulses rather than pass
-- them on" -- and it stayed applied after anti-fling was switched off, so every
-- fling WE attempted afterwards measured zero and nothing said why.
local physSaved, physHad = nil, false
local physRoot, stateHum, ragdollWas, fallingWas
local lastSafe, spikeUntil = nil, 0

-- WHY THIS WORKS AT ALL, AND WHERE IT STOPS.
--
-- You own your character's assembly, so the collision that flings you is
-- resolved on YOUR machine using YOUR local property values, and your result is
-- what replicates. That is the whole reason a client-side anti-fling is real
-- while client-side invisibility is not.
--
-- The attacker's own engine says the quiet part out loud: an impulse can only be
-- handed over through a CONTACT. So the strongest defence is not to survive the
-- impulse, it is to never take part in the collision -- and a client cannot
-- write another client's CanCollide in a way that replicates, which makes this
-- the one layer they cannot answer.
--
-- What is NOT achievable, and the UI must not imply it is: stopping them
-- teleporting into you, anything at all once the SERVER owns your assembly
-- (seats, vehicles, SetNetworkOwner(nil)), and server-authoritative knockback
-- delivered through the game's own remotes.

-- SUSPENDED WHILE WE ARE THE ONE ATTACKING.
--
-- Layer 1 of the anti-fling takes every other player out of our local collision
-- set, which is the strongest defence available precisely because an impulse
-- cannot cross a contact that does not exist. That is also exactly what OUR
-- fling engine needs, so with anti-fling on -- or with the guardian having armed
-- it automatically after catching a hit -- every fling silently measured zero.
--
-- Nothing in the interface explained it, and it presented as "the fling stopped
-- working". So attacking suspends the block for its duration and puts it back
-- afterwards; the velocity clamp and the position rubber-band stay on the whole
-- time, since neither interferes.
Mv.blockSuspended = false
local blockSuspensions = {}
local restoreCollisions

local function restoreCollisionsFwd()
  if not restoreCollisions then return false end
  restoreCollisions()
  return true
end

function Mv.suspendBlock(token)
  token = tostring(token or "anonymous")
  if blockSuspensions[token] then return false end
  blockSuspensions[token] = true
  Mv.blockSuspended = true
  local ok, restored = pcall(restoreCollisionsFwd)
  if not ok or not restored then
    blockSuspensions[token] = nil
    Mv.blockSuspended = next(blockSuspensions) ~= nil
    return false
  end
  return true
end

function Mv.resumeBlock(token)
  token = tostring(token or "anonymous")
  if not blockSuspensions[token] then return false end
  blockSuspensions[token] = nil
  Mv.blockSuspended = next(blockSuspensions) ~= nil
  return true
end

restoreCollisions = function()
  for part, was in pairs(decolSaved) do
    if part.Parent then pcall(function() part.CanCollide = was end) end
  end
  decolSaved = {}
end

local function restoreAntiFlingState()
  restoreCollisions()
  if physRoot and physRoot.Parent and physHad then
    pcall(function() physRoot.CustomPhysicalProperties = physSaved end)
  end
  if stateHum and stateHum.Parent then
    pcall(function()
      if ragdollWas ~= nil then
        stateHum:SetStateEnabled(Enum.HumanoidStateType.Ragdoll, ragdollWas)
      end
      if fallingWas ~= nil then
        stateHum:SetStateEnabled(Enum.HumanoidStateType.FallingDown, fallingWas)
      end
    end)
  end
  physSaved, physHad, physRoot = nil, false, nil
  stateHum, ragdollWas, fallingWas = nil, nil, nil
end

-- LAYER 1: take yourself out of everyone else's collision set, locally.
local function decollideOthers()
  if Mv.blockSuspended then return end
  for _, p in ipairs(Players:GetPlayers()) do
    if p ~= LP and p.Character then
      for _, d in ipairs(p.Character:GetDescendants()) do
        if d:IsA("BasePart") and d.CanCollide then
          if decolSaved[d] == nil then decolSaved[d] = d.CanCollide end
          d.CanCollide = false
        end
      end
    end
  end
end

-- Foreign movers: anything bolted to your root that LUMEN did not create. The
-- hub's own movers are named, so the whitelist is a name test rather than a
-- guess about what a mover is for.
local LUMEN_MOVERS = {
  LumenThrow = true, LumenLatch = true, LumenFly = true,
  LumenFlyGyro = true, LumenLatchAlign = true,
}
local function stripForeign(c, r)
  for _, d in ipairs(c:GetDescendants()) do
    if (d:IsA("BodyVelocity") or d:IsA("BodyAngularVelocity") or d:IsA("BodyThrust")
        or d:IsA("BodyForce") or d:IsA("LinearVelocity") or d:IsA("AngularVelocity")
        or d:IsA("Torque") or d:IsA("VectorForce"))
       and not LUMEN_MOVERS[d.Name] then
      pcall(function() d:Destroy() end)
    elseif d:IsA("Weld") and not LUMEN_MOVERS[d.Name] then
      -- a weld onto your root merges you into their assembly, which is exactly
      -- how the glued variant of a fling carries you along
      if d.Part1 == r or d.Part0 == r then pcall(function() d:Destroy() end) end
    end
  end
end

function Mv.setAntiFling(on)
  if combatPhysicsActive() then
    return false, "finish the active fling before changing Anti-fling"
  end
  bumpPhysicsEpoch("physical")
  Mv.want.antiFling = on and true or false
  for _, c in ipairs(flingConns) do pcall(function() c:Disconnect() end) end
  flingConns = {}
  if not Mv.want.antiFling then
    restoreAntiFlingState()
    return true
  end

  -- The budget: ordinary movement must pass untouched or this clamps the game
  -- rather than an attacker. Derived from your own walk speed, so a game that
  -- legitimately moves you fast is not fought.
  local function budget()
    local h = hum()
    local walk = (h and h.WalkSpeed) or 16
    return math.max(walk * 1.6, 60), 200          -- horizontal, vertical
  end

  local function guard()
    if not (L.live() and Mv.want.antiFling) then return end
    local c, r, h = char(), root(), hum()
    if not (c and r and h) then return end

    -- Never fight the things that are supposed to move you: a seat is
    -- server-owned anyway, and clamping your own fly or fling is self-sabotage.
    if h.SeatPart then return end
    if L.Universal and L.Universal.want and L.Universal.want.fly then return end
    if combatPhysicsActive() then return end

    if Mv.cfg.antiFlingBlockPlayers then decollideOthers() end
    stripForeign(c, r)

    local maxH, maxV = budget()
    local lv = r.AssemblyLinearVelocity
    local horiz = Vector3.new(lv.X, 0, lv.Z)
    local spiking = horiz.Magnitude > maxH * 3 or math.abs(lv.Y) > maxV * 3

    -- CLAMP EACH COMPONENT, do not rescale the vector. Rescaling to a fixed
    -- speed left you coasting at that speed in the attacker's chosen direction
    -- for the whole of their run, which is a slower fling rather than no fling.
    if horiz.Magnitude > maxH then horiz = horiz.Unit * maxH end
    local y = math.clamp(lv.Y, -maxV, maxV)
    r.AssemblyLinearVelocity = Vector3.new(horiz.X, y, horiz.Z)

    -- angular: skip entirely while Spinbot is on, or the two fight each other
    if not Mv.want.spin then
      local av = r.AssemblyAngularVelocity
      if av.Magnitude > 60 then r.AssemblyAngularVelocity = Vector3.zero end
    end

    -- LAYER 2: a real spike gets the position back, not just the speed. The
    -- clamp alone cannot retract displacement -- by the time it runs you have
    -- already been moved, and one frame at 9e7 is a long way.
    if spiking and lastSafe and os.clock() > spikeUntil then
      spikeUntil = os.clock() + 0.35
      pcall(function()
        r.CFrame = lastSafe
        r.AssemblyLinearVelocity = Vector3.zero
        r.AssemblyAngularVelocity = Vector3.zero
        h:ChangeState(Enum.HumanoidStateType.GettingUp)
      end)
      L.note("move", "anti-fling put you back")
    elseif not spiking and h.FloorMaterial ~= Enum.Material.Air then
      lastSafe = r.CFrame                 -- only remember somewhere you stood
    end
  end

  -- BOTH HOOKS. Stepped is pre-physics, so the impulse is caught before it is
  -- integrated; Heartbeat is post-physics and mops up whatever the step still
  -- produced. Either alone concedes a frame, and a frame is the whole attack.
  flingConns[#flingConns + 1] = L.hold(RS.Stepped:Connect(guard))
  flingConns[#flingConns + 1] = L.hold(RS.Heartbeat:Connect(guard))

  -- LAYER 4: passive hardening. Heavier and completely inelastic, so each
  -- contact that does land transfers less and nothing bounces.
  local r = root()
  if r then
    if not physHad or physRoot ~= r then
      if physHad then restoreAntiFlingState() end
      lastSafe, spikeUntil = nil, 0
      local ok, was = pcall(function() return r.CustomPhysicalProperties end)
      physSaved, physHad, physRoot = (ok and was or nil), true, r
    end
    -- DENSITY, BUT NOT ZERO ELASTICITY.
    --
    -- Both reduce how much a contact moves you, so the first version used both.
    -- But elasticity is symmetric: setting it to zero also stops US handing an
    -- impulse to anybody, and because the hardening survived re-execution it
    -- quietly disabled our own fling for the rest of the session. The full
    -- chain, measured: Guardian persists on -> catches a hit -> arms anti-fling
    -- -> hardens the root -> every fling we attempt afterwards reads zero.
    --
    -- Mass alone carries almost all of the defensive benefit, since delta-v goes
    -- as m_them/(m_you + m_them). A modest elasticity keeps us able to hit back.
    pcall(function()
      r.CustomPhysicalProperties = PhysicalProperties.new(100, 0.3, 0.35, 1, 1)
    end)
  end
  local h = hum()
  if h then
    if stateHum ~= h then
      stateHum = h
      local okR, wasR = pcall(function()
        return h:GetStateEnabled(Enum.HumanoidStateType.Ragdoll)
      end)
      local okF, wasF = pcall(function()
        return h:GetStateEnabled(Enum.HumanoidStateType.FallingDown)
      end)
      ragdollWas = okR and wasR or nil
      fallingWas = okF and wasF or nil
    end
    pcall(function()
      h:SetStateEnabled(Enum.HumanoidStateType.Ragdoll, false)
      h:SetStateEnabled(Enum.HumanoidStateType.FallingDown, false)
    end)
  end
  return true
end

-- ---------------------------------------------------------------- guardian
--
-- THE ONE THAT RUNS WHILE YOU ARE NOT LOOKING.
--
-- Anti-fling above is a clamp: it fights the physics every frame whether or not
-- anything is happening. This is different -- it watches, and only acts when
-- something has actually gone wrong. That makes it cheap enough to leave on for
-- hours, which is the point, because the whole failure it exists for is "I left
-- the script running and came back to find myself in orbit".
--
-- Three jobs, all of them things you would otherwise have to remember:
--   * you got flung          -> snap back to where you were standing, and drop
--                               out of everyone else's collision set so the
--                               next one cannot land either
--   * you are about to be
--     idle-kicked            -> arm anti-AFK before the twenty minutes are up
--   * somebody keeps doing it -> optionally hand the problem back to them
--
-- WHAT IT CANNOT DO HONESTLY: name the attacker. Nothing in the engine says who
-- applied an impulse. The best available inference is "whoever was closest and
-- spinning when it landed", which is a guess -- so retaliation is off by default
-- and says so, rather than confidently punishing a bystander.
local guardConns = {}
Mv.guard = { flungCount = 0, lastFlung = 0, lastSuspect = nil, afkArmed = false }

local function guardianRestore(root, hum, safe)
  pcall(function()
    root.AssemblyLinearVelocity = Vector3.zero
    root.AssemblyAngularVelocity = Vector3.zero
    if safe then root.CFrame = safe end
    if hum then hum:ChangeState(Enum.HumanoidStateType.GettingUp) end
  end)
end

-- Closest player who was spinning hard at the moment it landed. A guess, and
-- labelled as one everywhere it surfaces.
local function suspectNear(root)
  local best, score
  for _, p in ipairs(Players:GetPlayers()) do
    if p ~= LP and p.Character then
      local r = p.Character:FindFirstChild("HumanoidRootPart")
      if r then
        local d = (r.Position - root.Position).Magnitude
        if d < 60 then
          local spin = r.AssemblyAngularVelocity.Magnitude
          if spin ~= spin then spin = 0 end
          -- near AND spinning beats merely near
          local sc = (spin > 50 and 1000 or 0) - d
          if not score or sc > score then best, score = p, sc end
        end
      end
    end
  end
  return best
end

function Mv.setGuardian(on)
  Mv.want.guardian = on and true or false
  for _, c in ipairs(guardConns) do pcall(function() c:Disconnect() end) end
  guardConns = {}
  if not Mv.want.guardian then return true end

  local safe, safeRoot, lastCheck = nil, nil, 0
  guardConns[#guardConns + 1] = L.hold(RS.Heartbeat:Connect(function()
    if not (L.live() and Mv.want.guardian) then return end
    local c, r, h = char(), root(), hum()
    if not (c and r and h) then return end
    if h.Health <= 0 or h.SeatPart then return end
    -- never fight our own tools
    if L.Universal and L.Universal.want and L.Universal.want.fly then return end
    if combatPhysicsActive() then return end

    -- The loop resolves root dynamically, so bind its rollback point to the
    -- body that produced it. A respawn must never inherit the previous body's
    -- CFrame and get snapped into another life/map on its first velocity spike.
    if safeRoot ~= r then safe, safeRoot = nil, r end

    local lv = r.AssemblyLinearVelocity
    local speed = lv.Magnitude
    local budget = math.max((h.WalkSpeed or 16) * 4, 120)

    if speed ~= speed or speed > budget then
      -- IT IS HAPPENING NOW
      local g = Mv.guard
      local now = os.clock()
      if now - g.lastFlung > 1.5 then g.flungCount = g.flungCount + 1 end
      g.lastFlung = now
      g.lastSuspect = suspectNear(r)
      guardianRestore(r, h, safe)

      if Mv.cfg.guardDecollide and L.Move and Mv.setAntiFling and not Mv.want.antiFling then
        -- borrow the strongest layer we already have: out of their collision set
        Mv.cfg.antiFlingBlockPlayers = true
        L.try("guard.antifling", Mv.setAntiFling, true)
        if L.Toast then
          L.Toast.warn("Guardian", "You were flung -- collision blocking is now on.")
        end
      elseif L.Toast and g.flungCount <= 3 then
        L.Toast.warn("Guardian", "Caught a fling and put you back.")
      end

      if Mv.cfg.guardRetaliate and g.lastSuspect and L.Combat then
        local who = g.lastSuspect.Name
        if not combatPhysicsActive() then
          L.Combat.cfg.flingMode = "Loop one target"
          L.Combat.cfg.flingAttach = "Contact lock"
          L.try("guard.retaliate", L.Combat.startFling, who)
          if L.Toast then
            L.Toast.info("Guardian", "Best guess: " .. who .. ". Returning the favour.")
          end
        end
      end
    elseif h.FloorMaterial ~= Enum.Material.Air then
      safe = r.CFrame                   -- only remember somewhere we stood
    end

    -- ---- idle kick, handled before it happens ------------------------
    if Mv.cfg.guardAntiAfk and os.clock() - lastCheck > 30 then
      lastCheck = os.clock()
      if not Mv.guard.afkArmed and L.Universal and L.Universal.setAntiAfk
         and not (L.Universal.want and L.Universal.want.antiAfk) then
        L.try("guard.afk", L.Universal.setAntiAfk, true)
        Mv.guard.afkArmed = true
        if L.Toast then
          L.Toast.info("Guardian", "Anti-AFK armed so the idle kick cannot land.")
        end
      end
    end
  end))
  return true
end

L.cleanup(function()
  Mv.want.freeze = false
  pcall(Mv.setFreeze, false)
  Mv.want.spin = false
  pcall(Mv.setSpin, false)
  Mv.want.invis = false
  pcall(Mv.setInvis, false)
  Mv.want.antiVoid = false
  pcall(Mv.setAntiVoid, false)
  Mv.want.guardian = false
  pcall(Mv.setGuardian, false)
  Mv.want.antiFling = false
  pcall(Mv.setAntiFling, false)
  pcall(Mv.resetGravity)
end, 50)

-- ---------------------------------------------------------------- residue
--
-- STATE FROM A PREVIOUS INSTANCE OUTLIVES THE INSTANCE THAT MADE IT.
--
-- Anti-fling hardens the root with zero elasticity, and stores the original so
-- it can hand it back. That works within one run -- but re-executing the script
-- creates a fresh module with an empty memory, so hardening applied by the
-- PREVIOUS instance can never be undone by this one. Measured: density 100 left
-- on the root after anti-fling reported itself off, which silently absorbed
-- every impulse our own fling tried to deliver.
--
-- So a fresh instance clears what it can recognise as ours. Density 100 with
-- zero elasticity is not a value any game sets by accident; it is our
-- fingerprint, and clearing it back to default is the correct repair.
task.spawn(function()
  task.wait(2)
  if not L.live() or Mv.want.antiFling or combatPhysicsActive() then return end
  L.try("move.residue", function()
    local r = root()
    if not r then return end
    local pp = r.CustomPhysicalProperties
    if pp and math.abs(pp.Density - 100) < 0.001 then
      r.CustomPhysicalProperties = nil
      L.note("move", "cleared hardening left by an earlier run")
    end
  end)
end)

-- ---------------------------------------------------------------- marks

function Mv.saveMark()
  local r = root()
  if not r then return false, "no character" end
  Mv.mark = r.CFrame
  return true, string.format("saved %d, %d, %d",
    r.Position.X, r.Position.Y, r.Position.Z)
end

function Mv.returnToMark()
  local r = root()
  if not r then return false, "no character" end
  if not Mv.mark then return false, "nothing saved yet", "user" end
  r.CFrame = Mv.mark
  return true, "back at the mark"
end

-- ---------------------------------------------------------------- server

function Mv.rejoin()
  local ok, err = pcall(function()
    TS:TeleportToPlaceInstance(game.PlaceId, game.JobId, LP)
  end)
  if not ok then return false, tostring(err) end
  return true, "rejoining this server"
end

function Mv.copyJobId()
  local ok = pcall(function() setclipboard(game.JobId) end)
  return ok, ok and game.JobId or "no clipboard"
end

function Mv.copyJoinScript()
  local s = string.format(
    'game:GetService("TeleportService"):TeleportToPlaceInstance(%d, "%s", game.Players.LocalPlayer)',
    game.PlaceId, game.JobId)
  local ok = pcall(function() setclipboard(s) end)
  return ok, ok and "join script copied" or "no clipboard"
end

-- Server hop needs the public-servers endpoint, which needs http. Without it the
-- honest answer is that we cannot pick a different server, not a silent no-op.
function Mv.serverHop()
  local req = rawget(getgenv(), "request") or rawget(getgenv(), "http_request")
  if type(req) ~= "function" then return false, "this executor has no request" end
  local url = string.format(
    "https://games.roblox.com/v1/games/%d/servers/Public?sortOrder=Asc&limit=100",
    game.PlaceId)
  local ok, res = pcall(req, { Url = url, Method = "GET" })
  if not ok or type(res) ~= "table" then return false, "could not list servers" end
  local decoded, data = pcall(function() return L.Http:JSONDecode(res.Body) end)
  if not decoded or type(data) ~= "table" then return false, "unreadable server list" end

  local pool = {}
  for _, s in ipairs(data.data or {}) do
    if s.id ~= game.JobId and (s.playing or 0) < (s.maxPlayers or 0) then
      pool[#pool + 1] = s.id
    end
  end
  if #pool == 0 then return false, "no other server has room" end
  local pick = pool[math.random(1, #pool)]
  local tok, terr = pcall(function()
    TS:TeleportToPlaceInstance(game.PlaceId, pick, LP)
  end)
  if not tok then return false, tostring(terr) end
  return true, string.format("hopping to another server (%d found)", #pool)
end

-- ---------------------------------------------------------------- respawn
--
-- WITHOUT THIS, EVERY TOGGLE ON THIS PAGE IS A LIE THE MOMENT YOU DIE. Each one
-- edits a property of a character that is about to be destroyed and replaced, so
-- the switch stays on, the loop keeps running against a stale part, and nothing
-- happens -- which is worse than it having turned itself off, because the UI
-- still says it is working.
--
-- Same shape as L.Universal's: intent is stored, and the intent is re-applied to
-- whatever character exists now.
L.hold(LP.CharacterAdded:Connect(function(c)
  if not L.live() then return end
  lastSafe, spikeUntil, voidSafe, voidRoot = nil, 0, nil, nil
  local rearmPark = Mv.want.invis and parkState ~= nil
  if rearmPark then
    Mv.setInvis(false)
    Mv.want.invis = true
  end
  c:WaitForChild("HumanoidRootPart", 8)
  task.wait(0.35)
  if not L.live() or LP.Character ~= c then return end
  L.try("move.respawn", function()
    -- invisibility first: it walks the new character's parts, and doing it after
    -- freeze would paint an anchored body
    if Mv.want.invis then
      if not rearmPark then Mv.setInvis(false) end
      Mv.setInvis(true)
    end
    if Mv.want.freeze then Mv.setFreeze(false) Mv.setFreeze(true) end
    if Mv.want.spin then Mv.setSpin(false) Mv.setSpin(true) end
    -- these two run off the root and only need their loops pointed at the new
    -- one, which their own root() lookup does per tick
    if Mv.want.antiVoid then Mv.setAntiVoid(true) end
    if Mv.want.antiFling then
      if combatPhysicsActive() then
        -- Touch fling intentionally survives a respawn. Anti-fling's old
        -- connections resolve the new root, but its exact physical snapshot is
        -- still bound to the dead body. Rebind as soon as Combat releases all
        -- physics ownership; keep this generation/body/intent guarded.
        task.spawn(function()
          while L.live() and LP.Character == c and Mv.want.antiFling
                and combatPhysicsActive() do
            task.wait(0.1)
          end
          if L.live() and LP.Character == c and Mv.want.antiFling then
            L.try("move.respawn.antifling", Mv.setAntiFling, true)
          end
        end)
      else
        Mv.setAntiFling(true)
      end
    end
    -- gravity is a workspace property and survives, but a game that resets it on
    -- spawn would otherwise silently win
    if savedGravity ~= nil then workspace.Gravity = Mv.cfg.gravity end
  end)
end))

-- ---------------------------------------------------------------- ui

function Mv.build(page)
  C.ctx("movement")
  C.section(page, "physics")

  C.slider(page, {
    text = "Gravity", desc = "Default is 196",
    min = 0, max = 2000, step = 1, default = 196,
    callback = function(v) Mv.setGravity(v) end,
  })
  C.toggle(page, {
    text = "Freeze in place", desc = "Stops you moving",
    default = false, callback = function(v) return Mv.setFreeze(v) end,
  })
  C.dropdown(page, {
    text = "Freeze method", desc = "Try another if one is undone",
    when = "movement.physics.Freeze in place",
    items = Mv.FREEZE, default = Mv.cfg.freezeMethod,
    callback = function(v)
      Mv.cfg.freezeMethod = v
      if Mv.want.freeze then Mv.setFreeze(false) Mv.setFreeze(true) end
    end,
  })
  C.toggle(page, {
    text = "Spinbot", desc = "Constant rotation",
    default = false, callback = function(v) return Mv.setSpin(v) end,
  })
  C.slider(page, {
    text = "Spin speed", desc = "How fast",
    when = "movement.physics.Spinbot",
    min = 0.1, max = 5000, step = 0.1, curve = "log", default = Mv.cfg.spinSpeed,
    callback = function(v) Mv.cfg.spinSpeed = v end,
  })

  C.section(page, "protection")

  C.toggle(page, {
    text = "Anti-void", desc = "Catches you below the map",
    default = false, callback = function(v) return Mv.setAntiVoid(v) end,
  })
  C.slider(page, {
    text = "Void floor", desc = "The height that counts as fallen",
    min = -100000, max = -1, step = 1, default = Mv.cfg.voidFloor,
    callback = function(v) Mv.cfg.voidFloor = v end,
  })
  C.toggle(page, {
    text = "Anti-fling", desc = "Budgets velocity and puts you back if launched",
    default = false, callback = function(v) return Mv.setAntiFling(v) end,
  })
  C.toggle(page, {
    text = "Guardian",
    desc = "Watches while you are away: catches flings, puts you back, arms anti-AFK",
    default = false,
    callback = function(v) return Mv.setGuardian(v) end,
  })
  C.toggle(page, {
    text = "Guardian: block collisions when hit",
    desc = "First fling that lands takes you out of everyone's collision set",
    when = "movement.protection.Guardian",
    default = Mv.cfg.guardDecollide,
    callback = function(v) Mv.cfg.guardDecollide = v end,
  })
  C.toggle(page, {
    text = "Guardian: arm anti-AFK",
    desc = "Turns anti-AFK on for you before the twenty minute idle kick",
    when = "movement.protection.Guardian",
    default = Mv.cfg.guardAntiAfk,
    callback = function(v) Mv.cfg.guardAntiAfk = v end,
  })
  C.toggle(page, {
    text = "Guardian: fling them back",
    desc = "Off by default -- the engine cannot name an attacker, so this GUESSES",
    when = "movement.protection.Guardian",
    default = Mv.cfg.guardRetaliate,
    callback = function(v)
      Mv.cfg.guardRetaliate = v
      if v then
        L.Toast.warn("Retaliation is a guess",
          "Nothing reports who flung you. It picks the closest spinning player, " ..
          "which in a crowd can be the wrong one.")
      end
    end,
  })
  C.toggle(page, {
    text = "Block player collisions",
    desc = "The strongest layer -- they cannot fling what they cannot touch",
    default = Mv.cfg.antiFlingBlockPlayers,
    callback = function(v)
      Mv.cfg.antiFlingBlockPlayers = v
      if Mv.want.antiFling then Mv.setAntiFling(false) Mv.setAntiFling(true) end
    end,
  })

  C.section(page, "hide")

  C.toggle(page, {
    text = "Invisibility", desc = "Park is the only one others can see",
    default = false,
    callback = function(v)
      local ok, why = Mv.setInvis(v)
      if ok and v and why then L.Toast.info("Invisibility", why) end
      return ok
    end,
  })
  C.dropdown(page, {
    text = "Invisibility method",
    desc = "The two transparency ones hide you from yourself only",
    items = Mv.INVIS, default = Mv.cfg.invisMethod,
    callback = function(v)
      -- undo with the OLD method still selected, or the restore writes the
      -- saved values into the wrong property and leaves you painted
      local was = Mv.want.invis
      if was then Mv.setInvis(false) end
      Mv.cfg.invisMethod = v
      if was then Mv.setInvis(true) end
    end,
  })
  C.slider(page, {
    text = "Stand-in fade", desc = "How solid your own copy looks while parked",
    min = 0, max = 1, step = 0.01, default = Mv.cfg.ghostFade,
    callback = function(v) Mv.cfg.ghostFade = v end,
  })
  C.section(page, "position")

  C.actions(page, {
    { text = "Save this spot", primary = true, callback = function()
        local ok, why = Mv.saveMark()
        if ok then L.Toast.ok("Marked", why) else L.Toast.warn("Mark", why) end
      end },
    { text = "Return to mark", callback = function()
        local ok, why, kind = Mv.returnToMark()
        if ok then L.Toast.ok("Returned", why)
        else L.Toast.warn("Return", tostring(why)) end
      end },
  })

  C.section(page, "server")

  C.actions(page, {
    { text = "Server hop", primary = true, callback = function()
        local ok, why = Mv.serverHop()
        if ok then L.Toast.ok("Hopping", why)
        else L.Toast.warn("Server hop", tostring(why)) end
      end },
    { text = "Rejoin", callback = function()
        local ok, why = Mv.rejoin()
        if ok then L.Toast.ok("Rejoining", why)
        else L.Toast.warn("Rejoin", tostring(why)) end
      end },
  })
  C.actions(page, {
    { text = "Copy job id", callback = function()
        local ok, why = Mv.copyJobId()
        if ok then L.Toast.ok("Copied", why) else L.Toast.warn("Clipboard", why) end
      end },
    { text = "Copy join script", callback = function()
        local ok, why = Mv.copyJoinScript()
        if ok then L.Toast.ok("Copied", why) else L.Toast.warn("Clipboard", why) end
      end },
  })

  C.actions(page, {
    { text = "Turn everything off", primary = true, callback = function()
        Mv.setFreeze(false) Mv.setSpin(false) Mv.setInvis(false)
        Mv.setAntiVoid(false) Mv.setAntiFling(false) Mv.resetGravity()
        L.Toast.ok("Movement reset", "Physics and protection cleared.")
      end },
  })
end

end
do -- ==== lm_22_side.lua ====
-- LUMEN :: SIDE
-- The player panel: a resizable drawer that slides out from behind the window.
--
-- WHY A SECOND PANEL AND NOT A MENU. Picking a player is a browsing task -- you
-- scan faces, compare distances, change your mind, act, then look again. A
-- popover that covers the page and closes on the first click is the wrong shape
-- for that. This stays open while you work, sorts and filters, and keeps a
-- selection you can act on more than once.
--
-- It normally lives in the hub shell, then moves into its own ScreenGui while
-- the hub is minimised so the detached panel remains visible and draggable.

local L = getgenv().LUMEN
local T, M, A, C = L.T, L.Motion, L.A, L.C
local mk = L.mk
local Players = game:GetService("Players")

local Side = {}
L.Side = Side

Side.open = false

-- Three steps rather than a drag handle: a free resize needs a min/max, a
-- persisted rect, and a grip on an edge that is tucked under the window, and
-- none of that buys anything over picking the size you want.
Side.SIZES = {
  { name = "Compact", w = 300, h = 380, row = 44 },
  { name = "Regular", w = 348, h = 470, row = 52 },
  { name = "Wide",    w = 396, h = 560, row = 58 },
}

Side.state = { size = 2, sort = "distance", query = "", selected = nil }

-- Session cache of headshot URLs, keyed by UserId. Weak keys are pointless here
-- (a number is not collectable) and the table is bounded by the server size.
Side._thumbs = Side._thumbs or {}

Side.SORTS = { "distance", "name" }
Side.SORT_LABEL = { distance = "D", name = "A" }
Side.SORT_HINT  = {
  distance = "Sorted by distance -- nearest first. Click for A to Z.",
  name     = "Sorted A to Z. Click for nearest first.",
}

local PAD = 12
-- One pitch for the header button group: 22 px chip on a 4 px gutter. Every
-- button position below is SLOT * n, so they cannot collide by arithmetic.
local SLOT = 26

-- ---------------------------------------------------------------- helpers

local function sizeDef()
  return Side.SIZES[math.clamp(Side.state.size, 1, #Side.SIZES)]
end

local function humanoidOf(name)
  local p = Players:FindFirstChild(name)
  local ch = p and p.Character
  return ch and ch:FindFirstChildOfClass("Humanoid"), ch
end

local function distanceTo(name)
  local mine = L.LP.Character and L.LP.Character:FindFirstChild("HumanoidRootPart")
  local _, ch = humanoidOf(name)
  local theirs = ch and ch:FindFirstChild("HumanoidRootPart")
  if not (mine and theirs) then return nil end
  return (mine.Position - theirs.Position).Magnitude
end

-- IT IS A DRAWER, NOT A SATELLITE.
--
-- The previous version floated the panel in free space and drew a curve of dots
-- between it and the window to imply a connection. Dots on a bezier are a
-- diagram of a link, not a link -- and at any real size they read as debris.
--
-- So the panel is not connected to the window, it is PART of it: a child of the
-- shell whose inner edge is tucked underneath the window body, so it slides out
-- from behind it and the join has no seam to get wrong. There is nothing to draw
-- between them because there is no gap.
local TUCK = 26           -- how far the inner edge hides under the window

local watchRoster   -- defined with the detach block below

-- ---------------------------------------------------------------- rows

-- A CARD, WITH ITS OWN ACTIONS ON IT.
--
-- The first version put one shared action bar at the bottom and made you select
-- a player before you could do anything. That is a two-step for a one-step job,
-- and it means the panel carries a footer whether or not anyone is picked.
-- Every card now owns its buttons, so acting on someone is a single click on the
-- thing you are already looking at -- the shape DEV HUD landed on, and it was
-- right. What is added on top of that: a presence dot that reads before the text
-- does, health that only speaks up once it matters, and detail lines that stay
-- live while the card is open rather than being a snapshot from when you opened
-- it.
local function buildRow(self, name, i, animate)
  local p = Players:FindFirstChild(name)
  if not p then return nil end

  -- NO AutomaticSize ON THE CARD.
  --
  -- A.interactive hangs four UDim2.fromScale(1, 1) overlays on whatever it is
  -- given. With AutomaticSize.Y the card grows to fit a child whose height is
  -- defined AS the card's height -- a feedback loop that creeps upward every
  -- time the pointer touches it. Measured live: two cards at 367 and 202 px
  -- around a body of 96. Moving the layout into Body stopped them STACKING but
  -- not this.
  --
  -- The body measures itself from its own list; the card simply follows it.
  local card = mk("Frame", {
    Size = UDim2.new(1, 0, 0, 96),
    BackgroundColor3 = T.c.raised, BackgroundTransparency = 0.35,
    BorderSizePixel = 0, LayoutOrder = i, ZIndex = 6,
    Name = "P_" .. name, Parent = self.list,
  })
  L.corner(T.r.md, card)
  local st = L.stroke(T.c.line, 1, 0.72, card)
  -- top-to-bottom shade, so a stack of cards has depth instead of reading as one
  -- flat block of rectangles
  mk("UIGradient", { Rotation = 90,
    Color = ColorSequence.new(T.c.raised, T.c.surface), Parent = card })

  -- THE LAYOUT GOES ON AN INNER FRAME, NOT ON THE CARD.
  --
  -- A.interactive hangs four full-size children on whatever it is given -- the
  -- state wash, the hit target, the sweep, the spotlight host -- all sized
  -- UDim2.fromScale(1, 1). Put a UIListLayout on that same frame and those
  -- overlays become LAYOUT ITEMS: each one is stacked below the content and
  -- measures a full card tall, which then grows the card, which grows them.
  -- Measured before the fix: every row 13056 px high and a 38990 px canvas, so
  -- the list rendered as an empty black column.
  --
  -- Scale-sized children contribute nothing to AutomaticSize, so with the layout
  -- moved inside, the card still hugs its content and the hover effects still
  -- cover the whole card.
  local body = mk("Frame", {
    Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y,
    BackgroundTransparency = 1, ZIndex = 7, Name = "Body", Parent = card,
  })
  L.list(0, Enum.FillDirection.Vertical, body)
  local function fitCard()
    if not (card.Parent and body.Parent) then return end
    local sc = (L.Hub.window and L.Hub.window.scaleObj and L.Hub.window.scaleObj.Scale) or 1
    local h = body.AbsoluteSize.Y / sc
    if h > 8 and math.abs(card.Size.Y.Offset - h) > 0.5 then
      card.Size = UDim2.new(1, 0, 0, h)
    end
  end
  body:GetPropertyChangedSignal("AbsoluteSize"):Connect(fitCard)

  -- ---- identity -------------------------------------------------------
  local top = mk("Frame", {
    Size = UDim2.new(1, 0, 0, 58), BackgroundTransparency = 1,
    LayoutOrder = 1, ZIndex = 7, Parent = body,
  })

  local av = mk("ImageLabel", {
    Position = UDim2.fromOffset(11, 9), Size = UDim2.fromOffset(40, 40),
    BackgroundColor3 = T.c.overlay, BackgroundTransparency = 0.1,
    BorderSizePixel = 0, ImageTransparency = 1,
    ScaleType = Enum.ScaleType.Crop, ZIndex = 8, Name = "Head", Parent = top,
  })
  L.corner(999, av)
  L.stroke(T.c.lineStrong, 1, 0.5, av)

  -- presence dot: never spawned, alive, or dead -- legible before you have read
  -- a single word of the card
  local dot = mk("Frame", {
    AnchorPoint = Vector2.new(1, 1),
    Position = UDim2.fromOffset(52, 50), Size = UDim2.fromOffset(11, 11),
    BackgroundColor3 = T.c.textOff, BorderSizePixel = 0, ZIndex = 9, Parent = top,
  })
  L.corner(999, dot)
  L.stroke(T.c.surface, 2, 0, dot)

  -- HEADSHOTS ARE CACHED FOR THE SESSION.
  --
  -- GetUserThumbnailAsync is a yielding web call, and refresh() rebuilds every
  -- row -- on every roster change, on every search keystroke, on every sort. So
  -- each rebuild re-fetched a picture of somebody whose face has not changed,
  -- and every avatar restarted from ImageTransparency 1 while it did. That is
  -- the flicker: not a slow request, a request that should never have been made
  -- a second time.
  --
  -- Keyed by UserId rather than name, because a display name can change inside
  -- a session and the picture it points at does not.
  local cachedUrl = Side._thumbs[p.UserId]
  if cachedUrl then
    av.Image = cachedUrl
    av.ImageTransparency = 0        -- already loaded once; do not re-fade it
  else
    task.spawn(function()
      local ok, url = pcall(function()
        return Players:GetUserThumbnailAsync(p.UserId,
          Enum.ThumbnailType.HeadShot, Enum.ThumbnailSize.Size150x150)
      end)
      if ok and url then
        Side._thumbs[p.UserId] = url
        if av.Parent then
          av.Image = url
          M.to(av, "ImageTransparency", 0, "base")
        end
      end
    end)
  end

  A.text({
    Text = (p.DisplayName ~= "" and p.DisplayName) or name,
    font = T.font.strong, size = T.size.body, colour = T.c.text,
    Position = UDim2.fromOffset(60, 9), Size = UDim2.new(1, -158, 0, 16),
    truncate = true, ZIndex = 8, Parent = top,
  })
  A.text({
    Text = "@" .. name, font = T.font.mono, size = T.size.micro, colour = T.c.textOff,
    Position = UDim2.fromOffset(60, 27), Size = UDim2.new(1, -158, 0, 13),
    truncate = true, ZIndex = 8, Parent = top,
  })
  local dist = A.text({
    Text = "--", font = T.font.mono, size = T.size.micro, colour = T.c.textDim,
    align = Enum.TextXAlignment.Right, AnchorPoint = Vector2.new(1, 0),
    Position = UDim2.new(1, -12, 0, 11), Size = UDim2.fromOffset(82, 14),
    ZIndex = 8, Parent = top,
  })

  local hpTrack = mk("Frame", {
    Position = UDim2.fromOffset(60, 46), Size = UDim2.fromOffset(64, 3),
    BackgroundColor3 = T.c.line, BackgroundTransparency = 0.72,
    BorderSizePixel = 0, ZIndex = 8, Parent = top,
  })
  L.corner(999, hpTrack)
  local hpFill = mk("Frame", {
    Size = UDim2.fromScale(1, 1), BackgroundColor3 = T.c.ok,
    BackgroundTransparency = 0.5, BorderSizePixel = 0, ZIndex = 9, Parent = hpTrack,
  })
  L.corner(999, hpFill)

  local roleLbl = A.text({
    Text = "", font = T.font.mono, size = T.size.micro, colour = T.c.textOff,
    align = Enum.TextXAlignment.Right, AnchorPoint = Vector2.new(1, 0),
    Position = UDim2.new(1, -12, 0, 41), Size = UDim2.fromOffset(118, 12),
    truncate = true, ZIndex = 8, Parent = top,
  })

  -- ---- actions --------------------------------------------------------
  local pills = mk("Frame", {
    Size = UDim2.new(1, 0, 0, 38), BackgroundTransparency = 1,
    LayoutOrder = 2, ZIndex = 7, Parent = body,
  })
  local info = mk("Frame", {
    Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y,
    BackgroundTransparency = 1, Visible = false, LayoutOrder = 3,
    ZIndex = 7, Parent = body,
  })
  L.pad(0, 12, 12, 12, info)
  L.list(3, Enum.FillDirection.Vertical, info)

  -- GROUPED BY WHAT THEY DO, NOT BY WHO REGISTERED THEM.
  --
  -- Seven identical pills in a row is a list to read every time; the eye has no
  -- structure to shortcut. They are the same seven controls in the same order,
  -- with a hairline between the three groups so the row reads as
  -- "go to them / act on them / manage them" at a glance:
  --
  --     Goto View | Fling Pick | Hide Mark Info
  --
  -- A divider rather than extra spacing, because these pills are laid out in
  -- fractions of the row -- inserting pixel gaps would push the last pill past
  -- the edge at the narrow panel size.
  -- A HAIRLINE IS NOT ENOUGH TO CARRY THE GROUPING.
  --
  -- The three groups above were already separated by a 1 px rule, and in the
  -- panel as shipped they still read as seven identical grey pills -- the rule
  -- is a pixel wide against a busy card, and every pill had the same fill, the
  -- same stroke and the same dim label. Nothing told you that Fling does
  -- something TO somebody and Info does not.
  --
  -- Ink carries it instead, and only ink: the fill and the geometry stay exactly
  -- as they were, so the row is no louder than before. Brightest for the two you
  -- actually press, warm for the two that act on a person, dimmest for the three
  -- that only change what you are looking at. The eye reads bright-warm-dim in
  -- one pass without reading a single word.
  local WARM = T.c.warn:Lerp(T.c.textDim, 0.42)
  local GROUP_OF = { Goto = 1, View = 1, Fling = 2, Pick = 2,
                     Hide = 3, Mark = 3, Info = 3 }
  local GROUP_INK = { T.c.text, WARM, T.c.textMute }
  -- the hover light picks up the same three, so the grouping survives the state
  -- change instead of being contradicted by it
  local GROUP_LIT = { T.c.accent, T.c.warn, T.c.lineStrong }

  local labels = { "Goto", "View", "Fling", "Pick", "Hide", "Mark", "Info" }
  local groupAfter = { View = true, Pick = true }
  local made, n = {}, #labels
  for k, label in ipairs(labels) do
    local g = GROUP_OF[label] or 3
    local b = mk("Frame", {
      Position = UDim2.new((k - 1) / n, k == 1 and 11 or 4, 0, 0),
      Size = UDim2.new(1 / n, k == 1 and -15 or -8, 0, 26),
      BackgroundColor3 = T.c.overlay, BackgroundTransparency = 0.1,
      BorderSizePixel = 0, ZIndex = 8, Parent = pills,
    })
    L.corner(T.r.sm, b)
    L.stroke(g == 2 and T.c.warn or T.c.lineStrong, 1, g == 2 and 0.72 or 0.45, b)
    local lbl = A.text({
      Text = label, font = T.font.medium, size = T.size.micro,
      colour = GROUP_INK[g],
      align = Enum.TextXAlignment.Center, Size = UDim2.fromScale(1, 1),
      ZIndex = 9, Parent = b,
    })
    -- REST IS RECORDED, NOT ASSUMED. Five of these pills toggle their own label
    -- colour and every one of them restored to a hardcoded T.c.textDim, which
    -- would have quietly flattened the grouping the first time you pressed one.
    made[label] = { frame = b, label = lbl, ink = GROUP_INK[g], lit = GROUP_LIT[g] }

    if groupAfter[label] then
      local sep = mk("Frame", {
        AnchorPoint = Vector2.new(0.5, 0.5),
        Position = UDim2.new(k / n, 2, 0.5, 0), Size = UDim2.fromOffset(1, 12),
        BackgroundColor3 = T.c.lineStrong, BackgroundTransparency = 0.55,
        BorderSizePixel = 0, ZIndex = 8, Parent = pills,
      })
      sep.Name = "GroupRule"
    end
  end

  -- FOUR CHARACTERS EACH, because a card is narrow. None of them says what it
  -- does, which is exactly what the hover explanations are for.
  local PILL_HELP = {
    Goto = "Teleport yourself to them",
    View = "Watch them through your camera. Press again to come back",
    Fling = "Throw them, using the technique set in Combat",
    Pick = "Add them to the Selected group the fling engine walks",
    Hide = "Stop outlining this one player in the ESP",
    Mark = "Track them: the ESP keeps a line on them wherever they go",
    Info = "Open their user id, account age, team and live position",
  }
  for label, help in pairs(PILL_HELP) do
    if made[label] then A.explain(made[label].frame, help) end
  end

  local rec = { card = card, name = name, player = p, stroke = st,
                 dist = dist, dot = dot, hpFill = hpFill, hpTrack = hpTrack,
                 roleLbl = roleLbl, info = info, pills = made,
                 built = false, expanded = false }

  A.interactive(made.Goto.frame, { radius = T.r.sm, spotSize = 70, spotColour = made.Goto.lit, onClick = function()
    Side.state.selected = name
    Side.actTeleport()
  end })
  A.interactive(made.View.frame, { radius = T.r.sm, spotSize = 70, spotColour = made.View.lit, onClick = function()
    Side.state.selected = name
    Side.actSpectate()
    local on = Side.spectating == name
    made.View.label.Text = on and "Stop" or "View"
    M.to(made.View.label, "TextColor3", on and T.c.accent or made.View.ink, "fast")
    if Side.refreshView then Side.refreshView() end
  end })
  -- FLING FROM THE CARD. Typing a name into a box to fling somebody is the
  -- wrong shape for the job: you already have every player in front of you with
  -- their face on. This starts on whoever you clicked, and turns into the stop
  -- button while it runs, so the same pill both starts and ends it.
  local function paintFling()
    local combat = L.Combat
    local on = combat and combat.flinging and combat.flingTarget == name or false
    if rec.flingOn == on then return end
    rec.flingOn = on
    made.Fling.label.Text = on and "Stop" or "Fling"
    M.to(made.Fling.label, "TextColor3", on and T.c.bad or made.Fling.ink, "fast")
  end
  paintFling()
  task.spawn(function()
    while rec.card.Parent do paintFling() task.wait(0.35) end
  end)
  A.interactive(made.Fling.frame, { radius = T.r.sm, spotSize = 70, spotColour = made.Fling.lit, onClick = function()
    if L.Combat.flinging then
      L.Combat.stopFling("stopped from the panel")
      L.Toast.ok("Fling", "Stopped.")
      paintFling()
      return
    end
    L.Combat.cfg.flingMode = "One target"
    local ok, why, kind = L.Combat.startFling(name)
    if ok then L.Toast.ok("Fling", why)
    else
      L.Toast.warn("Fling", tostring(why))
      if kind ~= "user" then L.log("refused", "fling", why) end
    end
    paintFling()
  end })

  -- Hide mutes THIS player in the ESP without turning the whole thing off,
  -- which is what DEV HUD's blacklist is for: one person you do not want
  -- outlined while you keep the rest.
  local function paintHide()
    local on = L.Universal.espHidden[p.UserId] == true
    made.Hide.label.Text = on and "Show" or "Hide"
    M.to(made.Hide.label, "TextColor3", on and T.c.warn or made.Hide.ink, "fast")
  end
  paintHide()
  -- PICK adds them to the Selected set, which the fling engine walks as a group.
  -- Marked on the card itself so a squad you assembled is visible at a glance
  -- rather than living invisibly in a config table.
  local function paintPick()
    local on = L.Combat and L.Combat.selected and L.Combat.selected[name] == true
    made.Pick.label.Text = on and "Set" or "Pick"
    M.to(made.Pick.label, "TextColor3", on and T.c.accent or made.Pick.ink, "fast")
    M.to(st, "Color", on and T.c.accent or T.c.line, "fast")
    M.to(st, "Transparency", on and 0.35 or 0.7, "fast")
  end
  paintPick()
  A.interactive(made.Pick.frame, { radius = T.r.sm, spotSize = 70, spotColour = made.Pick.lit, onClick = function()
    if not (L.Combat and L.Combat.select) then return end
    local on = L.Combat.select(name)
    paintPick()
    local n = #L.Combat.selectedList()
    L.Toast.info(on and "Picked" or "Unpicked",
      n .. (n == 1 and " player selected" or " players selected"))
  end })

  A.interactive(made.Hide.frame, { radius = T.r.sm, spotSize = 70, spotColour = made.Hide.lit, onClick = function()
    local nowHidden = L.Universal.setEspHidden(
      p.UserId, not (L.Universal.espHidden[p.UserId] == true))
    paintHide()
    L.Toast.ok(nowHidden and "Hidden from ESP" or "Shown again",
      (p.DisplayName ~= "" and p.DisplayName or name) ..
      (nowHidden and " will not be outlined." or " is outlined again."))
  end })
  A.interactive(made.Mark.frame, { radius = T.r.sm, spotSize = 70, spotColour = made.Mark.lit, onClick = function()
    Side.state.selected = name
    Side.actTrack()
    -- the tint says it is on; the WORD stays four characters, because at
    -- Compact width a fifth of the card cannot hold "Marked"
    local on = Side.tracking == name
    M.to(made.Mark.label, "TextColor3", on and T.c.accent or made.Mark.ink, "fast")
  end })
  A.interactive(made.Info.frame, { radius = T.r.sm, spotSize = 70, spotColour = made.Info.lit, onClick = function()
    rec.expanded = not rec.expanded
    info.Visible = rec.expanded
    made.Info.label.Text = rec.expanded and "Less" or "Info"
    if rec.expanded and not rec.built then
      rec.built = true
      local mem = "n/a"
      pcall(function()
        mem = (tostring(p.MembershipType):gsub("Enum.MembershipType.", ""))
      end)
      local function line(txt)
        return A.text({ Text = txt, font = T.font.mono, size = T.size.micro,
          colour = T.c.textOff, Size = UDim2.new(1, 0, 0, 14),
          truncate = true, ZIndex = 8, Parent = info })
      end
      line("user id   " .. p.UserId)
      line("account   " .. p.AccountAge .. " days   " .. mem)
      line("team      " .. (p.Team and p.Team.Name or "none"))
      rec.lHealth = line("health    --")
      rec.lSpeed  = line("speed     --")
      rec.lPos    = line("position  --")
    end
  end })

  -- ---- live -----------------------------------------------------------
  task.spawn(function()
    while card.Parent and self.panel and self.panel.Parent do
      local ch = p.Character
      local hum = ch and ch:FindFirstChildOfClass("Humanoid")
      local root = ch and ch:FindFirstChild("HumanoidRootPart")
      local mine = L.LP.Character and L.LP.Character:FindFirstChild("HumanoidRootPart")

      local d = (mine and root) and (mine.Position - root.Position).Magnitude or nil
      rec.distance = d or math.huge
      dist.Text = d and string.format("%d studs", math.floor(d + 0.5)) or "not spawned"
      dist.TextColor3 = d and T.c.textDim or T.c.warn

      local alive = hum and hum.Health > 0
      local presence = (not root) and "missing" or (alive and "alive" or "dead")
      if presence ~= rec.presence then
        rec.presence = presence
        M.to(dot, "BackgroundColor3",
          presence == "missing" and T.c.textOff or (presence == "alive" and T.c.ok or T.c.bad), "fast")
      end

      if hum and hum.MaxHealth > 0 then
        local f = math.clamp(hum.Health / hum.MaxHealth, 0, 1)
        hpTrack.Visible = true
        if not rec.hpFrac or math.abs(rec.hpFrac - f) > 0.002 then
          rec.hpFrac = f
          M.to(hpFill, "Size", UDim2.fromScale(f, 1), "fast")
          M.to(hpFill, "BackgroundTransparency", 0.12 + 0.6 * f, "fast")
        end
        local hpBand = f > 0.6 and "ok" or (f > 0.25 and "warn" or "bad")
        if hpBand ~= rec.hpBand then
          rec.hpBand = hpBand
          M.to(hpFill, "BackgroundColor3",
            hpBand == "ok" and T.c.ok or (hpBand == "warn" and T.c.warn or T.c.bad), "fast")
        end
        -- fades UP as it drops: near-invisible at full health, insistent when
        -- nearly dead, so a healthy list stays calm and a hurt player is the
        -- thing your eye lands on
      else
        hpTrack.Visible = false
        rec.hpFrac, rec.hpBand = nil, nil
      end

      if L.MM2 and game.PlaceId == L.MM2.PLACE and L.MM2.roleOf then
        local role = L.MM2.roleOf(p)
        roleLbl.Text = string.upper(tostring(role))
        roleLbl.TextColor3 = L.MM2.colourFor and L.MM2.colourFor(role) or T.c.textOff
      else
        roleLbl.Text = ""
      end

      if rec.expanded and rec.lHealth then
        rec.lHealth.Text = hum
          and string.format("health    %d / %d", math.floor(hum.Health), math.floor(hum.MaxHealth))
          or "health    --"
        rec.lSpeed.Text = hum and string.format("speed     %.0f", hum.WalkSpeed) or "speed     --"
        rec.lPos.Text = root
          and string.format("position  %d, %d, %d",
                root.Position.X, root.Position.Y, root.Position.Z)
          or "position  --"
      end
      task.wait(0.4)
    end
  end)

  -- NO CURSOR GLOW ON THE CARD ITSELF. A 150 px bloom tracking the pointer
  -- across a list is restless where the same effect on a small button reads as
  -- polish -- and while the cards were oversized it drifted through empty space
  -- looking like a stray light. The pills keep theirs; they are small and the
  -- glow stays inside them.
  A.interactive(card, { radius = T.r.md, hoverAlpha = 0.92, spot = false,
    onClick = function() Side.select(name) end })

  -- STAGGERED ARRIVAL, BUT ONLY WHEN THE PANEL OPENS.
  --
  -- This used to run on every buildRow, and Side.refresh rebuilds every row on
  -- every roster change AND on every search keystroke -- so typing a name
  -- re-staggered the whole list per character. A cascade is an arrival; replayed
  -- while somebody is filtering it is just the list refusing to settle.
  --
  -- The delays are also collected now instead of being fired and forgotten.
  -- A bare M.after cannot be recalled, so a cascade begun by opening the panel
  -- kept fading rows in after it had been closed again.
  if animate then
    local pending = {}
    rec.fadeHandles = pending
    local step = math.min(i, 12) * 0.03
    for _, d in ipairs(card:GetDescendants()) do
      if d:IsA("TextLabel") then
        local rest = d.TextTransparency
        d.TextTransparency = 1
        pending[#pending + 1] = { obj = d, prop = "TextTransparency", rest = rest }
      end
    end
    card.BackgroundTransparency = 1
    pending[#pending + 1] = { obj = card, prop = "BackgroundTransparency", rest = 0.35 }
    rec.fadeAt = step
  end

  return rec
end

-- ---------------------------------------------------------------- selection

function Side.select(name)
  Side.state.selected = name
  for _, rec in ipairs(Side.rows or {}) do
    local on = rec.name == name
    M.to(rec.stroke, "Color", on and T.c.accent or T.c.line, "fast")
    M.to(rec.stroke, "Transparency", on and 0.2 or 0.72, "fast")
  end
end

-- ---------------------------------------------------------------- actions

local function selectedPlayer()
  local n = Side.state.selected
  return n and Players:FindFirstChild(n), n
end

function Side.actTeleport()
  local _, n = selectedPlayer()
  if not n then return L.Toast.info("Nobody picked", "Choose a player first.") end
  local ok, why, kind = L.Universal.teleportTo(n)
  if ok then L.Toast.ok("Teleport", why) L.note("teleport", why)
  else
    L.Toast.warn("Teleport", tostring(why))
    if kind ~= "user" then L.log("refused", "teleport", why) end
  end
end

function Side.actSpectate()
  local p, n = selectedPlayer()
  if not p then return L.Toast.info("Nobody picked", "Choose a player first.") end
  local cam = workspace.CurrentCamera
  local hum = humanoidOf(n)
  if Side.spectating == n then
    local mine = L.LP.Character and L.LP.Character:FindFirstChildOfClass("Humanoid")
    cam.CameraSubject = mine
    Side.spectating = nil
    L.Toast.ok("Spectate off", "Camera back on you.")
    return
  end
  if not hum then return L.Toast.warn("Spectate", n .. " has no character right now.") end
  cam.CameraSubject = hum
  Side.spectating = n
  L.Toast.ok("Spectating", n .. ". Press again to come back.")
end

function Side.actTrack()
  local p, n = selectedPlayer()
  if not p then return L.Toast.info("Nobody picked", "Choose a player first.") end
  if Side.mark then pcall(function() Side.mark:Destroy() end) Side.mark = nil end
  if Side.tracking == n then
    Side.tracking = nil
    L.Toast.ok("Marker off", "No longer marking " .. n .. ".")
    return
  end
  local _, ch = humanoidOf(n)
  if not ch then return L.Toast.warn("Marker", n .. " has no character right now.") end
  local hl = Instance.new("Highlight")
  hl.Name = "LumenMark"
  hl.FillColor = T.c.accent
  hl.FillTransparency = 0.62
  hl.OutlineColor = Color3.new(1, 1, 1)
  hl.Adornee = ch
  hl.Parent = ch
  Side.mark = hl
  L.own(hl)
  Side.tracking = n
  L.Toast.ok("Marked", n .. " is highlighted through walls.")
end

function Side.actCopy()
  local p, n = selectedPlayer()
  if not p then return L.Toast.info("Nobody picked", "Choose a player first.") end
  local url = "https://www.roblox.com/users/" .. p.UserId .. "/profile"
  local ok = pcall(function() setclipboard(url) end)
  if ok then L.Toast.ok("Copied", url) else L.Toast.info(n, url) end
end

-- ---------------------------------------------------------------- list

-- REBUILDING FOURTEEN CARDS BECAUSE ONE PLAYER LEFT.
--
-- This destroyed every row and built the list again from nothing, on every
-- PlayerAdded and every PlayerRemoving. In a 22-slot public server somebody
-- joins or leaves every few seconds, so the panel was tearing itself down and
-- reassembling -- with the arrival cascade replaying each time -- while you were
-- trying to read it or click something in it. That is the "it refreshes a lot"
-- complaint, and it is also a click you lose if you happen to press during one.
--
-- The roster is a SET, and set changes are almost always one element. So the
-- common path is now a diff: departed rows are destroyed, arrivals are built,
-- and everyone still here keeps the card they already had -- reordered by
-- LayoutOrder, which costs one integer per row.
--
-- A full rebuild is still available and still correct, and is what an explicit
-- refresh, an opening panel, a sort change and a search keystroke all take:
-- those are moments where the whole list genuinely changes meaning, and where
-- the cascade is the point rather than an interruption.
function Side.refresh(animate)
  if not Side.list then return 0 end

  local q = string.lower(Side.state.query or "")
  local names = {}
  for _, p in ipairs(Players:GetPlayers()) do
    if p ~= L.LP then
      local hay = string.lower(p.Name .. " " .. (p.DisplayName or ""))
      if q == "" or hay:find(q, 1, true) then names[#names + 1] = p.Name end
    end
  end

  if Side.state.sort == "distance" then
    local d = {}
    for _, n in ipairs(names) do d[n] = distanceTo(n) or math.huge end
    table.sort(names, function(a, b)
      if d[a] == d[b] then return a:lower() < b:lower() end
      return d[a] < d[b]
    end)
  else
    table.sort(names, function(a, b) return a:lower() < b:lower() end)
  end

  -- ---- the quiet path: keep what is still here -------------------------
  if not animate then
    local want = {}
    for i, n in ipairs(names) do want[n] = i end
    local have, ok = {}, true
    for _, rec in ipairs(Side.rows or {}) do
      if rec and rec.card and rec.card.Parent then have[rec.name] = rec else ok = false end
    end
    if ok then
      for nm, rec in pairs(have) do
        if not want[nm] then
          pcall(function() rec.card:Destroy() end)
          have[nm] = nil
        end
      end
      local out = {}
      for i, n in ipairs(names) do
        local rec = have[n]
        if not rec then rec = buildRow(Side, n, i, false) end
        if rec then
          if rec.card then rec.card.LayoutOrder = i end
          out[#out + 1] = rec
        end
      end
      Side.rows = out
      if Side.countLbl then
        local total = #Players:GetPlayers() - 1
        Side.countLbl.Text = (q ~= "" and (#names .. " of " .. total) or (total .. " here"))
      end
      if Side.emptyLbl then Side.emptyLbl.Visible = #names == 0 end
      if Side.state.selected then Side.select(Side.state.selected) end
      return #names
    end
  end

  -- ---- the full rebuild -------------------------------------------------
  for _, c in ipairs(Side.list:GetChildren()) do
    if c:IsA("GuiObject") then c:Destroy() end
  end
  Side.rows = {}

  -- a cascade still in flight belongs to a list that no longer exists
  if Side._seq then Side._seq:cancel() Side._seq = nil end

  local built = {}
  for i, n in ipairs(names) do
    local rec = buildRow(Side, n, i, animate)
    Side.rows[#Side.rows + 1] = rec
    if animate and rec and rec.fadeHandles then built[#built + 1] = rec end
  end

  if animate and #built > 0 then
    Side._seq = M.seq(built, function(rec)
      for _, e in ipairs(rec.fadeHandles) do
        if e.obj.Parent then M.to(e.obj, e.prop, e.rest, "base") end
      end
    end, { step = 0.03, cap = 0.34 })
  end

  if Side.countLbl then
    local total = #Players:GetPlayers() - 1
    Side.countLbl.Text = (q ~= "" and (#names .. " of " .. total) or (total .. " here"))
  end
  if Side.emptyLbl then
    Side.emptyLbl.Visible = #names == 0
  end
  if Side.state.selected then Side.select(Side.state.selected) end
  return #names
end

-- ---------------------------------------------------------------- lifecycle

function Side.setSort(mode)
  if mode ~= "distance" and mode ~= "name" then return false end
  Side.state.sort = mode
  if L.Cfg then L.Cfg.set("sideSort", mode) end
  if Side.sortLbl then Side.sortLbl.Text = Side.SORT_LABEL[mode] end
  if Side.sortBtn then A.explain(Side.sortBtn, Side.SORT_HINT[mode]) end
  -- a reorder is a different list even though it is the same people
  if Side.open then Side.refresh(true) end
  return true
end

function Side.cycleSort()
  return Side.setSort(Side.state.sort == "distance" and "name" or "distance")
end

function Side.setSize(i)
  Side.state.size = math.clamp(i, 1, #Side.SIZES)
  if L.Cfg then L.Cfg.set("sideSize", Side.state.size) end
  if Side.open and Side.panel then
    local def = sizeDef()
    if Side.content then Side.content.Size = UDim2.fromOffset(def.w, def.h) end
    if Side.detached and Side.holder then
      local sc = (Side.freeScale and Side.freeScale.Scale) or 1
      local centre = Side.holder.AbsolutePosition + Side.holder.AbsoluteSize / 2
      local oldOffset = Vector2.new(
        Side.holder.Position.X.Offset, Side.holder.Position.Y.Offset)
      local origin = Side.holder.AbsolutePosition - oldOffset
      -- UIScale applies to the holder itself as well as its descendants.  Keep
      -- the authored size here; multiplying by `sc` a second time made the
      -- detached rect grow by scale^2 and defeated the viewport clamp.
      Side.holder.Size = UDim2.fromOffset(def.w, def.h)
      Side.panel.Size = UDim2.fromOffset(def.w, def.h)
      if Side.grip then Side.grip.Size = UDim2.fromOffset(def.w, 30) end
      local vp, sz = L.viewport(), Vector2.new(def.w * sc, def.h * sc)
      local absX = math.clamp(centre.X - sz.X / 2, 8, math.max(8, vp.X - sz.X - 8))
      local absY = math.clamp(centre.Y - sz.Y / 2, 8, math.max(8, vp.Y - sz.Y - 8))
      -- The free ScreenGui can have a non-zero absolute origin even with
      -- IgnoreGuiInset (CoreGui.RobloxGui is -58 px on the measured client).
      -- Clamp in screen pixels, then convert back to the holder's offset space.
      Side.holder.Position = UDim2.fromOffset(absX - origin.X, absY - origin.Y)
      Side.detachedPosition = Vector2.new(absX, absY)
    else
      M.to(Side.panel, "Size", UDim2.fromOffset(def.w, def.h), "base")
    end
    Side.refresh()
  end
end

function Side.show()
  local win = L.Hub and L.Hub.window
  if not win then return false, "the hub is not up" end

  -- OPENABLE WITH THE WINDOW DOWN. The panel is a child of the shell, so
  -- opening it while minimised used to build it inside something that is not on
  -- screen -- it reported success and showed nothing. That matters because the
  -- pinned "Open player panel" chip lives ON the minimised dock, so the one
  -- place you would most want it was the one place it did not work.
  --
  -- The detached mode already exists for exactly this shape (its own ScreenGui,
  -- draggable, independent of the window), so a minimised open simply builds and
  -- immediately detaches, and the panel floats on its own until you put it away.
  local wasDown = win.hidden == true
  if wasDown then Side._openedDetached = true end
  -- show() SHOWS. It used to close an already-open panel, which made it a toggle
  -- wearing the wrong name.
  if Side.open then return true end
  Side.transitionGen = (Side.transitionGen or 0) + 1
  local transitionGen = Side.transitionGen
  Side.open = true
  local self = Side

  if L.Cfg and tonumber(L.Cfg.data.sideSize) then
    Side.state.size = math.clamp(math.floor(L.Cfg.data.sideSize), 1, #Side.SIZES)
  end
  -- Sort is a preference, so it comes back. The SEARCH BOX DELIBERATELY DOES
  -- NOT: reopening the panel onto a filtered list, with no memory of having
  -- typed it, reads as half the server having left.
  local savedSort = L.Cfg and L.Cfg.data.sideSort
  if savedSort == "distance" or savedSort == "name" then
    Side.state.sort = savedSort
  end
  Side.state.query = ""

  local def = sizeDef()
  local shell = win.shell
  local sc = (win.scaleObj and win.scaleObj.Scale) or 1

  -- IT IS A CHILD OF THE SHELL, NOT A SCREEN-SPACE SATELLITE.
  --
  -- The previous version lived in its own ScreenGui and recomputed its screen
  -- rect every frame to stay beside a window that moves. That bought two bugs
  -- (a full-screen shadow, and a dimmed panel once it was ordered under the
  -- window's own scrim) to solve a problem the scene graph already solves:
  -- parented to the shell it simply MOVES WITH IT, for free, and it inherits the
  -- window's UIScale so everything below is authored in the same pre-scale units
  -- as the rest of the hub.
  --
  -- ZIndex 4 puts it above the window's drop shadow (3) and below the window
  -- body (5), so it is genuinely behind the window while still sitting above the
  -- backdrop scrim that was washing it out.
  local shellW = shell.AbsoluteSize.X / sc
  local roomRight = (L.viewport().X
    - (shell.AbsolutePosition.X + shell.AbsoluteSize.X)) / sc
  local flipped = roomRight < (def.w - TUCK + 12)
  self.flipped = flipped

  local panel = mk("Frame", {
    -- anchored on the tucked edge, so width alone drives the slide
    AnchorPoint = Vector2.new(flipped and 1 or 0, 0.5),
    Position = UDim2.new(0, flipped and TUCK or (shellW - TUCK), 0.5, 0),
    Size = UDim2.fromOffset(0, def.h),
    BackgroundColor3 = T.c.surface, BackgroundTransparency = 0.02,
    BorderSizePixel = 0, ClipsDescendants = true,
    ZIndex = 4, Name = "SidePanel", Parent = shell,
  })
  L.corner(T.r.lg, panel)
  -- kept, because the entrance fades it in with the panel rather than letting a
  -- hard 1px outline snap into existence around a slab that is still growing
  local panelStroke = L.stroke(T.c.lineStrong, 1, 0.32, panel)
  self.panel = panel
  self.panelStroke = panelStroke

  -- pinned to the same edge the panel is anchored on, so the drawer uncovers the
  -- content instead of dragging it along. No UIScale of its own: it inherits the
  -- window's, which is the whole point of living in the shell.
  local content = mk("Frame", {
    AnchorPoint = Vector2.new(flipped and 1 or 0, 0),
    Position = flipped and UDim2.fromScale(1, 0) or UDim2.fromScale(0, 0),
    Size = UDim2.fromOffset(def.w, def.h), BackgroundTransparency = 1,
    ZIndex = 4, Name = "Content", Parent = panel,
  })
  -- KEEP THE CONTENT OUT OF THE TUCKED STRIP. The inner 26 px of the panel sit
  -- underneath the window on purpose, and anything drawn there is invisible --
  -- which quietly ate the right-hand end of every distance label ("162 stud").
  -- Padding the tucked side moves the whole column clear of the overlap.
  L.pad(0, flipped and TUCK or 0, 0, (not flipped) and TUCK or 0, content)
  self.content = content

  -- NO PLAYING BACKGROUND. The dichroic sequence that used to sit here was a
  -- lovely thing to look at and a bad thing to read a list of names on top of --
  -- moving contrast behind static text is the one place motion actively costs
  -- you. The panel gets its depth from a still gradient and its life from the
  -- rows themselves.
  local wash = mk("Frame", {
    Size = UDim2.fromScale(1, 1), BackgroundColor3 = T.c.raised,
    BackgroundTransparency = 0.72, BorderSizePixel = 0,
    ZIndex = 3, Name = "Wash", Parent = panel,
  })
  L.corner(T.r.lg, wash)
  mk("UIGradient", {
    Rotation = 90,
    Color = ColorSequence.new(T.c.accentDeep, T.c.surface),
    Transparency = NumberSequence.new({
      NumberSequenceKeypoint.new(0.00, 0.72),
      NumberSequenceKeypoint.new(1.00, 1.00),
    }),
    Parent = wash,
  })

  -- ---- header ---------------------------------------------------------
  A.text({
    Text = "PLAYERS", font = T.font.mono, size = T.size.micro, colour = T.c.textOff,
    -- 64, not 90: seven tracked characters need about fifty, and the extra forty
    -- reached far enough right to overlap the count's box at Compact width. The
    -- glyphs never collided, which is exactly why it survived being looked at.
    Position = UDim2.fromOffset(PAD + 2, 12), Size = UDim2.fromOffset(64, 12),
    ZIndex = 6, Parent = content,
  })
  -- the count has to end clear of the two header buttons, or it is drawn
  -- underneath them -- they sit on the same baseline at the same right edge
  self.countLbl = A.text({
    Text = "", font = T.font.mono, size = T.size.micro, colour = T.c.accent,
    align = Enum.TextXAlignment.Right, AnchorPoint = Vector2.new(1, 0),
    -- clears the whole button group: five slots plus a gutter
    Position = UDim2.new(1, -(PAD + SLOT * 5 + 6), 0, 12), Size = UDim2.fromOffset(110, 12),
    ZIndex = 6, Parent = content,
  })

  -- search
  local search = mk("TextBox", {
    Position = UDim2.fromOffset(PAD, 32), Size = UDim2.new(1, -(PAD * 2), 0, 26),
    BackgroundColor3 = T.c.overlay, BackgroundTransparency = 0.15, BorderSizePixel = 0,
    Text = "", PlaceholderText = "Search", PlaceholderColor3 = T.c.textOff,
    TextColor3 = T.c.text, Font = T.font.body, TextSize = T.size.label,
    TextXAlignment = Enum.TextXAlignment.Left, ClearTextOnFocus = false,
    ZIndex = 6, Parent = content,
  })
  L.corner(T.r.sm, search)
  L.pad(0, 8, 0, 8, search)
  L.stroke(T.c.lineStrong, 1, 0.5, search)
  search:GetPropertyChangedSignal("Text"):Connect(function()
    Side.state.query = search.Text
    Side.refresh()
  end)

  -- NO SORT CONTROL. It was a two-state toggle between "nearest" and "A to Z"
  -- that had to be discovered, remembered and re-set, to reorder a list short
  -- enough to read at a glance. Nearest-first is what you want essentially
  -- always -- the person about to matter is the person next to you -- so it is
  -- simply always that, and the space goes to the search box instead.

  -- CLOSE LIVES ON THE PANEL. Until now the only way to put it away was to
  -- open the window and toggle it back off, which is backwards when the panel
  -- is detached and the window is minimised -- you had to restore the thing
  -- you minimised in order to dismiss the thing you kept.
  local closeBtn = mk("Frame", {
    AnchorPoint = Vector2.new(1, 0),
    Position = UDim2.new(1, -PAD, 0, 8), Size = UDim2.fromOffset(22, 20),
    BackgroundColor3 = T.c.raised, BackgroundTransparency = 0.35,
    BorderSizePixel = 0, ZIndex = 8, Parent = content,
  })
  L.corner(T.r.sm, closeBtn)
  local closeIcon = A.Icon.close(closeBtn, 10, T.c.textDim)
  closeIcon.AnchorPoint = Vector2.new(0.5, 0.5)
  closeIcon.Position = UDim2.fromScale(0.5, 0.5)
  closeIcon.ZIndex = 9
  A.explain(closeBtn, "Close the player panel")
  local closeIx = A.interactive(closeBtn, { radius = T.r.sm, spotSize = 50,
    onClick = function() Side.hide() end })
  -- close is the one control here that destroys what you are looking at, so it
  -- warns in the colour everything else in the framework uses for destructive
  local function paintClose(c)
    for _, b in ipairs(closeIcon:GetChildren()) do
      if b:IsA("Frame") then M.to(b, "BackgroundColor3", c, "fast") end
    end
  end
  closeIx.button.MouseEnter:Connect(function() paintClose(T.c.bad) end)
  closeIx.button.MouseLeave:Connect(function() paintClose(T.c.textDim) end)

  -- SORT HAD NO CONTROL AT ALL. Side.state.sort was read once in refresh and
  -- written nowhere, so it was a dead setting permanently stuck on "distance".
  -- Two orders is one button, not a dropdown: the label IS the current state.
  local sortBtn = mk("Frame", {
    AnchorPoint = Vector2.new(1, 0),
    Position = UDim2.new(1, -(PAD + SLOT * 2), 0, 8), Size = UDim2.fromOffset(22, 20),
    BackgroundColor3 = T.c.raised, BackgroundTransparency = 0.35,
    BorderSizePixel = 0, ZIndex = 8, Parent = content,
  })
  L.corner(T.r.sm, sortBtn)
  local sortLbl = A.text({
    Text = Side.SORT_LABEL[Side.state.sort] or "D",
    font = T.font.mono, size = T.size.micro, colour = T.c.textDim,
    align = Enum.TextXAlignment.Center, Size = UDim2.fromScale(1, 1),
    ZIndex = 9, Parent = sortBtn,
  })
  Side.sortBtn, Side.sortLbl = sortBtn, sortLbl
  A.explain(sortBtn, Side.SORT_HINT[Side.state.sort] or Side.SORT_HINT.distance)
  A.interactive(sortBtn, { radius = T.r.sm, spotSize = 50, onClick = function()
    Side.cycleSort()
    M.to(sortLbl, "TextColor3", T.c.accent, "fast")
    M.after(0.4, function()
      if sortLbl.Parent then M.to(sortLbl, "TextColor3", T.c.textDim, "base") end
    end)
  end })

  local refreshBtn = mk("Frame", {
    AnchorPoint = Vector2.new(1, 0),
    Position = UDim2.new(1, -(PAD + SLOT), 0, 8), Size = UDim2.fromOffset(22, 20),
    BackgroundColor3 = T.c.raised, BackgroundTransparency = 0.35,
    BorderSizePixel = 0, ZIndex = 8, Parent = content,
  })
  L.corner(T.r.sm, refreshBtn)
  local refreshLbl = A.text({
    Text = "R", font = T.font.mono, size = T.size.micro, colour = T.c.textDim,
    align = Enum.TextXAlignment.Center, Size = UDim2.fromScale(1, 1),
    ZIndex = 9, Parent = refreshBtn,
  })
  A.explain(refreshBtn, "Rebuild the list now -- it also refreshes itself as people join and leave")
  A.interactive(refreshBtn, { radius = T.r.sm, spotSize = 50, onClick = function()
    -- an explicit rebuild is a deliberate act, so it earns the cascade too
    local n = Side.refresh(true)
    M.to(refreshLbl, "TextColor3", T.c.accent, "fast")
    M.after(0.4, function()
      if refreshLbl.Parent then M.to(refreshLbl, "TextColor3", T.c.textDim, "base") end
    end)
    L.Toast.ok("Refreshed", (n or 0) .. " other players here.")
  end })

  -- ---- view bar --------------------------------------------------------
  -- DEV HUD keeps a "stop viewing" control at the top of its player list, and
  -- it is right to: once the camera is on someone else, getting it back is the
  -- one thing you urgently need and the card that did it may be scrolled away.
  -- Shown always, like DEV HUD's, but it says which state it is in rather than
  -- sitting there as a dead button when nobody is being watched.
  local viewBar = mk("Frame", {
    Position = UDim2.fromOffset(PAD, 66), Size = UDim2.new(1, -PAD * 2, 0, 26),
    BackgroundColor3 = T.c.raised, BackgroundTransparency = 0.45,
    BorderSizePixel = 0, ZIndex = 6, Parent = content,
  })
  L.corner(T.r.sm, viewBar)
  L.stroke(T.c.line, 1, 0.6, viewBar)
  local viewLbl = A.text({
    Text = "Not viewing anyone", font = T.font.body, size = T.size.micro,
    colour = T.c.textOff, align = Enum.TextXAlignment.Center,
    Size = UDim2.fromScale(1, 1), ZIndex = 7, Parent = viewBar,
  })
  self.viewLbl = viewLbl
  A.interactive(viewBar, { radius = T.r.sm, spotSize = 90, onClick = function()
    if not Side.spectating then
      L.Toast.info("Not viewing", "Press View on a card to watch someone.")
      return
    end
    Side.state.selected = Side.spectating
    Side.actSpectate()
    Side.refreshView()
  end })

  function Side.refreshView()
    if not Side.viewLbl then return end
    local who = Side.spectating
    Side.viewLbl.Text = who and ("Stop viewing  " .. who) or "Not viewing anyone"
    M.to(Side.viewLbl, "TextColor3", who and T.c.accent or T.c.textOff, "fast")
  end
  Side.refreshView()

  -- ---- list -----------------------------------------------------------
  -- Full height below the view bar: the shared action footer that used to live
  -- at the bottom is gone, because each card carries its own buttons. That space
  -- is worth more as two extra players than as a bar telling you nobody is
  -- selected.
  self.list = A.scroll({
    Parent = content, gap = 6,
    Position = UDim2.fromOffset(PAD, 100),
    Size = UDim2.new(1, -PAD * 2, 1, -(100 + PAD)),
    Name = "SideList",
  })
  self.list.ZIndex = 5

  self.emptyLbl = A.text({
    Text = "Nobody matches that.", font = T.font.body, size = T.size.label,
    colour = T.c.textOff, align = Enum.TextXAlignment.Center,
    Position = UDim2.fromOffset(PAD, 120), Size = UDim2.new(1, -PAD * 2, 0, 20),
    Visible = false, ZIndex = 6, Parent = content,
  })

  -- ---- size + close ---------------------------------------------------
  local function chip(xOff, label, fn)
    local b = mk("Frame", {
      AnchorPoint = Vector2.new(1, 0),
      Position = UDim2.new(1, xOff, 0, 8), Size = UDim2.fromOffset(20, 20),
      BackgroundColor3 = T.c.raised, BackgroundTransparency = 0.35,
      BorderSizePixel = 0, ZIndex = 8, Parent = content,
    })
    L.corner(T.r.sm, b)
    local t = A.text({ Text = label, font = T.font.mono, size = T.size.micro,
      colour = T.c.textDim, align = Enum.TextXAlignment.Center,
      Size = UDim2.fromScale(1, 1), ZIndex = 9, Parent = b })
    A.interactive(b, { radius = T.r.sm, spotSize = 50, onClick = fn })
    return b, t
  end
  -- FIVE BUTTONS, FOUR SLOTS, AND TWO OF THEM ON THE SAME COORDINATE.
  --
  -- This comment used to say "the four header buttons" and the offsets were
  -- hand-written to match. Sort was added afterwards and given -(PAD + 52) --
  -- which is exactly where "+" already was:
  --
  --   close    PAD +   0   ->   0 .. 22
  --   refresh  PAD +  26   ->  26 .. 48
  --   sort     PAD +  52   ->  52 .. 74   <-+ the same slot, drawn on
  --   "+"      PAD +  52   ->  52 .. 72   <-+ top of each other
  --   "-"      PAD +  76   ->  76 .. 96
  --
  -- On screen that is an "A" and a "+" superimposed in one chip, which is what
  -- the recording caught. Derived from SLOT now rather than typed per button,
  -- so the next one added cannot land on top of an existing one.
  chip(-PAD - SLOT * 3, "+", function()
    if Side.state.size >= #Side.SIZES then
      L.Toast.info("Largest", "Already at " .. sizeDef().name .. ".")
      return
    end
    Side.setSize(Side.state.size + 1)
  end)
  chip(-PAD - SLOT * 4, "-", function()
    if Side.state.size <= 1 then
      L.Toast.info("Smallest", "Already at " .. sizeDef().name .. ".")
      return
    end
    Side.setSize(Side.state.size - 1)
  end)

  -- the panel opening IS the arrival, so this build is the one that cascades
  Side.refresh(true)
  watchRoster()

  if Side._openedDetached then
    Side._openedDetached = nil
    -- one frame so the panel has a real rect to be detached FROM, otherwise the
    -- free copy is positioned from an unresolved zero
    task.defer(function()
      if Side.transitionGen == transitionGen and Side.open and not Side.detached then
        L.try("side.autoDetach", function() Side.detach(true) end)
      end
    end)
  end

  -- ---- entrance -------------------------------------------------------
  -- ONE TWEEN, NO PER-FRAME FOLLOW. Being a child of the shell means there is
  -- nothing to keep in sync: it slides out sideways from the edge it is tucked
  -- under, and the content is full size the whole time so nothing reflows while
  -- it opens.
  --
  -- WHAT WAS MISSING WAS EVERYTHING EXCEPT THE WIDTH.
  --
  -- The old entrance was a single `Size` tween on "base": a solid slab, at full
  -- opacity from frame one, growing sideways. That is a wipe, and a wipe is the
  -- cheapest-looking reveal there is -- the panel does not arrive, it is
  -- uncovered, and because the fill and the outline are already at rest the
  -- first frame is a hard-edged bar appearing out of nothing.
  --
  -- Three things fix it, and none of them touch the layout:
  --
  --   * the fill and the outline fade UP as the width grows, so the panel
  --     resolves rather than being unmasked;
  --   * it settles a few pixels vertically, which is what stops a purely
  --     horizontal motion reading as mechanical;
  --   * a token with real bounce, so it arrives with weight instead of
  --     decelerating into place.
  --
  -- The width still leads, because the drawer metaphor is correct -- this makes
  -- it feel like a drawer rather than a rectangle being revealed.
  local restY = panel.Position.Y
  M.set(panel, "BackgroundTransparency", 1)
  if panelStroke then M.set(panelStroke, "Transparency", 1) end
  M.set(panel, "Position", UDim2.new(
    panel.Position.X.Scale, panel.Position.X.Offset,
    restY.Scale, restY.Offset + 10))

  -- 0.34 with 0.30 bounce: fractionally longer than "base" and noticeably more
  -- alive. Bounce is what carries the character; the extra 40ms is what stops
  -- that bounce reading as a wobble.
  local OPEN = { 0.34, 0.30 }
  M.to(panel, "Size", UDim2.fromOffset(def.w, def.h), OPEN)
  M.to(panel, "Position", UDim2.new(
    panel.Position.X.Scale, panel.Position.X.Offset, restY.Scale, restY.Offset), OPEN)
  -- The fill lands ahead of the geometry, so the panel reads as solid while it
  -- is still settling rather than fading in after it has stopped moving.
  --
  -- "gentle" (overdamped) rather than "base", because BOUNCE ON A TRANSPARENCY
  -- IS MEANINGLESS. Measured on the first version: the fill overshot to -0.02,
  -- which is "more opaque than opaque" -- Roblox clamps it so nothing looks
  -- wrong, but it is a spring spending frames travelling past a hard boundary,
  -- and anything reading the property back gets a value outside its own range.
  -- Geometry is what should bounce; opacity should arrive and stop.
  M.to(panel, "BackgroundTransparency", 0.02, "gentle")
  if panelStroke then M.to(panelStroke, "Transparency", 0.32, "gentle") end

  L.note("side", "player panel opened (" .. def.name .. ")")
  return true
end


-- `instant` skips the retract animation.
--
-- The panel is a child of the shell, so when the window minimises it is dragged
-- through the morph -- squashed and carried along with a shell that is folding
-- into a pill. Sliding out gracefully while that happens looks like a bug, so
-- the window tells it to just go.
local function stopDetachedDragLoops()
  for _, key in ipairs({ "_freeInputEnded", "_freeRenderStep" }) do
    local conn = Side[key]
    Side[key] = nil
    if conn then pcall(function() conn:Disconnect() end) end
  end
end

function Side.hide(instant)
  if not Side.open then return end
  Side.transitionGen = (Side.transitionGen or 0) + 1
  Side.open = false
  local panel = Side.panel
  local panelStroke = Side.panelStroke

  -- A DETACHED PANEL OWNS A SCREENGUI OF ITS OWN. Destroying just the panel
  -- leaves that behind as an empty layer and leaves `detached` set, so the next
  -- detach thought it had already happened and the next reattach had nothing to
  -- put back. Closing from the panel's own button is the common way in, so this
  -- is the common path, not the corner case.
  local freeGui = Side.freeGui
  if Side.detached then
    stopDetachedDragLoops()
    if Side.holder then
      -- Remember screen-space pixels. ScreenGui offsets include its parent
      -- origin and cannot safely be replayed as absolute positions.
      Side.detachedPosition = Side.holder.AbsolutePosition
    end
    Side.freeGui, Side.holder, Side.detached, Side.freeScale, Side.grip = nil, nil, false, nil, nil
    Side.panel, Side.list, Side.content, Side.rows = nil, nil, nil, nil
    Side.panelStroke = nil
    if freeGui then
      if instant then
        pcall(function() freeGui:Destroy() end)
      else
        local holder = panel and panel.Parent
        if holder then M.to(holder, "BackgroundTransparency", 1, "fast") end
        -- fades as it retracts, matching the entrance -- a panel that collapses
        -- at full opacity reads as being cut off rather than closing
        M.to(panel, "BackgroundTransparency", 1, "fast")
        if panelStroke then M.to(panelStroke, "Transparency", 1, "fast") end
        M.to(panel, "Size", UDim2.fromOffset(0, panel.Size.Y.Offset), "fast")
        task.delay(select(1, M.resolve("fast")) + 0.30, function()
          pcall(function() freeGui:Destroy() end)
        end)
      end
    end
    L.note("side", "player panel closed while detached")
    return
  end

  if instant then
    Side.panel, Side.list, Side.content, Side.rows = nil, nil, nil, nil
    Side.panelStroke = nil
    if panel then pcall(function() panel:Destroy() end) end
    L.note("side", "player panel closed with the window")
    return
  end
  -- retracts the way it came out, back under the window, and only then is
  -- destroyed -- tearing it down first would make it vanish rather than close
  if panel then
    local h = panel.Size.Y.Offset
    M.to(panel, "BackgroundTransparency", 1, "fast")
    if panelStroke then M.to(panelStroke, "Transparency", 1, "fast") end
    M.to(panel, "Size", UDim2.fromOffset(0, h), "fast")
    task.delay(select(1, M.resolve("fast")) + 0.30, function()
      pcall(function() panel:Destroy() end)
    end)
  end
  Side.panel, Side.list, Side.content, Side.rows = nil, nil, nil, nil
  Side.panelStroke = nil
  L.note("side", "player panel closed")
end

-- The list is a snapshot, so somebody joining or leaving leaves it wrong until
-- you touch it. Debounced: a wave of joins should rebuild once, not eight times.
local rosterConns = {}
local rosterQueued = false

watchRoster = function()
  for _, c in ipairs(rosterConns) do pcall(function() c:Disconnect() end) end
  rosterConns = {}
  local function bump()
    if not Side.open or rosterQueued then return end
    rosterQueued = true
    task.delay(0.6, function()
      rosterQueued = false
      if Side.open then L.try("side.autorefresh", Side.refresh) end
    end)
  end
  rosterConns[#rosterConns + 1] = L.hold(Players.PlayerAdded:Connect(bump))
  rosterConns[#rosterConns + 1] = L.hold(Players.PlayerRemoving:Connect(bump))
end

-- ---------------------------------------------------------------- detach
--
-- Minimising used to close the panel. It is parented to the shell, so it was
-- either dragged through the morph or thrown away -- and neither is what you
-- want when the panel is the thing you were using.
--
-- Instead it is handed its own ScreenGui at the same screen position, becomes
-- draggable on its own, and is put back into the shell when the window returns.
function Side.detach(centred)
  if not (Side.open and Side.panel) then return false end
  if Side.detached then return true end
  -- A prior free window should have retired these on reattach/hide. Be
  -- defensive so repeated minimise/restore cycles never collect idle globals.
  stopDetachedDragLoops()
  local panel = Side.panel
  local transitionGen = Side.transitionGen

  local gui = mk("ScreenGui", {
    Name = "LumenSideFree", ResetOnSpawn = false, IgnoreGuiInset = true,
    ZIndexBehavior = Enum.ZIndexBehavior.Sibling, DisplayOrder = 11,
  })
  gui.Parent = L.host()
  L.own(gui)

  -- measured, not assumed: the new parent's origin is its own
  local probe = mk("Frame", { Size = UDim2.fromOffset(1, 1),
    Position = UDim2.fromOffset(0, 0), BackgroundTransparency = 1, Parent = gui })
  L.RunService.Heartbeat:Wait()
  if not L.live() or not gui.Parent or not Side.open
     or Side.transitionGen ~= transitionGen or Side.panel ~= panel or not panel.Parent then
    pcall(function() gui:Destroy() end)
    return false
  end
  local ox, oy = probe.AbsolutePosition.X, probe.AbsolutePosition.Y
  probe:Destroy()

  local ax, ay = panel.AbsolutePosition.X, panel.AbsolutePosition.Y

  -- THE UISCALE HAS TO COME WITH IT.
  --
  -- Everything inside the panel is authored in pre-scale units because the shell
  -- carries a UIScale. Reparenting to a bare ScreenGui leaves that behind, so the
  -- content renders at 1x inside a panel still sized for 1.6 -- and fitCard,
  -- which divides body heights by the window scale, then made every card 60 px
  -- tall around 96 px of content. That is the overlap: names sitting on the pill
  -- row of the card above.
  --
  -- The holder keeps the authored rect and owns a matching UIScale, so its
  -- screen-space size and the subtree below it grow by exactly one scale term.
  local sc = (L.Hub.window and L.Hub.window.scaleObj and L.Hub.window.scaleObj.Scale) or 1
  local def = sizeDef()
  local fullW, fullH = def.w * sc, def.h * sc
  local vp = L.viewport()
  local absX, absY = ax, ay
  if centred then
    local saved = Side.detachedPosition
    absX = saved and saved.X or math.floor((vp.X - fullW) / 2)
    absY = saved and saved.Y or math.floor((vp.Y - fullH) / 2)
  end
  local function clampAbsolute(x, y)
    local currentVp = L.viewport()
    local currentDef = sizeDef()
    local currentScale = (Side.freeScale and Side.freeScale.Scale) or sc
    local w, h = currentDef.w * currentScale, currentDef.h * currentScale
    return math.clamp(x, 8, math.max(8, currentVp.X - w - 8)),
           math.clamp(y, 8, math.max(8, currentVp.Y - h - 8))
  end
  absX, absY = clampAbsolute(absX, absY)
  local px, py = absX - ox, absY - oy

  local holder = mk("Frame", {
    Position = UDim2.fromOffset(px, py),
    -- `freeScale` scales this holder too.  `fullW` / `fullH` are used only for
    -- screen-space positioning and clamping; storing them as the authored size
    -- here would apply the scale twice.
    Size = UDim2.fromOffset(def.w, def.h),
    BackgroundTransparency = 1, Name = "Free", Parent = gui,
  })
  Side.freeScale = mk("UIScale", { Scale = sc, Parent = holder })
  Side.detachedPosition = Vector2.new(absX, absY)

  -- Reparenting changes the coordinate space. Retire any in-flight drawer
  -- geometry springs before assigning free-window coordinates, otherwise the
  -- old shell-relative target resumes one frame later and drags the panel away.
  M.stop(panel, "Position")
  M.stop(panel, "Size")
  panel.AnchorPoint = Vector2.new(0, 0)
  panel.Position = UDim2.fromOffset(0, 0)
  panel.Size = UDim2.fromOffset(def.w, def.h)   -- pre-scale, like it was in the shell
  panel.Parent = holder

  Side.freeGui, Side.holder, Side.detached = gui, holder, true

  -- drag by the header strip, the same delta arithmetic the window uses so the
  -- UIScale term cancels instead of multiplying the movement
  local grip = mk("TextButton", {
    Size = UDim2.fromOffset(def.w, 30),
    BackgroundTransparency = 1, Text = "", AutoButtonColor = false,
    -- BELOW THE PANEL, NOT BETWEEN THE PANEL AND ITS CONTROLS.
    --
    -- This was 20, which swallowed Close/Refresh/+/- whenever detached, and was
    -- then lowered to 5 to sit "below the interactive controls (8/9), above the
    -- passive panel (4)". That reasoning does not hold under Sibling ZIndex
    -- behaviour and the bug survived the fix: the grip and the panel are
    -- SIBLINGS under this holder, so 5 against 4 ranks the grip above the
    -- panel's ENTIRE subtree. A close button at ZIndex 13 is only ever compared
    -- with its own siblings inside the panel; it never gets compared with the
    -- grip at all. Hit-tested at the close button's centre while detached, top
    -- of stack down:
    --
    --   1) promptOverlay      (inert)
    --   2) Grip     z=5       ACTIVE  <- takes the click
    --   3) Hit      z=13      ACTIVE  <- the close button, unreachable
    --
    -- So the panel could not be closed from its own button in exactly the state
    -- the button exists for: floating, with the window minimised.
    --
    -- Ranking it BELOW the panel fixes every header control at once rather than
    -- one rect at a time. Dragging still works: a plain Frame does not consume
    -- input, so anywhere the header has no control the grip is still the
    -- top-most ACTIVE object under the pointer.
    ZIndex = 3, Name = "Grip", Parent = holder,
  })
  Side.grip = grip
  local dragging, startM, startP
  grip.MouseButton1Down:Connect(function()
    dragging = true
    startM = L.UIS:GetMouseLocation()
    startP = holder.AbsolutePosition
  end)
  Side._freeInputEnded = L.hold(L.UIS.InputEnded:Connect(function(i)
    if i.UserInputType == Enum.UserInputType.MouseButton1 then dragging = false end
  end))
  local lastViewport = L.viewport()
  local lastSize = holder.AbsoluteSize
  Side._freeRenderStep = L.hold(L.RunService.RenderStepped:Connect(function()
    if not holder.Parent then return end

    local vpNow, sizeNow = L.viewport(), holder.AbsoluteSize
    if vpNow ~= lastViewport or sizeNow ~= lastSize then
      lastViewport, lastSize = vpNow, sizeNow
      local at = holder.AbsolutePosition
      local x, y = clampAbsolute(at.X, at.Y)
      local oldOffset = Vector2.new(holder.Position.X.Offset, holder.Position.Y.Offset)
      local origin = holder.AbsolutePosition - oldOffset
      holder.Position = UDim2.fromOffset(x - origin.X, y - origin.Y)
      Side.detachedPosition = Vector2.new(x, y)
    end

    if not dragging then return end
    local m = L.UIS:GetMouseLocation()
    local x, y = clampAbsolute(startP.X + (m.X - startM.X),
                               startP.Y + (m.Y - startM.Y))
    local oldOffset = Vector2.new(holder.Position.X.Offset, holder.Position.Y.Offset)
    local origin = holder.AbsolutePosition - oldOffset
    holder.Position = UDim2.fromOffset(x - origin.X, y - origin.Y)
    Side.detachedPosition = Vector2.new(x, y)
  end))

  L.note("side", "panel detached -- drag it by its header")
  return true
end

function Side.reattach()
  if not (Side.detached and Side.panel and Side.panel.Parent) then
    Side.detached = false
    return false
  end
  local win = L.Hub and L.Hub.window
  if not (win and win.shell) then return false end
  local panel = Side.panel
  local def = sizeDef()
  local sc = (win.scaleObj and win.scaleObj.Scale) or 1
  local shellW = win.shell.AbsoluteSize.X / sc

  -- Preserve the actual screen location even if an inset or another script
  -- moved the free holder without going through our drag callback.
  if Side.holder then Side.detachedPosition = Side.holder.AbsolutePosition end
  stopDetachedDragLoops()

  -- The window or viewport may have moved while minimised. Choose the side
  -- again from current geometry instead of replaying the old attachment edge.
  local roomRight = (L.viewport().X
    - (win.shell.AbsolutePosition.X + win.shell.AbsoluteSize.X)) / sc
  Side.flipped = roomRight < (def.w - TUCK + 12)

  panel.Parent = win.shell
  panel.AnchorPoint = Vector2.new(Side.flipped and 1 or 0, 0.5)
  panel.Position = UDim2.new(0, Side.flipped and TUCK or (shellW - TUCK), 0.5, 0)
  panel.Size = UDim2.fromOffset(def.w, def.h)

  if Side.freeGui then pcall(function() Side.freeGui:Destroy() end) end
  Side.freeGui, Side.holder, Side.detached, Side.freeScale, Side.grip = nil, nil, false, nil, nil
  L.note("side", "panel reattached")
  return true
end

function Side.toggle()
  if Side.open then Side.hide() return true end
  return Side.show()
end

-- PINNABLE, AND AS A TOGGLE RATHER THAN A BUTTON.
--
-- Every other pin is a control that already existed somewhere in a tab; the
-- player panel had none, so there was no way to reach it from the strip at all.
-- Registering it as kind "toggle" rather than "action" is what makes the second
-- click close it -- and it earns the chip a state dot, so the strip reports
-- whether the panel is open instead of only commanding it.
--
-- DEFERRED, because L.Pins is built by a later part than this one: calling
-- register at file scope here would silently do nothing.
task.defer(function()
  if not (L.Pins and L.Pins.register) then return end
  L.Pins.register("hub.panel.Player panel", {
    label = "Player panel",
    kind  = "toggle",
    ctx   = "hub",
    get   = function() return Side.open and true or false end,
    set   = function(on)
      if on then Side.show() else Side.hide() end
    end,
  })
end)

end
do -- ==== lm_21_ai.lua ====
-- LUMEN :: AI
-- Ask a model a question from inside the game, using your own free API key.
-- The key is a credential: it lives in its own file, never in the config, a URL
-- or the activity log, and travels in a header. Every provider here is free-tier.

local L = getgenv().LUMEN
local T, A, C, M = L.T, L.A, L.C, L.Motion

local AI = {}
L.AI = AI

AI.FILE = "_lumen_ai.json"

-- `kind` is the wire format: four of the five speak OpenAI-shaped
-- /chat/completions, so there are only two request builders.
AI.providers = {
  {
    key = "gemini", name = "Google Gemini", kind = "gemini",
    url = "https://generativelanguage.googleapis.com/v1beta/models/%s:generateContent",
    listUrl = "https://generativelanguage.googleapis.com/v1beta/models",
    model = "gemini-3.6-flash",
    keyUrl = "https://aistudio.google.com/apikey",
    note = "Best free limits. No card. Sign in with a Google account.",
  },
  {
    key = "groq", name = "Groq", kind = "openai",
    url = "https://api.groq.com/openai/v1/chat/completions",
    model = "llama-3.3-70b-versatile",
    keyUrl = "https://console.groq.com/keys",
    note = "Fastest replies. Free tier, no card.",
  },
  {
    key = "openrouter", name = "OpenRouter", kind = "openai",
    url = "https://openrouter.ai/api/v1/chat/completions",
    -- OpenRouter's /models lists only 15 ':free' ids, and the old llama-3.3
    -- default is no longer one of them.
    model = "nvidia/nemotron-3-super-120b-a12b:free",
    keyUrl = "https://openrouter.ai/keys",
    note = "Many models in one key. Anything ending ':free' costs nothing.",
    -- Attribution headers; not required to authenticate.
    headers = { ["HTTP-Referer"] = "https://github.com/lumen-hub",
                ["X-Title"] = "LUMEN" },
  },
  {
    key = "cerebras", name = "Cerebras", kind = "openai",
    url = "https://api.cerebras.ai/v1/chat/completions",
    model = "llama-3.3-70b",
    keyUrl = "https://cloud.cerebras.ai",
    note = "Very fast. Free tier, no card.",
  },
  {
    key = "mistral", name = "Mistral", kind = "openai",
    url = "https://api.mistral.ai/v1/chat/completions",
    model = "mistral-small-latest",
    keyUrl = "https://console.mistral.ai/api-keys",
    note = "Free experiment tier. Needs a phone number.",
  },
}

function AI.providerFor(key)
  for _, p in ipairs(AI.providers) do if p.key == key then return p end end
  return AI.providers[1]
end

function AI.names()
  local out = {}
  for _, p in ipairs(AI.providers) do out[#out + 1] = p.name end
  return out
end

function AI.keyForName(name)
  for _, p in ipairs(AI.providers) do if p.name == name then return p.key end end
  return AI.providers[1].key
end

-- ---------------------------------------------------------------- storage

AI.state = { provider = "gemini", model = nil, key = nil, context = true }

function AI.load()
  local ok, raw = pcall(readfile, AI.FILE)
  if not ok or type(raw) ~= "string" then return false end
  local decoded, data = pcall(function() return L.Http:JSONDecode(raw) end)
  if not decoded or type(data) ~= "table" then return false end
  if type(data.provider) == "string" then AI.state.provider = data.provider end
  if type(data.model) == "string" and data.model ~= "" then AI.state.model = data.model end
  if type(data.key) == "string" and data.key ~= "" then AI.state.key = data.key end
  if type(data.context) == "boolean" then AI.state.context = data.context end
  return true
end

function AI.save()
  local ok = pcall(writefile, AI.FILE, L.Http:JSONEncode({
    provider = AI.state.provider, model = AI.state.model,
    key = AI.state.key, context = AI.state.context,
  }))
  -- Says nothing about the key itself.
  L.note("ai", ok and "settings saved" or "could not write settings")
  return ok
end

function AI.forget()
  AI.state.key = nil
  pcall(delfile, AI.FILE)
  L.note("ai", "key removed")
end

-- Never render a key in full: enough to recognise it, not enough to use.
function AI.maskedKey()
  local k = AI.state.key
  if type(k) ~= "string" or k == "" then return "no key set" end
  if #k <= 10 then return string.rep("*", #k) end
  return k:sub(1, 4) .. string.rep("*", 8) .. k:sub(-4)
end

function AI.modelName()
  return AI.state.model or AI.providerFor(AI.state.provider).model
end

-- ---------------------------------------------------------------- transport

local function httpFn()
  local f = rawget(getgenv(), "request") or rawget(getgenv(), "http_request")
  return type(f) == "function" and f or nil
end

function AI.canCall() return httpFn() ~= nil end

-- Pulls the human-readable message out of the provider's error body.
local function explain(status, body)
  local decoded, data = pcall(function() return L.Http:JSONDecode(body) end)
  if decoded and type(data) == "table" then
    local e = data.error
    if type(e) == "table" and type(e.message) == "string" then return e.message end
    if type(e) == "string" then return e end
    if type(data.message) == "string" then return data.message end
  end
  if status == 401 or status == 403 then return "the key was rejected" end
  if status == 429 then return "rate limited -- wait a moment and try again" end
  return string.format("http %s", tostring(status))
end

-- Some rejections really mean "you pasted it wrong". OpenRouter reports a
-- malformed bearer token as a missing one.
local function hint(msg)
  local m = tostring(msg):lower()
  if m:find("missing authentication") then
    return " -- that usually means the key is malformed; re-copy the whole thing"
  end
  if m:find("user not found") or m:find("not valid") or m:find("invalid api key") then
    return " -- check you copied the whole key, and that it is for this provider"
  end
  -- Retired model with a valid key.
  if m:find("no longer available") or m:find("not found") or m:find("decommission")
     or m:find("does not exist") or m:find("unsupported model") then
    return " -- press Fetch models: this one has been retired by the provider"
  end
  return ""
end

-- ---------------------------------------------------------------- models
-- Model names rot invisibly: a retired model still authenticates and returns a
-- well-formed refusal, so ask the provider what it actually serves.
function AI.listModels(done)
  local function finish(ok, v) L.try("ai.models", done, ok, v) end
  local req = httpFn()
  if not req then return finish(false, "This executor has no request function.") end

  local p = AI.providerFor(AI.state.provider)
  local url = p.listUrl or p.url:gsub("/chat/completions$", "/models")
  local headers = { ["Content-Type"] = "application/json" }
  if p.kind == "gemini" then
    headers["x-goog-api-key"] = AI.state.key or ""
  else
    headers["Authorization"] = "Bearer " .. (AI.state.key or "")
  end

  task.spawn(function()
    local ok, res = pcall(req, { Url = url, Method = "GET", Headers = headers })
    if not ok or type(res) ~= "table" then return finish(false, "Request failed.") end
    local status = res.StatusCode or 0
    if status < 200 or status >= 300 then
      return finish(false, explain(status, res.Body or ""))
    end
    local decoded, data = pcall(function() return L.Http:JSONDecode(res.Body) end)
    if not decoded or type(data) ~= "table" then return finish(false, "Unreadable list.") end

    local ids = {}
    if p.kind == "gemini" then
      for _, m in ipairs(data.models or {}) do
        -- Only ids that support generateContent can answer a prompt.
        local can = false
        for _, meth in ipairs(m.supportedGenerationMethods or {}) do
          if meth == "generateContent" then can = true end
        end
        local id = tostring(m.name or ""):gsub("^models/", "")
        if can and id ~= "" then ids[#ids + 1] = id end
      end
    else
      for _, m in ipairs(data.data or {}) do
        local id = tostring(m.id or "")
        -- OpenRouter lists 400+ models, most of which cost money
        if id ~= "" and (p.key ~= "openrouter" or id:find(":free", 1, true)) then
          ids[#ids + 1] = id
        end
      end
    end
    table.sort(ids)
    if #ids == 0 then return finish(false, "The provider listed no usable models.") end
    finish(true, ids)
  end)
end

-- Always calls back with (ok, text): a silent failure looks like a slow answer.
function AI.ask(prompt, done)
  local function finish(ok, text) L.try("ai.done", done, ok, text) end

  if type(prompt) ~= "string" or prompt:gsub("%s", "") == "" then
    return finish(false, "Nothing to ask.")
  end
  local req = httpFn()
  if not req then return finish(false, "This executor has no request function.") end
  if not AI.state.key or AI.state.key == "" then
    return finish(false, "No API key yet. Pick a provider and paste a key.")
  end

  local p = AI.providerFor(AI.state.provider)
  local model = AI.modelName()

  -- Sends the place only: no username, user id or server id.
  local text = prompt
  if AI.state.context then
    text = string.format(
      "Context: the user is playing the Roblox experience \"%s\" (place id %d). " ..
      "Answer for that game where relevant.\n\n%s",
      AI.placeName or "unknown", game.PlaceId, prompt)
  end

  local url, headers, body
  if p.kind == "gemini" then
    url = string.format(p.url, model)
    -- Header, not ?key=: a credential in a query string ends up in logs.
    headers = { ["Content-Type"] = "application/json",
                ["x-goog-api-key"] = AI.state.key }
    body = L.Http:JSONEncode({ contents = { { parts = { { text = text } } } } })
  else
    url = p.url
    headers = { ["Content-Type"] = "application/json",
                ["Authorization"] = "Bearer " .. AI.state.key }
    if p.headers then for k, v in pairs(p.headers) do headers[k] = v end end
    body = L.Http:JSONEncode({
      model = model,
      messages = { { role = "user", content = text } },
    })
  end

  -- Blocking call, so it runs off the render thread.
  task.spawn(function()
    local sent = os.clock()
    local ok, res = pcall(req, { Url = url, Method = "POST",
                                 Headers = headers, Body = body })
    if not ok then return finish(false, "Request failed: " .. tostring(res)) end
    if type(res) ~= "table" then return finish(false, "The executor returned nothing.") end

    local status = res.StatusCode or res.status_code or 0
    if status < 200 or status >= 300 then
      local why = explain(status, res.Body or "")
      L.log("refused", "ai", string.format("%s said no: %s", p.name, why))
      return finish(false, why .. hint(why))
    end

    local decoded, data = pcall(function() return L.Http:JSONDecode(res.Body) end)
    if not decoded or type(data) ~= "table" then
      return finish(false, "Could not read the reply.")
    end

    local answer
    if p.kind == "gemini" then
      local cand = data.candidates and data.candidates[1]
      local part = cand and cand.content and cand.content.parts and cand.content.parts[1]
      answer = part and part.text
      -- A declined prompt still returns 200, with no candidate.
      if not answer and cand and cand.finishReason then
        return finish(false, "The model stopped: " .. tostring(cand.finishReason))
      end
    else
      local choice = data.choices and data.choices[1]
      answer = choice and choice.message and choice.message.content
    end

    if type(answer) ~= "string" or answer == "" then
      return finish(false, "The reply had no text in it.")
    end
    L.note("ai", string.format("%s answered in %.1fs (%d chars)",
      p.name, os.clock() - sent, #answer))
    finish(true, answer)
  end)
end

-- ---------------------------------------------------------------- ui

function AI.build(page)
  C.ctx("ai")
  AI.load()

  -- Resolved once, so answers name the right game.
  task.spawn(function()
    local ok, info = pcall(function()
      return game:GetService("MarketplaceService"):GetProductInfo(game.PlaceId)
    end)
    if ok and type(info) == "table" and info.Name then AI.placeName = info.Name end
  end)

  C.section(page, "ask")

  -- ---- the live stage -------------------------------------------------
  -- Collapsed to zero height when idle.
  local STAGE_H = 64
  local stage = A.surface({
    Parent = page, elev = 1, radius = T.r.md,
    Size = UDim2.new(1, 0, 0, 0), Name = "Stage",
  })
  stage.ClipsDescendants = true
  stage.BackgroundTransparency = 1

  -- Self-clocked, unlike the tab icons the window seeks each frame. Starts
  -- paused so an idle page burns no RenderStepped on an unseen orb.
  local orb = L.Video and L.Video.new(stage, {
    folder = "lumen_fx/think", prefix = "think", count = 44, fps = 24,
    size = 38, Position = UDim2.fromOffset(14 + 19, STAGE_H / 2), ZIndex = 3,
    loop = true,
  })
  if orb then orb:pause() end

  local dots = C.textDots(stage, {
    text = "Thinking", size = T.size.body, font = T.font.medium,
    colour = T.c.text, autoStart = false,
    Position = UDim2.fromOffset(64, STAGE_H / 2 - 16),
    Size = UDim2.new(1, -160, 0, 20), ZIndex = 3,
  })

  local elapsed = A.text({
    Text = "", font = T.font.mono, size = T.size.micro, colour = T.c.textOff,
    align = Enum.TextXAlignment.Right, AnchorPoint = Vector2.new(1, 0.5),
    Position = UDim2.new(1, -14, 0.5, 0), Size = UDim2.fromOffset(90, 16),
    ZIndex = 3, Parent = stage,
  })

  local out = C.output(page, {
    default = "Answers appear here.", maxHeight = 300,
  })

  local prompt = C.textarea(page, {
    text = "Your question",
    placeholder = "What is the fastest way to earn money in this game?",
    lines = 4,
  })

  local busy, tick, reveal = false, nil, nil

  local function stopReveal()
    if reveal then reveal:Disconnect() reveal = nil end
  end

  -- Answers arrive whole; revealed on a per-second character budget.
  local function revealInto(text)
    stopReveal()
    local total = #text
    if total <= 120 then out:set(text, T.c.text) return end
    local shown, rate = 0, math.max(420, total / 2.2)
    local last = os.clock()
    out:set("", T.c.text)
    reveal = L.hold(L.RunService.RenderStepped:Connect(function()
      local now = os.clock()
      shown = math.min(total, shown + (now - last) * rate)
      last = now
      -- Cut on a space so words do not appear half-written.
      local n = math.floor(shown)
      if n < total then
        local sp = text:find("%s", n) or n
        n = math.min(sp, total)
      end
      out:set(text:sub(1, n), T.c.text)
      if n >= total then stopReveal() end
    end))
  end

  local function setBusy(on, what)
    busy = on
    if on then
      stage.BackgroundTransparency = 0
      M.to(stage, "Size", UDim2.new(1, 0, 0, STAGE_H), "base")
      dots:setText(what or "Thinking")
      dots:start()
      if orb then orb:play() end
      local t0 = os.clock()
      elapsed.Text = "0.0s"
      tick = L.hold(L.RunService.RenderStepped:Connect(function()
        elapsed.Text = string.format("%.1fs", os.clock() - t0)
      end))
    else
      dots:stop()
      if orb then orb:pause() end
      if tick then tick:Disconnect() tick = nil end
      M.to(stage, "Size", UDim2.new(1, 0, 0, 0), "fast")
      task.delay(0.30, function()
        if not busy then stage.BackgroundTransparency = 1 end
      end)
    end
  end
  AI._setBusy = setBusy

  local function ask()
    if busy then
      L.Toast.info("Still thinking", "One question at a time.")
      return
    end
    local q = prompt:get()
    if q:gsub("%s", "") == "" then
      L.Toast.warn("Nothing to ask", "Type a question first.")
      return
    end
    stopReveal()
    setBusy(true, "Thinking")
    out:set("", T.c.text)
    AI.ask(q, function(ok, text)
      setBusy(false)
      if ok then
        revealInto(text)
      else
        out:set(text, T.c.bad)
        L.Toast.warn("No answer", text)
      end
    end)
  end

  AI._ask = ask
  AI._prompt = prompt

  C.actions(page, {
    { text = "Ask", primary = true, callback = ask },
    { text = "Copy answer", callback = function()
        local t = out:get()
        if t == "" then return end
        local ok = pcall(function() setclipboard(t) end)
        if ok then L.Toast.ok("Copied", "Answer on the clipboard.")
        else L.Toast.warn("No clipboard", "This executor has no setclipboard.") end
      end },
    { text = "Clear", callback = function()
        prompt:set("") out:set("Answers appear here.", T.c.textMute)
      end },
  })

  -- ---- provider ------------------------------------------------------
  C.section(page, "provider")

  local keyRow, modelRow
  local function refreshKeyRow()
    if keyRow then keyRow:set("") end
    if modelRow then modelRow:set(AI.modelName()) end
  end

  local status = C.output(page, { mono = true, maxHeight = 90 })
  local function refreshStatus()
    local p = AI.providerFor(AI.state.provider)
    status:set(string.format("%s   %s\nmodel  %s\nkey    %s",
      p.name, AI.canCall() and "" or "(no http in this executor)",
      AI.modelName(), AI.maskedKey()),
      AI.state.key and T.c.textMute or T.c.textOff)
  end

  C.dropdown(page, {
    text = "Provider", desc = "All five have a free tier",
    options = AI.names(),
    default = AI.providerFor(AI.state.provider).name,
    callback = function(name)
      AI.state.provider = AI.keyForName(name)
      AI.state.model = nil            -- the old model name means nothing here
      AI.save()
      refreshKeyRow()
      refreshStatus()
      local p = AI.providerFor(AI.state.provider)
      L.Toast.info(p.name, p.note)
    end,
  })

  modelRow = C.input(page, {
    text = "Model", desc = "Edit if one stops working",
    default = AI.modelName(),
    callback = function(v)
      v = (v or ""):gsub("^%s+", ""):gsub("%s+$", "")
      AI.state.model = (v ~= "" and v) or nil
      AI.save()
      refreshStatus()
    end,
  })

  keyRow = C.input(page, {
    text = "API key", desc = "Stored locally, sent as a header",
    placeholder = "paste, then press Enter",
    callback = function(v)
      v = (v or ""):gsub("%s", "")
      if v == "" then return end
      AI.state.key = v
      AI.save()
      refreshKeyRow()                 -- clears the box so it is not left on screen
      refreshStatus()
      L.Toast.ok("Key saved", "Stored in " .. AI.FILE .. " and masked from now on.")
    end,
  })

  C.toggle(page, {
    text = "Tell it what game you are in",
    desc = "Sends the place, nothing about you",
    default = AI.state.context,
    callback = function(v) AI.state.context = v AI.save() end,
  })

  local models = C.output(page, { mono = true, maxHeight = 190,
    default = "Press Fetch models to see what this provider serves right now." })

  C.actions(page, {
    { text = "Fetch models", primary = true, callback = function()
        if not AI.state.key or AI.state.key == "" then
          L.Toast.warn("No key", "A key is needed to ask what models exist.")
          return
        end
        models:set("Asking " .. AI.providerFor(AI.state.provider).name .. "...", T.c.textOff)
        AI.listModels(function(ok, v)
          if not ok then
            models:set(tostring(v), T.c.bad)
            L.Toast.warn("Could not list models", tostring(v))
            return
          end
          models:set(table.concat(v, "\n"), T.c.textMute)
          -- If the model in use is not on the list, switch to one that is.
          local cur, found = AI.modelName(), false
          for _, id in ipairs(v) do if id == cur then found = true end end
          if found then
            L.Toast.ok("Models listed", #v .. " available. Yours is one of them.")
          else
            AI.state.model = v[1]
            AI.save()
            if modelRow then modelRow:set(v[1]) end
            refreshStatus()
            L.Toast.warn("That model is gone",
              cur .. " is no longer served. Switched you to " .. v[1] .. ".")
          end
        end)
      end },
    { text = "Copy key page link", callback = function()
        local p = AI.providerFor(AI.state.provider)
        local ok = pcall(function() setclipboard(p.keyUrl) end)
        if ok then L.Toast.ok("Link copied", p.keyUrl)
        else L.Toast.info(p.name, p.keyUrl) end
      end },
    { text = "Forget key", callback = function()
        AI.forget() refreshKeyRow() refreshStatus()
        L.Toast.ok("Forgotten", "The key is off this machine.")
      end },
  })

  refreshStatus()

  -- ---- where to get one ----------------------------------------------
  C.section(page, "free keys")
  local lines = {}
  for _, p in ipairs(AI.providers) do
    lines[#lines + 1] = string.format("%-16s %s\n%s", p.name, p.keyUrl, "   " .. p.note)
  end
  C.output(page, { mono = true, maxHeight = 300,
                   default = table.concat(lines, "\n\n") })

end

end
do -- ==== lm_09_demo.lua ====
-- LUMEN :: HUB
-- Builds the window and its tabs, and owns the launch sequence.
--
-- Per-game modules register themselves with Hub.register(placeId, name, builder)
-- and appear under Farming automatically.

local L = getgenv().LUMEN
local T, M, A, C = L.T, L.Motion, L.A, L.C
local mk = L.mk

local Hub = {}
L.Hub = Hub

Hub.modules = {}          -- [placeId] = function(ctx) ... end
Hub.settings = { autoRun = false, notify = true, scale = nil }

-- A GAME MODULE MAY OWN THE WHOLE WINDOW, NOT JUST A PAGE IN IT.
--
-- The first shape of this put every game's features into one section of the
-- Farming tab. That is fine for a three-toggle module and wrong for a real one:
-- Murder Mystery 2 has roles, a fling, combat, ESP, pickups, safety and a
-- lookup, and stacking all of it into a single scroll makes the game LUMEN
-- supports feel like a footnote inside LUMEN.
--
-- So a module can now declare TABS. When it does, those tabs are built first,
-- under the game's own nav section, and the universal ones follow. The module
-- is not shipping its own interface -- it gets the same window, springs, atoms
-- and controls as everything else -- it is just allowed to be the first thing
-- you see, and to be shaped like the game rather than like the framework.
--
-- Both call shapes are accepted, because the older modules use the first:
--
--   Hub.register(placeId, "Name", builderFn)        -- one page, in Farming
--   Hub.register(placeId, {                          -- its own tabs
--     name = "Murder Mystery 2", short = "MM2",
--     accent = Color3.fromRGB(...),
--     tabs = { { name = "Round", chrome = "eye", desc = "...", build = fn } },
--   })
function Hub.register(placeId, nameOrSpec, builder)
  local spec
  if type(nameOrSpec) == "table" then
    spec = nameOrSpec
    spec.build = spec.build or builder
  else
    spec = { name = nameOrSpec, build = builder }
  end
  spec.name = spec.name or ("Place " .. tostring(placeId))
  Hub.modules[tostring(placeId)] = spec
end

function Hub.moduleFor()
  return Hub.modules[tostring(game.PlaceId)]
end

-- True when the current place brings its own tabs, which is what decides
-- whether this session is "the MM2 build of LUMEN" or "LUMEN, universal".
function Hub.hasOwnTabs()
  local m = Hub.moduleFor()
  return (m and type(m.tabs) == "table" and #m.tabs > 0) and true or false
end

-- ---------------------------------------------------------------- empty state

-- AN EMPTY STATE THAT ONLY APOLOGISES IS WASTED SPACE. "Nothing here" is a fact
-- the user already had; what they need is why it is empty and what would change
-- that. So this takes an optional action, and the body is measured and given
-- exactly the height it needs rather than a fixed 32 px that silently clipped a
-- third line.
local function emptyState(page, title, body, action)
  local TS = game:GetService("TextService")
  local f = A.surface({
    Parent = page, elev = 0, radius = T.r.md, line = true,
    Size = UDim2.new(1, 0, 0, 132), Name = "Empty",
  })

  local glyph = A.Icon.search(f, 26, T.c.textOff)
  glyph.AnchorPoint = Vector2.new(0.5, 0)
  glyph.Position = UDim2.new(0.5, 0, 0, 30)
  A.text({
    Text = title, font = T.font.strong, size = T.size.body, colour = T.c.textDim,
    align = Enum.TextXAlignment.Center,
    Position = UDim2.fromOffset(0, 66), Size = UDim2.new(1, 0, 0, 16), Parent = f,
  })

  -- height derived from the actual wrapped text, at the page's real width
  local bodyLbl = A.text({
    Text = body, font = T.font.body, size = T.size.micro, colour = T.c.textOff,
    align = Enum.TextXAlignment.Center, wrap = true,
    Position = UDim2.new(0, 24, 0, 86), Size = UDim2.new(1, -48, 0, 32), Parent = f,
  })
  task.defer(function()
    if not f.Parent then return end
    local w = math.max(f.AbsoluteSize.X - 48, 40)
    local ok, sz = pcall(function()
      return TS:GetTextSize(body, bodyLbl.TextSize, bodyLbl.Font, Vector2.new(w, 9999))
    end)
    local h = (ok and sz) and math.ceil(sz.Y) or 32
    bodyLbl.Size = UDim2.new(1, -48, 0, h)
    f.Size = UDim2.new(1, 0, 0, 86 + h + (action and 52 or 22))
    if action then
      local btn = C.button(f, { text = action.text, callback = action.callback })
      btn.frame.Size = UDim2.fromOffset(math.min(f.AbsoluteSize.X - 48, 220), 32)
      btn.frame.AnchorPoint = Vector2.new(0.5, 0)
      btn.frame.Position = UDim2.new(0.5, 0, 0, 86 + h + 10)
    end
  end)
  return f
end

-- ---------------------------------------------------------------- build

function Hub.build()
  -- named `placeMod` rather than `mod`, which is already a local further down
  -- in this function for the same value; two of them shadowing each other is a
  -- lint warning today and a wrong-variable bug the next time this is edited
  local placeMod = Hub.moduleFor()
  local owns = Hub.hasOwnTabs()

  -- THE SUBTITLE IS THE DETECTOR'S ONLY VISIBLE OUTPUT, AND IT SHOULD BE.
  -- A place id told you nothing you could act on. The name of the game LUMEN
  -- recognised, or plainly that it did not, is the one fact worth the line.
  local win = L.Window.new({
    title = "LUMEN",
    subtitle = owns and string.format("v%s   %s", L.VERSION, placeMod.name)
                    or  string.format("v%s   universal   place %d", L.VERSION, game.PlaceId),
    width = 880, height = 556,
  })
  Hub.window = win

  -- ---- THE GAME'S OWN TABS, BEFORE ANYTHING ELSE ----------------------
  --
  -- Built from the same atoms, controls and motion as every other page -- what
  -- makes them the game's own is position and shape, not a separate interface.
  -- Put first because if LUMEN recognises the place, the place is the reason
  -- the operator opened it.
  if owns then
    win:navSection(placeMod.short or placeMod.name)
    for _, spec in ipairs(placeMod.tabs) do
      local t = win:tab({
        name = spec.name, chrome = spec.chrome or "spark", desc = spec.desc,
      })
      if type(spec.build) == "function" then
        L.try("mod." .. tostring(spec.name), spec.build,
          { page = t.body, tab = t, window = win, hub = Hub, module = placeMod })
      end
    end
  end

  -- ---- HOME ----------------------------------------------------------
  win:navSection("Session")
  local home = win:tab({ name = "Overview", chrome = "eye",
    desc = "Live session state and quick actions" })
  do
    local p = home.body

    -- NO IDENTITY CARD HERE. The username is already in the sidebar footer and
    -- the ping is already in the header; a card repeating both was the same three
    -- facts printed three times, which is what makes a dashboard feel padded.
    -- This block is about the PLACE, which is stated nowhere else.
    local tiles = C.tiles(p, {
      { key = "ping",    label = "Ping",    value = "--" },
      { key = "fps",     label = "FPS",     value = "--" },
      { key = "players", label = "Players", value = "--" },
      { key = "uptime",  label = "Session", value = "0:00" },
    })
    task.spawn(function()
      local Stats = game:GetService("Stats")
      local t0, frames, acc, fps = os.clock(), 0, 0, 0
      L.hold(L.RunService.RenderStepped:Connect(function(dt)
        frames = frames + 1 acc = acc + dt
        if acc >= 0.5 then fps = frames / acc frames, acc = 0, 0 end
      end))
      while L.live() and tiles.frame.Parent do
        local ok, v = pcall(function()
          return Stats.Network.ServerStatsItem["Data Ping"]:GetValue()
        end)
        local ms = (ok and type(v) == "number") and math.floor(v) or -1
        tiles:set("ping", ms >= 0 and (ms .. " ms") or "--",
          (ms < 0 and T.c.textOff) or (ms < 120 and T.c.ok)
          or (ms < 260 and T.c.warn) or T.c.bad)
        tiles:set("fps", string.format("%d", fps + 0.5),
          fps >= 50 and T.c.ok or (fps >= 30 and T.c.warn or T.c.bad))
        tiles:set("players", #L.Players:GetPlayers() .. "/" .. L.Players.MaxPlayers)
        local el = os.clock() - t0
        tiles:set("uptime", string.format("%d:%02d", el / 60, el % 60), T.c.accent)
        task.wait(1)
      end
    end)

    C.section(p, "place")
    local mod = Hub.moduleFor()
    local card = A.surface({
      Parent = p, elev = 1, radius = T.r.md, sheen = true,
      Size = UDim2.new(1, 0, 0, 76), Name = "Place",
    })
    A.chrome(card, mod and "torus" or "eye", 34, {
      Position = UDim2.fromOffset(14, 21), ZIndex = 2 })
    local placeName = "Place " .. game.PlaceId
    pcall(function()
      local info = game:GetService("MarketplaceService"):GetProductInfo(game.PlaceId)
      if info and info.Name then placeName = info.Name end
    end)
    A.text({
      Text = placeName, font = T.font.strong, size = T.size.head, colour = T.c.text,
      Position = UDim2.fromOffset(60, 20), Size = UDim2.new(1, -76, 0, 18),
      truncate = true, Parent = card,
    })
    A.text({
      Text = mod and ("module loaded: " .. mod.name) or "no module written for this place yet",
      font = T.font.mono, size = T.size.micro,
      colour = mod and T.c.ok or T.c.textMute,
      Position = UDim2.fromOffset(60, 42), Size = UDim2.new(1, -76, 0, 14),
      truncate = true, Parent = card,
    })

    -- ---- activity strip ------------------------------------------------
    --
    -- Wave 1 gave the hub a memory; this is where the landing page finally reads
    -- from it. One line of state and the last three things that happened -- not
    -- a second copy of the Activity tab, just enough that you can tell at a
    -- glance whether anything needs looking at, and click through if it does.
    C.section(p, "activity")
    local strip = A.surface({
      Parent = p, elev = 1, radius = T.r.md, sheen = true,
      Size = UDim2.new(1, 0, 0, 98), Name = "ActivityStrip",
    })
    local sDot = mk("Frame", {
      AnchorPoint = Vector2.new(0, 0.5), Position = UDim2.new(0, 14, 0, 19),
      Size = UDim2.fromOffset(6, 6), BackgroundColor3 = T.c.ok,
      BorderSizePixel = 0, ZIndex = 2, Parent = strip,
    })
    L.corner(999, sDot)
    -- Derived from the same four numbers, for the reason the dropdown was: a
    -- hand-picked `-120` here left the head and "view all" overlapping by 2 px.
    local ST_LEFT, ST_MORE_W, ST_RIGHT, ST_GAP = 28, 80, 14, 10
    local sHead = A.text({
      Text = "", font = T.font.medium, size = T.size.label, colour = T.c.textDim,
      Position = UDim2.fromOffset(ST_LEFT, 8),
      Size = UDim2.new(1, -(ST_LEFT + ST_MORE_W + ST_RIGHT + ST_GAP), 0, 22),
      truncate = true, ZIndex = 2, Parent = strip,
    })
    local sMore = A.text({
      Text = "view all", font = T.font.mono, size = T.size.tiny, colour = T.c.textOff,
      align = Enum.TextXAlignment.Right, AnchorPoint = Vector2.new(1, 0),
      Position = UDim2.new(1, -ST_RIGHT, 0, 12), Size = UDim2.fromOffset(ST_MORE_W, 14),
      ZIndex = 2, Parent = strip,
    })
    -- Same 52 px clock column as the log view had, and the same bug: "23:58:25"
    -- needs 56 at this font, so the strip quietly dropped the last digit of every
    -- timestamp. Measured rather than nudged, and the text column follows it.
    local CLOCK_W = math.ceil(game:GetService("TextService")
      :GetTextSize("00:00:00", T.size.tiny, T.font.mono, Vector2.new(1e5, 1e5)).X) + 4
    local WHAT_X = 28 + CLOCK_W + 4

    local sRows = {}
    for i = 1, 3 do
      sRows[i] = {
        when = A.text({
          Text = "", font = T.font.mono, size = T.size.tiny, colour = T.c.textOff,
          Position = UDim2.fromOffset(28, 26 + i * 18), Size = UDim2.fromOffset(CLOCK_W, 14),
          ZIndex = 2, Parent = strip,
        }),
        what = A.text({
          Text = "", font = T.font.body, size = T.size.micro, colour = T.c.textMute,
          Position = UDim2.fromOffset(WHAT_X, 26 + i * 18),
          Size = UDim2.new(1, -(WHAT_X + 16), 0, 14),
          truncate = true, ZIndex = 2, Parent = strip,
        }),
      }
    end
    A.interactive(strip, { radius = T.r.md, onClick = function()
      if Hub.activityIndex then win:select(Hub.activityIndex) end
    end })

    task.spawn(function()
      while L.live() and strip.Parent do
        local state, nf, nc = L.health()
        local col = (state == "fault" and T.c.bad)
                 or (state == "contested" and T.c.warn) or T.c.ok
        M.to(sDot, "BackgroundColor3", col, "fast")
        M.to(sHead, "TextColor3", state == "ok" and T.c.textDim or col, "fast")
        sHead.Text = (state == "ok" and "Everything switched on is holding")
          or (state == "fault"
              and string.format("%d fault%s recorded", nf, nf == 1 and "" or "s"))
          or string.format("%d feature%s asked for but not in effect", nc, nc == 1 and "" or "s")
        local logs = L.logs
        for i = 1, 3 do
          local e = logs[#logs - i + 1]
          sRows[i].when.Text = e and e.at or ""
          sRows[i].what.Text = e
            and (e.src .. "  " .. e.text .. (e.n > 1 and ("  x" .. e.n) or ""))
            or (i == 1 and #logs == 0 and "nothing yet this session" or "")
          sRows[i].what.TextColor3 = (e and e.kind == "fault" and T.c.bad)
            or (e and e.kind == "refused" and T.c.warn) or T.c.textMute
        end
        sMore.Text = #logs > 3 and (#logs .. " entries") or "view all"
        task.wait(0.6)
      end
    end)

    C.section(p, "actions")
    C.actions(p, {
      { text = "Open farming", primary = true, callback = function()
          win:select(2)
        end },
      { text = "Test alert", callback = function()
          L.Toast.ok("Working", "Springs carry velocity through every interruption.")
        end },
      { text = "Copy place id", callback = function()
          local ok = pcall(function() setclipboard(tostring(game.PlaceId)) end)
          if ok then L.Toast.info("Copied", tostring(game.PlaceId))
          else L.Toast.warn("No clipboard", "This executor has no setclipboard.") end
        end },
    })
  end

  -- ---- FARMING -------------------------------------------------------
  local farm = win:tab({ name = "Farming", chrome = "chart",
    desc = "Per-game automation modules" })
  do
    local p = farm.body
    local mod = Hub.moduleFor()
    C.section(p, "supported games")

    -- The carousel is built FROM the module registry rather than from its own
    -- list. Two lists of the same games drift apart the moment one is edited, and
    -- the drift is invisible: a card that promises automation nothing backs.
    local Mods = L.Modules
    local games = Mods and Mods.list() or {}

    Hub.spinner = L.Spinner.new(p, {
      Size = UDim2.new(1, 0, 0, 330),
      items = games,
      -- Says what picking this card would actually get you, before you press Join.
      subFor = function(item, i, total)
        local e = item and item.entry
        local state
        if not e then state = "no module"
        elseif item.place == game.PlaceId then state = "you are here"
        elseif Mods.exists(e) then state = string.format("%s  %d KB", e.file, Mods.sizeKB(e))
        else state = "missing " .. e.file end
        if Mods.always(item.place) then state = state .. "   *  auto" end
        return string.format("%d / %d   -   %s", i, total, state)
      end,
      callback = function(item) L.Toast.info("Selected", item.name) end,
      onFront = function(item) Hub._front = item end,
    })

    -- Joining is the whole point of the picker, and it has to survive the
    -- teleport: queue the hub for the destination first, then travel. Modules
    -- handles both halves so the ordering cannot be got wrong here.
    C.actions(p, {
      { text = "Join and auto-farm", primary = true, callback = function()
          local item = Hub._front or (Hub.spinner and Hub.spinner.items[Hub.spinner.index])
          if not item or not item.place then
            L.Toast.warn("No game", "Nothing selected.") return
          end
          if item.place == game.PlaceId then
            -- already in the place: skip the round trip and just start it
            local e = Mods.registry[item.place]
            if e and Mods.exists(e) then
              local ok, why = Mods.launch(e)
              if ok then L.Toast.ok("Started", why) else L.Toast.bad("Failed", why) end
            else
              L.Toast.info("Already here", "You are in " .. item.name .. ".")
            end
            return
          end
          if not Mods.canQueue() then
            L.Toast.warn("No autorun",
              "This executor cannot queue a script across a teleport. " ..
              "You will land in " .. item.name .. " without the hub.")
          end
          task.delay(0.5, function()
            Mods.travelTo(item.place, item.name, function(ok, why, link, code)
              if ok then
                L.Toast.info("Joining", item.name .. "  -  hub will reload on arrival")
                return
              end
              -- The arrival is armed either way, so the useful thing is never an
              -- error -- it is the link, because joining by hand still auto-farms.
              local copied = pcall(function() setclipboard(link) end)
              if Hub._refreshArmed then Hub._refreshArmed() end
              local tail = copied and "Link copied -- join it and the hub starts itself."
                                   or ("Open " .. link .. " and the hub starts itself.")
              if code == "policy" then
                -- not a malfunction: Roblox was never going to allow this one,
                -- and we did not ask, so there is no error dialog to explain
                L.Toast.ok("Armed  -  " .. item.name,
                  "Roblox only teleports between one creator's games, so " ..
                  "there is nothing to click through. " .. tail)
              else
                L.Toast.warn("Roblox blocked the teleport", why .. "  -  " .. tail)
              end
            end)
          end)
        end },
      -- The half of Join that Roblox cannot veto. Arming does not need a
      -- teleport at all: it queues the hub for the next place you enter, so you
      -- join the game however you like and it is already running when you land.
      { text = "Arm for manual join", callback = function()
          local item = Hub._front or (Hub.spinner and Hub.spinner.items[Hub.spinner.index])
          if not item then return end
          local ok, why = Mods.queueArrival(item.place)
          if not ok then L.Toast.bad("Cannot arm", tostring(why)) return end
          local link = Mods.gameLink(item.place)
          local copied = pcall(function() setclipboard(link) end)
          if Hub._refreshArmed then Hub._refreshArmed() end
          L.Toast.ok("Armed  -  " .. item.name,
            copied and "Link copied. Join it and the hub starts on its own."
                   or  ("Join " .. link .. " and the hub starts on its own."))
        end },
      -- Settable from here rather than only from inside the game, which is the
      -- whole point: you decide what farms itself while you are stood elsewhere.
      { text = "Always run this", callback = function()
          local item = Hub._front or (Hub.spinner and Hub.spinner.items[Hub.spinner.index])
          if not item then return end
          local on = not Mods.always(item.place)
          Mods.setAlways(item.place, on)
          if Hub.spinner then                      -- refresh the "* auto" marker
            Hub.spinner.sub.Text = Hub.spinner.subText(item, Hub.spinner.index)
          end
          if on then
            L.Toast.ok("Always run  -  " .. item.name,
              "It starts by itself every time you enter, however you got there.")
          else
            L.Toast.info("No longer automatic", item.name .. " will wait to be asked.")
          end
        end },
    })

    C.paragraph(p,
      "Roblox blocks most cross-game teleports. Join arms the game and copies the link, so joining it any way you like still starts the script.")

    -- Arming outlives the session, so it must be visible and cancellable. A
    -- hidden pending state that fires on some unrelated join later is the kind
    -- of surprise that reads as the hub being broken.
    do
      local armed = A.text({
        Text = "", font = T.font.mono, size = T.size.micro, colour = T.c.textMute,
        Size = UDim2.new(1, 0, 0, 16), truncate = true, Parent = p,
      })
      local function refresh()
        local pend = Mods and Mods.pending()
        if not pend then
          armed.Text = "nothing armed"
          armed.TextColor3 = T.c.textOff
          return
        end
        local e = Mods.registry[pend.place]
        local mins = math.max(0, math.floor((Mods.PENDING_TTL - (os.time() - (pend.at or 0))) / 60))
        armed.Text = string.format("armed: %s  -  expires in %d min",
          e and e.name or tostring(pend.place), mins)
        armed.TextColor3 = T.c.accent
      end
      refresh()
      C.actions(p, {
        { text = "Disarm", callback = function()
            if not (Mods and Mods.pending()) then
              L.Toast.info("Nothing armed", "No game is waiting to auto-start.")
              refresh() return
            end
            Mods.disarm()
            refresh()
            L.Toast.ok("Disarmed", "Nothing will auto-start on your next join.")
          end },
      })
      Hub._refreshArmed = refresh
    end

    -- Only when the module did NOT take its own tabs. A module that owns tabs
    -- has already been built above, and building it again here would put a
    -- second, live copy of every control on a different page -- two switches
    -- for one setting, disagreeing the moment either is touched.
    if mod and mod.build and not owns then
      C.section(p, mod.name)
      L.try("hub.module", mod.build, { page = p, window = win, hub = Hub })
    else
      C.section(p, "this place")
      emptyState(p, "No module for this place",
        "Game support plugs in through L.Hub.register(placeId, name, builder). " ..
        "Nothing here would do anything yet, so nothing is shown. The Player " ..
        "and Movement tabs work in any place and need no module.",
        { text = "Copy this place id", callback = function()
            local ok2 = pcall(function() setclipboard(tostring(game.PlaceId)) end)
            if ok2 then L.Toast.ok("Copied", tostring(game.PlaceId))
            else L.Toast.warn("No clipboard", "This executor has no setclipboard.") end
          end })
    end
  end

  -- ---- PLAYER + MOVEMENT ---------------------------------------------
  -- Both tabs exist before either builder runs. Universal still OWNS walk
  -- speed, fly and noclip -- moving that code would rename their ids and
  -- orphan every saved value -- so it BUILDS them into move.body, which
  -- therefore has to be a live frame first. It runs before L.Move.build, so
  -- its rows land at the top of the Movement page and physics follows.
  local combat = win:tab({ name = "Player", chrome = "torus",
    desc = "Camera, other players and your shortcuts" })
  local move = win:tab({ name = "Movement", chrome = "bolt",
    desc = "Speed, fly, physics, protection and getting out of a server" })
  do
    -- WRAPPED LIKE EVERY OTHER BUILDER. This was the one tab whose builder ran
    -- bare, so a single error inside it did not just lose the Universal page --
    -- it aborted Hub.build where it stood and Movement, Combat, Visuals, AI,
    -- Interface, Activity and About were never created at all. One unguarded
    -- call cost seven tabs.
    L.try("hub.universal", L.Universal.build, combat.body, move.body)
  end
  do
    L.try("hub.move", L.Move.build, move.body)
  end

  -- ---- COMBAT --------------------------------------------------------
  local fight = win:tab({ name = "Combat", chrome = "blade",
    desc = "Aim assistance, hitbox and fling -- all client side" })
  do
    L.try("hub.combat", L.Combat.build, fight.body)
  end

  -- ---- VISUALS -------------------------------------------------------
  local vis = win:tab({ name = "Visuals", chrome = "prism3",
    desc = "Lighting, visibility and frame rate" })
  do
    L.try("hub.visuals", L.Visuals.build, vis.body)
  end

  -- ---- AI ------------------------------------------------------------
  local ai = win:tab({ name = "AI", chrome = "spark",
    desc = "Ask a model, using your own free API key" })
  do
    L.try("hub.ai", L.AI.build, ai.body)
  end

  -- ---- CONFIG --------------------------------------------------------
  win:navSection("System")
  local conf = win:tab({ name = "Config", chrome = "vault",
    desc = "Everything you change, remembered -- and named sets to switch between" })
  do
    L.try("hub.config", Hub.buildConfig, conf.body)
  end

  -- ---- INTERFACE -----------------------------------------------------
  local visuals = win:tab({ name = "Interface", chrome = "cards",
    desc = "How the hub looks and behaves" })
  do
    local p = visuals.body
    C.section(p, "motion")
    C.slider(p, {
      text = "Interface scale", desc = "Auto-fits your resolution on launch",
      min = 0.8, max = 1.6, step = 0.05, default = tonumber(L.Cfg.data.scale) or L.autoScale(), suffix = "x",
      callback = function(v)
        if win.scaleObj then win.scaleObj.Scale = v end
        L.Cfg.set("scale", v)
      end,
    })

    -- This control used to fire a toast and change nothing -- a switch that
    -- reports success while doing nothing is worse than no switch at all. It now
    -- scales every motion token and retunes the springs already on screen.
    C.segmented(p, {
      text = "Animation profile", desc = "How lively the interface feels",
      items = L.Theme.motionOrder, default = L.Theme.motion,
      callback = function(v)
        local ok = L.Theme.setMotion(v)
        if ok then
          local prof = L.Theme.motionProfiles[v]
          L.Toast.info("Motion: " .. v,
            string.format("duration x%.2f   bounce x%.2f", prof.dur, prof.bounce))
        end
      end,
    })

    -- MADE IN HEAVEN MODE. One switch over three settings, and it puts them
    -- back when you turn it off -- see Theme.setHeaven.
    C.toggle(p, {
      text = "Made in Heaven", desc = "Palette, motion and loading screen as one",
      default = L.Theme.heavenOn,
      callback = function(v) L.Theme.setHeaven(v) end,
    })

    -- LOADING SCREEN PICKER.
    --
    -- It takes effect on the NEXT execute, not this one, and the description
    -- says so -- a setting that appears to do nothing when you change it is the
    -- same complaint as a switch that lies, just quieter.
    --
    -- Made in Heaven ships as loose files, so it can genuinely be absent. The
    -- control asks rather than assuming: if the frames are not there the option
    -- refuses with the reason instead of being silently swapped for the other
    -- one at boot.
    C.segmented(p, {
      text = "Loading screen", desc = "Which one plays on the next execute",
      items = L.Loader.SKINS, default = L.Loader.skinName(),
      locked = L.Loader.LOCKED,
      callback = function(v)
        local ok, why = L.Loader.setSkin(v)
        if ok then
          L.Toast.info("Loading screen: " .. v, "Plays the next time you execute")
        else
          L.Toast.warn("Unavailable", tostring(why))
        end
        return ok, why
      end,
    })

    C.segmented(p, {
      text = "Background", desc = "What moves behind the loading screen",
      items = L.Backdrop.STYLES, default = L.Backdrop.styleName(),
      callback = function(v)
        local ok, why = L.Backdrop.setStyle(v)
        if ok then
          L.Toast.info("Background: " .. v, L.Backdrop.STYLE_DESC[v] or "")
        else
          L.Toast.warn("Unavailable", tostring(why))
        end
        return ok, why
      end,
    })

    C.actions(p, {
      { text = "What's new", callback = function()
          if L.Changelog then L.Changelog.show() end
        end },
    })

    C.segmented(p, {
      text = "Density", desc = "Row heights and spacing",
      items = L.Theme.densityOrder, default = L.Theme.density,
      callback = function(v) task.defer(function() L.Theme.setDensity(v) end) end,
    })

    C.slider(p, {
      text = "Background blur", desc = "How far the game recedes",
      min = 0, max = 64, step = 1, default = L.Window.BLUR, suffix = "px",
      callback = function(v) L.Theme.setBlur(v) end,
    })

    C.dropdown(p, {
      text = "Accent", items = L.Theme.names(),
      default = L.Theme.palettes[L.Theme.current].name,
      callback = function(v)
        local key = L.Theme.keyFor(v)
        -- rebuilds the window: the accent is baked into gradients and strokes at
        -- construction, so repainting in place would leave half the UI two-toned
        task.defer(function() L.Theme.set(key) end)
      end,
    })

    -- ---- appearance -----------------------------------------------------
    --
    -- Anything that changes how a control is BUILT needs the window rebuilt to
    -- take, so those say so and offer the reload rather than pretending.
    -- these change how a control is BUILT (radii, whether a layer exists at
    -- all), not what colour it is, so they need the real thing rather than a
    -- repaint
    local function rebuild()
      task.defer(function() L.Theme.rebuild() end)
    end

    C.section(p, "appearance")
    C.slider(p, {
      text = "Corner roundness", desc = "Square through to fully rounded",
      min = 0, max = 2, step = 0.1, default = tonumber(L.Cfg.data.radius) or 1, suffix = "x",
      callback = function(v) L.Cfg.set("radius", v) rebuild() end,
    })
    C.slider(p, {
      text = "Shadow strength", desc = "How far the panel lifts off the game",
      min = 0, max = 1, step = 0.02, default = tonumber(L.Cfg.data.shadow) or 0.34,
      callback = function(v)
        L.Cfg.set("shadow", v)
        if win.shadow then
          win.shadowRest = v
          M.to(win.shadow, "ImageTransparency", v, "fast")
        end
      end,
    })
    C.toggle(p, {
      text = "Film grain", desc = "Dither over the panel -- stops flat areas banding",
      default = L.Cfg.data.grain ~= false,
      callback = function(v) L.Cfg.set("grain", v) rebuild() end,
    })
    C.toggle(p, {
      text = "Hero artwork", desc = "The Saturn behind each page",
      default = L.Cfg.data.heroArt ~= false,
      callback = function(v) L.Cfg.set("heroArt", v) rebuild() end,
    })
    C.toggle(p, {
      text = "Chrome page titles", desc = "Brushed metal headings, or flat text",
      default = L.Cfg.data.chromeTitle ~= false,
      callback = function(v) L.Cfg.set("chromeTitle", v) rebuild() end,
    })

    -- ---- motion ----------------------------------------------------------
    C.section(p, "live motion")
    C.slider(p, {
      text = "Row cascade", desc = "Delay between rows arriving. 0 turns it off",
      min = 0, max = 0.12, step = 0.005,
      default = tonumber(L.Cfg.data.cascade) or 0.035, suffix = "s",
      callback = function(v) L.Cfg.set("cascade", v) win.cascade = v end,
    })
    C.toggle(p, {
      text = "Specular sweep", desc = "A band of light crosses a row on hover",
      default = L.Cfg.data.sweep ~= false,
      callback = function(v) L.Cfg.set("sweep", v) rebuild() end,
    })
    C.toggle(p, {
      text = "Cursor glow", desc = "Light follows the pointer",
      default = L.Cfg.data.spot ~= false,
      callback = function(v) L.Cfg.set("spot", v) rebuild() end,
    })
    C.toggle(p, {
      text = "Rolling numbers", desc = "Figures travel to their new value",
      default = L.Cfg.data.rollNumbers ~= false,
      callback = function(v) L.Cfg.set("rollNumbers", v) end,
    })

    -- ---- notifications ---------------------------------------------------
    C.section(p, "notifications")
    C.slider(p, {
      text = "Toast duration", desc = "How long a notification stays up",
      min = 0.2, max = 60, step = 0.1,
      default = tonumber(L.Cfg.data.toastDur) or 4.5, suffix = "s",
      callback = function(v) L.Cfg.set("toastDur", v) end,
    })
    C.slider(p, {
      text = "Toasts on screen", desc = "The rest queue behind them",
      min = 1, max = 20, step = 1, default = tonumber(L.Cfg.data.toastMax) or 4,
      callback = function(v) L.Cfg.set("toastMax", v) end,
    })

    C.section(p, "behaviour")
    C.toggle(p, {
      text = "Notifications", desc = "Toasts for actions and errors",
      default = L.Cfg.data.notify ~= false,
      callback = function(v) L.Cfg.set("notify", v) end,
    })
    C.toggle(p, {
      text = "Auto-run on join",
      desc = "Every time you enter this place",
      default = L.Cfg.data.autoRun == true,
      callback = function(v) L.Cfg.set("autoRun", v) end,
    })
    C.segmented(p, {
      text = "What the toggle key does",
      desc = "Minimise keeps the pill on screen",
      items = { "Minimise", "Hide" },
      default = (L.Cfg.data.toggleAction == "Hide") and "Hide" or "Minimise",
      callback = function(v) L.Cfg.set("toggleAction", v) end,
    })
    C.keybind(p, {
      text = "Toggle window", desc = "Hide and show the interface",
      default = L.Cfg.keyCode(),
      callback = function(k)
        if k then win.toggleKey = k L.Cfg.set("toggleKey", k.Name) end
      end,
    })
    -- ---- this place ---------------------------------------------------
    --
    -- A per-place layer the user cannot see the state of is not a feature, it is
    -- an unexplained difference between two sessions. This is the window into it.
    C.section(p, "this place")
    local ovr = C.paragraph(p, "")
    local olbl = ovr:FindFirstChildOfClass("TextLabel")
    local function paintOverrides()
      local list = L.Cfg.overrides()
      if #list == 0 then
        olbl.Text = "Nothing is saved specifically for place " .. L.Cfg.placeId
          .. ".\n\nThis game is using your global preferences. Change a per-game "
          .. "setting -- walk speed, jump power, the open tab -- and it will start "
          .. "being remembered here without affecting anywhere else."
        return
      end
      local parts = {}
      for _, o in ipairs(list) do
        local v = o.value
        parts[#parts + 1] = string.format("    %s  =  %s", o.key,
          type(v) == "table" and "(set)" or tostring(v))
      end
      olbl.Text = "Saved for place " .. L.Cfg.placeId .. " only:\n\n"
        .. table.concat(parts, "\n")
        .. "\n\nThese layer over your global preferences and stay with the game, not with you."
    end
    paintOverrides()
    task.spawn(function()
      while L.live() and olbl.Parent do
        L.try("cfg.overrideView", paintOverrides)
        task.wait(1)
      end
    end)

    C.actions(p, {
      { text = "Save now", primary = true, callback = function()
          local ok = L.Cfg.flush()
          if ok then L.Toast.ok("Saved", "Written to " .. L.Cfg.PATH)
          else L.Toast.warn("Not saved", "The executor refused the write.") end
        end },
      { text = "Clear this place", callback = function()
          local n = #L.Cfg.overrides()
          if n == 0 then
            L.Toast.info("Nothing to clear", "This place has no saved settings.")
            return
          end
          L.Cfg.clearPlace()
          L.Cfg.flush()
          paintOverrides()
          L.note("config", "cleared " .. n .. " per-place values")
          L.Toast.ok("Cleared", n .. " per-game setting" .. (n == 1 and "" or "s")
            .. " removed. Global preferences kept.")
        end },
      { text = "Reset everything", callback = function()
          L.Cfg.wipe() L.Cfg.flush()
          paintOverrides()
          L.Toast.warn("Reset", "Global and per-game settings cleared -- reload to apply.")
        end },
    })

    -- Rendered FROM the config module, not typed out again -- and it is
    -- rendered at all now, which it was not: the old loop here built a
    -- `neverParts` table and then never used it, so the policy it described was
    -- invisible in the one tab that exists to explain what gets saved.
    C.paragraph(p, L.Cfg.ARM_POLICY)
    C.paragraph(p, "Settings: " .. L.Cfg.PATH .. "   Per-game: "
      .. L.Cfg.PLACE_DIR .. "/<placeId>.json")

  end

  -- ---- ACTIVITY ------------------------------------------------------
  --
  -- The receipt. Every other tab makes claims; this is where they can be
  -- checked. "hero" is the one chrome tile no tab had claimed -- it has no
  -- animated sequence, so it renders as a still tile, which is what the other
  -- four look like at rest anyway.
  local activity = win:tab({ name = "Activity", chrome = "hero",
    desc = "What the hub actually did" })
  local activityIndex = #win.tabs
  Hub.activityIndex = activityIndex     -- the Overview strip links here
  do
    local p = activity.body
    C.section(p, "health")

    local sum = C.paragraph(p, "")
    local slbl = sum:FindFirstChildOfClass("TextLabel")
    task.spawn(function()
      while L.live() and slbl and slbl.Parent do
        local state, nf, nc = L.health()
        if state == "ok" then
          slbl.Text = "Everything switched on is holding, and nothing has thrown "
            .. "this session.\n\nFeatures are re-checked against the game once a "
            .. "second -- a switch here means the game agrees, not just that you "
            .. "clicked it."
        else
          local parts = {}
          for key, c in pairs(L.contested) do
            parts[#parts + 1] = string.format("    %s  --  %s  (%ds)",
              key, c.why or "not holding", math.floor(os.clock() - c.since))
          end
          table.sort(parts)
          slbl.Text = (nc > 0
              and ("Asked for, but not in effect:\n\n" .. table.concat(parts, "\n"))
              or "Nothing contested.")
            .. string.format("\n\nInternal faults this session: %d", nf)
            .. (nf > 0 and "  --  these are bugs in the hub, not the game." or "")
        end
        task.wait(0.5)
      end
    end)

    C.section(p, "activity log")
    C.logView(p, { height = 300 })

    C.actions(p, {
      { text = "Copy log", primary = true, callback = function()
          local out = {}
          for _, e in ipairs(L.logs) do
            out[#out + 1] = string.format("%s  %-8s %-16s %s%s",
              e.at, e.kind, e.src, e.text, e.n > 1 and ("  x" .. e.n) or "")
          end
          if #out == 0 then
            L.Toast.info("Nothing to copy", "The log is empty.") return
          end
          local ok = pcall(function() setclipboard(table.concat(out, "\n")) end)
          if ok then L.Toast.ok("Copied", #out .. " entries on the clipboard.")
          else L.Toast.warn("No clipboard", "This executor has no setclipboard.") end
        end },
      { text = "Clear log", callback = function()
          -- Faults clear with it: the indicator is meant to mean "since you last
          -- looked". Contested state is deliberately NOT cleared -- it is live,
          -- and anything still wrong re-reports within a second, which is the
          -- honest outcome rather than a wiped slate that looks healthy.
          L.logs, L.faults, L._faultOrder = {}, {}, {}
          L.note("log", "cleared by user")
          L.Toast.ok("Cleared", "Log and faults reset. Anything still failing reports again within a second.")
        end },
    })
  end

  -- The health chip in the header is only useful if it goes somewhere.
  win.onHealth = function() win:select(activityIndex) end

  -- ---- ABOUT ---------------------------------------------------------
  local about = win:tab({ name = "About", chrome = "pyramid",
    desc = "What this is built on" })
  do
    local p = about.body
    C.section(p, "lumen " .. L.VERSION)
    C.section(p, "diagnostics")
    local diag = C.paragraph(p, "")
    local lbl = diag:FindFirstChildOfClass("TextLabel")
    task.spawn(function()
      while L.live() and lbl.Parent do
        local st = M.stats()
        lbl.Text = string.format(
          "active springs   %d\nfaults           %d\nviewport         %d x %d\nscale            %.2f",
          st.active, #L._faultOrder, L.viewport().X, L.viewport().Y,
          win.scaleObj and win.scaleObj.Scale or 1)
        task.wait(0.25)
      end
    end)
  end

  -- RESTORE THE TAB YOU LEFT ON. Window:select has always WRITTEN this on every
  do
    local want = tonumber(L.Cfg and L.Cfg.data.tab) or 1
    want = math.clamp(math.floor(want), 1, #win.tabs)
    if want ~= win.active then win:select(want, true) end
  end

  return win
end

-- ---------------------------------------------------------------- launch

-- Warms every texture the window is about to use. This is the work that makes a
-- longer loading screen honest rather than padded: without it the icons, chrome
-- tiles and game art decode lazily on first paint, which is a stutter the moment
-- the window opens. Doing it here moves that cost to the one place the user is
-- already waiting.
function Hub.preload(report)
  local A = L.A
  local ids = {}
  for _, id in pairs(A.img or {}) do ids[#ids + 1] = id end
  for _, id in pairs(A.icons or {}) do ids[#ids + 1] = id end

  local getAsset = rawget(getgenv(), "getcustomasset") or rawget(getgenv(), "getsynasset")
  if type(getAsset) == "function" then
    for _, key in ipairs({ "mm2", "bitcoin", "restaurant",
                           "planet", "chicken", "business" }) do
      local path = "lumen_fx/games/" .. key .. ".png"
      local ok, present = pcall(isfile, path)
      if ok and present then
        local gok, id = pcall(getAsset, path)
        if gok then ids[#ids + 1] = id end
      end
    end
    -- The chrome page titles: the FIRST frame of each only. Warming all 216
    -- added ~14 s to the loading screen for no gain -- the sequences are manual
    -- now, so the other 35 frames of a title decode while it is already on
    -- screen and animating, which is exactly when there is time for it.
    for _, p in ipairs({ "ovw", "frm", "unv", "itf", "act", "abt" }) do
      local path = "lumen_fx/titles/" .. p .. "001.png"
      local ok, present = pcall(isfile, path)
      if ok and present then
        local gok, id = pcall(getAsset, path)
        if gok then ids[#ids + 1] = id end
      end
    end
  end

  -- PreloadAsync wants Instances, so give it throwaway labels in a hidden gui
  local holder = Instance.new("ScreenGui")
  holder.Name = "LumenPreload"
  holder.Enabled = false
  holder.Parent = L.host()
  local labels = {}
  for _, id in ipairs(ids) do
    local im = Instance.new("ImageLabel")
    im.Image = id
    im.ImageTransparency = 1
    im.Parent = holder
    labels[#labels + 1] = im
  end

  -- IN BATCHES, NOT ONE CALL. PreloadAsync blocks until everything in the list
  -- is resolved, so handing it the whole set stalls the loading screen mid-
  -- animation. Twelve at a time with a frame between keeps it moving.
  local CP = game:GetService("ContentProvider")
  for i = 1, #labels, 12 do
    local batch = {}
    for k = i, math.min(i + 11, #labels) do batch[#batch + 1] = labels[k] end
    L.try("hub.preload", function() CP:PreloadAsync(batch) end)
    L.RunService.Heartbeat:Wait()
  end
  if report then report(#labels) end
  task.delay(1, function() pcall(function() holder:Destroy() end) end)
  return #labels
end

-- ---------------------------------------------------------------- config tab
--
-- WHAT THIS PAGE IS FOR. Saving already happens by itself -- every control in
-- the hub writes its value the moment you change it -- so this page is not a
-- save button pretending to be necessary. It is the place you can SEE what is
-- being remembered, and keep more than one set of it.
--
-- Profiles are the reason it earns a tab. One set of settings for a fighting
-- game and another for a farming one is a real thing to want, and until now the
-- only way to get it was to re-tune everything by hand on arrival.
function Hub.buildConfig(p)
  C.ctx("config")
  C.section(p, "state")

  local state = C.output(p, { maxHeight = 92 })

  local function refreshCount()
    local n = L.Cfg.featTotal and L.Cfg.featTotal() or 0
    local prof = L.Cfg.data.profile or "default"
    local txt = string.format(
      "%d settings remembered\nactive set: %s\nsaves itself the moment you change anything",
      n, prof)
    if state and state.set then state:set(txt) end
    return string.format("%d settings, set \"%s\"", n, prof)
  end
  refreshCount()
  Hub._refreshConfigCount = refreshCount

  C.actions(p, {
    { text = "Save now", primary = true, callback = function()
        L.Cfg.flush()
        refreshCount()
        L.Toast.ok("Saved", refreshCount())
      end },
    { text = "Forget all settings", callback = function()
        L.Cfg.wipeFeatures()
        refreshCount()
        L.Toast.warn("Cleared",
          "Every remembered control value is gone. Reload to see defaults.")
      end },
  })

  -- ---- profiles -------------------------------------------------------
  C.section(p, "profiles")

  local listHolder = mk("Frame", {
    Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y,
    BackgroundTransparency = 1, Name = "Profiles", Parent = p,
  })
  L.list(T.gap.sm, Enum.FillDirection.Vertical, listHolder)

  local nameBox
  local function redrawProfiles()
    for _, c in ipairs(listHolder:GetChildren()) do
      if c:IsA("GuiObject") then c:Destroy() end
    end
    local names = L.Cfg.profiles()
    if #names == 0 then
      C.paragraph(listHolder,
        "No saved sets yet. Tune the hub how you like it, type a name below " ..
        "and press Save as.")
      return
    end
    local active = L.Cfg.data.profile
    for _, nm in ipairs(names) do
      local isActive = (nm == active)
      C.actions(listHolder, {
        { text = (isActive and "● " or "") .. nm, primary = isActive,
          callback = function()
            local ok, why = L.Cfg.loadProfile(nm)
            if not ok then L.Toast.warn("Profile", tostring(why)) return end
            refreshCount()
            L.Toast.ok("Loaded \"" .. nm .. "\"", "Rebuilding with those settings.")
            task.delay(0.4, function() L.Theme.rebuild() end)
          end },
        { text = "Overwrite", callback = function()
            local ok, why = L.Cfg.saveProfile(nm)
            if ok then L.Toast.ok("Saved", "\"" .. nm .. "\" updated.")
            else L.Toast.warn("Profile", tostring(why)) end
            redrawProfiles()
          end },
        { text = "Delete", callback = function()
            L.Cfg.deleteProfile(nm)
            L.Toast.info("Deleted", "\"" .. nm .. "\" is gone.")
            redrawProfiles()
          end },
      })
    end
  end

  nameBox = C.input(p, {
    text = "New set name", desc = "Letters, numbers, spaces, - and _",
    placeholder = "combat",
  })
  C.actions(p, {
    { text = "Save as", primary = true, callback = function()
        local nm = nameBox and nameBox.get and nameBox:get() or ""
        local ok, why = L.Cfg.saveProfile(nm)
        if not ok then L.Toast.warn("Save as", tostring(why)) return end
        L.Toast.ok("Saved \"" .. nm .. "\"", "Switch to it any time from this page.")
        redrawProfiles()
        refreshCount()
      end },
    { text = "Refresh list", callback = redrawProfiles },
  })

  redrawProfiles()

  -- A PAGE BUILT ONCE GOES STALE. Both readouts here describe state that
  -- changes while you are somewhere else -- you save a set from this page,
  -- switch to Combat, come back, and the list still says there are none. Redraw
  -- when the page becomes visible rather than making the user find Refresh.
  task.spawn(function()
    local wasVisible = true
    while L.live() and p.Parent do
      local vis = p.Visible
      if vis and not wasVisible then
        L.try("config.refresh", function()
          refreshCount()
          redrawProfiles()
        end)
      end
      wasVisible = vis
      task.wait(0.4)
    end
  end)

  -- ---- scope ----------------------------------------------------------
  C.section(p, "scope")

  C.paragraph(p,
    "Settings are global: what you change follows you into every game. Walk " ..
    "speed, jump power, the open tab and auto-run stay per place, because " ..
    "those genuinely differ game to game.")

  local overrides = L.Cfg.overrides()
  if #overrides > 0 then
    local lines = {}
    for _, o in ipairs(overrides) do
      lines[#lines + 1] = o.key .. " = " .. tostring(o.value)
    end
    C.paragraph(p, "This place overrides: " .. table.concat(lines, ", "))
  end

  C.actions(p, {
    { text = "Clear this place's overrides", callback = function()
        L.Cfg.clearPlace()
        L.Toast.info("Cleared", "This game no longer overrides anything.")
      end },
  })
end

function Hub.launch()
  if not L.live() then return end
  local loader = L.Loader.new({
    title = "LUMEN",
    subtitle = "spring-driven interface",
    status = "starting",
    stages = 6,
  })
  Hub._loader = loader          -- exposed so the sequence can be inspected

  -- Boot is deliberately paced across several seconds. Every pause is also a
  -- generation boundary: an unload during the loader must stop here, otherwise
  -- the retired task can build a fresh 10k-node ScreenGui after teardown has
  -- already emptied its ownership lists.
  local function waitLive(seconds)
    task.wait(seconds)
    return L.live()
  end

  -- The caller already owns a spawned, protected thread. Keep the sequence in
  -- that thread so errors reach its pcall and teardown cannot lose track of a
  -- second unprotected launcher.
  do
    if not L.live() then return end
    -- Paced so each stage is readable. The old sequence ran six lines in about a
    -- second, which is not a loading screen, it is a flicker.
    if not waitLive(0.65) then return end
    loader:stage("checking executor")
    local hasAssets = L.A.hasImages()
    if not waitLive(0.75) then return end

    -- ---- first run on a machine that has never seen this ----------------
    --
    -- The visuals are 65 MB of frame sequences that cannot travel inside the
    -- script, and a sequence resolves through getcustomasset at BUILD time --
    -- so anything arriving after the window is constructed does not show up
    -- until the next run. Downloading quietly in the background therefore ends
    -- with a finished hub and a message asking the user to run it again, which
    -- is a strange thing to do to somebody on their first launch.
    --
    -- Instead the wait is held here, where a wait already exists and is
    -- explained, and the hub restarts itself the moment the packs land.
    if L.Fetch and not L.Fetch.canDownload() then
      -- An executor with no request/http_request cannot fetch anything. Saying
      -- so once beats a progress line counting down megabytes that will never
      -- move: the hub runs on its embedded sprites and drawn fallbacks, and that
      -- is a legitimate state, not a failure.
      L.note("fetch", "no http on this executor -- running on built-in visuals")
    elseif L.Fetch then
      -- CORE ONLY. Everything else is scenery and downloads after the hub is up.
      local todo, bytes = L.Fetch.pending("core")
      if #todo > 0 then
        -- `say`, not `stage`: the percentage is sized for the six boot steps and
        -- advancing it here would run the counter to 100% before the interface
        -- has been built. The flashing line carries the download's own progress.
        loader:say("fetching icons")
        loader:flash(string.format("first run -- %.1f MB", bytes / 1048576))

        local ok = L.Fetch.runBlocking(function(i, n, pack, left)
          if not L.live() then return end
          loader:say(string.format("pack %d of %d", i, n))
          loader:flash(string.format("%s  --  %.1f MB to go",
            pack.name, math.max(left, 0) / 1048576))
        end, "core")
        if not L.live() then return end

        loader:flash(nil)
        local failed = #(L.Fetch.state.failed or {})
        if ok and failed == 0 then
          loader:say("restarting")
          loader:flash("visuals installed -- restarting")
          if not waitLive(0.9) then return end
          local re, why = L.Fetch.reexec()
          if re then return end          -- this boot is over; the next one owns the screen
          -- could not restart from anywhere: carry on with what we have and be
          -- honest about it rather than pretending the visuals are live
          loader:flash(nil)
          L.note("fetch", "installed, but " .. tostring(why))
        elseif failed > 0 then
          loader:say("some visuals failed")
          -- The failure path is exactly where the restart hint matters most, and
          -- it was the only path that withheld it.
          loader:flash("running on fallbacks -- run again to retry")
          L.note("fetch", failed .. " pack(s) failed -- running on fallbacks")
          if not waitLive(0.6) then return end
        end
      end

      -- Scenery, on its own thread, after the interface exists.
      L.Fetch.runLater("extra")
    end

    if not L.live() then return end
    loader:stage("warming textures")
    local warmed = Hub.preload()
    if not waitLive(0.55) then return end

    loader:stage("resolving place")
    local mod = Hub.moduleFor()
    -- who owns this place, resolved off the critical path so the first press of
    -- Join already knows whether a teleport is even permitted
    if L.Modules and L.Modules.warmHere then L.Modules.warmHere() end
    local pend = L.Modules and L.Modules.pending()
    if pend and pend.place == game.PlaceId and mod then
      loader:say("arrived for " .. mod.name)
    end
    if not waitLive(0.8) then return end

    loader:stage("building interface")
    local win = Hub.build()
    if not L.live() then return end
    win.root.Visible = false
    if not waitLive(0.85) then return end

    loader:stage(mod and ("module: " .. mod.name) or "no place module")
    if not waitLive(0.8) then return end

    loader:say(string.format("%d textures  -  %s",
      warmed, hasAssets and "assets ok" or "assets missing"))
    if not waitLive(0.6) then return end
    loader:stage("ready")
    if not waitLive(0.45) then return end

    loader:finish(function()
      if not L.live() or not win.gui.Parent then return end
      win:show()
      if L.Cfg.data.notify ~= false then
        task.delay(0.30, function()
          if not L.live() then return end
          L.Toast.ok("LUMEN ready", mod and ("Module: " .. mod.name)
            or "No module for this place yet.")
        end)

    -- WHAT CAME BACK ON, SAID OUT LOUD.
    --
    -- The hub restores armed features again (see Cfg.ARM_HOLD for the short
    -- list it still holds back). That is only defensible if it is announced:
    -- a feature switching itself on silently is the exact bug this project
    -- spent a session chasing, and doing it deliberately does not make the
    -- surprise any smaller. Naming them, with one click to undo, is the
    -- difference between a restore and a trap.
    task.delay(0.9, function()
      if not L.live() then return end
      local Cfg = L.Cfg
      local n = (Cfg and Cfg.restoredCount and Cfg.restoredCount()) or 0
      if n <= 0 then return end
      local names = Cfg.restoredNames(3)
      local tail = (n > #names) and (" +" .. (n - #names) .. " more") or ""
      L.Toast.push({
        kind = "info", duration = 9,
        title = "Restored " .. n .. " setting" .. (n == 1 and "" or "s"),
        body = table.concat(names, ", ") .. tail .. "  --  click to switch them back off",
        onAction = function()
          local undone = Cfg.revertRestored()
          L.Toast.ok("Reverted", undone .. " switched back off")
        end,
      })
    end)
      end
      -- Arriving from a Join press, or with per-place autorun on, starts the
      -- game script. It runs AFTER the window is up so that if the script errors
      -- there is a hub on screen to say so -- a failed autofarm that leaves a
      -- blank screen is indistinguishable from a failed injection.
      task.delay(0.9, function()
        if not L.live() then return end
        if L.Modules and L.Modules.autoRun then L.try("hub.autorun", L.Modules.autoRun) end
      end)
      -- once per version, after the window has arrived
      if L.Changelog then L.try("hub.changelog", L.Changelog.maybeShow) end
    end)
  end
end

if not getgenv().__LUMEN_NOBOOT then
  task.spawn(function()
    local ok, err = pcall(Hub.launch)
    if not ok and L.live() then
      L.fault("launch", err)
      warn("[LUMEN] launch failed: " .. tostring(err))
    end
  end)
end

end
do -- ==== lm_18_modules.lua ====
-- LUMEN :: MODULES
-- Per-game automation entries, registered into the Farming tab by place id.

local L = getgenv().LUMEN
local T, A, C = L.T, L.A, L.C

local Mod = {}
L.Modules = Mod

-- placeId -> the script that automates it. `icon` is the basename under
-- lumen_fx/games; `travel` means the id resolved against Roblox's universe
-- endpoint. Unresolved ids still load in-game but stay out of the carousel.
Mod.order = {
  142823291, 2629642516, 77843161404023, 121125129560252, 137233438285284,
  118055952211055, 112032463947981, 88503041003371, 131906518201863,
  136020512003847, 125927821145950,
}

-- `universe` and `creator` are baked rather than looked up: they never change,
-- and knowing the creator BEFORE trying to travel is what stops Roblox throwing
-- its own "Error Code: 773" modal in the user's face for a teleport that was
-- never going to be allowed. Pulled from Roblox's public games API by
-- fetch_games.py; only the place you are currently standing in needs a lookup.
Mod.registry = {
  -- MURDER MYSTERY 2 IS NOT LAUNCHED FROM HERE. It is compiled into the hub
  -- (lm_32_mm2), so it has no file and nothing to fetch. It sits in the registry
  -- only so the carousel can show it, and `builtin` is what stops the
  -- registration loop below from overwriting the six-tab module with a launcher
  -- card for a file that does not exist.
  [142823291]       = { name = "Murder Mystery 2", builtin = true,
                        icon = "mm2",        travel = true,
                        universe = 66654135,   creator = 1848960,   by = "Nikilis",
                        note = "Roles, fling, silent aim, coins and traps" },
  [2629642516]      = { name = "Bitcoin Miner",    file = "BitcoinMinerHub.lua",
                        icon = "bitcoin",    travel = true,
                        universe = 943733974,  creator = 3732983,   by = "polandgamebuilders",
                        note = "Smart auto-exchange at the best rate" },
  [77843161404023]  = { name = "Run a Restaurant", file = "RestaurantHub.lua",
                        icon = "restaurant", travel = true,
                        universe = 9970645639, creator = 75550158,  by = "Burnt Toast Labs!",
                        note = "Auto-cook, serve and upgrade" },
  [121125129560252] = { name = "Mine a Planet",    file = "MinePlanetHub.lua",
                        icon = "planet",     travel = true,
                        universe = 10406668651, creator = 627287172, by = "Skydog Games",
                        note = "Auto-mine and upgrade" },
  [137233438285284] = { name = "Chicken Farm",     file = "Coop.obf.lua",
                        icon = "chicken",    travel = true,
                        universe = 10209534490, creator = 34492682, by = "Skandi Studios",
                        note = "COOP -- auto collect, merge, rebirth" },
  [118055952211055] = { name = "Hack a Business",  file = "Breach.lua",
                        icon = "business",   travel = true,
                        universe = 10066929248, creator = 287664347, by = "Matthew 7:7",
                        note = "BREACH -- auto hack and sell" },
  [112032463947981] = { name = "Limit Breaker",    file = "LimitBreakerHub.lua",
                        icon = "breaker",    travel = true,
                        universe = 8971680970, creator = 11925281,  by = "Oxa Game Inc",
                        note = "Calorie-gated auto-train" },
  [88503041003371]  = { name = "Fast Lifting Sim", file = "LiftHub.lua",
                        icon = "lifting",    travel = true,
                        universe = 10070351442, creator = 36090039, by = "InfCube Official Community",
                        note = "Auto-train via the trainer remote" },
  [131906518201863] = { name = "Own a Cafe",       file = "BrewHub.lua",
                        icon = "cafe",       travel = true,
                        universe = 8935993972, creator = 1053923615, by = "Espresso Espresso",
                        note = "Auto-brew and staff" },
  [136020512003847] = { name = "SDBR Convoy",      file = "Convoy.lua",
                        icon = "convoy",     travel = true,
                        universe = 9855761734, creator = 177149320, by = "San Diego Border Community",
                        note = "Semi-legit convoy driving" },
  -- place id never resolved against the universe endpoint, so no travel entry
  [125927821145950] = { name = "Mine a Mountain",  file = "Vein.lua",
                        icon = "mountain",   travel = false,
                        note = "Auto-mine, value-per-kg sorting" },
}

-- Carousel entries, in declared order, for places we can actually teleport to.
function Mod.list()
  local out = {}
  for _, id in ipairs(Mod.order) do
    local e = Mod.registry[id]
    if e and e.travel then
      out[#out + 1] = { key = e.icon, name = e.name, place = id, entry = e }
    end
  end
  return out
end

Mod._ran = {}

-- ---------------------------------------------------------------- arming
--
-- A teleport destroys the executor's script context, so nothing survives it by
-- itself. queue_on_teleport hands the executor a source string to run in the
-- NEXT place -- it is the only hook that crosses the boundary.
--
-- THE DESTINATION IS NOT IN THE PAYLOAD, AND THAT IS THE WHOLE DESIGN. It used
-- to be, and the queue turned out to be a QUEUE: every press of Join added
-- another boot script, none of them replaceable and none removable, because no
-- executor offers an unqueue. Arming three games meant three boots racing on the
-- next join, each loading the hub, and the winner was whichever the scheduler
-- happened to finish last -- measured live, landing with the marker set to a
-- game chosen two tests earlier.
--
-- So the queued script is now a CONSTANT: load the hub, nothing else. The intent
-- lives in a file, which is idempotent -- the newest arm overwrites the previous
-- one, so however many boots are queued they all read the same answer, and the
-- answer is the last thing the user actually asked for.
Mod.PENDING = "_lumen_pending.json"
Mod.PENDING_TTL = 3600      -- an armed game is stale after an hour

-- Guarded so duplicate queued boots do not each rebuild the hub, and waits on
-- signals rather than a guessed duration -- a fixed sleep is a bet on how fast
-- the destination loads, and losing it means readfile runs before the executor
-- has a workspace, an intermittent failure that only shows up on a slow join.
local BOOT = [[
if getgenv().__LUMEN_ARRIVING then return end
getgenv().__LUMEN_ARRIVING = true
pcall(function()
  local Players = game:GetService("Players")
  if not game:IsLoaded() then game.Loaded:Wait() end
  local t0 = os.clock()
  while not Players.LocalPlayer and os.clock() - t0 < 20 do task.wait(0.2) end
  task.wait(0.5)
end)
getgenv().__LUMEN_ARRIVING = nil
if not (isfile and isfile("Lumen.lua")) then
  warn("[LUMEN] arrived but Lumen.lua is not in the workspace")
  return
end
local fn, err = loadstring(readfile("Lumen.lua"))
if not fn then warn("[LUMEN] arrival compile failed: " .. tostring(err)) return end
local ranOk, runErr = pcall(fn)
if not ranOk then warn("[LUMEN] arrival failed: " .. tostring(runErr)) end
]]

-- Resolved per call, not cached at load. Some executors install their queue hook
-- after the first script runs, and a nil captured at load time would never
-- recover -- Join would silently stop arming the arrival for the whole session.
local function queueFn()
  local g = getgenv()
  local f = rawget(g, "queue_on_teleport") or rawget(g, "queueonteleport")
  return type(f) == "function" and f or nil
end

function Mod.canQueue() return queueFn() ~= nil end

-- What are we currently armed for? nil if nothing, or if it went stale.
function Mod.pending()
  local ok, raw = pcall(readfile, Mod.PENDING)
  if not ok or type(raw) ~= "string" then return nil end
  local decoded, data = pcall(function() return L.Http:JSONDecode(raw) end)
  if not decoded or type(data) ~= "table" or not data.place then return nil end
  if type(data.at) == "number" and os.time() - data.at > Mod.PENDING_TTL then
    Mod.disarm()
    return nil
  end
  return data
end

function Mod.disarm()
  pcall(delfile, Mod.PENDING)
end

function Mod.queueArrival(placeId)
  local QUEUE = queueFn()
  if not QUEUE then return false, "this executor has no queue_on_teleport" end
  local wrote = pcall(writefile, Mod.PENDING,
    L.Http:JSONEncode({ place = placeId, at = os.time() }))
  if not wrote then return false, "could not write " .. Mod.PENDING end
  local ok, err = pcall(QUEUE, BOOT)
  if not ok then return false, tostring(err) end
  return true
end

function Mod.gameLink(placeId)
  return "https://www.roblox.com/games/" .. tostring(placeId)
end

-- ---------------------------------------------------------------- pre-flight
--
-- ERROR CODE 773, "Attempted to teleport to a place that is restricted", is the
-- client-side face of the same block: Roblox only lets a client teleport between
-- games owned by the same creator. Every game in the registry has a different
-- owner, so from anywhere else the answer is known in advance -- and asking
-- anyway makes Roblox throw a modal the user has to dismiss before our own
-- explanation is even visible. So we ask ourselves first and only teleport when
-- it can actually work.
Mod.HERE = "_lumen_here.json"       -- cached creator of the place we are in

local function httpGet(url)
  local req = rawget(getgenv(), "request") or rawget(getgenv(), "http_request")
  if type(req) ~= "function" then return nil, "no http" end
  local ok, res = pcall(req, { Url = url, Method = "GET" })
  if not ok or type(res) ~= "table" then return nil, "request failed" end
  if res.StatusCode and res.StatusCode >= 300 then return nil, "http " .. res.StatusCode end
  local decoded, data = pcall(function() return L.Http:JSONDecode(res.Body) end)
  if not decoded then return nil, "bad json" end
  return data
end

-- Creator of the current place. One network round trip per place, then cached,
-- because a place never changes hands mid-session.
function Mod.here()
  if Mod._here and Mod._here.place == game.PlaceId then return Mod._here end

  local ok, raw = pcall(readfile, Mod.HERE)
  if ok and type(raw) == "string" then
    local decoded, data = pcall(function() return L.Http:JSONDecode(raw) end)
    if decoded and type(data) == "table" and data.place == game.PlaceId and data.creator then
      Mod._here = data
      return data
    end
  end

  local uni = httpGet("https://apis.roblox.com/universes/v1/places/"
    .. game.PlaceId .. "/universe")
  if not (uni and uni.universeId) then return nil end
  local info = httpGet("https://games.roblox.com/v1/games?universeIds=" .. uni.universeId)
  local first = info and info.data and info.data[1]
  if not (first and first.creator) then return nil end

  local data = { place = game.PlaceId, universe = uni.universeId,
                 creator = first.creator.id, by = first.creator.name }
  Mod._here = data
  pcall(writefile, Mod.HERE, L.Http:JSONEncode(data))
  return data
end

-- true  -> Roblox should allow it
-- false -> Roblox will refuse it, do not ask
-- nil   -> cannot tell (no http, offline); try anyway and handle the refusal
function Mod.canTravelTo(placeId)
  local dest = Mod.registry[placeId]
  if not (dest and dest.creator) then return nil end
  -- resolved once, through here(), so the place-match guard applies to every
  -- comparison rather than only to the slow path
  local here = Mod.here()
  if not here then return nil end
  if here.place == placeId then return true, here, dest end
  if dest.universe and here.universe == dest.universe then return true, here, dest end
  return here.creator == dest.creator, here, dest
end

-- Resolved in the background at launch so the first press of Join is instant.
function Mod.warmHere()
  task.spawn(function() L.try("modules.here", Mod.here) end)
end

-- Teleport, having first queued what should happen on arrival.
--
-- THE PLATFORM USUALLY REFUSES THIS, AND IT REFUSES IT QUIETLY. Roblox blocks
-- client-initiated teleports into a universe owned by a different creator, and
-- TeleportService:Teleport does not throw when that happens -- it returns
-- normally and fires TeleportInitFailed a moment later:
--
--   TeleportResult.Unauthorized
--   "Cannot teleport from this universe to a universe owned by a different creator"
--
-- Measured in-game, not inferred. So a pcall around Teleport proves nothing, and
-- reporting success the instant it did not error is how the Join button came to
-- claim it had travelled while the client had not moved. The result has to be
-- waited for on the signal.
--
-- `report(ok, reason, link)` is called once the outcome is actually known.
function Mod.travelTo(placeId, name, report)
  local TS = game:GetService("TeleportService")
  local queued, qwhy = Mod.queueArrival(placeId)
  if not queued then
    L.log("refused", "travel", "no autorun after teleport -- " .. tostring(qwhy))
  end

  local settled = false
  local conn
  -- `code` says WHY, so the caller can word it differently: "policy" is Roblox's
  -- same-creator rule and is not a malfunction, the rest are.
  local function settle(ok, reason, code)
    if settled then return end
    settled = true
    if conn then pcall(function() conn:Disconnect() end) end
    if not ok then
      L.log("refused", "travel", string.format("%s -- %s", name or placeId, reason))
    end
    if report then
      L.try("travel.report", report, ok, reason, Mod.gameLink(placeId), code)
    end
  end

  pcall(function()
    conn = TS.TeleportInitFailed:Connect(function(plr, result, msg)
      if plr ~= L.LP then return end
      local why = tostring((msg and msg ~= "") and msg or result)
      -- name the actual cause, because Roblox's own wording ("restricted",
      -- "different creator") sends people looking at the destination when the
      -- switch that refused them belongs to the game they are standing in
      if why:lower():find("creator") or why:lower():find("restrict") then
        why = why .. "  --  this game blocks third-party teleports"
      end
      settle(false, why, "refused")
    end)
  end)

  -- ALWAYS ATTEMPT. The pre-flight that used to live here refused any teleport
  -- to a different creator's game, and that rule was simply wrong -- it was
  -- blocking teleports that would have worked.
  --
  -- What actually governs this is a setting on the game you are LEAVING, not the
  -- one you are going to: Game Settings > Security > "Allow Third Party
  -- Teleports". With it on, a client teleport to another universe succeeds. With
  -- it off, Roblox refuses with error 773 no matter who owns the destination.
  -- Since it belongs to the source place and cannot be read from the client,
  -- there is nothing to check in advance -- so we try, and report honestly.
  --
  -- The old bypasses for this are in a repository literally named
  -- "roblox-patched-vulnerabilities". There is no client-side trick left.

  local ok, err = pcall(function() TS:Teleport(placeId, L.LP) end)
  if not ok then settle(false, tostring(err), "threw") return false, tostring(err), queued end

  L.note("travel", string.format("teleport requested: %s (%d)%s", name or "?", placeId,
    queued and ", arrival queued" or ""))

  -- If the teleport is going to happen the client is gone long before this; if
  -- it was refused the signal has already fired. Either way, six seconds with no
  -- refusal and no departure means it silently did nothing.
  task.delay(6, function()
    settle(false, "the teleport did not start and Roblox gave no reason", "silent")
  end)
  return true, nil, queued
end

-- Called by the launcher once the hub is up. Runs the module for this place if
-- we arrived here on purpose, or if the user asked for it per-place.
function Mod.autoRun()
  local pend = Mod.pending()
  local wanted = pend ~= nil and pend.place == game.PlaceId

  local entry = Mod.forPlace()
  if not entry then
    -- An arm for THIS place is spent even if there is nothing to run, otherwise
    -- it sits there and fires on some unrelated visit later.
    if wanted then Mod.disarm() end
    return false, "no module for this place"
  end

  if not wanted and not Mod.always() and not (L.Cfg and L.Cfg.data.autoRun == true) then
    -- armed for somewhere else: leave it alone, that is the point of arming
    return false, "not requested"
  end
  if wanted then Mod.disarm() end          -- one arrival, one launch

  local ok, why = Mod.launch(entry)
  if ok then
    L.note("autorun", entry.name .. " started on arrival")
    if L.Toast then L.Toast.ok("Auto-farm running", entry.name .. " started.") end
  else
    L.log("refused", "autorun", tostring(why))
    if L.Toast then L.Toast.warn("Auto-farm failed", tostring(why)) end
  end
  return ok, why
end

function Mod.forPlace(placeId)
  return Mod.registry[placeId or game.PlaceId]
end

-- ---------------------------------------------------------------- always-run
-- "Start this game every time I enter it", settable from anywhere rather than
-- only from inside the game.

function Mod.always(placeId)
  local set = L.Cfg and L.Cfg.data.autoGames
  return type(set) == "table" and set[tostring(placeId or game.PlaceId)] == true
end

function Mod.setAlways(placeId, on)
  if not L.Cfg then return false, "no config" end
  local set = {}
  local cur = L.Cfg.data.autoGames
  if type(cur) == "table" then
    -- copied, not mutated in place: Cfg.set is what marks the file dirty, and a
    -- table edited behind its back would never be written
    for k, v in pairs(cur) do
      -- drop ids we no longer have a module for, so the list cannot rot
      if v == true and Mod.registry[tonumber(k)] then set[k] = true end
    end
  end
  set[tostring(placeId)] = on and true or nil
  L.Cfg.set("autoGames", set)
  return true
end

function Mod.exists(entry)
  if not entry or not entry.file then return false end
  local ok, present = pcall(isfile, entry.file)
  return ok and present == true
end

function Mod.sizeKB(entry)
  local ok, raw = pcall(readfile, entry.file)
  if not ok or type(raw) ~= "string" then return 0 end
  return math.floor(#raw / 1024)
end

-- A cheap fingerprint of "has anything appeared". Deliberately generic: these
-- scripts are other people's, several are obfuscated, and none of them agree on
-- a global to look for -- but every one of them either draws a panel or leaves
-- something in getgenv.
local function surface()
  local guis = 0
  pcall(function()
    local hidden = rawget(getgenv(), "gethui")
    local roots = { L.LP and L.LP:FindFirstChild("PlayerGui") }
    if type(hidden) == "function" then roots[#roots + 1] = hidden() end
    pcall(function() roots[#roots + 1] = game:GetService("CoreGui") end)
    for _, root in ipairs(roots) do
      if root then
        for _, c in ipairs(root:GetChildren()) do
          if c:IsA("ScreenGui") or c:IsA("GuiBase2d") then guis = guis + 1 end
        end
      end
    end
  end)
  local globals = 0
  pcall(function() for _ in pairs(getgenv()) do globals = globals + 1 end end)
  return { guis = guis, globals = globals }
end

-- Runs the script. Errors are surfaced rather than swallowed -- a launcher that
-- silently does nothing is worse than one that says what broke.
function Mod.launch(entry)
  if not Mod.exists(entry) then
    return false, "file not found: " .. tostring(entry and entry.file)
  end
  local ok, src = pcall(readfile, entry.file)
  if not ok or type(src) ~= "string" or #src < 32 then
    return false, "could not read " .. entry.file
  end
  local fn, compileErr = loadstring(src)
  if not fn then return false, "compile failed: " .. tostring(compileErr) end

  -- "It did not error" is not "it started". A script whose main loop dies on its
  -- first yield returns cleanly and leaves nothing behind, and reporting that as
  -- Loaded is how a dead farm looks identical to a working one.
  local before = surface()
  local ranOk, runErr = pcall(fn)
  if not ranOk then return false, "error: " .. tostring(runErr) end
  Mod._ran[entry.file] = true

  task.delay(3, function()
    local after = surface()
    if after.guis > before.guis or after.globals > before.globals then
      L.note("module", string.format("%s is up (+%d panels, +%d globals)",
        entry.name, after.guis - before.guis, after.globals - before.globals))
      return
    end
    L.log("refused", "module", entry.name ..
      " ran without error but put nothing on screen and set no globals")
    if L.Toast then
      L.Toast.warn(entry.name .. " may not have started",
        "It ran without erroring but left no trace. Check the executor console.")
    end
  end)
  return true, entry.name .. " loaded"
end

-- ---------------------------------------------------------------- ui

function Mod.build(page, entry)
  local present = Mod.exists(entry)

  local card = A.surface({
    Parent = page, elev = 1, radius = T.r.md, sheen = true,
    Size = UDim2.new(1, 0, 0, 78), Name = "Module",
  })
  A.chrome(card, "torus", 34, { Position = UDim2.fromOffset(14, 22), ZIndex = 2 })
  A.text({
    Text = entry.name, font = T.font.strong, size = T.size.head, colour = T.c.text,
    Position = UDim2.fromOffset(60, 20), Size = UDim2.new(1, -76, 0, 18),
    truncate = true, Parent = card,
  })
  A.text({
    Text = present
      and string.format("%s  %d KB  -  %s", entry.file, Mod.sizeKB(entry), entry.note)
      or ("missing: " .. entry.file),
    font = T.font.mono, size = T.size.micro,
    colour = present and T.c.textMute or T.c.bad,
    Position = UDim2.fromOffset(60, 42), Size = UDim2.new(1, -76, 0, 14),
    truncate = true, Parent = card,
  })

  if not present then
      return
  end

  C.actions(page, {
    { text = "Launch " .. entry.name, primary = true, callback = function()
        if Mod._ran[entry.file] then
          L.Toast.warn("Already running",
            "Loading a second copy will fight the first. Rejoin to reset.")
          return
        end
        local ok, why = Mod.launch(entry)
        if ok then L.Toast.ok("Loaded", why) else L.Toast.bad("Failed", why) end
      end },
    { text = "Force reload", callback = function()
        Mod._ran[entry.file] = nil
        local ok, why = Mod.launch(entry)
        if ok then L.Toast.ok("Reloaded", why) else L.Toast.bad("Failed", why) end
      end },
  })
end

-- ---------------------------------------------------------------- registration

-- ---------------------------------------------------------------- own page
--
-- WHAT THESE ELEVEN ARE, AND WHY THEIR PAGE IS SHAPED LIKE THIS.
--
-- Murder Mystery 2 lives INSIDE the hub: its toggles are `L.C` controls and its
-- state is a table in the same VM, so it can be given tabs full of switches.
-- Every entry in this registry is the opposite -- a standalone script with its
-- own interface, which LUMEN fetches and runs. There are no toggles here to
-- render, because they do not exist until the script is loaded and then they
-- belong to that script's own window.
--
-- So this page does not pretend otherwise. It gives the game a real section of
-- its own with the hub's own atoms, states plainly what LUMEN's role is, and
-- makes launching it one obvious action instead of a card buried in a list.
function Mod.page(page, entry)
  local present = Mod.exists(entry)

  C.section(page, "module")
  Mod.build(page, entry)

  C.section(page, "about this game")
  C.paragraph(page, string.format(
    "%s  --  by %s.\n%s", entry.name, entry.by or "unknown", entry.note or ""))

  if present then
    C.paragraph(page,
      "This one is a standalone hub: LUMEN fetches " .. entry.file ..
      " and runs it, and it opens its own window with its own controls. "
      .. "Nothing here mirrors those switches, because they do not exist until "
      .. "it loads. Murder Mystery 2 is the other kind -- built into LUMEN, so "
      .. "its controls are these controls. Porting a game from the first kind "
      .. "to the second is what puts its features on tabs like these.")
  else
    C.paragraph(page,
      "The script for this game is not on disk. LUMEN knows the place and can "
      .. "still travel to it, but there is nothing to launch until "
      .. entry.file .. " is present.")
  end

  C.section(page, "elsewhere")
  C.paragraph(page,
    "Universal, Movement, Combat and Visuals work in every game, including this "
    .. "one, and are unaffected by whether the module above is running.")
end

-- Wire each entry into the hub. Every supported place now gets its own nav
-- section and page rather than a card inside Farming -- the same promotion MM2
-- has, applied to what these modules actually are.
for placeId, entry in pairs(Mod.registry) do
  -- `builtin` entries are registered by their own module file with real tabs;
  -- registering a launcher card over the top would replace six working pages
  -- with one that offers to load a file that was never on disk.
  if L.Hub and L.Hub.register and not entry.builtin then
    L.Hub.register(placeId, {
      name  = entry.name,
      short = entry.name,
      tabs = {
        { name = entry.name, chrome = "chart",
          desc = entry.note or "Per-game automation",
          build = function(ctx) Mod.page(ctx.page, entry) end },
      },
      -- kept so the Farming tab still has something to show if this place is
      -- ever mounted the old way
      build = function(ctx) Mod.build(ctx.page, entry) end,
    })
  end
end

end
do -- ==== lm_33_changelog.lua ====
-- LUMEN :: CHANGELOG

local L = getgenv().LUMEN
local T, M, A = L.T, L.Motion, L.A
local mk = L.mk

local Log = {}
L.Changelog = Log

-- Newest first. Phrase entries as what you will notice, not what was edited.
Log.RELEASES = {
  {
    version = "1.0.0",
    title   = "Polish round",
    -- Six notes max; past that the card is a third of the screen.
    notes   = {
      "Target fling hits much harder. A new technique throws people through "
        .. "their own physics stream instead of shoving them, so it lands in "
        .. "games where contact gets filtered.",
      "It aims where your camera looks, and starts on the brutal preset "
        .. "instead of the careful one.",
      "Fling can be stopped or unstuck, and puts you back where you started.",
      "Aim prediction tunes itself to your ping and keeps following it.",
      "Tooltips stay put instead of following you around.",
      "Nothing leaves a dark outline behind when it fades.",
    },
  },
}

local SEEN_KEY = "seenVersion"

function Log.current() return Log.RELEASES[1] end

function Log.unseen()
  local cur = Log.current()
  if not cur then return false end
  local seen = L.Cfg and L.Cfg.data and L.Cfg.data[SEEN_KEY]
  return seen ~= cur.version
end

function Log.markSeen()
  local cur = Log.current()
  if cur and L.Cfg then L.Cfg.set(SEEN_KEY, cur.version) end
end

-- ---------------------------------------------------------------- the bubble

local bubble, host, closing

local function teardown()
  local b, h = bubble, host
  bubble, host, closing = nil, nil, false
  if b then pcall(function() b:Destroy() end) end
  if h then pcall(function() h:Destroy() end) end
end

function Log.close()
  if not bubble or closing then return false end
  closing = true
  -- released now, not when the animation lands: a show() during the fade must
  -- see no bubble, or it waits on state that is already on its way out
  local b, h = bubble, host
  bubble, host = nil, nil
  A.groupTo(b, 1, "fast")
  M.to(b, "Position", UDim2.new(1, -18, 1, -18), "fast")
  M.to(b, "Size", UDim2.fromOffset(b.Size.X.Offset, 0), "fast")
  M.after(select(1, M.resolve("fast")) + 0.25, function()
    closing = false
    if h then pcall(function() h:Destroy() end) end
  end)
  return true
end

-- Any layer this module ever made, whoever lost track of it. Cheap, and it runs
-- on the one path that can create a duplicate.
local function sweepStrays(keep)
  local root = L.host()
  if not root then return end
  for _, d in ipairs(root:GetChildren()) do
    if d ~= keep and d.Name == "LumenChangelog" then
      pcall(function() d:Destroy() end)
    end
  end
end

function Log.show(rel)
  rel = rel or Log.current()
  if not rel then return false end
  -- The old card goes NOW. Closing and waiting 0.2 s was a race against its own
  -- 0.36 s teardown: the wait expired first, `host` was overwritten while the
  -- previous layer was still alive, and the delayed destroy then held a
  -- reference to a variable that had moved on. Two layers, measured.
  if bubble then
    local b, h = bubble, host
    bubble, host, closing = nil, nil, false
    if b then pcall(function() b:Destroy() end) end
    if h then pcall(function() h:Destroy() end) end
  end
  sweepStrays(nil)

  host = mk("ScreenGui", {
    Name = "LumenChangelog", ResetOnSpawn = false, IgnoreGuiInset = true,
    ZIndexBehavior = Enum.ZIndexBehavior.Sibling, DisplayOrder = 55,
  })
  host.Parent = L.host()
  L.own(host)
  sweepStrays(host)

  local sc = L.autoScale()
  local W = math.floor(330 * sc)
  local PAD = math.floor(16 * sc)

  -- CanvasGroup so the card fades as one; its stroke needs A.groupTo to follow.
  bubble = mk("CanvasGroup", {
    AnchorPoint = Vector2.new(1, 1),
    Position = UDim2.new(1, -18, 1, -18),
    Size = UDim2.fromOffset(W, 0),
    BackgroundColor3 = T.c.overlay, BackgroundTransparency = 0,
    BorderSizePixel = 0, GroupTransparency = 1, ZIndex = 4,
    Name = "Bubble", Parent = host,
  })
  L.corner(T.r.lg, bubble)
  L.stroke(T.c.lineStrong, 1, 0.45, bubble)

  local shadow = A.shadow(nil, { Parent = host, spread = 26, alpha = 1, ZIndex = 3 })

  local accent = mk("Frame", {
    Position = UDim2.fromOffset(0, 0), Size = UDim2.new(1, 0, 0, 2),
    BackgroundColor3 = T.c.accent, BorderSizePixel = 0, ZIndex = 6,
    Name = "Edge", Parent = bubble,
  })
  A.accentGradient(accent, 0)

  local head = A.text({
    Text = "What's new",
    font = T.font.strong, size = math.floor(T.size.head * sc), colour = T.c.text,
    Position = UDim2.fromOffset(PAD, math.floor(14 * sc)),
    Size = UDim2.new(1, -PAD * 2, 0, math.floor(20 * sc)),
    ZIndex = 6, tip = false, Parent = bubble,
  })

  local sub = A.text({
    Text = rel.title .. "  ·  v" .. rel.version,
    font = T.font.mono, size = math.floor(T.size.micro * sc), colour = T.c.textMute,
    Position = UDim2.fromOffset(PAD, math.floor(34 * sc)),
    Size = UDim2.new(1, -PAD * 2, 0, math.floor(14 * sc)),
    ZIndex = 6, tip = false, Parent = bubble,
  })

  -- Close sits outside the flow so the notes keep the full width.
  local x = mk("Frame", {
    AnchorPoint = Vector2.new(1, 0),
    Position = UDim2.new(1, -math.floor(10 * sc), 0, math.floor(12 * sc)),
    Size = UDim2.fromOffset(math.floor(22 * sc), math.floor(20 * sc)),
    BackgroundColor3 = T.c.raised, BackgroundTransparency = 0.4,
    BorderSizePixel = 0, ZIndex = 7, Parent = bubble,
  })
  L.corner(T.r.sm, x)
  local xIcon = A.Icon.close(x, math.floor(9 * sc), T.c.textDim)
  xIcon.AnchorPoint = Vector2.new(0.5, 0.5)
  xIcon.Position = UDim2.fromScale(0.5, 0.5)
  xIcon.ZIndex = 8
  A.explain(x, "Dismiss -- reopen it any time from Config", "Close")
  A.interactive(x, { radius = T.r.sm, spotSize = 44, onClick = function()
    Log.markSeen()
    Log.close()
  end })

  -- ---- the notes -------------------------------------------------------
  local top = math.floor(58 * sc)
  local ROW = math.floor(15 * sc)
  local GAP = math.floor(9 * sc)
  local TextService = game:GetService("TextService")
  local size = math.floor(T.size.label * sc)
  local textW = W - PAD * 2 - math.floor(16 * sc)

  local rows, y = {}, top
  for i, note in ipairs(rel.notes or {}) do
    local h = ROW
    local ok, z = pcall(function()
      return TextService:GetTextSize(note, size, T.font.body, Vector2.new(textW, 9999))
    end)
    if ok and z then h = math.max(ROW, math.ceil(z.Y)) end

    local row = mk("Frame", {
      Position = UDim2.fromOffset(PAD, y), Size = UDim2.new(1, -PAD * 2, 0, h),
      BackgroundTransparency = 1, ZIndex = 6, Name = "Note" .. i, Parent = bubble,
    })
    local dot = mk("Frame", {
      AnchorPoint = Vector2.new(0, 0),
      Position = UDim2.fromOffset(0, math.floor(size * 0.42)),
      Size = UDim2.fromOffset(math.max(3, math.floor(4 * sc)), math.max(3, math.floor(4 * sc))),
      BackgroundColor3 = T.c.accent, BorderSizePixel = 0, ZIndex = 7, Parent = row,
    })
    L.corner(999, dot)
    local lbl = A.text({
      Text = note, font = T.font.body, size = size, colour = T.c.textDim,
      align = Enum.TextXAlignment.Left, valign = Enum.TextYAlignment.Top,
      Position = UDim2.fromOffset(math.floor(16 * sc), 0),
      Size = UDim2.new(1, -math.floor(16 * sc), 1, 0),
      ZIndex = 7, tip = false, Parent = row,
    })
    lbl.TextWrapped = true
    rows[#rows + 1] = { row = row, dot = dot, lbl = lbl }
    y = y + h + GAP
  end

  local H = y + math.floor(6 * sc)

  if shadow then
    shadow.AnchorPoint = Vector2.new(1, 1)
    shadow.Position = UDim2.new(1, -18 + 26, 1, -18 + 26)
    shadow.Size = UDim2.fromOffset(W + 52, H + 52)
    shadow.ImageTransparency = 1
  end

  -- ---- the arrival -----------------------------------------------------
  -- Card grows and rises as it fades in, then the notes stagger in one by one.
  M.set(bubble, "Size", UDim2.fromOffset(W, math.floor(H * 0.7)))
  M.set(bubble, "Position", UDim2.new(1, -18, 1, math.floor(14 * sc)))
  for _, r in ipairs(rows) do
    M.set(r.lbl, "TextTransparency", 1)
    M.set(r.dot, "BackgroundTransparency", 1)
    M.set(r.row, "Position", UDim2.fromOffset(PAD + math.floor(10 * sc),
                                              r.row.Position.Y.Offset))
  end
  M.set(head, "TextTransparency", 1)
  M.set(sub, "TextTransparency", 1)

  A.groupSet(bubble, 1)
  A.groupTo(bubble, 0, "base")
  M.to(bubble, "Size", UDim2.fromOffset(W, H), "expressive")
  M.to(bubble, "Position", UDim2.new(1, -18, 1, -18), "expressive")
  if shadow then M.to(shadow, "ImageTransparency", 0.45, "base") end

  M.after(0.08, function()
    if head.Parent then M.to(head, "TextTransparency", 0, "base") end
    if sub.Parent then M.to(sub, "TextTransparency", 0, "base") end
  end)

  Log._seq = M.seq(rows, function(r)
    if not r.row.Parent then return end
    M.to(r.lbl, "TextTransparency", 0, "base")
    M.to(r.dot, "BackgroundTransparency", 0, "base")
    M.to(r.row, "Position", UDim2.fromOffset(PAD, r.row.Position.Y.Offset), "expressive")
  end, { step = 0.055, cap = 0.5 })

  return true
end

function Log.toggle()
  if bubble then return Log.close() end
  return Log.show()
end

-- Once per version, delayed until the hub has finished arriving.
function Log.maybeShow()
  if not Log.unseen() then return false end
  M.after(1.1, function()
    if L.live() and Log.unseen() then Log.show() end
  end)
  return true
end

L.cleanup(teardown, 40)

end
do -- ==== lm_32_mm2.lua ====
-- LUMEN :: MURDER MYSTERY 2
--
-- Place 142823291. Registers into the hub, so it inherits the window, the
-- motion, the toasts, the assets and the fling engine. Fly, noclip, ESP,
-- fullbright and the rest are not reimplemented here; the Elsewhere page names
-- where each one lives.
--
-- A fling is momentum transferred through a contact, resolved by the victim's
-- client when two bodies overlap, so collision must be ON -- the reference
-- script sets CanCollide false and its own changelog lists the fling as broken.
-- LUMEN's engine forces collision on every cycle and measures throws past
-- 100,000 studs; this module only points it at MM2's roles.

local L = getgenv().LUMEN
local T, M, A, C = L.T, L.Motion, L.A, L.C
local mk = L.mk

local Players           = game:GetService("Players")
local RS                = game:GetService("ReplicatedStorage")
local CollectionService = game:GetService("CollectionService")
local RunService        = game:GetService("RunService")
local UIS               = game:GetService("UserInputService")
local TextService       = game:GetService("TextService")
local LP                = L.LP

-- Not every executor exposes VirtualUser, and asking for it is allowed to fail:
-- the swing path below degrades to Tool:Activate() rather than erroring at load.
local VirtualUser = nil
pcall(function() VirtualUser = game:GetService("VirtualUser") end)

-- WHERE A SYNTHETIC CLICK LANDS MATTERS, AND (0,0) IS THE WRONG ANSWER.
--
-- The reference script clicks at Vector2.new(0, 0) -- the top-left pixel. Two
-- problems with copying that. A click there is over whatever GUI happens to
-- occupy the corner, and an input consumed by a ScreenGui never reaches the
-- tool at all; and the gun raycasts through the crosshair, which is the middle
-- of the screen, not the corner.
--
-- So click where the player's crosshair actually is. Recomputed per call
-- because the viewport changes with window size and full-screen toggles.
local function clickPoint()
  local cam = workspace.CurrentCamera
  local v = cam and cam.ViewportSize
  if not v or v.X < 2 or v.Y < 2 then return Vector2.new(400, 300) end
  return Vector2.new(v.X / 2, v.Y / 2)
end

local MM2 = {}
L.MM2 = MM2

MM2.PLACE = 142823291

MM2.cfg = {
  -- combat
  autoKill      = false,
  -- Swing the knife through the engine's own input path instead of firing the
  -- weapon's remotes by hand. See MM2.knifeSweep for why this is not a style
  -- preference: the hand-fired remotes have never once killed.
  realSwing     = true,
  -- Keep shooting at the cover a hidden murderer is behind. Legitimate, and it
  -- is how you can tell the gun is alive, but it cannot kill -- see MM2.COVER_FIRE.
  coverFire     = true,
  -- Play the shot locally so you can hear and see the gun working. Cosmetic and
  -- client-only: it changes nothing the server is told. See MM2.showShot.
  shotFeedback  = true,
  -- Aim the camera at the murderer and let the real GunClient pull the trigger.
  -- ONLY on a genuine clear line, which is rare -- see MM2.shootForReal.
  realShot      = true,
  gunPredict    = true,
  knifeWalls    = false,
  gunWalls      = false,
  instantKnife  = false,
  silentAim     = false,
  aimFov        = 140,
  -- fling
  autoFlingMurderer = false,
  autoFlingSheriff  = false,
  flingStyle    = "Instant",
  -- pickups
  autoGun       = false,
  autoCoins     = false,
  -- esp
  coinEsp       = false,
  gunEsp        = false,
  gunEspDist    = true,
  gunEspColour  = "Blue",
  murdererEsp   = false,
  sheriffEsp    = false,
  trapEsp       = false,
  roleTags      = true,
  -- safety / awareness
  antiTrap      = false,
  murdererNotify = true,
  killFeed      = false,
}

-- PERSISTENCE IS NOT THIS MODULE'S JOB, AND TAKING IT ON BROKE TWO THINGS.
--
-- Every control already persists itself: `bindPersist` in lm_06_controls keys
-- each one by context.section.label, stores through `Cfg.setFeat`, and on the
-- next load restores the knob AND pushes the value back through the original
-- callback so the module's own state follows.
--
-- The first version of this file ignored all of that and wrote its own
-- `Cfg.set("mm2_" .. key)`. Two failures, both measured live:
--
--   1. `Cfg.set` validates against `Cfg.SCHEMA` and `mm2_*` is not in it, so
--      every write was refused and lit the fault indicator -- 9 faults in one
--      session, and nothing ever saved.
--   2. Worse, it made two stores for one fact. The feature store came back
--      holding "Dropped gun ESP = true" while `MM2.cfg.gunEsp` was still false:
--      the panel read ON and the engine read OFF.
--
-- So `save` only mirrors into the live table. Disk is bindPersist's.
local function save(k, v)
  MM2.cfg[k] = v
end

local function combatPhysicsBusy()
  local combat = L.Combat
  if not combat then return false end
  if combat.physicsBusy then
    local ok, busy = pcall(combat.physicsBusy)
    if ok then return busy and true or false end
  end
  return combat.flinging or combat.activeCleanup ~= nil
      or (combat.want and combat.want.touchFling) or false
end

-- ---------------------------------------------------------------- game bindings
--
-- Every lookup is wrapped. A game update that renames a module is a thing that
-- happens, and it must degrade to "role unknown" rather than to a stack trace
-- on somebody's screen mid-round.

local CRC
local function roundClient()
  if game.PlaceId ~= MM2.PLACE then return nil end
  if CRC then return CRC end
  pcall(function()
    CRC = require(RS:WaitForChild("Modules", 5):WaitForChild("CurrentRoundClient", 5))
  end)
  return CRC
end

local function roundData(plr)
  local c = roundClient()
  return c and c.PlayerData and c.PlayerData[plr.Name] or nil
end

local function hrpOf(ch) return ch and ch:FindFirstChild("HumanoidRootPart") end

local GameplayR
if game.PlaceId == MM2.PLACE then
  pcall(function()
    GameplayR = RS:WaitForChild("Remotes", 8):WaitForChild("Gameplay", 8)
  end)
end

-- ---- role -----------------------------------------------------------------
--
-- TWO SOURCES, AND BOTH ARE NEEDED.
--
-- `CurrentRoundClient.PlayerData` is authoritative but only populated once the
-- round has started -- during the countdown, and for a few seconds after a role
-- swap, it is empty or stale. CollectionService tags on the weapon tools fill
-- that gap: whoever holds the knife IS the murderer regardless of what the
-- round table currently says.
--
-- Reading only the round data means being blind at the exact moment the
-- information is most valuable. Reading only the tags means missing a murderer
-- who has not drawn yet.

local WEAPON_TAG = { Gun = "Weapon_Gun", Knife = "Weapon_Knife" }

local function isRemoteEvent(value)
  return value and value:IsA("RemoteEvent")
end

local function hasWeaponIdentity(tool, kind)
  if tool.Name == kind then return true end
  local tag = WEAPON_TAG[kind]
  if not tag then return false end
  local ok, tagged = pcall(CollectionService.HasTag, CollectionService, tool, tag)
  return ok and tagged == true
end

-- A role/remote is authorized only by MM2's identity AND its expected remote
-- shape. A random Tool with a Shoot RemoteEvent can no longer turn Innocent
-- into Hero; renamed MM2 tools remain supported through their server tag.
local function isWeapon(tool, kind)
  if not (tool and tool:IsA("Tool") and hasWeaponIdentity(tool, kind)) then
    return false
  end
  if kind == "Gun" then
    return isRemoteEvent(tool:FindFirstChild("Shoot"))
  end
  if kind == "Knife" then
    local events = tool:FindFirstChild("Events")
    return events and events:IsA("Folder")
       and isRemoteEvent(events:FindFirstChild("HandleTouched"))
       and isRemoteEvent(events:FindFirstChild("KnifeStabbed"))
       or false
  end
  return false
end

local tagOwners = {}
local function refreshTags()
  for _, spec in ipairs({
    { tag = "Weapon_Gun", kind = "Gun" },
    { tag = "Weapon_Knife", kind = "Knife" },
  }) do
    local tag = spec.tag
    local m = tagOwners[tag]
    if m then table.clear(m) else m = {} tagOwners[tag] = m end
    for _, t in ipairs(CollectionService:GetTagged(tag)) do
      if t.Parent and isWeapon(t, spec.kind) then m[t.Parent] = true end
    end
  end
end

local function hasTagged(plr, tag)
  local m = tagOwners[tag]
  if not m then return false end
  local ch = plr.Character
  if ch and m[ch] then return true end
  local bp = plr:FindFirstChildOfClass("Backpack")
  return (bp and m[bp]) and true or false
end

local function charHasWeapon(ch, kind)
  if not ch then return false end
  for _, t in ipairs(ch:GetChildren()) do
    if isWeapon(t, kind) then return true end
  end
  return false
end

local function computeRole(plr)
  local d = roundData(plr)
  local r = d and d.Role
  if r == "Murderer" then return "Murderer" end
  if r == "Sheriff" or r == "Hero" then return r end
  local ch = plr.Character
  if hasTagged(plr, "Weapon_Gun") or charHasWeapon(ch, "Gun") then return "Hero" end
  if hasTagged(plr, "Weapon_Knife") or charHasWeapon(ch, "Knife") then return "Murderer" end
  return r or "Innocent"
end

local function computeAlive(plr)
  local d = roundData(plr)
  if d and d.Dead == true then return false end
  local ch = plr.Character
  local hum = ch and ch:FindFirstChildOfClass("Humanoid")
  return (ch and hum and hum.Health > 0 and hrpOf(ch)) and true or false
end

-- A SHORT CACHE, NOT NO CACHE AND NOT A LONG ONE.
--
-- Role is read by the ESP loop, auto-kill, the fling picker, the kill feed and
-- the notifier -- every frame, for every player -- and `computeRole` walks the
-- character's children. At 20 players that is hundreds of tree walks a frame.
-- 50 ms is short enough that a role swap is invisible and long enough to
-- collapse all of them into one.
local CACHE_TTL = 0.05
local roleCache, aliveCache, stamp = {}, {}, 0
local function sweep()
  local now = os.clock()
  if now - stamp > CACHE_TTL then
    table.clear(roleCache) table.clear(aliveCache)
    stamp = now
    refreshTags()
  end
end

function MM2.roleOf(plr)
  if not plr then return "Innocent" end
  sweep()
  local v = roleCache[plr]
  if v == nil then v = computeRole(plr) roleCache[plr] = v end
  return v
end

function MM2.alive(plr)
  if not plr then return false end
  sweep()
  local v = aliveCache[plr]
  if v == nil then v = computeAlive(plr) aliveCache[plr] = v end
  return v
end

function MM2.myRole() return MM2.roleOf(LP) end
local function isGunRole(r) return r == "Sheriff" or r == "Hero" end
MM2.isGunRole = isGunRole

-- Lethal actions fail closed on contradictory evidence. The round table can be
-- stale during a hand-off, while a currently held/tagged weapon is immediate.
-- Display-only roleOf may remain permissive; a shot/stab gets this stricter view.
local function combatRole(plr)
  if not plr then return nil, "no player" end
  local ch = plr.Character
  local bp = plr:FindFirstChildOfClass("Backpack")
  local hasGun = hasTagged(plr, "Weapon_Gun")
              or charHasWeapon(ch, "Gun") or charHasWeapon(bp, "Gun")
  local hasKnife = hasTagged(plr, "Weapon_Knife")
                or charHasWeapon(ch, "Knife") or charHasWeapon(bp, "Knife")
  if hasGun and hasKnife then return nil, "conflicting live weapons" end
  if hasKnife then return "Murderer" end
  if hasGun then
    local d = roundData(plr)
    return d and d.Role == "Sheriff" and "Sheriff" or "Hero"
  end
  local d = roundData(plr)
  local role = d and d.Role
  if role == "Murderer" or role == "Sheriff" or role == "Hero" then return role end
  return role or "Innocent"
end

-- Lethal paths do not use the 50 ms display cache. This samples the round flag,
-- character epoch and humanoid/root directly at the point of authorization.
local function freshAlive(plr, expectedCharacter)
  if not plr or plr.Parent ~= Players then return false end
  local ch = plr.Character
  if not ch or (expectedCharacter and ch ~= expectedCharacter) then return false end
  local d = roundData(plr)
  if d and d.Dead == true then return false end
  local hum = ch:FindFirstChildOfClass("Humanoid")
  return hum ~= nil and hum.Health > 0 and hrpOf(ch) ~= nil
end
MM2.freshAlive = freshAlive
MM2.combatRole = combatRole

function MM2.findRole(role)
  for _, p in ipairs(Players:GetPlayers()) do
    if p ~= LP and MM2.alive(p) then
      local r = MM2.roleOf(p)
      if r == role or (role == "Sheriff" and isGunRole(r)) then return p end
    end
  end
  return nil
end

MM2.ROLE_COLOUR = {
  Murderer = Color3.fromRGB(255, 84, 84),
  Sheriff  = Color3.fromRGB(96, 154, 255),
  Hero     = Color3.fromRGB(255, 196, 88),
  Innocent = Color3.fromRGB(104, 226, 138),
}

MM2.GUN_ESP_PALETTE = {
  Blue  = { Color3.fromRGB(96, 154, 255), Color3.fromRGB(190, 220, 255) },
  Cyan  = { Color3.fromRGB(55, 220, 255), Color3.fromRGB(185, 248, 255) },
  Gold  = { Color3.fromRGB(255, 184, 48), Color3.fromRGB(255, 232, 150) },
  Green = { Color3.fromRGB(70, 225, 125), Color3.fromRGB(190, 255, 215) },
  Pink  = { Color3.fromRGB(255, 94, 190), Color3.fromRGB(255, 205, 238) },
  Red   = { Color3.fromRGB(255, 75, 75), Color3.fromRGB(255, 190, 190) },
  White = { Color3.fromRGB(225, 230, 240), Color3.fromRGB(255, 255, 255) },
}
MM2.GUN_ESP_COLOURS = { "Blue", "Cyan", "Gold", "Green", "Pink", "Red", "White" }

local function gunEspColours()
  local p = MM2.GUN_ESP_PALETTE[MM2.cfg.gunEspColour]
          or MM2.GUN_ESP_PALETTE.Blue
  return p[1], p[2]
end

-- Action targeting cannot use the permissive display cache: during a round
-- hand-off the table may still say last round's Sheriff while the same player
-- is visibly holding this round's knife. Live weapon evidence wins here.
function MM2.findCombatRole(role)
  for _, p in ipairs(Players:GetPlayers()) do
    local ch = p.Character
    if p ~= LP and freshAlive(p, ch) then
      local current = combatRole(p)
      if current == role or (role == "Sheriff" and isGunRole(current)) then return p end
    end
  end
  return nil
end

function MM2.colourFor(role) return MM2.ROLE_COLOUR[role] or MM2.ROLE_COLOUR.Innocent end
function MM2.tagFor(role)
  return role == "Murderer" and "M" or isGunRole(role) and "S" or "I"
end

-- Who this role may act on. Encoded ONCE so auto-kill, the fling picker and the
-- aim hook cannot disagree -- three copies of "is this person my enemy" is
-- three chances to knife an innocent by accident.
function MM2.isEnemy(myRole, theirRole)
  if myRole == "Murderer" then return theirRole ~= "Murderer" end
  if isGunRole(myRole) then return theirRole == "Murderer" end
  return false
end

-- ---------------------------------------------------------------- weapons

-- Renamed weapons remain supported only through MM2's authoritative weapon tag
-- and verified remote shape. Name text or remote shape alone grants nothing.
local function findWeapon(kind)
  local ch = LP.Character
  local bp = LP:FindFirstChildOfClass("Backpack")
  for _, parent in ipairs({ ch, bp }) do
    if parent then
      for _, tool in ipairs(parent:GetChildren()) do
        if isWeapon(tool, kind) then return tool end
      end
    end
  end
  return nil
end

local function equip(tool)
  local ch = LP.Character
  local hum = ch and ch:FindFirstChildOfClass("Humanoid")
  if not (tool and hum and ch) then return false, "no character" end
  if tool.Parent ~= ch then
    local ok, why = pcall(function() hum:EquipTool(tool) end)
    if not ok then return false, tostring(why) end
    local untilAt = os.clock() + 0.18
    while tool.Parent ~= ch and tool.Parent and os.clock() < untilAt do
      RunService.Heartbeat:Wait()
    end
  end
  if tool.Parent ~= ch then return false, "weapon did not equip" end
  return true
end

-- Candidate body parts accepted by common MM2 rigs, tried in order. This is a
-- compatibility list, not a claim that client-sent touches bypass server LOS or
-- proximity checks; single-target remote touch behavior remains unproved live.
local KNIFE_PARTS = { "HumanoidRootPart", "UpperTorso", "LowerTorso", "Torso", "Head" }

-- LIVE-PROVED SERVER CADENCE. Detection may run every frame; dispatch may not.
-- The 0.10 regression recreated roughly eight sheriff shots per second and the
-- server dropped most of them. These are hard scheduling gates, never catch-up
-- timers: a delayed frame sends once and schedules from that actual dispatch.
-- CADENCE, MEASURED -- NOT A SAFETY MARGIN.
--
-- These were 0.55 / 0.90 on the theory that the server rejects a fast fire rate.
-- That was never tested, and the run that PROVED the kill works passed
-- force = true, which skips this gate entirely and still killed at 65.5 studs
-- on the first attempt (round-table Dead flag flipped false -> true, caller
-- untouched). So the gate was only making a working kill take a second a body.
--
-- What is actually needed is the smallest interval that stops the same target
-- being struck twice inside one controller tick and stops a burst that looks
-- like spam. The controller re-dispatches until the round table reports the
-- target dead, so a rejected shot costs one interval, not one second.
MM2.GUN_COOLDOWN   = 0.16
MM2.KNIFE_COOLDOWN = 0.16

-- HOW LONG A KILL TAKES TO COME BACK, WHICH IS NOT THE SAME AS THE CADENCE.
--
-- The controller re-fires when the observe window expires. With the window set
-- to the cadence, both were 0.16 s -- shorter than the round trip a death has to
-- make before this client can see it. Measured on this game: ping ~0.07 s and
-- remote-state lag ~0.22 s, so a kill cannot show in under ~0.3 s.
--
-- The consequence was exact and visible in the counters: 82 dispatches,
-- 81 of them retries, 0 deaths observed. It never waited long enough to notice
-- it had already won, so it kept shooting and flooded the remote.
--
-- First shot is still immediate. This only governs how long to WATCH before
-- deciding the shot failed.
MM2.SHOT_OBSERVE = 0.45


-- Keep the cadence ledger outside this generation. Reloading LUMEN must not
-- make a gun that fired 100 ms ago look ready, and the outgoing-call hook below
-- also records ordinary game-client shots when the executor exposes namecalls.
local cadenceEnv = getgenv()
local cadence = rawget(cadenceEnv, "__LUMEN_MM2_CADENCE")
if type(cadence) ~= "table" or cadence.jobId ~= game.JobId then
  cadence = { jobId = game.JobId, lastShot = 0, lastStab = 0 }
  rawset(cadenceEnv, "__LUMEN_MM2_CADENCE", cadence)
end
local lastShot = tonumber(cadence.lastShot) or 0
local lastStab = tonumber(cadence.lastStab) or 0
local gunTransaction = false
MM2.shotPreparing = false

local function markShot(at)
  at = tonumber(at) or os.clock()
  lastShot = math.max(lastShot, at)
  cadence.lastShot = math.max(tonumber(cadence.lastShot) or 0, at)
end

local function markStab(at)
  at = tonumber(at) or os.clock()
  lastStab = math.max(lastStab, at)
  cadence.lastStab = math.max(tonumber(cadence.lastStab) or 0, at)
end

function MM2.gunReady()
  return not gunTransaction and os.clock() - lastShot >= MM2.GUN_COOLDOWN
end
function MM2.knifeReady() return os.clock() - lastStab >= MM2.KNIFE_COOLDOWN end

-- ORDER IS THE WHOLE FEATURE, AND THE FIRST VERSION HAD IT BACKWARDS.
--
-- The knife's own client script forwards a touch only inside a swing window:
--
--     Handle.Touched:Connect(function(part)
--         if os.clock() - u4 > 0.85 then return end   -- u4: time of last stab
--         if not u13 then return end                  -- u13: set by stabKnife()
--         Events.HandleTouched:FireServer(part)
--     end)
--
-- `KnifeStabbed` is what opens that window; `HandleTouched` is what declares
-- who was inside it. Firing the touch FIRST -- which is what this did -- lands
-- only when some earlier real swing happened to leave the window open, which is
-- exactly the "works sometimes, and I cannot tell why" the operator reported.
--
-- Stab, then touch. Trying the loaded rig parts avoids betting the whole swing
-- on one R6/R15 name. It does not override the proven 0.90 s server cadence.
function MM2.knifeKill(targetChar, force)
  if not targetChar then return false, "no target" end
  if not (force or MM2.knifeReady()) then return false, "swing not ready" end
  local knife = findWeapon("Knife")
  if not knife then return false, "no knife" end
  local equipped, equipWhy = equip(knife)
  if not equipped then return false, equipWhy end
  if not L.live() then return false, "generation retired" end
  markStab()
  local ev = knife:FindFirstChild("Events")
  local ht = ev and ev:FindFirstChild("HandleTouched")
  local ks = ev and ev:FindFirstChild("KnifeStabbed")
  if not ht then return false, "knife has no touch event" end

  -- ORDER OBSERVED LIVE, WHICH BEATS BOTH INFERENCE AND THE REFERENCE.
  --
  -- Three sources disagreed, so a __namecall capture was put on the real client
  -- and a genuine swing was recorded:
  --
  --     Events.KnifeStabbed   argc=0
  --     Events.HandleTouched  argc=1  1=Instance:Part
  --
  -- The stab fires first and the touch follows when the handle connects. That
  -- matches what reading the Touched handler suggested, and does NOT match the
  -- open-source reference, which touches first. The reference presumably works
  -- anyway because the server keeps a window either side -- but there is no
  -- reason to imitate the odd one out when the real order is on the wire.
  if ks then pcall(function() ks:FireServer() end) end
  local sent = 0
  for _, pn in ipairs(KNIFE_PARTS) do
    local part = targetChar:FindFirstChild(pn)
    if part then
      sent = sent + 1
      pcall(function() ht:FireServer(part) end)
    end
  end
  if sent == 0 then return false, "target has no body parts loaded" end
  -- SAME RETURN SHAPE AS THE GUN PATH: (ok, why, dispatch). The controller reads
  -- `dispatch.at` off whatever strike() returns, so a bare `true` here meant the
  -- knife branch threw the moment it was reached -- which it never was, because
  -- a role gate above stopped it first. Two bugs hiding each other.
  return true, "dispatched", { at = lastStab, range = 0 }
end

local function aimPointFor(p)
  local ch = p and p.Character
  local hrp = hrpOf(ch)
  if not hrp then return nil end
  local part = ch:FindFirstChild("UpperTorso") or ch:FindFirstChild("Torso") or hrp
  return part.Position
end
MM2.aimPointFor = aimPointFor

-- Packet-aware motion tracking for sheriff shots. Remote positions repeat for
-- many local frames, so only a DISTINCT replicated position is a sample. This
-- avoids the old zero/huge/zero velocity sawtooth and never trusts the replicated
-- AssemblyLinearVelocity property. A character replacement or teleport resets
-- the estimator instead of poisoning the next shot.
local Stats = game:FindService("Stats")
local gunMotion = setmetatable({}, { __mode = "k" })

local function gunHorizon()
  local oneWay = 0.035
  local ok, ms = pcall(function()
    return Stats.Network.ServerStatsItem["Data Ping"]:GetValue()
  end)
  if ok and type(ms) == "number" and ms == ms then
    oneWay = math.clamp(ms / 2000, 0.008, 0.35)
  end
  -- Two-client ground truth: visual lag = one-way trip + 0.185 s interpolation.
  return oneWay + 0.185
end

local function trackedAimPoint(p)
  local ch = p and p.Character
  local hrp = hrpOf(ch)
  if not hrp then return nil end
  local body = ch:FindFirstChild("UpperTorso") or ch:FindFirstChild("Torso") or hrp
  local now, here = os.clock(), hrp.Position
  local rec = gunMotion[p]
  if not rec or rec.character ~= ch then
    rec = { character = ch, position = here, changedAt = now,
            velocity = Vector3.zero, samples = 0, packetGap = 0.22 }
    gunMotion[p] = rec
  else
    local delta = here - rec.position
    if delta.Magnitude > 0.015 then
      local dt = now - rec.changedAt
      local speed = dt > 0 and delta.Magnitude / dt or math.huge
      if delta.Magnitude > 60 or dt < 0.025 or dt > 0.9 or speed > 240 then
        rec.velocity, rec.samples = Vector3.zero, 0
      else
        local observed = delta / dt
        local alpha = rec.samples == 0 and 1 or math.clamp(dt * 2.5, 0.35, 0.72)
        rec.velocity = rec.velocity:Lerp(observed, alpha)
        rec.samples = rec.samples + 1
        rec.packetGap = rec.packetGap * 0.7 + dt * 0.3
      end
      rec.position, rec.changedAt = here, now
    end
  end

  if not MM2.cfg.gunPredict or rec.samples == 0 then return body.Position end
  local age = now - rec.changedAt
  local staleAfter = math.clamp((rec.packetGap or 0.22) * 1.5, 0.10, 0.45)
  local freshness = 1 - math.clamp((age - staleAfter) / 0.20, 0, 1)
  local lead = rec.velocity * gunHorizon() * freshness
  if L.Guard then lead = lead * L.Guard.quality() end
  local cap = 20
  if lead.Magnitude > cap then lead = lead.Unit * cap end
  return body.Position + lead
end
MM2.gunAimPointFor = trackedAimPoint

-- RATE, NOT AIM, IS WHY THIS MISSED.
--
-- The real client sends two client-computed CFrames and nothing else:
--
--     local origin = HumanoidRootPart.GunRaycastAttachment.WorldCFrame
--     Gun.Shoot:FireServer(origin, CFrame.new(raycastResult.Position))
--
-- The server has no independent source for either, which is why a synthesised
-- origin two studs short of the target ignores geometry entirely -- that part
-- was always right.
--
-- What was wrong was the CADENCE. Auto-kill ticked every 0.12 s and fired every
-- tick, roughly eight shots a second at a weapon that will not accept anything
-- like that rate. The server drops the surplus, so seven of every eight attempts
-- did nothing and the one that landed looked like luck. Spacing the shots does
-- not slow the kill down -- it just stops throwing away the attempts that were
-- never going to be honoured.
-- THE GUN'S REAL LIMITS, READ OUT OF THE GAME RATHER THAN GUESSED.
--
-- ReplicatedStorage.ClientServices.WeaponService, line 63:
--
--     local v13 = Ray.new(v12.Origin, v12.Direction * 300);
--
-- 300 studs is the length of the client's own aim raycast, so it is the
-- furthest target a legitimate sheriff can ever send. Beyond that the real
-- client returns the ray's endpoint, never a player. A shot claiming a hit at
-- 400 studs is therefore something no honest client produces.
--
-- Two more facts from the same function, both useful:
--   * WeaponRaycast RE-CASTS PAST anything with Transparency == 1, and skips
--     everything tagged WeaponPassthrough. Invisible geometry never blocks.
--   * the ignore list starts with your own character, so you cannot self-hit.
MM2.GUN_RANGE = 300

-- AND THIS IS WHY IT ONLY WORKED SOMETIMES.
--
-- The real client sends the origin as
--     HumanoidRootPart.GunRaycastAttachment.WorldCFrame
-- which is ON THE SHOOTER'S BODY. The first version here always synthesised an
-- origin two studs from the TARGET -- which at any real distance is hundreds of
-- studs from where our body actually is, and is the single most obvious thing a
-- server can check. Close up the lie is small and it lands; far away it is
-- enormous and the shot is dropped. That is exactly the "works sometimes, and
-- I cannot tell why" pattern.
--
-- `gunWalls` was supposed to control this and never did: our own FireServer
-- makes `checkcaller()` true, so the __namecall hook deliberately skips it.
-- The toggle now applies here, where the call is actually made.
--
--   gunWalls off -> real attachment origin. Indistinguishable from a legit
--                   shot, so nothing to reject. This is the reliable one.
--   gunWalls on  -> origin two studs off the target, which defeats line of
--                   sight but is the version a server can notice.
local function gunLineClear(origin, pos, targetChar)
  if not targetChar or MM2.cfg.gunWalls then return true end
  local ignore = { LP.Character }
  for _ = 1, 10 do
    local params = RaycastParams.new()
    params.FilterType = Enum.RaycastFilterType.Exclude
    params.FilterDescendantsInstances = ignore
    params.IgnoreWater = true
    local result = workspace:Raycast(origin, pos - origin, params)
    if not result then return true end
    local hit = result.Instance
    if hit and hit:IsDescendantOf(targetChar) then return true end
    if hit and hit:IsA("BasePart")
       and (hit.Transparency == 1 or CollectionService:HasTag(hit, "WeaponPassthrough")) then
      ignore[#ignore + 1] = hit
    else
      return false, hit and hit:GetFullName() or "opaque geometry"
    end
  end
  return false, "too many passthrough layers"
end

MM2.shotStats = {
  dispatched = 0, deathObserved = 0, retryDispatches = 0, errors = 0,
}

local function performShot(pos, expectedPlayer)
  if not L.live() then return false, "generation retired" end
  if not pos then return false, "no aim point" end
  if MM2.relocating or combatPhysicsBusy() then
    return false, "local character is in a physics transaction"
  end
  if os.clock() - lastShot < MM2.GUN_COOLDOWN then return false, "reloading" end
  local localChar = LP.Character
  if not freshAlive(LP, localChar) then return false, "local character is not alive" end
  local expectedChar = expectedPlayer and expectedPlayer.Character
  if expectedPlayer then
    local theirRole = combatRole(expectedPlayer)
    if expectedPlayer.Parent ~= Players or expectedPlayer == LP
       or not expectedChar or not freshAlive(expectedPlayer, expectedChar)
       or theirRole ~= "Murderer" then
      return false, "target is no longer a living murderer"
    end
  end
  local gun = findWeapon("Gun")
  if not gun then return false, "no gun" end
  local equipped, equipWhy = equip(gun)
  if not equipped then return false, equipWhy end
  if not L.live() then return false, "generation retired while equipping" end
  if MM2.relocating or combatPhysicsBusy() then
    return false, "physics transaction started while equipping"
  end
  local shoot = gun:FindFirstChild("Shoot")
  local myHrp = hrpOf(localChar)
  if LP.Character ~= localChar or gun.Parent ~= localChar
     or not (isRemoteEvent(shoot) and shoot.Parent == gun and myHrp) then
    return false, "local character or equipped gun changed"
  end

  -- Equip can yield for several replicated frames. Re-authorize both character
  -- epochs, roles and life state, then compute the aim from the newest packet.
  if expectedPlayer then
    local mine, theirs = combatRole(LP), combatRole(expectedPlayer)
    if not freshAlive(LP, localChar)
       or not freshAlive(expectedPlayer, expectedChar)
       or not isGunRole(mine) or theirs ~= "Murderer" then
      return false, "combat state changed while equipping"
    end
    pos = trackedAimPoint(expectedPlayer)
    if not pos then return false, "target aim point is no longer available" end
  end

  -- No fallback. This exact attachment is the origin the real client sends.
  local att = myHrp:FindFirstChild("GunRaycastAttachment")
  if not (att and att:IsA("Attachment")) then
    return false, "GunRaycastAttachment is not ready"
  end
  local trueOrigin = att.WorldCFrame

  local range = (pos - trueOrigin.Position).Magnitude
  if range > MM2.GUN_RANGE then
    return false, string.format("%.0f studs -- past the gun's %d stud range",
      range, MM2.GUN_RANGE)
  end

  local clear, blocker = gunLineClear(trueOrigin.Position, pos, expectedChar)
  if not clear then return false, "blocked by " .. tostring(blocker) end

  -- Raycasting does not yield, but this final direct sample keeps the remote call
  -- adjacent to its authorization and prevents a cached lobby/respawn decision.
  if expectedPlayer then
    local mine, theirs = combatRole(LP), combatRole(expectedPlayer)
    if not freshAlive(LP, localChar)
       or not freshAlive(expectedPlayer, expectedChar)
       or not isGunRole(mine) or theirs ~= "Murderer" then
      return false, "combat state changed before dispatch"
    end
  end

  local origin
  if MM2.cfg.gunWalls then
    local dir = pos - trueOrigin.Position
    dir = dir.Magnitude > 0.1 and dir.Unit or myHrp.CFrame.LookVector
    origin = CFrame.new(pos - dir * 2, pos)
  else
    origin = trueOrigin
  end

  -- This is deliberately repeated after every possible yield. The transaction
  -- mutex prevents a second caller from crossing the equip wait in parallel.
  if not L.live() then return false, "generation retired before dispatch" end
  if MM2.relocating or combatPhysicsBusy() or LP.Character ~= localChar
     or gun.Parent ~= localChar or shoot.Parent ~= gun then
    return false, "physics, character or weapon state changed before dispatch"
  end
  if os.clock() - lastShot < MM2.GUN_COOLDOWN then return false, "reloading" end

  local ok, why = pcall(function() shoot:FireServer(origin, CFrame.new(pos)) end)
  if not ok then
    MM2.shotStats.errors = MM2.shotStats.errors + 1
    return false, "Shoot dispatch failed: " .. tostring(why)
  end
  -- A successful FireServer call is a dispatch, never proof of a kill.
  markShot()
  MM2.shotStats.dispatched = MM2.shotStats.dispatched + 1
  return true, "dispatched", { at = lastShot, origin = origin, range = range }
end

function MM2.shootAt(pos, expectedPlayer)
  if gunTransaction then return false, "another shot is already being prepared" end
  gunTransaction = true
  MM2.shotPreparing = true
  local result = table.pack(xpcall(function()
    return performShot(pos, expectedPlayer)
  end, function(why) return tostring(why) end))
  gunTransaction = false
  MM2.shotPreparing = false
  if not result[1] then
    MM2.shotStats.errors = MM2.shotStats.errors + 1
    return false, "shot transaction failed: " .. tostring(result[2])
  end
  return table.unpack(result, 2, result.n)
end

function MM2.strike(p)
  if not (p and p.Parent == Players and p ~= LP and MM2.alive(p)) then
    return false, "invalid target"
  end
  local mine, theirs = combatRole(LP), combatRole(p)
  if not MM2.isEnemy(mine, theirs) then return false, "target is not your enemy" end
  if mine == "Murderer" then return MM2.knifeKill(p.Character) end
  if isGunRole(mine) then return MM2.shootAt(trackedAimPoint(p), p) end
  return false, "you are innocent"
end

-- ---- instant knife throw --------------------------------------------------
--
-- The knife's throw has a wind-up animation before the remote fires. Firing
-- `KnifeThrown` directly skips it, so the knife is in flight on the frame you
-- pressed rather than a third of a second later.
--
-- `instantFiredAt` is what stops it throwing twice: the animation's own remote
-- still arrives shortly after, and the namecall hook below drops it if we have
-- already thrown within the window.
local instantFiredAt = 0

local function bestThrowTarget()
  local localChar = LP.Character
  local mine = combatRole(LP)
  local cam = workspace.CurrentCamera
  local myHrp = hrpOf(localChar)
  if not (cam and myHrp and freshAlive(LP, localChar)) then return nil end

  local best, bestD
  for _, p in ipairs(Players:GetPlayers()) do
    local theirChar = p.Character
    local theirRole = combatRole(p)
    if p ~= LP and freshAlive(p, theirChar) and MM2.isEnemy(mine, theirRole) then
      local pos = aimPointFor(p)
      if pos then
        local sp, on = cam:WorldToViewportPoint(pos)
        if on then
          local d = (Vector2.new(sp.X, sp.Y)
                   - Vector2.new(cam.ViewportSize.X / 2, cam.ViewportSize.Y / 2)).Magnitude
          if d <= (MM2.cfg.aimFov or 140) and (not bestD or d < bestD) then
            best, bestD = pos, d
          end
        end
      end
    end
  end
  return best
end

function MM2.throwKnifeNow()
  local knife = findWeapon("Knife")
  if not knife then return false, "no knife" end
  local equipped, equipWhy = equip(knife)
  if not equipped then return false, equipWhy end
  if not L.live() then return false, "generation retired" end
  local ev = knife:FindFirstChild("Events")
  local thrown = ev and ev:FindFirstChild("KnifeThrown")
  if not thrown then return false, "knife has no throw event" end

  local target = bestThrowTarget()
  if not target then
    local cam = workspace.CurrentCamera
    target = cam and (cam.CFrame.Position + cam.CFrame.LookVector * 250) or nil
  end
  local hrp = hrpOf(LP.Character)
  if not (target and hrp) then return false, "nothing to throw at" end

  local d = target - hrp.Position
  d = d.Magnitude > 0.1 and d.Unit or Vector3.new(0, 0, -1)
  instantFiredAt = os.clock()
  pcall(function()
    thrown:FireServer(CFrame.new(target - d * 2, target), CFrame.new(target))
  end)
  return true
end

L.hold(UIS.InputBegan:Connect(function(input, gpe)
  if gpe or not MM2.cfg.instantKnife then return end
  if game.PlaceId ~= MM2.PLACE then return end
  if input.UserInputType == Enum.UserInputType.MouseButton2 then
    L.try("mm2.throw", MM2.throwKnifeNow)
  end
end))

-- ---- silent aim / through walls -------------------------------------------
--
-- ONE HOOK FOR THREE FEATURES, because they are all the same edit: rewrite the
-- CFrame the game is about to send.
--
--   silent aim     -- replace the target with the best enemy in the FOV, so the
--                     shot lands wherever you were actually pointing
--   through walls  -- rebuild the ORIGIN two studs short of the target, which
--                     is what defeats the server's line-of-sight check
--   instant knife  -- drop the animation's duplicate remote after we have
--                     already fired one ourselves
--
-- Guarded on executor support: `hookmetamethod` is not universal, and a hub
-- that hard-errors at load on a weaker executor takes every other feature down
-- with it.
local silentAimPos
local hookInstalled = false
local hookEnv = getgenv()
local hookDispatcher = rawget(hookEnv, "__LUMEN_MM2_NAMECALL_DISPATCHER")
if type(hookDispatcher) ~= "table" or hookDispatcher.version ~= 1 then
  hookDispatcher = { version = 1, installed = false, handler = nil }
  rawset(hookEnv, "__LUMEN_MM2_NAMECALL_DISPATCHER", hookDispatcher)
end

local function outgoingWeaponKind(remote)
  if not isRemoteEvent(remote) then return nil end
  if remote.Name == "Shoot" then
    local tool = remote.Parent
    if tool and tool.Parent == LP.Character and isWeapon(tool, "Gun") then
      return "Gun"
    end
  elseif remote.Name == "KnifeThrown" then
    local events = remote.Parent
    local tool = events and events.Parent
    if tool and tool.Parent == LP.Character and isWeapon(tool, "Knife") then
      return "Knife"
    end
  end
  return nil
end

-- DID THE GAME ACTUALLY SWING? The one measurement that settles whether a
-- synthetic click reaches the weapon.
--
-- swingForReal produces an engine click and returns "input" -- but that only
-- says the click was ACCEPTED, not that KnifeClient heard it. If the game's own
-- client responds, it fires KnifeStabbed itself, with checkcaller FALSE. So a
-- rising `gameStabs` after our click is proof the real swing happened; a flat
-- one means the click went nowhere and the whole approach is wrong.
MM2.wire = { gameStabs = 0, gameTouches = 0, ourStabs = 0, lastGameStab = 0 }

local function activeAimHandler(self, method, caller, ...)
  if not L.live() or method ~= "FireServer" or game.PlaceId ~= MM2.PLACE then return nil end

  if typeof(self) == "Instance" then
    local n = self.Name
    if n == "KnifeStabbed" then
      if caller then
        MM2.wire.ourStabs = MM2.wire.ourStabs + 1
      else
        MM2.wire.gameStabs = MM2.wire.gameStabs + 1
        MM2.wire.lastGameStab = os.clock()
      end
    elseif n == "HandleTouched" and not caller then
      MM2.wire.gameTouches = MM2.wire.gameTouches + 1
    end
  end

  local kind = outgoingWeaponKind(self)
  if not kind then return nil end

  -- A normal MM2 weapon script is not checkcaller(). Recording its outgoing
  -- shot keeps auto-kill outside the same proven 0.55 s server window.
  if not caller and kind == "Gun" then markShot() end
  if caller then return nil end

  local nm = self.Name
  if nm == "KnifeThrown" and MM2.cfg.instantKnife
     and os.clock() - instantFiredAt < 0.6 then
    return "block"
  end

  local walls = (nm == "Shoot" and MM2.cfg.gunWalls)
             or (nm == "KnifeThrown" and MM2.cfg.knifeWalls)
  local retarget = (MM2.cfg.silentAim and silentAimPos) or nil
  if not (retarget or walls) then return nil end

  local n = select("#", ...)
  if n < 2 then return nil end
  local a = table.pack(...)
  if typeof(a[2]) ~= "CFrame" then return nil end
  local tp = retarget or a[2].Position
  a[2] = CFrame.new(tp)
  if walls and typeof(a[1]) == "CFrame" then
    local hrp = hrpOf(LP.Character)
    if hrp then
      local d = tp - hrp.Position
      d = d.Magnitude > 0.1 and d.Unit or Vector3.new(0, 0, -1)
      a[1] = CFrame.new(tp - d * 2, tp)
    end
  end
  a.n = n
  return "rewrite", a
end

local function installAimHook()
  if hookInstalled and hookDispatcher.handler == activeAimHandler then return true end

  -- Fetched through the environment rather than named as bare globals, which is
  -- what lm_24_combat does and what the linter expects: these four do not exist
  -- in stock Luau, so a direct reference is an undefined global everywhere the
  -- hub is type-checked.
  local hookmeta   = rawget(hookEnv, "hookmetamethod")
  local cclosure   = rawget(hookEnv, "newcclosure")
  local iscaller   = rawget(hookEnv, "checkcaller")
  local namecallof = rawget(hookEnv, "getnamecallmethod")
  if type(hookmeta) ~= "function" or type(cclosure) ~= "function"
     or type(iscaller) ~= "function" or type(namecallof) ~= "function" then
    return false, "this executor cannot hook __namecall"
  end

  if not hookDispatcher.installed then
    local ok = pcall(function()
      local old
      old = hookmeta(game, "__namecall", cclosure(function(self, ...)
        -- READ THE METHOD ONCE, UP FRONT. `getnamecallmethod` reports the call
        -- currently in flight, and the handler below makes namecalls of its own
        -- while it thinks -- so by the time it returns, the answer has changed.
        local method = namecallof()
        local handler = hookDispatcher.handler
        if type(handler) == "function" then
          local reply = table.pack(pcall(handler, self, method, iscaller(), ...))
          if reply[1] and reply[2] == "block" then return nil end
          if reply[1] and reply[2] == "rewrite" and type(reply[3]) == "table" then
            local args = reply[3]
            -- AND RE-DISPATCH BY NAME, NOT THROUGH `old`. THIS IS THE BUG THAT
            -- STOPPED THE SHERIFF FIRING AT ALL, AND IT COST DAYS.
            --
            -- `old` is the original __namecall metamethod: it works out WHICH
            -- method to run by reading the namecall state, not from anything we
            -- pass it. The wall-rewrite branch of the handler calls
            -- hrpOf(LP.Character) -> FindFirstChild -- itself a namecall --
            -- which overwrites that state. So `old(self, originCFrame,
            -- targetCFrame)` dispatched two CFrames into FindFirstChild and
            -- threw "argument #1 expects a string, but CFrame was passed",
            -- inside our own Shoot:FireServer, on every shot. The counter read
            -- 24 errors, 0 dispatches, and the gun sat silent holding a full
            -- barrel.
            --
            -- `self[method]` is an INDEX, not a namecall, so it cannot be
            -- clobbered and does not re-enter this hook. Calling it directly
            -- runs exactly the method the game asked for, with our arguments.
            local fn = self[method]
            if type(fn) == "function" then
              return fn(self, table.unpack(args, 1, args.n or #args))
            end
            return old(self, table.unpack(args, 1, args.n or #args))
          end
        end
        return old(self, ...)
      end))
    end)
    if not ok then return false, "the hook was refused" end
    hookDispatcher.installed = true
  end

  hookDispatcher.handler = activeAimHandler
  hookInstalled = true
  return true
end


-- The dispatcher itself is installed once for the executor session. Generations
-- replace only this handler, so reloads do not stack another metamethod on every
-- namecall; identity guarding cannot erase a newer generation's handler.
L.cleanup(function()
  if hookDispatcher.handler == activeAimHandler then hookDispatcher.handler = nil end
end, 20)

-- Keeps `silentAimPos` current so the hook has something to substitute. Runs
-- only while silent aim is on -- a per-frame viewport projection for every
-- player is not free.
task.spawn(function()
  while L.live() do
    RunService.Heartbeat:Wait()
    if not L.live() then break end
    if MM2.cfg.silentAim and game.PlaceId == MM2.PLACE then
      silentAimPos = bestThrowTarget()
    else
      silentAimPos = nil
    end
  end
end)

-- ---------------------------------------------------------------- fling
--
-- Delegates to LUMEN's engine. What this adds is role targeting and a tuning
-- profile, because "fling the murderer" is the actual request and "fling
-- whoever is called Steve" is a worse way to say it.

-- INSTANT IS A TUNING, NOT A DIFFERENT TECHNIQUE.
--
-- The engine's default profile is built for reliability in unknown games: close
-- the distance, wait for the victim's machine to see you arrive, then strike.
-- That settle is the single biggest factor in whether a fling lands -- measured
-- at 5 studs thrown without it against 101,476 with.
--
-- In MM2 the target is almost always already within a few studs, which is the
-- one case where the wait buys nothing because ownership has already
-- propagated. Instant cuts the settle to its floor and raises the release
-- speed; Heavy does the opposite for the long-range case.
MM2.FLING_STYLES = { "Instant", "Balanced", "Heavy" }

-- INSTANT IS NOW AS INSTANT AS THE NETWORK ALLOWS, WHICH IS NOT ZERO.
--
-- The settle is not politeness, it is the window in which the victim's machine
-- receives that we have arrived. Strike before that and their client resolves
-- the contact against a body it does not think is there yet. The engine's own
-- repeats: 0.5 s landed 2/2, 0.2 s landed 1/2, and 0 s landed 0/3 with a peak
-- of zero -- a fling that fires instantly and does nothing at all.
--
-- 0.05 s is the floor that still works. At the ranges MM2 fights happen at, the
-- engine additionally cuts this to 35% (gap < 25 studs), so the real wait is
-- about 18 ms -- roughly one frame. If it ever feels slow again the problem is
-- somewhere else; taking this to zero only makes it stop working silently.
local FLING_PROFILE = {
  Instant  = { approachSettle = 0.05, flungAt = 4500, flingAfterburn = 0.35,
               flingDuration = 1.6, orbitRadius = 0.85 },
  Balanced = { approachSettle = 0.35, flungAt = 3000, flingAfterburn = 0.45,
               flingDuration = 2.2, orbitRadius = 1.0 },
  Heavy    = { approachSettle = 0.55, flungAt = 2200, flingAfterburn = 1.10,
               flingDuration = 3.2, orbitRadius = 1.15 },
}

function MM2.applyFlingStyle(style)
  local K = L.Combat
  if not K then return false, "combat module missing" end
  local prof = FLING_PROFILE[style or MM2.cfg.flingStyle] or FLING_PROFILE.Instant
  for k, v in pairs(prof) do K.cfg[k] = v end
  if style then save("flingStyle", style) end
  return true
end

function MM2.fling(name)
  local K = L.Combat
  if not K then return false, "combat module missing" end
  if MM2.relocating then return false, "wait for the active pickup relocation" end
  MM2.applyFlingStyle()
  K.cfg.flingMode = "One target"
  return K.startFling(name)
end

-- Resolved at press time rather than bound to a name: roles change every round,
-- and a button that flings last round's murderer flings an innocent.
function MM2.flingRole(role)
  local p = MM2.findCombatRole(role)
  if not p then return false, "no living " .. string.lower(role) .. " right now" end
  local ok, why = MM2.fling(p.Name)
  return ok, ok and (p.DisplayName or p.Name) or why
end

function MM2.flingAll()
  local K = L.Combat
  if not K then return false, "combat module missing" end
  if MM2.relocating then return false, "wait for the active pickup relocation" end
  MM2.applyFlingStyle()
  K.cfg.flingMode = "Everyone"
  return K.startFling()
end

function MM2.stopFling()
  if L.Combat then L.Combat.stopFling("stopped from MM2") end
  return true
end

-- One loop for both auto-fling toggles rather than one each: two loops would
-- both see the same murderer and both call startFling, and the second restarts
-- the first mid-throw.
local autoFlingLoop
local function ensureAutoFling()
  if autoFlingLoop then return end
  autoFlingLoop = task.spawn(function()
    while L.live() do
      task.wait(0.35)
      if not L.live() then break end
      local K = L.Combat
      if K and not combatPhysicsBusy() and not MM2.relocating and game.PlaceId == MM2.PLACE
         and (MM2.cfg.autoFlingMurderer or MM2.cfg.autoFlingSheriff)
         and MM2.alive(LP) then
        local want
        if MM2.cfg.autoFlingMurderer then want = MM2.findCombatRole("Murderer") end
        if not want and MM2.cfg.autoFlingSheriff then want = MM2.findCombatRole("Sheriff") end
        if want then L.try("mm2.autofling", function() MM2.fling(want.Name) end) end
      end
    end
  end)
end

-- ---------------------------------------------------------------- auto kill

-- ONE SWING, EVERY ENEMY -- TRIED, AND IT KILLS YOU INSTEAD.
--
-- The theory was that `KnifeStabbed` opens a swing window, `HandleTouched`
-- names who was inside it, and nothing pairs the two per victim -- so one stab
-- plus a touch for every enemy should reach all of them for a single cooldown.
--
-- Fired live as the murderer against seven targets. Measured against the round
-- table's server-side Dead flag, not local health:
--
--     targetsTouched=7   aliveBefore=7   aliveAfter=7   died=NONE
--
-- Nobody died. The operator did, and the console records it as
-- `false Murderer MurdererDied nil` -- killer nil, which is an environmental
-- death, not a player kill. Firing HandleTouched at bodies the server does not
-- agree you are touching gets the CALLER launched off the map.
--
-- So the touch is validated after all, and the validation is punitive rather
-- than a silent no-op. Do not rebuild this, and do not trust the swing-window
-- reading it was based on: that came from a static read of the decompiled
-- client whose verification pass never ran.

local roleSeen = setmetatable({}, { __mode = "k" })
local pendingShot, stickyTarget, retryQueued
MM2.autoKillInfo = {
  phase = "idle", reason = "disabled", target = nil, distance = nil,
  lastDispatch = nil, lastInterval = nil,
}

local function setAutoPhase(phase, reason, target, distance)
  local s = MM2.autoKillInfo
  s.phase, s.reason = phase, reason
  s.target = target and target.Name or nil
  s.distance = distance
end

local function roleHeld(plr, wanted, seconds)
  local now = os.clock()
  local role, why = combatRole(plr)
  local rec = roleSeen[plr]
  if not rec or rec.role ~= role or rec.character ~= plr.Character
     or now - rec.lastSeen > 0.16 then
    rec = { role = role, character = plr.Character, since = now, lastSeen = now }
    roleSeen[plr] = rec
  else
    rec.lastSeen = now
  end
  return role == wanted and now - rec.since >= seconds, why
end

local function nearestEnemy(mine)
  local myRoot = hrpOf(LP.Character)
  local best, bestDistance
  for _, p in ipairs(Players:GetPlayers()) do
    if p ~= LP and MM2.alive(p) then
      local theirs = combatRole(p)
      if MM2.isEnemy(mine, theirs) then
        local pos = isGunRole(mine) and trackedAimPoint(p) or aimPointFor(p)
        local distance = pos and myRoot and (pos - myRoot.Position).Magnitude or math.huge
        if p == stickyTarget then distance = distance - 0.25 end
        if not bestDistance or distance < bestDistance then
          best, bestDistance = p, distance
        end
      end
    end
  end
  return best, bestDistance
end

local function clearAutoState(reason, phase)
  pendingShot, stickyTarget, retryQueued = nil, nil, nil
  table.clear(roleSeen)
  setAutoPhase(phase or "idle", reason or "reset")
end

-- One deterministic controller. It detects quickly, but the dispatch gate is
-- the measured weapon cadence. A delayed frame never catches up with a burst.
local function autoKillStep()
  if not L.live() then clearAutoState("generation retired") return end
  if not MM2.cfg.autoKill then clearAutoState("disabled") return end
  if game.PlaceId ~= MM2.PLACE then clearAutoState("wrong place") return end
  if not freshAlive(LP) then clearAutoState("lobby or dead") return end
  if MM2.relocating or combatPhysicsBusy() then
    clearAutoState("local character is being relocated", "paused")
    return
  end

  -- MURDERER RUNS THE REFERENCE SWEEP, NOT THIS CONTROLLER.
  --
  -- The state machine below was built around the gun: acquire, dispatch one
  -- shot, observe for a death, retry. That shape is wrong for the knife, and
  -- three rewrites of it never landed a kill.
  --
  -- The open-source script this module was derived from does something much
  -- simpler and it demonstrably works: equip once, then call a COMPLETE
  -- knifeKill on every living enemy, and repeat at 20 Hz. No cadence gate, no
  -- role-stability wait, no observe window.
  --
  -- Note what makes this different from the kill-all that got the operator
  -- launched off the map: that fired ONE KnifeStabbed and then touched seven
  -- scattered bodies. This fires a complete stab-and-touch PER VICTIM. The
  -- server rejects the first shape and accepts the second, which is why the
  -- reference has shipped this way for a long time.
  if combatRole(LP) == "Murderer" then
    local hit, why = MM2.knifeSweep()
    if hit and hit > 0 then
      setAutoPhase("sweeping", string.format("knifed %d enemy target(s)", hit))
    else
      setAutoPhase("armed", why or "no living enemy in reach")
    end
    return
  end

  -- AND THE SHERIFF TAKES THE SAME ROUTE, FOR THE SAME REASON.
  --
  -- The observe-and-retry machine below was written for the gun and it is the
  -- reason the gun did nothing: a 0.45 s observe window, two role-stability
  -- timers and `performShot`'s range and line-of-sight gates all had to agree
  -- before a single packet left. `MM2.gunSweep` is the reference's six lines,
  -- gated only by the fire rate. Manual `strike()` still uses the strict path.
  if isGunRole(combatRole(LP)) then
    local fired, why = MM2.gunSweep()
    if fired and fired > 0 then
      setAutoPhase("sweeping", "shooting " .. tostring(why))
    else
      setAutoPhase("armed", why or "no murderer in sight")
    end
    return
  end

  -- BOTH ROLES. The knife was disabled here on the grounds that a multi-target
  -- knife experiment killed the caller and nobody else -- true, and the reason
  -- kill-all is gone. But it was the FAN-OUT that the server punished: claiming
  -- to touch seven bodies scattered across the map. A SINGLE-target stab was
  -- verified live in the same session and worked at 65.5 studs through walls,
  -- with the caller untouched. Disabling the whole knife path threw away a
  -- proven kill to avoid a mistake it does not make.
  local mine = combatRole(LP)
  if not (mine == "Murderer" or isGunRole(mine)) then
    clearAutoState("waiting for a weapon role")
    return
  end
  local usingKnife = (mine == "Murderer")
  local cadence = usingKnife and MM2.KNIFE_COOLDOWN or MM2.GUN_COOLDOWN

  if pendingShot then
    local shot, now = pendingShot, os.clock()
    local d = roundData(shot.player)
    local oldHum = shot.character and shot.character:FindFirstChildOfClass("Humanoid")
    if (d and d.Dead == true) or (oldHum and oldHum.Health <= 0) then
      MM2.shotStats.deathObserved = MM2.shotStats.deathObserved + 1
      setAutoPhase("observed", "death state observed after dispatch (not causal proof)", shot.player)
      pendingShot, stickyTarget, retryQueued = nil, nil, nil
      return
    end
    -- ENEMY, not literally "Murderer". Hardcoding the target's role was correct
    -- only for the sheriff; as the murderer every target is an innocent or the
    -- sheriff, so this cleared the pending shot on the very first tick and the
    -- controller could never observe its own dispatch.
    if not MM2.isEnemy(mine, combatRole(shot.player)) then
      pendingShot, stickyTarget = nil, nil
      setAutoPhase("idle", "round or role changed")
      return
    end
    if shot.player.Character ~= shot.character then
      pendingShot = nil
      setAutoPhase("waiting", "target character epoch changed", shot.player)
      return
    end
    -- Watch for at least as long as a death needs to reach us. See
    -- MM2.SHOT_OBSERVE -- re-firing sooner than this is how the counters ended
    -- up at 82 dispatches and 0 observed deaths.
    if now - shot.at < math.max(cadence, MM2.SHOT_OBSERVE) then
      setAutoPhase("observing", "dispatched; watching round death state", shot.player)
      return
    end
    pendingShot = nil
    retryQueued = shot.player
  end

  local target, distance = nearestEnemy(mine)
  if not target then setAutoPhase("armed", "no living enemy") return end
  stickyTarget = target

  -- Stability is about not acting on a role that is still settling, so it asks
  -- whether the TARGET'S OWN role has been steady -- whatever that role is --
  -- rather than whether it equals "Murderer". As the murderer that test could
  -- never pass, which is the second reason the knife never fired.
  local mineStable = roleHeld(LP, mine, 0.08)
  local targetStable = roleHeld(target, combatRole(target), 0.10)
  if not (mineStable and targetStable) then
    setAutoPhase("acquiring", "waiting for stable role evidence", target, distance)
    return
  end
  local ready = usingKnife and MM2.knifeReady() or MM2.gunReady()
  if not ready then
    setAutoPhase("cooldown", usingKnife and "swing recovery" or "gun recovery",
                 target, distance)
    return
  end

  local before = usingKnife and lastStab or lastShot
  local ok, why, dispatch = MM2.strike(target)
  if not ok then
    setAutoPhase("waiting", why, target, distance)
    return
  end
  -- Defensive: a future weapon path that forgets the dispatch table should
  -- degrade to "no telemetry", not throw inside the controller and land the
  -- whole loop in its error branch once every tick.
  dispatch = dispatch or { at = os.clock(), range = distance }
  local interval = before > 0 and dispatch.at - before or nil
  MM2.autoKillInfo.lastDispatch = dispatch.at
  MM2.autoKillInfo.lastInterval = interval
  if retryQueued == target then
    MM2.shotStats.retryDispatches = MM2.shotStats.retryDispatches + 1
  end
  retryQueued = nil
  pendingShot = { player = target, character = target.Character, at = dispatch.at }
  setAutoPhase("observing", "shot dispatched; watching local death evidence", target, dispatch.range)
end
MM2.autoKillStep = autoKillStep

L.hold(LP.CharacterAdded:Connect(function()
  table.clear(gunMotion)
  table.clear(roleSeen)
  MM2._sweptThisLife = nil        -- one sweep confirmation per life
  clearAutoState("local character changed")
end))

-- THE REFERENCE AUTO-KILL, COPIED. Not adapted, not improved.
--
-- Everything I inferred on top of this made it worse, so it is now a direct
-- port of the open-source script's murderer path:
--
--     if role=="Murderer" then
--         local knife=findWeapon("Knife"); local ev=knife and knife:FindFirstChild("Events")
--         if ev then equip(knife)
--             for _,tgt in ipairs(list) do knifeKill(ev,tgt.Character) end
--         end
--     end
--
-- and their knifeKill, which touches every part and THEN fires KnifeStabbed:
--
--     for _,pn in ipairs(KNIFE_PARTS) do
--         local part=targetChar:FindFirstChild(pn); if part then ht:FireServer(part) end
--     end
--     if ks then ks:FireServer() end
--
-- Their `enemies()` for a murderer is every living player that is not you --
-- no role filter, no distance filter, no line-of-sight check. Kept as-is.
-- A real swing reaches a few studs. Anything past this is a touch that could
-- not physically have happened, so claiming it is pure cost.
-- SWING BEFORE CONTACT, BECAUSE THE WINDOW IS WHAT MATTERS.
--
-- This was 8 studs, chosen as "roughly how far a real swing reaches" back when
-- the module hand-fired HandleTouched and a claimed touch past arm's length was
-- a lie worth not telling. That reasoning does not survive the move to a real
-- swing, and it was costing kills.
--
-- KnifeClient gates the touch on a TIMER, not a distance:
--
--     Handle.Touched:Connect(function(part)
--         if os.clock() - u4 > 0.85 then return end   -- u4 = last stab
--
-- So a stab opens an 0.85 s window and any GENUINE touch inside it counts. Wait
-- until they are within 8 studs and you swing at the moment of contact, after
-- which the animation and the 0.85 s recovery both have to play out before the
-- next one -- so the actual collision often lands in the dead time between
-- swings. Swing while closing instead and the window is already open when you
-- arrive.
--
-- 14 is a little over one swing-recovery of walking (WalkSpeed 16 covers ~13.6
-- studs in 0.85 s), so the window stays continuously open from the moment a
-- target is worth chasing. Nothing is claimed that did not happen: the touch is
-- still the engine's, resolved by real contact.
MM2.KNIFE_REACH = 14

-- The knife's own client refuses to swing again inside 0.85 s
-- (KnifeClient.stabKnife: `if os.clock() - u4 < 0.85 then return end`), so
-- sweeping at 20 Hz produced ~17 swings the weapon could never make, per second.
MM2.KNIFE_SWING = 0.85
local lastSweep = 0

-- WHAT THIS USED TO COST, MEASURED ON THE WIRE.
--
-- A namecall recorder caught one 0.11 s window of the old sweep:
--
--   167.67  KnifeStabbed
--   167.68  KnifeStabbed
--   167.69  HandleTouched  d=39.3  owner=cwutieemi
--   167.70  HandleTouched  d=39.0
--   167.71  HandleTouched  d=39.3
--   167.73  HandleTouched  d=38.9
--   167.74  KnifeStabbed
--   167.75  KnifeStabbed
--   167.76  HandleTouched  d=40.2  owner=AIlyox
--
-- Two KnifeStabbed plus four or five HandleTouched for EVERY living player,
-- twenty times a second. At eight players that is over a thousand remote calls
-- per second, and it visibly cost the operator frames.
--
-- Every distance in that capture is 38-40 studs. Not one of those calls could
-- ever have been honoured, and the tally over 167 seconds was 300 KnifeStabbed,
-- hundreds of touches, and zero deaths.
--
-- So: only claim touches that are physically plausible, send one stab rather
-- than two, and pace to the weapon's real swing. This is a cost fix, not a kill
-- fix -- raw remotes have never been observed to kill, including at 2 studs
-- with a genuine Tool:Activate() swing.
-- THE SWING IS THE GAME'S, NOT OURS. THIS IS THE WHOLE FIX.
--
-- Every previous version of this function fired the knife's remotes by hand --
-- KnifeStabbed, then HandleTouched once per body part. The tally across this
-- module's whole life is roughly 300 KnifeStabbed, several hundred touches, and
-- ZERO deaths. Not "unreliable": zero. Including at two studs, in the open,
-- against a stationary target.
--
-- The open-source hub the operator found does something different, and it is
-- the one thing none of the rewrites tried: it never touches the remotes. It
-- makes the ENGINE produce a click, and the game's own KnifeClient does
-- everything else -- its own reach test, its own animation, its own remote call
-- with its own arguments in its own order. Whatever the server checks, a swing
-- that came from KnifeClient passes it by construction, because it is
-- indistinguishable from the player swinging.
--
-- That reference also teleports you onto each victim in turn, and that half is
-- deliberately NOT here -- the operator does not want it and it is what makes
-- that script obvious to anyone watching. The two halves are independent: the
-- teleport puts a body in range, the click swings. Dropping the teleport costs
-- reach, which is exactly what a knife is supposed to cost, and keeps the part
-- that actually lands the kill.
--
-- So: no remote is fired here any more. We check that someone is genuinely
-- within the knife's real reach, and then we click, for real.
local function swingForReal(knife)
  -- Real engine input first. This is what the reference proves works, and it is
  -- the only option that reaches a KnifeClient bound to UserInputService or
  -- ContextActionService rather than to Tool.Activated -- which would explain
  -- why Tool:Activate() alone never killed either.
  if VirtualUser then
    local cam = workspace.CurrentCamera
    local at = cam and cam.CFrame or CFrame.new()
    local pt = clickPoint()
    local ok = pcall(function()
      VirtualUser:Button1Down(pt, at)
      VirtualUser:Button1Up(pt, at)
    end)
    if ok then return "input" end
  end
  -- Fallback for executors with no VirtualUser. Fires Tool.Activated, which is
  -- strictly less real than the above but still the game's own code path.
  if pcall(function() knife:Activate() end) then return "activate" end
  return nil
end

function MM2.knifeSweep()
  if os.clock() - lastSweep < MM2.KNIFE_SWING then return 0, "swing recovery" end

  local knife = findWeapon("Knife")
  if not knife then return 0, "no knife" end

  local hrp = hrpOf(LP.Character)
  if not hrp then return 0, "no root part" end

  -- Nearest living enemy, measured before anything is equipped or sent, so a
  -- tick with nobody near costs one distance check per player and nothing else.
  local near, nearD
  for _, p in ipairs(Players:GetPlayers()) do
    if p ~= LP and MM2.alive(p) then
      local tp = hrpOf(p.Character)
      if tp then
        local d = (tp.Position - hrp.Position).Magnitude
        if not nearD or d < nearD then near, nearD = p, d end
      end
    end
  end
  if not near then return 0, "no living enemy" end

  -- REACH IS NOT NEGOTIABLE NOW. With the remotes gone there is nothing to gain
  -- by claiming a touch we could not make: the swing either connects in the
  -- game's own reach test or it does not, and swinging early just burns the
  -- 0.85 s the weapon makes us wait afterwards. So hold until they are close.
  if nearD > MM2.KNIFE_REACH then
    MM2.knifeBlocked = string.format("%s is %.0f studs away -- knife reaches %d",
                                     near.Name, nearD, MM2.KNIFE_REACH)
    return 0, MM2.knifeBlocked
  end
  MM2.knifeBlocked = nil

  local equipped, why = equip(knife)
  if not equipped then return 0, why end
  lastSweep = os.clock()

  -- The toggle exists so the claim above is falsifiable rather than just
  -- asserted: switch it off and you get the old hand-fired remotes back, on the
  -- same target at the same range, and can watch them not kill.
  local how
  if MM2.cfg.realSwing then
    how = swingForReal(knife)
    if not how then return 0, "this executor cannot produce a swing" end
  else
    local ok, kwhy = MM2.knifeKill(near.Character, true)
    if not ok then return 0, kwhy or "remote stab refused" end
    how = "remotes"
  end

  markStab()
  MM2.sweepCount = (MM2.sweepCount or 0) + 1
  MM2.lastSwing = { at = os.clock(), how = how, target = near.Name, range = nearD }
  if not MM2._sweptThisLife then
    MM2._sweptThisLife = true
    L.Toast.ok("Auto kill", string.format("swinging at %s (%s)", near.Name, how))
  end
  return 1, string.format("%s at %.1f studs (%s)", near.Name, nearD, how)
end

-- SHERIFF, REWRITTEN AGAINST THE GAME'S OWN CODE INSTEAD OF AGAINST A GUESS.
--
-- Decompiled Gun/GunClient.lua and ClientServices/WeaponService. What a real
-- shot is, exactly:
--
--     v13 = Character.HumanoidRootPart.GunRaycastAttachment.WorldCFrame
--     v12 = WeaponService:GetMouseTargetCFrame()      -- CFrame.new(hit.Position)
--     Parent.Shoot:FireServer(v13, v12)
--
-- The client has NO branch that sends anything else. The origin is always on
-- the shooter's own body.
--
-- MEASURED, THIS SESSION, AND IT SETTLES THE WALLBANG QUESTION FOR GOOD:
-- 744 shots were sent with the reference's synthesised origin -- two studs from
-- the victim, looking at them -- at a murderer 32-80 studs away who was behind
-- `Workspace.BeachResort.Map.Part` the whole time. Dispatch errors: 0.
-- Kills: 0. If the server honoured the origin we send, every one of those was a
-- point-blank hit. It does not. It checks.
--
-- So the open-source reference's `if true then` fake-origin branch is dead code
-- against the current game, and no amount of copying it will make it kill.
-- What is left is worth having: the honest shot, fired the instant a line
-- exists, aimed at whichever part is actually exposed. Reaction time and aim
-- are things a human loses; line of sight is not something anyone can fake.

-- Ordered by how much of a kill each part is worth against how often it is the
-- exposed one. Head first: over cover it is frequently the only thing showing.
local AIM_PARTS = {
  "Head", "UpperTorso", "HumanoidRootPart", "Torso", "LowerTorso",
  "RightUpperArm", "LeftUpperArm", "RightUpperLeg", "LeftUpperLeg",
}

-- A LOCAL COPY OF THE GAME'S OWN RAYCAST, NOT AN APPROXIMATION OF IT.
--
-- WeaponService.WeaponRaycast: ignore list starts with the shooter's character
-- plus everything tagged WeaponPassthrough, then it LOOPS -- each time it hits
-- a part with Transparency == 1 it adds it to the ignore list and casts again.
-- Glass, invisible hitboxes and decorative fog do not stop a bullet here, and a
-- checker that treated them as walls would refuse shots that would have landed.
local function weaponRayHits(originPos, part, targetChar)
  local dir = part.Position - originPos
  local dist = dir.Magnitude
  if dist < 0.05 or dist > MM2.GUN_RANGE then return nil end
  local ignore = { LP.Character }
  for _, t in ipairs(CollectionService:GetTagged("WeaponPassthrough")) do
    ignore[#ignore + 1] = t
  end
  local params = RaycastParams.new()
  params.FilterType = Enum.RaycastFilterType.Exclude
  params.IgnoreWater = true
  for _ = 1, 12 do
    params.FilterDescendantsInstances = ignore
    local r = workspace:Raycast(originPos, dir, params)
    if not r then return nil end
    local inst = r.Instance
    if inst and inst:IsDescendantOf(targetChar) then return r.Position end
    if inst and inst:IsA("BasePart") and inst.Transparency == 1 then
      ignore[#ignore + 1] = inst
    else
      return nil
    end
  end
  return nil
end

-- Exposed so the overlay can say WHY it is holding fire rather than just
-- sitting there looking broken.
MM2.gunBlocked = nil
MM2.knifeBlocked = nil

-- COVER FIRE IS PACED, A GENUINE LINE IS NOT.
--
-- Firing at the wall is what a real client does when you aim at someone behind
-- one, so the packet is legitimate and worth sending -- it keeps the gun
-- obviously alive instead of sitting silent, which is what "it's doing nothing"
-- turned out to mean the first time. But it cannot kill, by definition: the
-- bullet stops where the ray stopped.
--
-- Measured on the run that proved the dispatch fix: 204 shots in 40 seconds,
-- every one into cover, at six a second. That is 200 packets buying nothing but
-- noise and a very legible pattern. So cover fire gets a slow cadence and a
-- real line gets the full one -- the instant the murderer steps out, this stops
-- applying and the gun goes to 0.16 s, which is the case already proven to kill.
MM2.COVER_FIRE = 0.75
local lastCoverShot = 0
-- The text of the last refused dispatch, kept because a bare error count is
-- unactionable. Cleared by the next dispatch that succeeds.
MM2.lastShotError = nil
-- What the last knife swing actually was, so "it did nothing" can be checked
-- against whether a swing was even produced and by which path.
MM2.lastSwing = nil


-- WHY THE GUN LOOKED DEAD EVEN ONCE IT WAS WORKING.
--
-- `Shoot:FireServer(origin, target)` is the SERVER half of a shot and nothing
-- else. The bang, the muzzle flash and the arm animation are all played by the
-- game's own GunClient in response to your click -- and firing the remote
-- directly skips every bit of that. So the server was registering 97 shots
-- while the operator's screen showed a character standing still holding a gun,
-- which is exactly the "I don't hear shit happening" this started with.
--
-- This is cosmetic and CLIENT-ONLY on purpose. `Sound:Play()` called from the
-- client does not replicate, and a part created locally under FilteringEnabled
-- exists only here. Nothing below changes a single thing the server is told --
-- it just stops the tool lying to the person holding it.
local function showShot(gun, originPos, hitPos, blocked)
  -- The gun's own sound, found rather than hardcoded: the asset id has changed
  -- across MM2 updates and a stale rbxassetid is a silent failure.
  local snd
  for _, d in ipairs(gun:GetDescendants()) do
    if d:IsA("Sound") and d.SoundId ~= "" then
      local n = d.Name:lower()
      if n:find("fire") or n:find("shot") or n:find("shoot") or n:find("bang") then
        snd = d break
      end
      snd = snd or d
    end
  end
  if snd then pcall(function() snd:Play() end) end

  -- A tracer, so a shot into cover is visibly a shot into cover and the reason
  -- it is not killing anyone is on screen instead of in a log.
  local dist = (hitPos - originPos).Magnitude
  if dist < 0.5 or dist > 2000 then return end
  local ok, beam = pcall(function()
    local p = Instance.new("Part")
    p.Anchored, p.CanCollide, p.CanQuery, p.CanTouch = true, false, false, false
    p.Material = Enum.Material.Neon
    p.Color = blocked and Color3.fromRGB(255, 170, 60) or Color3.fromRGB(120, 255, 140)
    p.Transparency = 0.35
    p.Size = Vector3.new(0.12, 0.12, dist)
    p.CFrame = CFrame.new(originPos:Lerp(hitPos, 0.5), hitPos)
    p.Parent = workspace
    return p
  end)
  if not ok or not beam then return end
  task.spawn(function()
    for i = 1, 6 do
      if not beam.Parent then return end
      beam.Transparency = 0.35 + (i / 6) * 0.65
      RunService.Heartbeat:Wait()
    end
    pcall(function() beam:Destroy() end)
  end)
end

-- THE REAL TRIGGER PULL, AND THE ONE PLACE A FLICK IS ALLOWED.
--
-- Same principle as the knife: the most legitimate packet is the one the game's
-- own client builds. MM2's GunClient reads the CAMERA at the moment of the
-- click -- WeaponService raycasts from it -- so unlike the knife, a synthetic
-- click is only useful if the camera is already looking at the target.
--
-- That is a flick, and flicking is the thing the operator asked not to have. So
-- it is gated hard: it runs ONLY when there is already a genuine, unobstructed
-- line to the murderer. That is rare -- across several hundred logged shots it
-- had not happened once -- so the camera does not twitch while you play. It
-- moves at the exact moment a kill is on, and not otherwise.
--
-- The camera is NOT snapped back. The player's own camera module writes CFrame
-- every render step from mouse input, so it takes over again by itself on the
-- next frame; forcing it back would be a second flick fighting that, which
-- reads far worse than one.
local lastRealShot = 0
local function shootForReal(aimPos)
  if not VirtualUser then return nil, "no VirtualUser" end
  local cam = workspace.CurrentCamera
  if not cam then return nil, "no camera" end
  -- One synthetic trigger pull per gun cadence, never a burst: VirtualUser
  -- clicks are real input and the client queues them.
  if os.clock() - lastRealShot < MM2.GUN_COOLDOWN then return nil, "paced" end
  local shotCF = CFrame.new(cam.CFrame.Position, aimPos)
  local pt = clickPoint()
  local ok = pcall(function()
    cam.CFrame = shotCF
    VirtualUser:Button1Down(pt, shotCF)
    VirtualUser:Button1Up(pt, shotCF)
  end)
  if not ok then return nil, "click refused" end
  lastRealShot = os.clock()
  return "click"
end

function MM2.gunSweep()
  if not MM2.gunReady() then return 0, "gun recovery" end
  local gun = findWeapon("Gun")
  if not gun then return 0, "no gun" end
  local shoot = gun:FindFirstChild("Shoot")
  if not isRemoteEvent(shoot) then return 0, "gun has no Shoot remote" end

  local ch = LP.Character
  local myHrp = hrpOf(ch)
  if not myHrp then return 0, "no root part" end

  local target
  for _, p in ipairs(Players:GetPlayers()) do
    if p ~= LP and MM2.alive(p) and combatRole(p) == "Murderer" then target = p break end
  end
  if not target then return 0, "murderer not identified yet" end
  local tch = target.Character
  if not tch then return 0, "murderer has no body loaded" end

  local equipped, why = equip(gun)
  if not equipped then return 0, why end
  if gun.Parent ~= LP.Character then return 0, "gun did not stay equipped" end

  -- The exact origin GunClient sends. No fallback: if the attachment is not
  -- there the real client cannot shoot either, and inventing one is the lie the
  -- server rejects.
  local att = myHrp:FindFirstChild("GunRaycastAttachment")
  if not (att and att:IsA("Attachment")) then
    return 0, "GunRaycastAttachment not ready"
  end
  local origin = att.WorldCFrame
  local originPos = origin.Position

  -- Take the first part the game's own raycast would reach. Aiming at the torso
  -- and giving up when the torso is covered throws away every shot where a head
  -- or a shoulder is in the open, which in a map full of cover is most of them.
  local hitPos, hitPart
  for _, pn in ipairs(AIM_PARTS) do
    local part = tch:FindFirstChild(pn)
    if part and part:IsA("BasePart") then
      local at = weaponRayHits(originPos, part, tch)
      if at then hitPos, hitPart = at, pn break end
    end
  end

  -- WHY THROUGH-WALL FIRE IS GONE, PROVED SIDE BY SIDE ON THE WIRE.
  --
  -- A namecall recorder captured the operator's own manual clicks (caller=GAME)
  -- interleaved with this module's auto shots (caller=US), same second, same
  -- gun:
  --
  --   50.13  GAME  origin d=3.9 | target CFrame(661,298,9845)  d=3.7
  --   50.63  US    origin d=3.9 | target CFrame(540,286,9716)  d=183.9
  --
  -- The origins are identical, so that argument was never the problem. The
  -- second argument is. WeaponService builds it from
  --     Ray.new(camera.Origin, camera.Direction * 300)
  -- and returns WHERE THE RAY STOPPED. A real client shooting at a wall reports
  -- the wall, 3.7 studs out. It is not capable of reporting a hit 184 studs away
  -- behind that wall, because its own ray terminated on the near side.
  --
  -- So a through-wall packet is not a long shot the server happens to dislike --
  -- it is a claim no honest client can generate, and it is trivially checkable.
  -- That is consistent with every measurement: 744 forged-origin shots, 0 kills;
  -- 238 blind honest-origin shots, 0 kills; and the single confirmed kill coming
  -- from the version that only fired on a genuine line.
  --
  -- SO SHOOT THE WALL, EXACTLY LIKE THE REAL CLIENT DOES.
  --
  -- Holding fire entirely was the other overcorrection: the gun then sits
  -- silent for whole rounds and looks broken, which is precisely what the
  -- operator reported. But the fix is not to send an impossible packet -- it is
  -- to send the packet a real client WOULD send.
  --
  -- GetMouseTargetCFrame returns `CFrame.new(raycastResult.Position)`, i.e.
  -- wherever the ray actually stopped. Aim at a murderer behind a wall and a
  -- genuine client reports THE WALL. So do that: cast at them, and claim the
  -- first thing the ray hits.
  --
  -- This is strictly better than both previous versions:
  --   * the packet is legitimate, so the server has no reason to drop it
  --   * the gun visibly and audibly fires, every cycle, so it is obviously alive
  --   * the moment the murderer steps clear the ray reaches THEM instead of the
  --     wall, and that is the case already proven to kill -- no extra logic and
  --     no delay, it just starts landing.
  local blocked = false
  if not hitPos then
    blocked = true
    if not MM2.cfg.coverFire then
      MM2.gunBlocked = string.format("%s is behind cover -- holding", target.Name)
      return 0, MM2.gunBlocked
    end
    if os.clock() - lastCoverShot < MM2.COVER_FIRE then
      return 0, "cover fire paced"
    end
    local aim = aimPointFor(target)
    if not aim then return 0, "murderer has no aim point" end
    local params = RaycastParams.new()
    params.FilterType = Enum.RaycastFilterType.Exclude
    params.FilterDescendantsInstances = { LP.Character }
    params.IgnoreWater = true
    local r = workspace:Raycast(originPos, aim - originPos, params)
    -- Ray reached nothing: report its endpoint, which is what the real client
    -- does when it hits open air (`v13.Origin + v13.Direction`).
    hitPos = r and r.Position or aim
    hitPart = "wall"
  end
  MM2.gunBlocked = blocked
    and string.format("%s covered at %.0f studs -- firing at cover",
                      target.Name, ((aimPointFor(target) or originPos) - originPos).Magnitude)
    or nil

  -- Second argument is CFrame.new(hitPosition) -- the same shape WeaponService
  -- builds from its own raycast result, not a lookAt and not the part centre.
  -- A CLEAR LINE IS THE ONLY TIME THE REAL CLIENT IS WORTH INVOLVING.
  --
  -- On a genuine line, let the game pull its own trigger: it plays the shot,
  -- builds its own arguments from its own raycast, and sends a packet that is
  -- not merely legitimate but literally the game's. If that path is available
  -- we are done -- sending our remote as well would be two shots claiming one
  -- trigger pull, which is the shape the server is most likely to punish.
  if not blocked and MM2.cfg.realShot then
    local how = shootForReal(hitPos)
    if how then
      markShot()
      MM2.shotStats.dispatched = MM2.shotStats.dispatched + 1
      MM2.sweepCount = (MM2.sweepCount or 0) + 1
      MM2.lastShotError = nil
      MM2.gunBlocked = nil
      return 1, string.format("%s (%s, real trigger)", target.Name, hitPart)
    end
  end

  local ok, err = pcall(function() shoot:FireServer(origin, CFrame.new(hitPos)) end)
  if not ok then
    MM2.shotStats.errors = MM2.shotStats.errors + 1
    -- KEEP THE TEXT, not just the tally. A previous session ended with
    -- "disp=0 err=24" on screen and no way to tell what threw 24 times, which
    -- is a counter that can only ever tell you that you are stuck.
    MM2.lastShotError = tostring(err)
    return 0, "Shoot dispatch failed: " .. tostring(err)
  end
  MM2.lastShotError = nil
  markShot()
  if blocked then lastCoverShot = os.clock() end
  if MM2.cfg.shotFeedback then
    L.try("mm2.showShot", showShot, gun, originPos, hitPos, blocked)
  end
  MM2.shotStats.dispatched = MM2.shotStats.dispatched + 1
  MM2.sweepCount = (MM2.sweepCount or 0) + 1
  if not MM2._sweptThisLife then
    MM2._sweptThisLife = true
    L.Toast.ok("Auto kill", "firing on " .. target.Name)
  end
  return 1, target.Name .. " (" .. hitPart .. ")"
end

local autoKillLoop
local function ensureAutoKill()
  if autoKillLoop then return end
  autoKillLoop = task.spawn(function()
    while L.live() do
      task.wait(0.05)
      if not L.live() then break end
      local ok, why = pcall(autoKillStep)
      if not ok then
        MM2.shotStats.errors = MM2.shotStats.errors + 1
        setAutoPhase("error", tostring(why))
        task.wait(0.20)
      end
    end
  end)
end

-- ---------------------------------------------------------------- esp overlay
--
-- Its own folder rather than hanging highlights off the parts themselves, so
-- unloading is one Destroy and a game that rebuilds the map cannot strand them.

local espHost
local function ensureEspHost()
  if espHost and espHost.Parent then return espHost end
  espHost = mk("Folder", { Name = "LumenMM2Esp", Parent = L.host() })
  L.own(espHost)
  return espHost
end

local function highlight(adornee, fill, outline, alpha)
  return mk("Highlight", {
    Adornee = adornee, FillColor = fill, FillTransparency = alpha or 0.35,
    OutlineColor = outline, OutlineTransparency = 0,
    DepthMode = Enum.HighlightDepthMode.AlwaysOnTop,
    Parent = ensureEspHost(),
  })
end

local function billboard(adornee, text, colour, yOffset)
  local bb = mk("BillboardGui", {
    Adornee = adornee, Size = UDim2.fromOffset(110, 16), AlwaysOnTop = true,
    StudsOffsetWorldSpace = Vector3.new(0, yOffset or 2, 0),
    Parent = ensureEspHost(),
  })
  local lbl = A.text({
    Text = text, font = T.font.strong, size = T.size.nano, colour = colour,
    align = Enum.TextXAlignment.Center, Size = UDim2.fromScale(1, 1), Parent = bb,
  })
  lbl.TextStrokeTransparency = 0.4
  return bb, lbl
end

-- ---- coins ----------------------------------------------------------------

-- ---- THE FREEZE, AND WHY IT ONLY HAPPENED SOMETIMES ------------------------
--
-- `workspace:FindFirstChild(name, true)` is RECURSIVE -- it walks every
-- descendant of the workspace, and an MM2 map is tens of thousands of
-- instances. The lookup is cached, so while the container exists this costs
-- nothing and the whole thing looks fine.
--
-- Between rounds the container does not exist. The cache never fills, so the
-- full walk ran on EVERY tick of both the overlay loop (0.15 s) and the pickup
-- loop (0.25 s) -- roughly eleven full workspace traversals a second, for the
-- entire map-loading stretch. That is the stutter, and it is why it came and
-- went with the round rather than with anything the operator did.
--
-- Fixed twice over: search only the shallow places the container is actually
-- parented, and rate-limit the miss so a genuine absence costs one look a
-- second instead of eleven.
local coinContainer, lastCoinLook = nil, 0
local fullCoinBags, activeCoinBags = {}, {}
local coinBagFull = false

local function coinBagKey(coin)
  local id = coin and coin:GetAttribute("CoinID")
  return id ~= nil and tostring(id) or nil
end

local function allActiveCoinBagsFull()
  local any = false
  for id in pairs(activeCoinBags) do
    any = true
    if not fullCoinBags[id] then return false end
  end
  return any
end
local function findCoinContainer()
  local direct = workspace:FindFirstChild("CoinContainer")   -- non-recursive
  if direct then return direct end
  -- one level down, which is where a map-parented container lives
  for _, d in ipairs(workspace:GetChildren()) do
    if d:IsA("Model") or d:IsA("Folder") then
      local hit = d:FindFirstChild("CoinContainer")
      if hit then return hit end
    end
  end
  return nil
end

local function coinList()
  if not (coinContainer and coinContainer.Parent) then
    local now = os.clock()
    if now - lastCoinLook < 1.0 then return {} end
    lastCoinLook = now
    coinContainer = findCoinContainer()
  end
  local out = {}
  if coinContainer then
    for _, d in ipairs(coinContainer:GetChildren()) do
      if d:IsA("BasePart")
         and (d:GetAttribute("CoinID") ~= nil or d.Name == "Coin_Server") then
        local taken = d:GetAttribute("Collected")
        local bag = coinBagKey(d)
        if not (taken == true or taken == "true")
           and not (bag and fullCoinBags[bag]) then
          out[#out + 1] = d
        end
      end
    end
  end
  return out
end
MM2.coins = coinList

function MM2.nearestCoin()
  local hrp = hrpOf(LP.Character)
  if not hrp then return nil end
  local best, bestD
  for _, c in ipairs(coinList()) do
    local d = (c.Position - hrp.Position).Magnitude
    if not bestD or d < bestD then best, bestD = c, d end
  end
  return best, bestD
end

-- ---- dropped gun ----------------------------------------------------------

-- THE SECOND FULL WALK, AND THE WORSE OF THE TWO.
--
-- The fallback here was `workspace:GetDescendants()` -- which does not just
-- traverse the map, it ALLOCATES A TABLE of every instance in it. The tag
-- lookup above almost always succeeds, so the fallback looked harmless; but a
-- dropped gun only exists after the sheriff dies, which means for most of every
-- round there is nothing tagged and the fallback ran on every single tick of
-- the overlay loop. Tens of thousands of instances, six times a second, into a
-- table that is thrown away immediately. That is the multi-second freeze.
--
-- Now: tags first, then a cached direct reference, and a hard rate limit on the
-- miss. No unbounded traversal on any path.
-- THE NAME "GunDrop" IS NOT PROOF OF A GUN.
--
-- Measured live: this returned a part 9,095 studs away inside
-- `Workspace.MilBase` -- permanent map scenery that happens to carry the name.
-- Auto-grab then teleported across the map to a decoration, picked up nothing,
-- and `gunCache` latched onto it forever because the cache only checks
-- `.Parent`, which scenery always has. Every later look returned the prop.
--
-- Two guards, because either alone still fails:
--   REACH  -- a real drop appears where the sheriff died, i.e. in play. Nothing
--             thousands of studs away is a pickup, so distance disqualifies it.
--   PROOF  -- a candidate that does not actually yield a gun is blacklisted, so
--             one bad match costs one attempt instead of the whole round.
local gunCache, lastGunLook = nil, 0
local gunReject = {}
MM2.GUN_DROP_REACH = 1200

function MM2.rejectGunCandidate(part)
  if part then gunReject[part] = true end
  if gunCache == part then gunCache = nil end
end

local function gunCandidateOk(part)
  if not (part and part:IsA("BasePart") and part.Parent) then return false end
  if gunReject[part] then return false end
  local hrp = hrpOf(LP.Character)
  if hrp and (part.Position - hrp.Position).Magnitude > MM2.GUN_DROP_REACH then
    return false
  end
  return true
end

function MM2.findDroppedGun()
  if gunCache and gunCandidateOk(gunCache) then return gunCache end
  gunCache = nil
  for _, p in ipairs(CollectionService:GetTagged("GunDrop")) do
    if gunCandidateOk(p) then gunCache = p return p end
    local g = p:FindFirstChild("GunDrop")
    if gunCandidateOk(g) then gunCache = g return g end
  end
  -- Not tagged. Look shallowly, and at most once a second -- a miss is the
  -- common case, so it is the one that has to be cheap.
  local now = os.clock()
  if now - lastGunLook < 1.0 then return nil end
  lastGunLook = now
  for _, d in ipairs(workspace:GetChildren()) do
    if d:IsA("BasePart") and d.Name == "GunDrop" and gunCandidateOk(d) then
      gunCache = d return d
    end
    if d:IsA("Model") or d:IsA("Folder") then
      local hit = d:FindFirstChild("GunDrop")
      if gunCandidateOk(hit) then gunCache = hit return hit end
    end
  end
  return nil
end

local relocationTokens = {}
local activeRelocation
MM2.relocationDepth = 0
MM2.relocating = false

local function beginRelocation(root, home)
  if MM2.relocationDepth > 0 then return nil, "another relocation is active" end
  if gunTransaction or MM2.shotPreparing then
    return nil, "a sheriff shot is being prepared"
  end
  if combatPhysicsBusy() then return nil, "a target fling is active or recovering" end
  root = root or hrpOf(LP.Character)
  if not root then return nil, "you have no character" end
  local token = {
    root = root,
    character = LP.Character,
    home = home or root.CFrame,
    cancelled = false,
  }
  relocationTokens[token] = true
  activeRelocation = token
  MM2.relocationDepth = MM2.relocationDepth + 1
  MM2.relocating = true
  return token
end

local function relocationActive(token)
  return L.live() and relocationTokens[token] == true and not token.cancelled
      and activeRelocation == token and token.root and token.root.Parent
      and LP.Character == token.character
end

local function endRelocation(token)
  if not relocationTokens[token] then return end
  relocationTokens[token] = nil
  if activeRelocation == token then activeRelocation = nil end
  MM2.relocationDepth = math.max(0, MM2.relocationDepth - 1)
  MM2.relocating = MM2.relocationDepth > 0
end

local function cancelRelocation(token, restore)
  if not token or not relocationTokens[token] then return false end
  token.cancelled = true
  if restore and token.root and token.root.Parent
     and LP.Character == token.character then
    pcall(function()
      token.root.CFrame = token.home
      token.root.AssemblyLinearVelocity = Vector3.zero
      token.root.AssemblyAngularVelocity = Vector3.zero
    end)
  end
  endRelocation(token)
  return true
end

-- Relocation is a real physics transaction. Retire it before Combat/Movement
-- teardown so no old pickup coroutine can resume after a reload and write its
-- stale `home` into a new fling generation.
L.cleanup(function()
  if activeRelocation then cancelRelocation(activeRelocation, true) end
  for token in pairs(relocationTokens) do
    cancelRelocation(token, false)
  end
end, 110)

function MM2.grabGun()
  if combatPhysicsBusy() then return false, "a target fling is active or recovering" end
  local g = MM2.findDroppedGun()
  if not g then return false, "no gun on the ground" end
  local hrp = hrpOf(LP.Character)
  if not hrp then return false, "you have no character" end
  -- Return to where we were. Picking the gun up is a touch, not a place to
  -- stand, and being left across the map is how a pickup gets you knifed by
  -- the murderer who watched you appear.
  local home = hrp.CFrame
  local relocation, relocationWhy = beginRelocation(hrp, home)
  if not relocation then return false, relocationWhy end
  -- A DROP IS A PROMPT, NOT ONLY A TOUCH.
  --
  -- This teleported on top of the part, waited 0.18 s and hoped a Touched fired.
  -- MM2 hands out pickups through ProximityPrompt -- the map's own KnifePrompt
  -- is built the same way -- and a prompt does not care that you are standing on
  -- it, it wants an activation. That is why the trip kept succeeding and the
  -- hands kept coming back empty.
  --
  -- So: stand on it, HOLD the position across real replicated frames so the
  -- server agrees we are there, and fire any prompt we can find on the way. The
  -- touch path still works for drops that use one; the prompt path covers the
  -- rest.
  local prompt = g:FindFirstChildWhichIsA("ProximityPrompt")
    or (g.Parent and g.Parent:FindFirstChildWhichIsA("ProximityPrompt", true))
  local firePrompt = rawget(getgenv(), "fireproximityprompt")
  local ok, why = pcall(function()
    if not relocationActive(relocation) then return end
    local stand = CFrame.new(g.Position)
    local deadline = os.clock() + 0.40
    local fired = false
    repeat
      if not relocationActive(relocation) then return end
      -- Re-assert every frame: one write can be swallowed by the physics step
      -- that follows it, and then the server never saw us next to the drop.
      hrp.CFrame = stand
      hrp.AssemblyLinearVelocity = Vector3.zero
      RunService.Heartbeat:Wait()
      if prompt and firePrompt and not fired then
        fired = true
        pcall(firePrompt, prompt, 0)
      end
      if findWeapon("Gun") then break end
    until os.clock() > deadline
    if relocationActive(relocation) then
      hrp.CFrame = home
      hrp.AssemblyLinearVelocity = Vector3.zero
      hrp.AssemblyAngularVelocity = Vector3.zero
    end
  end)
  local completed = relocationActive(relocation)
  if not ok then
    cancelRelocation(relocation, true)
    return false, tostring(why)
  end
  endRelocation(relocation)
  if not completed then return false, "pickup relocation was cancelled" end

  -- SUCCESS IS HOLDING A GUN, NOT HAVING TRAVELLED.
  --
  -- This used to return true whenever the relocation finished, so a trip to a
  -- piece of map scenery reported success and the caller believed it. Measured:
  -- `GRABGUN ok=true` immediately followed by `gunHeld=false`. A pickup that
  -- cannot tell you whether it picked anything up is worse than no pickup.
  --
  -- The touch is resolved by the server, so give it a moment before judging --
  -- then blacklist the candidate so auto-grab moves on instead of teleporting
  -- to the same decoration every tick.
  local deadline = os.clock() + 0.45
  repeat
    if findWeapon("Gun") then return true end
    task.wait(0.05)
  until os.clock() > deadline

  MM2.rejectGunCandidate(g)
  return false, "reached the pickup but no gun was acquired"
end

local function coinEligible(coin)
  if not (coin and coin.Parent and coin:IsA("BasePart")) then return false end
  local taken = coin:GetAttribute("Collected")
  local bag = coinBagKey(coin)
  return taken ~= true and taken ~= "true" and not (bag and fullCoinBags[bag])
end

local function routeCoins(from, candidates, limit)
  local route, used, cursor = {}, {}, from
  for _ = 1, math.min(limit, #candidates) do
    local pick, pickD
    for _, coin in ipairs(candidates) do
      if not used[coin] and coinEligible(coin) then
        local d = (coin.Position - cursor).Magnitude
        if not pickD or d < pickD then pick, pickD = coin, d end
      end
    end
    if not pick then break end
    used[pick] = true
    route[#route + 1] = pick
    cursor = pick.Position
  end
  return route
end

-- One generation-bound movement transaction drives both the button and auto
-- collect. Each touch is held across two replication frames; zero-frame hops
-- were quick on our screen but intermittently never reached the server.
local function collectCoinBatch(limit)
  if game.PlaceId ~= MM2.PLACE then return false, "not in Murder Mystery 2" end
  local character = LP.Character
  local hrp = hrpOf(character)
  if not (hrp and freshAlive(LP, character)) then return false, "you are not alive" end
  local candidates = coinList()
  if #candidates == 0 then return false, coinBagFull and "active coin bags are full" or "no coins left" end
  local home = hrp.CFrame
  local route = routeCoins(home.Position, candidates, math.max(1, limit or 1))
  if #route == 0 then return false, "no eligible coins left" end

  local relocation, relocationWhy = beginRelocation(hrp, home)
  if not relocation then return false, relocationWhy end
  local fireTouch = rawget(getgenv(), "firetouchinterest")
  local collected = 0
  local ok, why = pcall(function()
    for _, coin in ipairs(route) do
      if not relocationActive(relocation) or not freshAlive(LP, character) then break end
      if coinEligible(coin) then
        hrp.CFrame = CFrame.new(coin.Position)
        hrp.AssemblyLinearVelocity = Vector3.zero
        hrp.AssemblyAngularVelocity = Vector3.zero
        if type(fireTouch) == "function" then
          pcall(fireTouch, hrp, coin, 0)
        end
        RunService.Heartbeat:Wait()
        if type(fireTouch) == "function" and coin.Parent then
          pcall(fireTouch, hrp, coin, 1)
        end
        RunService.Heartbeat:Wait()
        collected = collected + 1
      end
    end
    if relocationActive(relocation) then
      hrp.CFrame = home
      hrp.AssemblyLinearVelocity = Vector3.zero
      hrp.AssemblyAngularVelocity = Vector3.zero
    end
  end)
  local completed = relocationActive(relocation)
  if not ok then
    cancelRelocation(relocation, true)
    return false, tostring(why)
  end
  endRelocation(relocation)
  if not completed then return false, "coin relocation was cancelled" end
  if collected == 0 then return false, "coins disappeared before contact" end
  return true, collected
end

MM2.collectCoins = collectCoinBatch
function MM2.collectNearestCoin()
  return collectCoinBatch(1)
end

-- ---- one loop drives every overlay ----------------------------------------
--
-- One pass rather than three. Each overlay is a handful of instances; what
-- costs is walking the workspace, and doing that once for coins, guns and traps
-- together is the difference the reference script's own changelog calls out as
-- an optimisation.

local coinHl, gunHl, gunTag, trapHl, roleHl = {}, nil, nil, {}, {}

local function clearMap(store)
  for k, v in pairs(store) do pcall(function() v:Destroy() end) store[k] = nil end
end

local function destroyRoleEsp(rec)
  if not rec then return end
  pcall(function() rec.hl:Destroy() end)
  pcall(function() rec.bb:Destroy() end)
end

local function clearRoleEsp()
  for plr, rec in pairs(roleHl) do destroyRoleEsp(rec) roleHl[plr] = nil end
end

task.spawn(function()
  while L.live() do
    task.wait(0.15)
    if not L.live() then break end
    if game.PlaceId ~= MM2.PLACE then
      if next(coinHl) then clearMap(coinHl) end
      if next(roleHl) then clearRoleEsp() end
      if gunHl then pcall(function() gunHl:Destroy() end) gunHl = nil end
      if gunTag then pcall(function() gunTag:Destroy() end) gunTag = nil end
      if next(trapHl) then
        for part, rec in pairs(trapHl) do
          pcall(function() rec.hl:Destroy() end)
          pcall(function() rec.bb:Destroy() end)
          trapHl[part] = nil
        end
      end
    else
      -- coins
      if MM2.cfg.coinEsp then
        local seen = {}
        for _, coin in ipairs(coinList()) do
          seen[coin] = true
          if not coinHl[coin] then
            local vis = coin:FindFirstChild("CoinVisual")
            local ad = (vis and vis:FindFirstChild("MainCoin")) or vis or coin
            coinHl[coin] = highlight(ad, Color3.fromRGB(255, 205, 55),
                                     Color3.fromRGB(255, 235, 150), 0.25)
          end
        end
        for coin, hl in pairs(coinHl) do
          if not seen[coin] or not coin.Parent then
            pcall(function() hl:Destroy() end) coinHl[coin] = nil
          end
        end
      elseif next(coinHl) then
        clearMap(coinHl)
      end

      -- dropped gun
      if MM2.cfg.gunEsp then
        local g = MM2.findDroppedGun()
        if g then
          local gunFill, gunOutline = gunEspColours()
          if not (gunHl and gunHl.Parent) then
            gunHl = highlight(g, gunFill, gunOutline, 0.2)
            local bb = billboard(g, "GUN", gunOutline, 2.4)
            gunTag = bb
          else
            gunHl.Adornee = g
            gunHl.FillColor = gunFill
            gunHl.OutlineColor = gunOutline
            if gunTag then gunTag.Adornee = g end
          end
          local gunLbl = gunTag and gunTag:FindFirstChildWhichIsA("TextLabel")
          if gunLbl then gunLbl.TextColor3 = gunOutline end
          if gunTag and MM2.cfg.gunEspDist then
            local hrp = hrpOf(LP.Character)
            if hrp and gunLbl then
              gunLbl.Text = string.format("GUN  %dm",
                math.floor((g.Position - hrp.Position).Magnitude))
            end
          elseif gunLbl then
            gunLbl.Text = "GUN"
          end
        else
          if gunHl then pcall(function() gunHl:Destroy() end) gunHl = nil end
          if gunTag then pcall(function() gunTag:Destroy() end) gunTag = nil end
        end
      else
        if gunHl then pcall(function() gunHl:Destroy() end) gunHl = nil end
        if gunTag then pcall(function() gunTag:Destroy() end) gunTag = nil end
      end

      -- Dedicated role markers work even when the universal ESP is disabled.
      -- Character epochs are explicit so a respawn never leaves a label on an
      -- old rig, and only the two high-value roles consume Highlight slots.
      local roleSeen = {}
      for _, plr in ipairs(Players:GetPlayers()) do
        if plr ~= LP and MM2.alive(plr) then
          local role = MM2.roleOf(plr)
          local wanted = (role == "Murderer" and MM2.cfg.murdererEsp)
                      or (isGunRole(role) and MM2.cfg.sheriffEsp)
          local character = plr.Character
          local anchor = hrpOf(character)
          if wanted and character and anchor then
            roleSeen[plr] = true
            local rec = roleHl[plr]
            if not rec or rec.character ~= character
               or not rec.hl.Parent or not rec.bb.Parent then
              destroyRoleEsp(rec)
              local colour = MM2.colourFor(role)
              local bb, label = billboard(anchor, "", colour, 3.3)
              rec = {
                character = character,
                hl = highlight(character, colour, colour, 0.62),
                bb = bb,
                label = label,
              }
              roleHl[plr] = rec
            end
            local colour = MM2.colourFor(role)
            rec.hl.FillColor, rec.hl.OutlineColor = colour, colour
            rec.bb.Adornee = anchor
            rec.label.TextColor3 = colour
            rec.label.Text = string.format("%s  ·  %s", string.upper(role), plr.DisplayName or plr.Name)
          end
        end
      end
      for plr, rec in pairs(roleHl) do
        if not roleSeen[plr] then destroyRoleEsp(rec) roleHl[plr] = nil end
      end

      -- traps
      for part, rec in pairs(trapHl) do
        if not part.Parent then
          pcall(function() rec.hl:Destroy() end)
          pcall(function() rec.bb:Destroy() end)
          trapHl[part] = nil
        else
          rec.hl.Enabled = MM2.cfg.trapEsp
          rec.bb.Enabled = MM2.cfg.trapEsp
        end
      end
    end
  end
end)

-- Traps are discovered by name as the map builds them, not scanned for.
local function addTrap(part)
  if not L.live() or trapHl[part] or not part:IsA("BasePart") or not part.Parent then return end
  local hl = highlight(part, Color3.fromRGB(255, 90, 255),
                       Color3.fromRGB(255, 170, 255), 0.4)
  hl.Enabled = MM2.cfg.trapEsp
  local bb = billboard(part, "TRAP", Color3.fromRGB(255, 150, 255), 2)
  bb.Enabled = MM2.cfg.trapEsp
  trapHl[part] = { hl = hl, bb = bb }
end

if game.PlaceId == MM2.PLACE then
  task.spawn(function()
    if not L.live() then return end
    for _, d in ipairs(workspace:GetDescendants()) do
      if not L.live() then break end
      if d.Name == "TrapVisual" then addTrap(d) end
    end
  end)
  L.hold(workspace.DescendantAdded:Connect(function(d)
    if L.live() and d.Name == "TrapVisual" then task.defer(addTrap, d) end
  end))
  L.hold(workspace.DescendantRemoving:Connect(function(d)
    local rec = trapHl[d]
    if rec then
      pcall(function() rec.hl:Destroy() end)
      pcall(function() rec.bb:Destroy() end)
      trapHl[d] = nil
    end
  end))
end

-- ---- anti-trap ------------------------------------------------------------
--
-- A trap does not damage you, it SLOWS you -- which is worse, because it holds
-- you still for the murderer. The server tells your own client it happened, so
-- the counter is to keep re-asserting your speed for as long as the effect
-- would have lasted rather than trying to block the event.
task.spawn(function()
  if game.PlaceId ~= MM2.PLACE or not L.live() then return end
  local ts = RS:FindFirstChild("TrapSystem")
  local hit = ts and ts:FindFirstChild("TrapHitLocal")
  if not hit then return end
  L.hold(hit.OnClientEvent:Connect(function()
    if not MM2.cfg.antiTrap then return end
    task.spawn(function()
      local ch = LP.Character
      local hum = ch and ch:FindFirstChildOfClass("Humanoid")
      if not hum then return end
      -- Whatever the operator set stands; 16 only when nothing else is known.
      local wantWalk = 16
      if L.Universal and L.Universal.want and L.Universal.want.walkSpeed then
        wantWalk = L.Universal.want.walkSpeed
      end
      local t0 = os.clock()
      while L.live() and LP.Character == ch
            and os.clock() - t0 < 4.6 and hum.Parent do
        if hum.WalkSpeed < wantWalk then hum.WalkSpeed = wantWalk end
        if hum.JumpPower < 40 then hum.UseJumpPower = true hum.JumpPower = 50 end
        RunService.Heartbeat:Wait()
      end
    end)
  end))
end)

-- ---------------------------------------------------------------- pickups

task.spawn(function()
  if not GameplayR then return end
  local collected = GameplayR:FindFirstChild("CoinCollected")
  local started = GameplayR:FindFirstChild("CoinsStarted")
  if collected then
    L.hold(collected.OnClientEvent:Connect(function(bag, got, cap)
      if type(got) == "number" and type(cap) == "number" and cap > 0 and got >= cap then
        local id = tostring(bag)
        local first = not fullCoinBags[id]
        activeCoinBags[id] = true
        fullCoinBags[id] = true
        coinBagFull = allActiveCoinBagsFull()
        if first and MM2.cfg.autoCoins then
          L.Toast.info("Coin bag full", "Skipping " .. id .. " coins for the rest of this round")
        end
      end
    end))
  end
  if started then
    L.hold(started.OnClientEvent:Connect(function(active)
      table.clear(fullCoinBags)
      table.clear(activeCoinBags)
      if type(active) == "table" then
        for key, value in pairs(active) do
          local id = type(key) == "number" and value or key
          if id ~= nil and value ~= false then activeCoinBags[tostring(id)] = true end
        end
      end
      coinBagFull = false
    end))
  end
end)

function MM2.coinBagStatus()
  local active, full = 0, 0
  for id in pairs(activeCoinBags) do
    active = active + 1
    if fullCoinBags[id] then full = full + 1 end
  end
  return full, active, coinBagFull
end

local pickupLoop
local function ensurePickups()
  if pickupLoop then return end
  pickupLoop = task.spawn(function()
    while L.live() do
      task.wait(0.25)
      if not L.live() then break end
      if game.PlaceId == MM2.PLACE then
        local combatBusy = combatPhysicsBusy()
        if not combatBusy and MM2.cfg.autoCoins and MM2.alive(LP) then
          L.try("mm2.coins", function()
            if #coinList() > 0 then collectCoinBatch(6) end
          end)
        end
        if not combatBusy and MM2.cfg.autoGun and MM2.alive(LP) and not findWeapon("Gun") then
          L.try("mm2.gun", MM2.grabGun)
        end
      end
    end
  end)
end

-- ---------------------------------------------------------------- awareness

-- Roblox tells you your own role through a remote; relaying it is free and it
-- is the single most useful line in the whole hub.
task.spawn(function()
  if not GameplayR then return end
  local give = GameplayR:FindFirstChild("GiveWeapon")
  if not give then return end
  L.hold(give.OnClientEvent:Connect(function(w)
    if w == "Knife" then L.Toast.bad("You are the MURDERER")
    elseif w == "Gun" then L.Toast.ok("You are the SHERIFF") end
  end))
end)

local lastMurderer
task.spawn(function()
  while L.live() do
    task.wait(0.5)
    if not L.live() then break end
    if MM2.cfg.murdererNotify and game.PlaceId == MM2.PLACE then
      local m = MM2.findRole("Murderer")
      local name = m and m.Name or nil
      if name and name ~= lastMurderer then
        lastMurderer = name
        L.Toast.bad("Murderer", (m.DisplayName or m.Name) .. " has the knife")
      elseif not name then
        lastMurderer = nil
      end
    end
  end
end)

-- ---- kill feed ------------------------------------------------------------
--
-- THREE SOURCES, DEDUPLICATED, because no single one sees every death.
--
--   KillEvent           -- fires for weapon kills, and carries the kill type
--   Humanoid.Died       -- catches falls, traps and anything the remote misses
--   PlayerData.Dead     -- catches deaths that happened while you were loading
--
-- All three can report the same death, so a two-second window suppresses the
-- repeats. Without it a single knife produces three identical toasts.
local recentKill = {}
local function feedSay(name, how, role)
  local tag = role and ("  [" .. MM2.tagFor(role) .. "]") or ""
  L.Toast.info("Kill feed", tostring(name) .. tag .. "  ·  " .. tostring(how or "eliminated"))
end
local function reportKill(name, how, role)
  if not MM2.cfg.killFeed then return end
  local seen = recentKill[name]
  if seen and os.clock() - seen < 2 then return end
  recentKill[name] = os.clock()
  feedSay(name, how, role)
end

task.spawn(function()
  if not GameplayR then return end
  local ke = GameplayR:FindFirstChild("KillEvent")
  if ke then
    L.hold(ke.OnClientEvent:Connect(function(victim, _, _, how)
      if victim then reportKill(tostring(victim), how) end
    end))
  end
end)

local function watchDeaths(plr)
  if not L.live() or game.PlaceId ~= MM2.PLACE or plr == LP then return end
  local function hook(ch)
    if not L.live() or plr.Parent ~= Players or plr.Character ~= ch then return end
    local hum = ch and ch:FindFirstChildOfClass("Humanoid")
    if not hum then return end
    L.hold(hum.Died:Connect(function()
      reportKill(plr.DisplayName or plr.Name, nil, MM2.roleOf(plr))
    end))
  end
  if plr.Character then hook(plr.Character) end
  L.hold(plr.CharacterAdded:Connect(function(ch)
    if L.live() then task.defer(hook, ch) end
  end))
end
if game.PlaceId == MM2.PLACE then
  for _, p in ipairs(Players:GetPlayers()) do watchDeaths(p) end
  L.hold(Players.PlayerAdded:Connect(watchDeaths))
end

-- ---------------------------------------------------------------- lookup

function MM2.lookup(name)
  local p = Players:FindFirstChild(name)
  if not p then
    for _, q in ipairs(Players:GetPlayers()) do
      if q.Name:lower():sub(1, #name) == name:lower()
         or (q.DisplayName or ""):lower():sub(1, #name) == name:lower() then p = q break end
    end
  end
  if not p then return nil, "no player matching " .. tostring(name) end

  local out = {}
  out[#out + 1] = (p.DisplayName ~= "" and p.DisplayName or p.Name) .. "  (@" .. p.Name .. ")"
  out[#out + 1] = "User id:  " .. p.UserId
  out[#out + 1] = "Role:     " .. MM2.roleOf(p) .. (MM2.alive(p) and "" or "  (dead)")

  local d = roundData(p)
  if d then
    out[#out + 1] = "Coins:    " .. tostring(d.Coins or 0)
  end
  out[#out + 1] = "Knife:    " .. tostring(p:GetAttribute("EquippedKnife") or "?")
  out[#out + 1] = "Gun:      " .. tostring(p:GetAttribute("EquippedGun") or "?")

  local hrp = hrpOf(p.Character)
  local mine = hrpOf(LP.Character)
  if hrp and mine then
    out[#out + 1] = "Distance: " .. math.floor((hrp.Position - mine.Position).Magnitude) .. " studs"
  end

  -- Inventory is a server round trip and the rarest thing about an MM2 account,
  -- so it is worth the wait -- but it is wrapped, because it is also the call
  -- most likely to be rate limited or renamed.
  local ItemDB
  pcall(function() ItemDB = require(RS.Database.Sync.Item) end)
  local okInv, inv = pcall(function()
    return RS.Remotes.Extras.GetFullInventory:InvokeServer(p)
  end)
  if okInv and type(inv) == "table" then
    local byRarity, total = {}, 0
    local owned = type(inv.Weapons) == "table" and inv.Weapons.Owned or nil
    if type(owned) == "table" then
      for id, cnt in pairs(owned) do
        local n = tonumber(cnt) or 1
        local it = ItemDB and ItemDB[id]
        local r = (it and it.Rarity) or "Other"
        byRarity[r] = (byRarity[r] or 0) + n
        total = total + n
      end
    end
    out[#out + 1] = ""
    out[#out + 1] = "Weapons:   " .. total
    for _, r in ipairs({ "Ancient", "Godly", "Legendary", "Unique", "Rare" }) do
      if (byRarity[r] or 0) > 0 then
        out[#out + 1] = string.format("%-10s %d", r .. ":", byRarity[r])
      end
    end
  else
    out[#out + 1] = ""
    out[#out + 1] = "Inventory unavailable (the game refused the request)"
  end

  return table.concat(out, "\n")
end

-- ---------------------------------------------------------------- ui

local function roleChip(parent)
  local f = mk("Frame", {
    Size = UDim2.new(1, 0, 0, 46),
    BackgroundColor3 = T.c.raised, BackgroundTransparency = 0.35,
    BorderSizePixel = 0, Name = "RoleChip", Parent = parent,
  })
  L.corner(T.r.md, f)
  local stroke = L.stroke(T.c.line, 1, 0.6, f)

  local dot = mk("Frame", {
    AnchorPoint = Vector2.new(0, 0.5),
    Position = UDim2.new(0, 14, 0.5, 0), Size = UDim2.fromOffset(9, 9),
    BackgroundColor3 = T.c.textOff, BorderSizePixel = 0, ZIndex = 3, Parent = f,
  })
  L.corner(999, dot)

  local lbl = A.text({
    Text = "Waiting for a round", font = T.font.strong, size = T.size.label,
    colour = T.c.text, Position = UDim2.fromOffset(32, 8),
    Size = UDim2.new(1, -44, 0, 16), ZIndex = 3, Parent = f,
  })
  local sub = A.text({
    Text = "", font = T.font.body, size = T.size.micro, colour = T.c.textMute,
    Position = UDim2.fromOffset(32, 25), Size = UDim2.new(1, -44, 0, 14),
    ZIndex = 3, Parent = f,
  })

  task.spawn(function()
    while L.live() and f.Parent do
      task.wait(0.4)
      local role = MM2.myRole()
      local col = MM2.colourFor(role)
      M.to(dot, "BackgroundColor3", col, "fast")
      M.to(stroke, "Color", col, "fast")
      M.to(stroke, "Transparency", 0.55, "fast")
      lbl.Text = "You are " .. role
      local murd, sher = MM2.findRole("Murderer"), MM2.findRole("Sheriff")
      sub.Text = string.format("Murderer: %s     Sheriff: %s",
        murd and (murd.DisplayName or murd.Name) or "unknown",
        sher and (sher.DisplayName or sher.Name) or "unknown")
    end
  end)
  return f
end

-- RETURN THE REFUSAL, DO NOT HANDLE IT.
--
-- C.toggle already does the whole job: it runs the callback through `L.try`,
-- and on an explicit `false` it flips the knob back, logs "refused", and warns
-- with the reason. bindPersist then declines to write a refused value to disk.
--
-- So a feature that cannot arm -- the __namecall hook on an executor without
-- `hookmetamethod` -- only has to say `false, why` and the rest is handled.
-- Reverting here as well produced two toasts and fought the control for
-- ownership of its own state.
-- EVERY SWITCH KEEPS ITS HANDLE, the way lm_14_universal keeps U.ui.
--
-- Without this the control was write-only: `MM2.cfg.autoKill = true` set the
-- engine's copy and left the switch reading off, and since the switch is pinned
-- -- and the pin strip drives the same api -- the next refresh asserted the
-- switch's answer and turned it back off. That is the "I enabled it and it
-- disabled itself" the operator kept hitting, and it fought a keeper loop for
-- two sessions.
--
-- `api:set(v)` is the honest way in: it moves the knob, runs the callback, and
-- writes through to cfg, so the panel, the pin and the engine cannot disagree.
MM2.ui = {}

local function flagToggle(page, key, text, desc, after)
  local api = C.toggle(page, {
    text = text, desc = desc, default = MM2.cfg[key],
    callback = function(v)
      if after then
        local ok, why = after(v)
        if ok == false then return false, why end
      end
      save(key, v)
      return true
    end,
  })
  MM2.ui[key] = api
  return api
end

-- Arm or disarm a feature the same way a click would. Anything driving the hub
-- from outside -- a probe, a keybind, another module -- goes through here, so
-- there is exactly one path that can change a switch and no way to leave the
-- knob and the engine holding different answers.
function MM2.setFlag(key, on)
  local api = MM2.ui[key]
  if not api then return false, "no control named " .. tostring(key) end
  api:set(on and true or false)
  return MM2.cfg[key] == (on and true or false), MM2.cfg[key]
end

-- ---------------------------------------------------------------- pages
--
-- ONE FUNCTION PER TAB, so the module can be mounted either way. LUMEN builds
-- these as the game's own tabs when it recognises the place; the legacy
-- single-page path below stacks them into one scroll for anything that still
-- calls `MM2.build`. Both run the same code, which is the point -- a second
-- copy of a control is a second source of truth for the same setting.
MM2.pages = {}

function MM2.pages.round(page)
  C.section(page, "round")
  roleChip(page)
  C.paragraph(page,
    "Roles come from the round table where the game publishes it, and from the "
    .. "weapon tags where it has not yet -- so the murderer is known during the "
    .. "countdown rather than after the first body drops.")

  -- ---- fling ------------------------------------------------------------
end

function MM2.pages.fling(page)
  C.section(page, "fling")
  C.paragraph(page,
    "Runs LUMEN's engine, which forces collision on before every contact. A "
    .. "fling is momentum handed over through a collision; the script this "
    .. "replaces switched collision off, which is why its own changelog says the "
    .. "fling does not work.")

  C.dropdown(page, {
    text = "Power", desc = "Instant trades reach for speed. Heavy is the opposite",
    items = MM2.FLING_STYLES, default = MM2.cfg.flingStyle,
    callback = function(v) MM2.applyFlingStyle(v) end,
  })
  C.actions(page, {
    { text = "Fling murderer", primary = true, callback = function()
        local ok, who = MM2.flingRole("Murderer")
        if ok then L.Toast.ok("Flinging", who) else L.Toast.warn("No target", who) end
      end },
    { text = "Fling sheriff", callback = function()
        local ok, who = MM2.flingRole("Sheriff")
        if ok then L.Toast.ok("Flinging", who) else L.Toast.warn("No target", who) end
      end },
  })
  C.actions(page, {
    { text = "Fling everyone", callback = function()
        local ok, why = MM2.flingAll()
        if ok then L.Toast.ok("Flinging everyone") else L.Toast.warn("Refused", why) end
      end },
    { text = "Stop", callback = function()
        MM2.stopFling() L.Toast.info("Fling stopped")
      end },
  })
  flagToggle(page, "autoFlingMurderer", "Auto-fling the murderer",
    "The moment one exists, every round", function() ensureAutoFling() end)
  flagToggle(page, "autoFlingSheriff", "Auto-fling the sheriff",
    "Only fires when no murderer is queued", function() ensureAutoFling() end)

  -- ---- combat -----------------------------------------------------------
end

function MM2.pages.combat(page)
  C.section(page, "combat")
  flagToggle(page, "autoKill", "Auto kill",
    "Sheriff/Hero only; verifies cadence, origin and target every shot",
    function(v)
      ensureAutoKill()
      if v then installAimHook() end -- also observes ordinary client gun cadence
    end)
  flagToggle(page, "realSwing", "Knife: swing for real",
    "Lets the game's own client swing instead of firing knife remotes by hand")
  flagToggle(page, "coverFire", "Fire at cover",
    "Keeps shooting when the murderer is hidden -- audible, but cannot kill")
  flagToggle(page, "shotFeedback", "Show your own shots",
    "Plays the gun and draws a tracer locally -- the server is told nothing extra")
  flagToggle(page, "realShot", "Pull the real trigger",
    "On a clear line only: aims and lets the game's own gun fire. This flicks the camera")
  flagToggle(page, "gunPredict", "Sheriff movement prediction",
    "Packet-aware bounded lead for moving murderers")
  -- All four ride the same __namecall hook, so all four refuse the same way on
  -- an executor that cannot install it.
  local needsHook = function(v) if v then return installAimHook() end end
  flagToggle(page, "instantKnife", "Instant knife throw",
    "Right click throws immediately, skipping the wind-up", needsHook)
  flagToggle(page, "silentAim", "Knife silent aim",
    "Rewrites the throw to the best enemy in your FOV", needsHook)
  flagToggle(page, "knifeWalls", "Knife synthetic origin (experimental)",
    "Rewrites the throw origin; no through-wall guarantee is claimed", needsHook)
  flagToggle(page, "gunWalls", "Gun through walls",
    "Experimental synthetic origin; less reliable than the verified default shot", needsHook)
  C.slider(page, {
    text = "Aim FOV", desc = "Radius that silent aim and instant throw search",
    min = 20, max = 600, step = 5, default = MM2.cfg.aimFov, suffix = "px",
    callback = function(v) save("aimFov", v) end,
  })
  C.actions(page, {
    { text = "Kill murderer", primary = true, callback = function()
        local m = MM2.findCombatRole("Murderer")
        if not m then L.Toast.warn("No murderer", "Nobody is holding the knife") return end
        local ok, why = MM2.strike(m)
        if ok and isGunRole(combatRole(LP)) then
          L.Toast.info("Shot dispatched", "The round death state is observation, not causal proof")
        elseif ok then L.Toast.ok("Struck", m.DisplayName or m.Name)
        else L.Toast.warn("Refused", tostring(why)) end
      end },
    { text = "Throw knife", callback = function()
        local ok, why = MM2.throwKnifeNow()
        if not ok then L.Toast.warn("Could not throw", tostring(why)) end
      end },
    { text = "Auto status", callback = function()
        local s, n = MM2.autoKillInfo, MM2.shotStats
        L.Toast.info("Auto kill: " .. tostring(s.phase),
          string.format("%s | sent %d, deaths seen %d, retry sends %d, errors %d",
            tostring(s.reason), n.dispatched, n.deathObserved, n.retryDispatches, n.errors))
      end },
  })
  -- ---- esp --------------------------------------------------------------
end

function MM2.pages.esp(page)
  C.section(page, "esp")
  flagToggle(page, "roleTags", "Role colours on ESP",
    "Colours LUMEN's player ESP red/blue/green by round role")
  flagToggle(page, "murdererEsp", "Murderer ESP",
    "Dedicated red marker and role label, even when universal ESP is off")
  flagToggle(page, "sheriffEsp", "Sheriff ESP",
    "Dedicated blue/gold marker for the sheriff or hero")
  flagToggle(page, "coinEsp", "Coin ESP", "Highlights every uncollected coin")
  flagToggle(page, "gunEsp", "Dropped gun ESP", "Marks the sheriff's gun when it drops")
  flagToggle(page, "gunEspDist", "Show gun distance", "Adds metres to the gun marker")
  C.dropdown(page, {
    text = "Dropped gun colour", desc = "Colour used by the gun highlight and label",
    items = MM2.GUN_ESP_COLOURS, default = MM2.cfg.gunEspColour,
    callback = function(v) save("gunEspColour", v) end,
  })
  flagToggle(page, "trapEsp", "Trap ESP", "Marks trap volumes before you walk into one")

  -- ---- pickups ----------------------------------------------------------
end

function MM2.pages.pickups(page)
  C.section(page, "pickups")
  flagToggle(page, "autoCoins", "Auto collect coins",
    "Six a pass, then straight back -- pauses when the bag is full",
    function() ensurePickups() end)
  flagToggle(page, "autoGun", "Auto grab the gun",
    "Only when one is on the ground and you have none", function() ensurePickups() end)
  C.actions(page, {
    { text = "Grab gun now", callback = function()
        local ok, why = MM2.grabGun()
        if ok then L.Toast.ok("Grabbed the gun") else L.Toast.warn("Nothing to grab", why) end
      end },
    { text = "Nearest coin", callback = function()
        local ok, count = MM2.collectNearestCoin()
        if ok then L.Toast.ok("Coin collected", tostring(count) .. " contact sent")
        else L.Toast.warn("Could not collect", tostring(count)) end
      end },
  })

  -- ---- safety -----------------------------------------------------------
end

function MM2.pages.safety(page)
  C.section(page, "safety")
  flagToggle(page, "antiTrap", "Anti trap",
    "Re-asserts your speed for as long as the slow would have lasted")
  flagToggle(page, "murdererNotify", "Announce the murderer",
    "Once per round, as soon as the knife appears")
  flagToggle(page, "killFeed", "Kill feed",
    "Three sources, deduplicated -- one death, one toast")

  -- ---- lookup -----------------------------------------------------------
end

function MM2.pages.lookup(page)
  C.section(page, "lookup")
  local out = C.output(page, {
    mono = true, maxHeight = 240,
    default = "Type a name and press Look up.",
  })
  local who = ""
  C.input(page, {
    text = "Player", desc = "Full or partial name",
    placeholder = "username",
    callback = function(v) who = v end,
  })
  C.actions(page, {
    { text = "Look up", primary = true, callback = function()
        if who == "" then out:set("Type a name first.") return end
        out:set("Looking up " .. who .. "...")
        task.spawn(function()
          local text, why = MM2.lookup(who)
          out:set(text or ("Nothing found -- " .. tostring(why)))
        end)
      end },
    { text = "Copy", callback = function()
        local ok = pcall(function() setclipboard(out:get()) end)
        L.Toast[ok and "ok" or "warn"](ok and "Copied" or "Clipboard unavailable")
      end },
  })

  -- ---- where the rest lives ---------------------------------------------
end

function MM2.pages.elsewhere(page)
  C.section(page, "elsewhere")
  C.paragraph(page,
    "Not duplicated here, because the hub already owns them and two copies "
    .. "would drift apart:\n\n"
    .. "Universal  --  fly, noclip, infinite jump, walk speed, jump power, "
    .. "anti-AFK, unlock camera, reset character, teleport to player\n"
    .. "Combat     --  aimbot, FOV circle, hitbox, the fling engine's own tuning\n"
    .. "Visuals    --  box / skeleton / chams / nametag ESP, fullbright, "
    .. "FPS boost, field of view\n"
    .. "Movement   --  anti-fling, server hop, copy job id, invisibility\n"
    .. "Interface  --  keybinds, theme, config profiles, unload")
end

-- Starts whatever is switched on once the pages exist -- which, since the
-- config stopped re-arming features at execute, is normally nothing at all.
--
-- It is kept rather than deleted because the rule is not "nothing restores": a
-- handful of ids in Cfg.ARM_SAFE still come back, and a toggle flipped during
-- the build still has to reach its loop. What changed is that arriving here
-- with auto kill already true is now something the operator did, not something
-- a three-day-old config file decided on their behalf.
function MM2.arm()
  if MM2.cfg.autoKill then ensureAutoKill() installAimHook() end
  if MM2.cfg.autoCoins or MM2.cfg.autoGun then ensurePickups() end
  if MM2.cfg.autoFlingMurderer or MM2.cfg.autoFlingSheriff then ensureAutoFling() end
  if MM2.cfg.instantKnife or MM2.cfg.silentAim
     or MM2.cfg.knifeWalls or MM2.cfg.gunWalls then installAimHook() end
end

-- ---------------------------------------------------------------- esp bridge
--
-- LUMEN's ESP already draws every player; what it cannot know is that in this
-- game the colour carries the single most important fact on screen. Rather than
-- a second ESP implementation, the existing one takes a colour function.
if L.Esp and L.Esp.setColourHook then
  L.Esp.setColourHook(function(plr)
    if not MM2.cfg.roleTags then return nil end
    if game.PlaceId ~= MM2.PLACE then return nil end
    local role = MM2.roleOf(plr)
    return MM2.colourFor(role), MM2.tagFor(role)
  end)
end

-- Legacy single-page mount, kept for any caller that has not moved to tabs.
function MM2.build(page)
  for _, k in ipairs({ "round", "fling", "combat", "esp",
                       "pickups", "safety", "lookup", "elsewhere" }) do
    MM2.pages[k](page)
  end
  MM2.arm()
end


-- ---------------------------------------------------------------- register

-- Registered with TABS, so in Murder Mystery 2 the hub opens as the Murder
-- Mystery 2 build of LUMEN: its own nav section, its own pages, first in the
-- list -- and every one of them drawn with the hub's own atoms, controls and
-- springs. Anywhere else this module is simply never mounted and the operator
-- gets the universal build.
--
-- `arm` runs once after the pages exist, because the loops it starts read
-- config the controls restore during their own construction.
if L.Hub and L.Hub.register then
  L.Hub.register(MM2.PLACE, {
    name   = "Murder Mystery 2",
    short  = "MM2",
    accent = MM2.ROLE_COLOUR.Murderer,
    tabs = {
      { name = "Round",   chrome = "eye",    desc = "Who is who, this round",
        build = function(ctx) MM2.pages.round(ctx.page) MM2.pages.safety(ctx.page) end },
      { name = "Combat",  chrome = "blade",  desc = "Knife, gun, and the aim hook",
        build = function(ctx) MM2.pages.combat(ctx.page) end },
      { name = "Fling",   chrome = "torus",  desc = "Throw them, by role",
        build = function(ctx) MM2.pages.fling(ctx.page) end },
      { name = "ESP",     chrome = "prism3", desc = "Roles, coins, guns and traps",
        build = function(ctx) MM2.pages.esp(ctx.page) end },
      { name = "Pickups", chrome = "chart",  desc = "Coins and the dropped gun",
        build = function(ctx) MM2.pages.pickups(ctx.page) end },
      { name = "Lookup",  chrome = "vault",  desc = "Any player's profile and inventory",
        build = function(ctx)
          MM2.pages.lookup(ctx.page)
          MM2.pages.elsewhere(ctx.page)
          MM2.arm()
        end },
    },
    -- kept so a caller that still wants one page gets one page
    build = function(ctx) L.try("mm2.build", MM2.build, ctx.page) end,
  })
end

end
do -- ==== lm_28_fetch.lua ====
-- LUMEN :: FETCH
-- Brings the frame sequences down on first run, once, in the background.
-- 66 MB of PNG cannot be embedded the way lm_26's sprites are, so it ships as one
-- binary container per folder. Binary survives HttpGet byte-identical through a
-- disk round trip, so nothing here is base64'd. Nothing waits on the download:
-- the hub opens on drawn fallbacks and picks the sequences up on the next run.

local L = getgenv().LUMEN
local Fetch = {}
L.Fetch = Fetch

-- ---------------------------------------------------------------- config
-- Any https host serving the files verbatim works; a public GitHub repo with
-- lumen_packs/ on the raw host is the free option. Empty means this module does
-- nothing at all -- no requests, no errors -- and the hub runs on fallbacks.
Fetch.BASE = "https://raw.githubusercontent.com/Mrzaytoon/lumen-assets/main/lumen_packs/"

-- Where this script itself lives, used to restart once the visuals have landed.
-- A sequence resolves through getcustomasset when its frames are built, so packs
-- arriving after the window was constructed need a restart, not a refresh. Falls
-- back to Lumen.lua on disk; with neither, the user just gets a toast.
Fetch.SELF = "https://raw.githubusercontent.com/Mrzaytoon/lumen-assets/main/Lumen.lua"

Fetch.DIR   = "lumen_fx"
Fetch.MARKS = "lumen_fx/_packs"
Fetch.VER   = 1

-- TIERS, because a 65 MiB blocking download was the whole first-run experience.
--
-- `core` is what the interface needs to stop looking broken: the nav rail icons.
-- Everything else is decoration that already has a drawn fallback -- saturn and
-- titles alone are 56 MB of the 68, and both are scenery.
--
-- The `ui` pack is gone from this list entirely: all six of its sprites are now
-- base64 in lm_26_assets.lua. It was 67 KB sitting at priority 9, behind 11.5 MB
-- of footage, which put every shadow, glow and chrome edge in the product behind
-- a download it did not need.
Fetch.PACKS = {
  { name = "icons",      files = 11,  bytes = 472121,   prio = 1,  tier = "core" },
  { name = "icons_anim", files = 480, bytes = 4658650,  prio = 2,  tier = "extra" },
  { name = "think",      files = 44,  bytes = 934891,   prio = 3,  tier = "extra" },
  { name = "word",       files = 60,  bytes = 783128,   prio = 4,  tier = "extra" },
  { name = "bg",         files = 48,  bytes = 463727,   prio = 5,  tier = "extra" },
  { name = "prism",      files = 36,  bytes = 724114,   prio = 6,  tier = "extra" },
  { name = "games",      files = 10,  bytes = 1815595,  prio = 7,  tier = "extra" },
  { name = "saturn_s",   files = 151, bytes = 1678759,  prio = 8,  tier = "extra" },
  { name = "titles",     files = 216, bytes = 16188940, prio = 9,  tier = "extra" },
  { name = "saturn",     files = 301, bytes = 40612366, prio = 10, tier = "extra" },
}

-- A pack that cannot be downloaded must not re-block every future boot. Failures
-- are remembered on disk with an attempt count; three strikes and the pack is
-- skipped until the user asks for it again. Without this, one 404 or geo-block
-- turns every launch, forever, into a failed download attempt.
Fetch.STRIKES = 3
Fetch.TIMEOUT = 25          -- seconds per pack; there was no timeout at all

Fetch.state = { running = false, done = 0, total = #Fetch.PACKS, pack = nil, failed = {} }

-- ---------------------------------------------------------------- helpers

local function fs(name)
  local f = rawget(getgenv(), name)
  return type(f) == "function" and f or nil
end

local function have()
  return fs("writefile") and fs("isfile") and fs("isfolder")
         and fs("makefolder") and fs("listfiles")
end

local function ensureDir(path)
  local isd, mk = fs("isfolder"), fs("makefolder")
  local ok = false
  pcall(function() ok = isd(path) end)
  if not ok then pcall(mk, path) end
end

local function markPath(name)
  return Fetch.MARKS .. "/" .. name .. ".v" .. Fetch.VER
end

-- Two ways to be satisfied: our own marker, or the folder already being there
-- for some other reason (the machine the packs were built on).
local function satisfied(pack)
  local isd, ls = fs("isfolder"), fs("listfiles")
  local dir = Fetch.DIR .. "/" .. pack.name
  local there = false
  pcall(function() there = isd(dir) end)
  if not there then return false end
  local n = 0
  pcall(function() n = #ls(dir) end)

  -- The file count decides, not the marker: a pack that grows in a later release
  -- would otherwise be skipped forever on machines that installed the old one.
  if n >= pack.files then return true, "already on disk" end
  return false
end

local function download(url)
  local req = fs("request") or fs("http_request")
  if req then
    local ok, res = pcall(req, { Url = url, Method = "GET" })
    if not ok then return nil, tostring(res) end
    local code = res.StatusCode or res.status or 0
    if code ~= 200 then return nil, "http " .. tostring(code) end
    return res.Body
  end
  local ok, body = pcall(function() return game:HttpGet(url) end)
  if not ok then return nil, tostring(body) end
  return body
end

-- ---------------------------------------------------------------- unpack
-- "LMPK" | ver(1) | manifestLen(4 LE) | manifest JSON | payload
local function unpack(pack, blob)
  if #blob < 9 then return false, "truncated" end
  if blob:sub(1, 4) ~= "LMPK" then return false, "not a pack" end
  if blob:byte(5) ~= Fetch.VER then return false, "pack version" end
  local b1, b2, b3, b4 = blob:byte(6, 9)
  local mlen = b1 + b2 * 256 + b3 * 65536 + b4 * 16777216
  if mlen <= 0 or 9 + mlen > #blob then return false, "bad manifest length" end

  local ok, man = pcall(function()
    return L.Http:JSONDecode(blob:sub(10, 9 + mlen))
  end)
  if not ok or type(man) ~= "table" or type(man.e) ~= "table" then
    return false, "manifest unreadable"
  end

  local base = 9 + mlen
  local dir = Fetch.DIR .. "/" .. man.f
  ensureDir(Fetch.DIR)
  ensureDir(dir)

  local w = fs("writefile")
  local wrote = 0
  for i, e in ipairs(man.e) do
    local name, off, size = e[1], e[2], e[3]
    local from, to = base + off + 1, base + off + size
    if to > #blob then return false, "payload short at " .. tostring(name) end
    local data = blob:sub(from, to)
    if #data ~= size then return false, "size mismatch at " .. tostring(name) end
    if pcall(w, dir .. "/" .. name, data) then wrote = wrote + 1 end
    -- 432 writes in one go is a visible hitch even in the background
    if i % 24 == 0 then L.RunService.Heartbeat:Wait() end
  end
  return true, wrote
end

-- ---------------------------------------------------------------- run

function Fetch.installOne(pack)
  local url = Fetch.BASE .. pack.name .. ".lmpk"
  local blob, err = download(url)
  if not blob then return false, err end
  -- Catches the realistic failure: a truncated body or an error page.
  if #blob ~= pack.bytes then
    return false, string.format("expected %d bytes, got %d", pack.bytes, #blob)
  end
  local ok, res = unpack(pack, blob)
  if not ok then return false, res end
  pcall(fs("writefile"), markPath(pack.name), tostring(res))
  return true, res
end

-- Same unpacking, from a pack already on disk: installs from a copied folder
-- with no host, and is the path the offset handling is tested against.
function Fetch.installFromFile(name, path)
  local pack
  for _, p in ipairs(Fetch.PACKS) do if p.name == name then pack = p end end
  if not pack then return false, "unknown pack " .. tostring(name) end
  local ok, blob = pcall(fs("readfile"), path or ("lumen_packs/" .. name .. ".lmpk"))
  if not ok then return false, "cannot read pack" end
  if #blob ~= pack.bytes then
    return false, string.format("expected %d bytes, got %d", pack.bytes, #blob)
  end
  return unpack(pack, blob)
end

function Fetch.run()
  if Fetch.state.running then return false, "already running" end
  if Fetch.BASE == "" then return false, "no host configured" end
  if not have() then return false, "executor has no file api" end

  Fetch.state.running = true
  ensureDir(Fetch.DIR)
  ensureDir(Fetch.MARKS)

  task.spawn(function()
    local todo = {}
    for _, p in ipairs(Fetch.PACKS) do
      if not satisfied(p) then todo[#todo + 1] = p end
    end
    table.sort(todo, function(a, b) return a.prio < b.prio end)

    if #todo == 0 then
      Fetch.state.running = false
      Fetch.state.done = Fetch.state.total
      L.note("fetch", "all packs already present")
      return
    end

    local mb = 0
    for _, p in ipairs(todo) do mb = mb + p.bytes end
    L.Toast.info("Downloading visuals",
      string.format("%d packs, %.1f MB. The hub is usable now.", #todo, mb / 1048576))

    local ok, bad = 0, 0
    for _, p in ipairs(todo) do
      Fetch.state.pack = p.name
      local good, why = Fetch.installOne(p)
      if good then
        ok = ok + 1
      else
        bad = bad + 1
        Fetch.state.failed[#Fetch.state.failed + 1] = p.name .. ": " .. tostring(why)
        L.note("fetch", p.name .. " failed -- " .. tostring(why))
      end
      Fetch.state.done = Fetch.state.done + 1
      L.RunService.Heartbeat:Wait()
    end

    Fetch.state.running = false
    Fetch.state.pack = nil
    if bad == 0 then
      L.Toast.ok("Visuals installed", "Restart the script to see them.")
    else
      L.Toast.warn("Visuals partly installed",
        ok .. " of " .. (ok + bad) .. " packs. The rest stay drawn.")
    end
  end)
  return true
end

-- What is still missing, and how much it weighs. Used by the loading screen to
-- decide whether it is worth making anybody wait at all.
-- Can this machine download at all? `request`/`http_request` are executor globals
-- and HttpGet is refused in some contexts -- without one of them the fetch must
-- not start, because a loading screen that counts down megabytes it can never
-- transfer is worse than one that says so.
function Fetch.canDownload()
  if fs("request") or fs("http_request") then return true end
  local ok = pcall(function() return game:HttpGet(Fetch.BASE) end)
  return ok
end

local strikePath = function(name) return Fetch.MARKS .. "/" .. name .. ".fail" end

local function strikes(name)
  local rf, isf = fs("readfile"), fs("isfile")
  if not (rf and isf) then return 0 end
  local there = false
  pcall(function() there = isf(strikePath(name)) end)
  if not there then return 0 end
  local n = 0
  pcall(function() n = tonumber(rf(strikePath(name))) or 0 end)
  return n
end

local function strike(name)
  local wf = fs("writefile")
  if not wf then return end
  pcall(wf, strikePath(name), tostring(strikes(name) + 1))
end

local function clearStrikes(name)
  local df, isf = fs("delfile"), fs("isfile")
  if not (df and isf) then return end
  local there = false
  pcall(function() there = isf(strikePath(name)) end)
  if there then pcall(df, strikePath(name)) end
end

-- Forget every strike, so "try again" is a real option rather than a reinstall.
function Fetch.retryFailed()
  local n = 0
  for _, p in ipairs(Fetch.PACKS) do
    if strikes(p.name) > 0 then clearStrikes(p.name) n = n + 1 end
  end
  return n
end

---Packs still needed. `tier` filters to "core" or "extra"; omit it for all.
function Fetch.pending(tier)
  if Fetch.BASE == "" or not have() then return {}, 0 end
  local todo, bytes = {}, 0
  for _, p in ipairs(Fetch.PACKS) do
    if (not tier or p.tier == tier) and not satisfied(p)
       and strikes(p.name) < Fetch.STRIKES then
      todo[#todo + 1] = p
      bytes = bytes + p.bytes
    end
  end
  table.sort(todo, function(a, b) return a.prio < b.prio end)
  return todo, bytes
end

---Packs that have struck out, so the UI can say so instead of silently skipping.
function Fetch.givenUp()
  local out = {}
  for _, p in ipairs(Fetch.PACKS) do
    if not satisfied(p) and strikes(p.name) >= Fetch.STRIKES then
      out[#out + 1] = p.name
    end
  end
  return out
end

-- BLOCKING, on purpose, unlike Fetch.run. This is the loading-screen path: the
-- caller is already showing a wait, so downloading in the background behind it
-- would mean finishing the boot and THEN telling somebody to restart. `onStep`
-- is called with (index, total, pack, bytesLeft) so the screen can say
-- something true rather than spinning.
function Fetch.runBlocking(onStep, tier)
  if Fetch.state.running then return false, "already running" end
  if not Fetch.canDownload() then return false, "no http on this executor" end
  local todo, bytes = Fetch.pending(tier)
  if #todo == 0 then return true, 0 end

  Fetch.state.running = true
  ensureDir(Fetch.DIR)
  ensureDir(Fetch.MARKS)

  local okCount, left = 0, bytes
  for i, p in ipairs(todo) do
    Fetch.state.pack = p.name
    if onStep then L.try("fetch.step", onStep, i, #todo, p, left) end
    local good, why = Fetch.installOne(p)
    if good then
      okCount = okCount + 1
      clearStrikes(p.name)
    else
      strike(p.name)
      local n = strikes(p.name)
      Fetch.state.failed[#Fetch.state.failed + 1] = p.name .. ": " .. tostring(why)
      L.note("fetch", string.format("%s failed (%d/%d) -- %s",
        p.name, n, Fetch.STRIKES, tostring(why)))
    end
    left = left - p.bytes
    Fetch.state.done = Fetch.state.done + 1
    L.RunService.Heartbeat:Wait()
  end

  Fetch.state.running = false
  Fetch.state.pack = nil
  return true, okCount
end

-- Decoration downloads AFTER the hub is usable, not in front of it.
--
-- saturn and titles are 56 MB of the 68 and both are scenery with a drawn
-- fallback, so holding the first launch hostage to them was the wrong trade.
-- This runs on its own thread, reports once when it finishes, and never touches
-- the loading screen. Sequences bind their frame lists at construction, so what
-- lands here shows up on the next execute -- which is worth saying plainly
-- rather than restarting the hub under someone who is already using it.
function Fetch.runLater(tier)
  if Fetch.state.running or Fetch.state.deferred then return false end
  if not Fetch.canDownload() then return false end
  local todo = Fetch.pending(tier or "extra")
  if #todo == 0 then return false end

  Fetch.state.deferred = true
  task.spawn(function()
    task.wait(3)                     -- let the interface settle first
    if not L.live() then return end
    local ok, n = Fetch.runBlocking(nil, tier or "extra")
    Fetch.state.deferred = false
    if not L.live() then return end
    if ok and n and n > 0 and L.Toast then
      L.Toast.ok("Visuals ready", n .. " pack(s) installed. They appear next launch.")
    end
  end)
  return true
end

-- Restart the hub so the freshly downloaded sequences are actually built with.
-- The local file first: on the machine this was made on it is always current,
-- and it costs no network. The hosted copy second, for everyone else.
function Fetch.reexec()
  local isf, rf = fs("isfile"), fs("readfile")
  local src
  if isf and rf then
    local ok, present = pcall(isf, "Lumen.lua")
    if ok and present then
      local rok, body = pcall(rf, "Lumen.lua")
      if rok and type(body) == "string" and #body > 1000 then src = body end
    end
  end
  if not src and Fetch.SELF ~= "" then
    local ok, body = pcall(function() return game:HttpGet(Fetch.SELF) end)
    if ok and type(body) == "string" and #body > 1000 then src = body end
  end
  if not src then return false, "no copy of the script to restart from" end

  local fn, err = loadstring(src)
  if not fn then return false, "restart failed: " .. tostring(err) end
  -- deferred so this call stack (and the loading screen that owns it) unwinds
  -- before a second hub starts building over the top of it
  task.defer(function()
    L.try("fetch.reexec", function()
      if L.teardown then L.teardown() end
      task.wait(0.15)
      fn()
    end)
  end)
  return true
end

function Fetch.status()
  local s = Fetch.state
  return { running = s.running, done = s.done, total = s.total,
           pack = s.pack, failed = #s.failed, host = Fetch.BASE ~= "" }
end

-- NO AUTOMATIC BACKGROUND RUN. The loading screen drives this now, via
-- runBlocking, so the wait is visible and the restart happens the moment the
-- packs land. Starting a second, silent download here would race it and could
-- have two writers on the same file.
--
-- Fetch.run remains for anything that wants the old fire-and-forget behaviour
-- (a manual "download visuals" button, say); it is simply no longer wired to
-- fire on its own.

end
